\begin{theorem}\label{th:f-vectors}
Take any $n\ge3$, and any $C>0$.
Then there is a triangulation of $\SS^n$ for which $\frac{f_j}{f_i}>C$
for any $0\le i<j\le n$ such that $i<\lfloor\frac {n-1}2\rfloor$.
\end{theorem}

ref_dict.s:lower:
\begin{proof}[Proof of the upper bound in Theorem \ref{t:main2}] Let $n$ be large and  $a \in (0, 1)$. Consider $\ell= \lceil ne^{- \frac{\pi}{\sqrt{ 2 \beta_n}} (1-a)}\rceil$,  $r=e^{\frac{\pi}{\sqrt{2\beta_n}}(1-\frac{a}2)}$ and  let $m'_\Delta(L)$ be the number of $i\in \lb 0,L\rb$ such that $\inf_{j \in \lb i,L\rb} S_j\le S_i- \Delta$ with $\Delta:=\ln r$.  Let $b_n=\ln n + \ln\ln n$.  By the same argument leading to \eqref{eq:L>ell-bn}, but using Corollary \ref{cor:jump} (ii) in addition, we obtain that  for any $M>2$, $$\p\Big(\L(n, \beta_n) \ge \ell\Big) \le  \sum_{L=\ell}^{2\ell} \widetilde a_L + \frac{2}{M}+ o(1),$$

\noindent where for $L\in \lb \ell, 2\ell \rb$, $$ \widetilde a_L:= \p\Big(\exists \gamma\in {\mathcal P}_L: S_L(\gamma) \le \beta_n L, m'_\Delta(L) \le M \frac{n}{r},\, \min_{0\le i \le j \le L} (S_j(\gamma)- S_i(\gamma)) >-  b_n \Big).$$

By \eqref{comp:moment1} and \eqref{eq:many-to-one}, \begin{align*}    \widetilde a_L & \le n \, e^{\beta_n L}  \p\Big( Y_L\le \beta_n L , \, m_\Delta(L) \le M \frac{n}{r},\,  \min_{0\le i \le j \le L} (Y_j - Y_i ) >- b_n\Big)
\\
& \le n \, e^{\beta_n L}  \p\Big(   \max_{i \in \lb 0, L\rb} Y_i \le 2 \beta_n L, \,  m_\Delta(L) \le M \frac{n}{r}\Big)
 ,
\end{align*} where $m_\Delta(L)$ is as defined in Lemma \ref{main2:upper} and in the last inequality, we have used the fact that $\max_{i \in \lb 0, L\rb} Y_i\le Y_L+b_n \le \beta_n L+ b_n \le 2 \beta_n L$. Choose $d\in (0, \frac{\pi^2}2)$ 
  such that $\eta:= \frac{2d}{\pi^2 (1-\frac{a}2)^2} - 1>0$. Fix an arbitrary $c\in (0, 1)$. If $\varepsilon>0$ is chosen small enough in Theorem \ref{t:main2}, we have $L\ge \Delta^{2+c}$, $M \frac{n}{r} \le L \Delta^{-2-c}$ and $2 \beta_n L \le L \Delta^{-1-c}$.  Note that $\Delta$ is arbitrarily large when $\varepsilon$ goes to $0$.   Lemma \ref{main2:upper} yields that $$ \widetilde a_L \le n e^{\beta_n L} e^{- d \frac{L}{\Delta^2}} = n e^{- \eta \,\beta_n L}. $$

 Notice that for all large $n$, $\beta_n L \ge \beta_n \ell \ge n^{a'}$ for some positive constant $a'$. Hence   $\sum_{L=\ell}^{2\ell} \widetilde a_L \le n^2  e^{- \eta\, n^{a'}}\to 0$ and we conclude the proof by letting $n \to\infty$ then $M\to\infty$.  \end{proof}

\section{Proofs of the lower bounds}
\label{s:lower}

We consider a branching random walk $\V$ on $\r$. It starts with a certain number of particles at $0$. At each discrete time $k\ge 0$, each particle of the current population splits into an infinite number of children, whose displacements from their parent  are given by a copy of 
\begin{equation} \label{eq:BRW-V}   
\sum_{i=1}^\infty {\delta}_{\{e T_i -1\}} 
\end{equation}

\noindent where $0<T_1<T_2<\ldots$ are the atoms of a Poisson point process of intensity $1$ on $\r_+$. The position of a particle $u$ is denoted by $\V(u)$.
The offspring distribution corresponds to the limiting law  of $\sum_{u=2}^{n} \delta_{X(1,u)}$, so that, when $n$ is large, exploring the graph around a given vertex locally approximates the branching random walk $\V$. To make it precise, we will  couple labels $X(u,v)$ and copies of the Poisson point process $(T_i)_{i\ge 1}$ as follows. 

\medskip

Consider $(X_i)_{1\le i \le n-1}$ a family of $(n-1)$ i.i.d. copies of $X= n e \mbox{Exp}(1)-1$.  Its increasing order statistics $ X_{(0)}:=-1 < X_{(1)}< ...< X_{(n-1)}$ verify that the variables $X_{(i)}-X_{(i-1)}$ are independent, distributed as $\frac{n e }{n-i}\text{Exp}(1)$.   One can couple it with a Poisson point process $T_1<T_2<\ldots$ of intensity $1$, by 
\[     X_{(i)}-X_{(i-1)} = \frac{n e}{n-i} (T_{i}-T_{i-1}), \qquad i\in \lb 1, n-1\rb, 
\]where we set $T_0=0$.  In particular,  for all $i\in \lb 1, n-1\rb$, \begin{equation}\label{coupling}
   e T_i-1 \le  X_{(i)} \le   \frac{n}{n-i} (e T_{i}-1) + \frac{i}{n-i}.
\end{equation}

For each $u\in K_n$, this gives a coupling between $(X(u,v))_{v\neq u}$ and a copy of $(T_i)_{i\ge 1}$.  We further need the following simple observation.  Let $m \in \lb 1, n-1 \rb$. If we choose   $m$  points uniformly from $(X_{(i)})_{1\le i \le n-1}$ and arrange them in increasing order, then they have the same distribution as  the increasing order statistics of $(X_i)_{1\le i \le m}$. In other words, there exists a coupling in the sense of \eqref{coupling}, between $X(u, v)$ when $v$ varies over a subset of $K_n$ with $m$ vertices, and the family of $m$  points  chosen uniformly from $(T_i)_{1\le i \le n-1}$.  

Let $N$ be an integer between $1$ and $n-1$.  We denote by $\V^N$ the branching random walk $\V$  in which, at each step, we only keep the $N$ leftmost particles of the next generation. For a particle $u$ in $\V^N$, let   $|u|$ denote its generation in the genealogical tree of $\V^N$, and let $\V^N(u)$ denote its position in $\r$.

\begin{proposition}\label{p:first_moment} Fix $a\in [0, 1]$ and $t>0$.    If $\V^N$ starts with $\lfloor N^a\rfloor$ particles located at $0$, then for any sequence $\ell_N$ satisfying $\frac{\ell_N}{\ln^3 N} \to t$,  \begin{equation}  \frac{1}{\ln N}  \min_{|u|=\ell_N} \V^N(u)   \,\cvL2\, -a+\frac{\pi^2}{2}t  , \qquad N \to\infty. \label{Nbrw-cvL2}\end{equation}
\end{proposition}

We will apply the above proposition to two cases: $a=1$ and $a=0$.
The proof of Proposition \ref{p:first_moment} is postponed to Section \ref{sub:brw}. 

In what follows, we construct a coupling between $\V^N$ and an exploration process on $K_n$. 
We will color particles of $\V^{N}$ in blue, red or purple. Blue particles will correspond to  vertices of $K_{n}$ and will be the particles of interest. 

\subsection{Construction of an exploration process $(Z_j, {\mathcal Q}_j)_{j\ge 0}$ in $K_n$ and its coupling with $\V^N$.}
 \label{s:exploration}

For each $j\ge 0$, we define a  set $Z_j$ of so-called {\it active} vertices of $K_n$ and a set of paths ${\mathcal Q}_j\subset {\mathcal P}_j$  such that each vertex  in $Z_j$ is associated with a unique  path in ${\mathcal Q}_j$ ending at this point. The set $Z_j$ will correspond to the blue particles of $\V^{N}$ at time $j$. We will therefore write $u$ either for the blue particle or its corresponding  vertex in $K_n$.  For each active vertex $u$ at step $j$, we will write $V(u)$  for $S_j(\gamma)$ where $\gamma$ is the path in ${\mathcal Q}_j$ ending at $u$.  

Let $G_0$ be a complete subgraph of $K_n$. Let $Z_0\subset G_0$ be a set of $N_0\le N$ active vertices at time $0$. We start  the branching random walk $\V$ with  $N_0$ blue particles,  each particle corresponding to an active vertex in $Z_0$.  We let $\mathcal Q_0$ be the collection $\{\{u\},\, u\in Z_0\}$.  We denote by $\#G_0$ the number of vertices in $G_0$. Let $m:=\#G_0- \#Z_0$.   Each $u\in Z_0$ corresponds to a blue particle in $\V$, still denoted by $u$. We have $\V(u)=V(u)=0$. We  choose $m$ children $v$ of $u$ in $\V$ uniformly among the $n-1$ leftmost ones and color them {\it blue.}  By the coupling described above, for each blue particle $u$, $\V(v)-\V(u)$ is coupled with $X(u, v)$ for $v \in G_0 \backslash Z_0$ (where, as for $u$, the variable $v$ denotes both a particle in $\V$ and a vertex in $G_0$).  Let $i_v$ be the index of the point $T_i$ corresponding to $v$ in the coupling \eqref{coupling}. We have  $$X(u,v) = X_{(i_v)} \le \frac{n}{n-i_v} e T_{i_v} -1 =   \frac{n}{n-i_v} (\V(v)-\V(u))+\frac{i_v}{n-i_v}.$$ We also have $X(u,v) \ge \V(v)-\V(u)$. 
We will see that $i_v \le N$ for all $v$ of interest.  We color the remaining children of $u$ in $\V$ {\it red.}  We then retain the $N$ leftmost particles of $\V$ in generation $1$ which is in fact the population of $\V^N$ at generation $1$.  This population may contain red and blue particles.  If a blue particle $v$  is selected in $\V^N$, we select the corresponding edge $(u, v)$ in $G_0$. Note that in this case we indeed have $i_v \le N$. We also remark that several selected edges may point to the same vertex $v$. If this happens, we keep blue the corresponding particle in $\V^N$ which has the minimal position in $\V$,  and color the other particles corresponding to $v$ {\it purple.} We then define $Z_1$ to be the set of blue particles in ${\mathcal V}^N$ at generation $1$, after removing all purple particles. We identify $Z_1$ with a subset of $G_0$: a blue particle of $Z_1$ in $\V^N$ corresponds exactly to one (active) vertex of $G_0$, and the paths $(u, v)_{u\in Z_0, v \in Z_1}$ form  ${\mathcal Q}_1$. Since $i_v\le N$ if $(u,v)\in {\mathcal Q}_1$,  we have $\V^N(v)-\V^N(u)= \V(v)-\V(u)$ and 
 \begin{equation}\label{eq:index}
  V(v)-V(u):=X(u,v) \le \frac{n}{n-N} (\V^N(v)-\V^N(u)) + \frac{N}{n-N}.
\end{equation} 
 Finally,  $G_1$ is the sub-complete graph formed by  removing $Z_0$ and all incident edges in $G_0$.  

For the next steps, we proceed by induction on $j$ as long as $Z_j\neq \emptyset$. See Figure \ref{f:coupling}.

