 Suppose we are at step $j$ and have constructed the graph $G_j$, the set $Z_j\subset G_j$ and the paths in $\mathcal Q_j$.  Each active vertex  $u\in Z_j$ corresponds to a blue particle $u$ of $\V^N$ at time $j$. We randomly color $\#G_j-\#Z_j$ children of $u$ in $\V$ blue, among the $n-1$ leftmost ones, so that each blue child $v$ corresponds to an edge in $\{u\}\times (G_j\setminus Z_j)$.  The remaining children of $u$ in $\V$ are colored {\it red}.  We couple the family $(X(u,v))_{v\in G_j\setminus Z_j}$ with the displacements of the blue particles in $\V$ via the same coupling described above. 

 Purple and red particles at time $j$ give birth only to red particles. We then retain the $N$ leftmost particles of the population at generation $j+1$, which form the population of $\V^N$ at generation $j+1$.  It is composed of blue/red particles. If a blue particle $|v|=j+1$ with parent $u$ is selected in $\V^N$, we select the corresponding edge $(u,v)$ in $G_j$.  In the case several selected edges  point to the same vertex $v$ in $G_j \setminus Z_j$, so that multiple blue particles at time $j+1$ correspond to the same vertex $v$, we keep the one with minimal position in $\V$ {\it blue} and color the other particles {\it purple.}  By definition, $V(v):=V(u)+X(u,v)$ is the weight $S_{j+1}(\gamma,v)$ of the path $(\gamma,v)$ in $K_n$ obtained by  adding the edge $e=(u,v)$ to the unique path $\gamma \in {\mathcal Q}_j$ ending at $u$. The blue particles  $v$ in $\V^N$ at time $j+1$ form the set $Z_{j+1}$, and the paths $(\gamma,v)$ the set ${\mathcal Q}_{j+1}$.  Finally, we remove $Z_j$ and all incident edges to obtain the graph $G_{j+1}$.  We note that \eqref{eq:index} also holds for any $v \in Z_{j+1}$ (if it exists). Summing these inequalities, we obtain that \begin{equation}\label{eq:index-2}
V(v) \le \frac{n}{n-N}  \V^N(v)+\frac{N}{n-N}(j+1) , \qquad \forall\, v \in Z_{j+1}.
\end{equation} 

\noindent Therefore, we have constructed an exploration process $(Z_j, {\mathcal Q}_j)_{j\ge 0}$, together with its coupling with $\V^N$,  up to the first index $j$ for which $Z_j=\emptyset$.  \hfill {\footnotesize $\Box$}

\medskip
   Let $|u|=j$ be a blue particle in $\V^N$ at time $j$ and $v$ be a child of $u$ in $\V$ among the $n-1$ leftmost children. Conditionally on the whole branching random walk $\V$ and     on the exploration process up to time $j$, the probability for $v$ to be colored  red is 
\[ 1-\frac{ \#G_{j+1}}{n-1}= \frac{n-1-\#G_0+\#Z_0 + \#Z_1+\ldots+\#Z_j }{n-1}\le \frac{n-\#G_0+N(j+1)}{n-1}.
\]  

Now, we estimate the probability that $v$ is colored purple, given it is not red. In particular, $v$ belongs to $\V^N$ at time $j+1$. To avoid confusion, write temporarily $w$ for the vertex in $K_n$ associated to the particle $v$ in $\V^N$. Whenever $v$ is colored purple,  there must exist some particle $u'\neq u$  in $\V^N$ at time $j$ and some child $v'$ of $u'$ in $\V^N$ such that  $\V^N(v')-\V^N(u')$  is less than $x:=\V^N(v)- \V^N(u')$, and $v'$ is coupled with the vertex $w$. Let  ${\mathcal N}_{u'}$ be the set of children of $u'$ that are not red and  whose displacement (in $\V$) with respect to $u'$ is less than $x$.  By our coupling, we identify ${\mathcal N}_{u'}$ with a set of vertices in $G_{j+1}$. In particular, $w\in {\mathcal N}_{u'}$.
  By symmetry, conditionally on $\V$, on the exploration process up to time $j$, and on the red/non-red particles at time $j+1$,   the probability that $w\in {\mathcal N}_{u'}$ is $\frac{\#{\mathcal N}_{u'}}{\#G_{j+1}}$.   Since $\sum_{u'} \#{\mathcal N}_{u'} \le N$, we obtain that the conditional probability that $v$ is colored purple, given it is not colored red, is less than  
 \[
  \frac{N}{\#G_{j+1}}\le \frac{N}{\#G_0-N(j+1)}
  \]
as long as $N(j+1)<\#G_0$.  Since $\p(v \textrm{ is not blue} \mid \V) = \p(u \textrm{ is not blue} \mid \V)+\p(u \textrm{ is blue}, v \textrm{ is not blue} \mid \V)$, we find by induction that
 \begin{equation}\label{proba_red}
       \p( v \textrm{ is not blue} \mid \V) \le \sum_{k=0}^j \Big(\frac{n-\#G_0+N(k+1)}{n-1}  +\frac{N}{\#G_0-N(k+1)}\Big).
  \end{equation}

\subsection{Lower bound in Theorem \ref{t:main}}
The lower bound of Theorem \ref{t:main} is a consequence  of the following lemma.
\begin{lemma}
 Let $\alpha < \frac{\pi^2}{2}$ and $t<\frac{1}{\frac{\pi^2}{2}-\alpha}$. Choose $a\in (0,1)$ close enough to $1$ such that 
\[
- a + \frac{\pi^2}{2 a^2} t < \alpha t .
\]
Apply the above exploration process with $G_0=K_n$ and $N_0=N=\lfloor n^a\rfloor$. With probability tending to $1$ as $n\to\infty$, there is an active vertex  at time $\lfloor t\ln^3 n\rfloor $ such that $V(u)\le \alpha t\ln n$.  
\end{lemma}
 \begin{proof}
   For simplicity, suppose that $N=n^a$ and that $L:=t\ln^3 n= \frac{t}{a^3} \ln^3 N$ is an integer.  Note that $(-1+ \frac{\pi^2}2 \frac{t}{a^3}) \ln N= (-a + \frac{\pi^2}{2 a^2} t) \ln n $. Fix   $b\in (0,\alpha)$ such that $- a + \frac{\pi^2}{2 a^2} t<  b t$. By Proposition \ref{p:first_moment} (with $a=1$ there), there is  a particle $|u|=L$ in $\V^N$ with $\V^N(u)\le b t \ln n$ with probability going to $1$ as $n\to\infty$. By \eqref{proba_red}, the probability for $u$ to be blue also tends to $1$ as $n\to\infty$.  It remains to prove that $V(u)\le \alpha t \ln n$. By \eqref{eq:index-2},  $V(u)\le (bt \ln n)  \frac{n}{n-N} + \frac{N}{n-N} L \le \alpha t \ln n$ for $n$ large enough indeed. 
\end{proof}

