\section{Proofs of Lemmas \ref{main:upper}, \ref{main2:upper},  and of Proposition  \ref{p:first_moment}}\label{s:rw-brw}

Recall that $(Y_n)_{n\ge 0}$ is a centered random walk starting at $0$ with step distribution $\mbox{Exp}(1)-1$. In the first subsection, we present several estimates on $(Y_n)_{n\ge 0}$ and provide  the proofs of Lemmas \ref{main:upper}, \ref{main2:upper}. The second subsection is devoted to the study of the branching random walks $\V$ and $\V^N$, and to the proof of Proposition  \ref{p:first_moment}. 

\subsection{Estimates of random walks: Proofs of Lemmas \ref{main:upper} and \ref{main2:upper}}\label{sub:rw}

\begin{lemma}\label{l:mogulski}
 Let $\upsilon>0$ and $0<d<\frac{\pi^2}{2}$. There exists $\Delta_0>0$ such that for all $\Delta\ge \Delta_0$,   $r_0\le 0\le r_0+\Delta$ and  $\ell\ge 1$,
\begin{equation}
    \p(r_0  \le Y_j\le r_0+\Delta,\, \forall \, j\in \lb 1,  \ell\rb) \le e^{\Delta^\upsilon-\frac{d}{\Delta^2}\ell}. \label{mogulskii_upper0} 
\end{equation}

pre_theorem_intro_text:
We consider the complete graph $K_n$ of the set of vertices $\llbracket 1, n\rrbracket=\{1,2,\ldots,n\}$. Following Aldous \cite{aldous}, we  assign each edge  an independent exponential random variable with mean $n$. In this setting, Aldous proved the existence of a phase transition for the size of  the largest tree with average weight below a given threshold \cite[Theorem 1]{aldous}. We are interested in the analogous result for paths, rather than trees, established in  \cite[Proposition 3.7]{aldous}. In order to state this result, we introduce the following notation. 
For ease of notation, in this paper, we will suppose that the labels $X(u,v)_{u\neq v \in \llbracket 1, n\rrbracket}$  on the (non-oriented) edges of $K_n$ are i.i.d. copies of 
\begin{equation}\label{def:X}
X=ne \mathrm{Exp}(1)-1
\end{equation} 
where $\mathrm{Exp(1)}$ denotes an exponential random variable with mean $1$. 
A path $\gamma$ is a sequence of vertices $(\gamma_0,\gamma_1,\ldots,\gamma_\ell) \in  \llbracket 1, n\rrbracket^{\ell+1}$ which is made of distinct adjacent edges $(\gamma_i,\gamma_{i+1})$. We call $|\gamma|=\ell$ the length of the path, and let ${\mathcal P}_\ell$ be the collection of paths of length $\ell$. A path of length $0$ is reduced to a single vertex.

For any $\gamma \in {\mathcal P}_\ell$, we let $S_0(\gamma)=0$ and 
\begin{equation}    
S_i(\gamma) := X(\gamma_0,\gamma_1)+\ldots+X(\gamma_{i-1},\gamma_i),\qquad  i\in \llbracket 1,  \ell\rrbracket. \label{Sigamma}
\end{equation}
