\section{Proof of Theorem~\ref{thm:diagonal_to_ratio}}
\label{sec:proof_1.2}
In this section, we establish upper and lower bounds sufficient to prove Theorem~\ref{thm:diagonal_to_ratio}. We write $h = o_n(t)$ if the functions $t,h\colon \N \to \RR$ satisfy $\lim\limits_{n \to \infty} \frac{h(n)}{t(n)} = 0$. When the variable $n$ is clear from the context, we simply write $h=o(t)$. Let us define 
\begin{equation*}
g(n) \coloneqq \frac{(\log n)^2}{n} f(n),\quad
L \coloneqq \liminf\limits_{k \to \infty} \; \frac{\log (R(k,k))}{k}
\quad \text{ and } \quad 
M \coloneq \limsup_{t \to \infty } \; \max_{s\le t} \ \frac{\log(R(s,t))}{\sqrt{st \ }}
\end{equation*}

\begin{fact}\label{fact} Under the assumption of Conjecture~\ref{conj:weak.mult.RDC}, equality holds in \eqref{ineq:limsups}.
\end{fact}
\begin{proof}
For $0 < s\le t$, let $k$ be the positive integer such that $(k-1)^2 < st \le k^2$. Let 
\[D\coloneq\limsup_{k \to \infty} \;\frac{\log (R(k,k))}{k}.\]
Conjecture~\ref{conj:weak.mult.RDC} implies that 
\begin{equation*}
 R(s,t) \le R(k,k) \le 2^{(D+o_k(1))k}
\end{equation*}
 and, therefore, we have
\begin{equation*}
 \frac{\log(R(s,t))}{\sqrt{st \ }} \le \frac{\log(R(k,k))}{k-1} \le D +o_k(1) = D +o_t(1). \qedhere
\end{equation*}
\end{proof}

Let $G$ be a graph on $n$ vertices with no clique or independent set of size $k_n+1$. In other words, $\alpha(G) \le k_n$ and $\omega(G) \le k_n$. As $\chi(G) \ge n/\alpha(G)$, we conclude that
\begin{equation}\label{eq:lower.bound.inf.g}
 g(n)=\frac{f(n)}{n/(\log n)^2} \ge \frac{\chi(G)}{\omega(G)}\cdot\frac{(\log n)^2}{n} \ge 
\frac{(\log n)^2}{\alpha(G)\omega(G)}\ge
\frac{(\log n)^2}{k_n^2} \ge
L^2 + o_n(1),
\end{equation}
where the last inequality is true by \eqref{eq:bound.logn}. Hence, $\liminf\limits_{n \to \infty} g(n) \ge L^2$.

