 & \theta(a, N) \stackrel{\text{def.}}{=} \P_N\big( \mathscr{C}^{\geqslant a} \cap \partial B_R \neq \emptyset, \, \text{cap}_N( \mathscr{C}^{\geqslant a}) < \infty \big), \quad a \in \mathbb R, N \geq 1,
