& \le \eps \sum_{k \in B} \log \big( 1+ \sqrt{\pi}\varepsilon^{-1/2}\, c_k\, \big) + \eps \sum_{k \in B} \left(\frac{\varepsilon^{-1} \, c_k^2}{4}\right) \\
& \le \sqrt{\pi}\varepsilon^{1/2} \sum_{k \in B} \, c_k\, + \frac14 \sum_{k \in B} c_k^2,
\end{split}
\end{align}
which is again uniformly bounded as $(c_k) \in \l^1 \subset \l^2$, where we used $\eps^{1/2} \le c_k$ for $k \in B$.
\end{proof}

\subsection{Linear LDP II - \texorpdfstring{$L^\infty$}{Lg} norm}
In this subsection,
we prove an LDP for the linear solution to \eqref{linear} under $L^\infty$ norm.
In particular, we shall prove
\begin{proposition}
\label{PROP:linear2}
Consider the linear Schr\"odinger equation on the torus $\T = [0,2\pi]$ as in \eqref{linear}, with random initial data $u_0^\o$ given by \eqref{random_data}.
Then,
\begin{align}
\label{LDP_linear2}
\lim_{\eps\to 0^+} \eps \log \PP \big( \|u(t)\|_{L^\infty (\T)} \ge z_0 \eps^{-1/2} \big) = - \frac{z_0^2}{\sum_{k \in \Z} c_k^2}, 
\end{align}

\noi 
where $\mathcal B_\eps$ is defined in \eqref{Beps}.
We first note, see also \cite[Proposition 4.1]{GGKS21},\footnote{Please note that \cite[Proposition 4.1]{GGKS21} only requires that $\|c_k\|_{\l^1_k} < \infty$.} that 
\begin{align}
\label{pp400}
\lim_{\eps \to 0^+} \eps \log \PP \big( \| u_{\rm app} (t) \|_{L^\infty (\T)} > z_0 (\eps^{-1/2} + \eps^{-1/2 + \dl}) \big) = - \frac{z_0^2}{\sum_{k \in \Z} c_k^2}.
\end{align}

\begin{align}
\label{THM_LDP4}
\lim_{\eps \to 0^+} \eps \log \PP \Big( \|u(t,x) \|_{\FL^1 (\T)} > z_0\eps^{-1/2} \Big) = - \frac{z_0^2}{\sum_k c_k^2},
