\begin{corollary}\label{Cor:siltingdiscretegentle}
    Let $A$ be a homologically smooth, proper graded gentle algebra and let $(S,\eta,\Delta)$ be the associated graded surface. Then the following are equivalent.
    \begin{enumerate}
        \item $\per(A)$ is silting-discrete.
        \item $S$ is of genus $0$ and $m_i$ defined above satisfies  the `No Equipartition' condition
        \[ \sum_{j\in J}m_j\not=\frac{1}{2}\sum_{j=1}^bm_j  \] 
        for all $J\subset\{1,2,\ldots,b\}$.
    \end{enumerate}
\end{corollary}

ref_dict.thm::1.1:
\begin{theorem}[Theorem \ref{theo::main-result-skew-gentle}]\label{thm::1.1}
Let $A$ be a skew-gentle algebra. Then, $A$ is $\tau$-tilting finite if and only if $A$ is representation-finite, or equivalently, $A$ admits no band module.
\end{theorem}

ref_dict.Thm:siltingdiscreteforskewgentle:
\begin{theorem}\label{Thm:siltingdiscreteforskewgentle}
Let $A=\Bbbk Q/\langle I \rangle$ be a graded skew-gentle algebra with surface model $(S,O,\eta,\Delta)$. Consider the following conditions.
  \begin{enumerate}
      \item $\per(A)$ is silting-discrete.
      \item $S$ is of genus $0$ and $\# O\le 1$. Moreover, $\omega_\eta(\ell)\neq 0$ for any simple closed curve $\ell$.
      \item $S$ is of genus $0$ and 
        \[ \sum_{j\in J}m_j\not=2 \mbox{ for all $J\subset\{1,2,\ldots,b\}$,} \] 
        where  $m_i=\omega_\eta(\partial_i)+2$ for $1\le i\le b$. 
 \end{enumerate}
 Then (1) implies (2), and (2) is equivalent to (3).
\end{theorem}

ref_dict.def::tau-tilt-finite:
\begin{Def}\label{def::tau-tilt-finite}
A finite-dimensional $\Bbbk$-algebra $A$ is called \emph{$\tau$-tilting finite} if it admits only finitely many $\tau$-tilting modules up to isomorphisms, and \emph{$\tau$-tilting infinite} otherwise.
\end{Def}

ref_dict.thm:main1:
\begin{theorem}\label{thm:main1}
    Let $A$ be a homologically smooth, proper graded gentle algebra and let $(S,\eta,\Delta)$ be the associated graded surface. Then $\per(A)$ is silting-discrete if and only if $S$ is of genus zero and $\omega_\eta(\ell)\neq 0$ for any simple closed curve $\ell$.
\end{theorem}

ref_dict.Prop:silt:
\begin{Prop}[{\cite[Theorem 2.15]{AM17}}]\label{Prop:silt}
Let $\T$ be a Hom-finite Krull-Schmidt triangulated category with silting objects. If $\T$ is silting-discrete, then any pre-silting object in $\T$ is partial silting. 
\end{Prop}

ref_dict.thm::1.2:
\begin{theorem}[Theorem \ref{thm:main1} and Corollary \ref{Cor:siltingdiscretegentle}]\label{thm::1.2}
    Let $A$ be a homologically smooth, proper graded gentle algebra and let $(S,\eta,\Delta)$ be the associated graded surface with boundary components $\partial_i$, for $1 \leq i \leq b$. Then the following are equivalent:
    \begin{enumerate}
        \item The perfect derived category $\per(A)$ is silting-discrete.
        \item $S$ is of genus $0$ and admits no simple closed curves with winding number $0$.
        \item $S$ is of genus $0$ and the following `No Equipartition' condition is satisfied
        \[ \sum_{j\in J}m_j\not=\frac{1}{2}\sum_{j=1}^bm_j  \] 
        for all $J\subset\{1,2,\ldots,b\}$,
        where  $m_i=\omega_\eta(\partial_i)+2$ for $1\le i\le b$. 
    \end{enumerate}
\end{theorem}

ref_dict.JSW:
\begin{Thm}\cite{JSW23}\label{JSW}
Let $A$ be a graded gentle algebra arising from a graded surface with dissection $(S,\eta,\Delta)$.
The following two conditions are equivalent:
\begin{enumerate}
    \item Any pre-silting object in $\per(A)$ is partial silting;
    \item $S$ is of genus zero, or $S$ is of genus one such that 
\begin{equation}\label{equ:neq}
    \Tilde{A}(\eta)\neq \gcd(\omega_\eta(\partial_1)+2,\omega_\eta(\partial_2)+2,\cdots,\omega_\eta(\partial_b)+2)
\end{equation}
where $\Tilde{A}(\eta)=\gcd(\omega_\eta(s),\omega_\eta(t),\omega_\eta(\partial_1)+2,\omega_\eta(\partial_2)+2,\cdots,\omega_\eta(\partial_b)+2)$.
\end{enumerate} 
\end{Thm}

ref_dict.Def:silting-discrete:
\begin{definition}[{\cite[Definition 3.6]{Aihara13}}]\label{Def:silting-discrete}
Let $\T$ be a triangulated category with silting objects. We say that $\T$ is \emph{silting-discrete} if for any $P, Q$ in $\silt \T$ with $P\geq Q$, the poset $[P, Q]$ is finite.
\end{definition}

