ref_dict.corollary: cartier duality is an antiequ:
\begin{corollary}\label{corollary: cartier duality is an antiequivalence}
    Cartier duality induces an involutive antiequivalence 
    between flat Mittag-Leffler affine commutative group schemes
    and coflat commutative group ind-finite ind-schemes.
\end{corollary}

ref_dict.definition: coflat:
\begin{definition}\label{definition: coflat}
    An ind-affine $R$-ind-scheme $\SpInd A \to \Spec R$ is \emph{coflat} if $A$ is pro-projective as pro-$R$-module.
\end{definition}

ref_dict.cor: linear duality equivalence:
\begin{corollary} \label{cor: linear duality equivalence}
There exists an equivalence
\[(\Mod_R^{fl})^{op}\simeq(\ProMod^f_R)^{pproj},\] unique up to a canonical isomorphism. 
\end{corollary}

ref_dict.maintheorem: cartier:
\begin{theoremalpha}\label{maintheorem: cartier}
    (Corollary \ref{corollary: cartier duality is an antiequivalence})
    The assignment $G \mapsto G^\vee = \Homs(G, \Gm)$ 
    is an antiequivalence of categories between flat Mittag-Leffler affine commutative group schemes over $R$ and coflat commutative group ind-finite ind-schemes over $R$.
\end{theoremalpha}

ref_dict.theorem: FM for 1-motives:
\begin{theorem}\label{theorem: FM for 1-motives}
    Let $R$ be a Noetherian ring admitting a dualizing complex.
    Let $G=\Spec A$ and $H=\Spec B$ be flat Mittag-Leffler affine commutative group schemes of finite type over $R$ and let $u: G^\vee \times H^\vee \to \Gm$ be a bilinear pairing.
    Then there is an equivalence of categories
    \[ \QCoh([G/H^\vee]) \simeq \QCoh([H/G^\vee]).\]
\end{theorem}

ref_dict.maintheorem: fourier for BG:
\begin{theoremalpha}(Theorem \ref{theorem: FM for BG})
    \label{maintheorem: fourier for BG}
    Let $R$ be a Noetherian ring and let $G$ be a flat Mittag-Leffler affine commutative group scheme.
    Then the pairing $G^\vee \times BG \to B\Gm$ induces an equivalence 
    \[ \IndCoh(G^\vee)^{\geq 0} \simeq \QCoh(BG)^{\geq 0}.\]
\end{theoremalpha}

ref_dict.theorem: FM for B of G dual is symmetric:
\begin{theorem}\label{theorem: FM for B of G dual is symmetric monoidal}
    Let $R$ be a Noetherian ring admitting a dualizing complex and $G \to S = \Spec R$ be a flat Mittag-Leffler affine commutative group scheme.
    The Fourier-Mukai equivalence
    \[ \Phi_G: \QCoh(G) \tensor{\QCoh(S)} \IndCoh(S) \to \IndCoh(BG^\vee)\]
    carries a symmetric monoidal structure with respect to convolution on $G$ and tensor product in $\IndCoh(BG^\vee)$.
\end{theorem}

ref_dict.remark: symmetric monoidal structure and:
\begin{remark}\label{remark: symmetric monoidal structure and BG}
In fact, Heine proved a version of Proposition \ref{prop: symmetric monoidal structures on monads} for much more general $(\infty,2)$-categories $\mathcal C$, including $(\Op_{\infty}^{\Einfty})^{op}$ \cite[Theorem 6.30]{Hei25}. Thus, if $A_1$ and $A_2$ are commutative bialgebras in $\mathcal C$, then the space of symmetric monoidal functors $A_1\mathrm{-comod} \to A_2\mathrm{-comod}$ is equivalent to the space of commutative bialgebra morphisms $A_1 \to A_2$ in $\mathcal C$.

    Unfortunately, this does not apply in the setting of Theorem \ref{theorem: FM for BG} since $\QCoh(S)^{\geq 0}$ is not a symmetric monoidal category. Presumably, this technical difficulty can be resolved by choosing an appropriate renormalization of categories. However, in the case of the Cartier dual of a formal Lie group, our Fourier-Mukai equivalence extends to an equivalence over $\QCoh(S)$, so we find that when $G$ is the Cartier dual of a formal Lie group, $\Phi': \QCoh(G^\vee) \to \QCoh(BG)$ upgrades to a symmetric monoidal functor. 
\end{remark}

