ref_dict.theorem:vertices imply sources:
\begin{theorem}[{\cite[Corollary 7.4]{Puig1999}}]\label{theorem:vertices imply sources}
Keep the notation of \ref{notation:stable equ of Morita type}. Assume that $k$ is algebraically closed. Then the following are equivalent:
\begin{enumerate}[{\rm (i)}]
	\item $X$ is a twisted diagonal subgroup of $G\times H$.
	\item $V$ is an endopermutation $\O X$-module.
	\item $p$ does not divide the $\O$-rank of $V$.
\end{enumerate}
\end{theorem}

ref_dict.void:points:
\begin{void}\label{void:points}

	{\rm (i) Let $G$ be a finite group and $A$ an $\O$-algebra. Following Puig \cite{Puig pointed group}, a {\it point} of $A$ is an $A^\times$-conjugacy class of a primitive idempotent in $A$. Let $I$ be a primitive decomposition of $1_A$ in $A$. The {\it multiplicity} of a point $\alpha$ on $A$ is the cardinal $m_\alpha=|I\cap \alpha|$ of the set $I\cap \alpha$, and it does not depend on the choice of $I$. Denote by $\P(A)$ the set of points of $A$. The map sending a primitive idempotent $i\in A$ to the projective (resp. simple) $A$-module $Ai$ (resp. $Ai/J(A)i$) induces a bijection between $\P(A)$ and the set of  isomorphism classes of projective (resp. simple) modules; see e.g. \cite[Proposition 4.7.17 (i),(ii)]{Lin18a}. Suppose that $A$ is split. Then for any point $\alpha$ of $A$ and any $i\in \alpha$, we have $\dim_k(Ai/J(A)i)=m_\alpha$, and hence $\End_k(Ai/J(A)i)$ is isomorphic to the matrix algebra $M_{m_\alpha}(k)$; see e.g. \cite[Proposition 4.7.17 (iv)]{Lin18a}. Denote the $k$-algebra $\End_k(Ai/J(A)i)$ by $A(\alpha)$. It is clear that up to isomorphism $A(\alpha)$ is independent of the choice of $i$. By Wedderburn's theorem for split algebras (see \cite[Theorem 1.14.6]{Lin18a}), the sum of the structure homomorphisms $A\to \End_k(Ai/J(A)i)=A(\alpha)$ induces an isomorphism of $k$-algebras
		\begin{equation}\label{equation:direct product decomposition}
		A/J(A)\cong \oplus_{\alpha\in \P(A)}A(\alpha).
		\end{equation}

(ii)	Let $A$ be a $G$-algebra over $\O$ and $P$ a subgroup of $G$. A {\it point of $P$ on $A$} is a point $\alpha$ of $A^P$.  Following Puig \cite{Puig pointed group}, we call $P_\alpha$ a pointed group on $A$. Let $Q_\beta$ be another pointed group on $A$. We say that $Q_\beta$ is contained in $P_\alpha$ and write $Q_\beta\leq P_\alpha$ if $Q\leq P$ and if there are $i\in \alpha$ and $j\in \beta$ such that $ij=j=ji$.    If ${\rm br}_P^A(\alpha)\neq \{0\}$, the point $\alpha$ is called a {\it local point of $P$ on $A$}, any idempotent in $\alpha$ is called a {\it primitive local idempotent of $P$ on $A$}, and $P_\alpha$ is called a {\it local pointed group}; we know that in this case ${\rm br}_P^A(\alpha)$ is a point of $A(P)$. We use the symbol $\LP_A(P)$ to denote the set of local points of $P$ on $A$. The correspondence $\alpha\mapsto {\rm br}_P^A(\alpha)$ induces a bijection between $\LP_A(P)$ and $\P(A(P))$; see e.g. \cite[Lemma 14.5]{Thevenaz}.

(iii) Let $G$ be a finite group. A {\it block} of $\O G$ is a primitive idempotent $b$ in $Z(\O G)$, and $\O Gb$ is called a {\it block algebra} of $\O G$. A defect group of $b$ is a maximal subgroup $P$ of $G$ such that $\br_P^{\O G}(b)\neq 0$. A primitive idempotent $i\in (\O Gb)^P$ is called a {\it source idempotent} of $b$ if $\br_P^{\O G}(i)\neq 0$, and the interior $P$-algebra $i\O Gi$ is called a {\it source algebra} of $b$; see \cite[\S3]{Puig pointed group} or \cite[Definition 6.4.1]{Lin18b}. It is well-known that block algebras and source algebras are symmetric algebras; see e.g. \cite[Theorem 2.11.11]{Lin18a}. By \cite[3.5]{Puig pointed group} or \cite[Theorem 6.4.6]{Lin18b}, the $\O Gb$-$i\O Gi$-bimodule $\O Gi$ and its dual $i\O G$ induce a Morita equivalence between $\O Gb$ and $i\O Gi$. 
}
\end{void}

ref_dict.prop:relation of source algebras:
\begin{proposition}\label{prop:relation of source algebras}
Keep the notation of Proposition \ref{prop: source idempotents}. Let $A:=i\O Gi$ and $B:=j\O Hj$ be the corresponding source algebras. The following hold:
\begin{enumerate}[{\rm (i)}]
	\item  There is a primitive idempotent $t\in \End_{\O P\otimes_\O B^{\rm op}}(iMj)$ with $\br_P^{\End_{B^{\rm op}}(iMj)}(t)\neq 0$ such that we have an isomorphism of interior $P$-algebras $$t\End_{B^{\rm op}}(iMj)t\cong e(\End_\O({}_\psi V)\otimes_\O {}_\tau B)e$$ for some group isomorphisms $\psi:P\to X$, $\tau:P\to Q$ and some primitive idempotent $e\in (\End_\O({}_\psi V)\otimes_\O {}_\tau B)^P$ satisfying $\br_P(e)\neq 0$.
	\item As an $\O$-algebra, $t\End_{B^{\rm op}}(iMj)t$ is a symmetric algebra and has an $\O$-basis which is stable under the $P$-conjugation action. 
\end{enumerate}

\end{proposition}

ref_dict.notation:stable equ of Morita type:
\begin{notation}\label{notation:stable equ of Morita type}
Let $G$ and $H$ be finite groups, $b$ a block of $\O G$ and $c$ a block of $\O H$. Assume that $M$ is an indecomposable
$(\O Gb, \O Hc)$-bimodule, which is finitely generated projective as a left and right module, inducing a stable equivalence of Morita type between $\O Gb$ and $\O Hc$. This means that $M\otimes_{\O Hc}M^*\cong \O Gb\oplus U_1$ for some projective $\O Gb\otimes_\O (\O Gb)^{\rm op}$-module $U_1$ and $M^*\otimes_{\O Gb} M\cong \O Hc\oplus U_2$ for some projective $\O Hc\otimes_\O (\O Hc)^{\rm op}$-module $U_2$, where $M^*:={\rm Hom}_\O(M,\O)$.
Let $X$ be a vertex of $M$ and $V$ an $\O X$-source of $M$.
\end{notation}

ref_dict.theorem: Puig 7.2:
\begin{theorem}[{\cite[Theorem 7.2]{Puig1999}}]\label{theorem: Puig 7.2}
	Assume that $k$ is algebraically closed. Let $P$ be a finite $p$-group, and let $A$ and $B$ be finitely generated $\O$-free interior $P$-algebras such that $1_A$ and $1_B$ are primitive in $A^P$ and $B^P$ respectively. Let $V$ be a finitely generated indecomposable $\O$-free left $\O P$-module and write $S:=\End_\O(V)$. Assume that there is an interior $P$-algebra embedding $g:A\to S\otimes_\O B$. If $P$ stabilises by conjugation $\O$-bases of $A$ and $B$, $A$ admits a nondegenerate symmetric $\O$-linear form $\mu:A\to \O$ and $A(P)\neq 0$, then $V$ is an endopermutation $\O P$-module. 
\end{theorem}

ref_dict.notation:basis notatin for algebras:
\begin{notation}\label{notation:basis notatin for algebras}
{\rm  For any $\O$-algebra $A$, we denote by $A^\times$ the group of invertible elements of $A$ and by $A^{\rm op}$ the opposite $\O$-algebra of $A$. All $\O$-algebras in this paper are assumed to be finitely generated as $\O$-modules; this implies that all $k$-algebras in this paper are finite-dimensional. Unless otherwise specificed, all modules are left modules. A homomorphism $f:A\to B$ between $\O$-algebras is not required to be unitary. Following Puig \cite{Puig pointed group}, we say that $f$ is an {\it embedding} if $\ker(f)=0$ and ${\rm Im}(f)=f(1_A)Bf(1_A)$. Following Puig \cite{Puig1988}, we say that $f$ is a {\it covering homomorphism} if $f(A)+J(B)=B$. Let $G$ and $H$ be finite groups. A {\it $G$-algebra over $\O$} is an $\O$-algebra $A$ endowed with an action of $G$ by $\O$-algebra automorphisms, denoted $a\mapsto {}^ga$, where $a\in A$ and $g\in G$. An {\it interior $G$-algebra over $\O$} is an $\O$-algebra $A$ with a group homomorphsim $G\to A^\times$, called the structure homomorphism. For any $g\in G$ we abusively use the same letter $g$ to denote the image of $g$ in $A^\times$. Let $A$ be an interior $G$-algebra over $\O$, $B$ an interior $H$-algebra over $\O$, and $V$ a left (resp. right) $\O H$-module. Then $\End_\O(V)$ is an interior $H$-algebra.  Let $f:G\to H$ be a group isomorphism. Then we denote by ${}_f V$ (resp. $V_f$) the left (resp. right) $\O G$-module with structure homomorphism $G\xrightarrow{f} H\to \End_\O(V)^\times$, and by ${}_f B$ the interior $G$-algebra with structure homomorphism $G\xrightarrow{f}H\to\Aut(B)$. If $G=H$, we consider $A\otimes_\O B$ as an interior $G$-algebra over $\O$ with the structure homomorphism $G\cong \Delta G\hookrightarrow G\times G\to \Aut(A)\times\Aut(B)\to\Aut(A\otimes_\O B)$. For a $k$-algebra $A$, we say that $A$ is {\it split}, if for any simple $A$-module $V$, we have $\End_A(V)\cong k$; we say that $A$ is {\it semisimple} if the Jacobson radical $J(A)=0$.
}	
\end{notation}

ref_dict.void: Brauer homomorphisms:
\begin{void}\label{void: Brauer homomorphisms}
	{\rm \textbf{Brauer homomorphisms.}	Let $G$ be a finite group, and let $A$ and $B$ be $G$-algebras over $\O$ (resp. $\O G$-modules). For any subgroup $P$ of $G$, we denote by $A^P$ the $N_G(P)$-subalgebra (resp. $kN_G(P)$-submodule) of $P$-fixed points of $A$.  For any two $p$-subgroups $Q\leq P$ of $G$, the {\it relative trace map} ${\rm Tr}_Q^P:A^Q\to A^P$ is defined by ${\rm Tr}_Q^P(a)=\sum_{x\in [P/Q]}{}^xa$, where $[P/Q]$ denotes a set of representatives of the left cosets of $Q$ in $P$. We denote by $A(P)$ the {\it $P$-Brauer quotient} of $A$, i.e., the $N_G(P)$-algebra (resp. $kN_G(P)$-module)
		\[A^P/(\sum_{Q<P}{\rm Tr}_Q^P(A^Q)+J(\O)A^P).\]
		We denote by ${\rm br}_P^A:A^P\to A(P)$ the canonical map, which is called the {\it $P$-Brauer homomorphism}. Sometimes we write $\br_P$ instead of $\br_P^A$ if no confusion arises. The following properties of Brauer homomorphisms are well-known and easy to check:

	(i)	If $f:A\to B$ is a homomorphism of $G$-algebras (resp. $\O G$-modules), then $f$ restricts to a homomorphism of $N_G(P)$-algebras (resp. $\O N_G(P)$-modules) $f^P:A^P\to B^P$, which in turn induces a homomorphism of $N_G(P)$-algebras (resp. $kN_G(P)$-modules) 
	\begin{equation}\label{equation: f(P)}
	f(P): A(P)\to B(P)
	\end{equation}
	 sending $\br_P^A(a)$ to $\br_P^B(f(a))$ for any $a\in A^P$. In other words, we have $f(P)\circ \br_P^A=\br_P^B\circ f^P$. In this way, the $P$-Brauer construction defines a functor (called the $P$-Brauer functor) from the category of $G$-algebras (resp. $\O G$-modules) to the category of $N_G(P)$-algebras (resp. $kN_G(P)$-modules). 

(ii) If $Q$ is a $p$-subgroup of $N_G(P)$, then $P$-Brauer homomorphism $\br_P^A:A^Q\to A(Q)$ restricts to a homomorphism $(\br_P^A)^Q: A^Q\to A(P)^Q$ of $N_G(P,Q)$-algebras (resp. $kN_G(P,Q)$-modules) (where $N_G(P,Q):=N_G(P)\cap N_G(Q)$), which in turn induces a homomorphism of $N_G(P,Q)$-algebras (resp. $kN_G(P,Q)$-modules)
		\begin{equation}\label{equation: Brauer const. transitivity}
		\alpha_A(P,Q):A(Q)\to A(P)(Q)
		\end{equation}
		sending $\br_Q^A(a)$ to $\br_Q^{A(P)}(\br_P^A(a))$ for any $a\in A^Q$. Note that $\alpha_A(P,Q)$ is exactly $(\br_P^A)(Q)$ in the sense of (i).

(iii) The inclusion map $A^P\otimes_\O B^P\to (A\otimes_\O B)^P$ induces a homomorphism of $N_G(P)$-algebras (resp. $kN_G(P)$-modules)
		\begin{equation}\label{equation: Brauer map tensor products}
		\alpha_{A,B}(P):A(P)\otimes_k B(P)\to (A\otimes_\O B)(P)
		\end{equation}
		sending $\br_P(a)\otimes \br_P(b)$ to $\br_P(a\otimes b)$ for any $a\in A^P$ and $b\in B^P$. In the algebra case, it is clear that both $\alpha_A(P,Q)$ and $\alpha_{A,B}(P)$ are unitary homomorphisms.		 
	}
\end{void}

