ref_dict.thm:K-moduli:
\begin{thm}\label{thm:K-moduli}
Let $X$ be a K-semistable $\bQ$-Fano threefold with volume $(-K_X)^3 = V$.
\begin{enumerate}
    \item If $V\geq 26$, then $X$ has only $cA_1$-singularities or  cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
    \item If $V\geq 22$, then $X$ has only $cA_1$-singularities, isolated $cA_2$-singularities, $D_\infty$-singularities, or cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
    \item If $V\geq 11$, then any non-Gorenstein singularity $x\in X$ is a cyclic quotient of a (possibly smooth) hypersurface singularity of type $cA_{\leq 2}$.
\end{enumerate}
If in addition $X$ is $\bQ$-Gorenstein smoothable, then it does not admit cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
\end{thm}

ref_dict.rem:K-mod:
\begin{rem}\label{rem:K-mod}
According to the author's knowledge based on \cite{SS17, LX19, ADL21, ACC+, ACD+, CDG+, CT23, DJKHQ24, LZ24, Zha24, CFFK24}, we give a list of families of smooth Fano threefolds with volume $V\geq 11$ whose K-moduli compactifications are currently unknown. We hope Theorem \ref{thm:K-moduli} can be used to study these families in the future. We follow Mori--Mukai's notation for the numbering of these families.
\begin{enumerate}
    \item $V\geq 26$: \textnumero 2.20, 2.21, 3.11;
    \item $22\leq V<26$: \textnumero 1.10, 2.16, 2.17, 3.6, 3.7, 3.8;
    \item $11\leq V<22$: \textnumero 1.6, 1.7, 1.8, 1.9, 2.5, 2.6, 2.7, 2.8, 2.9, 2.10, 2.11, 2.12, 2.13, 2.14, 3.1, 3.2, 3.3, 3.4, 3.5.
\end{enumerate}
\end{rem}

ref_dict.thm:nv-3fold:
\begin{thm}\label{thm:nv-3fold}
Let $x\in X$ be a klt threefold singularity. Then $\hvol(x,X)\geq 9$ if and only if  $x\in X$ is either a hypersurface singularity of type $cA_{\leq 2}$, or a cyclic quotient singularity of type $\frac{1}{2}(1,1,1)$, $\frac{1}{3}(1,1,0)$, $\frac{1}{3}(1,1,1)$, or $\frac{1}{3}(1,1,2)$. 
\end{thm}

ref_dict.thm:nv-can:
\begin{thm}\label{thm:nv-can}
Let $x\in X$ be a Gorenstein canonical non-hypersurface threefold singularity. Then $\hvol(x,X)\leq 9$, and equality holds if and only if $x\in X$ is a quotient singularity  of type $\frac{1}{3}(1,1,1)$. 
\end{thm}

ref_dict.expl:ADE:
\begin{expl}\label{expl:ADE}
\begin{enumerate}
    \item If $x\in X$ is an $A_k$-singularity, that is, locally analytically given by $x_1 x_2 + x_3^2 + x_4^{k+1} = 0$, then its local volume is $16$ when $k=1$, $\frac{125}{9}$ when $k=2$, and $\frac{27}{2}$ when $k\geq 3$. See \cite[Section 5]{Li18}, \cite[Example 4.7]{LL19} and \cite[Example 7.1.2]{LX20}.
\item If $x\in X$ is a $cA_1$-singularity but not an $A_k$-singularity, then $x\in X$ has to be a transversal $A_1$-singularity with $\hvol(x,X) = \frac{27}{2}$.
\item If $x\in X$ is defined by $x_1 x_2 + x_3^3 + x_4^k=0$ for $3\leq k\leq 6$, then by \cite{CS15} and \cite{LST25} we have $\hvol(x,X) = \frac{4(3+k)^3}{9k^2}$. Thus we get values $\frac{32}{3}, \frac{343}{36}, \frac{2048}{225}, 9$ for $k = 3,4,5,6$. Note that  $k=3,4,5$ correspond to $D_4$, $E_6$, and $E_8$-singularities.
\item If $x\in X$ is a $D_k$-singularity with $k\geq 5$, then we have local equation $x_1x_2 + x_3^2 x_4 + x_4^{k-1} = 0$. Then by \cite[Appendix, Example 4.1]{LX18} we know that its local volume is computed by the monomial valuation $v_{\bfw}|_{K(X)}$ with weight $\bfw=(1, 1, \sqrt{3}-1, 4-2\sqrt{3})$ whose K-semistable Fano cone degeneration is precisely the $D_\infty$-singularity $x_1x_2 + x_3^2 x_4 = 0$. Thus we have $\hvol(x, X) = 6\sqrt{3}$ which is the same as the local volume of a $D_\infty$-singularity.
\item If $x\in X$ is an $E_7$-singularity, then we have local equation $x_1x_2 + x_3^3 + x_3 x_4^3 =0$. By \cite[Section 8]{Li18} and \cite[Example 7.1.3]{LX20} we know that $\hvol(x, X) = \frac{250}{27}$.
\end{enumerate}

\end{expl}

full_context:
The local volume $\hvol(x,X)$ of a klt singularity $x\in X$, introduced by Chi Li in \cite{Li18}, is a numerical invariant that has played a crucial role in the recent development of a local K-stability theory for singularities; see \cite{LLX18, Zhu25} for recent surveys. It is thus natural to further investigate the distribution of local volumes in a fixed dimension $n$, such as explicit bounds and gaps. In \cite{LX19} it was shown that $\hvol(x,X)\leq n^n$ and equality holds if and only if $x\in X$ is smooth. Then it was conjectured in \cite{SS17}, known as the ODP Gap Conjecture, that the second largest local volume is $2(n-1)^n$ which is obtained by the ordinary double point. This conjecture is confirmed in dimension at most $3$ \cite{LL19, LX19} and for local complete intersection singularities \cite{Liu22}. More recently, it was shown in \cite{XZ24}, as a consequence of their local boundedness result for K-semistable Fano cone singularities, that the local volumes in a fixed dimension are discrete away from zero. See also \cite{HLQ23, Zhu24, LMS23} for previous results in lower dimensions and \cite{HLQ24} for general coefficient sets.

In this article, we establish an optimal upper bound for local volumes of Gorenstein canonical non-hypersurface threefold singularities. Our main result goes as follows.

In this article, we establish an optimal upper bound for local volumes of Gorenstein canonical non-hypersurface threefold singularities. Our main result goes as follows.

Theorem \ref{thm:nv-can} can be thought of as a refinement of the ODP Gap Theorem for threefolds in \cite{LX19} that any non-smooth threefold singularity $x\in X$ satisfies $\hvol(x,X)\leq 16$, and equality holds if and only if $x\in X$ is an $A_1$-singularity.

\begin{thm}\label{thm:nv-3fold}
Let $x\in X$ be a klt threefold singularity. Then $\hvol(x,X)\geq 9$ if and only if $x\in X$ is either a hypersurface singularity of type $cA_{\leq 2}$, or a cyclic quotient singularity of type $\frac{1}{2}(1,1,1)$, $\frac{1}{3}(1,1,0)$, $\frac{1}{3}(1,1,1)$, or $\frac{1}{3}(1,1,2)$. 
\end{thm}

\begin{thm}\label{thm:K-moduli}
Let $X$ be a K-semistable $\bQ$-Fano threefold with volume $(-K_X)^3 = V$.
\begin{enumerate}
 \item If $V\geq 26$, then $X$ has only $cA_1$-singularities or cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
 \item If $V\geq 22$, then $X$ has only $cA_1$-singularities, isolated $cA_2$-singularities, $D_\infty$-singularities, or cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
 \item If $V\geq 11$, then any non-Gorenstein singularity $x\in X$ is a cyclic quotient of a (possibly smooth) hypersurface singularity of type $cA_{\leq 2}$.
\end{enumerate}
If in addition $X$ is $\bQ$-Gorenstein smoothable, then it does not admit cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
\end{thm}

\begin{thm}\label{thm:nv-mld}
Let $x\in X$ be a klt threefold singularity. Then 
\begin{equation}\label{eq:nv-mld}
 \hvol(x,X) \leq 9 \cdot \mld(x,X).
\end{equation}
Moreover, equality holds if and only if $x\in X$ is a cyclic quotient singularity of type $\frac{1}{r}(1,1,1)$ for some $r\in \bZ_{>0}$.
\end{thm}

\begin{proof}[Proof of Theorem \ref{thm:nv-3fold}]
 The ``if'' part is a direct consequence of Example \ref{expl:quotient} and Proposition \ref{prop:nv-hyp}.
 For the ``only if'' part, let $(\tx\in \tX)\to (x\in X)$ be the index $1$ cover of $K_X$ whose Cartier index is denoted by $d$. Then by Theorem \ref{thm:finite-deg} we have 
 \[
 \hvol(\tx, \tX) = d\cdot \hvol(x,X)\geq 9d.
 \]
 If $d=1$, i.e.\ $x\in X$ is Gorenstein, then by Theorem \ref{thm:crex-cDV} we know that $x\in X$ is either a hypersurface singularity or a cyclic quotient singularity of type $\frac{1}{3}(1,1,1)$. The hypersurface singularity case follows from Proposition \ref{prop:nv-hyp}. If $d\geq 2$, then we have $\hvol(\tx, \tX) \geq 18$ which implies that $\tx\in \tX$ is smooth and $d \leq 3$ by Theorem \ref{thm:ODP-gap}. Thus $x\in X$ is a cyclic quotient singularity of order $2$ or $3$. If $d=2$, then $x\in X$ is of type $\frac{1}{2}(1,1,1)$ as the other case $\frac{1}{2}(1,1,0)$ is Gorenstein. If $d=3$, then $x\in X$ is of type $\frac{1}{3}(1,1,0)$ or $\frac{1}{3}(1,1,2)$ as the other two cases $\frac{1}{3}(1,2,0)$ or $\frac{1}{3}(1,1,1)$ are both Gorenstein.
\end{proof}

Since $K_{\tX}$ is Cartier, we know that $\mld(\tx,\tX) \geq 1$ is a positive integer. If $\crex(\tx, \tX) = 0$, then $\mld(\tx, \tX) = 1$ and \eqref{eq:nv-mld-cover} follows by Theorem \ref{thm:nv-can} with equality if and only if $\tx\in \tX$ is a cyclic quotient singularity of type $\frac{1}{3}(1,1,1)$. If $\crex(\tx,\tX) >0$, then by Theorem \ref{thm:crex-cDV} we know that $\tx\in \tX$ is a cDV singularity. Then we have three cases: $\tx\in \tX$ is smooth, non-smooth terminal, or non-terminal. The smooth case is obvious as $\mld(\tx,\tX) = 3$ and $\hvol(\tx,\tX) = 27$. For the terminal case, we have $\mld(\tx,\tX) = 2$ by \cite{Mar96}. Thus \eqref{eq:nv-mld-cover} follows from Theorem \ref{thm:ODP-gap} as $\hvol(\tx, \tX)\leq 16 < 18 = 9\cdot \mld(\tx,\tX)$. The last case is when $\tx\in \tX$ is not terminal. Let $\phi: \tZ\to \tX$ be a terminalization. Then we know that $\phi^{-1}(\tx)$ has dimension $1$ since $\phi$ is exceptional over $\tx$ and there are no crepant exceptional divisors over $\tx\in \tX$ by the assumption that $\crex(\tx, \tX) = 0$. Let $\eta$ be a generic point of $\phi^{-1}(\tx)$. Since $\tZ$ is terminal, we know that $\tZ$ is smooth at $\eta$. Thus we have $\mld(\tx,\tX) \leq \mld(\eta, \tZ) = 2$. Moreover, since $\crex(\tx,\tX) = 0$ we have $\mld(\tx,\tX)>1$. Combining these together, we have $\mld(\tx, \tX) = 2$. Thus \eqref{eq:nv-mld-cover} follows again from Theorem \ref{thm:ODP-gap}.

\begin{que}\label{que:vol-list}
Let $\hVol_3$ denote the set of local volumes of all klt threefold singularities $x\in X$. By \cite{XZ24} (see also \cite{Zhu24, LMS23}) we know that $0$ is the only accumulation point of $\hVol_3$. Moreover, Theorem \ref{thm:nv-3fold} implies that if $\hvol(x,X)\in \hVol_3 \cap [9, 27]$ then $x\in X$ is either a quotient singularity of order at most $3$ or a hypersurface singularity of type $cA_{\leq 2}$.
 From Example \ref{expl:ADE} we have the following containment
\[
 \hVol_3 \cap [9, 27] \supset \left\{9, \tfrac{2048}{225}, \tfrac{250}{27}, \tfrac{343}{36}, 6\sqrt{3}, \tfrac{32}{3}, \tfrac{27}{2}, \tfrac{125}{9}, 16, 27\right\}.
\]
Is this containment an equality?
\end{que}

\begin{expl}\label{expl:ADE}
\begin{enumerate}
    \item If $x\in X$ is an $A_k$-singularity, that is, locally analytically given by $x_1 x_2 + x_3^2 + x_4^{k+1} = 0$, then its local volume is $16$ when $k=1$, $\frac{125}{9}$ when $k=2$, and $\frac{27}{2}$ when $k\geq 3$. See \cite[Section 5]{Li18}, \cite[Example 4.7]{LL19} and \cite[Example 7.1.2]{LX20}.
\item If $x\in X$ is a $cA_1$-singularity but not an $A_k$-singularity, then $x\in X$ has to be a transversal $A_1$-singularity with $\hvol(x,X) = \frac{27}{2}$.
\item If $x\in X$ is defined by $x_1 x_2 + x_3^3 + x_4^k=0$ for $3\leq k\leq 6$, then by \cite{CS15} and \cite{LST25} we have $\hvol(x,X) = \frac{4(3+k)^3}{9k^2}$. Thus we get values $\frac{32}{3}, \frac{343}{36}, \frac{2048}{225}, 9$ for $k = 3,4,5,6$. Note that  $k=3,4,5$ correspond to $D_4$, $E_6$, and $E_8$-singularities.
\item If $x\in X$ is a $D_k$-singularity with $k\geq 5$, then we have local equation $x_1x_2 + x_3^2 x_4 + x_4^{k-1} = 0$. Then by \cite[Appendix, Example 4.1]{LX18} we know that its local volume is computed by the monomial valuation $v_{\bfw}|_{K(X)}$ with weight $\bfw=(1, 1, \sqrt{3}-1, 4-2\sqrt{3})$ whose K-semistable Fano cone degeneration is precisely the $D_\infty$-singularity $x_1x_2 + x_3^2 x_4 = 0$. Thus we have $\hvol(x, X) = 6\sqrt{3}$ which is the same as the local volume of a $D_\infty$-singularity.
\item If $x\in X$ is an $E_7$-singularity, then we have local equation $x_1x_2 + x_3^3 + x_3 x_4^3 =0$. By \cite[Section 8]{Li18} and \cite[Example 7.1.3]{LX20} we know that $\hvol(x, X) = \frac{250}{27}$.
\end{enumerate}

\end{expl}

\begin{thm}\label{thm:nv-3fold}
Let $x\in X$ be a klt threefold singularity. Then $\hvol(x,X)\geq 9$ if and only if  $x\in X$ is either a hypersurface singularity of type $cA_{\leq 2}$, or a cyclic quotient singularity of type $\frac{1}{2}(1,1,1)$, $\frac{1}{3}(1,1,0)$, $\frac{1}{3}(1,1,1)$, or $\frac{1}{3}(1,1,2)$. 
\end{thm}

\begin{thm}\label{thm:nv-can}
Let $x\in X$ be a Gorenstein canonical non-hypersurface threefold singularity. Then $\hvol(x,X)\leq 9$, and equality holds if and only if $x\in X$ is a quotient singularity  of type $\frac{1}{3}(1,1,1)$. 
\end{thm}

post_theorem_intro_text:
Theorem \ref{thm:nv-can} can be thought of as a refinement of the ODP Gap Theorem for threefolds in \cite{LX19} that any non-smooth threefold singularity $x\in X$ satisfies $\hvol(x,X)\leq 16$, and equality holds if and only if $x\in X$ is an $A_1$-singularity.

As a consequence, we have the following characterization of threefold singularities with local volumes at least $9$. See Example \ref{expl:ADE} for many examples of such singularities and their local volumes, and Question \ref{que:vol-list} for a conjectural list of all possible local volumes that are at least $9$.

\begin{thm}\label{thm:nv-3fold}
Let $x\in X$ be a klt threefold singularity. Then $\hvol(x,X)\geq 9$ if and only if  $x\in X$ is either a hypersurface singularity of type $cA_{\leq 2}$, or a cyclic quotient singularity of type $\frac{1}{2}(1,1,1)$, $\frac{1}{3}(1,1,0)$, $\frac{1}{3}(1,1,1)$, or $\frac{1}{3}(1,1,2)$. 
\end{thm}

The above results have some notable applications to the study of K-moduli of Fano threefolds through the local-to-global volume comparison \cite{Liu18}.

\begin{thm}\label{thm:K-moduli}
Let $X$ be a K-semistable $\mathbb{Q}$-Fano threefold with volume $(-K_X)^3 = V$.
\begin{enumerate}
    \item If $V\geq 26$, then $X$ has only $cA_1$-singularities or  cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
    \item If $V\geq 22$, then $X$ has only $cA_1$-singularities, isolated $cA_2$-singularities, $D_\infty$-singularities, or cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
    \item If $V\geq 11$, then any non-Gorenstein singularity $x\in X$ is a cyclic quotient of a (possibly smooth) hypersurface singularity of type $cA_{\leq 2}$.
\end{enumerate}
If in addition $X$ is $\mathbb{Q}$-Gorenstein smoothable, then it does not admit cyclic quotient singularities of type $\frac{1}{2}(1,1,1)$.
\end{thm}

Theorem \ref{thm:K-moduli} can be viewed as a strengthening of a result proven in \cite{LX19, LZ24} stating that $X$ is Gorenstein canonical if $V\geq 20$. Such  restrictions on singularities played a key role in the description of K-moduli spaces for various families of Fano varieties via the moduli continuity method, see e.g.\ \cite{MM93, OSS16, SS17, LX19, Liu22, ADL21, LZ24, Zha24}. We expect Theorem \ref{thm:K-moduli} to be useful in the future study of K-moduli spaces for Fano threefolds. Specifically, according to \cite{ACC+}, there are precisely $79$ out of $105$ families of smooth Fano threefolds that contain K-semistable members, i.e.\ whose K-moduli spaces are non-empty. Among these $79$ families, Theorem \ref{thm:K-moduli} (1), (2), and (3) can be applied to $35$, $46$, and $68$ families, respectively, where   $3$, $9$, and $28$ families respectively have unknown K-moduli compactifications to the author's knowledge. See Remark \ref{rem:K-mod} for a list of these families.

As another application, we establish a sharp comparison between the local volume and the minimal log discrepancy (mld) for klt threefold singularities, answering  \cite[Question 6.16]{LLX18} affirmatively in dimension $3$. 

\begin{thm}\label{thm:nv-mld}
Let $x\in X$ be a klt threefold  singularity. Then 
\begin{equation}\label{eq:nv-mld}
    \hvol(x,X) \leq 9 \cdot \mathrm{mld}(x,X).
\end{equation}
Moreover, equality holds if and only if $x\in X$ is a cyclic quotient singularity of type $\frac{1}{r}(1,1,1)$ for some $r\in \bZ_{>0}$.
\end{thm}

Note that a weaker inequality $\hvol(x,X)< n^n\cdot \mathrm{mld}(x,X)$ was proven in any dimension $n$ in \cite[Theorem 6.13]{LLX18}.

Let us briefly explain the strategy of the proof of Theorems \ref{thm:nv-can} and \ref{thm:nv-3fold}, which is similar to \cite{LX19} but technically more involved. For hypersurface singularities, we use local equations and monomial valuations on the ambient space to get upper bounds for its local volumes.  Suppose $x\in X$ is a Gorenstein canonical non-hypersurface threefold singularity. Then the hope is to either find a good divisor with small normalized volume or to bound local volumes on a crepant birational model. This is done by running a suitable MMP on the terminalization to contract crepant exceptional divisors one by one. Compared to \cite{LX19}, the new difficulty lies in the fact that in order to achieve the local volume bound $9$ ($=$ local volume of a transversal $A_2$-singularity), we need to analyze the behavior of contractions of two exceptional divisors, as contracting only one divisor may create a transversal $A_1$-singularity whose local volume is $\frac{27}{2}$, which is not strong enough for our estimate. Then we reduce to the case when there are at most two crepant exceptional divisors over $x\in X$ and apply the detailed analysis  from \cite{Lau77, Rei76, Rei80, Rei94}. In some cases we are only able to get a good crepant birational model after an \'etale base change using Artin approximation theorem (see Section \ref{sec:Artin}), a result that is of independent interest.

\subsection*{Acknowledgements} The author would like to thank Anne-Sophie Kaloghiros, J\'anos Koll\'ar, Andrea Petracci, Jakub Witaszek, Chenyang Xu, and Junyan Zhao for helpful discussions and comments. The author is partially supported by NSF CAREER Grant DMS-2237139 and an AT\&T Research Fellowship from Northwestern University.

theorem.content:
[{\cite[Theorem~0.1]{AFKKZ13}}] \label{FIT.th}
Let \( X \) be an affine variety. Then the following are equivalent:  
\begin{enumerate}
  \item \( X \) is flexible;  
  \item \( \SAut(X) \) acts transitively on the smooth locus \( X^\mathrm{reg} \);  
  \item if \( \dim X \ge 2 \), \( \SAut(X) \) acts infinitely transitively on \( X^\mathrm{reg} \).
\end{enumerate}

full_context:
The geometry of automorphism groups has long offered a revealing lens through which to view the structure of algebraic varieties. In the affine setting, varieties that admit an abundance of unipotent transformations exhibit particularly rich behaviour. Among them, the \emph{flexible varieties} form a distinguished class: they are those for which every tangent direction at a smooth point arises from an additive group action. Such varieties can be regarded as algebraically homogeneous in the strongest possible sense.

Throughout we work over an algebraically closed field \( \mathbb K \) of characteristic zero. A \emph{variety} means an integral separated scheme of finite type over \( \mathbb K \). We write \( \bb{G}_\mathrm{a} = (\mathbb K, +) \) for the one-dimensional additive algebraic group. For a variety \( X \), a point \( x \in X \) is said to be \emph{flexible} if the tangent space \( T_xX \) is spanned by tangent vectors to orbits of effective \( \bb{G}_\mathrm{a} \)-actions on \( X \); the variety \( X \) is \emph{flexible} if every smooth point is flexible. Denote by \( \operatorname{SAut}(X) \subseteq \operatorname{Aut}(X) \) the subgroup generated by all one-parameter unipotent subgroups of automorphisms of \( X \). A fundamental theorem of Arzhantsev, Flenner, Kaliman, Kutzschebauch, and Zaidenberg~\cite{AFKKZ13} shows that flexibility is equivalent to a strong homogeneity property of this group:

Throughout we work over an algebraically closed field \( \bb K \) of characteristic zero. A \emph{variety} means an integral separated scheme of finite type over \( \bb K \). We write \( \Ga = (\bb K, +) \) for the one-dimensional additive algebraic group. For a variety \( X \), a point \( x \in X \) is said to be \emph{flexible} if the tangent space \( T_xX \) is spanned by tangent vectors to orbits of effective \( \Ga \)-actions on \( X \); the variety \( X \) is \emph{flexible} if every smooth point is flexible. Denote by \( \operatorname{SAut}(X) \subseteq \operatorname{Aut}(X) \) the subgroup generated by all one-parameter unipotent subgroups of automorphisms of \( X \). A fundamental theorem of Arzhantsev, Flenner, Kaliman, Kutzschebauch, and Zaidenberg~\cite{AFKKZ13} shows that flexibility is equivalent to a strong homogeneity property of this group:

This theorem---widely regarded as a cornerstone in the development of the theory---places the notion of flexibility at the intersection of algebraic transformation groups and birational geometry. It identifies a distinguished class of affine varieties whose automorphism groups behave much like those of homogeneous spaces.

Within this evolution, a natural and historically significant next step concerns the class of \emph{smooth complete intersections of two quadrics}. These varieties occupy a central place in algebraic geometry, appearing in the early classification of Fano manifolds and re-emerging in modern studies of birational rigidity, derived categories, and moduli (\cite{Re72, HT21, HT25}). For \( n \ge 3 \), such a variety 
\begin{equation*}
X = Q_1 \cap Q_2 \subseteq \bb{P}^{n + 2}
\end{equation*}
is a Fano variety of Picard number~1 and index~\( n-1 \); in the case \( n = 2 \), one recovers the del Pezzo surface of degree~4. Despite their classical nature, the behaviour of their affine cones under unipotent automorphisms remained open. The present paper closes this gap by proving that the affine cones over all such varieties are flexible, thereby extending the known frontier of flexibility to one of the most fundamental families in Fano geometry.

\begin{proof}
For each $i \in I$ choose an action $\alpha_i$ on $X$ induced by $U_i$ and denote by $H_i$ the corresponding subgroup of $\Aut(X)$. Let $G$ be the subgroup of $\Aut(X)$ generated by all $H_i$. Then $G$ acts on $X$ transitively, hence $X$ is smooth. Moreover, $G \subseteq \SAut(X)$, so $X$ is flexible by Theorem~\ref{FIT.th}.
\end{proof}

\begin{prop} \label{CF.pr}
Let $X$ be an affine variety of dimension at least one. Then $X$ is flexible if and only if there exists a transversal covering of $X^\reg$ by cylinders, which are principal in $X$.
\end{prop}

Assume that $X$ is flexible. By Theorem~\ref{FIT.th} the group $\SAut(X)$ acts transitively on $X^\reg$, hence there exists an effective $\Ga$-action on $X$. It follows that there exists a principal \linebreak
$1$-cylinder $U = \bb{D}_X(h)$ in $X$. Without loss of generality we may assume that $U \subseteq X^\reg$, see \cite[Section~1.1]{KPZ13}. Consider a collection
$$
\cal{U} = \{g U\}_{g \in \SAut(X)}
$$
of principal $1$-cylinders in $X$. Clearly, $\cal{U}$ covers $X^\reg$. Consider a nonempty subset $S \subseteq X$ which is invariant with respect to $\cal{U}$. There exists $U' \in \cal{U}$ such that $S \cap U' \ne \emptyset$. It follows that there exists an $\bb{A}^1$-fiber $A$ of $U$ such that $A \subseteq S$. Consider two distinct points $p, x \in A$ and let $y \in X^\reg$ be an arbitrary point distinct from $p$. By Theorem~\ref{FIT.th} the group $\SAut(X)$ acts infinitely transitively on $X^\reg$, hence there exists $g \in \SAut(X)$ such that $g \cdot x = y$ and $g \cdot p = p$. Then $p \in S \cap (g U')$ and the points $p, y$ belong to the same $\bb{A}^1$-fiber of the cylinder $g U'$. It follows that $y \in S$. Therefore, $S = X^\reg$ and $\cal{U}$ is transversal.

\begin{rema}
One can also deduce flexibility of the complement $Y = \bb{P}^n \setminus X$ of a smooth quadric $X \subseteq \bb{P}^n$, $n \ge 2$ from the following observation. A semisimple algebraic group $G = \SO{n + 1}$ acts on $Y$ transitively. By~\cite[Lemma~1.1]{Po11} the group $G$ is generated by its $\Ga$-subgroups. Therefore, $Y$ is flexible by Theorem~\ref{FIT.th}.
\end{rema}

\begin{coro} \label{EACX.co}
Consider an affine space $\bb{A}^n$, $n \ge 6$ with coordinates $x_1, \dots, x_n$. Let $X \subseteq \bb{A}^n$ be an affine variety given by equations
$$
x_1^2 + \ldots + x_n^2 = 0 \insertText{and}
\lambda_1 x_1^2 + \ldots + \lambda_n x_n^2 = 0,
$$
where $\lambda_1, \dots, \lambda_n \in \bb{K}$ are pairwise distinct. Then $X$ is flexible.
\end{coro}

