The post-theorem introduction explains that \cite{HooshKoh2025} used Cayley graph arguments to constrain the possible orders of $G$, reducing the classification to examining about twenty concrete groups. It then sketches a streamlined proof of the \emph{``only if''} direction, broken into four independent steps:
\begin{enumerate}[label=(\arabic*)]
  \item \emph{Analysis of groups with ``large'' proper subgroups}. We first prove the following lemma.

\begin{lemma}
\label{lemma:main}
Let $H$ be a proper subgroup of a finite group $G$ with $\lvert H\rvert \ge 5$.
Choose $h_0\in H$ with $h_0\neq e$ and choose $g\in G\setminus H$.
Let $h_1$ be an element of $H$ not in the set
$\{e,h_0,h_0^{-1}\}$,
and set
\[
H'= H\setminus\{e,h_0\}.
\]
Define
\begin{equation}\label{equ:subset-not-factor}
A= H'\cup\{g,h_1g\}.
\end{equation}
Then $\lvert A\rvert = \lvert H\rvert$ and $A$ is not a left factor of $G$.
\end{lemma}

  \item \emph{Groups of even order containing elements of odd order}. We next prove the following lemma.

\begin{lemma}
\label{lemma:small subset}
\begin{enumerate}[label=\textup{(\roman*)}]\!
    \item Let $G$ be a group of even order, and let $a\in G$, $a\neq e$. 
    The subset $\{e,a\}$ is a factor of $G$ if and only if the order of $a$ is even.
    \item Let $G$ be an elementary abelian $2$-group.
    Every subset of size $4$ is a factor of $G$.
    \item\,Let $G$ be an elementary abelian $3$-group.
    Every subset of size $3$ is a factor of $G$.
\end{enumerate}
\end{lemma}

  \item \emph{Investigation of groups of order $8$}. We then prove the following lemma.

\begin{lemma}
\label{lemma:groups of order 8}
Let $G$ be a group of order $8$, and let $a,b\in G$ be two elements of order $4$ with $\langle a\rangle\neq\langle b\rangle$.
Then
\[
  A = \{a,a^2,a^3,b\}
\]
is not a left factor of $G$.
\end{lemma}

  \item \emph{A direct check} for the three remaining groups: $D_4$, $C_8$, and $C_9$.
\end{enumerate}
It further indicates the paper proceeds by proving these lemmas next and then completing the proof later.

