\label{thm:mainPGL}
For $d \in (\mathbb{Z}/n\mathbb{Z})^*$ and  $k\le 2(g-1)(n-1) + 2$,
the cohomology group $H^k(\M_B^{\PGL}(\C_g, n,d); \mathbb{Q})$ is isomorphic to the degree $k$ part of the graded vector space
\begin{equation}\label{eq: PGLresult}
H^*\big(\M_g; \textstyle \bigwedge^\bullet (V_g \otimes \tW_n)) \otimes \Sym^\bullet (V_\circ \otimes \tW_n).
\end{equation}

ref_dict.subsec: PGLstablecohomology:
\begin{proof}
    We note that
    $$M_B(S_g,1,0) = \Hom(\pi_1(S_g), \CC^*) = \Hom(H_1(S_g; \ZZ); \CC^*) \cong (\CC^*)^{2g}$$
    with $\Mod_{g,1}$ acting through the symplectic representation on $H_1(S_g; \ZZ).$
\end{proof}

\subsection{Stable rational cohomology of \texorpdfstring{$\M^{\PGL}_{B}(\C_g, n,d)$}{}}\label{subsec: PGLstablecohomology}
We relate $H^*(\M_B^{\PGL}(\C_g,n,d); \QQ)$ to the cohomology of $\M_g$ with coefficients in exterior powers of direct sums of copies of the symplectic local system. To simplify the notation of the relevant local systems on $\M_g$, recall the conventions \eqref{eq: grading} from the introduction:
\begin{equation}\label{eq: grading-restated}
V_\circ := \QQ \oplus \QQ[-2], \quad \quad W_n := \QQ \oplus \QQ[-2] \oplus \cdots \oplus \QQ[2-2n], \quad \quad \quad  \widetilde{W}_n := W_n / \QQ. \end{equation} 

\begin{proof}[Proof of Theorem \ref{thm:mainPGL}]
    From Theorem \ref{thm:E2PGL} we have
    \begin{equation}\label{eq:lerayss}
    H^k(M^{\PGL}_B(\C_g, n,d);\QQ)\cong \bigoplus\limits_{p+q=k} H^p(\M_g;H^q(\M^{\PGL}_{B}(S_g,n,d);\QQ)).
\end{equation}
By Proposition \ref{prop: free generation} we have
\[ H^*(\M^{\PGL}_B(S_g,n,d); \QQ) \cong \wedge^\bullet (\oplus_{j=2}^n V_{1,j}) \otimes \Sym^\bullet(\oplus_{j=2}^n V_{0,j} \oplus V_{2,j})\]
in degrees $\le 2(g-1)(n-1) + 2$.
Using the notation \eqref{eq: grading-restated} and the description of the $\Mod_g$ action in Corollary \ref{cor: monodromy action}, we can rewrite the subspaces $V_{i,j}$ of $H^*(\M_B^{\PGL}(S_g,n,d); \QQ)$ as the following graded modules, where $V_g=H^1(S_g;\QQ)$, as in \eqref{eq:Vg}, in degree 1:
\begin{equation*}
    \oplus_{j=2}^n V_{1,j}=V_g \otimes \widetilde{W}_n, \quad \oplus_{j=2}^n V_{0,j} \oplus V_{2,j}=V_\circ \otimes \widetilde{W}_n.
\end{equation*}
Hence we conclude that in this range
\[ H^*(\M_B^{\PGL}(\C_g,n,d); \QQ)
= H^*\big(\M_g, 
\wedge^\bullet (V_g \otimes \widetilde{W}_n)\big)
\otimes \Sym^\bullet(V_\circ \otimes \widetilde{W}_n).
\qedhere \]
\end{proof}

