ref_dict.cor:stablePGL:
\begin{corollary} \label{cor:stablePGL}
For $k \leq \frac{2g-2}{3}$, the group $H^k(\M_B^{\PGL}(\C_g, n,d); \QQ)$ does not depend on $g$ and vanishes if $k$ is odd.  If, in addition, $k \le 2n-1$ then this group is independent of $n$.
\end{corollary}

ref_dict.defn: relative total PGL:
\begin{definition}\label{defn: relative total PGL}
	For $d$ coprime to $n$, the \emph{universal degree $d$ $\PGL$-character variety} is 
	\begin{equation*}
		\M_{B}^{\PGL}(\C_g, n, d) \coloneqq \mc T_g \times_{\Mod_g} \M_{B}^{\PGL}(S_g,n,d).
	\end{equation*}
\end{definition}

ref_dict.thm: splitting:
\begin{theorem} \label{thm: splitting}
Let $d \in (\ZZ/n\ZZ)^*$ and let $\pi \colon \M_B^{\PGL}(\C_g, n,d) \to \M_g$ be the projection from the universal degree $d$ $\PGL$-character variety. Then $R\pi_* \QQ \cong \oplus_i R^i\pi_* \QQ[-i]$ in the bounded derived category of constructible $\QQ$-sheaves on $\M_g$. In particular, the Leray spectral sequence
    $$E_2^{pq} = H^p(\M_g, R^q\pi_* \QQ) \implies H^{p+q}(\M_B^{\PGL}(\M_g, n,d); \QQ)$$
    degenerates at $E_2$.
\end{theorem}

