\end{definition}

ref_dict.key lemma:
\begin{lemma}[Key Lemma]\label{key lemma}
		Let $\C$ be an $\widehat{A}$-valued $\q$-characteristic class. Then equality
		\begin{equation}\label{key} \C = \C_0\circ\exp\left(\sum_{n\geq1}\C_n(x_1)\cdot\delta_{\mathsf{q},n}\right)
		\end{equation}
		holds whenever both sides are applied to any given homogeneous polynomial in $R$. If furthermore $\C$ is a $\Q$-algebra homomorphism, then equality \eqref{key} holds in general.
		\begin{proof}
			Let us prove that \eqref{key} holds when applied to the element $x_k$. The left-hand side is
			$$\C(x_k) = \sum_{n \geq 0} \C_n(x_k) = \C_0(x_k) + \sum_{n \geq 1} q_{n,k} \C_n(x_1).$$

			As for the right-hand side, we notice that $\delta_{\mathsf{q},n}(x_k) = q_{n,k} \in \Q$, so that $\delta_{\mathsf{q},m}(\delta_{\mathsf{q},n}(x_k)) = 0$ for all $m$ and $n$. When we apply the automorphism to $x_k$, only the constant and the linear term survive and we obtain
			$$\exp\left(\sum_{n\geq 1} \C_n(x_1) \cdot \delta_{\mathsf{q},n} \right)(x_k) = x_k + \sum_{n \geq 1} q_{n,k} \C_n(x_1).$$
			After applying $\C_0$, this coincides with the left-hand side.

			By multiplicativity of $\C$, Equation \eqref{key} holds for each monomial, and since the restriction of $\C$ on each graded component of $R$ is $\Q$-linear, it also holds for every homogeneous polynomial. The final claim is clear.
		\end{proof}
	\end{lemma}

ref_dict.example:2:
\begin{example}[Schur bundles of size $2$]\label{example:2}
		Let us compute $\ch(\Schur^{\alpha}E)$ when $|\alpha|=2$. We have only two cases, namely the symmetric power $\Schur^2E$ and the exterior power $\extp^2 E$, corresponding to $\alpha=(1,1)$. 
		\begin{description}
			\item[$\alpha=(2)$] it is easy to see that the only non-zero derivatives of $\schur_2$ are
			\[ \D_a(\schur_2)=\schur_1+2^{a-1}\implies \rk(\D_a(\schur_2))=r+2^{a-1} \qquad\mbox{ and }\qquad\D_a\D_b(\schur_2)=1. \]
			Then the first values of $\ch_n(\Schur^2 E)$ are:
			\begin{align*}
				\ch_1(\Schur^{2}E) = & \, (r+1)\ch_1(E), \\
				\ch_2(\Schur^{2}E) = & \, (r+2)\ch_2(E)+\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{2}E) = & \, (r+4)\ch_3(E)+\ch_2(E)\ch_1(E), \\
				\ch_4(\Schur^{2}E) = & \, (r+8)\ch_4(E)+\ch_3(E)\ch_1(E)+\frac{\ch_2(E)^2}{2}, \dots
			\end{align*}

			\item[$\alpha=(1,1)$] it is easy to see that the only non-zero derivatives of $\schur_{(1,1)}$ are
			\[ \D_a(\schur_{(1,1)})=\schur_1-2^{a-1}\implies \rk(\D_a(\schur_2))=r-2^{a-1}\qquad\mbox{ and }\qquad\D_a\D_b(\schur_{(1,1)})=1. \]
			Then the first values of $\ch_n(\extp^2 E)$ are:
			\begin{align*}
				\ch_1(\extp^2E) = & \, (r-1)\ch_1(E), \\
				\ch_2(\extp^2E) = & \, (r-2)\ch_2(E)+\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\extp^2E) = & \, (r-4)\ch_3(E)+\ch_2(E)\ch_1(E), \\
				\ch_4(\extp^2E) = & \, (r-8)\ch_4(E)+\ch_3(E)\ch_1(E)+\frac{\ch_2(E)^2}{2}, \dots
			\end{align*}
		\end{description}
	\end{example}

