\begin{prop}\label{nondegvemst}
Let $\blam\in\mathscr{P}_{\ell,n}$ and $\s,\t\in\te{Std}(\blam)$. Suppose that either $n(\s)=n$ or $n(\t)=n$. Then
$$\ve_n(\fm_{\s\t})=\begin{cases} \bigg(\prod\limits_{i=l(\t,n)+1}^{\ell}(-Q_i)\bigg)\fm_{\s_{\downarrow\leq (n-1)}\t_{\downarrow\leq (n-1)}}, &\text{if\ \ $n(\s)=n(\t),$}\\
0, &\text{if\ \ $n(\s)\neq n(\t).$}\end{cases}$$
\end{prop}

\begin{prop}\label{nondegvemst2}
Let $\blam\in\mathscr{P}_{\ell,n}$ and $\s,\t\in\te{Std}(\blam)$. Suppose that $n(\s)\neq n\neq n(\t)$. Then
$$\ve_n(\fm_{\s\t})=\begin{cases} q^{n-n(\t)}\bigg(\prod\limits_{i=l(\t,n)+1}^{\ell}(-Q_i)\bigg)\fm_{\s_{\downarrow\leq (n-1)}\t_{\downarrow\leq (n-1)}}, &\text{if\ \,$n(\s)=n(\t),$}\\
0, &\text{if\ \,$n(\s)\neq n(\t).$}\end{cases}$$
\end{prop}

\smallskip\noindent
{\it Case 2.} Suppose $n(\s)\neq n=n(\t)$. Then $d(\s)\neq d(\s_{\downarrow\leq (n-1)})$ and $d(\t)=d(\t_{\downarrow\leq (n-1)}).$
