theorem.content:
\label{thm:main}
    Let $r \in \{2,3,4\}$, let $\W_{\underline a}$ be the fully reduced web basis for $\mathsf{Inv}(V_q^{\underline a})$, and let $\underline{C}$ be a clasp sequence for $\underline{a}$ with weights $\lambda_1,\ldots,\lambda_m$. Then the following are equivalent for $[W]_q \in \W_{\underline a}$:
    \begin{enumerate}
        \item $[W]_q\notin \ker\pi_{\underline C}$,
        \item $W$ is non-convex (see \Cref{def:nonconvex}),
        \item $W$ has no trips that start and end in the same clasp.
    \end{enumerate}
    Moreover, the clasped web invariants for these webs $W$ form a basis for $\mathsf{Inv}\left(\bigotimes_{i=1}^m V_q(\lambda_i)\right)$.

ref_dict.def:latticeword:
\begin{definition}\label{def:latticeword}
    Given a sequence of sorted clasps $\underline C = (\underline c_1,\dots, \underline c_m)$, a lattice word $L$ has no \emph{$\underline C$-descents} if $L = L_1\cdots L_m$ with $\type(L_i) = \underline c_i, \forall i$ and each $L_i$ has no descents.
    The set of all lattice words with no $\underline C$-descents is denoted $\mathsf L(\underline C)$, and the set of all balanced lattice words with no $\underline C$-descents is denoted $\BL(\underline C)$.
\end{definition}

