ref_dict.thm homeo:
\begin{theorem} \label{thm homeo}
The map 
\begin{equation*}
 \Psi_{\ge0}\colon Y_{\ge 0}\rightarrow X(\Sigma)_{\ge0}
 \quad ; \quad
 gB \mapsto [\Delta_{\varpi_1}(g),\ldots,\Delta_{\varpi_{\rkg}}(g);\qp{1}(g),\ldots,\qp{n}(g)]
\end{equation*}
is a homeomorphism satisfying
\begin{equation*}
\Psi_{\ge 0}(\RY{K}{J;>0}) = \Xp{K,J}
\end{equation*}
for $K\subseteq J \subseteq I$.
\end{theorem}

ref_dict.prop description of YKJ:
\begin{proposition}\label{prop description of YKJ}
For $K\subseteq J\subseteq I$, we have
\begin{align*}
 \RY{K}{J}
 = \left\{ x\dot{w}_J B\in G/B \ \left| \ x \in (U_J)^{e_J} \text{ and }
 \begin{cases}
 \Delta_{\varpi_i}(x\dot{w}_J)=0 \quad \text{if $i\in K$}, \\
 \Delta_{\varpi_i}(x\dot{w}_J)\ne0 \quad \text{if $i\in I-K$}
 \end{cases}
 \right.
 \right\},
\end{align*}
where $(U_J)^{e_J}=U_J\cap Z_{G_J}(e_J)$.
\end{proposition}

ref_dict.thm LR in our setting:
\begin{theorem}\label{thm LR in our setting}
The map 
\begin{align*}
 U^e_{\ge0} \rightarrow \R^{I}_{\ge0}
 \quad ; \quad
 x \mapsto 
 (\Delta_{\varpi_1}(x\dot{w}_0), \ldots, \Delta_{\varpi_{\rkg}}(x\dot{w}_0))
\end{align*}
is a homeomorphism.
 \end{theorem}

ref_dict.prop restrict:
\begin{proposition}\label{prop restrict}
The morphism $\Psi \colon Y\to X(\fan)$ restricts to a continuous map
\begin{equation*}
\Psi_{\ge 0} \colon Y_{\ge 0}\to X(\fan)_{\ge 0}
\end{equation*}
which sends $\RY{K}{J;>0}$ to $\Xp{K,J}$ for $K\subseteq J \subseteq  I$.
\end{proposition}

ref_dict.prop Delta is nonnegative:
\begin{proposition}\label{prop Delta is nonnegative}
For $x\in U_{\ge0}$ and $w\in W$, we have
\begin{equation*}
 \Delta_{\varpi_i}(x\dot{w}) \ge0
 \qquad (i\in I),
\end{equation*}
where $\Delta_{\varpi_i}$ is the function defined in \eqref{eq def of Delta}.
\end{proposition}

ref_dict.prop description for R KI>0 2:
\begin{proposition}\label{prop description for R KI>0 2}
Let $K\subseteq J\subseteq I$. Then, we have 
\begin{equation*}
\RY{K}{J;>0}=\left\{x\dot{w}_JB \ \left| \ 
\begin{matrix}
\text{
\rm $x\in (U_J)^{e_J}_{\ge0}$ and}
~\begin{cases}\Delta_{\varpi_i}(x\dot{w}_J)=0\quad\text{if}\quad i\in K\\
\Delta_{\varpi_i}(x\dot{w}_J)> 0\quad\text{if}\quad i\in J-K \\
\Delta_{\varpi_i}(x\dot{w}_J)=1 \quad\text{if}\quad i\in I-J
