ref_dict.prop LR and our:
\begin{proposition}\label{prop LR and our}
Let $i\in I$. For all $x\in U^e_{\ge0}$, we have
\begin{align*}
 \Delta_i([\dot{w}_0^{-1}x\dot{w}_0]) = (\Delta_{\varpi_i}(x\dot{w}_0))^{m_i}.
\end{align*}
\end{proposition}

ref_dict.thm main:
\begin{theorem} \label{thm main}
    The totally nonnegative part of the Peterson variety is homeomorphic to the strongly dominant weight polytope as a cell-decomposed space. In particular, it is a regular CW-complex, which is homeomorphic to a cube.
\end{theorem}

ref_dict.prop nonnengative stratum parametrizatio:
\begin{proposition}\label{prop nonnengative stratum parametrization}
For $K\subseteq J\subseteq I$, the map
\begin{align*}
 (\R^{I})_{K,J;>0} \rightarrow \Xp{K,J}
 \quad ; \quad 
 (x_1,\ldots,x_{\rkg}) \mapsto [x_1,\ldots,x_{\rkg}\hspace{2pt};\delta_1,\ldots,\delta_{\rkg}]
\end{align*} 
is a bijection, where $(\delta_1,\ldots,\delta_{\rkg})\in\R^{I}$ is the element given by
\begin{align*}
\begin{cases}
 \delta_i=0 \quad (i\in I-J) \\
 \delta_i=1 \quad (i\in J) .
\end{cases}
\end{align*}
\end{proposition}

