ref_dict.thm: main:
\begin{thm}\label{thm: main}
    Let $A$ be an abelian variety and let $C_1, \ldots, C_d$ be smooth projective geometrically irreducible curves such that $C(k) \ne \emptyset$. Then there exists an isomorphism
    \[
        \mathbb{Z}[1/r!]\otimes \frac{F^r(C_1\times \ldots C_d\times A)}{F^{r+1}(C_1\times \ldots C_d\times A)} \xrightarrow{\Z[1/r!]\otimes \Phi_r} \mathbb{Z}[1/r!]\otimes S_r(k; \underline{J_1}\times \cdots \times \underline{J_d}\times A).
    \]
\end{thm}

ref_dict.thm: vanishing:
\begin{thm}\label{thm: vanishing}
    For $r > \text{dim}(C_1\times\cdots \times C_d \times A)$, 
    \[
        F^r\ch_0(C_1\times\cdots \times C_d\times A)\otimes \Q = 0. 
    \]
\end{thm}

ref_dict.thm:main-theorem-intro:
\begin{lettertheorem}\label{thm:main-theorem-intro}
  Let $p>3$ be prime. Let $K$ be a $p$-adic field that is totally ramified over $\Q_p$. Let $E_1$ and $E_2$ be elliptic curves defined over $K$ with full $K$-rational 2-torsion and supersingular reduction. Then for any $n>0$, there exists a WR relation $\{P_1,P_2\}_{K/K}=0$ in $K(K;E_1,E_2)$ of signature $(n,n)$.
\end{lettertheorem}

ref_dict.def:signature-of-formal-point-mod-p:
\begin{definition}\label{def:signature-of-formal-point-mod-p}
  Let $K$ be a $p$-adic field with $e<p-1$. Let $E$ be an elliptic curve over $K$. The \emph{signature} of a class $[\a]\in\E(\m)/p$ is defined as
  \[
    \sS([\a]):=
    \begin{cases}
      \nu(\a) &\text{if}\; \a\not\equiv 0\spmod{p}\\
      +\infty &\text{otherwise}.
    \end{cases}
  \]
\end{definition}

ref_dict.prop:TateCv:
\begin{proposition}\label{prop:TateCv}
\begin{enumerate}
\item 
Let $a, b \in k^\times$ and $m>0$.
If $[a],  [b] \in E_q(k)[m]$, we have
\[ \langle [a], [b] \rangle 
= a^{-s_m([b])} \otimes \frac{1}{m}
= b^{-s_m([a])} \otimes \frac{1}{m}
= q^{-s_m([a])s_m([b])} \otimes \frac{1}{m^2}.
\]
\item
We have $E_q(k)_\Tor^\is = \{ [\zeta] \mid \zeta \in \mu(k) \}$.
\end{enumerate}
\end{proposition}

ref_dict.eg nef:
\begin{prop}\label{eg nef}
    Let us define a holomorphic vector bundle $F$ on $X$ by $F:=\pi^*E\oplus(\mathcal{O}(C)\otimes\pi^*\mathcal{O}(1))$. Then the following holds:\\
    $(1)$ $F$ is $\pi^*\mathcal{O}(1)$-semistable, but not stable.\\
    $(2)$ For any ample line bundle $H$ on $X$, $F$ is not $H$-semistable.\\
    $(3)$ $F$ satisfies the Bogomolov-Gieseker inequality.
\end{prop}

