\begin{thm}\label{lt HE}
     Let $X$ be a compact normal analytic variety with klt singularities. Suppose that $X$ admits a singular K\"{a}hler-Einstein metric $\omega$. Then, if a reflexive coherent sheaf $\mathcal{E}$ on $X$ is $\{\omega\}^{n-1}$-stable, then $\mathcal{E}$ admits an $\omega$-admissible HYM metric.
\end{thm}
\label{lt HE intro}
    Let $X$ be a compact normal analytic variety with klt singularities. Suppose that $X$ admits a singular K\"{a}hler-Einstein metric $\omega$. Then, if a reflexive sheaf $\mathcal{E}$ on $X$ is $\{\omega\}^{n-1}$-slope stable, then $\mathcal{E}$ admits an $\omega$-admissible Hermitian-Yang-Mills metric.

ref_dict.Thm:IGP:
\begin{theorem}\label{Thm:IGP}
    For any prime $p$ for which there exists an $\ell \in \cL$ with the Kronecker symbol $\legendre{\ell}{p}$ equal to $-1$, the group $\PSL_2(\F_{p^2})$ is a \emph{regular} Galois group over $\Q$.\footnote{Concretely, this implies that $\PSL_2(\F_{p^2})$ is realisable as a regular Galois group over $\Q$ for all $p<3,267,289$ (compared to the previous implied bound $p<1,009$).}
\end{theorem}

ref_dict.Thm:cover:
\begin{theorem}\label{Thm:cover}
    Let $K$ be the real quadratic field of discriminant $D$ with ring of integers $\mathfrak o$, and let $X/\Q$ be the Hilbert modular surface of discriminant $D$ and genus $g$ at base level. For every rational prime $p$ that is inert in $K$, there exists a Galois geometrically integral cover $Y_p \to X$ with group $\PSL_2(\mathfrak o/p)$.
\end{theorem}

ref_dict.Rem:shih:
\begin{remark}\label{Rem:shih}
Theorem~\ref{Thm:cover} should be compared to the analogous cover $X_0(p)\to X(1)$ of modular curves corresponding to the level structure $\Gamma_0(p)$.

In the one-dimensional setting, $X_0(p)$ has field of definition $\Q(\zeta_p)$ and one only obtains a $\PGL_2(\F_p)$-cover. Under certain congruence conditions, Atkin-Lehner involutions can be used to turn this into a $\PSL_2(\F_p)$-cover by what has become known as Shih's trick \cite{Shih}. In our situation such a trick is unnecessary.
\end{remark}

ref_dict.Thm:K3regular:
\begin{theorem}\label{Thm:K3regular}
     Let $X/\Q$ be the Hilbert modular surface of discriminant $D\in \cS_+$ (resp.\ $\cS_-$) and principal genus (resp.\ non-principal genus) at base level. Then the natural image of $X(\Q(t))$ in $X_{\bar \Q(t)}$ is non-thin.
\end{theorem}

ref_dict.Thm:K3:
\begin{theorem}\label{Thm:K3}
 Let $X/\Q$ be the Hilbert modular surface of discriminant $D$ and genus $g$ at base level. If $X$ is birational to a K3 surface, then $X(\Q)$ is not thin.
\end{theorem}

expanded_sketch:
To prove the main theorem, the authors “combin[e] Theorems \ref{Thm:K3} and \ref{Thm:cover}.” We first record the two inputs.

\begin{theorem}\label{Thm:cover}
    Let $K$ be the real quadratic field of discriminant $D$ with ring of integers $\mathfrak o$, and let $X/\Q$ be the Hilbert modular surface of discriminant $D$ and genus $g$ at base level. For every rational prime $p$ that is inert in $K$, there exists a Galois geometrically integral cover $Y_p \to X$ with group $\PSL_2(\mathfrak o/p)$.
\end{theorem}

\begin{theorem}\label{Thm:K3}
 Let $X/\Q$ be the Hilbert modular surface of discriminant $D$ and genus $g$ at base level. If $X$ is birational to a K3 surface, then $X(\Q)$ is not thin.
\end{theorem}

The first theorem supplies, for every rational prime $p$ inert in the relevant real quadratic field $K$, a Galois geometrically integral cover $Y_p \to X$ with group $\PSL_2(\mathfrak o/p)$. The second theorem provides the needed Hilbert irreducibility input on the Hilbert modular surface $X$: if $X$ is birational to a K3 surface then $X(\Q)$ is not thin (indeed they prove the stronger non-thinness statement over $\Q(t)$ in
\begin{theorem}\label{Thm:K3regular}
     Let $X/\Q$ be the Hilbert modular surface of discriminant $D\in \cS_+$ (resp.\ $\cS_-$) and principal genus (resp.\ non-principal genus) at base level. Then the natural image of $X(\Q(t))$ in $X_{\bar \Q(t)}$ is non-thin.
\end{theorem}
, yielding “an abundance of rational curves”).

For small $\ell$ with $\Q$-rational Hilbert modular surfaces (Elkies--Kumar), they “apply the classical Hilbert Irreducibility Theorem.” For the remaining listed primes $\ell$ where the surfaces are “not (uni)rational,” they instead “prove the theorem with the help of new versions of the Hilbert Irreducibility Theorem over non-unirational surfaces” by establishing that “the Hilbert Property holds” for the relevant low-discriminant surfaces via the “multiple fibration method.” Concretely, although $X$ already has many rational curves coming from boundary/embedded Shimura data, “specialising the cover $Y_p \to X$ to these rational curves does not produce surjective representations” to $\PSL_2(\F_{p^2})$; instead, those curves induce many genus $1$ fibrations on $X$, and this geometric feature “allows us to propagate these rational curves and obtain new ones for which the specialised representation instead does indeed surject,” with the propagation formalised by the multiple fibration method used in proving the theorem above.

