Then, there exists an explicit $K_{3,3}$-subdivision in $\Gkp$ if $\xi_{2,\kappa}\eta_{2,\kappa}\ne 0$, $5(\kappa^2-73\kappa+61)\ne 0$, 
and either of the following conditions holds. 
\begin{itemize}
\item[$\mathrm{(A)}$] 
$\left(\dfrac{\eta_{2,\kappa}}{p}\right)=1$ and 
$\left(\dfrac{5}{p}\right)
=\left(\dfrac{8\kappa-17+2\sqrt{\eta_{2,\kappa}}}{p}\right)
=\left(\dfrac{8\kappa-17-2\sqrt{\eta_{2,\kappa}}}{p}\right)=1$, or,
\\[0pt]
\item[$\mathrm{(B)}$] 
$\left(\dfrac{\eta_{2,\kappa}}{p}\right)=-1$ and $\left(\dfrac{5}{p}\right)=1$.
\end{itemize}
\end{theorem}
\begin{theorem}
\label{thm-n=(p-1)/2}
Let $\kappa\in\mathbb{Z}\setminus\{4\}$.
Then, there exists an explicit $K_{3,3}$-subdivision in $\Gkp$ if $\left(\frac{\kappa-4}{p}\right)=1$.
\end{theorem}
For each such $\kappa$ and for infinitely many primes $p$ (depending on $\kappa$) of natural density at least $1/2$, 
there exists an explicit $K_{3,3}$-subdivision in $\Gkp$.

\item[$(2)$] 
Moreover, the following theorem implies that for almost all $\kappa$, 
the natural density of primes $p$ for which $(1)$ holds is at least $13/16$.
\begin{theorem}
\label{thm:np density}
\begin{itemize}
\item[$(1)$]
For each $\kappa\in\mathbb{Z}\setminus\{4\}$ such that none of  
$\eta_{1,\kappa}$,  
$\eta_{2,\kappa}$, 
$5$, and $\kappa-4$
is a square in $\mathbb{Z}$, 
and that the ratio of any two of them is not a square in $\mathbb{Q}$, 
we have
\begin{equation}
\label{for:lower bound of Dnp}
\delta_{\kappa}\ge \frac{13}{16}.
\end{equation}
That is, $\Gkp$ contains a $K_{3,3}$-subdivision
for at least $81.25\%$ 
of primes $p$ asymptotically.
\item[$(2)$]
The natural density 
of $\kappa\in\mathbb{Z}\setminus\{4\}$ for which $(1)$ holds 
is equal to $1$.
\end{itemize}
\end{theorem}

\end{enumerate},

