\begin{example}\label{simple-ex}
Let $A$ be a finite simple group. The Schur multiplier $H_2(A;\mathbb{Z})$ has odd order precisely in the following cases:
\begin{itemize}
\item[(1).] Cyclic groups: $\mathbb{Z}/p$ with $p$ a prime number;
\item[(2).] Groups of Lie type (with $q=p^k$ for a prime number $p$ and positive $k$):
  \begin{itemize}
  \item Chevalley groups: 
     \begin{itemize} 
     \item[(Ch1).] linear groups $A_n(q)$ with $(n+1,q-1)$ odd and $(n, q)\neq (1, 4)$, $(2, 2)$, $(2, 4)$, $(3, 2)$; 
     \item[(Ch2).] orthogonal groups $B_n(q)$ with $n>1$, $q$ even and $(n, q)\neq (2, 2)$, $(3, 2)$; 
     \item[(Ch3).] symplectic groups $C_n(q)$ with $n>2$, $q$ even and $(n, q)\neq (3, 2)$; 
     \item[(Ch4).] orthogonal groups $D_n(q)$ with $n>3$, $(4,q^n-1)=1$ and $(n, q)\neq (4, 2)$; 
     \item[(Ch5).] $E_6(q)$; 
     \item[(Ch6).] $E_7(q)$ with $q$ even; 
     \item[(Ch7).] $E_8(q)$; 
     \item[(Ch8).] $F_4(q)$ with $q\neq 2$;
     \item[(Ch9).] $G_2(q)$ with $q\neq 4$;
     \end{itemize}
 \item Steinberg groups: 
   \begin{itemize} 
     \item[(S1).] unitary groups ${}^{2}A_n(q^2)$ with $n>1$, $(n+1,q+1)$ odd and $(n, q)\neq (3, 2)$, $(5,2)$; 
