\begin{lem}\label{lemma: p-adic nilpotent implies algebraic nilpotent}
Let $G \subset\GL_{n}(\Q_p)$ be a connected reductive algebraic subgroup and $H \subset G(\Q_p)$ be an abstract subgroup, dense in the Zariski topology. Suppose that $H$ is solvable of finite class as an abstract group. Then $G$ is a torus.
\end{lem}

