		$$ 1 \to I(N_r) \to \mathrm{MCG}(N_r) \to A \to 1,$$
		where $A \cong \z_2$ if $r \ne -3$, and $A \cong S_3$, the symmetric group of $3$ elements, if $r=-3$;
		\item when $r=8n+5$, $I(N_r)$ is isomorphic to $ \mathbb{Z}_{2\mathrm{gcd}(3,2n^2+3n+1)}\oplus \mathbb{Z}_{2\mathrm{gcd}(14,n+1)}$.
		\end{enumerate}

