full_context:
The mapping class group $\mathrm{MCG}(M)$ of a smooth manifold $M$ is the group of isotopy classes of orientation preserving self diffeomorphisms of $M$. It is an important object that encodes fundamental information about the symmetries of $M$. In this paper, we study the computation of $\mathrm{MCG}(M)$ for certain closed, simply-connected $6$-manifolds.

Although closed, simply-connected $6$-manifolds with torsion-free homology groups are classified by their algebraic-topological invariants due to the work of Wall \cite{Wa66} and Jupp \cite{Jup73}, there appears to be no systematic treatment of the computation of their mapping class groups. Particular interest has been devoted to manifolds admitting geometric structures. For instance, in \cite{KreSu} a class of $6$-manifolds with second Betti number $b_2=1$ is studied, including complete intersections of complex dimension $3$.

The present paper considers a class of $6$-manifolds with $b_2=2$, which includes natural compact K\"ahler manifolds such as projective bundles associated to rank $2$ holomorphic vector bundles over the complex projective plane $\mathbb P^2$. More precisely, in this paper we study the mapping class group of the total spaces of $S^2$-bundles over $\mathbb P^2$. A priori, the structure group of such bundles is the orientation-preserving diffeomorphism group of $S^2$. It was shown by Smale \cite{Sma59} that this group is homotopy equivalent to $SO(3)$. Consequently, such bundles arise as the sphere bundles of $3$-dimensional real vector bundles over $\mathbb P^2$.

Let $\mathrm{Vect}_{\mathbb R}^3(\mathbb P^2)$ denote the set of equivalence classes of $3$-dimensional real vector bundles over $\mathbb P^2$. In Proposition \ref{prop:real3} we show that the first Pontrjagin class induces a bijection 
$$p_1 \colon \mathrm{Vect}_{\mathbb R}^3(\mathbb P^2) \stackrel{\cong}{\longrightarrow}\{r\omega \in H^4(\mathbb{P}^2):r\in 4\mathbb{Z}+\{0,1\}\},$$
where $\omega$ is the cohomology fundamental class determined by the nature orientation of $\mathbb P^2$.

Let $I(M)$ be the Torelli group of $M$, which is the normal subgroup of $\mathrm{MCG}(M)$ consisting of diffeomorphisms that induce the identity on the cohomology groups of $M$.

\begin{prop}\label{prop:real3}
	 	The map 
		$$p_1 \colon  [\mathbb{P}^2, BSO(3)]\to \{rx^2\in H^4(\mathbb{P}^2) \ | \ r\in4\mathbb{Z}+\{0,1\}\}$$ 
	is a bijection and maps $\phi(\gamma_{k,l})$ to $(k^2-4l)x^2$.
	 \end{prop}

Let $I(M)$ be the Torelli group of $M$, which is the normal subgroup of $\m(M)$ consisting of diffeomorphisms that induce the identity on the cohomology groups of $M$.

The projective unitary group $PU(2)$ is isomorphic to the orthogonal group $SO(3)$; consequently, $S^2$-bundles may be identified with $\p^1$-bundles. Thus, the manifolds considered in this paper include many complex K\"ahler manifolds, such as projective bundle associated to rank $2$ holomorphic vector bundles over $\p^2$.

\begin{cor}\label{gmhs}
 Let $M_k=\{(x,y)\in \mathbb{P}^2\times\mathbb{P}^2 \ | \ \sum_i x^k_iy_i=0\}$, then
 \begin{enumerate}
 \item there is a short exact sequence 
 $$ 1 \to I(M_k) \to \m(M_k) \to A \to 1,$$
 where $A \cong \z_2$ if $k \ne 1$, and $A \cong S_3$ if $k=1$;
 \item when $k=2l+1$, $I(M_k)$ is isomorphic to $\mathbb{Z}_6\oplus \mathbb{Z}_{\mathrm{gcd}(28,l^2+l)}$. 
 \end{enumerate}
 \end{cor}

\begin{eg} \label{eg:1}
 Let $\zeta_k$ be the complex vector bundle over $\p^2$ with total space 
 $$E_r=\{(z,z')\in \mathbb{P}^2\times\mathbb{C}^3 \ | \ \sum z^k_iz'_i=0\}$$
 and bundle projection $\pi \colon E_r \to \p^2$, $\pi(z,z')=z$.
 One can identify $\zeta_k$ as conjugation of the orthogonal complement of canonical embedding $O(-k)\to\mathbb{C}^3$. So $\zeta_k\cong \xi_{k,k^2}$ and $p_1(\phi( \zeta_k))=-3k^2$. Notice that $\mathbb{P}(\zeta_1)$ is the Milnor hypersurface $\{(z,z')\in \mathbb{P}^2\times\mathbb{P}^2 \ | \ \sum z_iz'_i=0\}$. We call $M_k=\{(z,z')\in \mathbb{P}^2\times\mathbb{P}^2 \ | \ \sum z^k_iz'_i=0\}=\mathbb{P}(\zeta_k)$ a generalized Milnor hypersurface. One can easily show that the canonical generators of $M_k$ induced from the bundle $\zeta_k$ are $(\pi^* x,\pi'^* x)$. Here $\pi(z,z')=z, \pi'(z,z')=z'$. 
\end{eg}

\begin{lemma}\label{bh}
Let $\xi$ be the nontrivial $3$-dimensional real vector bundle over $S^5$, $\partial \colon \pi_{i+1}(S^5)\to \pi_i(S^2)$ be the boundary homomorphism in the long exact sequence of homotopy groups associated to the sphere bundle of $\xi$, $\pi_i(S^4) \to \pi_i(\Omega S^5)$ be the map induced by the adjoint of the identity map $S^5= \Sigma S^4 \to S^5$. Then the composite $\pi_i(S^4) \to \pi_i(\Omega S^5) = \pi_{i+1}(S^5) \to \pi_i(S^2)$ is identified with the homomorphism $\eta^2 \colon \pi_i(S^4) \to \pi_i(S^2)$ induced by the Hopf map $\eta \colon S^3 \to S^2$.

\begin{cor}\label{htg}
Let $N_r$ be the $S^2$-bundle over $ \mathbb{P}^2$ defined as above. Assume $r\in 8\mathbb{Z}+5$. Then
\begin{enumerate}
\item the inclusion of a fiber induces an isomorphism $\pi_3(S^2)\to\pi_3(N_r)$; 
\item$\pi_4(N_r)=0$; 
\item the bundle projection induces an injective homomorphism $\pi_5(N_r)\to \pi_5(\mathbb{P}^2)$ with image $2 \cdot \pi_5(\mathbb{P}^2)$;
\item $\pi_6(S^2)\to\pi_6(N_r)$ is surjective and $\pi_6(N_r)\cong \mathbb{Z}_6$.
\end{enumerate}
 \end{cor}

\begin{lemma}\label{t7}
 Let $\Theta_7\cong \mathbb{Z}_{28}$ be the Milnor-Kervaire group of oriented differential structures on the $7$-sphere. Then connected sum operation induces a surjective map $cs:\Theta_7\to S_\partial(N_r\times I)$. 
 \end{lemma} 
 \begin{proof}
Consider the smooth surgery exact sequence ( Theorem 11.22 of \cite{LuTi})
$$L_8(\z) \to S_\partial(N_r\times I) \to [\Sigma N_r, G/O] \to L_7(\z).$$
A direct calculation shows that the group $H^i(\Sigma N_r;\pi_i(G/O))$ vanishes for all $i$. Therefore by obstruction theory, the homotopy set $[\Sigma N_r, G/O]$ consists of a single element. Therefore
the map $L_8(\z) \to S_\partial(N_r\times I)$ is surjective. By the construction, the Wall realization map $L_8(\mathbb Z) \to S_{\partial}(N_r \times I)$ factors through $L_8(\z) \to \Theta_7 \to S_\partial(N_r\times I)$.
 \end{proof}

In \cite[Theorem 7.9 and 7.12]{KreSu}, the group $\m_\partial(S^2\times D^4)$ is computed and a system of generator is given. Let $g_1$ be a diffeomorphism of $D^6$ relative to the boundary, representing a generator of $ \m_\partial(D^6)\cong \Theta_7$, $t_1\in\pi_3(SO(4))$ be a generator of $\mathrm{Im}\, \pi_3(SO(3))\cong\mathbb{Z}$, $t_2$ be a generator of $\pi_4(SO(3))\cong \mathbb{Z}_2$ and $i_\eta:S^3\times D^3\to S^2\times D^4$ be an embedding representing the Hopf map $\eta\in\pi_3(S^2)$. Fix an embedded $6$-disk in $S^2 \times D^4$ and extend $g_1$ to the complement by the identity; let $g_2$ and $g_3$ be the Dehn twists in $i_{\eta}(S^3 \times D^3)$ with parameters $t_1$ and $t_2$, respectively. Then $$\m_\partial(S^2\times D^4)=\mathbb{Z}_{28}\{g_1\}\oplus\mathbb{Z}_{12}\{g_2\}\oplus\mathbb{Z}_2\{g_3\}$$
For any given embedding of $S^2 \times D^4$ in a $6$-manifold, we extend these diffeomorphisms by the identity on the complement and still denote them by the same notation. 
 \begin{prop}\label{sur}
 Let $i \colon S^2\times D^4\to N_r$ be a local trivialization of the $S^2$-bundle. Then $I(N_r)$ is generate by the disk-supported diffeomorphism $g_1$ and the Dehn twist $g_2$. 
 \end{prop}
 \begin{proof}
Choose a localization $i \colon S^2\times D^4\to N_r$ such that $i(S^2\times D^4)$ and $S^2\vee S^2$ (defined in the proof of Lemma \ref{Ih}) are disjoint. The diffeomorphisms $g_1$ and $g_2$, which are extended by the identity on the complement of $i(S^2 \times D^4)$, clearly induce the identity on the cohomology groups and thus (their isotopy classes) are in $I(N_r)$.

