 \mu(\d x)\,\mu(\d y).
 \end{align*}
 Once again by the properties of Wiener integrals, 
 $\sup_{t\in[\varepsilon_1,|x-y|^{1/\rho}]} |H_\alpha(t\,,y)| $
 is independent from $\sup_{t\in[\varepsilon_1,\varepsilon_2]} |H_\alpha(t\,,x)|$. 
 Therefore,
 \[
 I_2 \le \frac{1}{\P(\mathcal{E}(\varepsilon_1\,,\varepsilon_2\,,0))}
 \iint_{\substack{x,y\in K:\\\varepsilon_1^\rho < |x-y|\le 2\varepsilon_2^\rho}}
 \P\left\{ \sup_{t\in[\varepsilon_1,|x-y|^{1/\rho}]} |H_\alpha(t\,,y)| \le \theta\right\}
 \mu(\d x)\,\mu(\d y).
 \]
 By the Gaussian correlation inequality of Royen \cite{Royen},
 \begin{align*}
 \P\left\{\sup_{t\in[\varepsilon_1,|x-y|^{1/\rho}]} |H_\alpha(t\,,y)| \le \theta\right\}
 &\le\dfrac{\P\left\{ \sup_{t\in[\varepsilon_1,\varepsilon_2]} |H_\alpha(t\,,y)| \le \theta\right\}}{ \P\left\{ \sup_{t\in[|x-y|^{1/\rho},\varepsilon_2]} |H_\alpha(t\,,y)| \le \theta\right\}}\\
 &\le \dfrac{\P(\mathcal{E}(\varepsilon_1\,,\varepsilon_2\,,0))}{ \P\left\{ \sup_{t\in[|x-y|^{1/\rho},\varepsilon_2]} |H(t\,,y)| \le \theta\right\}},
 \end{align*}
 where the last inequality follows from the spatial stationarity of $H_\alpha$ 
 and Anderson's shifted-ball inequality \cite{Anderson}.
 Fix $\delta > 0$ such that
 \begin{equation}\label{ltdb}
 \frac{\lambda(\theta)+\delta}{\rho}<\beta.
 \end{equation}
 It follows from the above and Proposition \ref{pr:BC:H} that
 \begin{align*}
 I_2 &\le 
 \iint_{\substack{x,y\in K:\\\varepsilon_1^\rho < |x-y|\le 2\varepsilon_2^\rho}}
 \frac{\mu(\d x)\,\mu(\d y)}{\P\left\{\sup_{t\in[|x-y|^{1/\rho}, \varepsilon_2]} 
 |H(t\,,y)| \le \theta\right\}}\\
 &\lesssim\iint_{\substack{x,y\in K:\\\varepsilon_1^\rho < |x-y|\le 2\varepsilon_2^\rho}}\left( \frac{\varepsilon_2}{|x-y|^{1/\rho}}\right)^{\lambda(\theta)+\delta}\,
 \mu(\d x)\,\mu(\d y)
 =\mathscr{o}(1) \iint_{K \times K}
 \frac{\mu(\d x)\,\mu(\d y)}{|x-y|^{(\lambda(\theta)+\delta)/\rho}},
 \end{align*}
 uniformly for all 
 small enough numbers $\varepsilon_1,\varepsilon_2$ that satisfy
 $0<\varepsilon_1<\varepsilon_2$.
 It is well known that the preceding integral is finite thanks to \eqref{Frostman:meas} 
 and \eqref{ltdb}. Indeed, let $C = \sup_{a\in K}\inf_{b\in K}|a-b|$
 denote the diameter of $K$ and define $a=(\lambda(\theta)+\delta)/\rho$
 in order to deduce from \eqref{ltdb} that
 \begin{align*}
 &\iint_{K\times K}\frac{\mu(\d x)\,\mu(\d y)}{|x-y|^a} \lesssim
 \sum_{n=0}^\infty 2^{na}\iint_{C 2^{-n-1}\le
 |x-y|\le C2^{-n}}\,\mu(\d x)\,\mu(\d y)\\
 &\le\sum_{n=0}^\infty 2^{na} \sup_{y\in\R}
 \mu\left(\left[y-C2^{-n}~,~y+C2^{-n}\right]\right)
 \lesssim\sum_{n=0}^\infty 2^{-n(\beta-a)}<\infty.
 \end{align*}
 Thus, it follows that $I_2=\mathscr{o}(1)$ as $\varepsilon_2\to0^+$,
 whence $\E( X_{\varepsilon_1,\varepsilon_2}^2) \le 1+\mathscr{o}(1)$
 as $\max\{\varepsilon_2\,,\varepsilon_1/\varepsilon_2\}\to 0^+$.
 Therefore, we may use the Paley-Zygmund inequality and combine the above estimates to deduce that
 \begin{align*}
 \P\{ X_{\varepsilon_1,\varepsilon_2}>0 \} \ge 
 \frac{[\E(X_{\varepsilon_1,\varepsilon_2})]^2}{ \E(X_{\varepsilon_1,\varepsilon_2}^2)} = 1+\mathscr{o}(1)
 \quad\text{as $\max\{\varepsilon_2\,,\varepsilon_1/\varepsilon_2\} \to 0^+$.}
 \end{align*}

Choose and fix a decreasing sequence $\{\varepsilon_n\}_{n=1}^\infty$
 that satisfies $\max\{\varepsilon_n\,,\varepsilon_{n+1}/\varepsilon_n\}\to0$
 as $n\to\infty$.
 Then the preceding implies that
 \begin{align*}
 \P\left( \bigcup_{n \in \N} \bigcap_{m \ge n} 
 \left\{ \exists\, x \in K\,, \sup_{t \in [\varepsilon_{m+1},\varepsilon_m]}
 \frac{|H_\alpha(t\,,x)|}{t^{1/4}} \le \theta \right\} \right)
 \ge \liminf_{n\to\infty} \P\{ X_{\varepsilon_{n+1},\varepsilon_n} > 0 \} =1.
 \end{align*}
 This proves that there is a $\P$-null set off which there exists 
 $\mathfrak{N}=\mathfrak{N}(\omega) \in \N$ such that $U_{N,\mathfrak{N}}(\theta) \ne \varnothing$
 for all $N>\mathfrak{N}$, where $U_{N,n}(\theta)$ denotes the random subset of $K$
 that is defined as
 \begin{align*}
 U_{N,n}(\theta) = \left\{ x \in K : \sup_{t \in 
 [\varepsilon_N,\varepsilon_n]}\frac{|H_{\alpha}(t\,,x)|}{t^{1/4}}\le \theta \right\}
 \qquad\forall n\in\N,\ N>n.
 \end{align*}
 By the continuity of $H_{\alpha}$, every $U_{N,n}(\theta)$ 
 is a closed subset of the compact set $K$, and $N\mapsto U_{N,n}(\theta)$
 is decreasing with respect to set inclusion. Consequently,
 $\cap_{N \in \N: N>n} U_{N,n}(\theta)\neq\varnothing$ (Cantor's theorem).
 This, together with Proposition \ref{pr:H-H_alpha:sup}, implies
 that there exists $x^*\in \cup_{n\in\N}
 \cap_{N \in \N: N>n} U_{N,n}(\theta)$ such that
 \[
 \adjustlimits\inf_{x \in K} \limsup_{t\to0^+} \frac{|H(t\,,x)|}{t^{1/4}}
 \le \limsup_{t\to0^+} \frac{ |H_{\alpha}(t\,,x^*)|}{t^{1/4}} \le \theta\quad\text{a.s.}
 \]
 Recall that $\lambda: (0\,,\infty) \to (0\,,\infty)$ is strictly decreasing and $\lambda(\theta) \to 0$ as $\theta \to \infty$ 
 (see Proposition \ref{pr:BC:H}).
 Therefore, we may let $\beta \uparrow \dimh K$, $\alpha \uparrow 1$ 
 and $\delta \downarrow 0$, all along rationals, in order to see that for every 
 $\theta>0$ that satisfies $\lambda(\theta) < \tfrac12 \dimh K$,
 \[
 \adjustlimits\inf_{x \in K} \limsup_{t\to0^+} \frac{|H(t\,,x)|}{t^{1/4}} \le \theta
 \quad\text{a.s.}
 \]
 Finally, we may take infimum over all such $\theta>0$ to 
 conclude that there is a $\P$-null set off which
 \[
 \adjustlimits\inf_{x \in K} \limsup_{t\to0^+} 
 \frac{|H(t\,,x)|}{t^{1/4}} \le \inf\{\theta>0 : \lambda(\theta)<\tfrac12 \dimh K\}
 =\lambda^{-1}\left(\tfrac12\dimh K\right)\quad\text{a.s.}
 \]
 This completes the proof of Theorem \ref{th:H}.
\end{proof}

