\begin{prop}\label{prop_bl_fundamental_family}
    The blow-up 
    \begin{equation}
        \kf:=\bl_{Y}\ky'\to\DDD
    \end{equation}
    is a flat family  with regular total space, reduced central fibre
    $E\cup \Sigma$, where $E$ is a fibration in quadric 4folds over $Y\subset\Sigmab$, moreover the intersection $E\cap \Sigma$ is transverse and it is a fibration in quadric 3folds over $Y$.
\end{prop}

