The flop of $\bl_S\mathbb{P}^8$ is explicit
\begin{equation*}
        \xymatrix{
    \bl_S\mathbb{P}^8\ar[dr]&&\Sigma\ar[dl]\\
    &\overline{X}
    }
    \end{equation*}
where $\bl_S\mathbb{P}^8\to \overline{X}$ is a contraction of a $\mathbb{P}^1$ bundle over $S^{[2]}\subset \overline{X}$ and $\Sigma\to \overline{X}$ is a contraction of a $\mathbb{P}^2$ bundle over $S^{[2]}$.
In Section \ref{section_CS} we recall some results from \cite{morrison_clemens_schmid} and prove that the monodromy of the family ${\cal F}\to \mathbb{D}$ is zero.
This implies that the motivic nearby cycle
    \[
    \psi_f^{\mathrm{mot}}:=[\Sigma]+[Q_4/Y]-(1+\mathbb{L})[Q_3/Y]
    \]
gives the Hodge numbers of $\kf_t,t\neq 0$.
\begin{cor}
The Hodge diamond of $F$ is 
      \begin{equation*}
    \begin{tikzcd}[sep=tiny]
        {\rm H}^8&0&0&1&22&253&22&1&0&0\\
        {\rm H}^6&&0&0&1&22&1&0&0&\\
        {\rm H}^4&&&0&1&22&1&0&&\\
        {\rm H}^2&&&&0&1&0&&&\\
        {\rm H}^0&&&&&1&&&&\\
    \end{tikzcd}
\end{equation*}
    and the odd cohomology of $F$ is zero.
\end{cor}

\begin{proof}[Sketch of the proof of Theorem~\ref{thm_main_intro}.]
x(\tau_{-1})$. 
Moreover the fixed part by $\tau_{-1}$ in cohomology ${\rm H}^2(M_{-1},\mathbb{Q})_{+}$ has dimension two, hence we want to contract a divisor whose class in ${\rm H}^2(M_{-1},\mathbb{Q})$ is invariant by $\tau_{-1}$.
To achieve this we perform a sequence of Mukai flops $c_i,c_i',i=-1,0,1$ and a divisorial contraction $g$  given by wall crossing with respect to Bridgeland stability.
\begin{equation*}
    \xymatrix{
M_{-1}\ar[d]^{\pi}\ar[dr]^{c_{-1}}&&M_{0}\ar[dl]^{c_{-1}'}\ar[dr]^{c_{0}}&&M_{1}\ar[dl]^{c_0'}\ar[dr]^{c_1}&&M_2=M_{\rm last}\ar[dl]^{c_1'}\ar[d]^{g}\\
{\mathbb{P}^8}^\vee&\overline{M}_{-1}&&\overline{M}_{0}&&\overline{M}_{1}&\overline{M}.
    }
\end{equation*}
x(\tau_{-1})$.
\begin{equation*}
    \xymatrix{
{\mathbb{P}^8}^\vee=\Sigma_{-1}\ar[d]^{\pi_|}\ar[dr]&&\mathbb{P}^8=\Sigma_{0}\ar[dl]\ar[dr]&&\bl_S\mathbb{P}^8=\Sigma_1\ar[dl]^{{c'_0}_|}\ar[dr]^{{c_1}_|}&&\Sigma_{\rm last}\ar[dl]^{{c'_1}_|}\ar[d]^{g_|}\\
{\mathbb{P}^8}^{\vee}&{\rm pt}&&\mathbb{P}^8&&\overline{\Sigma}_1&\overline{\Sigma}
    }
\end{equation*}
In Section~\ref{section_flops} we continue the work of \cite{antisymplI,arav24} and describe the flops of $M_i,\Sigma_i$ and in particular we describe the singularities of $\overline{M}_i,i=-1,0,1$ and prove that $\Sigmab_1$ is normal, see Proposition~\ref{prop_barsigma1_normal}.
In Section~\ref{Section_contraction} we study the divisorial contraction $g$ and its restriction to $\Sigmal$ and compute the analytic neighborhood of the singularities of $\overline{\Sigma}$.
Moreover we prove that $g_|\colon \Sigmal=\bl_Y\overline{\Sigma}\to \overline{\Sigma}$ is the blowup of the singular locus which is a smooth cubic 4fold $Y\subset \overline{\Sigma}$ and the exceptional divisor $E\to Y$ is a fibration in Lagrangian Grassmannians $E={\rm LGr}(4)/Y$, see Propositions~\ref{prop_barsigm_normal}~\ref{prop_blowup_sigma}.
In Section~\ref{section_semistable} we recall some results from \cite{namikawa,markman10a,antisymplI} and we study the deformations of $\overline{\Sigma}$, this  gives us a flat family over the disc
${\cal Y}'\to \mathbb{D}$ 
where ${\cal Y}'_t,t\neq 0$ is deformation equivalent to the Fano eightfold $F$, ${\cal Y}'_0=\overline{\Sigma}$, the singular loci coincides ${\cal Y}'_{\operatorname{sing}}=\Sigmab_{\operatorname{sing}}$ and the singularity of ${\cal Y}'$ are locally analytically of the form $\mathbb{C}^4\times \{q=0\}$ where $q\in \mathbb{C}[x_0,\dots,x_4]$ is a quadric of maximal rank, see Proposition~\ref{prop_family_Y'}.
The blowup ${\cal F}:=\bl_{{\cal Y}'_{\operatorname{sing}}}{\cal Y}'\to \mathbb{D}$ is the desired family, see Proposition~\ref{prop_bl_fundamental_family}.
\end{proof}

We conclude the introduction with an example that arises naturally in the study of $F$ and it gives an interesting interpretation of a projective model of the Hilbert scheme of a K3 surface of genus eight in terms of the secant lines of the surface.
Let $V_6$ be a $\mathbb{C}$-vector space of dimension six, let us consider the birational map
\begin{equation*}
    \begin{split}
        \phi\colon \mathbb{P}(\wedge^2 V_6)&\bir \mathbb{P}(\wedge^4 V_6)\\
        [\omega]&\mapsto [\omega\wedge\omega].
    \end{split}
\end{equation*}
 For a generic $\mathbb{P}^8\subset \mathbb{P}(\wedge^2 V_6)$ the intersection $S:={\rm Gr}(2,4)\cap \mathbb{P}^8$ is a smooth K3 surface of genus eight and by the work of Mukai all the K3 surfaces of genus eight arise this way.
\begin{thm}[{Theorem~\ref{thm_geom_descr_contr}}]
    There is a projective model $S^{[2]}\subset \mathbb{P}(\wedge^4 V_6)$ obtained as the closure of the images trough $\phi$ of the 2-secant lines to $S$ in $\mathbb{P}^8$, i.e.,
    \[
    S^{[2]}=\overline{\bigcup_{p,q\in S}\phi(L_{p,q})}
    \]
    where $L_{p,q}$ is the line in $\mathbb{P}^8$ passing trough $p$ and $q$.
\end{thm}

\subsection{Open questions}
We recall that if $Y$ is a smooth cubic 4fold not containing a plane then the LLSvS eightfold $N$ associated to $Y$ has an antisymplectic involution, $Y\subset N$ is naturally embedded in $N$ and it is one of the connected components of the fixed locus, see \cite{LLSvS,antisymplI,antisymplII}. 
Hence it is interesting to ask if the Fano eightfold $F$ shares some properties with the cubic 4folds, we list here some questions that interest us
\begin{itemize}
    \item do we have a Torelli theorem for $F$?
    \item is $F$ irrational?
    \item is $F$ a $K$-stable variety?
\end{itemize}

The BGMN conjecture proved by Tevelev-Torres in \cite{TT} provides a semiorthogonal decomposition of the derived category ${\rm D}(N)$ of the moduli space $N$ of vector bundles of rank 2 of odd degree on a curve $C$ of genus at least 2.
The factors of the semiorthogonal decompositions are equivalent to the derived category of the symmetric powers of $C$.
\begin{conj}[Flapan-Macrì-O'Grady-Saccà]
    The Fano eightfold $F$ obtained as fixed locus in $X$ admits the following semiorthogonal decomposition
    \begin{equation*}
        {\rm D}(F)=\langle {\rm D}(K),{\rm D},{\rm D},{\rm D},{\cal O},{\cal O}(1),{\cal O}(2)\rangle
    \end{equation*}
    where ${\rm D}$ is a K3 category for which $X=(M_{\sigma}(h),v)$ is a moduli space of objects on ${\rm D}$ with a polarization $v$.
    Moreover $K$ is a HK 4fold \textit{strange dual} to $X$, i.e., $K=M_{\sigma}(v)$.
\end{conj}
Note that the Hodge numbers of $F$ agree with this conjecture.

\subsection{Acknowledgments}
I would like to thank my advisor  Emanuele Macr{\`i} for suggesting me such a beautiful problem and for the support  during the work and the writing of this article. 
I would like to also thank Pietro Beri, Aaron Bertram, Alessio Bottini, Franco Giovenzana, Alexander Kuznetsov, Kieran O'Grady, {\'A}ngel-David R{\'i}os-Ortiz,  
Francesca Rizzo and Franco Rota for helpful conversations. 
