\begin{thmA}\label{thmC}
Let $\alpha \colon \Gamma \actson M$ be a state preserving outer action of a countably infinite discrete group $\Gamma$ on a type $\mathrm{III}_1$ factor with separable predual. 
Assume that $\Gamma$ is amenable and that $M$ has trivial bicentralizer. 
If $\Gamma_{\mathrm{mod}}$ is trivial, then there exists an $\alpha$-cocycle 
$u \colon \Gamma \to \mathcal U(M)$ such that the perturbed action 
is state preserving and weakly mixing.
\end{thmA}

\begin{lem}\label{lem-relative-bicentralizer}
 Let $\Gamma \actson M$ be a state preserving outer action of a countable group on a von Neumann algebra. Assume that:
\begin{itemize}
 \item $\Gamma_{\mathrm{mod}}$ is trivial;
 \item $M$ is a type $\mathrm{III}_1$ factor with separable predual and has trivial bicentralizer.
\end{itemize}
Then we have $\mathrm{BC}(M \subset M\rtimes_\alpha \Gamma, \varphi)=\mathbb C$ for all faithful state $\varphi\in M_\ast$.
\end{lem}

\begin{lem}\label{lem-cocycle3.6}
 Let $\alpha\colon \Gamma \actson (M,\varphi)$ be a state preserving outer action of a countably infinite discrete group on a diffuse factor with separable predual and with a faithful normal state. 
Assume that $\Gamma$ is amenable and that $\mathrm{BC}(M\subset M\rtimes \Gamma,\varphi)=\C$. 
Then for every $\varepsilon>0$ and every finite subset $F\subset \Gamma$, there exist $h\in \Gamma$ and $U\in \mathcal U(M^\omega)$ such that:
\begin{itemize}
 \item $\varphi^\omega(U)=0$, \quad $\|U\varphi^\omega-\varphi^\omega U\|<\varepsilon$,\quad and \quad $\|\alpha_g^\omega(U)-U\|_{\varphi^\omega}<\varepsilon$ for all $g\in F$;
 \item $M$, $U$, and $\alpha_h^\omega(U)$ are $\ast$-free with respect to $\varphi^\omega$.
\end{itemize}
\end{lem}

\begin{lem}\label{lem-cocycle3.5}
Let $\alpha\colon \Gamma \actson (M,\varphi)$ be a state preserving outer action of a countably infinite discrete group on a diffuse factor with separable predual. Assume that $\Gamma$ is amenable and that $\mathrm{BC}(M\subset M\rtimes \Gamma,\varphi)=\C$. For any $x\in M\setminus\C$, any finite subset $E\subset M\setminus\C$, and any $\varepsilon>0$, the pair $(1,\varphi)\in\mathcal C_{\mathrm{state}}(\alpha)$ can be approximated by elements of $\mathcal U(x)\cap \mathcal V( E,\varepsilon)$, where $1\in\mathcal C(\alpha)$ is the trivial cocycle.
\end{lem}
\begin{proof}
 Fix $\varepsilon>0$, $x\in M\setminus\C$, finite subsets $F\subset\Gamma$ and $E\subset M$. We will show that for every sufficiently small $\delta>0$, there exists $u\in\mathcal U(M)$ satisfying the following conditions:
\begin{itemize}
 \item[(a)] $\|u-\alpha_g(u)\|_\varphi<\delta$ for all $g\in F$, and $\|u\varphi-\varphi u\|<\delta$;
 \item[(b)] there exists $h\in\Gamma$ such that 
 \[
 \|\alpha_h(uxu^*)-uxu^*\|_\varphi>\|uxu^*-\varphi(uxu^*)\|_\varphi;
 \]
 \item[(c)] there exists $h\in\Gamma$ such that 
 \[
 \sum_{a,b\in E}\bigl|
 \varphi(\alpha_h(uau^*)ubu^*)-\varphi(uau^*)\varphi(ubu^*)
 \bigr|<\varepsilon.
 \]
\end{itemize}
If such a unitary $u$ exists, define an $\alpha$-cocycle $v_g:=u^*\alpha_g(u)$ for $g\in\Gamma$ and set $\psi:=u^*\varphi u$. Then $ \alpha^v$ preserves $\psi$, and by (a) the distance between $(1,\varphi)$ and $(v,\psi)$ is small. Moreover, (b) and (c) ensures that $(v,\psi)\in\mathcal U(x) \cap \mathcal V(E,\varepsilon)$. Thus to prove the lemma, it suffices to construct such a unitary $u$.

