ref_dict.thm:recursion:
\begin{theorem} \label{thm:recursion}
    Let $(f_3,f_4,\cdots)$ be the sequence of polynomials 
    \begin{align}
        f_n(\hat{t}_0,\cdots,\hat{t}_{n-3};1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-2})\in \Z[\hat{t}_0,\cdots,\hat{t}_{n-3},1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-2}],
    \end{align}
    defined recursively by 
    \begin{align}
        f_3(\hat{t}_0;1/\hat{\gamma}_1)=-\frac{\hat{t}_0^3}{\hat{\gamma}_1}
    \end{align} 
    and for $n\geq3$
    \begin{align}\label{eq:f_rec}
        &f_{n+1}(\hat{t}_0,\cdots,\hat{t}_{n-2};1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-1})=\nonumber\\&\qquad\qquad
        \sum_{k=0}^{n-3}\left[
            \hat{t}_{k+1}\left(\pdv{\hat{\gamma}_{k+1}}-\frac{\hat{t}_0}{\hat{\gamma}_1}\pdv{\hat{t}_k}\right) 
            -\hat{\gamma}_{k+2}\frac{\hat{t}_0}{\hat{\gamma}_1}\pdv{\hat{\gamma}_{k+1}}
        \right] f_n(\hat{t}_0,\cdots,\hat{t}_{n-3};1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-2}).
    \end{align}
\\\\
    Then the $n$-th term of the generating function of genus-$0$ Weil--Petersson volumes is given by
    \begin{align}
        n![x^n]F_0(x\mu)=\int\rmd\mu(L_1)\cdots\rmd\mu(L_n)V_{0,n}(L_1,\cdots,L_n)=
        \frac{1}{8} f_n(t_0[\mu],\cdots,t_{n-3}[\mu];1/\gamma_1,\gamma_2,\cdots,\gamma_{n-2}),
    \end{align}
    where
    \begin{align}
        t_k[\mu]=\int \rmd\mu(L)\, 2\frac{L^{2k}}{4^k k!}
    \end{align}
    and 
    \begin{align}
        \gamma_k=(-1)^k \frac{\pi^{2k-2}}{(k-1)!}.
    \end{align}
\end{theorem}

