To a $\tree\in\treeset^{\mathrm{all,HTC}}_n$ we associate the \emph{half-tight polytope} $\mathcal{A}_{\tree}(\mathbf{L})$ as follows:
\begin{align}
 \mathcal{A}_{\tree}(\mathbf{L}) \coloneqq &\left\{ \varphi : \vec{\edgeset}(\tree) \to \R_{\geq 0} \middle|\begin{array}{l}
 \varphi(\vec{\edge}_{\bvertex,i}) = 0\text{ for }\bvertex\in\vsetboundary(\tree), 1\leq i\leq\deg(\bvertex),\\
 \varphi(\vec{\edge}_{\vertex,i}) > 0\text{ for }\vertex\in \vsetinner(\tree), 1\leq i\leq\deg(\vertex),\\
 \sum_{i=1}^{\deg(\vertex)}\varphi(\vec{\edge}_{\vertex,i}) = \pi\text{ for }\vertex\in \vsetinner(\tree), \nonumber\\ 
 \varphi(\vec{\edge}) + \varphi(\cev{\edge}) < \pi\text{ for }\edge\in \edgeset(\tree)\end{array}\right\} \\
 &\times \left[\Delta_{\deg(\bvertex_2)}^{((L_2-L_1)/2)} \times \Delta_{\operatorname{nonid}(\bvertex_2)}^{((L_2+L_1)/2)}\right]
 \times \prod_{\bvertex\in \vsetboundary(\tree)\setminus\{\bvertex_2\}} \left[\Delta_{\deg(\bvertex)}^{(L_{\bvertex}/2)} \times \Delta_{\operatorname{nonid}(\bvertex)}^{(L_{\bvertex}/2)}\right].\label{eq:polytopedef}
\end{align}
where $\Delta_k^{(y)} = \{ \mathbf{x} \in (0,\infty)^{k} : x_1 + \cdots + x_{k} = y \}$ is the open $(k-1)$-dimensional simplex of size $y$.

The half-tight polytopes are of dimension 
\begin{align}
 \dim\mathcal{A}_\tree(\mathbf{L}) 
 &= 2n-6 + \sum_{\vertex\in\vsetinner(\tree)} (3-\deg(\vertex)) + \sum_{\bvertex\in\vsetboundary(\tree)} (\operatorname{nonid}(\bvertex)-\deg(\bvertex)), \label{eq:dimpolytope}
\end{align}
from which follows that the top-dimensional polytopes correspond to trees $\tree\in\treeset^{\mathrm{all,HTC}}_n$, where all inner vertices are of degree $3$ and all corners are marked as non-ideal.

For these top-dimension polytopes, we can introduce the following natural volume measure given by $2^{n-3}$ times the $(2n-6)$-dimensional Lebesgue measure
\begin{align}
 \operatorname{Vol}_\tree = 2^{n-3} \prod_{\vertex\in \vsetinner(\tree)}\rmd\varphi(\vec{\edge}_{\vertex,1})\rmd\varphi(\vec{\edge}_{\vertex,2}) \prod_{\bvertex\in \vsetboundary(\tree)} \prod_{j=1}^{\deg(\bvertex)-1}\rmd w_{\bvertex,j}\rmd v_{\bvertex,j},\label{eq:measurepolytope}
\end{align}
where $(w_{\bvertex,1},\ldots,w_{\bvertex,\deg(\bvertex)},v_{\bvertex,1},\ldots,v_{\bvertex,\deg(\bvertex)})$ parametrizes the simplices of $\bvertex$.

\begin{theorem}\label{thm:HTC_gf}
 Let the generating function $R[\mu]$ be the unique formal power series solution satisfying $R[\mu] = \int\rmd\mu(L) + O(\mu^2)$ to
 \begin{equation}\label{eq:Zdef}
 Z(R[\mu];\mu] = 0,\qquad Z(r;\mu]\coloneqq \frac{\sqrt{r}}{\sqrt{2}\pi}J_1(2\pi\sqrt{2r}) - \int\rmd\mu(L)\,I_0(L\sqrt{2r})
 \end{equation}
 where $I_0$ and $J_1$ are (modified) Bessel functions.

To a $\dubtree\in\treeset^{\mathrm{all,double}}_n$ we associate the \emph{full polytope} $\mathcal{A}_{\dubtree}(\mathbf{L})$: 
\begin{align}
 \mathcal{A}_{\dubtree}(\mathbf{L}) &=
 \left\{
 \left(\ell,\tau,
 (w_{\bvertex_1,i})_{i=1}^{\deg(\bvertex_1)},
 (v_{\bvertex_1,i})_{i=1}^{\operatorname{nonid}(\bvertex_1)},
 (w_{\bvertex_2,i})_{i=1}^{\deg(\bvertex_2)},
 (v_{\bvertex_2,i})_{i=1}^{\operatorname{nonid}(\bvertex_2)}\right) 
 \in \R^{d_{12}}
 \middle| 
 \begin{array}{l}
 0\leq\tau<\ell<\min(L_1,L_2)\\
 \mathbf{w}_{\bvertex_i}\in \Delta_{\deg(\bvertex_i)}^{((L_i-\ell)/2)}\\
 \mathbf{v}_{\bvertex_1}\in \Delta_{\operatorname{nonid}(\bvertex_i)}^{((L_i+\ell)/2)} 
 \end{array}\right\}
 \nonumber\\&\qquad
 \times \left\{ \varphi : \vec{\edgeset}(\dubtree) \to \R_{\geq 0} \middle|
 \begin{array}{l}
 \varphi(\vec{\edge}_{\bvertex,i}) = 0\text{ for }\bvertex\in\vsetboundary(\dubtree), 1\leq i\leq\deg(\bvertex),\\
 \varphi(\vec{\edge}_{\vertex,i}) > 0\text{ for }\vertex\in \vsetinner(\dubtree), 1\leq i\leq\deg(\vertex),\\
 \sum_{i=1}^{\deg(\vertex)}\varphi(\vec{\edge}_{\vertex,i}) = \pi\text{ for }\vertex\in \vsetinner(\dubtree), \\ 
 \varphi(\vec{\edge}) + \varphi(\cev{\edge}) < \pi\text{ for }\edge\in \edgeset(\dubtree)
 \end{array}\right\} \nonumber\\&\qquad
 \times \prod_{\bvertex\in \vsetboundary(\tree)\setminus\{\bvertex_1,\bvertex_2\}} \left[\Delta_{\deg(\bvertex)}^{(L_{\bvertex}/2)} \times \Delta_{\operatorname{nonid}(\bvertex)}^{(L_{\bvertex}/2)}\right],
 \label{eq:Full_polytopedef}
\end{align}
where $d_{12}=2+\deg(\bvertex_1)+\operatorname{nonid}(\bvertex_1)+\deg(\bvertex_2)+\operatorname{nonid}(\bvertex_2)$.

We get the following result.
\begin{theorem}\label{thm:Full_bij}
 Given $\mathbf{L}=(L_1,\dots,L_n)$ with $L_1< L_2$, let $\mathcal{M}^\circ_{0,n}(\mathbf{L})\subset\mathcal{M}_{0,n}(\mathbf{L})$ be the full WP-measure subset, where there is a unique shortest geodesic separating the first two boundaries, possibly being one of the boundaries itself.
 Then there is a bijection
 \begin{align}
 \spinebijection:\mathcal{M}^\circ_{0,n}(\mathbf{L})\to \left(\bigsqcup_{\tree \in \treeset^{\mathrm{all,HTC}}_n} \mathcal{A}_{\tree}(\mathbf{L})\right)\sqcup\left(\bigsqcup_{\dubtree \in \treeset^{\mathrm{all,full}}_n} \mathcal{A}_{\dubtree}(\mathbf{L})\right).
 \end{align}
 Moreover, the push-forward of the Weil--Petersson measure is the measure $\operatorname{Vol}_\tree$ on the top-dimensional half-tight and full polytopes.
\end{theorem}

Similarly, we have the inverse mapping 
\begin{align}
 \mathsf{Glue} : \bigsqcup_{\tree \in \treeset^{\mathrm{all,HTC}}_n} \mathcal{A}_{\tree}(\mathbf{L}) \to \mathcal{H}_n(\mathbf{L}),
\end{align}
defined identically to \cite{Budd2025_Tree_bij}, where we use the tree structure and labels to construct the quadrilaterals and wedges and glue them accordingly.

We can now prove the first claim of Theorem~\ref{thm:HTC_bij}
\begin{proposition}\label{prop:HTC_tree_bij}
 $\spinebijection$ is a bijection from $\mathcal{H}_n(\mathbf{L})$ to $\bigsqcup_{\tree \in \treeset^{\mathrm{all,HTC}}_n} \mathcal{A}_{\tree}(\mathbf{L})$, with $\mathsf{Glue}$ as inverse.
\end{proposition}
\begin{proof}
 By construction, it is clear that $\mathsf{Glue}\circ \spinebijection(X) = X$. 
 We thus only need to show that the reverse is also true. 
 In particular, we need to show that the union of diagonals of the quadrilaterals and inner vertices $\Sigma$ is indeed the spine of the image of $\mathsf{Glue}$.

\begin{theorem}\label{thm:HTC_bij}
    There exists a bijection
    \begin{align}
        \spinebijection:\mathcal{H}_n(\mathbf{L})\to \bigsqcup_{\tree \in \treeset^{\mathrm{all,HTC}}_n} \mathcal{A}_{\tree}(\mathbf{L}).
    \end{align} 
    Moreover, the push-forward of the Weil--Petersson measure is the measure $\operatorname{Vol}_\tree$ on the top-dimensional polytopes.
\end{theorem}

