\subsection{General planar surfaces}
We now introduce the set of bicolored \emph{double} plane trees $\mathsf{t}=(\tree_1,\tree_2)\in\mathfrak{T}^{\mathrm{all,double}}_n$, each with identical restrictions as before, except that there are in total $n$ boundary vertices with labels $1,\ldots,n$, partitioned such that $b_1\in\mathsf{B}(\tree_1)$ and $b_2\in\mathsf{B}(\tree_2)$ and each tree has at least two boundary vertices.

To a $\mathsf{t}\in\mathfrak{T}^{\mathrm{all,double}}_n$ we associate the \emph{full polytope} $\mathcal{A}_{\mathsf{t}}(\mathbf{L})$: 
\begin{align}
	\mathcal{A}_{\mathsf{t}}(\mathbf{L}) &=
    \left\{
        \left(\ell,\tau,
        (w_{\bvertex_1,i})_{i=1}^{\deg(\bvertex_1)},
        (v_{\bvertex_1,i})_{i=1}^{\operatorname{nonid}(\bvertex_1)},
        (w_{\bvertex_2,i})_{i=1}^{\deg(\bvertex_2)},
        (v_{\bvertex_2,i})_{i=1}^{\operatorname{nonid}(\bvertex_2)}\right) 
        \in \mathbb{R}^{d_{12}}
    \middle| 
    \begin{array}{l}
        0\leq\tau<\ell<\min(L_1,L_2)\\
        \mathbf{w}_{\bvertex_i}\in \Delta_{\deg(\bvertex_i)}^{((L_i-\ell)/2)}\\
        \mathbf{v}_{\bvertex_1}\in \Delta_{\operatorname{nonid}(\bvertex_i)}^{((L_i+\ell)/2)} 
    \end{array}\right\}
    \nonumber\\&\qquad
    \times \left\{ \varphi : \vec{\mathsf{E}}(\mathsf{t}) \to \R_{\geq 0} \middle|
    \begin{array}{l}
        \varphi(\vec{\mathsf{e}}_{\mathsf{b},i}) = 0\text{ for }\mathsf{b}\in\mathsf{B}(\mathsf{t}), 1\leq i\leq\deg(\mathsf{b}),\\
        \varphi(\vec{\mathsf{e}}_{\mathsf{v},i}) > 0\text{ for }\mathsf{v}\in \mathsf{V}(\mathsf{t}),  1\leq i\leq\deg(\mathsf{v}),\\
        \sum_{i=1}^{\deg(\mathsf{v})}\varphi(\vec{\mathsf{e}}_{\mathsf{v},i}) = \pi\text{ for }\mathsf{v}\in \mathsf{V}(\mathsf{t}), \\ 
        \varphi(\vec{\mathsf{e}}) + \varphi(\cev{\mathsf{e}}) < \pi\text{ for }\mathsf{e}\in \mathsf{E}(\mathsf{t})
    \end{array}\right\} \nonumber\\&\qquad
    \times \prod_{\mathsf{b}\in \mathsf{B}(\mathfrak{t})\setminus\{\bvertex_1,\bvertex_2\}} \left[\Delta_{\deg(\mathsf{b})}^{(L_{\mathsf{b}}/2)} \times \Delta_{\operatorname{nonid}(\mathsf{b})}^{(L_{\mathsf{b}}/2)}\right],
    \label{eq:Full_polytopedef}
\end{align}
where $d_{12}=2+\deg(\bvertex_1)+\operatorname{nonid}(\bvertex_1)+\deg(\bvertex_2)+\operatorname{nonid}(\bvertex_2)$.

Furthermore, the top-dimensional polytopes again correspond to the trees 
where all inner vertices are of degree $3$ and all corners are marked as non-ideal. 
On the top-dimensional full polytopes, we have a similar volume measure given by $2^{n-4}$ times the $(2n-6)$-dimensional Lebesgue measure
\begin{align}
	\operatorname{Vol}_\mathfrak{t} = 2^{n-4}\,\mathrm{d}\ell\mathrm{d}\tau \prod_{\mathsf{v}\in \mathsf{V}(\mathfrak{t})}\mathrm{d}\varphi(\vec{\mathsf{e}}_{\mathsf{v},1})\mathrm{d}\varphi(\vec{\mathsf{e}}_{\mathsf{v},2}) \prod_{\mathsf{b}\in \mathsf{B}(\mathfrak{t})} \prod_{j=1}^{\deg(\mathsf{b})-1}\mathrm{d} w_{\mathsf{b},j}\mathrm{d} v_{\mathsf{b},j}.\label{eq:measure_full_polytope}
\end{align}

We get the following result.
\begin{theorem}\label{thm:Full_bij}
    Given $\mathbf{L}=(L_1,\dots,L_n)$ with $L_1< L_2$, let $\mathcal{M}^\circ_{0,n}(\mathbf{L})\subset\mathcal{M}_{0,n}(\mathbf{L})$ be the full WP-measure subset, where there is a unique shortest geodesic separating the first two boundaries, possibly being one of the boundaries itself.
    Then there is a bijection
    \begin{align}
        \mathsf{Spine}:\mathcal{M}^\circ_{0,n}(\mathbf{L})\to \left(\bigsqcup_{\mathfrak{t} \in \mathfrak{T}^{\mathrm{all,HTC}}_n} \mathcal{A}_{\mathfrak{t}}(\mathbf{L})\right)\sqcup\left(\bigsqcup_{\mathsf{t} \in \mathfrak{T}^{\mathrm{all,full}}_n} \mathcal{A}_{\mathsf{t}}(\mathbf{L})\right).
    \end{align}
    Moreover, the push-forward of the Weil--Petersson measure is the measure $\operatorname{Vol}_\mathfrak{t}$ on the top-dimensional half-tight and full polytopes.
\end{theorem}

This theorem allows us to compute the Weil--Petersson volumes of planar hyperbolic surfaces, using a recursion in the number of boundaries:
\begin{theorem} \label{thm:recursion}
    Let $(f_3,f_4,\cdots)$ be the sequence of polynomials 
    \begin{align}
        f_n(\hat{t}_0,\cdots,\hat{t}_{n-3};1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-2})\in \mathbb{Z}[\hat{t}_0,\cdots,\hat{t}_{n-3},1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-2}],
    \end{align}
    defined recursively by 
    \begin{align}
        f_3(\hat{t}_0;1/\hat{\gamma}_1)=-\frac{\hat{t}_0^3}{\hat{\gamma}_1}
    \end{align} 
    and for $n\geq3$
    \begin{align}\label{eq:f_rec}
        &f_{n+1}(\hat{t}_0,\cdots,\hat{t}_{n-2};1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-1})=\nonumber\\&\qquad\qquad
        \sum_{k=0}^{n-3}\left[
            \hat{t}_{k+1}\left(\pdv{\hat{\gamma}_{k+1}}-\frac{\hat{t}_0}{\hat{\gamma}_1}\pdv{\hat{t}_k}\right) 
            -\hat{\gamma}_{k+2}\frac{\hat{t}_0}{\hat{\gamma}_1}\pdv{\hat{\gamma}_{k+1}}
        \right] f_n(\hat{t}_0,\cdots,\hat{t}_{n-3};1/\hat{\gamma}_1,\hat{\gamma}_2,\cdots,\hat{\gamma}_{n-2}).
    \end{align}
\\\\
    Then the $n$-th term of the generating function of genus-$0$ Weil--Petersson volumes is given by
    \begin{align}
        n![x^n]F_0(x\mu)=\int\mathrm{d}\mu(L_1)\cdots\mathrm{d}\mu(L_n)V_{0,n}(L_1,\cdots,L_n)=
        \frac{1}{8} f_n(t_0[\mu],\cdots,t_{n-3}[\mu];1/\gamma_1,\gamma_2,\cdots,\gamma_{n-2}),
    \end{align}
    where
    \begin{align}
        t_k[\mu]=\int \mathrm{d}\mu(L)\, 2\frac{L^{2k}}{4^k k!}
    \end{align}
    and 
    \begin{align}
        \gamma_k=(-1)^k \frac{\pi^{2k-2}}{(k-1)!}.
    \end{align}
\end{theorem}
In fact, this theorem is a special case of \cite[Theorem~4]{Budd2024_Top_rec},\footnote{Which is itself equivalent to \cite[Proposition~3.5]{Bouttier2024_Enumeration_BGM_D}, which is a similar recursion for tight maps.} 
although this is hard to recognize, due to different notation. 
In any case, in \cite{Budd2024_Top_rec} this theorem is proven by solving algebraic equations, while here we will provide a more direct proof. 

\subsection{Outline}
After some short background on moduli spaces and Weil--Petersson volumes in section~\ref{sec:background}, we start generalizing the tree bijection of \cite{Budd2025_Tree_bij}. 
In section~\ref{sec:spine}, we use Busemann functions to construct the spine for a half-tight cylinder. 
Section~\ref{sec:tiling} completes the proof of the bijection for the half-tight cylinder.

Next, in section~\ref{sec:general}, we extend the tree bijection to general surfaces, by decomposing the surfaces into half-tight cylinders.
We use these results in section~\ref{sec:compute} where we use some tricks to simplify the computation of Weil--Petersson volumes. 
Finally, in section~\ref{sec:outlook}, we give some outlook.

