|\nabla u|^2 dx-\frac{\rho}{p}\int_{\Omega}|x|^{-\alpha}|u|^pdx,\quad \forall u\in H_0^1(\Omega),\forall\rho\in[\frac{1}{2},1].\end{equation*}

\begin{definition}
 For $\mu>0, \rho\in[\frac{1}{2},1],$ a solution $u\in H_0^1(\Omega)$ to 
 \begin{equation}\tag{1.3-$\rho$}\label{1.1rho}
\begin{cases} 
 -\Delta u + \lambda u = \rho{|x|^{-\alpha}}|u|^{p-2} u \quad &\text{in } \Omega, \\
 u = 0 &\text{in } \partial\Omega 
\end{cases}
\end{equation}
is called $(\mu,\rho)$ sub-mass mountain pass solution$,$ if $u\in S_\mu\cup S_\mu^-$ solves $($\ref{1.1rho}$)$ for some $\lambda\in\mathbb{R},$ and $E_\rho(u)=c_\rho(\mu),$ where $S_\mu^-:=\{u\in H_0^1(\Omega):\int_{\Omega}|u|^2 dx< \mu\}.$
\end{definition}

We shall prove that for any given $\mu>0, \rho\in[\frac{1}{2},1],$ the mountain pass level $c_\rho(\mu)$ is attained by some positive $(\mu,\rho)$ sub-mass solution $u(\mu,\rho)\in H_0^1(\Omega),$ and corresponds to some $\lambda(\mu,\rho)\geq 0.$

\begin{equation}\label{1.1}
\begin{cases} 
   -\Delta u + \lambda u = |x|^{-\alpha}|u|^{p-2} u \quad &\text{in } \Omega, \\
   u = 0 \quad&\text{on } \partial\Omega,  
\end{cases}
\end{equation}

\begin{equation}\tag{1.3-$\rho$}\label{1.1rho}
\begin{cases} 
   -\Delta u + \lambda u = \rho{|x|^{-\alpha}}|u|^{p-2} u \quad &\text{in } \Omega, \\
   u = 0 &\text{in } \partial\Omega  
\end{cases}
\end{equation}

\begin{equation}\label{1.2}
    \int_{\Omega} u^2 \, dx = \mu>0,
\end{equation}

To deal with the lack of compactness, we only need to rule out the case $\lambda(\mu,\rho)=0$. This might typically involve Liouville type results, such as those in \cite{Ikoma,jeanjean2024JMPA}. However, to our knowledge, existing Liouville-type theorems are not applicable to our problem. Therefore, we develop a new approach by studying the asymptotic behavior of sub-mass solutions (or solutions under a closed ball constraint) to analyze compactness. And inspired by \cite{HE2023375}, we shall obtain the following asymptotic behavior for the $(\mu,\rho)$ sub-mass mountain pass solution $u(\mu,\rho)$ in the sense of $C^2_{loc}(\mathbb{R}^N)$ and $H^1(\mathbb{R}^N)$.

In other words, Theorem \ref{asymtotic} provides an a priori estimate of the Lagrange multiplier $\lambda$ in the setting of the mountain pass. Hence, for small enough $\mu,$ we necessarily have $\lambda>0,$ at this point we shall prove that the nonlinearity $|x|^{-\alpha}|u|^{p-2}u$ ensures compactness. And we have the following result: 
\begin{theorem}\label{main result}
Let $\alpha,\mu>0,$ $N\geq3,$ $2+4/N<p<2^*,$ and $\Omega\subset\mathbb{R}^N$ be an exterior domain with $0\notin\overline\Omega$. Then there is a $\mu_0>0$ such that for any $\mu\in(0,\mu_0),$ equations $($\ref{1.1}$)$-$($\ref{1.2}$)$ has a positive solution for some $\lambda> 0.$ 
\end{theorem}

\begin{lemma}\label{c_rho}
 For every $\mu > 0,$ there exist $w_1(\mu), w_2(\mu) \in S_\mu$ independent of $\rho \in \left[\frac{1}{2}, 1\right]$ such that
\[
c_\rho(\mu) := \inf_{\gamma \in \Gamma} \max_{t \in [0,1]} E_\rho(\gamma(t)) > \max\{E_\rho(w_1), E_\rho(w_2)\}, \quad \forall \rho \in \left[\frac{1}{2}, 1\right],
\]
where $\Gamma := \{\gamma \in C([0, 1], S_{\mu}) \mid \gamma \text{ is continuous}, \gamma(0) = w_1, \gamma(1) = w_2\}$.
\begin{proof}
 For any $\mu, k > 0,$ denote
\[
A_{\mu, k} := \{u \in S_{\mu} \mid \int_\Omega |\nabla u|^2 dx < k\},
\]
\[
\partial A_{\mu, k} := \{u \in S_{\mu} \mid \int_\Omega |\nabla u|^2 dx = k\}.
\]
Firstly note that, for any $\mu, k > 0,$ we have $A_{\mu, k} \neq \emptyset$ (and, similarly, $\partial A_{\mu, k} \neq \emptyset$). Indeed, take any function $v \in C_c^\infty(\mathbb{R})$ with $\|v\|_{L^2(\Omega)}^2 = \mu,$ and consider $v_t(x) = t^{N/2} v(tx),$ for $t > 0$. We have that
\[
\|v_{t}\|_{L^2(\Omega)}^2 = \mu \quad \text{and} \quad \|\nabla v_t\|_{L^2(\Omega)}^2 = t^2 \|\nabla v\|_{L^2(\Omega)}^2 \quad \text{for every } t > 0.
\]
Since $\Omega$ is an exterior domain, there exist $R_{0}>0,$ such that $\{x:|x|\geq R_{0}\}\subset \Omega$. Therefore, just let the support of $v$ be contained in $\{x:|x|\geq R_{0}\},$ any function $v_t$ can be regarded as a function in $S_\mu,$ and, in particular, $v_t \in A_{\mu, k}$ for $t$ small enough.
Now, we assume that $|x|\geq r_0>0$ for any $x\in \Omega$ from the assumption $0\notin \Omega,$ and by the Gagliardo–Nirenberg inequality \cite{weinstein1982nonlinear}, we obtain
\[
E_\rho(u) \geq \frac{1}{2} \|\nabla u\|_{L^2(\Omega)}^2 - \frac{r_0^{-\alpha}C_{p,N}}{p} \mu^{\frac{(1-\gamma_{p})p}{2}}\|\nabla u\|_{L^2(\Omega)}^{p\gamma_{p}}, \quad \forall u \in S_\mu. 
\]
Where $\gamma_{p}=\frac{N(p-2)}{2p}.$\\
Then, for any $\mu > 0$ and $u \in \partial A_{\mu, k_0}$ with $k_0 = \left(\frac{r_0^\alpha p}{4C_{p,N}}\right)^{\frac{2}{p\gamma_{p}-2}} \mu^{-\frac{(1-\gamma_{p})p}{p\gamma_{p}-2}},$ by Lemma \ref{C_{p,N}}, $k_{0}$ denoted as 
\[
k_0=(r_0^\alpha)^{\frac{2}{p\gamma_p-2}}\gamma_p(\frac{p\gamma_p}{4})^{\frac{2}{p\gamma_p-2}}(\frac{C_{0}}{\mu})^{\frac{p-p\gamma_P}{p\gamma_p-2}}C_1,
\] we have
\begin{equation}\label{tag3.2}
\inf_{u \in \partial A_{\mu, k_0}} E_\rho(u) \geq k_0 \left(\frac{1}{2} - \frac{r_0^{-\alpha}C_{p,N}}{p} \mu^{\frac{(1-\gamma_{p})p}{2}} k_0^{\frac{p\gamma_{p}-2}{2}} \right) =\frac{k_{0}}{4}=: \beta > 0, 
\end{equation}
for every $\rho \in \left[\frac{1}{2}, 1\right]$.

Then, if we define \(\xi_{n}:=e^{\gamma\,R\,}\lambda_{n}^{\frac{1}{p-2}}\sum_{i=1}^{k}\xi_{n}^{i},\) for \(L_{n}=-\Delta+\lambda_{n}-\rho_n|x|^{-\alpha}u_{n}^{p-2}\) we have
\[
L_{n}(\xi_{n}-u_{n})=L_n\xi_n=e^{\gamma\,R\,}\lambda_{n}^{\frac{1}{p-2}}\sum_{i=1}^{k}(-\Delta+\tilde{a}_{n})\xi_{n}^{i}\geq 0\quad\text{in $\{d_{n}(x)>R\,\lambda_{n}^{-\frac{1}{2 }}\}$}
\]
and by $($\ref{xilimit}$),$ \(\xi_{n}-u_{n}\geq 0\) on \(\{d_{n}(x)=R\,\lambda_{n}^{-\frac{1}{2}}\}\cup\partial\Omega\). Note that by Lemma \ref{Pn12k}
\[
\left\{d_{n}(x)=R\,\lambda_{n}^{-\frac{1}{2}}\right\}=\bigcup_{i=1}^{k}\partial B_{ R\,\lambda_{n}^{-\frac{1}{2}}}(P^{i}_{n})\subset\Omega
\]
for \(n\geq n(R)\). Then, by $($\ref{5.15}$)$ and the maximum principle of E.Hopf \cite[Theorem 6 in Section 3]{Maximum}
\[
u_{n}\leq\xi_{n}=e^{\gamma\,R}\,\lambda_{n}^{\frac{1}{p-2}}\sum_{i=1}^{k}e^{-\gamma \lambda_{n}^{\frac{1}{2}}\,|x-P^{i}_{n}|}
\]
in \(\{d_{n}(x)\geq R\,\lambda_{n}^{-\frac{1}{2}}\},\) if \(R\) is large and \(n\geq n(R)\). Since by the definition in Lemma \ref{complication} and Lemma \ref{Pn12k},
\[
u_{n}(x)\leq\max_{\Omega}u_{n}=(\tilde{\varepsilon}_{n})^{-\frac{2}{p-2}}\,\leq\,Ce^{ \gamma\,R}\,\lambda_{n}^{\frac{1}{p-2}}\sum_{i=1}^{k}e^{-\gamma\lambda_{n}^{\frac{1}{2}}\,| x-P^{i}_{n}|}
\]
for some \(C>0,\) if \(d_{n}(x)\leq R\,\lambda_{n}^{-\frac{1}{2}},\) we have that $($\ref{estimate'}$)$ holds true in \(\Omega\) with a constant \(Ce^{r\,R}\) and \(n\geq n(R)\). Up to take a larger constant \(C,\) we have the validity of $($\ref{estimate'}$)$ in \(\Omega\) for every \(n\in\mathbb{N}\).
\end{proof}
\end{lemma}
Building on the blow-up analysis above, we shall prove the following results.
\begin{proof}[Proof of Theorem \ref{submass}]
By Proposition \ref{prop3.5}, for any $\rho\in[\frac{1}{2},1],$ there is a sequence $\{\rho_n\}\subset[\frac{1}{2},1]$ such that $\rho_n\to \rho$ and $u_{\rho_n} $ is the positive $(\mu,\rho_n)$ sub-mass mountain pass solution for $\lambda_{\rho_n}\geq0$. We will prove the case where $\rho=1,$ writing for simplicity $u_n:=u_{\rho_n}$ for $\rho_n\to1^-$; the proofs for other cases are similar and left to interested readers.
 Firstly, we show that \(\{\lambda_{n}\}\) is bounded. Suppose, by contradiction, that \(\lambda_{n}\rightarrow+\infty\). By Lemma \ref{Pn12k}, there exist at most \(k\) blow-up limits \(\{P_{n}^{1}\},\cdots,\{P_{n}^{k}\}\) with \(k\leq 2\). In the following, we denote by \(\{v_{n}^{l}:= \lambda_{n}^{-\frac{1}{p-2}} u_{n}(\lambda_{n}^{-1/2}x + P^{l}_{n})\}\) the scaled sequence around \(\{P_{n}^{l}\},\) and by Lemma \ref{complication} we know\(W_0\) is the limit of \(v_{n}^{l},\) for all $l=1,\cdots,k$. Note that for these blow-up points \(\{P_{n}^{1}\},\cdots,\{P_{n}^{k}\},\) by Lemma \ref{complication} it hold
\[
\lambda_{n}^{\frac{1}{2}}\text{dist}(P_{n}^{l},\partial\Omega)\rightarrow+\infty,\quad \forall l=1,\cdots,k.
\]
On the one hand, we can deduce that for any \(R>0,\)
\begin{equation}\label{tag5.1}
\left|\lambda_{n}^{\frac{N}{2}-\frac{2}{p-2}}\int_{\Omega}u_{n}^{2}dx-\sum_{l=1}^{k}\int_{B_{R}(0)}|v_{n}^{l}|^{2}dx\right|\rightarrow+\infty. 
\end{equation}
In fact, from the proof of Proposition \ref{prop3.5}, the $(\mu,\rho_n)$ sub-mass mountain pass sequence $\{u_n\}$ is a subset of $S_\mu$ when $\lambda_n\to\infty,$ then since \(p\in(2+4/N,2^{*}),\) the first term satisfies
\[
\left|\lambda_{n}^{\frac{N}{2}-\frac{2}{p-2}}\int_{\Omega}u_{n}^{2}dx\right|=\lambda_{n}^{\frac{N}{2}-\frac{2}{p-2}}\mu\rightarrow+\infty.
\]
By Lemma Lemma \ref{complication}, we have
\[
\sum_{i=1}^{k}\int_{B_{R}(0)}|v_{n}^{i}|^{2}dx\rightarrow\sum_{i=1}^{k}\int_{B_{R}(0)}|W_0|^{2}dx,
\]
which imply that $($\ref{tag5.1}$)$ holds.

\begin{proposition}\label{mainproposition}
 Let $\alpha,\mu>0,$ $N\geq3,$ $2+4/N<p<2^*,$ $\rho\in[\frac{1}{2},1],$ and $\Omega\subset\mathbb{R}^N$ be an exterior domain with $0\notin\overline\Omega$. Then there is a $\mu_0>0$ such that for any $\mu\in(0,\mu_0),$ equations $($\ref{1.2}$)$-$($\ref{1.1rho}$)$ has a positive solution for some $\lambda> 0.$
\end{proposition}

