The proof of Theorem \ref{thvecchio} relies on a careful analysis of the Morse index of the standard bubble $U$, which shows that it becomes an unstable critical point of \eqref{Sobqintro} as soon as $\lambda_1(D)$ crosses the value $N-1$ (see Theorem 4.3 in \cite{CPP}). Instead when $\lambda_1(D)>N-1$ the bubble $U$ is a stable critical point for $Q$, i.e. it is a strict local minimum. Hence the analysis performed in \cite{CPP} shows that, varying the domains $D\subset \S^{N-1}$ (and hence the cone $\Sigma_D$) the bubble $U$ is degenerate for any cone $\Sigma_{D_1}$ such that $\lambda_1(D_1)=N-1$. This suggests that a bifurcation from the standard bubble could appear when $\lambda_1(D_1)=N-1.$ In other words a branch of nonradial solutions of \eqref{printro} in domains $D$ close to $D_1$ could emanate from the bubble $U$ in $D_1$.

Let $D\subset\mathbb S^{N-1}_+$ be a smooth domain. By $\lambda_j(D)$ with $j\in \N$, we denote the eigenvalues of the Laplacian $\Delta_{\mathbb S^{N-1}}$ on $D$ with Neumann boundary conditions, i.e. we consider the following problem:
\begin{equation}\label{pb_lambda_def1}
\begin{cases}
-\Delta_{\S^{N-1}}Y_j = \lambda_j(D) Y_j & \text{on } D\\
\partial_{\nu_D} Y_j = 0 & \text{on } \partial D \,.
\end{cases}
\end{equation}
It is well known that $-\Delta_{\S^{N-1}}$ has a compact, self-adjoint resolvent in $L^2(D)$ and admits a sequence of eigenvalues 
\begin{equation} \label{lambdabe}
0=\lambda_0(D)<\lambda_1(D)\le \cdots \le \lambda_j(D) \le \cdots\nearrow+\infty
\end{equation} 
(repeated according to their finite multiplicity) and corresponding eigenfunctions $Y_j(\theta) \in L^2(D)$. Here $\theta=(\theta_1,...,\theta_{N-1})$ is the system of coordinates on $D$ induced by the spherical coordinates in $\R^N$. The eigenfunctions $\{Y_j\}_{j\in\mathbb N}$ can be chosen to form a Hilbert basis for $L^2(D)$, they satisfy
\beq\label{def:lapleigbe}
-\Delta_{\S^{N-1}}Y_j(\theta)=\lambda_j(D) Y_j(\theta),\quad \theta\in D, 
\eeq
and 
$$
\int_{D} \langle \nabla_{\mathbb S^{N-1}} Y_j(\theta) , \nabla_{\mathbb S^{N-1}} Y_i(\theta)\rangle d\sigma(\theta) = \lambda_j(D)\delta_{ij}
$$
where we denote by $\nabla_{\mathbb S^{N-1}}$ the gradient on $\mathbb S^{N-1}$.

\section{Bifurcation results}\label{sec3}
\subsection{Spectral analysis}\label{spectan}
Let $D\subset\S^{N-1}_+$ be a smooth domain and assume that the corresponding cone $\Sigma_D$ is a Lipschitz domain. We consider the map $\phi_\alpha, \alpha \in (0,2)$ defined in Section \ref{ss3.1} and the cone $\Sigma_{D_\alpha}$.
Consider the bubble $U\in\mathcal{
D
}^{1,2}(\Sigma_{D_\alpha})$:
\beq\label{bubbledef}
U(x):=c_0(1+|x|^2)^{-\frac{N-2}{2}}\qquad x\in \Sigma_{D_\alpha},
\eeq
where $c_0$ is a constant such that 
$$
-U^{2-2^*}\Delta U=U\qquad \text{in} \quad \Sigma_{D_\alpha}.
$$
The rescaled bubbles will be denoted by $$
U_{s}(x):=s U(s^{\frac{2}{N-2}}x).
$$
\begin{lemma}\label{lemma_spettro}
The operator $L_{U}=U^{2-2^*}\Delta$ on $L^2(U^{2^*-2})$ has discrete spectrum.
\end{lemma}
\begin{proof}
 The proof can be found in \cite{CPP2}.
\end{proof}
To describe the spectrum of the operator $L_{U}$ we need to know the eigenvalues $\lambda_j(D_\alpha), j\in \N$, of problem \eqref{pb_lambda_def1} on $D_\alpha$.
In particular, we recall that the $\lambda_0(D_\alpha)=0$ and the corresponding eigenfunction is constant, while the first positive eigenvalue is $\lambda_1(D_\alpha)$.

Now we are ready to address the following eigenvalue problem that is studied in \cite{CPP2},
\begin{equation}\label{pb_mu_def2}
\begin{cases}
\Delta v+\mu_{\alpha} U^{2^*-2}v=0 &\text{in } {\Sigma_{D_\alpha}}\\
\partial_\nu v=0 &\text{on } \partial{\Sigma_{D_\alpha}}\setminus\{0\} \\
v\in \mathcal{D}^{1,2}(\Sigma_{D_\alpha}), &
\end{cases}
\end{equation}
whose eigenvalue will be denoted by $\mu_{i,\alpha}, i\in\N_+$. The eigenvalue equation in \eqref{pb_mu_def2} can be written by using spherical coordinates, and we can look for solutions by using separation of variables: let $(\rho,\theta)\in(0,+\infty)\times\mathbb S^{N-1}$ the standard spherical coordinates in $\mathbb R^N$ and let $v=R(\rho)Y(\theta)$ be a solution of \eqref{pb_mu_def2} for an eigenvalue $\mu_\alpha$, then it holds that $Y$ is an eigenfunction of \eqref{pb_lambda_def1} on $D_\alpha$ for some $j$, while $R$ satisfies (see \cite{CPP2}, Proposition 2.6)
\begin{equation} \label{SL_eq}
\begin{cases}
(\rho^{N-1}R')'+\rho^{N-1}(-\lambda_j(D_\alpha) \rho^{-2}+\mu_\alpha k_0^{2^*-2}(1+\rho^2)^{-2})R=0 & \text{in }\R_+ \\
\lim_{\rho\to 0}\rho^{N-1}R'(\rho)=0 & \\ 
R(\rho)=o(\rho^{2-N+\epsilon}) \quad \forall\epsilon> 0\text{ as }\rho\to + \infty \,. &

\subsection{Main results}
Let $D_\alpha$ be a domain as in Section \ref{sec2}.
We consider the following problem
\begin{equation}\label{problem}
\begin{cases}
 -\Delta v=v^{2^*-1} &\text{ in }\Sigma_{D_\alpha}\\
 v\in\mathcal{D}^{1,2}(\Sigma_{D_\alpha}).
\end{cases}
\end{equation}
For the reader convenience we recall the notation for the diffeomorphism considered in Section \ref{sec2}.
 Let $\alpha\in(0,\alpha^*)$, where $\alpha^*$ is the maximum value of $\alpha$ such that $\Phi_\alpha(D_1)\subset \S^{N-1}_+$, and consider the map
$$
\phi_{\alpha}:\mathbb S^{N-1}_+\to C_{\alpha}
$$
defined by
$$
\phi_{\alpha}(r,\omega)=(\alpha r,\omega),
$$
where $C_{\alpha}$ is a (spherical) disk centered at the north pole and radius $\alpha\pi/2$. Then we define
$$
\Phi_{\alpha}(\rho,p)=(\rho,\phi_{\alpha}(p)),
$$
where $(\rho,p)\in(0,+\infty)\times D$, and $p=(r,\omega)\in D$ is a point in $D$. The map $\phi_{\alpha}$ induces
$$
\Phi_{\alpha}^*:\mathcal{D}^{1,2}(\Sigma _{D_\alpha})\to\mathcal{D}^{1,2}(\Sigma _{D_1})
$$
defined by $\Phi_{\alpha}^*u=u\circ \Phi_{\alpha}$. We define an operator $\mathcal L_{\alpha}$ acting on $\mathcal D^{1,2}(\Sigma_{D_1})$ by
$$
\mathcal L_{\alpha}(\Phi_{\alpha}^*v)=\Phi_{\alpha}^*(-\Delta v),
$$
for $v\in\mathcal D^{1,2}(\Sigma_{D_{\alpha}})$ (as usual, the operator is defined in the weak sense). This operator can be described more explicitly: it is $-\Delta_{G_{\alpha}}$ defined in \eqref{laplacian_new_metric}, however we won't need this explicit expression in the following.

