ref_dict.thm:global_krt:
\begin{thmx}
\label{thm:global_krt}
Let $\psi$ be an $L^\infty(\mb P)$-bounded function of $\omega(0)$ with $\norm{\psi}_\infty=1$.
For each $d\ge 2$ and $\mb P$-a.e. $\omega$, there exists a function $\krt=\krt_\omega:\Z^d\to\R$ that solves 
\[
L_\omega\krt(x)=\psi(\theta_x\omega)-\bar\psi \quad\text{ for }x\in\Z^d
\]
with the following properties:
\begin{enumerate}[(i)]
\item\label{item:gkrt-2} When $d\ge 5$,\quad $\mb E[\exp(c|\krt(x)/\mu(|x|)|^p)]<C_p$ for any $p\in(0,\tfrac{2d}{3d+2}),x\in\Z^d$;

When $d=3,4$,\; $\mb E[\exp(c|\krt(x)/\mu(|x|)|^p)]<C_p$ for any $p\in(0,\tfrac{2d}{3d+4}),x\in\Z^d$;

When $d=2$,\quad
$\mb E\left[
\exp\big(
c\abs{\tfrac{\krt(x)}{|x|\delta(|x|)}}^p
\big)
\right]\le C_p$ for any $p\in(0,\tfrac13), x\in\Z^d$;

\item\label{item:gkrt-3} $\mb E[\exp(c|\nabla\krt(x)/\delta(|x|)|^q)]\le C_q$ for any $q\in(0,\tfrac{d}{2d+2})$ and $x\in\Z^d$;
\item\label{item:gkrt-2nd-der}
 $\mb E[\exp(c|\nabla^2\krt(x)|^r)]\le C_r$ for any $r\in(0,\tfrac{d}{2})$ and $x\in\Z^d$;
\item\label{item:gkrt-4}(Stationarity properties)
\begin{itemize}
\item When $d\ge 5$,  the field $\{\krt_\omega(x):x\in\Z^d\}$ is stationary (under $\mb P$);
\item When $d\ge 3$, we have $\nabla\krt_\omega(x)=\nabla\krt_{\theta_x\omega}(0)$ for all $x\in\Z^d$, and the field $\{\nabla\krt_\omega(x):x\in\Z^d\}$  is stationary;
\item When $d=2$, we have $\nabla^2\krt_\omega(x)=\nabla^2\krt_{\theta_x\omega}(0)$ for all $x\in\Z^d$, and the field $\{\nabla^2\krt_\omega(x):x\in\Z^d\}$  is stationary.
\end{itemize}
\end{enumerate}
Moreover,  such a corrector $\krt$ is unique up to an additive constant when $d\ge 3$,  and is unique up to an affine transformation when $d=2$.
\end{thmx}

ref_dict.lem:two-scale-exp:
\begin{proposition}
\label{lem:two-scale-exp}
Suppose that $d\geq 3$, $f\in C^{4,\alpha}(\bar\B_1)$, and $g\in C^{6,\alpha}(\partial\B_1)$. Let $u,\bar u$ be the solutions of \eqref{eq:elliptic-dirich}, \eqref{eq:effective-ellip}, respectively. Recall $a,\bar a$ from \eqref{eq:def-a}, \eqref{eq:def-abar}, and let $v^k,\xi,\lambda^k_j, \bar\lambda^k_j,\eta_j,\bar\eta_j$ be as above.  We extend $g$ so that $g=\bar{u}$ on $\bar\B_1$. Let $\bar z:\bar\B_1\to\R$ be the solution of 
\[
\left\{
\begin{array}{lr}
\frac{1}{2}\tr(\bar{a}D^2 \bar{z}(x))=\tfrac{1}{2}\bar{\lambda}^k_i\partial_{kki}\bar{u}(x)-\tfrac{1}{2}\bar\eta_j\partial_j f(x) & x\in\B_1,\\
\bar z(x)=0 &x\in\partial\B_1.
\end{array}
\right.
\]
For $\omega\in\Omega$, $R>1$, and $j,k\in\{1,\ldots,d\}$, let $p^k_j, s_j:\Z^d \rightarrow \R$ be solutions of 
\begin{align}
L_\omega p^k_j(x)&=\lambda^k_j(x)-\bar\lambda^k_j \quad\text{ for }x\in B_R,\label{eq:def-p}\\
L_\omega s_j(x)&=\eta_j(x)-\bar\eta_j \quad\;\text{ for }x\in B_R\label{eq:def-sj},
\end{align}
respectively. Then, for $\omega\in\Omega$, $R>1$, we have
\begin{align}\label{eq:two-scale-further}
&\max_{x\in B_R}\left|u(x)-\bar{u}(\tfrac xR)-\tfrac 1R\bar z(\tfrac xR)\right|\nn\\
&\qquad\lesssim
\tfrac 1{R^2}\norm{\bar u}_{C^6(\bar{\B}_1)}\max_{i,j,k=1}^d
\bigg[1+\left\| |\nabla p^k_j|+|\nabla s_j|+(|\bar\lambda_j^i|+|\bar\eta_j|)|\nabla v^k|\right\|_{d;B_R}
\nn\\
&\qquad
\qquad\qquad\qquad\qquad\quad\;\;\,+\max_{\bar B_R}\left(|\xi|+|v^k|+\tfrac{1}{R}(|p_i^k|+|s_i|)\right)\bigg].
\end{align}
\end{proposition}

