\inf_{p\in\fct_{j-1}}\osc_{B_R}\,(u-p)+A_{j},
\end{equation}
where the terms $A_1=A_1(R)$ and $A_2=A_2(R,r)$ obey the bounds
\begin{align*}
&A_1\le R^{1-\alpha}\norm{\psi}_\infty+R\norm{f}_\infty
\quad\text{ and }\quad
A_1\le R^{1-\alpha}\norm{\psi+f(0)}_\infty+R^{1+\sigma}[f]_{\sigma;B_R},
\\
&A_2\le r^{-\alpha}\norm{\psi}_\infty+\log(\tfrac{R}{r})\norm{f}_\infty
\quad\text{ and }\quad
A_2\le r^{-\alpha}\norm{\psi+f(0)}_\infty+R^\sigma[f]_{\sigma;B_R}
\end{align*}
for any $\sigma\in(0,1]$. In particular, for any $R>1$ and $j\in\{1,2\}$, there holds
\begin{equation}\label{eq:c2}
|\nabla^ju(0)|\lesssim \left(\frac{\tx}{R}\right)^j 
\left(
\norm{u-u(0)}_{1;B_R}+R^2\norm{\psi+f(0)}_\infty+R^{2+\sigma}[f]_{\sigma;B_{R}}
\right).
\end{equation}
\end{thmx}

\begin{thmx}
\label{thm:opt-quant-homo}
Assume {\rm(A1)}, {\rm(A2)}, and {\rm(A3)}. Let $\bar a :=E_{\Q}[\frac{\omega(0)}{\tr\omega(0)}]>0$ and $\bar\psi :=E_{\Q}[\frac{\zeta}{\tr\omega(0)}]$. Suppose $f,g$ are both in $C^4(\R^d)$. Then, for any $\error\in(0,1)$ and $R\ge 2$, there exists a random variable $\ms Y=\ms Y(R,\error, \omega)>1$ with $\mb E[\exp(\ms Y^{{d}/{(2d+2)}-\error})]<C$ such that the solution $u$ of \eqref{eq:elliptic-dirich} satisfies
\[
\max_{x\in B_R}|u(x)-\bar{u}(\tfrac{x}{R})|
\lesssim
\left\{
\begin{array}{rl}
(\log R)^{2+\error}R^{-1}\norm{\bar u}_{C^4(\bar\B_1)}\ms Y &\text{ when }d=2,\\
R^{-1}\norm{\bar u}_{C^4(\bar\B_1)}\ms Y &\text{ when }d\ge 3,
\end{array}
\right.
\]
where $\bar u$ is the solution of the Dirichlet problem \eqref{eq:effective-ellip}.
\end{thmx}

We point out that Theorem \ref{thm:opt-quant-homo} also remains valid for certain finite range dependent environments that are not i.i.d.\ (for example, the ``checkerboard" environment considered in \cite{AL-17}), provided that an Efron--Stein-type concentration inequality holds. Indeed, to obtain the heat-kernel bounds with exponential integrability \cite{GT-22} and the optimal convergence rates \cite{GT-23}, the only requirements are an Efron--Stein-type concentration inequality and a finite range of dependence.
We refer the reader to \cite{CaSu10, AS-14, AL-17, BCDG-18, GPT-19, GT-22, AFL-22, JZ-23,GT-23} for recent developments of quantitative stochastic homogenization of non-divergence form elliptic PDE in both discrete and continuous settings.

\subsection{Main results}

\subsection{Main results}

\begin{proposition}
\label{lem:two-scale-exp}
Suppose that $d\geq 3$, $f\in C^{4,\alpha}(\bar\B_1)$, and $g\in C^{6,\alpha}(\partial\B_1)$. Let $u,\bar u$ be the solutions of \eqref{eq:elliptic-dirich}, \eqref{eq:effective-ellip}, respectively. Recall $a,\bar a$ from \eqref{eq:def-a}, \eqref{eq:def-abar}, and let $v^k,\xi,\lambda^k_j, \bar\lambda^k_j,\eta_j,\bar\eta_j$ be as above. We extend $g$ so that $g=\bar{u}$ on $\bar\B_1$. Let $\bar z:\bar\B_1\to\R$ be the solution of 
\[
\left\{
\begin{array}{lr}
\frac{1}{2}\tr(\bar{a}D^2 \bar{z}(x))=\tfrac{1}{2}\bar{\lambda}^k_i\partial_{kki}\bar{u}(x)-\tfrac{1}{2}\bar\eta_j\partial_j f(x) & x\in\B_1,\\
\bar z(x)=0 &x\in\partial\B_1.
\end{array}
\right.
\]
For $\omega\in\Omega$, $R>1$, and $j,k\in\{1,\ldots,d\}$, let $p^k_j, s_j:\Z^d \rightarrow \R$ be solutions of 
\begin{align}
L_\omega p^k_j(x)&=\lambda^k_j(x)-\bar\lambda^k_j \quad\text{ for }x\in B_R,\label{eq:def-p}\\
L_\omega s_j(x)&=\eta_j(x)-\bar\eta_j \quad\;\text{ for }x\in B_R\label{eq:def-sj},
\end{align}
respectively. Then, for $\omega\in\Omega$, $R>1$, we have
\begin{align}\label{eq:two-scale-further}
&\max_{x\in B_R}\left|u(x)-\bar{u}(\tfrac xR)-\tfrac 1R\bar z(\tfrac xR)\right|\nn\\
&\qquad\lesssim
\tfrac 1{R^2}\norm{\bar u}_{C^6(\bar{\B}_1)}\max_{i,j,k=1}^d
\bigg[1+\left\| |\nabla p^k_j|+|\nabla s_j|+(|\bar\lambda_j^i|+|\bar\eta_j|)|\nabla v^k|\right\|_{d;B_R}
\nn\\
&\qquad
\qquad\qquad\qquad\qquad\quad\;\;\,+\max_{\bar B_R}\left(|\xi|+|v^k|+\tfrac{1}{R}(|p_i^k|+|s_i|)\right)\bigg].
\end{align}
\end{proposition}

\begin{proof}
Let $z:\binB R\to\R$ be a solution of the Dirichlet problem
\[
\left\{
\begin{array}{lr}
L_\omega z(x)=\tfrac{1}{R^2}\left[ \tfrac{1}{2}\bar{\lambda}^k_i\partial_{kki}\bar{u}(\tfrac xR)-\tfrac{1}{2}\bar\eta_i\partial_i f(\tfrac xR)\right] & x\in\inB R,\\
z(x)=0 &x\in\partial\inB R.
\end{array}
\right.
\]
Consider the function
\begin{align}\label{eq:def-w}
&w(x)=u(x)-\bar u(\tfrac{x}{R})-\tfrac 1R z(x)\nn\\
&
+\tfrac{1}{R^2}\left[v^k(x)\partial_{kk}\bar u(\tfrac{x}{R})
-f(\tfrac{x}R)\xi(x)\right]- {\tfrac{1}{2}} \tfrac{1}{R^3}\left[\partial_{kki}\bar{u}(\tfrac{x}{R})p_i^k(x)-\partial_i f(\tfrac{x}{R})s_i(x)\right]
\end{align}
for $x\in\binB R\subset\bar\B_R\cap\Z^d$. Then, applying the formula
\begin{align*}
L_\omega(uv)(x)&=u(x)L_\omega v(x)+v(x) L_\omega u(x)+
\sum_{y:y\sim x}\omega(x,y)[u(y)-u(x)][v(y)-v(x)]\\
&=u(x)L_\omega v(x)+v(x) L_\omega u(x) \\ &\qquad+ \tfrac{1}{2}
a_i(x)\left(\nabla_{e_i}u(x)[v(x+e_i)-v(x-e_i)]
+\nabla_i^2u(x)\nabla_{-e_i}v(x)
\right)
\end{align*}
to the products within \eqref{eq:def-w}, we obtain in $\inB R$ that
\begin{align}
&L_\omega[v^k\,\partial_{kk}\bar u(\tfrac{\cdot}{R})]\nn\\
&=
L_\omega v^k \,\partial_{kk}\bar u(\tfrac{\cdot}{R})
+v^k \, L_\omega[\partial_{kk}\bar u(\tfrac{\cdot}{R})]+\tfrac{1}{2}\lambda^k_i\nabla_{e_i}[\partial_{kk}\bar u(\tfrac{\cdot}{R})]+\tfrac{1}{2}a_i \,\nabla_i^2[\partial_{kk}\bar u(\tfrac{\cdot}{R})]\,\nabla_{-e_i}v^k 
\nn\\
&=\tfrac1{2}(a_k -\bar a_k)\partial_{kk}\bar u(\tfrac{\cdot}{R})+\tfrac{1}{2}\tfrac{1}{R}\lambda^k_i\partial_{kki}\bar u(\tfrac{\cdot}{R})+O(\tfrac 1{R^2})\norm{\bar u}_{C^5(\bar\B_1)}\max_{\binB R}\sum_{k = 1}^d|v^k|,\label{eq:term1}
\end{align}
where we used the fact that $|\lambda^k_i|\lesssim|\nabla v^k|\lesssim\max_{\binB R}|v^k|$ in $\inB R$. Similarly,
\begin{align}
L_\omega[f(\tfrac{\cdot}R)\xi ]
&=(\psi-\bar\psi)f(\tfrac{\cdot}R)+{\tfrac{1}{2}}\tfrac{1}{R}\eta_i\partial_i f(\tfrac{\cdot}{R})+O(\tfrac 1{R^2})\norm{\bar u}_{C^5(\bar\B_1)}\max_{\inB R}|\xi|,\label{eq:term2}\\
L_\omega[\partial_{kki}\bar{u}(\tfrac{\cdot}{R})p_i^k ]
&=(\lambda^k_i-\bar\lambda^k_i)\partial_{kki}\bar{u}(\tfrac{\cdot}{R})
+{\tfrac{1}{2}}\tfrac{1}{R}\partial_{kkij}\bar{u}(\tfrac{\cdot}{R})a_j[p^k_i(\cdot+e_j)-p^k_i(\cdot-e_j)]\nn\\
&+O(\tfrac 1{R^2})\norm{\bar u}_{C^6(\bar\B_1)}\max_{\binB R}\sum_{i,k = 1}^d|p^k_i|,\label{eq:term3}\\
L_\omega[\partial_i f(\tfrac{\cdot}{R})s_i ]
&=(\eta_i-\bar\eta_i)\partial_i f(\tfrac{\cdot}{R})
+{\tfrac{1}{2}}\tfrac{1}{R}\partial_{ij}f(\tfrac{\cdot}{R})a_j [s_i(\cdot+e_j)-s_i(\cdot-e_j)]\nn\\
&+O(\tfrac 1{R^2})\norm{\bar u}_{C^6(\bar\B_1)}\max_{\binB R}\sum_{i=1}^d|s_i|.\label{eq:term4}
\end{align}
Note that 
$\abs{L_\omega[\bar u(\tfrac{\cdot}{R})]-\tfrac1{2R^2}\tr[a D^2\bar{u}(\tfrac{\cdot}{R})]}\lesssim\tfrac1{R^4}\norm{\bar u}_{C^4(\bar\B_1)}$, and 
\begin{align*}
L_\omega u 
=\tfrac1{R^2}f(\tfrac{\cdot}{R})(\psi -\bar\psi)+\tfrac1{R^2}f(\tfrac{\cdot}{R})\bar\psi =\tfrac1{R^2}\big[f(\tfrac{\cdot}{R})L_\omega\xi +
\tfrac1{2}\bar{a}_k\partial_{kk}\bar u(\tfrac{\cdot}{R})\big].
\end{align*}
Then, recalling the definition of $w$ in \eqref{eq:def-w} and writing 
\[
A:=\max_{\binB R}\sum_{i,k=1}^d\left[|\xi|+|v^k|+\tfrac{1}{R}(|p_i^k|+|s_i|)\right],
\]
by \eqref{eq:term1}, \eqref{eq:term2},\eqref{eq:term3}, \eqref{eq:term4},
we have in $\inB R$ that
\begin{align*}
&\abs{L_\omega w } \\
&=
\tfrac1{R^2}\Abs{
f(\tfrac{\cdot}{R})L_\omega\xi +\tfrac1{2}\bar{a}_k\partial_{kk}\bar u(\tfrac{\cdot}{R})-R^2L_\omega[\bar{u}(\tfrac{\cdot}{R})]-{\tfrac{1}{2}}\tfrac{1}{R} \bar{\lambda}^k_i\partial_{kki}\bar{u}(\tfrac{\cdot}{R})+{\tfrac{1}{2}}\tfrac 1R\bar\eta_i\partial_i f(\tfrac{\cdot}{R})
\\
&\qquad+\tfrac1{2}(a_k-\bar a_k)\partial_{kk}\bar u(\tfrac{\cdot}{R})+{\tfrac{1}{2}}\tfrac{1}{R}\lambda^k_i\partial_{kki}\bar u(\tfrac{\cdot}{R})
\nn\\
&\qquad-(\psi-\bar\psi)f(\tfrac{\cdot}{R})-{\tfrac{1}{2}}\tfrac{1}{R}\eta_i\partial_i f(\tfrac{\cdot}{R})+O(\tfrac{1}{R^2})\norm{\bar u}_{C^6(\bar\B_1)}A\\
&\qquad-{\tfrac{1}{2}}\tfrac{1}{R}(\lambda^k_i-\bar\lambda^k_i)\partial_{kki}\bar{u}(\tfrac{\cdot}{R})
-{\tfrac{1}{4}}\tfrac{1}{R^2}\partial_{kkij}\bar{u}(\tfrac{\cdot}{R})a_j[p^k_i(\cdot+e_j)-p^k_i(\cdot-e_j)]\\
&\qquad+{\tfrac{1}{2}}\tfrac{1}{R}(\eta_i-\bar\eta_i)\partial_i f(\tfrac{\cdot}{R})
+{\tfrac{1}{4}}\tfrac{1}{R^2}\partial_{ij}f(\tfrac{\cdot}{R})a_j[s_i(\cdot+e_j)-s_i(\cdot-e_j)]
}
\nn\\
&\lesssim
\tfrac1{R^4}\norm{\bar u}_{C^6(\bar\B_1)}\sum_{i,k=1}^d\left[1+
|\nabla p_i^k|+|\nabla s_i|
+\max_{\binB R}\left(|\xi|+|v^k|+\tfrac{1}{R}(|p_i^k|+ |s_i|)\right)
\right].
\end{align*} 
Thus, by the above inequality, the definition of $w$ from \eqref{eq:def-w}, and the ABP maximum principle, we obtain that
\begin{align}
&\max_{\binB R}|u -\bar u(\tfrac{\cdot}{R})-\tfrac 1R z |\label{eq:ineq1}\\
&\le \max_{\binB R}|w|+
\max_{\binB R}\Abs{\tfrac{1}{R^2}[v^k\partial_{kk}\bar u(\tfrac{\cdot}{R})
-f(\tfrac{\cdot}{R})\xi ]
-{\tfrac{1}{2}}\tfrac{1}{R^3}[\partial_{kki}\bar{u}(\tfrac{\cdot}{R})p_i^k -\partial_i f(\tfrac{\cdot}{R})s_i ]}\nn\\
&\lesssim
R^2\norm{L_\omega w}_{d;\inB R}
+\tfrac1{R^2}\norm{\bar u}_{C^3}\max_{\binB R}\left(|\xi|+|v^k|+\tfrac{1}{R}(|p_i^k|+ |s_i|)\right)\nn
\\&
\lesssim
\tfrac1{R^2}\norm{\bar u}_{C^6}\sum_{i,k=1}^d
\big[1+
\left\||\nabla p_i^k|+|\nabla s_i|\right\|_{d;B_R}+\max_{\binB R}\left(|\xi|+|v^k|+\tfrac{1}{R}(|p_i^k|+|s_i|)\right)
\big].\nn
\end{align}
Furthermore, by \cite[Lemma~30]{GT-23}, 
\[
\max_{\binB R}\abs{z-\bar z(\tfrac{\cdot}{R})}
\lesssim
\tfrac1{R^2}\max_{j,\ell=1}^d(|\bar\lambda_j^\ell|+|\bar\eta_j|)\norm{\bar u}_{C^5(\bar\B_1)}
\sum_{k=1}^d(1+R \norm{\nabla v^k}_{d;\inB R}+\osc_{\binB R}v^k).
\]
This inequality, together with \eqref{eq:ineq1}, yields the claimed bound \eqref{eq:two-scale-further}.
\end{proof}

