			\begin{aligned}
				\left|\mathbb{I}\left(\Sigma\right)\right|\leq\frac{C\left(m\right)\left|\ln\varepsilon_{0}\right|^{82000d\left(\ln\ln\left(2+\JP{t}\right)\right)^{2}}}{\JP{t}^{\frac{1}{3}}},
			\end{aligned}
