		for any $t\in\R$ where $m>0$ and the constant $C\left(m\right)$ only depends on $m$.
	\end{lemma}

By \eqref{infinito}, we have
 \begin{equation}\label{eq:u(t)_int}
 |u(n,t)|\leq\frac{1}{\pi}\left|\int_\Sigma \left(g_1(E,t){\cK}_n(E)+g_2(E,t){\cJ}_n(E)\right) \rho^{\prime}\d E\right|+\varepsilon_0^{\frac{\sigma^2}{10}}\|u(\cdot,t)\|_{\ell^\infty\left(\Z\right)} \ .
 \end{equation}
 To estimate $\|u(\cdot,t)\|_{\ell^\infty\left(\Z\right)}$, it suffices to control the integral term by taking $\varepsilon_{0}$ to be small. Substituting the expression of $\mathcal{S}(u(t))$ into the integral, and recalling the definitions of $g^{\varphi}$ and $g^{\psi}$, we obtain
 \begin{equation}\label{eq:appro_u}
 \begin{aligned}
 &\int_\Sigma \left(g_1(E,t){\cK}_n(E)+g_2(E,t){\cJ}_n(E)\right)\, \rho^{\prime}\d E\\
 =&\frac{1}{2} \int_\Sigma e^{{\rm i}\Omega(E)t} \sum_{k\in\Z} \left(\varphi(k) + \frac{\psi(k)}{{\rm i}\Omega(E)}\right) \left({\cK}_k(E){\cK}_n(E)+{\cJ}_k(E){\cJ}_n(E)\right)\, \rho^{\prime}\d E \\
 &+\frac{1}{2} \int_\Sigma e^{-{\rm i}\Omega(E)t} \sum_{k\in\Z} \left(\varphi(k) - \frac{\psi(k)}{{\rm i}\Omega(E)}\right) \left({\cK}_k(E){\cK}_n(E)+{\cJ}_k(E){\cJ}_n(E)\right)\, \rho^{\prime}\d E \ .
 \end{aligned}
 \end{equation}
 Note that the term $\left({\cK}_k(E){\cK}_n(E)+{\cJ}_k(E){\cJ}_n(E)\right)$ can be expanded as
 \begin{equation}\label{eq:K,J expansions}
 \sum_{k_{\Delta}, n_{\Delta}} \beta_{k,k_{\Delta}} \beta_{n,n_{\Delta}} \cos(k_{\Delta}-n_{\Delta})\rho(E) \ .
 \end{equation}
 Since $m>0$, the factor $\frac{1}{\Omega(E)}= \frac{1}{\sqrt{2+m^2+E}}$ is smooth and bounded on the spectrum of $G_{\theta}+m^2$. By the symmetry of the complex conjugate terms in \eqref{eq:appro_u}, the dispersive decay estimates for both integrals depend on the oscillatory behavior of the phase function. Thus, the problem reduces to establishing the estimates for the oscillatory integral associated with the kernel
 $e^{-{\rm i} t \sqrt{2+m^2+E}}$. For simplicity, we denote
 $$\mathbb{I}(S;k_{\Delta},n_{\Delta},\rho):=\int_{S} \beta_{k,k_{\Delta}}\beta_{n,n_{\Delta}}\cos
 \big((k_{\Delta}-n_{\Delta})\rho\left(E\right)\big)e^{-\mathrm{i}t\Omega\left(E\right)}\cdot\rho^{\prime}\d E, \quad \text{for}\ S\subset\R,$$ 
 and
 $$\mathbb{I}^{J}(S;k_{\Delta},n_{\Delta},\rho):=\int_{S} \beta^J_{k,k_{\Delta}} \beta^J_{n,n_{\Delta}}\cos
 \big((k_{\Delta}-n_{\Delta})\rho\left(E\right)\big)e^{-\mathrm{i}t\Omega\left(E\right)}\cdot\rho^{\prime} \d E, \quad \text{for}\ S\subset\R.$$ 
 Whenever no confusion can arise, we simply write $\mathbb{I}(E)$ and $\mathbb{I}^{J}(E)$ respectively.

\begin{proof}[Proof of Theorem \ref{thm:disper} assuming Lemma \ref{lem:disper-log}]
 By the expansions \eqref{eq:K,J expansions}, we apply Lemma \ref{lem:disper-log} to equation \eqref{eq:appro_u} and derive
 \begin{equation}\label{eq:L infty estimate}
 \begin{aligned}
 &\left|\int_\Sigma \left(g_1(E,t){\cK}_n(E)+g_2(E,t){\cJ}_n(E)\right)\, \rho^{\prime}\d E\right|\\
 \leq&C\left(m\right)\cdot\frac{\left|\ln\varepsilon_{0}\right|^{82000\left(\ln\ln\left(2+\JP{t}\right)\right)^{2}d}}{\JP{t}^{\frac{1}{3}}}\left(\sum_{k\in\Z}\left|\varphi\left(k\right)\right|+\frac{1}{\inf_{E\in\Sigma}\left|\Omega\left(E\right)\right|}\sum_{k\in\Z}\left|\psi\left(k\right)\right|\right),
 \end{aligned}
 \end{equation}
 where the absolute constant $C_{1}$ relates to the estimate of $e^{{\rm i}\Omega\left(\lambda\right)t}$ and so does $C_{2}$ for the estimate related to $e^{-{\rm i}\Omega\left(\lambda\right)t}$. Since $\epsilon_{0}<1$ is small, and by \eqref{eq:u(t)_int}, \eqref{eq:L infty estimate} we deduce
 \begin{equation*}
 \norm{u\left(t\right)}_{\ell^{\infty}\left(\Z\right)}\leq\frac{C\left(m\right)}{1-\varepsilon_0^{\frac{\sigma^2}{10}}}\frac{\left|\ln\varepsilon_{0}\right|^{82000\left(\ln\ln\left(2+\JP{t}\right)\right)^{2}d}}{\JP{t}^{\frac{1}{3}}}\left(\norm{\varphi}_{\ell^{1}\left(\Z\right)}+\frac{1}{\inf_{E\in\Sigma}\left|\Omega\left(E\right)\right|}\norm{\psi}_{\ell^{1}\left(\Z\right)}\right).
 \end{equation*}
 This completes the proof.
 \end{proof}

In the case of $|k_{\Delta}-n_{\Delta}|$ is large, we derive the following bound. 
\begin{lemma}\label{lem:large}
For any $t \in \R$, the following estimate holds, 
\begin{equation*}
 \left|\mathbb{I}^{J}(\Sigma)\right|\leq\frac{18}{\left|k_{\Delta}-n_{\Delta}\right|}\left|\ln \varepsilon_{0}\right|^{2J^{2}d}+\frac{3\Theta_{1}\JP{t}}{\left|k_{\Delta}-n_{\Delta}\right|}\left(\left(1+\varepsilon_{0}^{\frac{1}{4}}\right)^{2}+\varepsilon_{j}^{6\sigma}\right)\left(1+\frac{1}{\Theta_{2}}\right).\\
\end{equation*} 
\end{lemma}
\begin{proof}
By Proposition~\ref{propsana1}, for each $0\leq j\leq J$ we can write
\begin{equation*}
 \Gamma_{j}^{(J)}
 =\mathcal{R}_{j}\cup\Bigl(\,\bigsqcup_{s^{J}_{j}}I_{s^{J}_{j}}\Bigr),
\end{equation*}
where $\mathcal{R}_{j}$ is a finite set of points (possibly empty) and each $I_{s^{J}_{j}}$ is an open interval in $\Gamma_{j}^{(J)}$. Recall that $\rho$ is absolutely continuous. Then
 \begin{equation}\label{eq:Ij-M large}
 \begin{aligned}
 \mathbb{I}^{J}(\Sigma)=&\int_{\inf\Sigma}^{\sup\Sigma}\beta^J_{k,k_{\Delta}} \beta^J_{n,n_{\Delta}}\cos\big((k_{\Delta}-n_{\Delta})\rho\left(E\right)\big)e^{-{\rm i}t\Omega\left(E\right)}\cdot\rho^{\prime} \d E\\
 =&\frac{1}{k_{\Delta}-n_{\Delta}}\sum_{j=0}^{J}\sum_{s_{j}^{J}}\big(\beta^J_{k,k_{\Delta}} \beta^J_{n,n_{\Delta}}\sin\big((k_{\Delta}-n_{\Delta})\rho\left(E\right)\big)e^{-{\rm i}t\Omega\left(E\right)}\big)\Big|_{\inf I_{s_{j}^{J}}}^{\sup I_{s_{j}^{J}}}\\
 &\quad-\frac{1}{k_{\Delta}-n_{\Delta}}\sum_{j=0}^{J}\sum_{s_{j}^{J}}\int_{I_{s_{j}^{J}}}\big(\beta^J_{k,k_{\Delta}} \beta^J_{n,n_{\Delta}}e^{-{\rm i}t\Omega\left(E\right)}\big)^{\prime}\sin\big((k_{\Delta}-n_{\Delta})\rho\left(E\right)\big)\d E.\\
 \end{aligned}
 \end{equation}
 Using Proposition \ref{propsana1} again, we derive the upper bound for connected components of $\bigcup \Gamma_{j}^{(J)}$:
 \begin{equation*}
 \sum_{j=0}^{J}\#\left(s_{j}^{J}\right)\leq \left|\ln \varepsilon_{0}\right|^{2J^{2}d}.
