\section{Transformation to an inhomogeneous density equation}
\label{s:rad}

In this Section we prove Theorem~\ref{t:transform}.
\\
Essentially, we want to move the weight out of the right hand side of \eqref{eq:pde_rad}.
To this end, we perform a change of the independent variable $\rpol$, introducing the function $\rpolf(s)$, $s>0$, and the new unknown $v(s,t)=U(\rpolf(s),t)$. Then clearly
\begin{equation*}
  U_{r}
  =
  v_{s}
  \rpolf_{s}^{-1}
  \,,
  \quad
  U^{m-1}
  \abs{U_{\rpol}}^{p-2}
  U_{\rpol}
  =
  v^{m-1}
  \abs{v_{s}}^{p-2}
  v_{s}
  \abs{\rpolf_{s}}^{-(p-2)}
  \rpolf_{s}^{-1}
  \,.
\end{equation*}
On recalling also
$\partial/\partial\rpol=\rpolf_{s}^{-1}\partial/\partial s$, and on
assuming $\rpolf_{s}>0$, we get that the right hand side of
\eqref{eq:pde_rad} equals
\begin{equation}
  \label{eq:div_new}
  \pder{}{s}
  \big[
  s^{N-1}
  v^{m-1}
  \abs{v_{s}}^{p-2}
  v_{s}
  Y(s)
  \big]
  \rpolf_{s}^{-1}
  \,,
\end{equation}
where
\begin{equation}
  \label{eq:div_coeff}
  Y(s)
  :=
  \ew(\rpolf(s))
  \frac{\rpolf(s)^{N-1}}{s^{N-1}}
  \rpolf_{s}(s)^{-(p-2)-1}
  \,,
  \qquad
  s>0
  \,.
\end{equation}
We choose here $\rpolf$ as a solution to $Y(s)=1$, that is more specifically to the problem
\begin{equation}
  \label{eq:rad_rpolf}
  \rpolf_{s}(s)
  =
  \Big(
  \ew(\rpolf(s))
  \frac{\rpolf(s)^{N-1}}{s^{N-1}}
  \Big)^{\frac{1}{p-1}}
  \,,
  \qquad
  \rpolf(1)
  =
  \rpol_{*}
  \,.
\end{equation}
We prove in Section~\ref{s:app} that for a suitable $\rpol_{*}>0$, depending only on $N$, $p$ and $\exw$, the solution $\rpolf(s)$ is defined and increasing over $(0,+\infty)$ and satisfies
\begin{equation*}
  \lim_{s\to 0+}
  \rpolf(s)
  =
  0
  \,,
  \qquad
  \lim_{s\to +\infty}
  \rpolf(s)
  =
  +\infty
  \,,
\end{equation*}
so that it can be extended to a continuous function over $[0,+\infty)$. Even more, we have $\rpolf\in C^{1}([0,+\infty))$, with $\rpolf_{s}(0)=1$. 
\\
Then \eqref{eq:pde_rad} becomes
\begin{equation*}
  \rpolf^{N-1}
  \ew(\rpolf)
  \rpolf_{s}
  \pder{v}{t}
  =
  \pder{}{s}
  \big[
  s^{N-1}
  v^{m-1}
  \abs{v_{s}}^{p-2}
  v_{s}
  \big]
  \,,
\end{equation*}
that is in view of our choice $Y(s)=1$,
\begin{equation}
  \label{eq:rad_new}
  \rpolf_{s}^{p}
  \pder{v}{t}
  =
  \frac{1}{s^{N-1}}
  \pder{}{s}
  \big[
  s^{N-1}
  v^{m-1}
  \abs{v_{s}}^{p-2}
  v_{s}
  \big]
  \,.
\end{equation}
The right hand side of \eqref{eq:rad_new} can of course be understood as the divergence in the space variable $x$ such that $\abs{x}=s$; we use for the sake of simplicity the old variable names. Then if we define
\begin{equation}
  \label{eq:rad_rw}
  \rw(s)=\rpolf_{s}(s)^{p}
  \,,
\end{equation}
we have the equation \eqref{eq:rad_N}
for the radial function $v$. According to the results on $\rpolf$ outlined above, $\rw$ is a continuos positive function on $[0,+\infty)$.

Next we estimate the asymptotic behavior of $\rw(s)$. We denote by $C_{i}$ constants depending only on $N$, $p$, $\exw$, possibly varying from line to line. We get from \eqref{eq:rad_rpolf} that
\begin{equation*}
  \frac{1}{(\ew(\rpol)\rpol^{N-1})^{\frac{1}{p-1}}}
  =
  \frac{1}{\flopr(\rpol)^{\frac{N-1}{p-1}}}\flopr_{\rpol}(\rpol)
  \,,
\end{equation*}
where $\flopr=\rpolf^{(-1)}$.
Thus, on defining
\begin{equation*}
  \varphi(\rpol)
  :=
  \int_{\rpol}^{+\infty}
  \frac{\di z}{(\ew(z)z^{N-1})^{\frac{1}{p-1}}}
  \,,  
\end{equation*}
we get
\begin{equation}
  \label{eq:rad_rs}
  \varphi(\rpol)
  =
  \int_{\rpol}^{+\infty}
  \frac{1}{\flopr(z)^{\frac{N-1}{p-1}}}\flopr_{z}(z)
  \di z
  =
  \frac{p-1}{N-p}
  \flopr(\rpol)^{-\frac{N-p}{p-1}}
  \,.
\end{equation}
Define the function
\begin{equation}
  \label{eq:rad_H}
  \Hf(r)
  =
  \Big[
  \frac{\exw(\rpol)}{\rpol}
  \big(
  \ew(\rpol)
  \rpol^{N-1}
  \big)^{\frac{1}{p-1}}
  \Big]^{-1}
  \,,
  \qquad
  \rpol>0
  \,.
\end{equation}
Let us calculate, recalling that $\ew(\rpol)=e^{\exw(\rpol)}$,
\begin{equation}
  \label{eq:rad_H_der}
  \begin{split}
    \Hf'(\rpol)
    &=
      -
      \Big[
      \frac{\exw(\rpol)}{\rpol}
      \big(
      \ew(\rpol)
      \rpol^{N-1}
      \big)^{\frac{1}{p-1}}
      \Big]^{-2}
      \big(
      \ew(\rpol)
      \rpol^{N-1}
      \big)^{\frac{1}{p-1}}
      \\
    &\quad
      \times\Big\{
      \Big[
      \frac{\exw'(\rpol)}{\rpol}
      -
      \frac{\exw(\rpol)}{\rpol^{2}}
      \Big]
      +
      \frac{\exw(\rpol)}{(p-1)\rpol}
      \big(
      \ew(\rpol)
      \rpol^{N-1}
      \big)^{-1}
  \\
    &\qquad
      \times\big[
      \exw'(\rpol)
      \ew(\rpol)
      \rpol^{N-1}
      +
      (N-1)
      \ew(\rpol)
      \rpol^{N-2}
      \big]
      \Big\}
      \\
    &=
      -
      \Big[
      \frac{\exw(\rpol)}{\rpol}
      \big(
      \ew(\rpol)
      \rpol^{N-1}
      \big)^{\frac{1}{p-1}}
      \Big]^{-1}
      \Big\{
      \Big[
      \frac{\exw'(\rpol)}{\exw(\rpol)}
      -
      \frac{1}{\rpol}
      \Big]
      \\
    &\quad
      +
      \frac{1}{p-1}
      \Big[
      \exw'(\rpol)
      +
      \frac{N-1}{\rpol}
      \Big]
      \Big\}
      \,.
  \end{split}

