 \\
 &\quad\le
 \tar(\varGamma \log t_{0})^{\frac{1}{p-1}}
 \le
 \tar(\tau)^{\frac{1}{p-1}}
 \,,
 \end{split}
\end{equation}
where the last two inequalities follow trivially from the increasing character of $\tar(\tau)$ and $\varGamma\ge 1$. But since $\rpol_{0}$ has been fixed, this amounts simply to choosing $t_{0}=t_{0}(\rpol_{0})$ so that both \eqref{eq:sss_ups_t0r0} and \eqref{eq:sss_ups_ineqs5} are satisfied; actually it is easily seen that \eqref{eq:sss_ups_t0r0} follows from \eqref{eq:sss_ups_ineqs5}. Note that $r_{0}$, $C_{*}$ and $t_{0}$ are independent of $\varGamma$.

We look for subsolutions in the radial form
\eqref{eq:sss_sup}--\eqref{eq:sss_ups_2}. We use here the same
notation introduced in Section~\ref{s:sss}, and we look at the set
where $\ups>0$. In this Section, the choice of the constants is more
delicate; we find it convenient to establish it from the beginning. In
this connection, let us note that the constant $\tilde\mu_{1}>0$ is
defined in \eqref{eq:sss_ubs_mu1}, $\tilde\mu_{2}>0$ in
\eqref{eq:sss_ubs_mu2}, and $\tilde\mu_{3}\ge 0$ in
\eqref{eq:sss_ubs_mu3}; the $\tilde\mu_{i}$ depend on $p$, $m$,
$\alpha_{1}$, $\alpha_{2}$ only. The constant $\nu_{0}$ is chosen as
in \eqref{eq:sss_ups_c1}. We also introduce for future reference a
given constant $\lambda>0$.
\\
We fix $t_{0}>1$ such that
\begin{equation}
 \label{eq:sss_ubs_t0}
 \begin{split}
 \log t_{0}
 \ge
 \max&\Big\{
 4
 \frac{p-\alpha_{1}}{\alpha_{1}}
 \,,
 \tilde\mu_{4}^{-1}
 \,,
 \frac{2\tilde\mu_{1}(N-1)+\tilde\mu_{3}
 +
 2\tilde\mu_{1}
 \alpha_{2}^{2}}
 {\tilde\mu_{4}}
 \,,
 \\
 &\quad
 \frac{2(\nu_{0}p)^{p-1}}{\tilde\mu_{4}(p+m-3)^{p-2}}
 (
 N
 +
 \alpha_{2}^{2}
 )
 \Big\}
 \,,
 \end{split}
\end{equation}
where
\begin{equation}
 \label{eq:ssb_ups_mu4}
 \tilde\mu_{4}
 =
 2^{-\frac{\alpha_{2}(p-1)}{p-\alpha_{2}}}
 \frac{\tilde\mu_{2}\alpha_{1}}{p-\alpha_{1}}
 >0
 \,. 
\end{equation}
Next we select $\rpol_{0}>0$ such that
\begin{equation}
 \label{eq:ssb_ups_r0}
 \excf(r_{0})
 <
 \min
 \Big\{
 1
 \,,
 \lambda^{p+m-3}
 \,,
 \tilde\mu_{4}
 C_{*}^{p+m-3}
 \log t_{0}
 \Big\}
 \,,
\end{equation}
where we set
\begin{equation}
 \label{eq:ssb_ups_C}
 \begin{split}
 C_{*}^{-(p+m-3)}
 &=
 \max\Big\{
 \lambda^{-(p+m-3)}
 \,,
 2\frac{\tilde\mu_{1}(N-1)+\tilde\mu_{3}}{\excf(\rpol_{0})}
 +
 2\tilde\mu_{1}
 \alpha_{2}^{2}
 \,,
 \\
 &\quad
 \frac{2(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 \frac{1}{\excf(\rpol_{0})}
 (
 N
 +
 \alpha_{2}^{2}
 \excf(\rpol_{0})
 )
 \Big\}
 \,.
 \end{split}
\end{equation}
Clearly we have to show that \eqref{eq:ssb_ups_r0}, \eqref{eq:ssb_ups_C} are compatible, that is that 
\begin{equation}
 \label{eq:ssb_ups_r0_i}
 \excf(\rpol_{0})C_{*}^{-(p+m-3)}
 <
 \tilde\mu_{4}
 \log t_{0}
\end{equation}
can be fulfilled by choosing a small enough $\rpol_{0}$. Indeed, also invoking $\excf(\rpol_{0})<\min\{1,\lambda^{p+m-3}\}$ which is certainly meaningful, we compute from \eqref{eq:ssb_ups_C}
\begin{equation}
 \label{eq:ssb_ups_r0_ii}
 \begin{split}
 \excf(\rpol_{0})C_{*}^{-(p+m-3)}
 &<
 \max\Big\{
 1
 \,,
 2\tilde\mu_{1}(N-1)+\tilde\mu_{3}
 +
 2\tilde\mu_{1}
 \alpha_{2}^{2}
 \,,
 \\
 &\quad
 \frac{2(\nu_{0}p)^{p-1}}{(p+m-3)^{p-2}}
 (
 N
 +
 \alpha_{2}^{2}
 )
 \Big\}
 \le
 \tilde\mu_{4}
 \log t_{0}
 \,,
 \end{split}
\end{equation}
according to our choice of $t_{0}$.
Finally we select
\begin{equation}
 \label{eq:ssb_ups_Gamma0}
 \varGamma
 =
 2^{\frac{\alpha_{2}(p-1)}{p-\alpha_{2}}}
 \frac{\excf(\rpol_{0})}{\log t_{0}}
 \,.
\end{equation}

