ref_dict.thm: monotonicity formula:
\begin{theorem}[Monotonicity formula]\label{thm: monotonicity formula}
			{Let $J\in W^{1,2}(\mathcal{J}_g(B_1(p)))$ be a minimizing harmonic almost complex structure on $B_1(p)\subset M$.} Then, for any $a\in B_{\frac{1}{2}}(p)$ and every $0 < r< R \le\frac12$, there holds
			\begin{equation}\label{eq: monotonicity formula}
				e^{C_0r}r^{2-m}\int_{B_r(a)}|D J|^2dx+\int_{B_R\backslash B_r(a)}\rho^{2-m}|\partial_\rho J|^2dx\le e^{C_0R}R^{2-m}\int_{B_R(a)}|D J|^2dx+C_0(R-r).
			\end{equation}
			where $C_0>0$ is a constant, $\rho=|x-a|$ and $\partial_{\rho}J=DJ\cdot\frac{x-a}{|x-a|}$.
	\end{theorem}

ref_dict.thm:B:
\begin{Thm}[{\cite[Theorem 2]{He-2019}}]\label{thm:B}
		Let {$J\in W^{1,2}_\Lambda(\cJ_g(M))$} be a minimizing harmonic almost complex structure. Then for each $\ep>0$ there exists $C_\ep=C_\ep(m,\Lambda,g,\ep)$ such that for all $r\in(0,1)$ {and $x\in M$,
			\begin{align}\label{eq: Vol estomate}
				\mbox{\rm Vol}(T_r(S^k_{\ep,r}(J))\cap B_1(x))\leq C_\ep r^{m-k-\e}.
		\end{align}}
		Consequently, for any $p\in (2,3)$, there exists a constant $C_0=C_0(m,g,\Lambda,p)>0$ such that
		\[	\max\left\{\int_{B_1(x)}|\nabla J|^p d\vol_g, \int_{B_1(x)}|\nabla^2 J|^{p/2}d\vol_g \right\}\leq \int_{B_1(x)}r_J^{-p}d\vol_g\leq C_0. 
		\]
	\end{Thm}

