 F:=\{y\in B_2(p): \Phi_J(y,2)-\Phi_J(y,\rho)<\delta_2\}$$
 $\rho$-effectively spans a $k$-dimensional affine plane $V$, then $$S^k_{\ep,\delta_2}(J)\cap B_1(p)\subset \exp_p(B_{2\rho}(V)).$$
 \end{proposition}

We need the following lemma to prove proposition \ref{prop: stratum property-1}. This result shows the relationship between almost translation invariant property and almost $(k+1)$-symmetric property. Here and after, $|P\cdot Du|^2=\sum\limits_{i=1}^{k+1}|D_{e_i}u|^2$ with $\{e_i\}_{i=1}^{k+1}$ being an orthonormal basis of a $(k+1)$-dimensional subspace $P$.
 \begin{lemma}\label{lemma: almost translation invariant}
 For any $\ep>0$, there exists $\delta_3=\delta_3(m,g,\Lambda,\ep)>0$ such that if $J\in W^{1,2}_\La(\cJ_g(B_3(p)))$ is a minimizing harmonic almost complex structure on $B_3(p)\subset M$ satisfying
 \begin{align}\label{eq: almost translation invariant}
 \int_{B_1(p)}|P\cdot D J|^2<\delta_3
 \end{align}
 for some $(k+1)$-dimensional subspace $P$, then 
 $S^k_{\ep,\overline{r}}(J)\cap B_{1/2}(p)=\emptyset$ for $\overline{r}=\delta_3^{\frac{1}{2(m-2)}}$. In particular, $0\not\in \exp^{-1}S^k_{\ep,\overline{r}}(J)$, i.e. $p\not\in S^k_{\ep,\overline{r}}(J)$.
 \end{lemma}
 The proof of Lemma \ref{lemma: almost translation invariant} is similar to Naber-Valtorta \cite[Lemma 4.8]{Naber-V-2018}. 
 \begin{proof} 
 Identify $B_3(p)\subset M$ with $B_3(0)\subset \R^m$ via the exponential map $\exp$, and still denote the pullback maps $\exp_p^*J$ and $\exp_p^*g$ by $J$ and $g$, respectively.
 We claim that there is a constant $C(m,\Lambda)>0$ such that for every $x\in B_{1/2}(p)$, there exists $r_x\in[\overline{r},1/2]$ such that
 \begin{equation}\label{eq: lemma 3-11-1}
 \Phi_J(x,r_x)-\Phi_J(x,r_x/2)<\frac{C(m,\Lambda)}{-\log\delta_3}.
 \end{equation}
 Indeed, if this is not true, then for $J\in W^{1,2}_\La(\cJ_g(B_3(p)))$ we may assume by choosing a good radius that $\Phi_J(x,1/2)\le C_0(m,\Lambda)$. Then 
 \begin{align*}
 C_0(m,\Lambda)\geq\Phi_J(x,1/2)&\geq\sum_{i=1}^{-\log\overline{r}+1}(\Phi_J(x,2^{-i})-\Phi_J(x,2^{-i-1}))\geq c(m)C(m,\Lambda),
 \end{align*}
 which is impossible if we let $C(m,\Lambda)=\frac{2C_0(m,\Lambda)}{c(m)}$. This proves the claim.

The next result shows that $\Phi_J$ remains almost constant on all pinched points.
 \begin{lemma}\label{lemma: Phi_J almost const}
 Let $\rho,\eta>0$ be fixed and {$J\in W^{1,2}_\La(\cJ_g(B_3(p)))$} is a minimizing harmonic almost complex structure. Let 
 {$$E:=\sup_{y\in B_2(p)}\Phi_J(y,1).$$ }
 Then there exists $\de_4=\de_4(m,g,\Lambda,\rho,\eta)>0$ such that, if the set 
 $$F:=\{y\in B_2(p):\Phi_J(y,\rho)>E-\delta_4\}$$
 $\rho$-effectively spans a $k$-dimensional affine subspace $L\subset\mathbb{R}^m$, then
 {$$\Phi_J(x,\rho)\ge E-\eta \qquad \text{for all } x\in \exp_p(L\cap B_2(0)).$$}
 \end{lemma}
 \begin{proof}
 We prove by contradiction. Suppose {$J\in W^{1,2}_\La(\cJ_g(B_3))$} is a sequence of minimizing harmonic almost complex structure with
 $$\sup_{y\in B_2(p)}\Phi_{J_i}(y,1)\leq E.$$
 {For each $i\ge 1$, we assume that there exists $\{y^i_j\}_{j=0}^k\subset F_i:=\{y\in B_2(p):\Phi_{J_i}(y,\rho)>E-i^{-1}\}$ spanning $\rho$-effectively a $k$-dimensional affine subspace $L_i\subset\mathbb{R}^m$, and there exists $x_i\in \exp_p(L_i\cap B_2(0))$} such that
 \begin{equation}\label{eq: Phi_J almost const-1}
 \Phi_{J_i}(x_i,\rho)\leq E-\eta.
 \end{equation}
 It follows from the assumption that
 \begin{equation}\label{eq: Phi_J almost const-2}
 \Phi_{J_i}(y^i_j,1)-\Phi_{J_i}(y^i_j,\rho)<1/i,\qquad \text{for all }\,i\ge 1,\, 0\le j\le k. 
 \end{equation}
 Without loss of generality, we assume that for each $0\le j\le k$, 
 $$y^i_j\to y_j,\quad x_i\to x\quad\text{and}\quad L_i\to L$$
 as $i\to \infty$ with {$x\in \exp_pL$} and $J_i\wto J$ in $W^{1,2}$.

Let $\de=\de(m,\Lambda,\ep)$ be fixed. By Lemma \ref{lemma: main covering lemma}, for all $0<r<\delta$,
 \begin{equation}\label{eq: main thm proof-1}
 \mbox{Vol}(T_r(S^k_{\ep,r}(J))\cap B_1(p))\le \mbox{Vol}\Big(T_r\Big(S^k_{\ep,\de }(J)\cap B_1(p)\Big)\Big) \leq C'_\ep r^{m-k}
 \end{equation}
 with $C'_{\ep}=C'_\ep(m,\Lambda,\ep)$. For $r\in[\de,1)$, we have 
 \begin{equation}\label{eq: main thm proof-2}
 \mbox{Vol}\Big(T_r\Big(S^k_{\ep,r}(J)\cap B_1(p)\Big)\Big) \le \mbox{Vol}(T_1( B_1(p)) \leq C_m \le C_m \left(\frac{r}{\de} \right)^{m-k}.
 \end{equation}
 \eqref{eq: main thm proof-1} and \eqref{eq: main thm proof-2} complete the proof of \eqref{eq: Vol estomate-1} for all $0<r<1$. The volume estimate \eqref{eq: Vol estomate-2} follows from \eqref{eq: Vol estomate-1} by noting that $S^k_{\ep}(J)\subset S^k_{\ep, r}(J)$ for any $r>0$.

post_theorem_intro_text:
Note that \eqref{eq: Vol estomate-2} implies that the Minkowski dimension of each $S^k$ satisfies
	\[\dim_{\rm Min} S^k\le k.\]
	In the above theorem, by saying that a subset $A\subset {\mathbb R}^n$ is upper Ahlfors $k$-regular, we mean  there is a constant $M>0$ such that
	\[\mathcal{H}^k(A\cap B_r(x))\le Mr^k\qquad \text{for all }\,x\in A \text{ and } 0<r<\text{diam}(A). \]
	As a standard application of the improved volume estimate \eqref{eq: Vol estomate-1} in Theorem \ref{thm: stratification of MHACS}, we obtain optimal higher regularity for harmonic almost complex structures, which sharpens the regularity result in Theorem \ref{thm:B}. In below, we denote by $L^q_{weak}(B_1(p))$ the space of weakly $L^q$-integrable functions on $B_1(p)$. 

	\begin{theorem}[Regularity estimates on minimizing harmonic almost complex structure]\label{thm: regularity estimates on minimizing HACS}
		There exists a positive constant  $C=C(m,g,\Lambda)$ such that, for any minimizing harmonic almost complex structure $J\in W^{1,2}_\Lambda(\cJ_g(M))$ and $p\in M$, there holds
		\begin{equation}\label{eq: nabla J in L3,infty}
			\begin{aligned}
				{\rm Vol}\Big(\{x\in B_1(p):r|\nabla J|+r^2|\nabla^2 J|>1\}\Big)\leq{\rm Vol}(\{x\in B_1(p):r_J(x)<r\})\leq Cr^3.
			\end{aligned}
		\end{equation}
		In particular,  both $|\nabla^{\ell} J|$ and $r_J^{-\ell}$ have uniform bounds in {$L^{3/\ell}_{weak}(B_1(p))$} for $\ell=1,2$.
	\end{theorem}

	We remark that since $\text{\rm sing}(J)\subset \{x:r_J(x)<r \} $ holds for all $r>0$, the second inequality of \eqref{eq: nabla J in L3,infty}  implies that the singular set of $J$ satisfying  $$\dim_{\rm Min}(\text{\rm sing}(J))\le m-3,$$ which reproduce the Hausdorff dimension estimate of He \cite{He-2019}. We also remark that the estimate of Theorem \ref{thm: regularity estimates on minimizing HACS} is optimal. To see this, consider the case $M={\mathbb R}^4$ and $g=g_0$ is the standard Euclidean metric. Then an energy minimizing harmonic almost complex structure $J$ on ${\mathbb R}^4$ can be viewed as a minimizing harmonic map from ${\mathbb R}^4$ to the sphere $S^2=SO(4)/U(2)$. In this case, Theorem \ref{thm: regularity estimates on minimizing HACS} reduces to the regularity theorem of Naber-Valtorta \cite{Naber-V-2017}. This shows the sharpness of  Theorem \ref{thm: regularity estimates on minimizing HACS}. 

	Now let us explain the strategy we use and the main difficulty we will meet in order to prove the above two theorems. As aforementioned, the main tool is  the robust approach of Naber-Valtorta \cite{Naber-V-2017}.  However, to apply their method, a major technical difficulty we met is the monotonicity formula for minimizing harmonic almost complex structures. More precisely, in Theorem \ref{thm: monotonicity formula} below, we proved the following monotonicity inequality
	\begin{equation}\label{eq: monotonicity formula 1}
		e^{C_0r}r^{2-m}\int_{B_r(a)}|D J|^2dx+\int_{B_R\backslash B_r(a)}\rho^{2-m}|\partial_\rho J|^2dx\le e^{C_0R}R^{2-m}\int_{B_R(a)}|D J|^2dx+C_0(R-r).\tag{MI}
	\end{equation}
	Comparing with that of harmonic maps considered by Naber-Valtorta \cite{Naber-V-2017} or other applications of the Naber-Valtorta theory \cite{Cheeger-N-V-2015,Cheeger-J-N-2021,Edelen-E-2019-TAMS,Fu-Wang-Zhang-2024,GJXZ-2024,Naber-V-2020-JEMS}, in \eqref{eq: monotonicity formula 1}, we do not have an equality, but merely a ``monotonicity inequality with an extra error term". As a result, we have to thoroughly check the whole procedure of \cite{Naber-V-2017}, where a monotonicity equality was used.  It turns out finally that this inequality is sufficient to do the quantitative regularity analysis as that of \cite{Naber-V-2017}. 

	Meanwhile, another two important ingredients of the argument that we establish in this paper  are the important compactness property and unique continuation property for minimizing harmonic almost complex structures, which seems to be unavailable in the literature before this paper. We also explore some basic properties of tangent almost complex structures. These results play a fundamental role in adapting the quantitative $\varepsilon$-regularity theorem of minimizing harmonic maps to minimizing harmonic almost complex structures. We believe that these results also have independent interest and potential applications in other problems. 

	Finally we remark that, in this paper we did not consider the regularity theory for stationary harmonic almost complex structures. The reason is that unlike the case of stationary harmonic maps \cite{Lin-1999-Annals}, the compatibility condition of $J$ with the metric $g$ gives restriction for the class of admissible test functions. Thus it is not clear how to obtain the monotonicity formula from the stationary condition for $J$. It would be interesting to know whether one can actually extend the Naber-Valtorta theory to stationary harmonic almost complex structures. On the other hand, in \cite{He-2023,He-Jiang-2021}, the theory of biharmonic almost complex structures and polyharmonic almost complex structures were studied. Comparing with the case of minimizing biharmonic maps \cite{GJXZ-2024}, it is plausible that one can extend Theorems \ref{thm: stratification of MHACS} and \ref{thm: regularity estimates on minimizing HACS} to biharmonic/polyharmonic almost complex structures. 
	\medskip 

	\textbf{Organization of this paper.} This paper is organized as follows. In Section \ref{sec:partial regularity}, we establish the partial regularity theory, compactness theory and unique continuation property for minimizing harmonic almost complex structures. In Section \ref{sec:quantitative ep regularity}, we use the results from Section \ref{sec:partial regularity} to develop the quantitative $\varepsilon$-regularity theorem. In Section \ref{sec:reifenberg}, we recall the rectifiable Reifenberg theorems from \cite{Naber-V-2017} and in Section \ref{sec:covering lemma}, we adapt the Naber-Valtorta covering argument to minimizing harmonic almost complex structures. In the final section, Section \ref{sec:proofs}, we prove our main results. 

	\medskip

	\textbf{Notation of this paper.}  	
	Through the article, we will use the notation ${\mathbb R}^m={\mathbb R}^{2n}$. The covariant derivative on $M$ is denoted by $\nabla$, while $D, \partial$ denote derivatives with respect to local coordinates. Note that $\nabla$ is equivalent to $D$ when the domain of definition is flat. The integration with the metric measure is written as $\int f d\vol_g$, and $\int f:=\int f dx$ for the integration with the Euclidean measure. The symbol $c_n$ denotes a uniformly bounded dimensional constant.

expanded_sketch:
A proof strategy for Theorem~\ref{thm: stratification of MHACS} is outlined as follows:

- The authors state that the “main tool is the robust approach of Naber-Valtorta \cite{Naber-V-2017},” and that they aim to “apply their method” to minimizing harmonic almost complex structures.

- The main technical difficulty in adapting this method is the monotonicity formula. We first record the following theorem.

\begin{theorem}[Monotonicity formula]\label{thm: monotonicity formula}
			{Let $J\in W^{1,2}(\mathcal{J}_g(B_1(p)))$ be a minimizing harmonic almost complex structure on $B_1(p)\subset M$.} Then, for any $a\in B_{\frac{1}{2}}(p)$ and every $0 < r< R \\le\frac12$, there holds
			\begin{equation}\label{eq: monotonicity formula}
				e^{C_0r}r^{2-m}\int_{B_r(a)}|D J|^2dx+\int_{B_R\backslash B_r(a)}\rho^{2-m}|\partial_\rho J|^2dx\le e^{C_0R}R^{2-m}\int_{B_R(a)}|D J|^2dx+C_0(R-r).
			\end{equation}
			where $C_0>0$ is a constant, $\rho=|x-a|$ and $\partial_{\rho}J=DJ\cdot\frac{x-a}{|x-a|}$.
	\end{theorem}

In place of a monotonicity equality, this provides a “monotonicity inequality with an extra error term” (MI). Consequently, they “have to thoroughly check the whole procedure of \cite{Naber-V-2017}, where a monotonicity equality was used,” and they conclude that “this inequality is sufficient to do the quantitative regularity analysis as that of \cite{Naber-V-2017}.”

- They identify further “important ingredients of the argument” needed for the adaptation: an “important compactness property and unique continuation property for minimizing harmonic almost complex structures,” and they “explore some basic properties of tangent almost complex structures.” These are said to “play a fundamental role in adapting the quantitative $\varepsilon$-regularity theorem of minimizing harmonic maps to minimizing harmonic almost complex structures.”

- The structure of the proof is organized into components: they (i) “establish the partial regularity theory, compactness theory and unique continuation property”; (ii) “develop the quantitative $\varepsilon$-regularity theorem” using those results; (iii) “recall the rectifiable Reifenberg theorems from \cite{Naber-V-2017}”; (iv) “adapt the Naber-Valtorta covering argument to minimizing harmonic almost complex structures”; and (v) “prove our main results,” thereby establishing the main theorem.

