has a huge amount of literature when we consider subcritical drift $b\in L^p(\Om)$, $\Om \subset \mathbb{R}^n$, with $p> n \ge2$. In the subcritical case we may treat the drift term $b\cdot \nabla u$ as a perturbation to $\De u$. The critical case is when $b\in L^n(\Om)$ or $b\in L^{n,\infty}(\Om)$. System \eqref{drifteq} in $\Om \subset \mathbb{R}^3$ with critical drift $b\in L^3(\Om)$ has previously been studied;
See Section 4 of Kim \cite{Kim09}, Theorem 18 in Choe \& Kim \cite{ChoeKim}, and Section 5 of
Amrouche \& Rodríguez-Bellido \cite{AmRB}. They contain estimates similar to \eqref{main1-eq}. A similar result for small $b\in L^{n,\infty}(\Om)$, $n \ge3$, is proved by the authors \cite[Theorem 1.4]{CT1}.

In this paper we extend our previous work for higher dimensions $n \ge 3$ \cite{CT1} to $n=2$. Our main theorem below extends \cite[Theorem 1.5]{CT1} to the dimension 2 case and proves existence of the solutions with higher integrability of the gradient.

The boundary value problem of the perturbed Stokes system \eqref{drifteq} and the corresponding scalar equation \eqref{scalar.eq}
has a huge amount of literature when we consider subcritical drift $b\in L^p(\Om)$, $\Om \subset \R^n$, with $p> n \ge2$. In the subcritical case we may treat the drift term $b\cdot \nb u$ as a perturbation to $\De u$. The critical case is when $b\in L^n(\Om)$ or $b\in L^{n,\infty}(\Om)$. System \eqref{drifteq} in $\Om \subset \R^3$ with critical drift $b\in L^3(\Om)$ has previously been studied;
See Section 4 of Kim \cite{Kim09}, Theorem 18 in Choe \& Kim \cite{ChoeKim}, and Section 5 of
Amrouche \& Rodríguez-Bellido \cite{AmRB}. They contain estimates similar to \eqref{main1-eq}. A similar result for small $b\in L^{n,\infty}(\Om)$, $n \ge3$, is proved by the authors \cite[Theorem 1.4]{CT1}.

\emph{Comments on Theorem \ref{main1}:}
\EN{
\item This theorem extends the higher dimensional result \cite[Theorem 1.5]{CT1} to the dimension 2 case.
In \cite[Theorem 1.5]{CT1} we take $L_0=1/2$. In this paper $L_0$ is specified after \eqref{change-var} and after \eqref{pressure_bound_est}, and is computable.
We skip in this paper the analogous results for small $b$ case (but full range $1<q<\infty$) as in \cite[Proposition 1.3, Theorem 1.4]{CT1}.

Using the same proof scheme we can also prove the following theorem for the scalar equation \eqref{scalar.eq}.
\begin{theorem}\label{th1.2}
 Let $\Om$ be a bounded Lipschtiz domain in $\RR^2$. Assume $b\in L^{2,\infty}(\Omega)$ and $\div b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $G\in L^q(\Om)$, there exists a weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ of \eqref{scalar.eq} such that
\EQ{\label{main2-eq}
\|u\|_{ W^{1,q}(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|G\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above solution $u$ is the unique weak solution in $W^{1,q}_0(\Om)$ without assuming \eqref{main2-eq}.
\end{theorem}

\section{Existence of weak solutions}\label{sec3}
In this section we will prove existence of weak solutions to the perturbed Stokes system \eqref{drifteq} for $b\in L^2$ or $L^{2,\infty}$, $\div b=0$,
\EQ{ \label{eq3.1}
-\Delta u+ b\cdot\nabla u + \nb \pi =f,\quad \div u=0, \quad u|_{\pd \Om}=0,
}
in $\Om \subset \R^2$. When $b\in L^2$, we will further show uniqueness.
Recall that a weak solution $u$ belongs to $ W^{1,2}_{0,\sigma}(\Omega)$ and satisfies a weak form of \eqref{drifteq} similar to \eqref{weak-soln}.
\begin{theorem}[Weak solutions for weak $L^2$ drift]\label{energy}
Let $\Om$ be a bounded Lipschitz domain in $\R^2$.
Assume $b\in L^{2,\infty}(\Omega)^2$ and $\div b=0$.
Then for any $f \in W^{-1,2}(\Omega)^2$,
there exists a weak solution $u\in W^{1,2}_{0,\sigma}(\Omega)$
of \eqref{drifteq}. Moreover, there is $\pi \in L^2(\Om)$ so that $(u,\pi)$ solves \eqref{drifteq} in distributional sense, $\int_\Om \pi=0$, and
\EQ{\label{eq6.1}
\|u\|_{ W^{1,2}(\Omega)}+\|\pi\|_{L^2(\Omega)}\le C\|f\|_{W^{-1,2}(\Om)},
}
for some constant $C=C(\Om)$ independent of $b$.
\end{theorem}

\begin{theorem}[Unique weak solution for $L^2$ drift]\label{energy_2}
Let $\Om$ be a bounded Lipschitz domain in $\R^2$.
Assume $b\in L^{2}(\Om)^2$ has an extension
$\tilde{b}\in L^{2}(\R^2)^2$ with $\div \tilde{b}=0$ in $\R^2$.
Then for any $f \in W^{-1,2}(\Omega)^2$,
there exists a unique weak solution $u\in W^{1,2}_{0,\sigma}(\Omega)$
of \eqref{drifteq}. Furthermore, there is $\pi \in L^2(\Om)$ so that $(u,\pi)$ solves \eqref{drifteq} in distributional sense, $\int_\Om \pi=0$, and
\EQ{\label{eq6.1b}
\|u\|_{ W^{1,2}(\Omega)}+\|\pi\|_{L^2(\Omega)}\le C\|f\|_{W^{-1,2}(\Om)},
}
for some constant $C=C(\Om)$ independent of $b$.
\end{theorem}

Approximating $u$ in $W^{1,2}_{0,\si}(\Om)$ by smooth $u_j$
and using $\div b=0$ conclude that
\EQ{\label{eq3.4}
\int_\Om (b\cdot \nb) u\cdot u = \lim_{j \to \infty} \int_\Om (b\cdot \nb) u_j\cdot u_j = \int_\Om b\cdot \nb(\frac12|u_j|^2) = 0.
}
 Thus we get the coercivity of this bilinear form, indeed,
\EQ{
\mathcal{B}(u,u)=\|\nabla u\|_{L^2(\Om)}^2, \quad \forall u\in W_{0,\sigma}^{1,2}(\Om).
}
Therefore, by Lax-Milgram theorem, for any $f \in W^{-1,2}(\Omega)^n\subset (W_{0,\sigma}^{1,2}(\Om)^n)^*$, there exists a unique $u\in W_{0,\sigma}^{1,2}(\Om)$ such that
\EQ{
\mathcal{B}(u,v)=\langle f,v\rangle,\quad \forall v\in W_{0,\sigma}^{1,2}(\Om).
}
This is the weak form of \eqref{drifteq} and hence
$u$ is the unique weak solution. By taking $v=u$, we get $\norm{u}_{W^{1,2}_0(\Om)} \le C\norm{f}_{W^{-1,2}(\Om)}$.
Lastly, we apply Lemma \ref{pressure} with $q=2$ (and using that $\Om$ is bounded and Lipschitz) to get an associated pressure $\pi\in L^2_0(\Om)$ that satisfies the bound.
\end{proof}

\begin{theorem}\label{theoremL2wolf}
Assume $p>1$ and $V\subset \R^n$, $n\ge2$, is a bounded Lipschitz domain with Lipschitz constant less than a sufficiently small $L_0(p,n)>0$.
Then the problem \eqref{Stokes} has a unique weak solution pair $(v,\pi)$ with $v \in W^{1,p}_{0,\si}(V)$ and $\pi \in L^p_0(V)$ for given $f=\div \FF$, $ \FF \in L^p(\Om)^{n\times n}$, and the local pressure projection in $V$,
\[
\mathcal{W}_{p,V}(\div \FF)=\nabla\pi,
\]
satisfies the following inequality
\EQ{\label{pWolfbound}
\|\pi\|_{L^p(V)}\le c_1\|\FF\|_{L^p(V)},
}
where $c_1=c_1(n,V,p)$.
\end{theorem}

\begin{theorem}\label{Capriori}
Let $\Om$ be a bounded Lipschitz domain in $\R^2$ with Lipschitz constant $L \le L_0$, where $0<L_0<1$ is a sufficiently small constant. Assume $b\in L^{2,\infty}(\Omega)^2$ and $\div b=0$.
Assume further $b \in L^{2+\delta}$ for some $\delta>0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $2<p<p_0$,
any weak solution $u\in W^{1,2}_{0,\si}(\Omega)$ of \eqref{drifteq} with force $\GG\in L^p(\Om)^{2\times 2}$
is in $ W^{1,p}(\Omega)$ and
\EQ{\label{eq5.1}
\|u\|_{W^{1,p}(\Omega)}\le c\|u\|_{W^{1,2}(\Omega)}+ c\|\GG\|_{L^p(\Omega)}
}
for some constant $c(\Omega,\|b\|_{L^{2,\infty}})>0$.
\end{theorem}

