 \lambda_{k}^{(p)} = -M^\delta (c_{2k-1}-\frac{1}{\delta}) \prod_{j \neq 2k-1}^{p} (c_{j} - c_{2k-1}), \quad k = 1, 2, \dots, \left[\frac{p+1}{2}\right].
 \end{align}
Then for $n = p+1$ is even, we have $\left[\frac{p+1}{2}\right] = \left[\frac{p+2}{2}\right]$ and for $k = 1, 2, \dots, \left[\frac{p+1}{2}\right]$, we have
 \begin{align}
 \mathcal{L}_{p+1,2k-1} =(\mathcal{R}(Q_{c_{2k-1}}) + c_{p+1}) \mathcal{S}_{p}^{\prime\prime}(Q_{c_{2k-1}}).
 \end{align}
 By Lemma \ref{lem3.2}, the operator $(\mathcal{R}(Q_{c_{2k-1}}) + c_{p+1})$ has an eigenvalue $c_{p+1} - c_{2k-1} > 0$, with continuous spectrum $(c_{p+1}, +\infty)$ whose generalized eigenfunctions are not in $L^{2}(\mathbb{R})$. Therefore, the $\left[\frac{p+2}{2}\right]$-th negative eigenvalues of $\mathcal{L}_{p+1,2k-1}$ is
 \begin{align}\label{4.50}
 \lambda_{k}^{(p+1)}= -M^\delta (c_{2k-1}-\frac{1}{\delta}) \prod_{j \neq 2k-1}^{p+1} (c_{j} - c_{2k-1}), \quad k = 1, 2, \dots, \left[\frac{p+1}{2}\right].
 \end{align}
For the case where $n = p+1$ is odd, we have $\left[\frac{p+1}{2}\right] + 1 = \left[\frac{p+2}{2}\right]$. The first $\left[\frac{p+1}{2}\right]$ negative eigenvalues of $\mathcal{L}_{p+1}$ are given by expression (\ref{4.50}). We now compute the final negative eigenvalue. Consider
\begin{align}
 \mathcal{L}_{p+1,p+1} =\left( \mathcal{R}(Q_{c_{p+1}}) + c_{j} \right) \tilde{S}_{p}^{\prime\prime}(Q_{c_{p+1}})
\end{align}
where $\tilde{S}_{p}$ denotes the action with wave speed $c_j$ in $S_p$ replaced by $c_{p+1}$ for some $1 \leq j \leq p$. By assumption (\ref{4.48}), the discrete eigenvalue of $\tilde{S}_{p}^{\prime\prime}(Q_{c_{p+1}})$ is
\begin{align}
 -M^\delta (c_{p+1}-\frac{1}{\delta})\prod_{l \neq j}^{p} (c_l - c_{p+1}).
\end{align}
The operator $\mathcal{R}(Q_{c_{p+1}}) + c_j$ has eigenvalue $c_j - c_{p+1} < 0$ by Lemma \ref{lem3.2}, with continuous spectrum $(c_j, +\infty)$ whose generalized eigenfunctions are not in $L^2(\mathbb{R})$. Therefore, the last negative eigenvalue of $\mathcal{L}_{p+1}$ is
\begin{align*}
 \lambda_{\left[\frac{p+2}{2}\right]}^{(p+1)} = -M^\delta (c_{p+1}-\frac{1}{\delta}) \prod_{l=1}^{p} (c_l - c_{p+1}).
\end{align*}
The proof of Theorem \ref{th1.3} is completed by combining the eigenvalue expressions.
\end{proof}

post_theorem_intro_text:
Since the stability result in \cite{MS} coincides with orbital stability theorem in \cite{GSS} for $n=1$, we obtain the following corollary regarding the orbital stability of ILW soliton solutions.
\begin{cor}
The single soliton solution of the ILW equation is orbital stable in $H^{\frac{1}{2}}(\mathbb{R})$.
\end{cor}
\begin{re}
For $n \geq 2$, it should be noted that the stability result in \cite{MS} aligns with the notion of orbital stability in \cite{GSS} when the stability framework of \cite{MS} is suitably extended. In Hamiltonian systems, invariant functionals (i.e., integrals of motion) generate Hamiltonian flows that commute with the original time evolution.
\end{re}

Then we will provide a more precise description of the orbital stability of the double solitons to the ILW equation.

\begin{theorem}[\textbf{Orbital stability of double solitons}]\label{thm1.2}
	The double solitons $U^{(2)}_{c_1,c_2}(t,x;x_1,x_2)$ of ILW equation (\ref{ILW}) with $0<c_1<c_2$ are orbitally stable in $H^1(\mathbb{R})$ in the following sense.
There exist parameters $\epsilon_0$ and $A_0$, depending on $c_1$ and $c_2$, if there exists $\epsilon \in (0,\epsilon_0)$ such that for any $u_0\in H^1(\mathbb{R})$,
\begin{align}\label{u02}
	\bigl\lVert u_0 - U^{(2)}_{c_1,c_2}(0;0,0) \bigr\rVert_{H^1(\mathbb{R})} < \epsilon,
\end{align}
then there exist $x_1(t), x_2(t) \in \mathbb{R}$, such that the corresponding solution $u(t,x)$ of the ILW equation (\ref{ILW}) with the initial data $u(0)=u_0$ satisfies $u_t \in C([0,\infty),H^1(\mathbb{R}))$ and
\begin{align}\label{1.22}
	\sup_{t\in (0,\infty)}|\!|u(t)-U^{(2)}_{c_1,c_2}(t,x;x_1,x_2)|\!|_{H^1(\mathbb{R})}<A_0\epsilon,
\end{align}
with
\begin{align}
	\sup_{t\in (0,\infty)}(|x_1'(t)|+|x_2'(t)|)\leq CA_0\epsilon.
\end{align}
\end{theorem}

Moreover, something is interesting is that one can express the negative eigenvalues of the isoinertial operator $\mathcal{L}_n$ in terms of the wave speeds $\{c_j\}^n_{j=1}$ as follows.
\begin{theorem}[\textbf{The negative eigenvalues of $\mathcal{L}_n$}]\label{th1.3}
	The linearized operator $\mathcal{L}_{n}$ about the $n$-soliton solution possesses exactly $\left\lfloor\frac{n+1}{2}\right\rfloor$ negative eigenvalues $\lambda_{k}$, where $k=1,2,\cdots,\left\lfloor\frac{n+1}{2}\right\rfloor$ and $\lfloor x\rfloor$ denotes the floor function. Furthermore, the negative eigenvalues of $\mathcal{L}_n(n\geq 1$)  have the following expression
	\begin{align}\label{negetive}
		\lambda_{k} = -M^\delta_k (c_{2k-1}-\frac{1}{\delta})\prod_{ j\neq 2k-1}^{n}(c_{j}-c_{2k-1}),\quad k=1,2,\cdots,\left\lfloor\frac{n+1}{2}\right\rfloor,
	\end{align}
	where $M^\delta_k$ are positive constants independent of the wave speeds $c_1,\cdots, c_n$.
\end{theorem}
