\begin{lemma}\label{Vaughan's identity}
 Let $\Psi: \mathbb{F}_q[x] \to \mathbb{C}$ be a function with $|\Psi(f)| \le 1$. If $u$ and $v$ are two integers in $[1, n]$ with $u+v>n$, then \[ \left|\sum_{f \in \mathcal{M}(n)} \Lambda(f)\Psi(f)\right| \ll n\Sigma_1 + n^{5/2}q^{n-(u+v)/2}\Sigma_2^{1/2}, \] with \[ \Sigma_1 = \sum_{\deg g \le u+v} \left|\sum_{\deg h = n - \deg g} \Psi(gh)\right| \] and \[ \Sigma_2 = \max_{v \le i \le n-u} \max_{\deg g_1 = n-i} \sum_{\deg g_2 = n-i} \left|\sum_{\deg h = i} \Psi(hg_1)\overline{\Psi(hg_2)}\right|, \] where both sums above are taken over monic polynomials.
\end{lemma}
In particular, it suffices to obtain upper bounds on $\Sigma_1$ and $\Sigma_2$. Using polarization, we will reduce the computation to computing character sums on multilinear polynomials.

\begin{lemma}\label{Polarization result}
 Let $P_1(f), \dots, P_m(f)$ be polynomials in the coefficients of a $k$-degree polynomial $f$. Let $j=\max(\deg P_1, \dots, \deg P_m)$ and $S$ denote the set of indices $i \in [1, m]$ for which $\deg P_i = j$. Then we have \[ \left|\sum_{\deg f = k} \prod_{i=1}^m \psi_i(P_i(f))\right| \le \left(q^{k}\left|\sum_{x \in (\mathbb{F}_q^k)^j} \prod_{i \in S} \psi_i(P_i^{\circ}(x)) \right|\right)^{1/2^j},\] where the sum above is over monic $f$. 
\end{lemma}
\begin{proof}
 Note that \begin{align*}
 \left|\sum_{\deg f = k} \prod_{i=1}^m \psi_i(P_i(f))\right|^2 & = \sum_{\deg f = k} \sum_{\deg h < k} \prod_{i=1}^m \psi_i(P_i(f+h))\overline{\psi_i(P_i(f))} \\ &= \left|\sum_{\deg f = k} \sum_{\deg h < k} \prod_{i=1}^m \psi_i(\Delta_h P_i(f))\right| \\ &\le \sum_{\deg f = k}\left| \sum_{\deg h < k} \prod_{i=1}^m \psi_i(\Delta_h P_i(f))\right|. 
 \end{align*}
 Repeatedly squaring in this fashion, we obtain that at the $j$th squaring, \[ \left|\sum_{\deg f = k} \prod_{i=1}^m \psi_i(P_i(f))\right|^{2^j} \le q^{k} \left|\sum_{h_1, \dots, h_j} \prod_{i \in S} \psi_i(P_i^{\circ}(h_1, \dots, h_j)) \right|, \] as desired. 
\end{proof}
Recall that the purpose of this application of polarization is to obtain upper bounds on the sums $\Sigma_1$ and $\Sigma_2$ from Lemma \ref{Vaughan's identity} upon selecting $\Psi(f) = \prod_{i=1}^m \psi_i(R_i(f))$. Indeed, we may consider the following choices of $P_i$, which are both polynomials in the coefficients of their arguments. 
\begin{itemize}
 \item For $\Sigma_1$, let $(P_i)_g(f)=R_i(fg)$ for all $f \in \mathcal{M}(n-\deg g)$ and $1 \le i \le m$. 
 \item For $\Sigma_2$, let $(P_i)_{g_1, g_2}(f) = R_i(g_1f) - R_i(g_2f)$ for all $f \in \mathcal{M}(n - \max(\deg g_1, \deg g_2))$ and $1 \le i \le m$. 
\end{itemize}

\subsection{Exponential sums of multilinear polynomials}
Note that Lemma \ref{Polarization result} requires us to only work with exponential sums of multilinear polynomials going forward. In order to obtain useful bounds on the exponential sums of multilinear polynomials, we require a corollary of a recent result on the comparison between the analytic rank and partition rank of tensors.
\begin{defn}
 The \emph{analytic rank} $\operatorname{AR}(T)$ of $T$ is defined as \[ \operatorname{AR}(T) := -\log_q\left(\frac{1}{q^n} \sum_{(x_1, \dots, x_n) \in \mathbb{F}_q^n} \psi_0(T(x_1, \dots, x_n))\right). \] The \emph{partition rank} $\operatorname{PR}(T)$ of $T$ is defined as the smallest number $r$ such that $T$ can be written as the sum of $r$ reducible homogeneous polynomials. 
\end{defn}

\begin{lemma}\label{char sums and ranks}
For all polynomials $f$ of degree $n<p$, $\operatorname{PR}(f^{\circ}) \ge \operatorname{rank}(f)$. Consequently, for any tuple $(P_1, \dots, P_m)$ of polynomials and nontrivial tuple $(\psi_1, \dots, \psi_m)$ of additive characters on $\mathbb{F}_q$, there exists a constant $c>0$ dependent only on $\max(\deg P_1, \dots, \deg P_m)$ such that \[ \left|\sum_{x \in (\mathbb{F}_q^k)^j} \prod_{i \in S} \psi_i(P_i^{\circ}(x)) \right| \le q^{n-c \cdot \operatorname{rank}((P_i)_{i \in S})}, \] where $j = \max(\deg P_1, \dots, \deg P_m)<p$ and $S$ is the set of indices $1 \le i \le m$ for which $\deg P_i = j$. 
\end{lemma}
\begin{proof}
Note that because $n<p$, the degree $n$ homogeneous component of $f$ is given by $\frac{1}{n!}f^{\circ}(x, \dots x)$. Thus, \[ \operatorname{rank}(f) = \operatorname{rank}(f^{\circ}(x, \dots x)) \le \operatorname{PR}(f^{\circ}), \] proving the first part. Let $L$ denote the set of nontrivial $\mathbb{F}_q$-combinations of $\{P_i: i \in S\}$. Observe that \begin{align*} \left|\sum_{x \in (\mathbb{F}_q^k)^j} \prod_{i \in S} \psi_i(P_i^{\circ}(x)) \right| = \left|\sum_{x \in (\mathbb{F}_q^k)^j} \psi_0\left(\sum_{i \in S} \varphi(\psi_i)P_i^{\circ}(x)\right) \right| \le \max_{P \in L} \left|\sum_{x \in (\mathbb{F}_q^k)^j} \psi_0\left(P^{\circ}(x)\right) \right| \end{align*} and \begin{align*} \max_{P \in L} \left|\sum_{x \in (\mathbb{F}_q^k)^j} \psi_0\left(P^{\circ}(x)\right) \right| &\le \max_{P \in L} q^{n-\operatorname{AR}(P^{\circ})} \\ &\le \max_{P \in L} q^{n-c \cdot \operatorname{PR}(P^{\circ})} \\ &\le \max_{P \in L} q^{n-c \cdot \operatorname{rank}(P)} \\ &= q^{n-c \cdot \operatorname{rank}((P_i)_{i \in S})}, \end{align*} which proves the second part.
\end{proof}

\section{Proof of main result}\label{main proof}
We are ready to prove our main result.
\begin{proof}[Proof of Theorem \ref{main theorem}]
By the orthogonality of characters, we have \[ I_n(R_1, \dots, R_m) = \frac{1}{q^m} \sum_{(\psi_1, \dots, \psi_m)} \sum_{f \in \mathcal{P}(n)} \prod_{i=1}^m \psi_i(R_i(f)). \] Thus, \[ I_n(R_1, \dots, R_m) - \frac{I(n)}{q^m} = \frac{1}{q^m} \sum_{(\psi_1, \dots, \psi_m) \neq \mathbf{0}} \sum_{f \in \mathcal{P}(n)} \prod_{i=1}^m \psi_i(R_i(f)). \] We may rewrite the above as \begin{align*} \sum_{f \in \mathcal{P}(n)} \prod_{i=1}^m \psi_i(R_i(f)) &= \sum_{f \in \mathcal{M}(n)} \mathbf{1}_{f \in \mathcal{P}(n)}\prod_{i=1}^m \psi_i(R_i(f)) \\ &= \sum_{f \in \mathcal{M}(n)} \Lambda(f) \prod_{i=1}^m \psi_i(R_i(f)) + O\left(\sum_{f \in \mathcal{M}(n)} \mathbf{1}_{\Lambda(f) > 1}\right) \\ &= \sum_{f \in \mathcal{M}(n)} \Lambda(f) \prod_{i=1}^m \psi_i(R_i(f)) + O(I(n)-I(n/2)) \\ &= \sum_{f \in \mathcal{M}(n)} \Lambda(f) \prod_{i=1}^m \psi_i(R_i(f)) + O(q^{n/2}/n) \end{align*} Therefore, \[ \left|I_n(R_1, \dots, R_m) - \frac{I(n)}{q^m}\right| \le \sum_{(\psi_1, \dots, \psi_m) \neq \mathbf{0}} \left|\sum_{f \in \mathcal{M}(n)} \Lambda(f)\prod_{i=1}^{m} \psi_i(R_i(f))\right| \] by the triangle inequality. By Lemma \ref{Vaughan's identity}, we have for all nontrivial tuples $(\psi_1, \dots, \psi_m)$ of additive characters on $\mathbb{F}_q$ that
\[ \left|\sum_{f \in \mathcal{M}(n)} \Lambda(f)\prod_{i=1}^m \psi_i(R_i(f))\right| \ll n\Sigma_1 + n^{5/2}q^{n-(u+v)/2}\Sigma_2^{1/2} \] 
for all choices of $u$ and $v$ with $u+v<n$, where 
\[ \Sigma_1 = \sum_{\deg g \le u+v} \left|\sum_{\deg h = n - \deg g} \prod_{i=1}^m \psi_i((P_i)_g(h)) \right| \] 
and 
\[ \Sigma_2 = \max_{v \le k \le n-u} \max_{\deg g_1 = n-k} \sum_{\deg g_2 = n-k} \left|\sum_{\deg h = k} \prod_{i=1}^m \psi_i((P_i)_{g_1, g_2}(h)) \right|. \] 
By Lemma \ref{Polarization result}, we have 
\[ \Sigma_1 \le \sum_{0 \le d \le u+v} q^{\frac{n-d}{2^j}} \sum_{\deg g = d} \left|\sum_{x \in (\mathbb{F}_q^d)^{n-d}} \prod_{i \in S} \psi_i((P_i)_g^{\circ}(x))\right|^{1/2^j} \] 
and
\[ \Sigma_2 = \max_{v \le k \le n-u} \max_{\deg g_1 = n-k} \sum_{\deg g_2 = n-k} q^{\frac{k}{2^j}}\left|\sum_{x \in (\mathbb{F}_q^{n-k})^k} \prod_{i \in S} \psi_i((P_i)_{g_1, g_2}^{\circ}(x))\right|^{1/2^j}. \] 
Thus, by Lemma \ref{char sums and ranks}, we have 
\[ \Sigma_1 = \sum_{0 \le d \le u+v} \sum_{\deg g = d} q^{(n-d)+\frac{n-d}{2^j}-c \cdot \operatorname{rank}(((P_i)_g)_{i \in S})} \] 
and 
\[ \Sigma_2 = \max_{v \le k \le n-u} \max_{\deg g_1 = n-k} \sum_{\deg g_2 = n-k} q^{k-c \cdot \operatorname{rank}(((P_i)_{g_1, g_2})_{i \in S})}. \] The desired result follows. 
\end{proof}

