	\section{Sketch of the proof of Theorem \ref{thm:main}}\label{ideas}
	In this section, we present some
	key ideas and the proof of Theorem \ref{thm:main}.

	Note that the coordinate $\theta$ in TC flow is defined on $\mathbb{S}^{1}$, and it is natural to applying Fourier transform on the $\theta$ direction. Then taking Fourier transform for (\ref{ini1})-(\ref{boundary condition}) with respect to $\theta$, we obtain
	\begin{equation}\label{eq:fourier}
		\left\{
		\begin{array}{lr}
			\partial_{t}\widehat{n}_{k}-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{n}_{k}+(1+\frac{1}{r^{2}})ik\widehat{n}_{k}+\frac{1}{Ar}\sum_{l\in\mathbb{Z}}i(k-l)\partial_{r}\widehat{\varphi}_{l}\widehat{n}_{k-l}\\-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}il\widehat{\varphi}_{l}\partial_{r}\widehat{n}_{k-l}=-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}\partial_{r}(r\widehat{n}_{l}\partial_{r}\widehat{c}_{k-l})-\frac{ik}{Ar^{2}}\sum_{l\in\mathbb{Z}}i(k-l)\widehat{n}_{l}\widehat{c}_{k-l},\\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{c}_{k}+\widehat{n}_{k}-\widehat{c}_{k}=0,\\
