\begin{remark}
The Taylor-Couette flow has been successfully implemented in biomedical devices such as the  VFPR, where its unique vortex structure significantly enhances hemocompatibility. It reduces platelet activation and protein adsorption by promoting the accumulation of cellular components in the vortex center, thereby lowering the risk of thrombogenesis and improving the safety of extracorporeal circulation systems \cite{K2003, GG1999}. 
Increased platelet adhesion or protein adsorption on the device surface can induce platelet aggregation or thrombosis, which  poses a huge threat to human life. The above theorem shows  that sufficiently strong flow can prevent the aggregation or blow-up from occurring. As shown in \cite{K2003} at shear rates $ G\geq
	550 s^{-1}$, laminar flow resulted in a significantly higher platelet drop and PF4 release than Taylor vortex flow. Here $G$ is similar as $A$. In fact, let $w_1$ and $w_2$ denote the angular velocity of the
inner or outer cylinder, where  $w_1r_1=v_\theta|_{r_1}=A(r+\frac1r)|_{r_1}$ and $w_2r_2=v_\theta|_{r_2}=A(r+\frac1r)|_{r_2}$. Then
\begin{eqnarray*}
G=\frac{2(r_1^2w_1+r_2^2w_2)}{r_2^2-r_1^2},\end{eqnarray*}
which implies $G=2A\frac{3+R^2}{R^2-1}$ when $r_1=1, r_2=R.$ It is interesting to estimate the value of $A$ in mathematics, which will be investigated in our future work.
	\end{remark}

	\begin{remark}
		Compared with previous results on planar flows (e.g., Couette or Poiseuille flows) usually set in Cartesian coordinates, to our best knowledge, the above result gives the first rigorous proof of global regularity for the Patlak-Keller-Segel-Navier-Stokes system driven by a non-planar shear flow, specifically the Taylor-Couette flow in an annular domain. One of main difficulties lies in the $T_1$ term of the estimates of $n$:
		\begin{equation*}
			\begin{aligned}
				\|n\|_{Y_{a}}
				&\leq C\Big( \sum_{k\neq 0, k\in\mathbb{Z}}\|n_{k}(0)\|_{L^{2}}+\sum_{k\neq 0, k\in\mathbb{Z}}A^{\frac16}|k|^{-\frac13}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}kf_{1}\|_{L^{2}L^{2}}+\cdots\Big)\\
				&=:C\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\|n_{k}(0)\|_{L^{2}}+T_{1}+\cdots \Big).
			\end{aligned}
		\end{equation*}
where
\begin{equation*}
				\begin{aligned}
					\|f_{1}\|_{L^{2}}&\leq \frac{C(R)}{A}\Big(\sum_{l\in\mathbb{Z}\backslash\{0,k\}}|l|^{-\frac12}\|w_{l}\|_{L^{2}}\|n_{k-l}\|_{L^{2}}+\cdots\Big)
				\end{aligned}
			\end{equation*}
(see \eqref{nk Xa} and \eqref{T2 0}). We estimate the norm by considering the characteristics of each of the four cases based on frequency.
Moreover, our result requires no smallness assumption on the initial cell mass or on the initial velocity field; the global bounded-ness is achieved solely by the strength of the Taylor-Couette flow (i.e., a sufficiently large $A$).
	\end{remark}

\begin{remark}\label{local well-posedness}
		The result of local well-posedness of the system (\ref{ini1}) is standard, which can be refered to \cite{Hu1, Wink2013}, and we omitted it.
	\end{remark}	
	The stabilizing phenomenon is fundamentally caused by the enhanced dissipation induced by the Taylor-Couette flow. We first recall the space-time estimate of the following system (see Proposition 6.1 in \cite{AHL2024}), which plays a crucial role in the subsequent analysis. Let
	\begin{equation}\label{eq:space time}
		\left\{
		\begin{array}{lr}
			\partial_{t}h-\frac{1}{A}\Big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \Big)h+\frac{ik}{r^{2}}h+\frac{1}{r}\big[ikh_{1}-r^{\frac12}\partial_{r}(r^{\frac12}h_{2}) \big]=0,\\
			h|_{t=0}=h(0),\quad h|_{r=1,R}=0,
		\end{array}
		\right.
	\end{equation}
	where $h_{1}$ and $ h_{2}$ are given functions.
	\begin{proposition}\label{prop:space time}
		For $k\in\mathbb{Z}\backslash\{0\}$, let $h$ be a solution to \eqref{eq:space time} with $h(0)\in L^{2}$. Given $\log R\leq CA^{\frac13}$, then there exists a constant $a>0$ independent of $A, k, R$, such that it holds
		\begin{equation*}
			\begin{aligned}
				&\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h\|_{L^{\infty}L^{2}}+A^{-\frac16}|k|^{\frac13}R^{-1}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h\|_{L^{2}L^{2}}\\&+A^{-\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\partial_{r}h\|_{L^{2}L^{2}}+A^{-\frac12}|k|\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\frac{h}{r}\Big\|_{L^{2}L^{2}}\\\leq&C\left(\|h(0)\|_{L^{2}}+A^{\frac16}|k|^{-\frac13}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}kh_{1}\|_{L^{2}L^{2}}+A^{\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h_{2}\|_{L^{2}L^{2}} \right).
			\end{aligned}
		\end{equation*}
	\end{proposition}

	Here are some notations used in this paper.

	\noindent\textbf{Notations}:
	\begin{itemize}

		\item The Fourier transform is defined by
		\begin{equation}
			f(t,r,\theta)=\sum_{k\in\mathbb{Z}}\widehat{f}_{k}(t,r){\rm e}^{ik\theta}, \nonumber
		\end{equation}
		where $\widehat{f}_{k}(t,r)=\frac{1}{2\pi}\int_{0}^{2\pi}f(t,r,\theta){\rm e}^{-ik\theta}d\theta$.

		\item For a given function $f=f(t,r,\theta)$,  we write its  zero mode by
		$$P_0f=\widehat{f}_0=\frac{1}{2\pi}\int_{0}^{2\pi}f(t,r,\theta)d\theta.$$ 

		\item  For  given functions $f=f(t,r,\theta)$ and $g=g(t,r)$, 
		their space norm  and  time-space norm  are defined as 
		$$\|f\|_{L^{p}([1,R]\times\mathbb{S}^{1})}=\left(\int_{0}^{2\pi}\int_{1}^{R}|f|^{p}drd\theta \right)^{\frac{1}{p}},
		\quad \|g\|_{L^{p}([1,R])}=\left(\int_{1}^{R}|g|^{p}dr \right)^{\frac{1}{p}}$$ 
		and 
		$$\|f\|_{L^{q}L^{p}}=\left\|\|f\|_{L^{p}([1,R]\times\mathbb{S}^{1})} \right\|_{L^{q}(0,t)},
		\quad \|g\|_{L^{q}L^{p}}=\left\|\|g\|_{L^{p}([1,R])} \right\|_{L^{q}(0,t)}.$$ Moreover, $\langle \cdot, \cdot\rangle$ denotes the standard $L^{2}$ scalar product.

		\item The total mass $\|n_{\rm in}\|_{L^{1}}$ is denoted by $M$. Clearly, Green’s identity gives
		\begin{equation*}
			\begin{aligned}
				&	\|n(t)\|_{L^{1}}\leq\|n_{\rm in}\|_{L^{1}}=:M.
			\end{aligned}
		\end{equation*}

		\item Throughout this paper, we denote by $ C $ a positive constant independent of $A$, $t$ and the initial data, and it may be different from line to line. $C(R)$  denotes a constant depending on the parameter $R$.
	\end{itemize}

	The rest part of this paper is organized as follows. In Section \ref{ideas}, some key ideas and the proof of
	Theorem \ref{thm:main} are presented. Section \ref{priori estimate} is devoted to providing a priori estimates and zero mode estimates, which are essential for the subsequent analysis.  The energy estimates for $E(t)$ and the proof of Proposition \ref{prop:E(t)} are established in Section \ref{estimate E(t)}. In Section \ref{estimate infty}, we complete the proof of Proposition \ref{prop:n infty}.

