	\section{Sketch of the proof of Theorem \ref{thm:main}}\label{ideas}
	In this section, we present some
	key ideas and the proof of Theorem \ref{thm:main}.

	Note that the coordinate $\theta$ in TC flow is defined on $\mathbb{S}^{1}$, and it is natural to applying Fourier transform on the $\theta$ direction. Then taking Fourier transform for (\ref{ini1})-(\ref{boundary condition}) with respect to $\theta$, we obtain
	\begin{equation}\label{eq:fourier}
		\left\{
		\begin{array}{lr}
			\partial_{t}\widehat{n}_{k}-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{n}_{k}+(1+\frac{1}{r^{2}})ik\widehat{n}_{k}+\frac{1}{Ar}\sum_{l\in\mathbb{Z}}i(k-l)\partial_{r}\widehat{\varphi}_{l}\widehat{n}_{k-l}\\-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}il\widehat{\varphi}_{l}\partial_{r}\widehat{n}_{k-l}=-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}\partial_{r}(r\widehat{n}_{l}\partial_{r}\widehat{c}_{k-l})-\frac{ik}{Ar^{2}}\sum_{l\in\mathbb{Z}}i(k-l)\widehat{n}_{l}\widehat{c}_{k-l},\\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{c}_{k}+\widehat{n}_{k}-\widehat{c}_{k}=0,\\
			\partial_{t}\widehat{w}_{k}-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{w}_{k}+(1+\frac{1}{r^{2}})ik\widehat{w}_{k}+\frac{1}{Ar}\sum_{l\in\mathbb{Z}}i(k-l)\partial_{r}\widehat{\varphi}_{l}\widehat{w}_{k-l}\\-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}il\widehat{\varphi}_{l}\partial_{r}\widehat{w}_{k-l}=-\frac{ik}{Ar}\widehat{n}_{k},\\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{\varphi}_{k}=\widehat{w}_{k},\\
			\widehat{n}_{k}|_{r=1,R}=\widehat{c}_{k}|_{r=1,R}=\widehat{w}_{k}|_{r=1,R}=\widehat{\varphi}_{k}|_{r=1,R}=0.

		\end{array}
		\right.
	\end{equation}
	Inspired by  An-He-Li \cite{AHL2024}, we introduce the weight $r^{\frac12}$ to eliminate the derivative $\frac{1}{r}\partial_{r}$. Specifically,  define 
	\begin{equation*}
		n_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{n}_{k},\quad c_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{c}_{k},\quad 
		w_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{w}_{k},\quad 
		\varphi_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{\varphi}_{k}.
	\end{equation*}
	It follows that
	\begin{equation}\label{define nk ck wk}
		\|F_{k}\|_{L^{p}}\leq R^{\frac12}\|\widehat{F}_{k}\|_{L^{p}},\quad {\rm for}\quad F\in\{n, c, w, \varphi \}~{\rm and}~p\in\{2, \infty\}.
	\end{equation}
	Denote the operator $\mathcal{L}_{k}$ as
	\begin{equation}\label{define:Lk}
		\mathcal{L}_{k}f:=-\frac{1}{A}\Big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \Big)f+\frac{ik}{r^{2}}f.
	\end{equation}
	Thus, the system (\ref{eq:fourier})  is transformed into
	\begin{equation}\label{eq:fourier 1}
		\left\{
		\begin{array}{lr}
			\partial_{t}n_{k}+\mathcal{L}_{k}n_{k}+\frac{\big[ik\sum_{l\in\mathbb{Z}}\partial_{r}(r^{-\frac12}\varphi_{l})n_{k-l}-r^{\frac12}\partial_{r}\left(\sum_{l\in\mathbb{Z}}ilr^{-1}\varphi_{l}n_{k-l} \right) \big]}{Ar}
			\\=-\frac{1}{Ar^{\frac12}}\partial_{r}\big[\sum_{l\in\mathbb{Z}}r^{\frac12}n_{l}\partial_{r}(r^{-\frac12}c_{k-l}) \big]-\frac{ik}{Ar^{\frac52}}\sum_{l\in\mathbb{Z}}i(k-l)n_{l}c_{k-l},\\
			\big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \big)c_{k}+n_{k}-c_{k}=0,\\
			\partial_{t}w_{k}+\mathcal{L}_{k}w_{k}
			+\frac{\big[ik\sum_{l\in\mathbb{Z}}\partial_{r}(r^{-\frac12}\varphi_{l})w_{k-l}-r^{\frac12}\partial_{r}\big(\sum_{l\in\mathbb{Z}}ilr^{-1}\varphi_{l}w_{k-l} \big) \big]}{Ar}=-\frac{ik}{Ar}n_{k},\\
			\big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \big)\varphi_{k}=w_{k},\\
			n_{k}|_{r=1,R}=c_{k}|_{r=1,R}=w_{k}|_{r=1,R}=\varphi_{k}|_{r=1,R}=0.
		\end{array}
		\right.
	\end{equation}

	We introduce the following norms
	\begin{equation}\label{X_a^k}
		\begin{aligned}
			\|f_k\|_{X_{a}^{k}}&=\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}f_k\|_{L^{\infty}L^{2}}+A^{-\frac16}|k|^{\frac13}R^{-1}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}f_k\|_{L^{2}L^{2}}\\&\quad +A^{-\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\partial_{r}f_k\|_{L^{2}L^{2}}
			+A^{-\frac12}|k|\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\frac{f_k}{r}\Big\|_{L^{2}L^{2}}
		\end{aligned}
while later sections provide “a priori estimates and zero mode estimates,” “energy estimates for $E(t)$,” and an $L^\infty$ estimate used to “complete the proof,” namely the following result:

\begin{proposition}\label{prop:n infty}
		Under the assumptions of Proposition \ref{prop:E(t)}, there exists a positive constant $\mathcal{Q}_{2}$ depending on $\|u_{\rm in}\|_{H^{2}(\mathcal{D})}$ and $\|n_{\rm in}\|_{L^{\infty}\cap H^{1}(\mathcal{D})}$, such that 
		\begin{equation*}
			\|n\|_{L^{\infty}L^{\infty}}\leq\mathcal{Q}_{2}
		\end{equation*}
		for all $t\in[0,T]$.
	\end{proposition}

