\begin{theorem}
\label{thm-n=1}
Let $\kappa\in\mathbb{Z}\setminus\{4\}$.
Then, there exists an explicit $K_{3,3}$-subdivision in $\Gkp$ 
if $\xi_{1,\kappa}\eta_{1,\kappa}\ne 0$ and $\left(\frac{\eta_{1,\kappa}}{p}\right)=1$.
\end{theorem}

ref_dict.cor:cycles:
\begin{cor}
\label{cor:cycles}
The graph $\Gkp$ contains cycles 
of lengths $4n+2$, $6n+3$, and $8n+2$ if there exists $n\in\mathbb{Z}_{>0}$ such that $\Knkpprop\ne\emptyset$.
\end{cor}

ref_dict.thm:np density:
\begin{theorem}
\label{thm:np density}
\begin{itemize}
\item[$(1)$]
For each $\kappa\in\mathbb{Z}\setminus\{4\}$ such that none of  
$\eta_{1,\kappa}$,  
$\eta_{2,\kappa}$, 
$5$, and $\kappa-4$
is a square in $\mathbb{Z}$, 
and that the ratio of any two of them is not a square in $\mathbb{Q}$, 
we have
\begin{equation}
\label{for:lower bound of Dnp}
\delta_{\kappa}\ge \frac{13}{16}.
\end{equation}
That is, $\Gkp$ contains a $K_{3,3}$-subdivision
for at least $81.25\%$ 
of primes $p$ asymptotically.
\item[$(2)$]
The natural density 
of $\kappa\in\mathbb{Z}\setminus\{4\}$ for which $(1)$ holds 
is equal to $1$.
\end{itemize}
\end{theorem}

ref_dict.thm:disjoint-intro:
\begin{theorem}[Theorem~\ref{thm-disjoint-k}]
\label{thm:disjoint-intro}
For each $\kappa \in \mathbb{Z} \setminus \{ 4\}$, $\Gkp$ contains at least four mutually vertex-disjoint $K_{3,3}$-subdivisions for infinitely many primes $p$ (depending on $\kappa$) of natural density at least $1/4$ if $\kappa=2$ and $1/2$ otherwise.
Moreover, for almost all $\kappa$, the natural density of primes $p$ for which this holds is at least $5/8$.
\end{theorem}

ref_dict.cor:direct:
\begin{cor} 
\label{cor:direct}
Under the same assumptions on $\kappa$ and $p$ of Theorem~\ref{thm:main} $(1)$,
the followings hold:
\begin{enumerate}
\item[$(1)$] 
$(\mathrm{Corollary}~\ref{cor:sufficient condition non-planarity})$
$\Gkp$ is non-planar. 
\item[$(2)$]
$(\mathrm{Corollary}~\ref{cor:cycles})$
$\Gkp$ has cycles (i.e. closed paths with no repeated vertices or edges) of lengths $6,9,10,15$, and $18$, 
all of which can be constructed explicitly.  
\end{enumerate}
\end{cor}

ref_dict.cor:sufficient condition non-planarity:
