\qed
\end{cor}

ref_dict.thm-disjoint-k:
\begin{theorem}
\label{thm-disjoint-k}
\begin{enumerate}
\item[$(1)$] 
For each $\kappa\in\mathbb{Z}\setminus\{4\}$,
$\Gkp$ contains at least four mutually vertex-disjoint 
$K_{3,3}$-subdivisions for infinitely many primes $p$ of natural density at least $1/4$ if $\kappa=2$ and $1/2$ otherwise. 
Furthermore, if $\kappa$ is an integer such that 
none of $\eta_{1, \kappa}$, $\eta_{2,\kappa}$ and $5$ is a square in $\mathbb{Z}$ and that the ratio of any two of them is also not a square in $\mathbb{Q}$,
then the natural density of such primes is at least $5/8$.
\item[$(2)$]
The natural density of $\kappa\in\mathbb{Z}\setminus\{4\}$
for which the latter assertion of $(1)$ holds is equal to $1$.
\end{enumerate}
\end{theorem}

