theorem.content:
\label{main thm last}
Fix a DCC set $I\subset{\mathbb R}^{\ge 0}$. Let $\CS$ be a set of lc algebraically integrable foliated triples $(Y,\CG,C)$ such that the coefficients of $C$ belong to $I$. Assume that $\CS$ is birationally bounded by algebraically integrable families (cf. Definition \ref{bir bdd fol triples}). 

Then the set $$\{\vol(Y,K_{\CG}+C)\,|\,(Y,\CG,C)\in \CS\}$$satisfies the DCC.

ref_dict.inv vol semistable:
\begin{thm}[see Theorem \ref{inv vol} for a more general form]\label{inv vol semistable} Let $(X,B)$ be a log pair. Suppose that $f:X\to Z/T$ is a contraction over a smooth variety $T$, such that
 \begin{enumerate}
     \item the morphism $f:(X,\Sigma_X)\to (Z,\Sigma_Z)$ is semistable with respect to the divisors $\Sigma_X$ and $\Sigma_Z$,
     \item $Z\to T$ is a contraction and $(Z,\Sigma_Z)$ is log smooth over $T$,
     \item $0\le B\le \Sigma^h_X$, where $\Sigma^h_X$ denotes the horizontal$/Z$ part of $\Sigma_X$.
 \end{enumerate}
Then the relative log canonical volume $\vol(X_t,K_{X_t/Z_t}+B_t)$ is independent of $t\in T$.
\end{thm}

ref_dict.fol log sm is lc:
\begin{rem}\label{fol log sm is lc}
 If $(X,\CF,B)$ is a foliated log smooth triple, then by \cite[Lemma 3.1]{ACSS21}, $(X,\CF,B^{\CF})$ is lc.
\end{rem}

ref_dict.bir bdd fol triples:
\begin{defn}[Birationally bounded by algebraically integrable families]\label{bir bdd fol triples}
    Let $\CS$ be a set of foliated triples. We say that $\CS$ is \emph{birationally bounded by algebraically integrable families} if there exist finitely many foliated triples $(X^i,\CF^i,B^i)$, equipped with dominant rational maps $f^i:X^i\dasharrow Z^i$ between normal varieties over base varieties $T^i$ for $i=1,...,N$, such that:
    \begin{enumerate}
        \item $B^i$ is a reduced divisor, and the structural morphisms $X^i\to T^i$ and $Z^i\to T^i$ are projective,
        \item $\CF^i$ is induced by $f^i$ (in particular, it is algebraically integrable), and
        \item for every $(Y,\CG,C)\in \CS$, there exists an index $i\in\{1,...,N\}$, a closed point $t\in T^i$ and a birational map $\phi: Y\dasharrow X^i_t$ such that:
 \begin{enumerate}
    \item the restriction of $f^i$ to the fibre $X^i_t$ induces a well-defined dominant rational map $f^i_t: X^i_t\dasharrow Z^i_t$ between normal varieties,
    \item $(X^i_t,\CF^i_t,B^i_t)$ is a foliated triple, where $\CF^i_t$ is the foliation induced by $f^i_t$ and $B^i_t$ is the restriction of $B^i$ to $X^i_t$,
    \item $\phi_*\CG=\CF^i_t$, and
    \item $\Supp B^i_t$ contains $\Supp \phi_{*}C$ and the support of any $\phi^{-1}$-exceptional divisor.
 \end{enumerate}
\end{enumerate}
\end{defn}

ref_dict.main thm last:
\begin{thm}\label{main thm last}
Fix a DCC set $I\subset\bR^{\ge 0}$. Let $\CS$ be a set of lc algebraically integrable foliated triples $(Y,\CG,C)$ such that the coefficients of $C$ belong to $I$. Assume that $\CS$ is birationally bounded by algebraically integrable families (cf. Definition \ref{bir bdd fol triples}). 

Then the set $$\{\vol(Y,K_{\CG}+C)\,|\,(Y,\CG,C)\in \CS\}$$satisfies the DCC.
\end{thm}

ref_dict.def: wss:
\begin{defn}[Weak semistable, {cf. \cite{AK00}}]\label{def: wss}
   A contraction $f:X\to Z$ between normal varieties is called \emph{weak semistable} if there exist divisors $\Sigma_X$ on $X$ and $\Sigma_Z$ on $Z$ such that 
	\begin{enumerate}
	    \item $f$ is a toroidal morphism between the toroidal couples $(X,\Sigma_X)$ and $(Z,\Sigma_Z)$,

		\item $f$ is flat,

		\item all fibres of $f$ are reduced, and

		\item $(X,\Sigma_X)$ is quasi-smooth and $(Z,\Sigma_Z)$ is log smooth. 

	\end{enumerate}
In particular, the vertical$/Z$ part of $\Sigma_X$ is equal to $f^*(\Sigma_Z)$. We also say that $f:(X,\Sigma_X)\to(Z,\Sigma_Z)$ is weak semistable with respect to the divisors $\Sigma_X$ and $\Sigma_Z$. If $X$ is also smooth, we say that the morphism $f:X\to Z$ is \emph{semistable}. 
\end{defn}

ref_dict.rem of def of wss:
\begin{rem}\label{rem of def of wss}
    The above definition is slightly different from \cite[Definition 0.1]{AK00}. First, we require that $(X,\Sigma_X)$ is quasi-smooth. This condition can be achieved by a further small toroidal birational modification (cf. \cite[Remark 4.5]{AK00}). Second, the original definition in \cite{AK00} requires that $f(\Sigma_X)\subset{\Sigma_Z}$ (that is, $\Sigma_X$ has no horizontal$/Z$ components), but we do not impose this condition. This definition is the same as \cite[Definition 3.7]{Jiao25}. See also \cite[Definition 2.19]{EH25} and \cite[Definition 2.2]{ALT18}.
\end{rem}

ref_dict.dcc of fixed model:
\begin{prop}\label{dcc of fixed model}
Let $I \subset \mathbb{R}^{\geq0}$ be a DCC set. Assume that $(Y,\mathcal{G},\Delta)$ is a projective foliated log smooth triple associated with $f:(Y,\Sigma_Y)\rightarrow (Z,\Sigma_Z)$ such that $\Delta=\Sigma^{\CG}_Y$. Let $\CS$ be the set of foliated triples $(X,\mathcal{F},B)$ equipped with a birational morphism $\phi:X\rightarrow Y$ satisfying
\begin{enumerate}
    \item $(X,\CF,B)$ is projective lc,
    \item the coefficients of B are in $I$,
    \item $\phi_{*}B\leq \Delta$, and $\phi_*\CF=\CG.$
\end{enumerate}
Then the set \begin{equation*}
	\{\vol(X,K_{\CF}+B)\,|\,(X,\mathcal{F},B)\in \CS\}
\end{equation*}
satisfies the DCC.
\end{prop}

ref_dict.weak semistable reduction:
\begin{thm}[Weak semistable reduction, {cf. \cite{AK00}}]\label{weak semistable reduction}
Let $f:X\to Z$ be a contraction between normal varieties, and let $B\subset X$ be a divisor. Then there exists a proper surjective, generically finite morphism $b: Z'\to Z$, a birational contraction $a: X'\to (X\times_Z Z')^m$, and divisors $\Sigma_{X'}\subset{X'}, \Sigma_{Z'}\subset{Z'}$, such that 
\begin{itemize}
    \item $a^{-1}(B\times_Z 
    Z')\subset{\Sigma_{X'}}$, and
    \item the morphism $f':(X',\Sigma_{X'})\to (Z',\Sigma_{Z'})$ is weak semistable.
\end{itemize}
Here, $(X\times_Z Z')^m$ denotes the normalization of the main component of $X\times_Z Z'$. 
\end{thm}

ref_dict.inv vol:
\begin{thm}\label{inv vol}
	Let $f:(X,\Sigma_X)\to (Z,\Sigma_Z)/T$ be a family of weak semistable morphisms. Let $B$ be an $\bR$-divisor on $X$ such that $0\le B\le \Sigma^h_X$, where $\Sigma^h_X$ denotes the horizontal$/Z$ part of $\Sigma_X$. 

 Then the relative log canonical volume $\vol(X_t,K_{X_t/Z_t}+B_t)$ is independent of $t\in T$.
\end{thm}

ref_dict.def: log smooth over base:
\begin{defn}[Relative log smoothness]\label{def: log smooth over base}
	Given a log pair $(X,B)$ and a morphism $X\to T$, we say that $(X,B)$ is \emph{log smooth over $T$} if $(X,B)$ is log smooth and both $X$ and every stratum of $(X,B)$ are smooth over $T$. Here, a \emph{stratum} of $(X,B=\sum_{i=1}^{n}b_i B_i)$ refers to an irreducible component of the intersection $\bigcap_{i\in I}B_i$, where $I\subset \{1,...,n\}$ is a nonempty subset.
\end{defn}

ref_dict.Main Question fol:
\begin{ques}[J.~Pereira,\,\, {\cite[Section 3]{cas21}, \cite[Question 4]{HL21}}]\label{Main Question fol}
    Let $d$ be a positive integer. Let $V=\{\vol(X,K_\CF)\}$ where $(X,\CF)$ is a  projective foliated pair with canonical singularities of general type (i.e. $K_\CF$ is big). Does $V$ satisfy the DCC or does it admit a positive minimum?
\end{ques}

ref_dict.preliminaries:
\begin{rem}
    Note that in Question \ref{question:inv of plurigenera}, the assumption that $m$ is sufficiently divisible is necessary, as the invariance of plurigenera fails for small values of $m$, even if $f:X\to Z$ is a smooth morphism (see \cite[Example 3.10]{CF18}).
\end{rem}

\noindent\textbf{Structure of the paper.} The paper is organized as follows. In Section \ref{preliminaries}, we gather some basic notation and tools used in the paper. In Section \ref{section: dcc for fixed model}, we prove a special case of Theorem \ref{main thm last}, where the foliated triples are birational to a fixed foliated log smooth model (cf. Proposition \ref{dcc of fixed model}). In Section \ref{section4}, we prove the invariance of relative log canonical volumes for a family of weak semistable morphisms (cf. Theorem \ref{inv vol}), which is a more general form of Theorem \ref{inv vol semistable}. Finally in Section \ref{section: main thm}, we prove the main result Theorem \ref{main thm last}, by combining the technique of weak semistable reduction \cite{AK00} (cf. Theorem \ref{weak semistable reduction}) with Proposition \ref{dcc of fixed model} and Theorem \ref{inv vol}. 

\section{Preliminaries}\label{preliminaries}
Throughout this paper, we mainly work with normal quasi-projective varieties to ensure consistency with the references. We adopt the standard notation and definitions in \cite{KM98, BCHM10}. For foliations, we generally follow the notation and definitions in \cite{CS21, ACSS21, CHLX23, CS251}, but there may be minor differences.
\subsection{Special notation}

\begin{nota}
    In this paper, a \emph{contraction} is a projective morphism between quasi-projective normal varieties $f:X\to Y$ such that $f_*\CO_X=\CO_Y$. In particular, $f$ has connected fibres. Let $f:X\to Z$ be a contraction, and $D$ an $\bR$-divisor on $X$. We define the \emph{horizontal$/Z$ part} $D^h$ of $D$ as the part of $D$ supported on prime divisors dominating $Z$; the \emph{vertical$/Z$ part} of $D$ is $D^v:=D-D^h$. A \emph{finite cover} is a finite surjective morphism. 

    Let $f:X\dasharrow X'$ be a birational map between normal varieties. We denote by $\Exc(f)$ the reduced divisor supported on the codimension one part of the exceptional locus of $f$. 

    Let $X$ be a normal variety, and let $M$ be an $\bR$-divisor on $X$. We denote the coefficient of a prime divisor $D$ in $M$ by $\mu_D M$.

The notation  ``/'' is used as shorthand for ``over''. For example, ``$/Z$'' means ``over $Z$''.

\end{nota}

\begin{defn}[Relative log smoothness]\label{def: log smooth over base}
	Given a log pair $(X,B)$ and a morphism $X\to T$, we say that $(X,B)$ is \emph{log smooth over $T$} if $(X,B)$ is log smooth and both $X$ and every stratum of $(X,B)$ are smooth over $T$. Here, a \emph{stratum} of $(X,B=\sum_{i=1}^{n}b_i B_i)$ refers to an irreducible component of the intersection $\bigcap_{i\in I}B_i$, where $I\subset \{1,...,n\}$ is a nonempty subset.
\end{defn}
\begin{defn}
    Let $X$ be a normal projective variety of dimension $d$, and $D$ an $\bR$-divisor on $X$. The \emph{volume} of $D$ is defined as: $$\vol(X,D):=\limsup_{m\to \infty}{\frac{h^0(X,\lfloor mD\rfloor)}{m^d/d!}}.$$ 
\end{defn}
For more background, see \cite{Laz04}. 

\subsection{Toroidal geometry and weak semistable reduction}
We recall some basic facts of toroidal embedding, following the standard notation and definitions in \cite{KKMS73} and \cite{AK00}. We also adopt the notion of \emph{toroidal couples} (cf. \cite[Section 3.7]{Bir23}).
 See also \cite{Qu25} for a more detailed treatment. 
 We refer to \cite{Cox11} for the general theory of toric varieties. 

 Recall that a \emph{couple} $(X,\Sigma_X)$ consists of a normal variety $X$ and a reduced Weil divisor $\Sigma_X$ on $X$. A morphism $(X,\Sigma_X)\to (Y,\Sigma_Y)$ of couples is a morphism $f:X\to Y$ between normal varieties such that $f^{-1}(\Sigma_Y)\subset{\Sigma_X}$ (cf. \cite[Section 3.6]{Bir23}).

\begin{defn}[Toroidal couple and toroidal embedding, {cf. \cite[II \S 1, Definition 1]{KKMS73} and \cite[Definition 1.2]{AK00}}]
 Let $(X,\Sigma_X)$ be a couple. We say that the couple is \emph{toroidal} if for any closed point $x\in X$, there exists a normal affine toric variety $W$ together with a closed point $w\in W$, such that there is an isomorphism of local complete $k$-algebras
$$\phi:\widehat{\mathcal{O}}_{X,x}\to\widehat{\mathcal{O}}_{W,w}$$ mapping the ideal of $\Sigma_X$ to the ideal of the toric boundary $\Sigma_W\subset W$ (that is, the reduction of the complement of the torus $\mathbb{T}_W$ in $W$). We call the data $\{(W,\Sigma_W),w\}$ a \emph{local toric model} of $\{(X,\Sigma_X),x\}$.

Let $(X,\Sigma_X)$ be a toroidal couple, and let $U_X:=X\backslash \Supp \Sigma_X$, which is an open subset of $X$. We call $(U_X\subset X)$ a \emph{toroidal embedding}, see \cite[page 54]{KKMS73}. 
\end{defn}

\begin{rem}\label{toroidal lc}
     If $(X,\Sigma_X)$ is a toroidal couple, then $X$ is normal and Cohen--Macaulay, $K_X+\Sigma_X$ is Cartier, and $(X,\Sigma_X)$ is an lc pair (see \cite[Lemma 3.8]{Bir23}). Moreover, if $X$ is smooth, then $(X,\Sigma_X)$ is log smooth. 
\end{rem}

ref_dict.defn: foliation singularity:
\begin{defn}[Singularities]\label{defn: foliation singularity}
Let $(X,\CF,B)$ be a foliated triple. For any prime divisor $E$ over $X$, let $f: Y\rightarrow X$ be a projective birational morphism such that $E$ is on $Y$, and suppose that
$$K_{\CF_Y}+B_Y:=f^*(K_\CF+B)$$
where $\CF_Y:=f^{-1}\CF$. We define $a(E,\CF,B):=-\mu_EB_Y$ to be the \emph{discrepancy} of $E$ with respect to $(X,\CF,B)$.
We say that $(X,\CF,B)$ is \emph{lc} (resp. \emph{klt}) if $a(E,\CF,B)\geq -1$ (resp. $>-1$) for any prime divisor $E$ over $X$. We say that $(X,\CF,B)$ is \emph{canonical} if $a(E,\CF,B)\geq 0$ for any prime divisor $E$ that is exceptional$/X$.
\textbf{Note that our definition of klt aligns with} \cite{LMX24} \textbf{and is different from
other references.}

 An \emph{lc place} of $(X,\CF,B)$ is a prime divisor $E$ over $X$ such that $a(E,\CF,B)=-\epsilon_{\CF}(E)$. An \emph{lc centre} of $(X,\CF,B)$ is the centre $V$ of an lc place of $(X,\CF,B)$ on $X$.
\end{defn}

ref_dict.rem: bir bdd foliations:
\begin{rem}\label{rem: bir bdd foliations}
    If a set $\CS$ of foliated triples is birationally bounded by algebraically integrable families, then the general leaves of elements in $\CS$ are also birationally bounded as algebraic varieties (cf. \cite[Definition 2.4.1]{HMX1}). However, as discussed in \cite[Example 4.3]{passantino24}, there exists a set $\CS$ of rank one algebraically integrable foliations on surfaces, such that $\CS$ is bounded (cf. \cite[Definition 3.31]{CHLMSSX25}), but the leaves of elements in $\CS$ (which are irreducible curves) have unbounded genus.
\end{rem}

ref_dict.question:inv of plurigenera:
\begin{ques}\label{question:inv of plurigenera}
    Notation as in Theorem \ref{inv vol semistable}. Further assume that $K_{X/Z}+B$ is big over $T$. Is $h^0(X_t,m(K_{X_t/Z_t}+B_t))$ independent of $t\in T$ for any sufficiently divisible positive integer $m$? 
\end{ques}

pre_theorem_intro_text:
We work over the field of complex numbers ${\mathbb C}$. DCC stands for the \emph{descending chain condition}.

 The volume of a projective variety is one of the most intensively studied invariants in birational geometry. For varieties of general type, a famous result of Hacon,   M\raisebox{\dimexpr\fontcharht\font`M - \height}{    \scriptsize c  } Kernan, and Xu establishes that their volumes satisfy the DCC, and in particular, have a positive lower bound. They also prove the effective birationality for the log canonical systems for such varieties. More precisely:
\begin{introthm}[{\cite[Theorem 1.3]{HMXacc}}]\label{HMX dcc} Fix a positive integer $d$ and a DCC set $I\subset{[0,1]}$. Let $\mathcal{D}$ be the set of log canonical pairs $(X,\Delta)$ such that $\dim X=d$, the coefficients of $\Delta$ belong to $I$, and $K_X+\Delta$ is big. Then we have
\begin{enumerate}
    \item the set $\{\vol(X,K_X+\Delta)\,|\, (X,\Delta)\in \mathcal{D}\}$ satisfies the DCC;
    \item (effective birationality) there exists a positive integer $m$ depending only on $d$ and $I$, such that the linear system $|m(K_X+\Delta)|$ defines a birational map.
\end{enumerate}
\end{introthm}
In this paper, we are interested in the volume of algebraically integrable foliations.

\medskip
\noindent\textbf{Volume of Algebraically Integrable Foliations.} In recent years, the minimal model program (MMP) for foliations has been extensively developed, starting with \cite{mcqui08}, and then \cite{ACSS21,CS21,CS251,CHLX23,LMX24}, especially for algebraically integrable ones.

 It is interesting to ask whether the above theorem of Hacon--  M\raisebox{\dimexpr\fontcharht\font`M - \height}{    \scriptsize c  } Kernan--Xu holds for foliations. However, the analogue of effective birationality fails in general, even for foliations induced by well-behaved fibrations, as shown in \cite[Theorem 1.3]{lu25}. In \cite[Theorem 2]{HL21}, Hacon and Langer showed that for a canonical model $(X,\CF)$ of a foliated surface of general type, the effective birationality holds if we fix the Hilbert polynomial $P(m)=\chi\left(X,\CO_{X}\left(mK_\CF\right)\right)$. See also \cite{Chen21,SS23,PS19,passantino24} for more progress.

 Hacon and Langer \cite[Question 4]{HL21} asked if volumes of canonical models of foliated surfaces are well ordered (e.g., satisfy the DCC) and admit a positive minimum. It was generalized to higher dimensions by Cascini \cite[Section 3]{cas21}. 

\begin{ques}[J.~Pereira,\,\, {\cite[Section 3]{cas21}, \cite[Question 4]{HL21}}]\label{Main Question fol}
    Let $d$ be a positive integer. Let $V=\{\vol(X,K_\CF)\}$ where $(X,\CF)$ is a  projective foliated pair with canonical singularities of general type (i.e. $K_\CF$ is big). Does $V$ satisfy the DCC or does it admit a positive minimum?
\end{ques}
Question \ref{Main Question fol} remains open even for surface foliations. See \cite{PS19,Chen21,HL21,LT22} for related works. In practice, it is often natural to consider the ``log version" of Question \ref{Main Question fol}. That is, we work with foliated triples rather than pairs, and replace  ``canonical singularities'' with ``lc singularities'' (see Definition \ref{defn: foliation singularity}).
In the recent work \cite{HJLL24}, it was shown that the volumes of lc algebraically integrable foliations belong to a discrete set depending only on their rank and the volumes of their general leaves. For stable families over a curve with klt general fibres and boundary coefficients in a finite set, the existence of a positive lower bound for the volume was proved in \cite[Corollary 1.8]{CPT25}.

In this paper we study Question \ref{Main Question fol} for algebraically integrable foliations via the MMP developed in \cite{ACSS21,CHLX23,LMX24}, etc. We consider a special case of Question \ref{Main Question fol} where foliations are \textbf{birationally bounded by algebraically integrable families} (cf. Definition \ref{bir bdd fol triples}). This condition is stronger than the usual assumption of birationally boundedness. We require that both the foliations and their general leaves are birationally bounded (see Remark \ref{rem: bir bdd foliations}). The main result of this paper is the following, which can be viewed as a foliated version of \cite[Theorem 1.9]{HMX1}.

