\noindent\textbf{Deformation Invariance of Plurigenera and Volumes.} A deep result of Siu \cite{Siu98,Siu02} states that the plurigenera of a family of smooth projective varieties are deformation invariant. Hacon, \mc Kernan, and Xu generalized this to the case of log pairs \cite[Theorem 1.8]{HMX1}. Specifically, let $(X,B)\to T$ be a projective morphism from a log canonical pair $(X,B)$ to a smooth variety $T$, such that $(X,B)$ is log smooth over $T$ (cf. Definition \ref{def: log smooth over base}). They proved that 
the log plurigenera $h^0(X_t,m(K_{X_t}+B_t))$ are independent of $t\in T$, assuming that $(X,B)$ is klt and $K_X+B$ is big over $T$. As a direct corollary, the log canonical volume $\vol(X_t,K_{X_t}+B_t)$ is also independent of $t\in T$. Notably, this volume invariance holds even without the klt and bigness assumptions. For more general results, see \cite[Theorem 4.2]{HMX1} and \cite[Corollary 1.3 and Lemma 6.3]{HMX2}.

\begin{prop}\label{dcc of fixed model}
Let $I \subset \mathbb{R}^{\geq0}$ be a DCC set. Assume that $(Y,\mathcal{G},\Delta)$ is a projective foliated log smooth triple associated with $f:(Y,\Sigma_Y)\rightarrow (Z,\Sigma_Z)$ such that $\Delta=\Sigma^{\CG}_Y$. Let $\CS$ be the set of foliated triples $(X,\mathcal{F},B)$ equipped with a birational morphism $\phi:X\rightarrow Y$ satisfying
\begin{enumerate}
 \item $(X,\CF,B)$ is projective lc,
 \item the coefficients of B are in $I$,
 \item $\phi_{*}B\leq \Delta$, and $\phi_*\CF=\CG.$
\end{enumerate}
Then the set \begin{equation*}
 \{\vol(X,K_{\CF}+B)\,|\,(X,\mathcal{F},B)\in \CS\}
\end{equation*}
satisfies the DCC.
\end{prop}
\begin{proof}
\noindent\textbf{Step 1}. By assumption and Remark \ref{fol log sm is lc}, $(Y,\CG,\Delta)$ is lc. Since $I$ is DCC, its closure $\Bar{I}$ is also DCC. By replacing $I$ with $\Bar{I}\cup\{1\}$, we may assume that $I$ is closed and $1\in I$. If the proposition does not hold, then there is a sequence $(X_i,\CF_i,B_i)$ with $\phi_i:X_i\rightarrow Y$ in $S$ such that the volumes $v_i=\vol(X_i,K_{\CF_i}+B_i)$ form a strictly decreasing sequence of positive real numbers. Let $v=\lim_{i\to\infty}v_i$.

\section{Proof of the main theorem}\label{section: main thm}
In this section we prove Theorem \ref{main thm last}. We start with the following definition. For the usual definition of a \emph{bounded family} of foliations, see for example, \cite[Definition 3.31]{CHLMSSX25}.
\begin{defn}[Birationally bounded by algebraically integrable families]\label{bir bdd fol triples}
 Let $\CS$ be a set of foliated triples. We say that $\CS$ is \emph{birationally bounded by algebraically integrable families} if there exist finitely many foliated triples $(X^i,\CF^i,B^i)$, equipped with dominant rational maps $f^i:X^i\dasharrow Z^i$ between normal varieties over base varieties $T^i$ for $i=1,...,N$, such that:
 \begin{enumerate}
 \item $B^i$ is a reduced divisor, and the structural morphisms $X^i\to T^i$ and $Z^i\to T^i$ are projective,
 \item $\CF^i$ is induced by $f^i$ (in particular, it is algebraically integrable), and
 \item for every $(Y,\CG,C)\in \CS$, there exists an index $i\in\{1,...,N\}$, a closed point $t\in T^i$ and a birational map $\phi: Y\dasharrow X^i_t$ such that:
 \begin{enumerate}
 \item the restriction of $f^i$ to the fibre $X^i_t$ induces a well-defined dominant rational map $f^i_t: X^i_t\dasharrow Z^i_t$ between normal varieties,
 \item $(X^i_t,\CF^i_t,B^i_t)$ is a foliated triple, where $\CF^i_t$ is the foliation induced by $f^i_t$ and $B^i_t$ is the restriction of $B^i$ to $X^i_t$,
 \item $\phi_*\CG=\CF^i_t$, and
 \item $\Supp B^i_t$ contains $\Supp \phi_{*}C$ and the support of any $\phi^{-1}$-exceptional divisor.
 \end{enumerate}
\end{enumerate}
\end{defn}

\medskip
 \noindent\textbf{Step 1}. In this step we fix notation and make standard reductions. We may assume that $1\in I$. Possibly replacing $\CS$ with a subset, we may assume that
 $\CS$ is birationally bounded by a single algebraically integrable family $f:X\dasharrow Z/T$. Let $(Y,\CG,C)\in \CS$. By assumption, there is a closed point $t\in T$ and a foliated triple $(X_t,\CF_t,B_t)$ equipped with a birational map $\phi: Y\dasharrow X_t$ such that $\phi_*\CG=\CF_t$ and $\Supp \phi_*C\cup\Exc \phi^{-1}\subset\Supp B_t$, where $\CF_t$ is induced by the dominant rational map $f_t:X_t\dasharrow Z_t$, see Definition \ref{bir bdd fol triples}.

\medskip
 \noindent\textbf{Step 3}. In this step, we complete the proof using Theorem \ref{inv vol} and Proposition \ref{dcc of fixed model}. Fix a closed point $0\in T$. Let $\CS_0\subset \CS$ be the set of lc projective algebraically integrable foliated triples $(Y,\CG,C)$ such that the coefficients of $C$ belong to $I$, and there exists a birational morphism $\beta:Y\to X_0$ with $\beta_*\CG=\CF_0$ and $\beta_*C\leq B_0$.

post_theorem_intro_text:
\noindent\textbf{Deformation Invariance of Plurigenera and Volumes.} A deep result of Siu \cite{Siu98,Siu02} states that the plurigenera of a family of smooth projective varieties are deformation invariant. Hacon,   M\raisebox{\dimexpr\fontcharht\font`M - \height}{    \scriptsize c  } Kernan, and Xu generalized this to the case of log pairs \cite[Theorem 1.8]{HMX1}. Specifically, let $(X,B)\to T$ be a projective morphism from a log canonical pair $(X,B)$ to a smooth variety $T$, such that $(X,B)$ is log smooth over $T$ (cf. Definition \ref{def: log smooth over base}). They proved that 
the log plurigenera $h^0(X_t,m(K_{X_t}+B_t))$ are independent of $t\in T$, assuming that $(X,B)$ is klt and $K_X+B$ is big over $T$. As a direct corollary, the log canonical volume $\vol(X_t,K_{X_t}+B_t)$ is also independent of $t\in T$. Notably, this volume invariance holds even without the klt and bigness assumptions. For more general results, see \cite[Theorem 4.2]{HMX1} and \cite[Corollary 1.3 and Lemma 6.3]{HMX2}.

 As a key ingredient in the proof of Theorem \ref{main thm last}, we establish the following result, which can be viewed as a relative version of the volume invariance discussed above.

\begin{thm}[see Theorem \ref{inv vol} for a more general form]\label{inv vol semistable} Let $(X,B)$ be a log pair. Suppose that $f:X\to Z/T$ is a contraction over a smooth variety $T$, such that
 \begin{enumerate}
     \item the morphism $f:(X,\Sigma_X)\to (Z,\Sigma_Z)$ is semistable with respect to the divisors $\Sigma_X$ and $\Sigma_Z$,
     \item $Z\to T$ is a contraction and $(Z,\Sigma_Z)$ is log smooth over $T$,
     \item $0\le B\le \Sigma^h_X$, where $\Sigma^h_X$ denotes the horizontal$/Z$ part of $\Sigma_X$.
 \end{enumerate}
Then the relative log canonical volume $\vol(X_t,K_{X_t/Z_t}+B_t)$ is independent of $t\in T$.
\end{thm}
For the definition of a semistable morphism, we mainly follow \cite{AK00} with minor modification. See Definition \ref{def: wss} and Remark \ref{rem of def of wss}. In Theorem \ref{inv vol semistable}, if we set $Z=T$, the condition that $(Z,\Sigma_Z)$ is log smooth over $T$ implies $\Sigma_Z=0$, and thus $(X,\Sigma_X)$ is log smooth over $T$. Consequently, this reduces to the volume invariance result of Hacon--  M\raisebox{\dimexpr\fontcharht\font`M - \height}{    \scriptsize c  } Kernan--Xu described above.

We further explain the conditions in Theorem \ref{inv vol semistable}. Consider the foliation $\CF$ induced by $f$. The assumption $0\le B\le\Sigma^h_X$ ensures that the foliated triple $(X,\CF,B)$ has log canonical singularities (see Definition \ref{defn: foliation singularity} and Remark \ref{fol log sm is lc}). Therefore, this theorem can also be viewed as a version of invariance of log canonical volume for foliations. In this direction, see \cite{CF18} for some results in the surface case. Here we mention that, although the volume is invariant under the assumptions of Theorem \ref{inv vol semistable}, we do not actually show the invariance of plurigenera during the proof. We may therefore propose the following:
\begin{ques}\label{question:inv of plurigenera}
    Notation as in Theorem \ref{inv vol semistable}. Further assume that $K_{X/Z}+B$ is big over $T$. Is $h^0(X_t,m(K_{X_t/Z_t}+B_t))$ independent of $t\in T$ for any sufficiently divisible positive integer $m$? 
\end{ques}
\begin{rem}
    Note that in Question \ref{question:inv of plurigenera}, the assumption that $m$ is sufficiently divisible is necessary, as the invariance of plurigenera fails for small values of $m$, even if $f:X\to Z$ is a smooth morphism (see \cite[Example 3.10]{CF18}).
\end{rem}

\noindent\textbf{Structure of the paper.} The paper is organized as follows. In Section \ref{preliminaries}, we gather some basic notation and tools used in the paper. In Section \ref{section: dcc for fixed model}, we prove a special case of Theorem \ref{main thm last}, where the foliated triples are birational to a fixed foliated log smooth model (cf. Proposition \ref{dcc of fixed model}). In Section \ref{section4}, we prove the invariance of relative log canonical volumes for a family of weak semistable morphisms (cf. Theorem \ref{inv vol}), which is a more general form of Theorem \ref{inv vol semistable}. Finally in Section \ref{section: main thm}, we prove the main result Theorem \ref{main thm last}, by combining the technique of weak semistable reduction \cite{AK00} (cf. Theorem \ref{weak semistable reduction}) with Proposition \ref{dcc of fixed model} and Theorem \ref{inv vol}.

