\label{th1}
Let $p>3$.
Assume that $\Gamma$ is a simple closed smooth curve with unit length in $\Omega$, and it is also a non-degenerate critical point of the functional
\begin{equation}\label{e91}
\mathcal{K}(\Gamma)=\int_\Gamma \mathbf{\Psi}^{\frac{p+3}{2p}}dvol_{\mathfrak{g}},
\end{equation}
where $\mathfrak{g}(X,Y)=\langle A^*X,Y\rangle$ is a Riemannian metric on $\mathbb R^2$ and $A^*$ is the adjoint matrix for $A$. We also assume that the following inequality holds on $\Gamma$:
\begin{eqnarray*}
\Upsilon_0&=&-\alpha^{1-p}\left[ 2\alpha^{-1}\alpha'a_{22}+\beta^{-1}\beta'b_{11}+b_{22}-a_{33}+\frac{p+3}2\alpha^{p-2}\beta^{-2}\mathbf{q}_{tt}+\frac{p+2}{2(p+3)}\alpha^{1-p} \beta^2 (a_{32})^2\right. \\
&&\left.-\frac{p+1}{p+3}\alpha^{1-p}\beta^2 a_{32}b_{21}-\frac{2}{p+3}\alpha^{1-p}\beta^2(b_{21})^2 +a_{11}\left(\beta^{-1}\beta''+2\alpha^{-1}\beta^{-1}\alpha'\beta'-\beta^{-2}(\beta')^2\right)\right]>0,
\end{eqnarray*}
where the coefficients $a_{ij}$ and $b_{ij}$ are given by the following lemma.

\begin{lemma}\label{lm8}
Under the stretched modified Fermi coordinate defined by $\Phi_\varepsilon(z,s)$, we get
\begin{eqnarray*}
\nonumber\Div(A(\varepsilon y)\nabla v)&=& a_{11}(\varepsilon z)v_{zz}+2\varepsilon s a_{22}(\varepsilon z)v_{sz} +\left(a_{31}(\varepsilon z)+\varepsilon s a_{32}(\varepsilon z) +\varepsilon^2 s^2 a_{33}(\varepsilon z)\right)v_{ss} \\
&& +\varepsilon b_{11}(\varepsilon z)v_z +\left(\varepsilon b_{21}(\varepsilon z)+\varepsilon^2 s b_{22}(\varepsilon z)\right) v_s +B_0(v),
\end{eqnarray*}
where
\[a_{11}(\theta)=\frac{\langle{A^*}n,n\rangle}{1-\langle\gamma',n\rangle^2},\qquad a_{22}(\theta)=-\frac{\langle{A^*}n,n'\rangle}{1-\langle\gamma',n\rangle^2}-\frac{\langle{A^*_t}n,\gamma'\rangle}{1-\langle\gamma',n\rangle^2}, \]
\[a_{31}(\theta)=\frac{\langle{A^*}\gamma',\gamma'\rangle}{1-\langle\gamma',n\rangle^2}, \qquad a_{32}=\frac{\langle{A^*_t}\gamma',\gamma'\rangle}{1-\langle\gamma',n\rangle^2}+ \frac{2\langle{A^*}\gamma',n'\rangle}{1-\langle\gamma',n\rangle^2}-\frac{2\langle\gamma',n'\rangle\langle{A^*}\gamma',\gamma'\rangle}{\left(1-\langle\gamma',n\rangle^2\right)^2}, \]
\begin{eqnarray*}
a_{33}(\theta)&=& \frac1{1-\langle\gamma',n\rangle^2}\left(\langle{A^*}n',n'\rangle +2\langle{A^*_t}\gamma',n'\rangle+\frac12\langle{A^*_{tt}}\gamma',\gamma'\rangle\right)  \\
&&-\frac{2\langle\gamma',n'\rangle}{\left(1-\langle\gamma',n\rangle^2\right)^2}\left(\langle{A^*_t} \gamma',\gamma'\rangle +2\langle{A^*}\gamma',n'\rangle\right)  \\
&&+\left(\frac{4\langle\gamma',n'\rangle^2}{\left(1-\langle\gamma',n\rangle^2\right)^3}- \frac{\langle n',n'\rangle}{\left(1-\langle\gamma',n\rangle^2\right)^2}\right)\langle{A^*}\gamma',\gamma'\rangle,
\end{eqnarray*}
\[b_{11}(\theta)=\left[\frac{\langle{A^*}n,n\rangle}{1-\langle\gamma',n\rangle^2}\right]_{\theta}-\frac12\left(\frac1{1-\langle\gamma',n\rangle^2}\right)_\theta \langle{A^*}n,n\rangle -\frac{\langle{A^*}n,n'\rangle}{1-\langle\gamma',n\rangle^2}-\frac{\langle{A^*_t}n,\gamma'\rangle}{1-\langle\gamma',n\rangle^2},\]
\[b_{21}(\theta)=\frac{\langle\gamma',n'\rangle}{1-\langle\gamma',n\rangle^2}a_{31}+a_{32},\]
\[b_{22}(\theta)=\frac12\frac{(1-\langle\gamma',n\rangle^2)_\theta}{1-\langle\gamma',n\rangle^2}a_{22}+\left[\frac{\langle n',n'\rangle}{1-\langle\gamma',n\rangle^2}-\frac{2\langle\gamma',n'\rangle^2}{(1-\langle\gamma',n\rangle^2)^2}\right]a_{31}+\frac{\langle\gamma',n'\rangle}{1-\langle\gamma', n\rangle^2}a_{32} +\partial_\theta a_{22}+2a_{33}\]
and
\[B_0(v)=\varepsilon a_{12}(\varepsilon z,s)v_{zz}+\varepsilon^2 a_{23}(\varepsilon z.s)v_{zs}+\varepsilon^3a_{33}(\varepsilon z,s)v_{ss} +\varepsilon^2 b_{12}(\varepsilon z,s) v_z +\varepsilon^3 b_{23}(\varepsilon z,s)v_s.\]
In the expression above, funtions $a_{12}$, $a_{23}$, $a_{33}$, $b_{12}$ and $b_{23}$ are smooth functions satisfying the following estimate
\[|a_{12}(\varepsilon z, s)|\le C(1+|s|), \quad |a_{23}(\varepsilon z, s)|\le C(1+|s|^2), \quad |a_{33}(\varepsilon z, s)|\le C(1+|s|^3),\]
and
\[|b_{12}(\varepsilon z, s)|\le C(1+|s|), \quad |b_{23}(\varepsilon z, s)|\le C(1+|s|^2).\]
\end{lemma}

Moreover,
\begin{equation}\label{80}
\alpha(\theta)=\mathbf{q}(\theta,0), \qquad \beta(\theta)=\frac{\left[\mathbf{q}(\theta,0)\right]^{\frac{p-1}2}}{\left[a_{31}(\theta)\right]^{\frac12}}.
\end{equation}
and
\begin{equation}\label{e88}
\mathbf{q}(\theta, t)=\mathbf{\Psi}^{\frac1p}(\gamma(\theta)+tn(\theta)).
\end{equation}

Then for each  integer $N>0$, there exists a sequence of $\varepsilon$, \textit{i.e.}, $\{\varepsilon_l\}$ converging to $0$ such that
\begin{equation}\label{1}
\left\{\begin{array}{ll}
-\varepsilon^2\Div (A(x)\nabla u)=|u|^p-\mathbf{\Psi}(x), &\mbox{in $\Omega$,} \\
u=0, & \mbox{on $\partial \Omega$},
\end{array}
\right.
\end{equation}
has a positive solutions $u_{\varepsilon_l}$ with exactly $N$ concentration layers at mutual distance $O(\varepsilon_l|\log\varepsilon_l|)$, the center of mass of $N$ concentration layers collapses to $\Gamma$ at speed $\varepsilon_l^{1+\mu}$ for small positive constant $\mu\in(0,1/2)$. More precisely $u_{\varepsilon_l}$ has the form
\begin{eqnarray*}
u_{\varepsilon_l}(y_1,y_2)\approx -\mathbf{\Psi}^{\frac1p}(y_1,y_2)+ \mathbf{\Psi}^{\frac1p}(\gamma(\theta))\sum_{k=1}^N w\left(\left[\frac{\mathbf{\Psi}^{\frac{p-1}p}(1-\langle\gamma',n\rangle)}{\langle A^*n,n\rangle}\right]^{\frac12}\frac{t-\varepsilon_l f_k}{\varepsilon_l}\right),
\end{eqnarray*}
where $\gamma$ is a natural parametrization of $\Gamma$, $n$ is the unit vector defined by
\begin{equation}\label{e102}
n(\theta)=\frac{A(\gamma(\theta))\nu(\theta)}{|A(\gamma(\theta))\nu(\theta)|}.
\end{equation}
and $w$ is  the unique solution of the following problem
\begin{equation}\label{29}
-w''=|1-w|^p -1, \qquad w>0 \quad \mathrm{in} \quad \mathbb R, \qquad w'(0)=w(\pm \infty).
\end{equation}
In the expression above, the functions $f_j$'s satisfy
\[\|f_j\|_{L^\infty(0,1)}\le C|\log\varepsilon_l|^2,\qquad \sum_{j=1}^N f_j =O(\frac1{|\log\varepsilon_l|^{\frac32}}),\]
\[\min_{1\le j\le N}(f_{j+1}-f_j)\approx\frac2{\sqrt{p}}|\log\varepsilon_l|\left[\frac{\langle A^*n,n\rangle}{\Psi^{\frac{p-1}p}(1-\langle\gamma',n\rangle)}\right]^{\frac12}\]
and solves the Jacobi-Toda system for $j=1,2,\cdots,N$
