\begin{remark}
\label{rmk: CGT lighttail from de1994}
    We note that the cumulant generating function (C.G.T.) bound derived from \eqref{equ: de1994bound} suggests that 
    \begin{equation}
        \label{equ: de1994bound CGT}
        K_{S}(\lambda)\leq \frac{1}{2} K_{S'}(2\lambda),
    \end{equation} 
    where $K_S(\cdot)$ denotes the C.G.T. of $S$, and $S = \sumn d_i$, $S' = \sumn e_i$ for simplicity.

    We note \[K'_{S}(0) = \E(\sumn d_i) = \E(\sumn \E [d_i|\G]) = K'_{S'}(0) = \frac{d\; \frac{1}{2} K_{S'}(2\lambda)}{d\lambda}\Bigg|_{\lambda = 0}.\]
    To make inequality \eqref{equ: de1994bound CGT} hold in the neighborhood of $\lambda = 0$, a necessary condition is that at zero, the second derivative of $ K_{S}(\lambda)$ is not greater than the second derivative of $\frac{1}{2} K_{S'}(2\lambda)$, i.e., $K"_{S}(0) \leq  \frac{d^2\; \frac{1}{2} K_{S'}(2\lambda)}{d\lambda^2}\Big|_{\lambda = 0} = 2K"_{S'}(0)$. This is equivalent to inequality \eqref{equ: Decoupling Inequality for the Variance}. 

    Similarly, in viewing inequality \eqref{equ: de1994bound}, we note that $M_S(0)= \sqrt{M_{S'}(0)} = 1$, and $M"_{S}(0) \leq  \frac{d^2\; \frac{1}{2} M_{S'}(2\lambda)}{d\lambda^2}\Big|_{\lambda = 0}$. 
    \[\frac{d (M_{S'}(2\lambda))^{\frac{1}{2}}}{d\lambda} \Bigg|_{\lambda = 0} = \frac{1}{2}2(M_{S'}(0))^{-\frac{1}{2}} M'_{S'}(0) =  M'_{S'}(0) = M'_{S}(0).\] With the same argument above, we have 
    \begin{align*}
        \frac{d^2\; (M_{S'}(2\lambda))^{\frac{1}{2}}}{d\lambda^2}\Bigg|_{\lambda = 0} & = -(M_{S'}(0))^{-\frac{3}{2}} (M'_{S'}(0))^2 + 2 (M_{S'}(0))^{-\frac{1}{2}} M"_{S'}(0)\\
        &= 2M"_{S'}(0) - (M'_{S'}(0))^2
        \geq M^"_S(0), 
    \end{align*}
    which also suggests \eqref{equ: Refined decoupling inequality for 2nd moment} holds. However, our results generalize the consequences of \cite{de1994bound} such that the second-moment inequality and variance inequality can hold not only for light-tailed sums but also for any heavy-tailed sum, as long as the square-integrability is assumed.
\end{remark}

