The first result on the singular solutions of incompressible Euler equations is a 1D model constructed by Constantin, Lax and Majda \cite{CLM}. Thanks to the nice properties of Hilbert transform, they solved the model explicitly. Since then there are rich developments. In 2019, an impressive progress was made by Elgindi \cite{El-annals}. He showed that the solutions to the original incompressible Euler equation blow up in finite time for some initial $ C^{1, \alpha}$ velocity with $\alpha$ small enough. The idea could trace back to \cite{KS}. Roughly speaking, the main thing is that when $\alpha$ goes to zero, the limiting system of the Euler equations has several nice self-similar singular solutions. The numerical studies by Hou and his collaborators \cite{LH} are also very interesting.
For detailed literature, one may refer to the survey papers \cite{El-survey, Elgindi-survey25}.

The first 2D model appeared in \cite{CS} (with a sign change $w=-w$) has the form
\begin{equation}\label{1.1}
 \omega_{t} = Z_{11}\omega\,\omega.
\end{equation}
For a wide class of negative initial datum, Constantin and Sun \cite{CS} constructed global regular solutions to this model. When the whole space is changed to an ellipse, some explicit singular solutions was constructed in \cite{Du-Euler}. Very recently, Bianchini and Elgindi \cite{BE} showed that the equation \eqref{1.1} blows up in finite time for a large class of initial data.

Here comes our theorem.
\noindent

\begin{equation}\label{1.1}
	\omega_{t} = Z_{11}\omega\,\omega.
\end{equation}

\begin{quote}
 \small \textbf{Abstract}:
We consider the following model equation:
\begin{equation}
 \omega_{t} = Z_{11}\omega\,\omega ,
\end{equation}
where \begin{equation}
 Z_{11} = \partial_{11}\Delta^{-1}
\end{equation}
is a Calderon-Zygmond operator. We get the existence of self-similar singular solutions with a special form. The main difficulty is the degeneracy of the operator $Z_{11}$ that is overcome by the spectral uncertainty principle. We also show that the solution to this model blows up in finite time if the initial datum is compactly supported and has a positive integral.

The first 2D model appeared in \cite{CS} (with a sign change $w=-w$) has the form
\begin{equation}\label{1.1}
 \omega_{t} = Z_{11}\omega\,\omega.
\end{equation}
For a wide class of negative initial datum, Constantin and Sun \cite{CS} constructed global regular solutions to this model. When the whole space is changed to an ellipse, some explicit singular solutions was constructed in \cite{Du-Euler}. Very recently, Bianchini and Elgindi \cite{BE} showed that the equation \eqref{1.1} blows up in finite time for a large class of initial data.

\begin{remark}
This is the first general result on the existence of self-similar singular solutions for the 2D nonlocal models.
\end{remark}

\begin{theorem}\label{thm-2}
Assume that the equation \eqref{1.1} is equipped with initial data $\omega(x,0) = \omega_{0}$. If $\omega_{0} \in C^{\alpha}$ with $\alpha>0$, $\omega_{0}$ is compactly supported in $\mathbb{R}^{2}$ with $\int_{\mathbb{R}^{2}}\omega_{0} dx>0$, then the solution to \eqref{1.1} blows up in finite time.
\end{theorem}

\begin{theorem}[Logvinenko-Sereda theorem]\label{thm-3} 
Let $f\in L^{2}(\mathbb{R}^{n}) $ and $\hat{f}$ be the Fourier transform of f. If $supp(\hat{f}) \subset A \Subset \mathbb{R}^{n} $, $B\subset\mathbb{R}^{n}$, $N(B) > 0$, then $\|f\|_{L^{2}(B)}\ge C^{-1}\|f\|_{L^{2}(\mathbb{R}^{n})}$ where $C$ is a constant only depending on $A$, $B$ and $n$.
\end{theorem}

\begin{corollary}\label{cor}
 Assume f $\in$ $L^{2}(\mathbb{R}^{n})$, supp $f \subset A \Subset \mathbb{R}^{n}$, $B \subset \mathbb{R}^{n}$, $N(B) \ne 0$. Then there exists C=C (A,B,n), such that $\|\hat{f}\|_{L^{2}(B)} \ge C^{-1}\|\hat{f}\|_{L^{2}(\mathbb{R}^{n})}$, where $\hat{f}$ is the Fourier transform of f.
\end{corollary}

\begin{proof}[Proof of Theorem \ref{thm-1}]
We note that
\begin{equation}
 \eqref{1.2} \iff (Z_{11} \, Q - 1) \, Q = 0.
\end{equation}
Thus for any subset $A \subset \mathbb{R}^2$, solving \eqref{2.1} reduces to finding $Q$ such that
\begin{equation}
\begin{cases}
1=Z_{11}Q,\quad x \in A ,\\
Q=0, \qquad \; \, x \notin A .
\end{cases}
\end{equation}
For $\phi \in L^{2}(a)$ define
\begin{equation}
 \tilde{\phi}=\begin{cases}
 \phi ,\quad x \in A ,\\
 0 ,\quad x \notin A,
\end{cases}
\end{equation}
and
\begin{equation} 
 L : L^{2}(A) \longrightarrow L^{2}(A), \ L\phi = Z_{11}\tilde{\phi}|_{A}.
\end{equation}
Next we will prove that $L$ is coercive.
Define
\begin{equation}
 \Omega = \left\{k > \frac{\lambda_{1}}{\lambda_{2}} > \frac{1}{k} |\lambda \ne 0 \right\}.
\end{equation}
Then
\begin{equation}
\begin{split}
 \left\langle L \,\phi,\phi \right\rangle_{L^{2}(A)} = \left\langle L \,\tilde{\phi},\tilde{\phi} \right\rangle_{L^{2}(R^{2})}
 = \int_{\mathbb{R}^2} F(Z_{11} \tilde{\phi}) \, F(\tilde{\phi})d\lambda &= \int_{\mathbb{R}^2} \frac{\lambda_1^2}{\lambda_1^2 + \lambda_2^2} |F(\tilde{\phi}) |^2 d\lambda \\
 &\ge \int_{\Omega}\frac{1}{1+k^{2}} | F(\tilde{\phi}) |^2 d\lambda.
\end{split}\end{equation}
From Corollary \ref{cor} we have
\begin{equation}
 \int_{\Omega}\frac{1}{1+k^{2}} | F(\tilde{\phi}) |^2 d\lambda
 \ge \frac{1}{1+k^{2}}C_{(\Omega,A))}\int_{R^{2}}| F(\tilde{\phi}) |^2 d\lambda.
\end{equation}
Thus,
\begin{equation}\label{2.9}
 \langle L \phi,\phi \rangle_{L^{2}(A)} \ge \delta\:\|\phi\|_{L^{2}(A)}^{2} \text{ for } \delta> 0.
\end{equation}
This implies $L$ is coercive.

\begin{proof}[Proof of Theorem \ref{thm-2}] 
First we have
\begin{equation}
 \int_{\mathbb{R}^{2}} \omega_{t} d\lambda = \int_{\mathbb{R}^{2}}Z_{11} \omega\,\omega d\lambda.
\end{equation}
Let $\hat{\omega}$ be the Fourier transform of $\omega$. Then
\begin{equation}\begin{split}
 \int_{\mathbb{R}^{2}}Z_{11}\omega\,\omega d\lambda
 =\int_{\mathbb{R}^{2}}\widehat{Z_{11}\omega} \hat{\omega}d\lambda =\int_{\mathbb{R}^{2}}\dfrac{\lambda_{1}^{2}}{\lambda_{1}^{2}+\lambda_{2}^{2}}\hat{\omega}\,\hat{\omega}d\lambda
 \ge \int_{\Omega}\frac{| \hat{\omega}|^{2}}{1+k^{2}}d\lambda. 
\end{split}\end{equation}
It follows from Corollary \ref{cor} that
\begin{equation}
 \frac{\int_{\Omega} |\hat{\omega}|^{2}d\lambda}{\int_{\mathbb{R}^{2}}|\hat{\omega}|^{2}d\lambda} \ge C_{(\Omega,\: A)} > 0. 
\end{equation}
Thus,
\begin{equation}
 \int_{\Omega}\frac{|\hat{\omega}|^{2}}{1+k^{2}}d\lambda \ge \frac{C_{(\Omega,\: A)}}{1+k^{2}}\int_{\mathbb{R}^{2}} \left|\hat{\omega}\right|d\lambda,
\end{equation}
from which we obtain that
\begin{equation}
 \omega_{t} \ge \delta\:\omega^{2} \text{ for some } \delta > 0.
\end{equation}
Therefore the solution of equation \eqref{1.1} blows up in finite time under the conditions of Theorem \ref{thm-2}.
\end{proof}

