\section{The cases $N=m^2\pm 1$}\label{sec-3}
The previous section suggests that if $N>1/4$ is a positive rational number for which the rank of $\mathcal{E}_N$ is positive, we may be able to construct integer triangles with $R/r=N$.
So we are facing two problems: Find  rational numbers $N>1/4$ for which the rank of $\mathcal{E}_N$ is positive, and find rational points on such
curves that satisfy condition~\eqref{eq-13'}.
In Section~\ref{sec:triangles} we will show that whenever $\mathcal{E}_N$ has positive rank, the curve has infinitely many rational points satisfying condition~\eqref{eq-13'},
and that these points lead to infinitely many non-similar integer triangles with $R/r=N$. 
In this section we first show that for each $N=m^2\pm 1>1/4$, $m\in\Q$, the rank of $\mathcal{E}_N$ is positive.
We provide explicit formulas for the sides $f,g,h$ of integer triangles with $R/r=N\in\Q$.   

\begin{thm}
    \label{th:4}
    \begin{itemize}
    	\item [(i)] If $N=m^2+1$ for a rational number $m>1$ the rank of $\mathcal{E}_N$ is positive with a non-torsion point 
    	$$P=\Bigl(\frac{1}{m^2}, \frac{3m^2+1}{m^3}\Bigr)$$
    	such that the point 
    	\begin{multline*}
    		-P-T_6^+=\Bigl(-\frac{(4m^2+3)(m+1)^2}{(2m^2-m+1)^2}, \\ \frac{2(m+1)(4m^2+3)(m^2+1)(2m^3+m^2+2m-1)}{(2m^2-m+1)^3}\Bigr)
    	\end{multline*}
    	leads to the triangle 
    	$$f=(m-1)(2m^2+m+1)^2, \ g=(m+1)(2m^2-m+1)^2, \ h=4m(m^2+1).$$

    	\item[(ii)] If $N=m^2-1>1/4$  for a rational number $m>1$ the rank of $\mathcal{E}_N$ is positive with a non-torsion point 
    	$$P=\Bigl(\frac{1}{m^2}, \frac{m^2-1}{m^3}\Bigr)$$
    	such that the point
    	$$-P-T_6^+=\Bigl(-\frac{4m^2-5}{(2m-1)^2}, \frac{2(m-1)(4m^2-5)(2m^2+m+1)}{(2m-1)^3}\Bigr)$$
    	 leads to the triangle 
    	$$f=(m-1)(2m+1)^2, \ g=(m+1)(2m-1)^2, \ h=4m.$$
    \end{itemize}    
\end{thm}
\begin{proof}
(i) By enforcing $u=N-1$ on $\mathcal{E}_N$, the expression $N-1$ must be a square, say $m^2$ for some rational number $m$. 
Then, $N=m^2+1$ and the corresponding elliptic curve $\mathcal{E}_N$ owns the rational non-torsion  point
$$P=\Bigl(\frac{1}{m^2}, \frac{3m^2+1}{m^3}\Bigr).$$
By the addition law, we compute 
\begin{multline*}
	-P-T_6^+=\Bigl(-\frac{(4m^2+3)(m+1)^2}{(2m^2-m+1)^2}, \\ \frac{2(m+1)(4m^2+3)(m^2+1)(2m^3+m^2+2m-1)}{(2m^2-m+1)^3}\Bigr).
\end{multline*}
By taking 
$(u,v)=-P-T_6^+$
we observe that condition~\eqref{eq-13'} holds, hence by Theorem~\ref{th:1} we get 
$$f=(m-1)(2m^2+m+1)^2, \ g=(m+1)(2m^2-m+1)^2, \ h=4m(m^2+1).$$
(ii) In a similar fashion, by enforcing $u=N+1$ on $\mathcal{E}_N$, the expression $N+1$ must be a square, say $m^2$ for some rational number $m$. 
Then, $N=m^2-1$ and the corresponding elliptic curve $\mathcal{E}_N$ owns the rational non-torsion  point
$$P=\Bigl(\frac{1}{m^2}, \frac{m^2-1}{m^3}\Bigr).$$
By the addition law, we compute 
$$-P-T_6^+=\Bigl(-\frac{4m^2-5}{(2m-1)^2}, \frac{2(m-1)(4m^2-5)(2m^2+m+1)}{(2m-1)^3}\Bigr).$$
By taking 
$(u,v)=-P-T_6^+$
we observe that  condition~\eqref{eq-13'} holds, hence by Theorem~\ref{th:1} we get 
$$f=(m-1)(2m+1)^2, \ g=(m+1)(2m-1)^2, \ h=4m.$$
\end{proof}

\section{Infinitely many triangles for curves of positive rank}\label{sec:triangles}
We start by determining just one rational point on $\mathcal{E}_N$ that fulfills condition~(\ref{eq-13'}).
This point will then be the stepping stone for an infinite number of such points.

\begin{lem}\label{lem:1a}
If $\mathcal{E}_N$ has positive rank for a rational number $N>1/4$, then there are rational points on $\mathcal{E}_N$ that satisfy condition~\eqref{eq-13'}.
\end{lem}
\begin{proof}
Let $R=(u_R,v_R)$ be a rational non-torsion point on $\mathcal{E}_N$ that does not satisfy condition~\eqref{eq-13'}.
If $u_R<1-4n$, then $R+T_3^-$ is a rational non-torison point satisfying condition~\eqref{eq-13'}.
If $0<u_R<1$, then $-(R+T_6^-)$ is a rational non-torison point satisfying condition~\eqref{eq-13'}.
See Figure~\ref{fig:3}.
