ref_dict.ThmConcentration.LastSection.Intro:
\begin{theorem}\label{ThmConcentration.LastSection.Intro}
Fix   $d\in \N$ and $\eps > 0$. Let $Q = \{a^{2j-1}\}_{j=1}^\infty \subseteq \N$, where  $a= \lceil 32/\eps + 2 \rceil$. Then, for all $m_1<\ldots< m_d<k\in Q$  and all step preserving maps $F:S_{\ell_\infty^k}^+ \to S_{\ell_1^k}^+$ with $\omega_F(\frac{1}{d})\le \frac{\eps}{8}$, we have
\[\Big\|F(z(\bar m))-\frac{1}{k}\sum_{i=1}^k e_i\Big\|_1\le \eps,\]
where $(e_i)_{i=1}^k$ denotes the standard basis of $\ell_1^k$. 
\end{theorem}

ref_dict.Lemma.Separation:
\begin{lemma}\label{Lemma.Separation}
Let $d\in\N$ and $\eps > 0$, and let $P \subseteq \N$ and $M \subseteq \N$ be subsets satisfying {\bf Assumption} $\boldsymbol{A(d,\eps)}$. Let $\bar m,\bar n\in [M]^d$ such that $m_1<n_1<\ldots<m_d<n_d$, let $k> n_d$, let $u=((a_s)_{s=1}^d,(b_s)_{s=1}^d,c) \in S_{\ell_\infty^{2d+1}}$, and let $F = (F_i)_{i=1}^k: S_{\ell_\infty^k} \to S_{X_k}$ be a step preserving function with $F_{i}(x(\bar m,u,k))=0$ for all $i\in (m_d,k]$, where $x(\bar m,u,k) \in S_{\ell_\infty^k}$ is defined in \eqref{Definition.x.m.u.k}. Then 
\[\|F(x(\bar m,u,k))-F(x(\bar n,u,k))\|_X>1-\eps.\] 
\end{lemma}

ref_dict.Lemma.Equivariant.Injective:
\begin{lemma}\label{Lemma.Equivariant.Injective}
Let $k\in\N$ and $F=(F_i)_{i=1}^k\colon S_{\ell_\infty^k}\to S_{\ell_1^k}$ be  equivariant with respect to basis permutation. Then $F$ is step preserving.
\end{lemma}

ref_dict.Thm.Intro.Homeo.Equiv.Intro:
\begin{theorem}\label{Thm.Intro.Homeo.Equiv.Intro}
Let $d \in \N$. Then for any  $k \geq 19^{2d-1}+1$ and any step preserving continuous map   $F:S_{\ell_\infty^k}\to S_{\ell_1^k}$ such that $F(1,\ldots,1)\neq F(-1,\ldots,-1)$, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{\ell_1^k})_{k=1}^\infty$ of equi-uniformly continuous step preserving homeomorphisms.
\end{theorem}

ref_dict.Defi.Local.Prop.Q:
\begin{definition}\label{Defi.Local.Prop.Q} Let $(e_i)_i$ be an unconditional basis of a Banach space $X$. We say that $(e_i)_i$ has the {\it local Property $\mathcal Q$} if there exists a constant $\gamma>0$ such that for any $d\in \N$, $\eps \in (0,1)$, there exists an infinite subset $Q \subseteq \N$ such that for all $\bar m \in [Q]^d$, all $k\in Q$ with $m_d<k$, and for all $F:S_{\ell_\infty^k}^+ \to S_{X_k}^+$ step preserving map with $\omega_F(\frac1d)\le \gamma\eps$ , we have 
\[\Big\|F(z(\bar m))-\frac{\sum_{i=1}^ke_i}{\|\sum_{i=1}^ke_i\|_X}\Big\|_X\le \eps.\]
\end{definition}

ref_dict.LemmaCardOfSupportPreservingToSupportPre:
\begin{lemma}\label{LemmaCardOfSupportPreservingToSupportPreserving}
Let  $k\in\N$ and $F\colon S_{\ell^k_\infty}\to S_{\ell_1^k} $ be an injective continuous map which does not increase support size. Then, there is a $\pi\in \mathrm{Per}_k$ such that $F\circ P_\pi$ is  support preserving.
In particular, such $F$   preserves support size. 
\end{lemma}

full_context:
In 2012, Kasparov and Yu introduced a new and intriguing property for Banach spaces: {\it{Property (H)}}. Recall, denoting the unit sphere of a Banach space $Y$ by $S_Y$, we say that a Banach space $X$ has {\it{Property (H)}} if there are a uniformly continuous map $F\colon S_X\to S_{\ell_2}$ and increasing sequences $(X_n)_n$ and $(H_n)_n$ of finite dimensional subspaces such that $\bigcup_nX_n$ and $\bigcup_n H_n$ are dense in $X$ and $\ell_2$, respectively, and such that the restrictions of $F$ to each $ S_{X_n}$ is a homeomorphism onto $S_{H_n}$ (see \cite[Definition 1.1]{KasparovYu2012GeoTop}). We call the sequence $(X_n)_n$ a {\it paving} of $X$. Property (H) is quite unique in a few aspects. While it may look at first glance to be a sort of ``nonlinear embedding/equivalence property'' between Banach spaces, this is really not the case since the inverses of the restrictions $F\restriction S_{X_n}$ need not be equi-uniformly continuous. This lack of uniform continuity places Property (H) in an unusual spot: it is somewhat simultaneously a geometric and a topological property which, on top of it, is also related to the local theory of Banach spaces since it must preserve the pavings $(X_n)_n$ and $(H_n)_n$.

The known method of showing that certain spaces have Property (H) relies on Mazur maps. Recall, if $p\in [1,\infty)$, then the map 
\begin{align*}
 M_{p}\colon S_{\ell_p}&\to S_{\ell_2}\\
(x_n)_n &\mapsto\left(\mathrm{sign}(x_n)|x_n|^{p/2}\right)_n
\end{align*}
is a uniform homeomorphism between the unit spheres of $\ell_p$ and $\ell_2$ (\cite[Theorem 9.1]{BenyaminiLindenstrauss2000Book}). Considering the finite dimensional spaces $(\ell_p^k)_k$ and $(\ell_2^k)_k$ as subspaces of $\ell_p$ and $\ell_2$, respectively, these maps restrict to uniform homeomorphisms between the unit spheres of $\ell_p^k$ and $\ell_2^k$. Hence all $\ell_p$'s, for $p\in [1,\infty)$, have Property (H). 
More generally, using generalized Mazur maps, one can obtain that every Banach space $X$ with an unconditional basis which does not contain the spaces $(\ell_\infty^k)_k$ with bounded distortion also has Property (H) (see \cite[Theorem 1]{ChengWang2018JMAA}). This is so because the unit sphere of any such space $X$ is uniformly homeomorphic to the one of $\ell_2$ by a ``Mazur type map'' which preserves the canonical pavings given by the unconditional basis of $X$ and by the canonical basis of $\ell_2$ (see \cite[Theorem 2.1]{OdellSchlumprecht1994Acta} and its proof). Moreover, Property (H) also holds for Banach lattices not containing $(\ell_\infty^k)_k$ and for Schatten $p$-classes, for $p\in [1,\infty)$, as noticed in \cite[Page 1860]{KasparovYu2012GeoTop}.

To help illustrate how little is known about Problem \ref{ProblemPropH}, we mention that it is not even known if $c_0$ fails the requirements of Property (H) with its standard paving. Precisely, is there a uniformly continuous map $F\colon S_{c_0} \to S_{\ell_2}$ such that, for some increasing sequence $(n_k)_k$ of naturals, the restriction of $F$ to the unit sphere of each $\ell_\infty^{n_k}$ has the whole $S_{\ell_2^{n_k}}$ as its homeomorphic image? As asked by Johnson in \cite{JohnsonOverFlow}, even the following remains strikingly open:

\begin{problem}[W.\ B.\ Johnson]
Is there a sequence of homeomorphisms $(F_k)_k$ between the unit spheres of $\ell_\infty^k$ and $\ell_2^k$ whose Lipschitz constants are (uniformly) bounded?\label{ProblemJohnson}
\end{problem}

The next two theorems give a strong negative answer to Problem \ref{ProblemJohnson} for certain classes of maps. We start by properly defining these classes. For that, given $k\in \mathbb{N}$ and $x=(x_i)_{i=1}^k\in \mathbb{R}^k$, $\mathrm{supp}(x)$ denotes $\{i\in \{1,\ldots,k\}\mid x_i\neq 0\}$. Given $F\colon S_{\ell_\infty^k}\to S_{\ell_1^k}$, we write $F =(F_i)_{i=1}^k$; so, each $F_i$ is the composition of $F$ with the canonical projection of $\ell_1^k$ onto its $i$th coordinate. 
\begin{enumerate}[label=\Roman*]
 \item We say that a map $F\colon S_{\ell^k_\infty}\to S_{\ell_1^k}$ {\it{does not increase support size}} if 
 the cardinality of $\mathrm{supp}(F(x))$ is at most the one of $\mathrm{supp}(x)$ for all $ x\in S_{\ell_\infty^k}.$
 \item We say that $F$ is {\it{step preserving}} if for all $x=(x_i)_{i=1}^k\in S_{\ell_\infty^k}$
and all $i,j\in \{1,\ldots, k\}$, $x_i=x_j$ implies $F_i(x)=F_j(x)$. 
\end{enumerate}
We postpone until Section \ref{SectionExamples} a discussion of examples of maps satisfying these properties. For now, we just point out the obvious: (1) the class of maps which do not increase support size includes all {\it support preserving maps}, i.e., maps such that $\mathrm{supp}(F(x))=\mathrm{supp}(x)$ for all $x\in S_{\ell_\infty^k}$, and (2) the class of step preserving maps includes all maps which are equivariant with respect to basis permutation (see more details in Section \ref{SectionExamples} below).

We obtain the following theorem for functions which do not increase support size. Recall that, for a map $F\colon (X,d_X)\to (Y,d_Y)$ between metric spaces, its {\it modulus of uniform continuity} is given by 
\[\omega_F(t)=\sup\left\{d_Y(F(x),F(y))\mid x,y\in X, \: d_X(x,y)\leq t\right\}, \text{ for }\ t\in [0,\infty).\]
We say that a sequence of maps $(F_k\colon X_k\to Y_k)_k$ between metric spaces is {\it equi-uniformly continuous} if
\[\forall\varepsilon>0, \ \exists \delta>0\text{ such that } \omega_{F_k}(\delta)<\varepsilon,\ \text{for all}\ k\in\mathbb{N}.\]

\begin{problem}[G.\ Kasparov and G.\ Yu]
    Does $c_0$ have Property (H)? In fact, do all separable Banach spaces have Property (H)?\label{ProblemPropH}
\end{problem}

We obtain the following theorem for functions which do not increase support size. Recall that, for a map $F\colon (X,d_X)\to (Y,d_Y)$ between metric spaces, its {\it modulus of uniform continuity} is given by 
\[\omega_F(t)=\sup\left\{d_Y(F(x),F(y))\mid x,y\in X, \: d_X(x,y)\leq t\right\}, \text{ for }\ t\in [0,\infty).\]
We say that a sequence of maps $(F_k\colon X_k\to Y_k)_k$ between metric spaces is {\it equi-uniformly continuous} if
\[\forall\eps>0, \ \exists \delta>0\text{ such that } \omega_{F_k}(\delta)<\eps,\ \text{for all}\ k\in\N.\]

The proof of Theorem \ref{Thm.Intro.Supp.Card.Preserv} passes first through obtaining the same conclusion for support preserving maps. In this case, the map $F$ does not even need to be continuous: we show that no sequence of support preserving maps from the spheres of $\ell_\infty^k$ to the ones of $\ell_1^k$ can be equi-uniformly continuous (see Theorem \ref{Thm.Main}). Theorem \ref{Thm.Intro.Supp.Card.Preserv} is then obtained by showing that, if the map $F$ is furthermore assumed to be a homeomorphism, then, up to a permutation operator, it is in fact support preserving (see Lemma \ref{LemmaCardOfSupportPreservingToSupportPreserving}). For both these results, it will be necessary to apply an averaging procedure which makes the map equivariant with respect to basis permutation and, in particular, also step preserving (see Section \ref{SectionExamples} and Lemma \ref{Lemma.Equivariant.Injective} for details). For this, Brouwer's invariance of domain theorem and its consequence that continuous injective maps between spheres of $k$-dimensional spaces is surjective will be crucial.

\begin{theorem}\label{Thm.Intro.Homeo.Equiv.Intro}
Let $d \in \N$. Then for any $k \geq 19^{2d-1}+1$ and any step preserving continuous map $F:S_{\ell_\infty^k}\to S_{\ell_1^k}$ such that $F(1,\ldots,1)\neq F(-1,\ldots,-1)$, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{\ell_1^k})_{k=1}^\infty$ of equi-uniformly continuous step preserving homeomorphisms.
\end{theorem}

\begin{theorem}\label{Thm.Main}
Let $d \in \N$. Then for any $ k \geq 19^{2d-1}+1$ and any support preserving map $F:S_{\ell_\infty^k}\to S_{\ell_1^k}$, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{\ell_1^k})_{k=1}^\infty$ of equi-uniformly continuous support preserving maps.
\end{theorem}

\begin{lemma}\label{LemmaCardOfSupportPreservingToSupportPreserving}
Let $k\in\N$ and $F\colon S_{\ell^k_\infty}\to S_{\ell_1^k} $ be an injective continuous map which does not increase support size. Then, there is a $\pi\in \mathrm{Per}_k$ such that $F\circ P_\pi$ is support preserving.
In particular, such $F$ preserves support size. 
\end{lemma}

\begin{proof}[Proof of Theorem \ref{Thm.Intro.Supp.Card.Preserv}]
Let $k \geq 19^{2d-1}+1$ and let $F: S_{\ell_\infty^k} \to S_{\ell_1^k}$ be a homeomorphism that does not increase support size. Applying Lemma \ref{LemmaCardOfSupportPreservingToSupportPreserving} to $F$, we may assume furthermore that the map $F$ is support preserving. The result then follows from Theorem \ref{Thm.Main}.
\end{proof}

\begin{theorem}\label{Thm.Intro.Homeo.Equiv(bis)} Let $d\in \N$ and let $P \subseteq \N$ and $M = \{k_j\}_{j=1}^\infty \subseteq \N$ be subsets satisfying {\bf Assumption} $\boldsymbol{A(d,\frac{1}{2})}$ defined in \eqref{AssumptionA}. Then for any $k > k_{2d}$ and any step preserving continuous map $F:S_{\ell_\infty^k}\to S_{X_k}$ such that $F(1,\ldots,1)\neq F(-1,\ldots,-1)$, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{X_k})_k$ of equi-uniformly continuous step preserving homeomorphisms.
\end{theorem}

\begin{theorem}\label{Thm.Intro.Homeo.Equiv}
Let $d \in \N$ and $1\leq r<\infty$. Then for any $k \geq \lceil 19^r\rceil^{2d-1}+1$ and any step preserving continuous map $F:S_{\ell_\infty^k}\to S_{\ell_r^k}$ such that $F(1,\ldots,1)\neq F(-1,\ldots,-1)$, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{\ell_r^k})_{k=1}^\infty$ of equi-uniformly continuous step preserving homeomorphisms.
\end{theorem}

\begin{lemma}\label{Lemma.Equivariant.Injective}
Let $k\in\N$ and $F=(F_i)_{i=1}^k\colon S_{\ell_\infty^k}\to S_{\ell_1^k}$ be  equivariant with respect to basis permutation. Then $F$ is step preserving.
\end{lemma}

\begin{lemma}\label{LemmaCardOfSupportPreservingToSupportPreserving}
Let  $k\in\N$ and $F\colon S_{\ell^k_\infty}\to S_{\ell_1^k} $ be an injective continuous map which does not increase support size. Then, there is a $\pi\in \mathrm{Per}_k$ such that $F\circ P_\pi$ is  support preserving.
In particular, such $F$   preserves support size. 
\end{lemma}

\begin{theorem}\label{Thm.Intro.Supp.Card.Preserv}
Let $d \in \N$. Then for any $k \geq 19^{2d-1}+1$ and any homeomorphism $F:S_{\ell_\infty^k}\to S_{\ell_1^k}$ that does not increase support size, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{\ell_1^k})_{k=1}^\infty$ of equi-uniformly continuous homeomorphisms that do not increase support size.
\end{theorem}

\begin{theorem}\label{Thm.Main}
Let $d \in \N$. Then for any $ k \geq 19^{2d-1}+1$ and any support preserving map   $F:S_{\ell_\infty^k}\to S_{\ell_1^k}$, we have $\omega_F(\frac1d)\ge \frac12$. In particular, there is no sequence $(F_k:S_{\ell_\infty^k}\to S_{\ell_1^k})_{k=1}^\infty$ of equi-uniformly continuous support preserving maps.
\end{theorem}

