An important inverse problem in rough analysis is the task of recovering a path from Chen's iterated-integrals signature. At third truncation level and \emph{dimension} $d\geq 2$, this problem can be formalized through the group orbit of a special $d\times d\times d$ \emph{core tensor} $C$. 
For any invertible matrix $A\in\GL_d$, the \emph{matrix-tensor congruence action} on $C$ yields a tensor $G:=A*C$ with entries
\begin{equation}\label{eq:learningTask}G_{ijk}=\sum_{\alpha=1}^d\sum_{\beta=1}^d\sum_{\gamma=1}^dC_{\alpha\beta\gamma}A_{i\alpha}A_{j\beta}A_{k\gamma}\end{equation}
for $1\leq i,j,k\leq d$. 
In the context of rough analysis, the matrix $A$ encodes a piecewise linear path, and $G$ its third level signature. Throughout this work, the core tensor $C$ is fixed and represents the signature of the \emph{canonical axis path}. We consider $G$ as an element in the group orbit ${\GL_d}*C$ under the action \eqref{eq:learningTask}. 
The \emph{learning task} is to find $A\in\GL_d$ such that $G=A*C$, thereby recovering the path from its signature. 
In \cite[Theorem 6.2]{bib:PSS2019} it is shown that this problem has a unique (real) solution.
Our main result is an efficient algorithm that provably solves the learning task.

\begin{algorithm}
\caption{Tensor learning}\label{alg:linear_learning}
\textbf{Input:} $G\in{\GL_d}* C$\tcp*[r]{$C$ according to \eqref{eq:coretensor}}
$Q\gets \mathrm{I}_d$\;
\For{$s =1,\dots,d-1$}
   {$Q_{\mathsf{up}}\gets 
\begin{cases}
\mathsf{up_{\geq 4}}(G,s)&s\leq d-3\\
\mathsf{up_3}(G)&s=d-2\\
\mathsf{up_2}(G)&s=d-1. 
\end{cases}$\tcp*[r]{output $Q_{\mathsf{up}}$ of \Cref{alg:solve}, \ref{alg:transformUp_s2} or \ref{alg:transformUp_s3}}
    $H\gets Q_{\mathsf{up}}*G$\;
    $y\gets-H_{sss}^{-1}\begin{bmatrix}{H_{s,s+1,s}}&\dots& {H_{s,s+d,s}}\end{bmatrix}$\tcp*[r]{$y\in\R^{d-s}$}
    $Q_{\mathsf{dlow}}\gets D^{(s,H_{sss}^{-1})}L^{(s,y)}$\tcp*[r]{$L$ and $D$ according to \eqref{eq:def_Lsy}}
    $G\gets Q_{\mathsf{dlow}}*H$\;
    $Q\gets Q_{\mathsf{dlow}}WQ$\;
}
\Return $Q^{-1}D^{(s,G_{ddd}^{-1})}$\tcp*[r]{returns $A$ such that $G=A*C$}
\end{algorithm}

The algorithm creates a matrix $M\in\R^{(d-s)^2\times (d-s)}$ and a vector $B\in\R^{d-s}$ that contain certain linear combinations of the entries of our input tensor. 
\par
For a generic tensor from our orbit $G\in(\mathrm{I}_{s-1}\oplus\GL_{d-s+1})*C$, the resulting system $Mx=B$ is solvable (see \Cref{cor:MxB_solvable}). Furthermore, the matrix $M$ has full rank (see \Cref{prop:genericG_Mfullrank}). Hence, we compute the unique solution $x\in\R^{d-s}$ and return our upper transformation matrix $U^{(s,x)}$. 
If our system $Mx=B$ is not uniquely solvable, we perform a randomized change of coordinates and repeat recursively. 
\begin{theorem}\label{thm:linearSolSolvesAlgebraicSystem}
 For every $1\leq s<d-2$ and $G\in(\mathrm{I}_{s-1}\oplus\GL_{d-s+1})*C$, \Cref{alg:solve} returns $U^{(s,x)}W$ with $x\in\R^{d-s}$ and $W\in\GL_d$ such that $H:=U^{(s,x)}W*G$ satisfies the conditions \eqref{thm:LowerTransformations1} to \eqref{thm:LowerTransformations31} of \Cref{thm:LowerTransformations}. 
\end{theorem}

The proof is similar to \Cref{lem:IsBonC} and is therefore omitted. We proceed with the forward direction of \Cref{thm:substab}. First, we state it for $s=1$. 
\begin{proposition}\label{prop:thm:substabs1}
 If $G\in{\GL_d}*C$ satisfies 
 $G_{ijk}=C_{ijk}$ for all $i,j,k$ with $i=j=k=1$, 
 $k=1<i$ or $j=1<i$, 
 then $G\in(1\oplus {\GL_{d-1}})*C$. 
\end{proposition}
\begin{proof}
The proof is an adaptation of 
\cite[Theorem 6.2]{bib:PSS2019} so that it requires fewer assumptions on $G$. With $G_{111}=C_{111}=1$ and \Cref{lem:diagonalElemCongruence} we obtain the first row sum, 
$A_{1+}=1$. 
By rearranging summation we can write the entries of $G$ as 
\begin{align}G_{ijk}
=
{\sum_{\alpha}A_{i\alpha}A_{j\alpha}A_{k\alpha}}
&+
{\sum_{\alpha<\beta}3A_{i\alpha}A_{j\alpha}A_{k\beta}\label{eq:PPS2019Thm62}}+
{\sum_{\alpha<\beta}3A_{i\alpha}A_{j\beta}A_{k\beta}}
+
{\sum_{\alpha<\beta<\gamma}6A_{i\alpha}A_{j\beta}A_{k\gamma}}
\end{align}
for every $1\leq i,j,k\leq d$. We recall a factorization of \eqref{eq:PPS2019Thm62} from the proof of 
\cite[Theorem 6.2]{bib:PSS2019}, that is, 
$G_{ij1}
=\langle g_{i1}, A_{j\bullet}\rangle$ 
with 
\begin{equation}\label{eq:proofStrongerStab1}g_{i1}(\beta):=A_{i\beta}A_{1\beta}
+\sum_{\gamma>\beta}3A_{i\beta}A_{1\gamma}
+\sum_{\alpha<\beta}3A_{i\alpha}A_{1\beta}
+\sum_{\gamma>\beta>\alpha}6A_{i\alpha}A_{1\gamma}
\end{equation}
for $1\leq\beta\leq d$. Since $A$ is invertible and $G_{ij1}=C_{ij1}=0$ for all $j$ and $i>1$ by assumption, we have $g_{i1}=0$ for all $i>1$. 
We introduce a new factorization of \eqref{eq:PPS2019Thm62} similar to the above one, 
$G_{i1k}=\langle h_{i1},A_{k\bullet}\rangle $, 
where 
\begin{equation}\label{eq:proofStrongerStab1_1}
h_{i1}(\gamma):=A_{i\gamma}A_{1\gamma}
+\sum_{\gamma>\alpha}3A_{i\alpha}A_{1\alpha}
+\sum_{\gamma>\alpha}3A_{i\alpha}A_{1\gamma}
+\sum_{\gamma>\beta>\alpha}6A_{i\alpha}A_{1\beta}
 \end{equation}
 for $1\leq \gamma\leq d$. By assumption $G_{i1k}=C_{i1k}$ for $i>1$ and arbitrary $k$. Again, this implies for all $i>1$ that $h_{i1}=0$, and in particular
 \begin{equation}\label{eq:proofStrongerStab2}
 0=h_{i1}(1)=A_{i1}A_{11}.
 \end{equation}
Substituting $A_{1+}=1$ and \eqref{eq:proofStrongerStab2} in \eqref{eq:proofStrongerStab1} yields 
 $$0=g_{i1}(1)=A_{i1}A_{11}+\sum_{\gamma=2}^d3A_{i1}A_{1\gamma}
 =3A_{i1}\left(\sum_{\gamma=1}^dA_{1\gamma}\right)=3A_{i1}$$
 for all $i>1$, 
 that is $A_{21}=A_{31}=\dots=A_{d1}=0$. We proceed with the first row of $A$. By inserting $\gamma=2$ in \eqref{eq:proofStrongerStab1_1} we obtain
 \begin{equation}\label{eq:proofStrongerStab3}
 0=h_{i1}(2)=A_{i2}A_{12}
 \end{equation}
 for all $i>1$. We already showed that 
 $$A=
 \begin{bmatrix}
 A_{11}&A_{12}&\dots&A_{1d}\\
 0&A_{22}&\dots&A_{2d}\\
 \vdots&\vdots&\ddots&\vdots\\
 0&A_{d2}&\dots&A_{dd}\\
 \end{bmatrix}
 $$
 is an upper block-triangular matrix, so the lower right block is invertible. Therefore, there exists $i'>1$ such that $A_{i'2}\not=0$. We use \eqref{eq:proofStrongerStab3} and get $A_{12}=0$. 
 \par 
 Assume inductively that $A_{12}=\dots =A_{1,n-1}=0$ for $3\leq n\leq d$. We show that $A_{1n}=0$. For this we insert 
 $\gamma=n$ in \eqref{eq:proofStrongerStab1_1}, use the induction hypothesis, and obtain
 \begin{equation}\label{eq:proofStrongerStab4}
 0=h_{i1}(n)=A_{in}A_{1n}+\sum_{\alpha=2}^{n-1}3A_{i\alpha}A_{1n}
 \end{equation}
 for all $i>1$. For the sake of contradiction, assume that $A_{1n}\not=0$. Then, we can multiply \eqref{eq:proofStrongerStab4} by the inverse of $3A_{1n}$ and obtain 
 $$\begin{bmatrix}A_{22}\\\vdots \\A_{d2}\end{bmatrix}
 +
 \dots
 +
 \begin{bmatrix}A_{2,n-1}\\\vdots \\A_{d,n-1}\end{bmatrix}
 +
 \frac13\begin{bmatrix}A_{2n}\\\vdots \\A_{dn}\end{bmatrix}
 =0,$$
contradicting that $A$ is invertible. Therefore, we conclude $A_{1n}=0$, which completes our induction. Hence we know $A_{21}=\dots=A_{d1}=0$. With $A_{1+}=1$ we obtain $A_{11}=1$.
\end{proof}

\begin{proposition}\label{prop:genericG_Mfullrank}
 The matrix $M$ according to \Cref{def:MB} has full rank in expectation. 
\end{proposition}
\begin{proof}
For every $G\in{\GL_d}*C$,
 the explicit formula \eqref{eq:learningTask} implies that $G$ is a tensor with polynomial entries in $A\in\GL_d$. Therefore, also $M$ and all its minors are polynomial in $A$. Clearly, one of the $(d-s)\times(d-s)$ minors is not the constant zero polynomial due to \Cref{lem:exFullRank}. The variety of a nonzero polynomial has Lebesgue measure zero \cite[Lemma 1]{okamoto1973distinctness}, so $M$ is invertible for almost every evaluation.
\end{proof}

\begin{proof}[Proof of \Cref{thm:mainResult}]
From \cite[Corollary 6.3]{bib:PSS2019} we know that for any $G\in {\GL_d}*C$ there exists a unique $A\in\GL_d$ such that $G=A*C$. 
\par
We show that 
\Cref{alg:linear_learning} computes from $G$ a sequence of transformations $Q^{(0)},\dots,Q^{(d)}\in\GL_d$ such that 
$Q:=Q^{(d)}\dots Q^{(0)}$
transforms $G$ to the core tensor $C$, that is 
\begin{equation}\label{eq:mainProofEq1}
Q*G=C,
\end{equation}
so we can use \cite[Theorem 6.2]{bib:PSS2019}, conclude $QA=\mathrm{I}_d$ and return $Q^{-1}=A$ as desired. 
\par
It remains to construct $Q^{(s)}$ for $0\leq s\leq d$ according to the algorithm and to show \eqref{eq:mainProofEq1}. 
We start with the initial $Q^{(0)}:=\mathrm{I}_d$ and $G^{(0)}:=G$.
We enter the loop of the algorithm, i.e., let $1\leq s \leq d-1$ and assume recursively that we have constructed 
$Q^{(0)},\dots ,Q^{(s-1)}$ and 
\begin{equation}\label{eq:mainProofEq2}
G^{(s-1)}\in\left(\mathrm{I}_{s-1}\oplus\GL_{d-s+1}\right)*C.
\end{equation}
Note that for $s=1$ the condition \eqref{eq:mainProofEq2} clearly holds. Due to \Cref{thm:linearSolSolvesAlgebraicSystem}, we 
 find $x^{(s)}\in R^{d-s}$ and $W^{(s)}\in\mathrm{I}_{s-1}\oplus\GL_{d-s+1}$, when using \Cref{alg:solve}, such that 
$$H^{(s)}:=\left(U^{(s,x^{(s)})}W^{(s)}\right)*G^{(s-1)}$$
fulfills the conditions \eqref{thm:LowerTransformations1} to \eqref{thm:LowerTransformations31} of \Cref{thm:LowerTransformations}. 
Therefore $y^{(s)}\in\R^{d-s}$ 
with 
$$y^{(s)}_i:=-\frac{H^{(s)}_{s,s+1,s}}{H^{(s)}_{sss}}$$ according to \Cref{alg:linear_learning} provides 
\begin{equation}\label{eq:mainProofEq3}
G^{(s)}:=(D^{(s,H^{(s)}_{sss})}L^{(s,y^{(s)})})*H^{(s)}\in\left(\mathrm{I}_{s}\oplus\GL_{d-s}\right)*C.
\end{equation}
Putting it all together, we get 
$$Q^{(s)}:=D^{(s,H^{(s)}_{sss})}L^{(s,y^{(s)})}U^{(s,x^{(s)})}W^{(s)}$$ and obtain \eqref{eq:mainProofEq3} from \eqref{eq:mainProofEq2} via elementary Gau{\ss} operations. We proceed recursively until we reach $s=d-1$ with 
$$G^{(d-1)}\in\left(\mathrm{I}_{d-1}\oplus\GL_{1}\right)*C.$$
A last scaling $Q^{(d)}:=D^{(d,G^{(d-1)}_{ddd})}$ yields \eqref{eq:mainProofEq1} as desired. 
Within the loop of the learning algorithm, the most computationally expensive step is solving the linear system. \Cref{cor:MxB_solvable} shows that this is generally possible, and it needs $\mathcal{O}(d^3)$ elementary operations. 
\end{proof}

