\begin{abstract}
 In 2006, Boyarchenko and Drinfeld conjectured that for a unipotent algebraic group over $\fqb$, every geometric point is contained in the neutral connected component of its centralizer if and only if its $\L$-packets of character sheaves are singletons. In 2013, Boyarchenko proved the ``only if" direction of this conjecture. In this paper, we complete the proof. Along the way, we explore the relationship between general algebraic groups satisfying this property and their Asai twisting operator.
\end{abstract}
\section*{Introduction}
The theory of character sheaves for unipotent groups was first conjectured by George Lusztig in \cite{lusztig2006}. This theory was later developed by Mitya Boyarchenko and Vladimir Drinfeld in \cite{foundations}, \cite{characters}, and \cite{chsheaves}. In 2006, Boyarchenko and Drinfeld proposed six initial conjectures in the development of this theory (\cite{motivatedintro}). Five of the six were proved in \cite{foundations} and \cite{chsheaves}. The goal of this paper is to complete the proof of the last remaining conjecture:

In \cite{chsheaves}, Boyarchenko proved the ``only if" direction. The following theorem completes the proof of the conjecture:

\begin{theorem}[{\cite[Theorem 1.15]{foundations}}]\label{edgg cat thm}
 Let $G$ be a unipotent algebraic group over $k$, and let $e\in \dgg$ be a minimal closed idempotent.
 \begin{itemize}
 \item[(a)]$\mathscr{M}_e^{perv}$ is a semisimple abelian category with finitely many simple objects. In particular, $\L$-packets of character sheaves on $G$ are finite.
 \item[(b)]There exists a (necessarily unique) integer $n_e$ such that $e[-n_e] \in \mathscr{M}_e^{perv}$. One has $0\le n_e \le \dim G$. The subcategory $\mathscr{M}_e := \mathscr{M}_e^{perv}[n_e]$ of the monoidal category $e\dgg$ is monoidal.
 \item[(c)]The perverse t-structure on $\dg$ induces a t-structure on $e\dgg$, and the canonical functor $D^b(\mathscr{M}_e^{perv}) \rightarrow e\dgg$ is an equivalence.
 \end{itemize}
\end{theorem}

\begin{prop}[{\cite[Proposition 4.4]{foundations}}]\label{ad pair prop}
 Let $G$ be a unipotent group over $k$ and $M \in \dg$, $M \ne 0$. Suppose that $\hl \in \mathscr{P}_{norm}(G)$ is maximal among all pairs $(A,\NN) \in \mathscr{P}_{norm}(G)$ that are compatible with $M$. If $\LL$ is invariant under the conjugation action of $G$, then the pair $(H,\LL)$ is admissible for $G$.
\end{prop}

\begin{lemma}[{\cite[Lemma 4.16]{characters}}]\label{easy twists}
 Let $G$ be an easy unipotent group over a field $k$ of characteristic $p>0$. Then, for every object $M \in \dgg$, its twist automorphism $\theta_M$ is trivial. 
\end{lemma}

\begin{theorem}[{\cite[Theorem 1.8(b)]{chsheaves}}]\label{basis}
 Let $G$ be a connected unipotent group. The functions
 $$\{t_M : G^F \to \qlb \;| \;M\in CS(G)^F\} $$
 form a basis for the space $C(G^F/ \sim)$ which is orthonormal with respect to the inner product 
 $$\langle f_1 \; | \;f_2\rangle = \sum_{g \in G^F}f_1(g) \overline{f_2(g)}.$$
\end{theorem}

\begin{theorem}\label{asai prop}
 Let $G$ be a connected algebraic group. The Asai twisting operator is trivial on $C(G^{F^m}/\sim)$ for all $m \in \Z_{>0}$ if and only if $G$ is easy.
\end{theorem}

From now on, let $G$ be a unipotent group over $\fqb$. The proof of \Cref{thm} relies on the structure of twists in the category $\dgg$ and their relationship to the Asai twisting operator. 
\begin{lemma}\label{triv twists}
 If the $\L$-packet of character sheaves corresponding to $e$ is a singleton, then the twists in the Hecke subcategory $e\dgg$ are trivial.
\end{lemma}

\begin{theorem}\label{thm}
    If $G$ has trivial $\L$-packets, then $G$ is easy.
\end{theorem}

ref_dict.Def: Lipschitz order on ultrafilters:
\begin{definition}[The Lipschitz order on ultrafilters]\label{Def: Lipschitz order on ultrafilters}
Let $U,W\subseteq \mathcal{P}(\kappa)$ be ultrafilters on $\kappa$. We say that $U$ is Lipschitz below $W$, and denote $U<_L W$, if one of the following equivalent conditions hold:
\begin{itemize}
	\item player I has a winning strategy in $G_{\kappa}(W,U)$.
	\item there exists a super-Lipschitz function $f\colon \mathcal{P}(\kappa)\to \mathcal{P}(\kappa)$ that reduces $U$ to $W$, in the sense that $f^{-1}[W] = U$.
\end{itemize}

\end{definition}

