theorem.content:
\label{thm:main}
	Let $T>0$ and $\lambda$ be a fixed positive constant. For $N>0$, let
	\begin{equation}\label{lambda}
		\lambda_N=\left\{
		\begin{aligned}
			\frac{\lambda}{\sqrt{\log N}} & , &d=2,\\
			\lambda N^{1 - \frac{d}{2}} & , &d\geq3.
		\end{aligned}
		\right.
	\end{equation}
	Define $u^N$ be the stationary solution to \eqref{eq:scaled-NS} with the initial value $u^N(0,\cdot):=\mu,$ for $\mu$
	a divergence-free and mean-free spatial white noise on $\mathbb{T}^d.$
	Then there exists a strictly positive constant $D$, depending only on the dimension $d$ and $\lambda$, such that $u^N$ converges in law in $C([0,T],\mathcal{S}'(\mathbb{T}^d,\mathbb{R}^d))$ to the unique stationary solution $u$ to
	\begin{align}\label{eq:limeq}
	\partial_t u = (1+D)\Delta u + \sqrt{2(1+D)}(-\Delta)^{\frac{1}{2}}\pmb{\Pi}\xi\,,\quad u(0,\cdot)=\mu\,.
	\end{align}
	In the case $d=2$, $D=\sqrt{\frac{\lambda^2}{8\pi}+1}-1.$
	{In the case $d\geq 3,$ the following asymptotic expansion of $D$ holds for any $m\geq1$: 
	$$D=\sum_{l=1}^m f_l\lambda^{2l} + R_m \,,$$
	with $f_l\in\mathbb{R}$ independent of $\lambda$ and $R_m\in\mathbb{R}$ given in \eqref{eq:expansion}. Moreover, there exists a positive constant $C$, depending only on $d$, such that 
	$$|f_l|\leq l!C^{l},\quad |R_m|\leq (m+1)!C^{m+1}\lambda^{2m+2}.$$}

ref_dict.lem5.9:
\begin{lem}\label{lem5.9}
	Let $p\in\Pi^{(n)}_{a,1}$ and $g\in\tilde\fG^2[p]$, where $a=2b\geq 1$ is even. There exist functions $W^i_g:\RR^{b+2}\to\RR$, $i=1,2$ and $W^3_g:\RR^{b+1}\to\RR$, such that
	\begin{align}
		&\lim_{N\to \infty}\langle{\tilde\sigma}_{-\bj',\bt'},\fT^N_p[g]{\tilde\sigma}_{\bj,\bt}\rangle_{L^2_{m_\kappa}}
		=\1_{A_{\bj;\bj'}(g)}\1_{t'_{\pi(a)}=t_2}
		\frac{|j_1|^2}{|\bj|^2}
		(\lambda\iota)^a2^{bd}\times\label{liminner}\\
		&\int\mu(dy_{1:b})\frac{I_g(y_{1:b};0)}{2\pi Q_g(y_{1:b};0)}\left[W^1_g\left(y_{1:b},\frac{j_1}{|j_1|},a_{j_1,t_1}\right)W^2_g\left(y_{1:b},\frac{j_1}{|j_1|},a_{j_1,t'_{\pi(a)^c}}\right)+\1_{t'_{\pi(a)^c}=t_1}W^3_g\left(y_{1:b},\frac{j_1}{|j_1|}\right)\right]\, ,\nonumber
	\end{align}
	where $A_{\bj;\bj'}(g)=\{j'_{\pi(a)^c}=j_1;\, j'_{\pi(a)}=j_2\}$, for $\pi(a)^c=\{1,2\}\backslash\{\pi(a)\}.$ $\mu$ is the uniform probability measure on $[-1,1]^{bd}$, and $I_g, Q_g$ are the functions defined in Lemma \ref{lem5.8}.
	 The terms in $W_g^1$ (resp. $W_g^2$) are the products of inner-products between vectors in $V$ and $V'$, 
	 where $V$ is the set of vectors which are linear combinations of $y_{1:b},\frac{j_1}{|j_1|}$ and $a_{j_1,t_1}$ (resp. $a_{j_1,t'_{\pi(a)^c}}$), and $V'$ is the set of vectors in $V$ divided by its Euclidean norm.
	 The terms in $W_g^3$ have the same form depending on $y_{1:b},\frac{j_1}{|j_1|}$.
	Moreover,
	the integral in \eqref{liminner} is independent of $j_1$.

	If $j_1,\, j'_1\in\ZZ_0^d,\, t_1,\, t'_1\in\{1,\cdots,d-1\}$ and $g\in\fG^1[p]$, the analog of \eqref{liminner} holds upon setting $\bj=j_1,\,\bj'=j'_1$ and $\bt=t_1,\, \bt'=t'_1$, and removing the dependence of $t_2$ and $\pi(a)$. 
	Furthormore, for $g\in\fG^1[p]$ and the associated elements $\hat g$ and $\tilde g$ in $\tilde\fG^2[p]$, we have $W_g^i=W^i_{\hat g}=W^i_{\tilde g}$ for $i=1,2,3$.
\end{lem}

