			\lim_{N\to \infty}\sum_{p\in \Pi^{(n)}_{a,1}}\sum_{g\in\tilde\fG^2[p]}\langle{\tilde\sigma}_{-\bj',\bt'},\fT^N_p[g]{\tilde\sigma}_{\bj,\bt}\rangle_{L^2_{m_\kappa}}&=\frac{|j_1|^2}{|\bj|^2}c(a,\lambda)\left(\1_{\bj'=\bj}\1_{\bt'=\bt}+\1_{\bj'=\bj^T}\1_{\bt'=\bt^T}\right),\label{eq:liminner2}
		\end{align}
