\begin{align}\label{PN5}
P^N_5(k_{1:n}):=\lambda_N^2\int_{|x|\leq1} \ud x\frac{2\sin^2\theta_1\cos^2\theta_1}{\Gamma_1(x)(1+\Gamma_1(x))(1+G(L^N(N^2\Gamma_1(x))))}.
\end{align}
Arguing as Step3 in \cite[Proposition A.1]{CGT24}, since $|k_1|\leq \frac N2$, and $\Gamma_1\gtrsim|x|^2$, $\sup_{k_{1:n}\in\ZZ_0^d}|P_4^N(k_{1:n})-P^N_{5}(k_{1:n})|$ is bounded by a constant times
	$$\lambda_N^2\int_{\frac12\leq|x|\leq1}\frac{1}{|x|^2}\ud x\lesssim\lambda_N^2.$$
At last, we focus on $P^N_5(k_{1:n})$. Set $\alpha_N:=|\frac{k_{1:n}}{N}|^2$. Then we have 
	\begin{align*}
		P^N_5(k_{1:n})=&\frac{\lambda^2}{\log N}\int_{|x|\leq1} \frac{2\sin^2\theta_1\cos^2\theta_1\ud x}{(2\pi)^2(2|x|^2+\alpha_N)((2\pi)^2(2|x|^2+\alpha_N)+1)(1+G(L^N(N^2(2\pi)^2(2|x|^2+\alpha_N))))}\\
		=&\frac{\lambda^2}{8\pi^2\log N}\int_0^{2\pi}\frac{\sin^22\theta}{2}\ud\theta\int_{0}^1 \frac{\ud r}{(2r+\alpha_N)((2\pi)^2(2r+\alpha_N)+1)(1+G(L^N(N^2(2\pi)^2(2r+\alpha_N))))}\\
		=&\frac{\lambda^2}{16\pi\log N}\int_{0}^1 \frac{\ud r}{(2r+\alpha_N)((2\pi)^2(2r+\alpha_N)+1)(1+G(L^N(N^2(2\pi)^2(2r+\alpha_N))))}\,.
	\end{align*}
	Let $t:=L^N(N^2(2\pi)^2(2r+\alpha_N))$. Then $\ud t=\frac{-2\lambda^2}{\log N(2r+\alpha_N)(1+(2\pi)^2(2r+\alpha_N))}\ud r$. The above integral equals
	\begin{align*}
		\frac{1}{32\pi}\int_{L^N(N^2(2\pi)^2(2+\alpha_N))}^{L^N(N^2(2\pi)^2\alpha_N)} \frac{\ud t}{1+G(t)}.
	\end{align*}
 It is immediate to verify that, with an error of order $\lambda_N^2$, we can replace the lower integration index with 0, and obtain
	\begin{align*}
	&\frac{1}{32\pi}\int_{0}^{L^N((2\pi)^2|k_{1:n}|^2)} \frac{\ud t}{1+G(t)}.
\end{align*}
Thus by the definition of $G$ in \eqref{eq:G}, the proof is complete.

\end{proof}

