\section{Proof of Theorem \ref{thm:F-D} when $d\geq3$}\label{appendixB}
{In this appendix, we prove Theorem \ref{thm:F-D} given Proposition \ref{prop:limite}. By Proposition \ref{prop:limite}, arguing as in the proof of \cite[Lemma 2.16, Lemma 2.17 and Proposition 2.13]{CGT24},
for any $a_1,a_2\in2\NN\,, m_1,m_2\geq2$, we have
\begin{align*}
	&\lim_{N\to\infty} \sum_{{p^1\in \Pi^{(n)}_{a_1,1},\, p^2\in \Pi^{(n)}_{a_2,1}}}\langle \mathcal T^N_{p^1} \sigma_{\bj,\bt},\overline {\mathcal T^N_{p^2} \sigma_{\bj,\bt}}\rangle= c(a_1,\lambda) c(a_2,\lambda)
	\|\sigma_{\bj,\bt}\|^2\,,\\
	&\lim_{N\to\infty}\sum_{{p^1\in \Pi^{(n)}_{a_1,m_1},\, p^2\in \Pi^{(n)}_{a_2,m_2}}} \langle(-\fL_0)^{-1}\fT_{p^1}^N\sigma_{\bj,\bt},\overline{\fT_{p^2}^N\sigma_{\bj,\bt}}\rangle= 0\,,
\end{align*}
where $c(a,\lambda)=1$ if $a=0$, and for $a\geq2$, $c(a,\lambda)$ is the one in Proposition \ref{prop:limite}.} 
Then similar as the proof of \cite[Proposition 2.12]{CGT24} by replacing $\{e_k\}_k$ with $\{\sigma_{k,\alpha}\}_{k,\alpha}$, we have the following Proposition.
\begin{prop}\label{prop:Nlim}
	For $d\geq3$ and $n$ fixed, there exists a unique constant $D^n>0$ such that, for $i=2,3$, 
	\begin{align*}
		\lim_{N\to\infty}\|(-\fL_0)^{-\frac12}(\fA_-^Nv_i^{N,n}-D^{n-i+2}\fL_0 f_{i-1})\|=0\,,\quad
		\lim_{N\to\infty}\|v^{N,n}\|=0\,.
	\end{align*}
\end{prop}
Now We prove Theorem \ref{thm:F-D} using Proposition \ref{prop:Nlim}. \eqref{5.2} follows from the proof of \cite[Theorem 2.7]{CGT24} and \eqref{eq:sector}. We only need to prove \eqref{5.3}.
Since the sequence $\{D^n\}_n$ is Cauchy by the proof of \cite[Theorem 2.11]{CGT24} in $d\geq3$, we only need to prove that the limit of $\{D^n\}_n$ is positive.

Fix $k\in\ZZ_0^d$.
Let $v^{N,n}[-k]$ be the solution to \eqref{eq:geneq} with $f_1=\sigma_{k,1}$ and $i=2.$
Then we have
\begin{align}
	D^n2\pi|k|=&\|(-\fL_0)^{-\frac12}(-D^n\fL_0)f_1\|\nonumber\\
	\leq&
\|(-\fL_0)^{-\frac12}\fA_-^Nv_2^{N,n}[-k]\|-\|(-\fL_0)^{-\frac12}(\fA_-^Nv_2^{N,n}[-k]-D^{n}\fL_0 f_1)\|.\label{C1}
\end{align}

