\begin{theorem}[The Fluctuation-Dissipation Theorem]\label{thm:F-D}
	Let the divergence-free functions $\varphi,\,\psi\in\fS(\TT^d,\RR^d)$ be fixed, and define 
	\begin{align}\label{eq:fi}
		f_1:=\varphi,\quad f_2:=[\psi\otimes\varphi]_{sym}=\frac12(\varphi\otimes\psi+\psi\otimes\varphi)\,.
	\end{align}
	Then for $i=2,3$, there exists a family $\mathcal V^i=\{v^{N,n}\in\oplus_{j=i}^n\FK_j, n\in\NN\}$ and a positive constant $D$ (which is independent of $i$) such that
	\begin{align}
		&\lim_{n\to\infty}\limsup_{N\to\infty}\|v^{N,n}\|=0,\label{5.1}\\
		&\lim_{n\to\infty}\limsup_{N\to\infty}\|(-\fL_0)^{-\frac12}(-\fL^Nv^{N,n}-\fA^N_+f_{i-1}+\fA_-^Nv_i^{N,n})\|=0,\label{5.2}\\
		&\lim_{n\to\infty}\limsup_{N\to\infty}\|(-\fL_0)^{-\frac12}(\fA_-^Nv_i^{N,n}-D\fL_0 f_{i-1})\|=0\,.\label{5.3}
	\end{align}
\end{theorem}

