ref_dict.thm.Geneator_in_Fourier:
\begin{theorem}\label{thm.Geneator_in_Fourier}
For $N\in\NN$, let $\fL^N = \fL_0+\fA^N$. Then $\fA^N = \fA^N_+ + \fA^N_-$ with $\fA^N_-=-(\fA^N_+)^{*}$\,. $\fL_0(\FK_0) = \fA_+^N(\FK_0) = \fA_-^N(\FK_1) = 0$.
For $n\ge1$, the action of the operators $\fL_0,\,\fA_+^N$ and $\fA_-^N$ on $\varphi_n\in \FK_n$ is given by
\begin{align}
	\fF(\fL_0\varphi_n)(l_{1:n},k_{1:n}) =& -(2\pi)^{2}\sum_{i=1}^n|k_i|^{2}\hat{\varphi}_n(l_{1:n},k_{1:n}),\label{3.9}\\
	\fF(\fA_+^{N}\varphi_n)(l_{1:n+1},k_{1:n+1}) =&\frac{\lambda_N 2\pi\iota}{n+1}\sum_{1\leq i,j\leq n+1,i\neq j}\fR_{k_{i},k_j}^N\left(\hat\Lp(k_i)(k_i+k_{j})\right)(l_i)\times\nonumber\\
	&\times\left(\hat\Lp(k_{j}) \hat{\varphi}_{n}((\cdot,k_i+k_{j}),(l_{1:n+1\backslash i,j},k_{1:n+1\backslash i,j}))\right)(l_j),\label{3.10}\\
	\fF(\fA_-^{N}\varphi_n)(l_{1:n-1},k_{1:n-1}) =&\lambda_N 2\pi\iota n\sum_{j=1}^{n-1}\sum_{p+q=k_j}\fR_{p,q}^N\sum_{i,t=1}^dk_j^i{\hat{\Lp}_{l_j,t}(k_j)}\hat{\varphi}_{n}((t,p),(i,q),(l_{1:n-1\backslash j},k_{1:n-1\backslash j})),\label{3.11}
\end{align}
where $k_j^i$ is the $i$-th component of $k_j$.
Moreover, for $i=1,\dots,d,$ the momentum operator $M_i$, defined for $f\in\FK_n$ as $\fF(M_if)(l_{1:n},k_{1:n})=(\sum_{j=1}^nk_j^i)\hat{f}(l_{1:n},k_{1:n}),$ commutes with $\fL_0,\fA^N_{+},\fA^N_{-}$, i.e.
\begin{align}\label{eq:commute}
\fL^NM_i-M_i\fL^N=0 \,.
\end{align}
\end{theorem}

ref_dict.rmk:
\begin{remark}\label{rmk}
	In the case $d\geq3$, by the same arguments as in Proposition \ref{prop:A} in the two-dimensional case, we can derive a similar "Replacement Lemma": for any $c_1>0,\, n\in\NN$ and the symmetric divergence-free test functions $\psi_1,\psi_2$ in $L^2(\TT^{dn},\RR^{dn})$,
	\begin{align}\label{4.1}
		\left|\langle(-\fL_0+c_1(-\fL_0))^{-1}\fA^N_+\psi_1,\fA^N_+\psi_2\rangle-\frac{c\lambda^2}{1+c_1}\langle(-\fL_0)\psi_1,\psi_2\rangle\right|
		\lesssim&\|\fN(-\fL_0)^{\frac12}\psi_1\|\|\fN(-\fL_0)^{\frac12}\psi_2\|,
	\end{align}
	where $c=\lambda^{-2}\lim_{N\to\infty}\|(-\fL_0)^{-\frac12}\fA_+^N(-\fL_0)^{-\frac12}\sigma_{k,1}\|^2,$ $\sigma_{k,1}$ is given by \eqref{vector-fields},
	$\fL^N = \fL_0 +\fA_+^N +\fA_-^N$ is the generator of $u^N$, and $\fN$ denotes the number operator (see Theorem \ref{thm.Geneator_in_Fourier} and Definition \ref{def:num}).
	Let $D_{\mathrm{rep}}$ be the unique positive solution to $x = \frac{c\lambda^2}{1+x}$. Although there is no vanishing term on the right hand side of \eqref{4.1}, 
	one might be tempted to regard the symmetric operator $D_{\mathrm{rep}}(-\fL_0)$ as a "Replacement operator" for approximating the fixed-point 
	$\fH^N = \fA^N_-(-\fL_0+\fH^N)^{-1}\fA_+^N$, and conjecture that $D=D_{\mathrm{rep}}$ as in the two dimensional case. The following corollary shows that such conjecture is in fact incorrect.
\end{remark}

