\begin{align}
 &\|T^{N,+}T^{N,+}\sigma_{k,1}\|^2\label{5.4}\\
 =&3!\sum_{k_{1:3},\alpha_{1:3}}\left|\langle T^{N,+}T^{N,+}\sigma_{k,1},(\sigma_{k_1,\alpha_1}\otimes \sigma_{k_2,\alpha_2}\otimes \sigma_{k_3,\alpha_3})_{\text{sym}}\rangle_{L^2_3}\right|^2\nonumber\\
 =& \frac{2}{3(2\pi)^4|k|^2} \sum_{k_{1:3},\alpha_{1:3}}\frac{1}{|k_{1:3}|^2}\left|\langle (-\fL_0)^{-1}\fA_+^N\sigma_{k,1},\fA_-^N(\sigma_{k_1,\alpha_1}\otimes \sigma_{k_2,\alpha_2}\otimes \sigma_{k_3,\alpha_3})_{\text{sym}}\rangle_{L^2_2}\right|^2\nonumber\,,
\end{align}
where 
\begin{align}\label{sym}
 (\sigma_{k_1,\alpha_1}\otimes \sigma_{k_2,\alpha_2}\otimes \sigma_{k_3,\alpha_3})_{\text{sym}} = \frac{1}{3!}\sum_{\sigma\in P_3}\sigma_{k_{\sigma(1)},\alpha_{\sigma(1)}}\otimes \sigma_{k_{\sigma(2)},\alpha_{\sigma(2)}}\otimes \sigma_{k_{\sigma(3)},\alpha_{\sigma(3)}},
\end{align}
and $P_3$ denotes the set of permutations of $(1,2,3)$.
By \eqref{A_-}, the above equation equals
\begin{align*}
 &\frac{6}{(2\pi)^4|k|^2} \sum_{k_{1:3},\alpha_{1:3}}\frac{1}{|k_{1:3}|^2}\left|\sum_{q=1}^2\langle (-\fL_0)^{-1}\fA_+^N\sigma_{k,1},\fA_-^N[q](\sigma_{k_1,\alpha_1}\otimes \sigma_{k_2,\alpha_2}\otimes \sigma_{k_3,\alpha_3})_{\text{sym}}\rangle_{L^2_2}\right|^2\,.
\end{align*}
Recall the definition of $\fA_-^N[q]$ in \eqref{Aq}. Then 
\begin{align}
 &\sum_{q=1}^2\langle (-\fL_0)^{-1}\fA_+^N\sigma_{k,1},\fA_-^N[q](\sigma_{k_1,\alpha_1}\otimes \sigma_{k_2,\alpha_2}\otimes \sigma_{k_3,\alpha_3})\rangle_{L^2_2}\nonumber\\
 =&\lambda_N^2\1_{\sum_{i=1}^3k_i=k}\fR^N_{k_1,k_2}\fR^N_{k_1+k_2,k_3}\frac{k_1\cdot a_{k_2,\alpha_2}}{|k_1+k_2|^2+|k_3|^2}\left((k\cdot \hat\Lp(k_1+k_2)a_{k_1,\alpha_1}) (a_{k_3,\alpha_3}\cdot a_{k,1})\right.\nonumber\\
 &\left.+(a_{k,1}\cdot \hat\Lp(k_1+k_2)a_{k_1,\alpha_1}) (a_{k_3,\alpha_3}\cdot k)\right)\nonumber\\
 =:&\lambda_N^2\1_{\sum_{i=1}^3k_i=k}\fR^N_{k_1,k_2}\fR^N_{k_1+k_2,k_3}C_{k_{1:3},\alpha_{1:3}}\,.\label{C}
\end{align}
Substituting the above equation into \eqref{5.4}. By \eqref{sym} and performing the change of variable $m_{1:3}=k_{\sigma'(1:3)}$ and $l_{1:3}=\alpha_{\sigma'(1:3)}$, we have
\begin{align*}
 &\|T^{N,+}T^{N,+}\sigma_{k,1}\|^2\\
 =&\frac{\lambda_N^4}{6(2\pi)^4|k|^2}\sum_{\sigma',\sigma\in P_3} \sum_{k_{1:3},\alpha_{1:3}}\frac{\1_{\sum_{i=1}^3k_i=k}}{|k_{1:3}|^2}\fR^N_{k_{\sigma'(1)},k_{\sigma'(2)}}\fR^N_{k_{\sigma'(1)}+k_{\sigma'(2)},k_{\sigma'(3)}}
 \fR^N_{k_{\sigma(1)},k_{\sigma(2)}}\fR^N_{k_{\sigma(1)}+k_{\sigma(2)},k_{\sigma(3)}}\times\\
 &C_{k_{\sigma'(1:3)},\alpha_{\sigma'(1:3)}}C_{k_{\sigma(1:3)},\alpha_{\sigma(1:3)}}\\
 =&\frac{\lambda_N^4}{(2\pi)^4|k|^2}\sum_{\sigma\in P_3} \sum_{m_{1:3},l_{1:3}}\frac{\1_{\sum_{i=1}^3m_i=k}}{|m_{1:3}|^2}\fR^N_{m_1,m_2}\fR^N_{m_1+m_2,m_3}
 \fR^N_{m_{\sigma(1)},m_{\sigma(2)}}\fR^N_{m_{\sigma(1)}+m_{\sigma(2)},m_{\sigma(3)}}\times\\
 &C_{m_{1:3},l_{1:3}}C_{m_{\sigma(1:3)},l_{\sigma(1:3)}}\,.
\end{align*}
Recall the definition of $\lambda_N$ in \eqref{lambda}. 
By the definition of $C_{m_{1:3},l_{1:3}}$ in \eqref{C}, we have $C_{m_{1:3}/N,l_{1:3}}=NC_{m_{1:3},l_{1:3}}$. Then
by taking $v_i=N^{-1}m_i$ for $i=1,2,3$, as $N\to\infty$, we have
\begin{align}
 &\lim_{N\to \infty}\|T^{N,+}T^{N,+}\sigma_{k,1}\|^2\nonumber\\
 =&\lim_{N\to \infty}\frac{\lambda^4}{(2\pi)^4|k|^2}\frac{1}{N^6}\sum_{\sigma\in P_3}\sum_{l_{1:3}=1}^3\sum_{\substack{v_1+v_2+v_3=k/N\\ v_{1:3}\in N^{-1}\ZZ_0^d}} \frac{\fR^1_{v_1,v_2}\fR^1_{v_1+v_2,v_3} \fR^1_{v_{\sigma(1)},v_{\sigma(2)}}}{|v_{1:3}|^2}C_{v_{1:3},l_{1:3}}C_{v_{\sigma(1:3)},l_{\sigma(1:3)}}\nonumber\\
 =&\lim_{N\to \infty}\frac{\lambda^4}{(2\pi)^4|k|^2}\sum_{\sigma\in P_3} \sum_{l_{1:3}=1}^3\int_{|x_1|,|x_2|,|x_1+x_2|\leq1}\frac{C_{x_{1:3},l_{1:3}} C_{x_{\sigma(1:3)},l_{\sigma(1:3)}}}{|x_1|^2+|x_2|^2+|x_1+x_2|^2}\ud x_1\ud x_2\,,\label{5.8}
\end{align}
where $x_3=\frac{k}{N}-x_1-x_2$.
By direct evaluation of the integral via \texttt{Mathematica} shows that the limit is approximately $\frac{8.588}{2(2\pi)^4} \lambda^4$. This is strictly less than $\lambda^4 \lim_{N\to \infty}\|T^{N,+} \sigma_{k,1}\|^4$, whose value by \eqref{5.6} is $\left(\frac{7}{30\pi}\right)^2 \lambda^4$. 
Therefore, $D \neq D_{\mathrm{rep}}$.
\end{proof}

\begin{prop}\label{prop:A}
 For $n,N\in\NN$, $\lambda>0$, and $k_{1:n}\in\ZZ_0^d$, let $P^N$ be 
 \begin{align}
 P^N(k_{1:n}):={\lambda_N^2}\sum_{l+m=k_1}\frac{\fR_{l,m}^N\left[\sin^2\theta_1-\sin^2\theta_2\left(\sin^2\theta_1+\frac{|l|}{|m|}\cos\theta_1\cos\theta_2\right)\right]}{(2\pi)^2(|l|^2+|m|^2+|k_{2:n}|^2)(1+G(L^N((2\pi)^2(|l|^2+|m|^2+|k_{2:n}|^2))))},\label{A1}
 \end{align}
where $G$ is defined in \eqref{eq:G}. $\theta_1$ and $\theta_2$ are the angles between $k_1$ and $m,\, l$ respectively. Then there exists a constant $C$ independent of $N$ such that
\begin{align}
 \sup_{k_{1:n}\in\ZZ_0^d}|P^N(k_{1:n})-G(L^N((2\pi)^2|k_{1:n}|^2))|\leq C\lambda_N^2\,.
\end{align}
\end{prop}
\begin{proof}
 Arguing as (A.3) of \cite{CGT24}, if $|k_1|>\frac N2$, we assume without loss of generality that $|l|\geq\frac N4$, and we have
 \begin{align*}
 |P^N(k_{1:n})|\lesssim&\lambda_N^2\sum_{\frac N4\leq|l|\leq N}\left(\frac{1}{|l|^2}+\frac{1}{|l||k_1-l|}\right)
 \lesssim\lambda_N^2\int_{\frac14\leq|x|\leq 1}\left(\frac{1}{|x|^2}+\frac{1}{|x||\frac{k_1}{N}-x|}\right)\lesssim \lambda_N^2.
 \end{align*}
 Thus we only consider the case when $|k_1|\leq \frac N2$. For simplicity, for $x\in\RR^2$ and $|x|\leq1$, define $$\beta_N:=\left|\frac{k_{2:n}}{N}\right|^2,\,\quad\Gamma(x):=(2\pi)^2\left(|x|^2+\left|\frac{k_1}{N}-x\right|^2+\beta_N\right),\quad\Gamma_1(x):=(2\pi)^2\left(2|x|^2+\left|\frac{k_{1:n}}{N}\right|^2\right).$$
 In the following steps, we simplify $P^N$ by resplcing it with several integrals, i.e. to construct $P^N_i$ and show that 
 \begin{align}\label{A3}
 \sup_{k_{1:n}\in\ZZ_0^d}|P^N_i(k_{1:n})-P^N_{i+1}(k_{1:n})|\lesssim\lambda_N^2
 \end{align}
 for $i=0,\cdots,4$ and $P^N_0:=P^N.$

