\label{thm:main}
	Let $T>0$ and $\lambda$ be a fixed positive constant. For $N>0$, let
	\begin{equation}\label{lambda}
		\lambda_N=\left\{
		\begin{aligned}
			\frac{\lambda}{\sqrt{\log N}} & , &d=2,\\
			\lambda N^{1 - \frac{d}{2}} & , &d\geq3.
		\end{aligned}
		\right.
	\end{equation}
	Define $u^N$ be the stationary solution to
	\begin{equation}\label{eq:scaled-NS}
    \partial_t u^N = \Delta u^N -\lambda_N \rho^N * \Lp \operatorname{div}((\rho^N*u^N)\otimes (\rho^N*u^N)) + \sqrt{2}(-\Delta)^{\frac{1}{2}}\Lp\xi\,,\quad \nabla \cdot u^N = 0\,,
\end{equation}
	with the initial value $u^N(0,\cdot):=\mu,$ for $\mu$
	a divergence-free and mean-free spatial white noise on $\mathbb{T}^d.$
	Then there exists a strictly positive constant $D$, depending only on the dimension $d$ and $\lambda$, such that $u^N$ converges in law in $C([0,T],\mathcal{S}'(\mathbb{T}^d,\mathbb{R}^d))$ to the unique stationary solution $u$ to
	\begin{align}\label{eq:limeq}
	\partial_t u = (1+D)\Delta u + \sqrt{2(1+D)}(-\Delta)^{\frac{1}{2}}\pmb{\Pi}\xi\,,\quad u(0,\cdot)=\mu\,.
	\end{align}
	In the case $d=2$, $D=\sqrt{\frac{\lambda^2}{8\pi}+1}-1.$
	{In the case $d\geq 3,$ the following asymptotic expansion of $D$ holds for any $m\geq1$: 
	$$D=\sum_{l=1}^m f_l\lambda^{2l} + R_m \,$$
	with $f_l\in\mathbb{R}$ independent of $\lambda$ and $R_m\in\mathbb{R}$ given by
	\begin{align}
	f_l =& (-1)^{l-1}\lim_{n\to\infty}\lim_{N\to\infty} \|(T^{N,*}_{2,n})^{l-1}T^{N,+,*}\sigma_{k,1}\|^2\,,\nonumber\\
	R_m =&(-1)^{m}\lim_{n\to\infty}\lim_{N\to\infty}\langle(-\fL_0)^{\frac12}(T^{N}_{2,n})^{m}T^{N,+}\sigma_{k,1},(-\fL^N_{2,n})^{-1}(-\fL_0)^{\frac12}(T^{N}_{2,n})^{m}T^{N,+}\sigma_{k,1}\rangle\,,\label{eq:expansion}
\end{align}
	Moreover, there exists a positive constant $C$, depending only on $d$, such that 
	$$|f_l|\leq l!C^{l},\quad |R_m|\leq (m+1)!C^{m+1}\lambda^{2m+2}.$$}

