\begin{theorem}\label{theorem:main_alt}
	Let $(\rho,V)$ be an irreducible spin representation of $\tilde A_n$ indexed by a partition $\lambda$.
	Let $g\in \tilde A_n$ be an element with cycle type $\mu=(\mu_1,\mu_2,\dotsc,\mu_k)$ and $k=\lcm(\mu)$.
	Then the minimal polynomial $p_V(g)$ of $\rho(g)$ has $k$ distinct roots except in the following cases:

	\noindent For $n\leq 10$ and $((\rho,V),g)$ is one of the pairs listed in Tables~\ref{table:exceptional_cases_1_8_alt} and \ref{table:exceptional_cases_9_10_alt}.

	For $n>10$, the following four exceptions occur:
\begin{itemize}
		\item $V=V_{(n)}$ and $\mu$ contains $3$ with the remaining parts are not divisible by $3$ and $5$ is not the unique part which is divisible by $5$. In this case, the minimal polynomial is given by $\frac{x^{k}\pm 1}{x^{k/3}\pm 1}$.
		\item $V=V_{(n)}$ and $\mu$ contains $5$ with the remaining parts are not divisible by $5$ and $3$ is not the unique part which is divisible by $3$. In this case, the minimal polynomial is given by $\frac{x^{k}\pm 1}{x^{k/5}\pm 1}$.
		\item $V=V_{(n)}$ and $\mu$ contains $3$ and $5$ and all other parts of $\mu$ are not divisible by $3$ or $5$. In this case, the minimal polynomial is given by $\frac{(x^{k}\pm1)(x^{k/15}\pm 1)}{(x^{k/3}\pm1)(x^{k/5}\pm 1)}$.
		\item $V=V_{(n-1,1)}$ and $\mu$ contains $3$ and $5$, and all other parts of $\mu$ are not divisible by $3$ or $5$. In this case, the minimal polynomial is given by $\frac{(x^{k}\pm1)}{(x^{k/15}\pm1)}$.
	\end{itemize}
\end{theorem}

