\section{Proof of Theorem \ref{tw:glow}}
We prove Theorem \ref{tw:glow} by induction on $\wym=\lceil 2\cdot \log_2 \kappa \rceil$ (we recall that $\kappa$ is such that $\lv X_{ij} \rv_{2p} \leq \kappa \lv X_{ij} \rv_p$ for any $p \geq 1$). If $\wym=1$ then the random variables $(X_{ij})_{i,j\leq n}$ satisfies $\lv X_{ij} \rv_{2p} \leq \sqrt{2} \lv X_{ij} \rv_p$ for any $p\geq 1$. This easily implies that $\lv X_{ij} \rv_{p} \leq C \sqrt{p} \lv X_{ij} \rv_1$. Therefore, the base case is that of $C$-subgaussian random variables (where $C\rown 1$). This is the content of the next theorem.
\begin{theorem}\label{tw:bazaindukcji}
 Assume that $X_{ij}$ are independent, symmetric, $C$-subgaussian random variables, such that $\Ex |X_{ij}|=1$. Then for any symmetric matrix $(a_{ij})_{i,j\leq n}$ such that $a_{ii}=0$ we have
 \begin{align*}
 \Ex \lv \AX \rv_{op}\lesssim \Log^{3/2}(d_A)\left(\mia+ \RX\right).
\end{align*}
\end{theorem}
\begin{proof}
The assertion follows by invoking Proposition \ref{prop:oszapodgaus} with $T=\{(1)_{i,j \leq n}\}$ ($T$ contains only one matrix with ones everywhere). It is enough to observe that, by Lemma \ref{lem:oszmaxpodex}
\[\Ex \max_{ij} |a_{ij} X_{ij}| \lesssim \RX . \]
\end{proof}
The main idea of the proof of Theorem \ref{tw:glow} is that if $\wym \in \eN$, and the random variables $(X_{ij})_{i,j \leq n}$ satisfy \eqref{eq:*} with $\kappa=2^{\wym/2}$, then each $X_{ij}$ is a product of at most $\wym$ subgaussian random variables. We will condition on the first $\wym-1$ of them and apply the induction assumption. Proposition \ref{prop:oszapodgaus} will handle the induction step. The key point is the analysis of the function defined by
\begin{equation}\label{eq:deffunkN}
 N^X_{ij}(t)=-\ln \Pro(|X_{ij}|\geq t).
\end{equation}
It turns out that if $X_{ij}$ satisfies \eqref{eq:*}, then $N^X_{ij}$ has certain asymptotics.
\begin{lemma}\cite[Lemma 3.1]{ja}\label{lem:wlasnosciN}
 Assume the random variable $X$ belongs to the $SRV(\kappa)$ class and $\Ex |X|=1$. Let $N(t)=-\ln \Pro(|X|\geq t)$. Then there exists $C(\kappa)$ such that for any $x,t\geq 1$ we have $N(C(\kappa)tx)\geq t^{\frac{1}{\Log_2 \kappa}}N(x)$. In particular, $N(C(\kappa)t)\geq t^{\frac{1}{\Log_2 \kappa}}$ for $t\geq 1$.
\end{lemma}
\begin{proof}
 The first part of the Lemma was proven in \cite{ja} (Lemma 3.1 therein) for random variables that satisfy \eqref{eq:*} with $\kappa=2^\wym$ for some $\wym\in \eN$. However, this specific value of the parameter is irrelevant. For this reason, we skip the proof. The second part of the lemma follows from the first one and Markov's inequality, since
\[N(e)\geq -\ln \frac{\Ex |X|}{e}=1.\]
\end{proof}

\begin{lemma}\label{lem:twierdzeniedlaproduktow}
 Let $r \in \mathbb{N}$. Assume that $(X^{(k)}_{ij})_{k \leq \wym,\; i,j \leq n}$ 
are independent $C(\wym)$ subgaussian random variables such that 
$\Ex |X^{(k)}_{ij}| \sim^{\wym} 1$ for each $k \leq \wym$ and $i,j \leq n$.
Then, for any symmetric matrix $(a_{ij})_{i,j \leq n}$ with $a_{ii} \equiv 0$,
we have
