\Ex \sup_{v,w \in B_2} \sum_{ij} a_{ij} \left( \prod_{k=1}^\wym \Xk_{ij}\right) v_i w_j \lesssim^\wym \left(\Log(d_A)\right)^{C(\wym)}\left(\mia+R_{\Xld}(A)\right),
 \end{equation}
 where $X^{(\leq l)}_{ij}:=\prod_{k=1}^l \Xk_{ij}$ for $l=1,\ldots,\wym$, and we recall
 \[R_{X^{(\leq l)}}(A)=R_{X^{(\leq l)}}(A,\Log \, n)=\sup_{v,w\in B_2} \lv \sum_{ij} a_{ij} \left( \prod_{k=1}^l \Xk_{ij}\right) v_i w_j \rv_{\Log \, n}. \]
\end{lemma}
\begin{proof}
 Theorem \ref{tw:bazaindukcji} solves the case when $\wym=1$. Assume that the assertion holds for $\wym$, i.e., \eqref{eq:zalinduk} is true. Let $T\subset \eR^{n^2}$ be the set for which \eqref{eq:wlasnoscT} holds for
\[(\Xld_{ij})_{i,j \leq n}=(\prod_{k=1}^\wym \Xk_{ij})_{i,j\leq n}\] 
in place of $X_{ij}$ (the existence of this set is guaranteed by Theorem \ref{tw:formulamomenty}). In our notation, this means that, for any matrix $M=(m_{ij})_{i,j \leq n}$, we have
\[R_{\Xld}(M) \rown^\wym \sup_{v,w\in B_2} \sup_{t\in T}\sum_{ij} m_{ij} t_{ij} v_i w_j. \]
In particular, for the random matrix $M=A \odot \Xd:=(a_{ij}\Xd_{ij})_{i,j \leq n}$, we have
\begin{align}
 \Ex R_{\Xld}(A \odot \Xd) \rown^\wym \Ex\sup_{v,w\in B_2} \sup_{t\in T}\sum_{ij} a_{ij} t_{ij} \Xd_{ij} v_i w_j. \label{eq:locpikachu*}
\end{align}
If for some $i,j \leq n$ we have $a_{ij}=0$, then $(A \odot \Xd)_{ij}=0$. As a result
\begin{equation}\label{eq:oszda}
d_{A \odot \Xd} \leq d_A.
\end{equation}
 We use the induction assumption i.e. \eqref{eq:zalinduk}, conditioned on the random matrix $=A \odot \Xd$ to upper bound
 \begin{align*}
 &\Ex \sup_{v,w \in B_2} \sum_{ij} a_{ij} \left( \prod_{k=1}^{\wym+1} \Xk_{ij}\right) v_i w_j = \Ex \sup_{v,w \in B_2} \sum_{ij} (A \odot \Xd)_{ij} \left( \prod_{k=1}^{\wym} \Xk_{ij}\right) v_i w_j \\
 &\lesssim^\wym \Ex \Log^{C(\wym)} \left(d_{A \odot \Xd} \right) \left( \max_i \sqrt{\sum_j (A \odot \Xd)^2_{ij}}+\Ex R_{\Xld}(A \odot \Xd) \right)\\
 &\lesssim^\wym \left(\Log(d_A)\right)^{C(\wym)} \left(\Ex \max_i \sqrt{\sum_j a^2_{ij} (\Xd_{ij})^2}+\Ex\sup_{v,w\in B_2} \sup_{t\in T}\sum_{ij} a_{ij} t_{ij} \Xd_{ij} v_i w_j \right),
 \end{align*}
 where the last line follows from \eqref{eq:locpikachu*} and \eqref{eq:oszda}. Since $\max_i \sqrt{\sum_j b^2_{ij}}\leq \lv (b_{ij})\rv_{op}$, Theorem \ref{tw:bazaindukcji} implies that
\begin{align*}
 \Ex \max_i \sqrt{\sum_j a^2_{ij} (\Xd_{ij})^2} \lesssim \Log^{3/2} (d_A)\left( R_{X^{\wym+1}}(A) +\mia\right).
\end{align*}
 The above can be shown directly by a simple argument (even without the $\Log(d_A)$ part). We refer interested readers to \cite[Proposition 4.4]{latswiat}).
By Lemmas \ref{lem:turbojensen} and then \ref{lem:zmnienwspol} (we recall that $\Ex |\Xk_{ij}| \geq c(\wym)>0$)
\begin{align*}
 R_{X^{(\leq \wym+1)}}(A)&\geq \sup_{v,w\in B_2} \lv \sum_{ij} a_{ij} \Xd_{ij} v_i w_j \left(\Ex \prod_{k=1}^{\wym}|\Xk_{ij}|\right)\rv_{\Log \, n} \\
 &\gtrsim^\wym \sup_{v,w\in B_2} \lv \sum_{ij} a_{ij} \Xd_{ij} v_i w_j \rv_{\Log \, n}= R_{X^{(\wym+1)}}(A).
\end{align*}
Hence, it is enough to show that
\begin{align}
 \Ex\sup_{v,w\in B_2} \sup_{t\in T}\sum_{ij} a_{ij} t_{ij} \Xd_{ij} v_i w_j &\lesssim^\wym \Log^{3/2}(d_A)R_{X^{\leq \wym+1}}(A)\label{eq:cel1} 
\end{align}
Theorem \ref{prop:oszapodgaus} (more precisely \eqref{eq:loctw2}) yields
\begin{multline}
 \Ex\sup_{v,w\in B_2} \sup_{t\in T}\sum_{ij} a_{ij} t_{ij} \Xd_{ij} v_i w_j \lesssim^\wym \Log^{(3/2)}(d_A) \Bigg(\sup_{v,w \in B_2} \lv \sup_{t\in T} \sum_{ij} a_{ij} t_{ij} \Xd_{ij} \rv_{\Log \, n} \\
 +\sup_{t\in T} \lv \AT\rv_{op}+\Ex \sup_{t\in T} \max_{ij} |a_{ij}t_{ij} \Xd_{ij}|\Bigg).\label{eq:loc1a}
\end{multline}
By \eqref{eq:suptpodmomentem}
\begin{align}
 \sup_{v,w\in B_2} \lv \sup_{t\in T} \sum_{ij} a_{ij} t_{ij} \Xd_{ij} v_i w_j \rv_{\Log \, n}\rown^\wym \sup_{v,w\in B_2} \lv \sum_{ij} a_{ij} \prod_{k=1}^{\wym+1} \Xk_{ij} v_i w_j \rv_{\Log \, n}=R_{X^{(\leq \wym+1)}}(A).
 \label{eq:loc1b}
\end{align}

post_theorem_intro_text:
To shorten the notation we define
\begin{align}
 R_{(X_{ij})_{i,j\leq n}}(A,p)&=R_X(A,p)=\sup_{v,w \in B_2} \left\lVert \sum_{ij} a_{ij} v_i w_j X_{ij}\rv_{p}.\label{eq:defR}
\end{align}
Most often, we will consider $p=\mathit{Log} \, n$. In this case, we simply write $R_X(A)$.
\begin{remark}
Formula \eqref{eq:wstepdwustronne} can be deduced from \eqref{eq:twglowneoszacowaniepodwojnylog}. The proof of \cite[Remark 4.5]{latswiat}, based on the permutation method from \cite{lathan} shows that if  we can prove (under assumptions of Theorem \ref{tw:main}) that 
    \[\Ex \left\lVert (a_{ij} X_{ij})_{i,j \leq n} \rv_{op} \leq \beta(\kappa,n)\left(M(A)+R_X(A)\right), \]
    then
    \[\Ex \left\lVert (a_{ij} X_{ij})_{i,j \leq n} \rv_{op} \leq C\beta(\kappa,n) \left(M(A)+D(A,X) \right),\]
    where the constant $\beta$ is equal in both above inequalities. In other words, the cost of applying the permutation trick is the appearance of a multiplicative numerical constant. Hence, the assertion follows by Theorem \ref{tw:glow}.
  Moreover, the lower bound in \eqref{eq:twglowneoszacowaniepodwojnylog} was proved in \cite{latswiat} (Theorem 4.1 therein). Thus, we will prove only the upper bound.
\end{remark}

As in  Lata{\l}a's result \eqref{eq:wsteprad}, the $\mathit{Log}^C \mathit{Log} (n)$ factor is much smaller than the natural scale of the problem. Therefore, Theorem \ref{tw:main} may be viewed as lending support to the hypothesis proposed by Lata{\l}a and \'{S}wi\k{a}tkowski that the lower bound in \eqref{eq:twglowneoszacowaniepodwojnylog} can be reversed (see \cite[Conjecture 4.3]{latswiat}).\\
To prove Theorem \ref{tw:main}, we follow an argument due to Lata{\l}a, which was used in his work \cite{latop}. We associate to a symmetric matrix $(a_{ij})_{i,j \leq n}$ a graph $G_A=([n],E_A)$, where $(i,j)\in E_A$ if and only if $i\neq j$ and $a_{i,j}\neq 0$.  We denote the maximal degree of vertices in $G_A$ by $d_A$. Lata{\l}a's idea was to obtain estimates on the operator norm that depend not on the matrix's dimension but on the (typically) much smaller parameter $d_A$.
\begin{theorem}\label{tw:glow}
 Assume that $(X_{ij})_{i,j \leq n}$ satisfies assumptions of Theorem \ref{tw:main}. Then for any symmetric matrix $A=(a_{ij})_{i,j \leq n}$  we have
\begin{equation}\label{eq:twglownezda}
\Ex \left\lVert (a_{ij} X_{ij})_{i,j \leq n} \rv_{op} \lesssim^\kappa   \mathit{Log}^{C(\kappa)}(d_A)\left(\max_i \lv (a_{ij})_j \rv_2 +R_X(A) \right).     
\end{equation}
\end{theorem}

\textbf{Organization of the paper.} The next section discusses the basic tools used in the sequel. In Section \ref{sec:tw1.1} we prove Theorem \ref{tw:main}, using Theorem \ref{tw:glow}. The proof builds on a generalization of the argument employed in the proof of \cite[Theorem 1.9]{latop}. Section \ref{sec:subgaus} proves a version of Theorem \ref{tw:glow} for subgaussian random variables with an additional supremum over a set $T \subset R^{n^2}$ (no conditions are imposed on $T$). The proof of Theorem \ref{prop:oszapodgaus} is a direct transcription of Lata{\l}a's proof of \cite[Proposition 4.4]{latop}, rewritten to fit our notation and assumptions. The two proofs are otherwise identical. This is made possible by the highly general nature of Lata{\l}a's arguments, which rely on pointwise estimates for random variables, together with a clever discretization of the Euclidean unit ball. However, not all of Lata{\l}a's arguments admit such a generalization. Consequently, we can prove Theorem \ref{tw:main} with a double logarithmic factor rather than a triple one. We present the proof in full in order to keep the exposition self-contained.  The last section is devoted to the proof of Theorem \ref{tw:glow}.

\textbf{Acknowledgments:} The author would like to thank Rafa{\l} Lata{\l}a for valuable discussions related to this work. This paper was inspired by reading his article \cite{latop}.

expanded_theorem:
\label{tw:main}
Assume that $(X_{ij})_{i,j,\leq n} $ are independent, symmetric random variables such that exists $\kappa>1$ such that for all $p\geq 1$ we have 
$\left\lVert X_{ij} \rv_{2p} \leq \kappa \left\lVert X_{ij} \rv_p$. We also assume normalization $\Ex |X_{ij}|=1$ for each $i,j \leq n$. Fix any matrix $A=(a_{ij})_{i,j\leq n}$ and denote $M(A):=\max_i \lv (a_{ij})_j \rv_2+\max_j \lv (a_{ij})_i \rv_2$. Then it holds that
   \begin{equation}\label{eq:twglowneoszacowaniepodwojnylog}
         \Ex \left\lVert (a_{ij} X_{ij})_{i,j \leq n} \rv_{op}\lesssim^\kappa   \mathit{Log}^{C(\kappa)} \mathit{Log}(n)\left(M(A)+\sup_{v,w \in B_2} \left\lVert \sum_{ij} a_{ij} v_i w_j X_{ij}\rv_{\mathit{Log} \, n}\right).    
        \end{equation}
        In particular
        \begin{equation}\label{eq:wstepdwustronne}
          M(A)+D(A,X)\lesssim^\kappa \Ex \sup_{v,w \in B_2} \sum_{ij} a_{ij} X_{ij}v_i w_j \lesssim^\kappa \mathit{Log}^{C(\kappa)} \mathit{Log}(n)\left(M(A)+D(A,X)\right),
        \end{equation}
        where
        \[D(A,X):=\max_{1\leq k \leq n} \min_{I \subset [n],|I|\leq k} \sup_{v,w \in B_2} \left\lVert \sum_{i,j \notin I} a_{ij} X_{ij}v_i w_j \rv_{\mathit{Log} \, {k+1}}.\]

ref_dict.Thm:IGP:
\begin{theorem}\label{Thm:IGP}
    For any prime $p$ for which there exists an $\ell \in \cL$ with the Kronecker symbol $\legendre{\ell}{p}$ equal to $-1$, the group $\PSL_2(\F_{p^2})$ is a \emph{regular} Galois group over $\Q$.\footnote{Concretely, this implies that $\PSL_2(\F_{p^2})$ is realisable as a regular Galois group over $\Q$ for all $p<3,267,289$ (compared to the previous implied bound $p<1,009$).}
\end{theorem}

ref_dict.Thm:cover:
\begin{theorem}\label{Thm:cover}
    Let $K$ be the real quadratic field of discriminant $D$ with ring of integers $\mathfrak o$, and let $X/\Q$ be the Hilbert modular surface of discriminant $D$ and genus $g$ at base level. For every rational prime $p$ that is inert in $K$, there exists a Galois geometrically integral cover $Y_p \to X$ with group $\PSL_2(\mathfrak o/p)$.
\end{theorem}

ref_dict.Rem:shih:
\begin{remark}\label{Rem:shih}
Theorem~\ref{Thm:cover} should be compared to the analogous cover $X_0(p)\to X(1)$ of modular curves corresponding to the level structure $\Gamma_0(p)$.

In the one-dimensional setting, $X_0(p)$ has field of definition $\Q(\zeta_p)$ and one only obtains a $\PGL_2(\F_p)$-cover. Under certain congruence conditions, Atkin-Lehner involutions can be used to turn this into a $\PSL_2(\F_p)$-cover by what has become known as Shih's trick \cite{Shih}. In our situation such a trick is unnecessary.
\end{remark}

