\section{Preliminaries}\label{section-preliminary}

In this section, we introduce the notation and basic properties for oscillatory integral operators satisfying the cinematic curvature condition. Throughout the remainder of the paper, we write $x=(x',x_n)\in \R^n$ and $\xi=(\xi',\xi_{n-1})\in\R^{n-1}$.

\subsection{Some Basic Reductions}\label{subsecquant}
One can reduce Proposition \ref{epsilon main theorem} to the case  $1 \le R \le \lambda^{1-\varepsilon}$ and $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$. Moreover, after an appropriate rescaling, we may further assume that $B^n_R=B^n_R(0)$ and
\begin{equation} \label{assumpetion 1}
    \|\partial_{x,\xi}^\beta a\|_{L^\infty(B^n_1(0) \times \mathbb{A})} \lesssim_\beta 1\qquad \textrm{for all $1 \leq |\beta| \leq N$.} 
\end{equation}
where $N=N_{\e,M,p}\in\N$ is some large number depending only on the dimension $n$ and the fixed choice of $\e,M$ and $p$. Hence, to prove Proposition \ref{epsilon main theorem},it suffices to show that:
\begin{proposition} \label{reduction 1}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition. Then the estimate
\begin{equation*}
    \|T^{\lambda}f\|_{L^p(B^n_R(0))} \lesssim_{\phi,\varepsilon,p} R^\varepsilon \|f\|_{L^{p}(B^{n-1})}
\end{equation*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$, provided that the amplitude $a$ satisfies \eqref{assumpetion 1} and the exponent $p$ lies in the range \eqref{range of result}.
\end{proposition}

To obtain uniform estimates for a family of oscillatory integral operators satisfying the cone condition, it is necessary to strengthen Proposition \ref{reduction 1} This strengthening is essential for implementing an induction-on-scales argument, since a single operator $T^\lambda$ is not stable under rescaling. Nevertheless, the rescaling procedure preserves certain structural features of this class of operators, allowing one to carry out the induction simultaneously over a larger family. In what follows, we work within the framework introduced in \cite[Section 2.3]{BHS}.

Fix a small constant $\cpar>0$ be a small fixed constant. For $\bA=(A_1,A_2,A_3)\in[1,\infty)^3$, we impose the following conditions on the phase function:

\begin{enumerate}
    \item[$(\text{H1}_{\bA})$]  $\|\partial^2_{\xi x'}\phi(x;\xi)-I_{n-1}\|_{\mathrm{op}}\le \cpar A_1$ for all $(x;\xi)\in B^n_1(0)\times \mathbb{A}$.
    \item[$(\text{H2}_{\bA})$] $\|\partial^2_{\xi'\xi'}\partial_{x_n}\phi(x;\xi)-\frac{1}{\xi_{n-1}}I_{n-2}\|_{\mathrm{op}}\le \cpar A_2$ for all $(x;\xi)\in B^n_1(0)\times \mathbb{A}$.
    \item[$(\textup{D1}_\bA)$]$\|\partial_\xi^\beta\partial_{x_k}\phi\|_{L^\infty(B_1^n(0)\times \mathbb{A})}\le \cpar A_1$ for all $1\le k\le n-1$ and $\beta\in\N_0^{n-1}$ with $2\le|\beta|\le 3$ satisfying $|\beta'|\ge 2$;

    \noindent $\|\partial_{\xi'}^{\beta'}\partial_{x_k}\phi\|_{L^\infty(B_1^n(0)\times \mathbb{A})}\le \frac{\cpar}{2n} A_1$ for all $1\le k\le n-1$ and $\beta'\in\N_0^{n-2}$ with $|\beta'|=3$. 
    \item[$(\textup{D2}_\bA)$] $
        \|\partial_\xi^\beta\partial_z^\al\phi\|_{L^\infty(B_1^n(0)\times \mathbb{A})}\le \frac{\cpar}{2n}A_3 $
    for all $(\al,\beta)\in\N_0^n\times \N_0^{n-1}$ with $2\le |\al|\le 4N$ and $1\le |\beta|\le 4N+2$ satisfying $1\le |\beta|\le 4N$ or $|\beta'|\ge 2$. 
    \item[$(\textup{M}_\bA)$] $\dist(\supp_x a, \R^n\setminus B_1^n)\ge \frac{1}{4A_3}$.

\end{enumerate}

\medskip

A pair $(\phi,a)$ is said to be of \textit{type} $\bA$ if it satisfies the conditions $(\textup{H1}_\bA),(\textup{H2}_\bA),\\(\textup{D1}_\bA),(\textup{D2}_\bA)$ and $(\textup{M}_\bA)$ (in addition to (\textbf{H1}) and (\textbf{H2})) is said to be of \textit{type} $\bA$. By decomposing the amplitude function and applying suitable rescaling arguments, one may reduce to the normalized case $\bA=\mathbf{1}:=(1,1,1)$; see \cite[Section 2.5]{BHS} for details.

In the remainder of this paper, we assume that the operator $T^\lambda$ is of type \textbf{1}. Under this normalization, Proposition \ref{reduction 1} admits the following strengthened formulation.

\begin{proposition}\label{main theorem type 1}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1}, then for all $p$ satisfies \eqref{main range}, the estimate
\begin{equation*}
    \|T^{\lambda}f\|_{L^p(B_R^n(0))} \lesssim_{\varepsilon,p,\phi}R^\varepsilon \|f\|_{L^{p}(\mathbb{R}^{n-1})}
\end{equation*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$.
\end{proposition}

\bigskip

\subsection{Wave packet decomposition}

Fix $0<\e \ll 1$. In this subsection, we recall the wave packet decomposition for a function $f \in \mathcal{S}(\mathbb{R}^{n-1})$ at scale $R$ satisfying $1 \ll R \leq \la^{1-\e}$, following the presentation in \cite[Section 3.3]{GW}. 

Condition \textbf{(H1)} guarantees that the mapping
$\partial_\xi \phi(\cdot, x_n; \xi)$ is locally invertible. More precisely, for each
fixed pair $(x_n,\xi)$, the map $x' \mapsto \partial_\xi \phi(x;\xi)$ has a
non-vanishing Jacobian determinant. After a suitable rescaling, we may further assume
that
\begin{equation} \label{assumption2}
\partial_\xi \phi(\cdot, x_n; \xi) \quad \text{defines a diffeomorphism on}\quad
B_1^{n-1}(0) \quad \text{for all} (x_n,\xi) \in [-1,1] \times \mathbb{A}. 
\end{equation}
Consequently, this
mapping admits a well-defined inverse, which we introduce below.

\begin{definition} \cite[Definition 3.3]{GW}
    For $(x_n,\xi)\in [-1,1]\times \mathbb{A}$, let $\Phi(u,x_n;\xi)$ be the unique solution to
    \begin{equation}\label{defPhi}
        \partial_\xi\phi(\Phi(u,x_n;\xi),x_n;\xi)=u.
    \end{equation}
Here, we may assume the equation holds for $u$ in a small neighborhood of the origin.
\end{definition}

Since the phase function $\phi$ is homogeneous of degree one in $\xi$, we have
$\partial_\xi \phi(u;\xi)=\partial_\xi \phi(u;s\xi)$ for any $s>0$. Consequently,
\begin{equation}
\label{1-homo}
    \Phi(u;\xi)=\Phi(u;s\xi)
\end{equation}

Moreover, by invoking the inverse function theorem together with conditions
$(\textup{D1}_\bA)$ and $(\textup{D2}_\bA)$, we obtain uniform $L^\infty$ bounds for
$\Phi$ and its derivatives. Differentiating \eqref{defPhi} with respect to $u$ yields
\[
\partial^2_{\xi, x'= \Phi(u,x_n;\xi)} \phi \cdot \partial_u \Phi = I_n.
\]
As a consequence,
\[
\det \partial_u \Phi(u,x_n;\xi) \gtrsim 1,
\]
That is, the matrix $\partial_u \Phi(u,x_n;\xi)$ is quantitatively non-singular.

Define $\gamma^\lambda: \mathbb{R}^{n-1} \times \mathbb{R} \times \mathbb{A} \mapsto \mathbb{R}^{n-1}$ by
\begin{equation}
\nonumber
    \ga^\la(u,x_n;\xi):=\la \Phi(u/\la,x_n/\la;\xi). 
\end{equation}

Then one has
\begin{equation}
\label{transformation-id}
    \partial_\xi\phi^\la(\ga^\la(u,x_n;\xi),t;\xi)=u.
\end{equation}

For each fixed pair $(u,\xi)$, the mapping $x_n \mapsto (\gamma^\lambda(u,x_n;\xi), x_n)$, with $x_n \in [-R,R]$, traces out a curve. The wave packets considered here will be defined as certain non-isotropic neighborhoods surrounding these curves.

\medskip
We proceed to describe the wave packet decomposition of $T^\lambda f$ at scale $R$. Cover $B^{n-2}_1(0)$ by finite-overlapping caps $\theta$ of diameter $\sim R^{-1/2}$. Let $\Theta_{R^{-1/2}} := \{\theta\}$ and $\{\psi_\theta\}$ be a smooth partition of unity subordinate to this cover. For each $\theta$ let $\omega_\theta$ denote the center of $\theta$ and define $\tilde{\psi_\theta}$ by
\begin{equation*}
\tilde{\psi_\theta}(\xi',\xi_{n-1}) :=
\begin{cases}
\psi_\theta(\xi'/\xi_{n-1}),
& \text{if } (\xi',\xi_{n-1}) \in \mathbb{A}, \\[4pt]
0,
& \text{otherwise}.
\end{cases}
\end{equation*}
Let $f_\theta := \tilde{\psi}_\theta f$. Now we can write
\[ f = \sum_{\theta\in\Theta_{r^{-1/2}}}f_\theta\]
Let $\tilde{\theta} \subset \mathbb{R}^{n-1}$ be a box of dimensions $1 \times R^{-1/2} \times ...\times R^{-1/2}$ such that
