that are parallel to $R^\delta\tilde{\theta}^*$. Denote this collection by
\begin{equation}
\label{T-flat}
\mathcal{T}_\theta^\flat := \{T^\flat\}.
\end{equation}

Let $\{\eta_{T^\flat}\}$ be a smooth partition of unity subordinate to this cover.
Then we may decompose $\widehat{f}$ as
\[
\widehat{f}
= \sum_{\theta \in \Theta_{R^{-1/2}}}
  \sum_{T^\flat \in \mathcal{T}_\theta^\flat}
  \eta_{T^\flat}\,\widehat{f}_\theta .
\]

For each $\theta \in \Theta_{R^{-1/2}}$ and $T^\flat \in \mathcal{T}_\theta^\flat$,
the function
$\widecheck{\eta_{T^\flat}\widehat{f}_\theta}
= \widecheck{\eta_{T^\flat}} * f_\theta$
is essentially supported in $2\tilde{\theta}$.
Consequently,
\begin{equation}
\label{wave packet 1}
f
= \sum_{\theta \in \Theta_{R^{-1/2}}}
  \sum_{T^\flat \in \mathcal{T}_\theta^\flat}
  (\widecheck{\eta_{T^\flat}} * f_\theta)\,\psi_{\tilde{\theta}}
  + \mathrm{Rap}(r)\|f\|_2 ,
\end{equation}
where $\psi_{\tilde{\theta}}$ is a smooth bump function satisfying
$\supp \psi_{\tilde{\theta}} \subset \tilde{3\theta}$ and
$\psi_{\tilde{\theta}}(\xi)=1$ for all $\xi \in \tilde{2\theta}$.

For each $\theta \in \Theta_{R^{-1/2}}$ and $T^\flat \in \mathcal{T}_\theta^\flat$,
we associate a tube
\[
T
:= \bigl\{
\bigl(\gamma^\lambda(u,x_n;\omega_\theta,1),x_n\bigr)
: u \in R^\delta T^\flat,\ -R \le x_n \le R
\bigr\}.
\]
and define
\begin{equation} \label{def fT}
f_T := (\widecheck{\eta_{T^\flat}} * f_\theta)\,\psi_{\tilde{\theta}}.
\end{equation}

$T^\lambda f_T$ is concentrated on $T$. A more precise statement is as follows:
\begin{lemma}\label{lemsuppT} \cite[Lemma 3.12]{GW}
    $(T^\lambda f_T)\Id_{B_R^n(0)}$ is essentially supported in $ T$. In other words, \[(T^\lambda f_T)\Id_{B_R^n(0)\setminus  T}=\rap(R)\|f\|_2.\]
\end{lemma}
With this notation \eqref{def fT}, \eqref{wave packet 1} may be rewritten as
\[
f
= \sum_{\theta \in \Theta_{R^{-1/2}}}
  \sum_{T \in \mathcal{T}_\theta} f_T
  + \mathrm{Rap}(R)\|f\|_2 .
\]
We write $\mathcal{T}_\theta := \{T : T^\flat \in \mathcal{T}_\theta^\flat\}$ and $\mathcal{T} := \bigcup_{\theta \in \Theta_{R^{-1/2}}} \mathcal{T}_\theta$. 

This yields the wave packet decomposition of $f$ at scale $R$. From Plancherel theorem, we see that
\begin{lemma}\label{l2-orthogonalty}
    Suppose $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$ and $\mathcal{T}' \subset \mathcal{T}$, then
    \begin{equation*}
        \|\sum_{T \in \mathcal{T}'}f_T\|_{L^2(\mathbb{R}^{n-1})}^2 \sim \sum_{T \in \mathcal{T}'} \|f_T\|_2^2
    \end{equation*}
\end{lemma}

For each tube $T \in \mathcal{T}$ and each $-R \le t \le R$, the cross-section $T \cap \{x_n = t\}$ is a rectangular box with dimensions $R^{2\delta} \times R^{1/2+\delta} \times \cdots \times R^{1/2+\delta}$. To state this more precisely, we introduce the following definition.

\begin{definition}\cite[Definition 3.5]{GW}
\label{defgaV}
Given $\xi_0\in \mathbb{A}$ and a box $V\subset B_R^{n-1}(0)$, define
\begin{equation}\label{defgaVeq}
    \Ga_V(\xi_0;R):=\{ (\ga^\la(u,x_n;\xi_0),t):u\in V,|x_n|\le R \}.
\end{equation}
$\Ga_V(\xi_0;R)$ is called a curved plank with base $V$ and direction $\xi_0$.
\end{definition}
Using the notation of curved planks, each tube $T\in \mathcal{T}$ can be represented as
    \[T= \Ga_{R^\de T^\flat}(\omega_\theta,1;R), \]
that is, a curved plank with base $R^\de T^\flat$ and direction $(\omega_\theta,1)$. We refer to each such $T$ as an \textbf{$R$-plank}. Formally,
\begin{lemma}\label{geometric} \cite[Lemma 3.9]{GW}
Let $s\in[R^{-1/2},1]$ and $\xi_0 \in \mathbb{A}$. Let $V\subset \mathbb{R}^{n-1}$ be a slab of dimensions $Rs^2\times Rs \times \dots\times Rs $. Then for $|t|\leq R$, each $t$-slice $\Ga_V(\xi_0;R)\cap \{x_n=t\} $ is comparable to a $Rs^2\times Rs\times \dots\times Rs$-slab.
\end{lemma}

