    \begin{equation*}
    \|T^{\lambda}f_T\|_{L^q(B_{2R}^n(0))} \lesssim_{\phi}\|f_T\|_{L^{2}(\mathbb{R}^{n-1})}
    \end{equation*}
\end{corollary}
