 	\begin{itemize}
 		\item[(i)] If $\End(A)\otimes_\Z \Qp$ is a division algebra.
 		\item[(ii)] If $\End(A)\otimes_\Z \Q$ has no factor of Albert-type IV.
 	\end{itemize}
 \end{theo}

