  \item Janko groups:   
     \begin{itemize} 
     \item[(J1)] $J_{1}$;
     \item[(J2)] $J_{3}$;
     \item[(J3)] $J_{4}$;
     \end{itemize}
  \item Conway groups:   
     \begin{itemize} 
     \item[(C1)] $Co_{2}$;
     \item[(C2)] $Co_{3}$;
     \end{itemize}
  \item Fischer groups:
    \begin{itemize} 
