     \item[(F2)] $Fi_{24}'$;
     \end{itemize}
  \item McLaughlin group: $McL$;
  \item Held group: $He$;
  \item O'Nan group: $O'N$;
  \item Harada-Norton group: $HN$;
  \item Lyons group: $Ly$;
