\begin{theorem}\label{conj:PTB}
Let $\pi$ be a generic representation of $G$, and $\phi=\phi_\pi$.
\begin{itemize}
\item[(1)] If $\pi$ is $E$-distinguished, then $\phi$ takes values in $\Sp_n(\C)$.
\item[(2)] Suppose $\phi$ takes values in $\Sp_n(\C)$ and we write it in the following form:
    \[
    \phi = \bigoplus_{i\in I_\phi} \phi_i \oplus \bigoplus_{j\in J_\phi}(\phi_j\oplus\phi_j^\vee),
