n_t & = \frac{\kappa_d}{2^d} \rho_t, & m_t &= \frac{\kappa_d}{2^d} \rho_t,& \text{ and } && I(x) &= \begin{cases} 1+x\ln x-x & \text{ if } x\geq 1, \\ \infty & \text{ otherwise.}\end{cases}\\ 
