    Consider affine morphism $t\colon T \to S$ locally of finite tor-dimension of Noetherian schemes whose target is semiseparated. Suppose $Y_1$ and $Y_2$ are proper and flat $S$-schemes. Denote by $\pi \colon Y_1\times_S Y_2 \times_S T \to Y_1\times_S Y_2$ the natural morphism. Let $K\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$ be relatively perfect over each $Y_i$. If $\Phi_K$ restricts to a fully faithful functor (resp.\ an equivalence) on $D^b_{\operatorname{coh}}$, then so does $\Phi_{\mathbf{L}\pi^\ast K}$.

ref_dict.prop:intro_preservation_adjoint:
\begin{proposition}
    \label{prop:intro_preservation_adjoint}
    Suppose $t\colon T \to S$ is a morphism of Noetherian schemes. Let $Y_1$ and $Y_2$ be proper and flat $S$-schemes. Denote by $\pi \colon Y_1\times_S Y_2 \times_S T \to Y_1\times_S Y_2$ the natural morphism. Consider $K\in D^-_{\operatorname{coh}}(Y_1\times_S Y_2)$. 
    \begin{enumerate}
        \item \label{prop:intro_preservation_adjoint1} If $t$ is affine and $\Phi_K$ restricts to $D^b_{\operatorname{coh}}$ (resp.\ $\operatorname{Perf}$), then so does $\Phi_{\mathbf{L}\pi^\ast K}$ (see \Cref{lem:induced_dbcoh_perf_preservation_upon_pullback_with_t_affine}). Additionally, the converse holds if $t$ is faithfully flat (see \Cref{cor:bounded_pseudocoherence_perfectness_faithfully_flat_affine}).
        \item \label{prop:intro_preservation_adjoint2} Assume $t$ is affine and locally of finite tor-dimension. 
        \begin{enumerate}
            \item \label{prop:intro_preservation_adjoint2a} If $\Phi_K$ restricts to $\operatorname{Perf}$, then $\mathbf{L}\pi^\ast$ preserves the adjunction of $\Phi_K$ with its right adjoint (see  \Cref{prop:right_adjoint_pullback}).
            \item \label{prop:intro_preservation_adjoint2b} If $\Phi_K$ restricts to $D^b_{\operatorname{coh}}$, then $\mathbf{L}\pi^\ast$ preserves the adjunction of $\Phi_K$ with its left adjoint (see \Cref{prop:left_adjoint_pullback}).
        \end{enumerate}
    \end{enumerate}
\end{proposition}

ref_dict.prop:CM_or_Gorensteinnes_morphisn_derive:
\begin{proposition}
    \label{prop:CM_or_Gorensteinnes_morphisn_derived_invariance}
    Let $f_i \colon Y_i \to S$ be projective flat morphisms to a separated Noetherian scheme with geometrically integral fibers. Assume that $Y_1$ and $Y_2$ are Fourier--Mukai partners over $S$. Then $f_1$ is Cohen--Macaulay (resp.\ Gorenstein) if, and only if, $f_2$ satisfies the same condition.
\end{proposition}

ref_dict.rmk:equivalences_induced:
\begin{remark}
    \label{rmk:equivalences_induced}
    Let $\Phi\colon D_{\operatorname{qc}}(Y_1) \to D_{\operatorname{qc}}(Y_2)$ be an exact functor where each $Y_i$ is Noetherian. Then the following are equivalent:
    \begin{enumerate}
        \item \label{rmk:equivalences_induced1} $\Phi$ is an equivalence
        \item \label{rmk:equivalences_induced2} $\Phi$ restricts to an equivalence on $D^-_{\operatorname{coh}}$
        \item \label{rmk:equivalences_induced3} $\Phi$ restricts to an equivalence on $D^b_{\operatorname{coh}}$
        \item \label{rmk:equivalences_induced4} $\Phi$ restricts to an equivalence on $\operatorname{Perf}$.
    \end{enumerate}
    Indeed, by \cite[Theorem 3.2(iv)]{Neeman:2022} and \cite[Theorem B]{Canonaco/Haesemeyer/Neeman/Stellari:2024}, $\eqref{rmk:equivalences_induced1} \implies \eqref{rmk:equivalences_induced2} \implies \eqref{rmk:equivalences_induced3} \implies \eqref{rmk:equivalences_induced4}$. Additionally, if $\eqref{rmk:equivalences_induced4}$ holds, then $\Phi$ admits a right adjoint that preserves small coproducts \cite[Theorem 5.1]{Neeman:1996}. So, \Cref{lem:equivalence_or_fully_faithful_via_compacts} tells us $\eqref{rmk:equivalences_induced4} \implies \eqref{rmk:equivalences_induced1}$.
\end{remark}

ref_dict.prop:right_adjoint_pullback:
\begin{proposition}
    \label{prop:right_adjoint_pullback}
    Consider \Cref{setup:fm_cube_pullback} where $t$ is an affine morphism locally of finite tor-dimension (e.g.\ $t=1_S$). Let $K\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$ be relatively perfect over $Y_2$. Then $\Phi_{\mathbf{L}(t^\prime)^\ast K^\prime}$ is right adjoint to $\Phi_{\mathbf{L} (t^\prime)^\ast K}$ on $D_{\operatorname{qc}}$ where $K^\prime:= \mathbf{R}\operatorname{\mathcal{H}\! \mathit{om}} (  K,  (f^\prime_1)^! \mathcal{O}_{Y_2})$. In particular, $K^\prime\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$.
\end{proposition}

ref_dict.prop:invariance_under_unit_preserve_adjo:
\begin{proposition}
    \label{prop:invariance_under_unit_preserve_adjointness}
    Consider \Cref{setup:fm_cube_pullback} where $t$ is an affine morphism locally of finite tor-dimension. Let $K\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$ be relatively perfect over $Y_2$. Denote by $K^\prime$ for the kernel of the integral transform obtained in \Cref{prop:right_adjoint_pullback} which is right adjoint to $\Phi_K$ on $D_{\operatorname{qc}}$. If $\Phi_K$ is fully faithful on $D_{\operatorname{qc}}$, then $\mathbf{L} t^\ast_1$ preserves the unit $\eta$ of the adjoint pair $\Phi_K$ and $\Phi_{K^\prime}$ on $D_{\operatorname{qc}}$. That is, $\mathbf{L}t_1^\ast \eta_E$ is the unit of $\mathbf{L}t_1^\ast E$ for the adjoint pair $\Phi_{\mathbf{L}(t^\prime)^\ast K}$ and $\Phi_{\mathbf{L}(t^\prime)^\ast K}$.
\end{proposition}

ref_dict.cor:special_fibers_genii_invariance:
\begin{corollary}
    \label{cor:special_fibers_genii_invariance}
    Let $S$ be a separated Noetherian $\mathbb{Q}$-scheme. Suppose $f_i\colon Y_i \to S$ are proper flat morphisms whose special fibers are geometrically integral curves. Assume $f_1$ is locally projective. If $Y_1$ and $Y_2$ are Fourier--Mukai partners over $S$, then then genii of the special fibers of $Y_1$ coincide with that of $Y_2$.
\end{corollary}

ref_dict.prop:left_adjoint_pullback:
\begin{proposition}
    \label{prop:left_adjoint_pullback}
    Consider \Cref{setup:fm_cube_pullback} where $t$ is an affine morphism locally of finite tor-dimension. Let $K\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$ be relatively perfect over $Y_1$. Then $\Phi_{\mathbf{L}(t^\prime)^\ast K^\prime}$ is left adjoint to $\Phi_{\mathbf{L} (t^\prime)^\ast K}$ on $D_{\operatorname{qc}}$ where $K^\prime:= \mathbf{R}\operatorname{\mathcal{H}\! \mathit{om}} (  K,  (f^\prime_2)^! \mathcal{O}_{Y_1}) $. In particular, $K^\prime\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$.
\end{proposition}

ref_dict.prop:smoothness_derived_invariance:
\begin{proposition}
    \label{prop:smoothness_derived_invariance}
    Let $Y_1$ and $Y_2$ be proper schemes over a field $k$ (which need not be perfect). Suppose $Y_1$ and $Y_2$ are Fourier--Mukai partners. If $Y_1$ is geometrically regular, then so is $Y_2$. In other words, smoothness is a derived invariance.
\end{proposition}

ref_dict.cor:smooth_morphisn_derived_invariance:
\begin{corollary}
    \label{cor:smooth_morphisn_derived_invariance}
    Let $f_i \colon Y_i \to S$ be locally projective flat morphisms to a separated Noetherian scheme. Assume that $Y_1$ and $Y_2$ are Fourier--Mukai partners over $S$. Then $f_1$ is smooth if, and only if, $f_2$ is smooth.
\end{corollary}

ref_dict.prop:adjoints_generalized_affine:
\begin{proposition}
    \label{prop:adjoints_generalized_affine}
    Consider \Cref{setup:fm_cube_pullback} where $t$ is affine, $f_1$ is locally projective, and $S$ is semiseparated. Let $K\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$ be relatively perfect over $Y_2$. Denote by $K^\prime$ the kernel of the integral transform associated to the right adjoint of $\Phi_K \colon D_{\operatorname{qc}}(Y_1) \to D_{\operatorname{qc}}(Y_2)$ obtained in \Cref{prop:right_adjoint_pullback}. If $\Phi_K$ is fully faithful on $D_{\operatorname{qc}}$, then $\mathbf{L} t^\ast_1$ preserves the unit $\eta$ of the adjoint pair $\Phi_K$ and $\Phi_{K^\prime}$ on $D_{\operatorname{qc}}$. That is, $\mathbf{L}t_1^\ast \eta_E$ is the unit of $\mathbf{L}t_1^\ast E$ for the adjoint pair $\Phi_{\mathbf{L}(t^\prime)^\ast K}$ and $\Phi_{\mathbf{L}(t^\prime)^\ast K^\prime}$.
\end{proposition}

ref_dict.introthm:fully_faithfulness_equivalence:
\begin{theorem}
    [see \Cref{cor:ascending_faithfully}]
    \label{introthm:fully_faithfulness_equivalence}
    Consider affine morphism $t\colon T \to S$ locally of finite tor-dimension of Noetherian schemes whose target is semiseparated. Suppose $Y_1$ and $Y_2$ are proper and flat $S$-schemes. Denote by $\pi \colon Y_1\times_S Y_2 \times_S T \to Y_1\times_S Y_2$ the natural morphism. Let $K\in D^b_{\operatorname{coh}}(Y_1\times_S Y_2)$ be relatively perfect over each $Y_i$. If $\Phi_K$ restricts to a fully faithful functor (resp.\ an equivalence) on $D^b_{\operatorname{coh}}$, then so does $\Phi_{\mathbf{L}\pi^\ast K}$.
