\begin{corollary}
    [cf.\ {\cite[Lemma 2.12]{Orlov:2002}}]
    \label{cor:orlov_varieties}
    Consider proper schemes $Y_1$ and $Y_2$ over a field $k$. Let $K\in D^b_{\operatorname{coh}}(Y_1\times_k Y_2)$ be relatively perfect over each $Y_i$. If $\Phi_K$ restricts to a fully faithful functor (resp.\ an equivalence) on $D^b_{\operatorname{coh}}$, then so does $\Phi_{K_L}$ for any field extension $L/k$.
