Let $K$ be a number field, and let $E$ be an elliptic curve over $K$. 
Throughout this article, we order elliptic curves by \textit{naive height},\footnote{As defined in equation (\ref{eq:naive_height}).} which we denote by $\textnormal{Ht}(E)$.
The average rank of elliptic curves over $K$ is conjectured to be $1/2$. 
A conjecture of Bhargava, Kane, Lenstra, Poonen, and Rains have conjectured that the average size of the $n$-Selmer group of elliptic curves is the sum of the positive divisors of $n$ \cite{PR12, BKLPR15}. Proving this conjecture for arbitrarily large $n$ would imply that the average rank is $1/2$. 
Over the rational numbers ${\mathbb Q}$, Bhargava and Shankar have computed the average size of the $n$-Selmer group of elliptic curves for each $n\in\{2,3,4,5\}$ \cite{BS15a, BS15b, BS13a, BS13b}. 
Using their results on the average size of the $5$-Selmer group, they were able to conclude that the average rank of elliptic curves over ${\mathbb Q}$ is bounded above by $0.885$.

In this article, we study families of elliptic curves for which the average size of the $n$-Selmer group can be unbounded. Let $\cY_1(M,N)$ denote the moduli stack of elliptic curves, whose $K$-points parametrize triples $(E,P,C)$, where
\begin{itemize}
\item $E$ is an elliptic curve over $K$,
\item $P\in E[MN](K)$ is an $NM$-torsion point of $E$, and
\item $C\leq E[M](\overline{K})$ is a $\textnormal{Gal}(\overline{K}/K)$-stable cyclic subgroup of order $M$, such that $$E[M](\overline{K})=\langle NP\rangle \oplus C.$$
\end{itemize}

Let $\cX_1(M,MN)$ denote the smooth compactification of $\cY_1(M,MN)$, and let $X_1(M,MN)$ denote the coarse space of $\cX_1(M,MN)$. 
For $B\in \R_{>0}$, let $\cE_{(M,MN)}(B;K)$ denote the set of elliptic curves $E$ defined over $K$ with height $\textnormal{Ht}(E)\leq B$ and for which there exists $P$ and $C$ with $(E,P,C)\in \cY_1(M,MN)(K)$.

Let $\cO_K$ denote the ring of integers of $K$.
For $m\in \Z_{>1}$, define $\sG_m(K)$ to be the subgroup of $\left({\mathbb Z}/m{\mathbb Z}\right)^\times$ consisting of elements $a\in \left({\mathbb Z}/m{\mathbb Z}\right)^\times$, for which there exist infinitely many prime ideals ${\mathfrak p}\subset \cO_K$ with norm $N_{K/{\mathbb Q}}({\mathfrak p})=p$ a rational prime satisfying $p\equiv a\ (\mathrm{mod}\ m)$.

Let $\Sel_{m}(E)$ denote the $m$-Selmer group of $E$. 
The main result in this article is the following theorem concerning the average size of $\Sel_{m}(E)$ in families.

\begin{equation}\label{eq:naive_height}
\Ht(E)\defeq \Ht_{(4,6)}([a:b])^{12}.
\end{equation}

Let $\Sel_{m}(E)$ denote the $m$-Selmer group of $E$. 
The main result in this article is the following theorem concerning the average size of $\Sel_{m}(E)$ in families.

\begin{remark}
 Equation (\ref{eq:main}) of Theorem \ref{thm:main} can be extended to $d$-Selmer groups for all divisors $d\in \Z_{>1}$ of $M$, and examples of this are given in Section \ref{sec:Composite_case}. 
\end{remark}

\begin{proposition}\label{prop:elliptic_count_general}
Let $G\leq \GL_2(\Z/N\Z)$, and suppose that the modular curve $\cX_G$ is isomorphic to the weighted projective stack $\cP(w_0,w_1)$ over the number field $K$. 
Let $\delta(G)$ denote the weighted degree of the morphism $\phi_{O}:\cX_G\to\cX(1)$ that forgets the level structure, and suppose that $\gcd(w_0w_1, \delta(G))=1$. Define
\begin{equation}
 \alpha(G)\defeq\frac{w_0+w_1}{12 \delta(G)}\qquad \text{ and }\qquad
 \beta(G)\defeq \frac{\deg_{\Q}(K)-\min\{w_0,w_1\}}{12\delta(G)\deg_{\Q}(K)}.
 \end{equation}
Let $v\in \Val_0(K)$ be a finite place not above $2$ or $3$, and let $\Omega_v\subseteq\cP(w_0,w_1)(K_v)$ be a subset for which $\Omega_v^{\aff}$ is measurable and whose boundary has measure $m_v(\partial \Omega_v^{\aff})=0$. 
Then there exists an explicit constant $\kappa_G$, depending only on $G$ and $K$, such that
\begin{equation}
\cN_G(K,\Omega_v; B) 
 = m_v\left(\Omega_v^{\aff}\cap \cO_{K,v}^{2}\right)\kappa_G B^{\alpha(G)}
 + O\left(B^{\beta(G)}\right).
\end{equation}
\end{proposition}

\begin{theorem}\label{thm:selmer_erdos_kac_prime}
 Consider the family of elliptic curves $E$ over a number field $K$ with level structure $G=G(M,MN)$. Let $\Phi$ be a subgroup of $\Z/M\Z$ of prime order, and let $m$ be as in Table \ref{tab:mean_variance_II}. Let $\sG = \sG_m(K)$ denote the subgroup 
\begin{equation}
 \{a\in (\Z/m\Z)^\times : \exists \text{ infinitely many degree one primes $\p$ with } N_{K/\Q}(\p)\equiv a \pmod{m}\}.
\end{equation}
 Let $c_{\E}(G,\Phi,\sG)$ and $\c_{\V}(G,\Phi,sG)$ be the constants in Table \ref{tab:mean_variance_II}. 
 Then the logarithmic Selmer ratios $s(E)$ are normally distributed with mean
 \begin{equation}
 c_{\E}(G,\Phi,\sG)\log\log(B)+O(1)
 \end{equation}
 and variance
 \begin{equation}
 c_{\V}(G,\Phi,\sG)\log\log(B)+O(1).
 \end{equation}
\end{theorem}

\begin{theorem}\label{thm:main2}
Suppose that $X_1(M,MN)$ has genus zero, and suppose that $p$ is a prime divisor of $MN$. Let $\theta(G, \Phi, \sG_m(K))$ denote the constant in Table \ref{tab:mean_variance_II}. Then
\begin{equation}\label{eq:main2}
 \limsup_{B\to\infty} \frac{1}{\# \cE_{G}(B; K)} \sum_{E\in \cE_{G}(B;K)} \# \Sel_p(E) \gg \log(B)^{\theta(G, \Phi, \sG_m(K))}.
\end{equation}
\end{theorem}

The method used to prove Theorem \ref{thm:selmer_erdos_kac_prime} works in this case as well. 
 For each $n\in \{-1,-1/2,0,1/2,1\}$ define a random variable
 \begin{equation}
X_{n,v}\defeq \begin{cases}
1 & \text{ with probability } \kappa_n(G,\Phi,v),\\
0 & \text{ with probability } 1-\kappa_n(G,\Phi,v).
\end{cases}
\end{equation}
Then we model the distribution of 
\begin{equation}
 s_n(B) \defeq \sum_{N_{K/\Q}(\p_v)\leq B} \#\{E\in \cE(K; B) : s_v(E)=n\}
\end{equation}
by the sum of random variables
\begin{equation}
X_n(B)\defeq \sum_{N_{K/\Q}(\p_v)\leq B} \varepsilon(K,a_v,m) X_{n,v}.
\end{equation}
Then we apply the Central Limit Theorem to obtain the distribution of the $X_n(B)$. We note the distribution will depend on the subgroup of $9$-th roots of unity contained in $K$, which we denote by $\sG=\sG_9(K)$. Table \ref{tab:9-isogeny_distributions} gives constants $c_n(G(1,9),C_9,\sG)$, such that $X_n(B)$ has mean and variance
\begin{equation}
 c_n\left(G(1,9),C_9,\sG\right) \log\log(B) + O(1).
\end{equation}

Let $\theta(G(1,9),C_9,\sG_9(K))$ be as in Table \ref{tab:9-isogeny_selmer_distributions}. 
By the same argument as the proof of Theorem \ref{thm:main2}, we have
\begin{equation}
 \limsup_{B\to\infty} \frac{1}{\# \cE_{G(1,9)}(B; K)} \sum_{E\in \cE_{G(1,9)}(B;K)} \# \Sel_9(E) \gg \log(B)^{\theta(G(1,9), C_9, \sG_9(K))}.
\end{equation}

Define
\begin{align}
 \theta(G(1,6),C_6,\{1\})&\defeq 1+\log_6\left(\frac{3}{2}\right)^2\\
 \theta(G(1,6),C_6,\{1\})&\defeq \frac{1}{4} - \frac{1}{2}\log_6\left(\frac{3}{2}\right) + \frac{1}{2} \log_6(2)^2 + \frac{3}{4} \log_6\left(\frac{3}{2}\right)^2.
\end{align}
By the same argument as the proof of Theorem \ref{thm:main2}, we have
\begin{equation}
 \limsup_{B\to\infty} \frac{1}{\# \cE_{G(1,6)}(B; K)} \sum_{E\in \cE_{G(1,6)}(B;K)} \# \Sel_6(E) \gg \log(B)^{\theta(G(1,6), C_6, \sG_6(K))}.
\end{equation}

\begin{equation}\label{eq:main}
	\limsup_{B\to\infty} \frac{1}{\# \cE_{(M,MN)}(B; K)} \sum_{E\in \cE_{(M,MN)}(B;K)} \# \Sel_p(E) \gg \log(B)^{\theta}.
\end{equation}

\begin{theorem}\label{thm:main}
