 \W(S^m)/S^m &= \W(S)/S \times \cdots \times \W(S)/S \quad \text{($m$ times)}.
\end{align*}
By assumption, there exists an $\hH \times \Aut(S)$-equivariant bijection 
\[
\Omega_S \colon \IBr(S) \to \W(S)/S
\]
such that $(S, \eta)_{\hH} \geqslant_{\ast} (\N_S(Q), \eta')_{\hH}$ for every $\eta \in \IBr(S)$ and $(Q, \eta') \in \Omega_S(\eta)$, where $\ast \in \{c, b\}$ depending on our assumption.

\begin{prop}\label{prop:ibGAW1}
Let $K$ be a finite perfect group such that $Z := \Z(K)$ is a $p'$-group and $K/Z$ is a direct product of isomorphic non-abelian simple groups satisfying the inductive GAW (resp. BGAW) condition.
Then Conjecture \ref{ConjA} (resp. Conjecture \ref{ConjB}) holds for $K$.
\end{prop}
\begin{proof}
Let $K/Z \cong L^m$, and let $S$ be the universal $p'$-covering group of $L$.
Let $\epsilon \colon S^m \to K$ be the universal $p'$-central extension of $K$.
Since every automorphism $\phi$ of $K$ lifts to a unique automorphism $\hat\phi$ of $S^m$, we can regard $\Aut(K)$ as a subgroup of $\Aut(S^m)$.
In fact, $\Aut(K) = \Aut(S^m)_{\ker(\epsilon)}$.
Let $1_{\ker(\epsilon)}$ be the trivial character of $\ker(\epsilon)$.
Then we can identify $\IBr(K)$ with the subset $\IBr(S^m \which 1_{\ker(\epsilon)})$ of $\IBr(S^m)$.

\begin{thm}\label{thm:ibGAW.con.}
Let $Z$ be a cyclic central $p'$-subgroup of a finite group $K$.
Suppose that $K/Z$ is either a direct product of isomorphic non-abelian simple groups satisfying the inductive GAW (resp. BGAW) condition, or a $p'$-group.
Then Conjecture \ref{ConjA} (resp. Conjecture \ref{ConjB}) holds for the group $K$.
\end{thm}
\begin{proof}
The theorem holds trivially if $K/Z$ is a $p'$-group.
Now suppose that $K/Z$ is a direct product of isomorphic non-abelian simple groups satisfying the inductive GAW (resp. BGAW) condition.
Let $K_1$ be the commutator subgroup of $K$ and $Z_1 = Z \cap K_1 = \Z(K_1)$. Note that $K_1$ is perfect and $K = K_1 Z$.
Since $K_1/Z_1 \cong K/Z$, by Proposition \ref{prop:ibGAW1}, Conjecture \ref{ConjA} (resp. Conjecture \ref{ConjB}) holds for $K_1$.

\begin{coro}\label{coro:10.4}
Let $L$ be a finite non-abelian simple group of order divisible by $p$ and $S$ be the universal $p'$-covering group of $L$. Suppose that there exists a finite group $G$ such that $S\zg G$ and $G$ induces all automorphisms on $S$ by conjugation.
