        |\cA(x,t,\xi)| \leq L |\xi|^{p-1}
\end{equation}
    and
    \begin{equation}\tag{S2a}\label{as:monotonicity-weaker}
            \left(\cA(x,t,\xi)-\cA(x,t,\eta) \right) \cdot \left( \xi - \eta \right) > 0 \text{ for all $\xi$, $\eta \in \R^n$ with } \xi \neq \eta\,,\end{equation}
    and assume that $u\in {C}(\Omega_T)$ is a weak solution of
    \begin{equation}\label{eq_main}
    \partial_t u-\div \cA(x,t,\nabla u)=0\,,
\end{equation}
    in $\Omega_T\backslash E$ such that 
    \begin{equation}
        \left| u(z)-u(z_0) \right|
        \leq
        Md^\alpha_\alpha(z,z_0)\,,
        \label{eq:Holder-condition-E}
    \end{equation}
    holds for every $z_0 \in E$ and $z \in \Omega_T$. If $\mathcal{H}^{n+\alpha}_{(\alpha)}(E) = 0$, then $u$ is a weak solution to the same equation in $\Omega_T$.

