\mathcal{J}(u)=\frac{\gamma}{p}\|\nabla u\|_p^p + \frac{1-\gamma}{p} [u]_{s,p}^p + \frac{1}{p}\|u\|_{p,\beta}^p- \frac{1}{q}\|u\|_{q, \alpha}^q
\end{equation}
defined on a suitable space $\mathcal{W}^{s,p}_\beta(\mathbb{R}^N)$, where $\|u\|_{\beta,p}^p$ denotes the integral $\int_{\mathbb{R}^N} |x|^\beta |u|^p\,dx$, and $[u]_{s,p}$ is the so-called Gagliardo seminorm (see Section \ref{sec.1} for precise definitions). Indeed, $\mathcal{J}$ is a $C^1$ functional whose Frech\'et derivative is given by
\begin{align*}
\langle \mathcal{J}'(u),v \rangle &=\gamma \int_{\mathbb{R}^N} \Phi_p(\nabla u)\cdot \nabla v\,dx + (1-\gamma) \iint_{\mathbb{R}^N\times\mathbb{R}^N} \frac{\Phi_p(u(x)-u(y))(v(x)-v(y))}{|x-y|^{N+sp}}\,dxdy\\ &\quad +\int_{\mathbb{R}^N} |x|^\beta \Phi_p(u)v\,dx - \int_{\mathbb{R}^N} |x|^\alpha \Phi_q(u)v\,dx \qquad \forall u,v \in \mathcal{W}^{s,p}_\beta(\mathbb{R}^N), 
\end{align*}
where $\Phi_p(t):=|t|^{p-2}t$. Therefore, any critical point of $\mathcal{J}$ is a weak solution of \eqref{eq}.

Our first result establishes a range of parameters for which a weak solution of \eqref{eq} exists. For further reference, we let for $\gamma\in [0, 1]$,
\begin{equation*}
p^{*}_{\gamma, s, \alpha}:= \begin{cases}
\frac{p(N+\alpha)}{N-sp}, \quad \text{if }\gamma = 0,\\
\frac{p(N+\alpha)}{N-p}, \quad \text{if }\gamma \in (0, 1].
\end{cases}
\end{equation*}

Precisely, we have:

\begin{align}\label{space}
\mathcal{W}^{s,p}_\beta(\mathbb{R}^N)=
\begin{cases}
W^{s,p}_{rad,\beta}(\mathbb{R}^N) & \text{ if } \gamma=0\\
W^{1,p}_{rad,\beta}(\mathbb{R}^N)  & \text{ if } \gamma\in(0,1].
\end{cases}
\end{align}

Precisely, we have:

The proof of Theorem \ref{teo.1} relies mainly on establishing a suitable compact embedding of the fractional Sobolev space of weighted radial functions into an appropriate weighted Lebesgue space (see Theorem \ref{compact}). This compactness result is the key ingredient that enables the application of a Mountain Pass–type existence theorem (see Lemma \ref{lema.BN}).

\begin{theorem} \label{teo_boundedness}
Let $s\in (0,1]$ be such that $1/p<s<N/p$, $\alpha>-sp $ and $p<q<p^{*}_{\gamma, s, \alpha}$. Moreover, assume condition \eqref{cond exponent 2}. Then, for any radial weak solution $u$ to \eqref{eq}, there is a constant $C>0$ such that
$$\|u\|_{L^{\infty}(\mathbb{R}^N)}\leq C.$$
\end{theorem}

\begin{theorem} \label{teo.no.exist}
Let $s\in (0,1]$ be such that $1/p<s<N/p$, $\alpha>-sp$ and $\beta>p(1-s)$. Then, for all $q>p^{*}_{\gamma, s, \alpha}$, problem \eqref{eq} has no solutions $u\in \mathcal{\tilde X}(\mathbb{R}^N)$, being
$$
\mathcal{\tilde X}(\mathbb{R}^N) =\{ u \in \mathcal{W}^{s,p}_\beta(\mathbb{R}^N)\cap L^\infty(\mathbb{R}^N) \text{ such that } |\nabla u(x)||x| \in L^r(\mathbb{R}^N) \text{ for some } r>1\}.
$$
\end{theorem}

\begin{lemma}\label{continuity}
Let $s \in(0,1]$ such that $1/p<s<N/p$, $-sp<\alpha$ and $p<q<\frac{p(N+\alpha)}{N-sp}$. Moreover, assume that
\begin{equation}\label{cond exponents}
\alpha-\beta +(q-p)\left(\dfrac{1-N}{p} \right)<0.
\end{equation}
Then, for any $u\in W^{s,p}_{rad, \beta}(\mathbb{R}^N)$, there holds
\begin{equation}\label{ineq with eta}
\int_{\mathbb{R}^N}|x|^\alpha |u|^q\,dx \leq C\|u\|_{s, p}^\eta\|u\|_{p, \beta}^\omega ,
\end{equation}for some $\eta, \omega>0$ depending on $N, p, q$ and $s$.
\end{lemma}

\begin{proof}
Let $\varepsilon >0$. Since $q<\frac{p(N+\alpha)}{N-sp}$, by Lemma \ref{embedding with W}, there is $c<\alpha$ such that
\begin{equation}\label{objective2}
\left(\int_{\mathbb{R}^N}|x|^c |u|^q\,dx\right)^{1/q} \leq C\|u\|_{{s, p}}.
\end{equation}Now,
\begin{equation}\label{ineq 1 eps}
\int_{|x|\leq \varepsilon}|x|^\alpha |u|^q\,dx = \int_{|x|\leq \varepsilon}|x|^{\alpha-c}|x|^c|u|^q\,dx \leq C\varepsilon^{\alpha-c}\|u\|^q_{s, p}.
\end{equation}Next, by Strauss' Lemma \ref{Strauss lemma} and Remark \ref{cont with beta}, we get that
\begin{equation}
\begin{split}
\int_{|x|>\varepsilon}|x|^\alpha |u|^q\,dx &= \int_{|x|>\varepsilon}|x|^{\alpha-\beta}|x|^\beta |u|^{q-p}|u|^p\,dx \\& \leq C\int_{|x|>\varepsilon}|x|^\beta |u|^{p} |x|^{\alpha-\beta}\left(|x|^{\frac{1-N}{p}}\|u\|_{s, p}\right)^{q-p}\,dx \\& = C \|u\|_{s, p}^{q-p} \int_{|x|>\varepsilon}|x|^\beta |u|^{p} |x|^{\alpha-\beta +(q-p)\frac{1-N}{p}}\,dx .
\end{split}
\end{equation}
Condition \eqref{cond exponents} yields that
\begin{equation}\label{ineq 2 eps}
\int_{|x|>\varepsilon}|x|^\alpha |u|^q\,dx \leq C\varepsilon^{\alpha-\beta +(q-p)\frac{1-N}{p}}\|u\|^p_{L^p_\beta} \|u\|_{s, p}^{q-p}.
\end{equation}Therefore, combining \eqref{ineq 1 eps} and \eqref{ineq 2 eps},
\begin{equation}
\int_{\mathbb{R}^N}|x|^\alpha |u|^q\,dx \leq C\left(\varepsilon^{\alpha-c}\|u\|^p_{s, p} + C\varepsilon^{\alpha-\beta +(q-p)\frac{1-N}{p}}\|u\|^p_{L^p_\beta} \|u\|_{s, p}^{q-p} \right).
\end{equation}Maximizing the auxiliary function 
$$g(\varepsilon):= C_1\varepsilon^{e_1}+C_2\varepsilon^{-e_2},$$with
$$C_1=C\|u\|^p_{s, p}, \, C_2=C\|u\|^p_{L^p_\beta} \|u\|_{s, p}^{q-p}$$and
\begin{equation}\label{exponents e}
e_1=\alpha-c, \quad -e_2=\alpha-\beta +(q-p)\frac{1-N}{p},
\end{equation}
we finally get \eqref{ineq with eta} with
$$\eta=\dfrac{pe_2+ (q-p)e_1}{e_1+e_2} \quad \text{and}\quad \omega = \dfrac{pe_1}{e_1+e_2}.$$
Observe that $\eta$ is positive since by \eqref{cond exponents},
$$
\eta= \frac{p(\beta-\alpha)+(q-p)(N-1)+(q-p)(\alpha -c)}{e_1+e_2}>\dfrac{(q-p)(\alpha -c)}{e_1+e_2}>0.
$$ 
This concludes the proof.
\end{proof}

\begin{theorem} \label{compact}
Let $s\in (0,1]$ such that $1/p<s<N/p$, $\alpha>-sp $ and $p<q<\frac{p(N+\alpha)}{N-sp}$. Moreover, assume that
\begin{equation}\label{cond exponents 2}
\alpha-\beta +(q-p)\left(\dfrac{1-N}{p} \right)<0. 
\end{equation}
Then, the following embedding is compact
$$W^{s,p}_{rad, \beta}(\mathbb{R}^N) \subset L^q_\alpha(\mathbb{R}^N).
$$

\begin{equation}\label{estimate w k}
\begin{split}
\frac{1}{p}\|w_{k+1}\|_{s, p, \beta} &\leq C(p, \gamma)\bigg(\gamma\int_{\mathbb{R}^N}|\nabla w_{k+1}|^{p-2}\nabla w_{k+1}\cdot \nabla w_{k+1}\,dx \\ &+(1-\gamma)\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}\dfrac{|w_{k+1}(x)-w_{k+1}(y)|^{p-2}(w_{k+1}(x)-w_{k+1}(y))(w_{k+1}(x)-w_{k+1}(y))}{|x-y|^{N+sp}}\,dx\,dy \bigg)\\& + \int_{\mathbb{R}^N}|x|^{\beta}|w_{k+1}|^{p-1}w_{k+1}\,dx \\ & \leq C(p, \gamma)\bigg(\gamma\int_{\mathbb{R}^N}|\nabla u|^{p-2}\nabla u\cdot \nabla w_{k+1}\,dx\\& +(1-\gamma)\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}\dfrac{|u(x)-u(y)|^{p-2}(u(x)-u(y))(w_{k+1}(x)-w_{k+1}(y))}{|x-y|^{N+sp}}\,dx\,dy \bigg)\\& + \int_{\mathbb{R}^N}|x|^{\beta}|u|^{p-1}w_{k+1}\,dx \\ & = C(p, \gamma)\int_{\mathbb{R}^N}|x|^{\alpha}|u|^{q-1}w_{k+1}\,dx,
\end{split}
\end{equation}where we have used the fact that
$$|v_+(x)-v_+(y)|^p \leq (v(x)-v(y))(v_+(x)-v_+(y))|v_+(x)-v_+(y)|^{p-2}$$and also that $u$ is a solution of \eqref{eq}. Now, by \eqref{property w}, we get
\begin{equation}\label{estimate w k 2}
\int_{\mathbb{R}^N}|x|^{\alpha}|u|^{q-1}w_{k+1}\,dx \leq \int_{\mathbb{R}^N}|x|^{\alpha}|(2^{k+1}-1)w_k|^{q-1}(2^{k+1}-1)w_k\,dx=C_{k+1} \int_{\mathbb{R}^N}|x|^\alpha |w_{k}|^q\,dx,
\end{equation}with $C_{k+1}=(2^{k+1}-1)^q$. By Lemma \ref{continuity} applied to $w_{k+1}\in \mathcal{W}^{s,p}_\beta(\mathbb{R}^N)$ (recall also the notation \eqref{exponents e}) and by \eqref{estimate w k} and \eqref{estimate w k 2},
\begin{equation}
\begin{split}
\int_{\mathbb{R}^N}|x|^\alpha |w_{k+1}|^q\,dx \leq C\|w_{k+1}\|_{s, p, \beta}^{\frac{pe_2+qe_1}{e_1+e_2}}\leq C_{k+1}\left(\int_{\mathbb{R}^N}|x|^\alpha |w_{k}|^q\,dx \right)^{\frac{pe_2+qe_1}{pe_1+pe_2}}= C_{k+1}\left(\int_{\mathbb{R}^N}|x|^\alpha |w_{k}|^q\,dx \right)^{1+\delta}
\end{split}
\end{equation}for some $\delta>0$ since $q>p$. Therefore, by the numerical lemma \cite[Lemma 13]{FSV}, we obtain that there is $\varepsilon\in (0, 1)$ such that if
 \begin{equation}\label{assumption with eps}
 \int_{\mathbb{R}^N}|x|^\alpha |w_{0}|^q\,dx <\varepsilon
 \end{equation}then
 $$\lim_{k\to \infty}\int_{\mathbb{R}^N}|x|^\alpha |w_{k}|^q\,dx =0.$$Hence, \eqref{convergence to u} implies $\|u\|_{L^{\infty}(\mathbb{R}^N)}\leq 1$. Observe that 
 $$\int_{\mathbb{R}^N}|x|^\alpha |w_{0}|^q\,dx=\int_{\mathbb{R}^N} |x|^\alpha u_{+}^q\,dx$$so the result is valid under the assumption
 $$\int_{\mathbb{R}^N} u_{+}^q|x|^\alpha\,dx<\varepsilon.$$If now
 $\xi=\int_{\mathbb{R}^N} u_{+}^q|x|^\alpha\,dx>0$ is arbitrary, then we choose $C>1$ large enough so that
 \begin{equation}
\int_{\mathbb{R}^N} \left(\frac{u_{+}}{C}\right)^q|x|^\alpha\,dx<\varepsilon.
 \end{equation}Moreover, $u/C$ also satisfies \eqref{estimate w k} with an extra constant at the end. Hence, from the above argument 
 $$\|u/C\|_{L^{\infty}(\mathbb{R}^N)}\leq 1 \text{ or }\|u\|_{L^{\infty}(\mathbb{R}^N)}\leq C.$$This ends the proof of the theorem.
\end{proof}

