One of the landmark results in research on quasi-isometric rigidity is the complete quasi-isometry classification of lattices in semisimple Lie groups. A large body of work in the 1980s and 1990s by several people over many papers culminated in a general theorem on the rigidity of the class of lattices among all finitely generated groups (see \cite{farb} for a detailed survey). Informally, this theorem states that any group quasi-isometric to a lattice in a semisimple Lie group is almost a lattice in that Lie group. More precisely,

One of the major breakthroughs leading to this general classification was the work of Schwartz \cite{Schwartz} on non-uniform lattices in rank one semisimple Lie groups. These Lie groups agree, up to index 2, with the isometry groups of the negatively curved symmetric spaces: real, complex, quaternionic hyperbolic space, and the Cayley hyperbolic plane.

\begin{theorem}[Schwartz]\label{Schwartz-theorem}
 Let $X$ be a negatively curved symmetric space other than the real hyperbolic plane $\bH^2$. If $\Gamma$ is a finitely generated group quasi-isometric to a non-uniform lattice $\Lambda$ in $\Isom{X}$, then there exists a short exact sequence
 \[
 \begin{tikzcd}
 1 \ar[r] & F \ar[r] & \Gamma \ar[r] & \Lambda' \ar[r] & 1.
 \end{tikzcd}
 \]
 where $\Lambda' \le \Isom{X}$ is a non-uniform lattice commensurable to $\Lambda$, and $F$ is a finite group.
\end{theorem}

\begin{theorem}[Frigerio--Lafont--Sisto]\label{FLS}
 If $\Gamma$ is a finitely generated group quasi-isometric to $\pi_1(M) \times \bZ^d$, then there exist short exact sequences
 \begin{equation*}
 \begin{tikzcd}
 1 \ar[r] & \bZ^d \ar[r,"j"] & \Gamma' \ar[r] & \Delta \ar[r] & 1
 \end{tikzcd}
 \end{equation*}
 \begin{equation*}
 \begin{tikzcd}
 1 \ar[r] & F \ar[r] & \Delta \ar[r] & \pi_1(M') \ar[r] & 1
 \end{tikzcd}
 \end{equation*}
 where $\Gamma' \le \Gamma$ has finite index, $M'$ is a finite-sheeted covering of $M$, $\Delta$ is a group, and $F$ is a finite group. Moreover, $j(\bZ^d)$ is contained in the center of $\Gamma'$. In other words, $\Gamma$ is virtually a central extension by $\bZ^d$ of a finite extension of $\pi_1(M')$.
\end{theorem}

\begin{thmx}\label{Theorem A}
 Let $X \ne \bH^2$ be a negatively curved symmetric space. Let $\Lambda$ be a non-uniform lattice in $\textup{Isom}(X)$ and $L$ be a nilpotent lattice. If $\Gamma$ is a finitely generated group quasi-isometric to $\Lambda \times L$, then there exist short exact sequences
 \begin{equation}\label{virtually nilcentral extension}
 \begin{tikzcd}
 1 \ar[r] & L' \ar[r] & \Gamma' \ar[r] & \Delta \ar[r] & 1,
 \end{tikzcd}
 \end{equation}
 \begin{equation*}
 \begin{tikzcd}
 1 \ar[r] & F \ar[r] & \Delta \ar[r] & \Lambda' \ar[r] & 1.
 \end{tikzcd}
 \end{equation*}
 where $\Gamma' \le \Gamma$ and $\Lambda' \le \Lambda$ have finite index, $L'$ is a nilpotent lattice quasi-isometric to $L$, $\Delta$ is a group, and $F$ is a finite group.
\end{thmx}

\begin{theorem}
Let $X \ne \bH^2$ be a negatively curved symmetric space. Let $\Lambda$ be a non-uniform lattice in $\textup{Isom}(X)$ and $L$ be a nilpotent lattice. If $\Gamma$ is a finitely generated group quasi-isometric to $\Lambda \times L$, then there exist short exact sequences
 \begin{equation}
 \begin{tikzcd}
 1 \ar[r] & L' \ar[r] & \Gamma' \ar[r] & \Delta \ar[r] & 1,
 \tag{\ref{virtually nilcentral extension}}
 \end{tikzcd}
 \end{equation}
 \begin{equation*}
 \begin{tikzcd}
 1 \ar[r] & F \ar[r] & \Delta \ar[r] & \Lambda' \ar[r] & 1.
 \end{tikzcd}
 \end{equation*}
 where $\Gamma' \le \Gamma$ and $\Lambda' \le \Lambda$ have finite index, $L'$ is a nilpotent lattice quasi-isometric to $L$, $\Delta$ is a group, and $F$ is a finite group.
\end{theorem}

\begin{proof}
By Proposition \ref{kernel qi to N}, $\ker\theta$ is quasi-isometric to $N$, where $N$ is the simply connected nilpotent Lie group in which $L$ is a lattice. In particular $\ker\theta$ has polynomial growth. Then by Gromov's polynomial growth theorem, $\ker\theta$ is virtually nilpotent. So $\ker\theta$ has a finite-index, hence finitely generated, nilpotent subgroup $K$. Such groups are virtually torsion-free, so take a finite-index torsion-free subgroup $K' \le K$. Since $\ker\theta$ is finitely generated, it has only finitely many subgroups with the same index as $K'$. Let $L'$ denote their intersection. Then $L'$ is a finite-index characteristic subgroup of $\ker\theta$. Moreover, $L'$ is finitely generated, nilpotent, and torsion-free. A theorem of Malcev \cite{malcev} then says that $L'$ embeds as a lattice in a simply connected nilpotent Lie group $N'$, known as the (real) Malcev completion of $L'$ (see also \cite[Theorem 2.18]{raghunathan1972discrete}). Since $L'$ is characteristic in $\ker\theta$, it is normal in $\Gamma$. By construction, $\Gamma/L'$ is an extension of $\Lambda_\Gamma = \Gamma/\ker\theta$ by the finite group $F = \ker\theta/L'$. By Corollary \ref{commensurable}, $\Lambda_\Gamma$ is virtually a finite-index subgroup $\Lambda' \le \Lambda$ which is also a non-uniform lattice in $\text{Isom}(X)$. Let $\Gamma' = \theta^{-1}(\Lambda')$ and $\Delta = \Gamma'/L'$. Then we obtain the desired short exact sequences.

Now suppose we are in the situation of Theorem \ref{Theorem A} and we have the following two short exact sequences.
\begin{equation}\label{vne}
\begin{tikzcd}
 1 \ar[r] & N \ar[r] & \Gamma \ar[r] & \Delta \ar[r] & 1
\end{tikzcd}
\end{equation}
\begin{equation}\label{finite extension}
\begin{tikzcd}
 1 \ar[r] & F \ar[r] & \Delta \ar[r] & \Lambda \ar[r] & 1
\end{tikzcd}
\end{equation}
where $N$ is a nilpotent lattice (we are now using $N$ to denote the lattice, not the ambient Lie group), $F$ is finite, and $\Lambda$ is a non-uniform lattice in $\text{Isom}(X)$, where $X \ne \bH^2$ is a negatively curved symmetric space. Since $N$ is finitely generated, nilpotent, and torsion-free, $Z(N/Z_i) = Z_{i+1}/Z_i$ is a finitely generated free abelian group. That is, $Z(N/Z_i) = \bZ^{d_i}$ for some $d_i$, and so $\Sigma(N) = \max_i d_i$. We now focus on the situation when $X$ is quaternionic hyperbolic space or the Cayley hyperbolic plane, and $\text{Isom}(X)$ has sufficiently large dimension.

\begin{thmx}\label{Theorem A}
