\begin{abstract}
 In this paper, we prove that for an $n$-dimensional closed minimal Willmore hypersurface $M^n$ with constant scalar curvature in the unit sphere $\mathbb{S}^{n+1}$, the squared norm $S$ of the second fundamental form of $M^n$ satisfies $S\geqslant n+\frac{4n+9-\sqrt{4 n^{2}+60 n+81}}{2}$ if $S>n$. This proves, in the approximate sense, the Chern conjecture about the second gap ($S\geqslant 2n$ if $S>n$), which will be fully verified under a further inequality condition about the 4-th mean curvature. 
\end{abstract}

The classification of $S\equiv n$ in the Simons theorem was characterized by Chern-do Carmo-Kobayashi \cite{CDK} and Lawson \cite{Lawson} independently: The Clifford tori $\mathbb{S}^{k}\Big(\sqrt\frac{k}{n}\Big)\times \mathbb{S}^{n-k}\Big(\sqrt\frac{n-k}{n}\Big)$, $1\leqslant k\leqslant n-1$, are the only closed minimal hypersurfaces in $\mathbb{S}^{n+1}$ satisfying $S\equiv n$. Note that for minimal hypersurfaces in $\mathbb{S}^{n+1}$, the scalar curvature $R_{M}$ satisfies $S=n(n-1)-R_{M}$. Hence, the Simons theorem established the first gap of the original Chern conjecture. 
Furthermore, motivated by the fact that
the isoparametric hypersurfaces are the only known examples of minimal hypersurfaces with
constant scalar curvature in $\mathbb{S}^{n+1}$,
the original Chern conjecture has been reformulated into the following stronger version (cf. \cite{Verstraelen}).

Considering the stronger version of the Chern conjecture, a number of significant partial results have been established over the past decades. In 1993, building on the seminal works of Cartan, Simons, Chern-do Carmo-Kobayashi \cite{CDK}, and Peng-Terng \cite{Peng-T1}, Chang \cite{Chang} verified the stronger Chern conjecture in the case $n=3$. As a matter of fact, de Almeida and Brito \cite{A-B} proved that the stronger Chern conjecture holds for hypersurfaces $M^3 \subset \mathbb{S}^4$ with constant mean curvature and nonnegative constant scalar curvature. As emphasized in \cite{Scherfner-Weiss-Yau-2012}, the method developed in \cite{A-B} has since become a fundamental conceptual framework for a large body of subsequent research in this direction.
Recently, an important development was achieved by Tang-Wei-Yan \cite{T-W-Y} and Tang-Yan \cite{T-Y}, who completely generalized this result of \cite{A-B} to arbitrary dimensions. For further background, developments, and related results on the Chern conjecture, we refer the reader to the surveys \cite{Cheng-Wei, GQTY, GT, Scherfner-Weiss-Yau-2012}.

\begin{rem}
 Notice that $T(n)$ reflects the approximation accuracy relative to $2n$. Besides, we also see that
 \[
 n+\frac{4n+9-\sqrt{4 n^{2}+60 n+81}}{2}>1.8252n-0.712898.
 \]
 Specifically, we compare the lower bounds of $S$ given by Theorem \ref{main} and \cite[Theorem 1.2]{2} for several values of $n$:
 \begin{table}[H]\centering
 \begin{tabular}{cccccccc}
 \hline
 $n$ & $5$ & $10$ & $25$ & $50$ & $100$ & $1000$ & $10000$ \\
 \Xhline{1pt}
 \textup{Theorem \ref{main}} & $8.534$ & $18.060$ & $47.558$ & $97.313$ & $197.167$ & $1997.017$ & $19997.001$ \\
 \textup{Theorem (\cite{2})} & $8.413$ & $17.539$ & $44.917$ & $90.547$ & $181.807$ & $1824.487$ & $18251.287$ \\
 \hline
 \end{tabular}
 \end{table}
\end{rem}

\begin{thm}\label{f4}
 Let $M^n$ be an n-dimensional closed minimal Willmore hypersurface in $\mathbb{S}^{n+1}$ with constant scalar curvature. Suppose that $S>n$ and one of the following conditions are satisfied: $(1)~ f_{4}\geqslant3S$, $(2)~ f_{4}\geqslant\dfrac{3S^2}{2n}$. Then $S\geqslant2n$.
\end{thm}

Set
\[
 t=\frac{S-n}{S},
\]
so that $0 < t < 1$.
\begin{lem}\label{ab}
Let $M^{n}$ be a closed minimal Willmore hypersurface of $\mathbb{S}^{n+1}$ with constant scalar curvature. 
Then there exists a point $x_{0}\in M^{n}$ at which \begin{equation}\label{AandB}
 \begin{aligned}
 A &= \left(\frac{2}{5}t + \frac{1}{5}\right) S f
 + \frac{3tS^{2}}{5(1-t)},\\
 B &= \left(\frac{1}{5}t - \frac{2}{5}\right) S f
 - \frac{tS^{2}}{5(1-t)}.
 \end{aligned}
\end{equation}
\end{lem}

\begin{lem}\label{imp}
 Let $M^{n}$ be a closed minimal Willmore hypersurface of $\mathbb{S}^{n+1}$ with constant scalar curvature. 
 Then at the point $x_{0}$ in Lemma~\ref{ab}, the inequality
 \begin{equation}\label{equ-f-upper}
 f \leqslant 
 \frac{t S}{(1-t)(3-4t)}
 \end{equation}
 holds for $0<t<\dfrac{3}{4}$.
\end{lem}

Using the notation $t=\dfrac{S-n}{S}$, Yang and Cheng (\cite{1}) proved that if $f_{3}$ is constant, then 
\[
 \sum_{i,j,k,l}u_{ijkl}^2
 \geqslant 
 \frac{1}{2Sf}\left(Sf-2A+tf_{3}^2+\frac{2tS^2}{1-t}\right)^2
 +\frac{1}{S^2}\left(\sum_{i,j,k}\lambda_{i}h_{ijk}^2\right)^2
 +\frac{t^2 S^2}{2(1-t)}.
\]
Since $f_{3}=0$ for a minimal Willmore hypersurface, combining \eqref{C0-used}, this simplifies to
\begin{equation}\label{key-f3zero}
 \sum_{i,j,k,l}u_{ijkl}^2
 \geqslant 
 \frac{1}{2Sf}\left(Sf-2A+\frac{2tS^2}{1-t}\right)^2
 +\frac{t^2 S^2}{2(1-t)}.
\end{equation}

\begin{thm}\label{main}
    Let $M^n$ $(n\geqslant5)$ be an n-dimensional closed minimal Willmore hypersurface in $\mathbb{S}^{n+1}$ with constant scalar curvature. If $S>n$, then
    \[
        S\geqslant n+\frac{4n+9-\sqrt{4 n^{2}+60 n+81}}{2}=2n-T(n),
    \]
    where
    \[
        T(n) =
        \frac{\sqrt{4 n^{2}+60 n+81} - 2n - 9}{2}
        = 3-\frac{18}{n}+\frac{135}{n^{2}}-\frac{2349}{2n^{3}}+\frac{44955}{4n^{4}}+O\left(\frac{1}{n^{5}}\right).
    \]
\end{thm}

