\begin{prop}\label{prop:Sabpf}
Let $f: Y\to X$ be a proper morphism of nonsingular varieties, such that $Y \to f(Y)$ is
a trim resolution. Then $f_* (T^*_Y Y)=T^*_{f(Y)} X$.
\end{prop}

