Notably, the H\"ormander condition
 \begin{align}\label{Hormander condition}
 \sup_{y\in\R^d,|v|>0} \int_{|x-y|\geq 2|v|} |K(x,y+v)-K(x,y)| {\rm d} x < \infty,
 \end{align}
 which is weaker than (\ref{Lipschitz regularity condition}), is already sufficient for weak type $(1,1)$ boundedness in classical Calder\'on-Zygmund theory.
It is therefore natural to ask whether the noncommutative weak type $(1,1)$ boundedness still holds under the H\"ormander condition (\ref{Hormander condition})?
This question remains open.

A step forward was made in 2022 by Cadilhac et al. \cite{Cadilhac2022Spectral}.
They developed a more effective noncommutative Calder\'on-Zygmund decomposition without the off-diagonal term of the good function, which allowed them to prove the noncommutative weak type $(1,1)$ estimates for Calder\'on-Zygmund operators if the kernel $K$ satisfies
 \begin{align} \label{L2-integral regularity condition}
 \sum_{m\geq 1} \sup_{{\begin{subarray}{c} y\in Q \\ Q\ \text{dyadic} \end{subarray}}} \Big( 2^{md}\ell(Q)^d \int_{2^m\ell(Q)\leq|x-c(Q)|\leq2^{m+1}\ell(Q)} |K(x,y)-K(x,c(Q))|^2 {\rm d} x \Big)^{\frac{1}{2}}
 <\infty,
 \end{align}
 where $\ell(Q)$ and $c(Q)$ stand for the length and the center of the dyadic cube $Q$, respectively.
 More generally, for $1\leq q\leq\infty$, we say that a kernel $K$ satisfies the $L_q$-integral regularity condition if
 \begin{align} \label{sum delta < infty}
 \sum_{m\geq 1} \delta_q(m) <\infty,
 \end{align}
where $\delta_q(m)$ is defined as
 \begin{align*}
 \sup_{{\begin{subarray}{c} y\in \R^d,\ R>0 \\ |v|<R \end{subarray}}} & \Big( (2^m R)^{d(q-1)} \int_{2^mR\leq |x-y|\leq 2^{m+1}R} |K(x,y+v)-K(x,y)|^q {\rm d} x\Big)^{\frac{1}{q}},
 \end{align*}
for $m\geq 1$.
Roughly speaking, the H\"ormander condition (\ref{Hormander condition}) corresponds to the $L_1$-integral regularity condition i.e. (\ref{sum delta < infty}) with $q=1$, while \eqref{L2-integral regularity condition} corresponds to the $L_2$-integral regularity condition, i.e., (\ref{sum delta < infty}) with $q=2$.
The fact $\delta_1(m)\lesssim_d \delta_2(m)$ shows that the $L_2$-integral regularity condition is stronger than the H\"ormander condition (\ref{Hormander condition}), but weaker than the Lipschitz regularity condition (\ref{Lipschitz regularity condition}).
By applying the noncommutative Calder\'on-Zygmund decomposition in \cite{Cadilhac2022Spectral}, Hong, the first author, and Xu \cite{hong2023maximal} established the weak type (1,1) boundedness for the noncommutative maximal truncated Calder\'on-Zygmund operators under the $L_2$-integral regularity condition.
We refer the reader to \cite{Cadilhac2022Spectral, Lai2024Noncommutative, Mei2009Pseudo-localization} for more results on weak (1,1) boundedness theory for noncommutative Calder\'on-Zygmund operators.

In this paper, we study a kernel smoothness condition that is slightly weaker than the $L_q$-integral regularity condition (\ref{sum delta < infty}): the $L_q$-mean H\"ormander condition ($1\leq q\leq\infty$), defined by
 \begin{align} \label{Hq < infty}
 \sum_{m\geq 1} H_q (m) < \infty,
 \end{align}
where $H_q(m)$ is defined as
 \begin{align*} \sup_{{\begin{subarray}{} y\in \R^d, \\ R>0 \end{subarray}}} & \Big(\frac{(2^m R)^{d(q-1)}}{|B_R|} \int_{|v|\leq R}\int_{2^mR\leq |x-y|\leq 2^{m+1}R} |K(x,y+v)-K(x,y)|^q {\rm d} x {\rm d} v\Big)^{\frac{1}{q}}, \end{align*}
for $m\geq 1$.
Here, $B_R$ denotes the ball centered at the origin with radius $R>0$, and $|B_R|$ denotes its volume.
It is not hard to see that $H_q(m) \lesssim_d \delta_q(m)$, meaning the $L_q$-mean H\"ormander condition (\ref{Hq < infty}) is indeed weaker than the $L_q$-integral regularity condition (\ref{sum delta < infty}).
In what follows, we focus on the case $q=2$, i.e., the $L_2$-mean H\"ormander condition:
 \begin{align}\label{L2 mean Hormander condition}
 \sum_{m\geq 1} H_2 (m) < \infty,
 \end{align}
where $H_2(m)$ is defined as in (\ref{Hq < infty}) with $q=2$.

Before stating the main result, we introduce some notions.
Let $\mM$ be a von Neumann algebra equipped with a normal semifinite faithful ($n. s. f. $, for short) trace $\tau$.
Let $\mN = L_{\infty}(\R^d)\bar\otimes \mM$ be the tensor von Neumann algebra with the tensor trace $\phi = \int\otimes \tau$.
Denote the noncommutative $L_p$ space associated with $(\mN, \phi)$ by $L_p(\mN)$ for $1\leq p\leq\infty$ (see Appendix \ref{Appendix: Noncommutative Lp spaces and maximal norms} for details).
The noncommutative Calder\'on-Zygmund operator $T$ with a kernel $K$ is defined as
 \begin{align}\label{def of Tf}
 T f(x) = \int_{\R^d} K(x,y) f(y) {\rm d} y, \quad x\notin \overrightarrow{\operatorname{supp}}\ f,
 \end{align}
where $f\in L_1(\mN)\bigcap L_{\infty}(\mN)$ is compactly supported and measurable.
Here, $\overrightarrow{\text{supp}}\ f$ denotes the support of $f$ as an operator-valued function in $\R^d$ rather than the support projection as an element in a von Neumann algebra.
For any $\epsilon>0$, the associated truncated singular integral $T_{\epsilon}f$ is defined as
 \begin{align}\label{def of T epsilon f}
 T_{\epsilon}f(x) = \int_{|x-y|>\epsilon} K(x,y) f(y) {\rm d} y.
 \end{align}

The main result
is stated as follows.

\textbf{Step 1.}
Let $T_{\epsilon}$ be a noncommutative Calder\'on-Zygmund truncated operator with a complex kernel $K$ (defined as in (\ref{def of T epsilon f})).
We decompose $K$ into its real and imaginary parts: $\Re(K)$ and $\Im(K)$.
The truncated operators associated with $\Re(K)$ and $\Im(K)$ are then given by
 \begin{align*}
 \Re(T_{\epsilon})f(x) = \int_{|x-y|>\epsilon} \Re(K)(x,y) f(y) \dif y
 \end{align*}
and
 \begin{align*}
 \Im(T_{\epsilon})f(x) = \int_{|x-y|>\epsilon} \Im(K)(x,y) f(y) \dif y.
 \end{align*}
\begin{lemma}\label{reduction to real kernel}
 Let $T$ be a noncommutative Calder\'on-Zygmund operator (defined as in (\ref{def of Tf})) whose kernel $K$ satisfies (\ref{Size condition}) and the $L_2$-mean H\"ormander condition (\ref{L2 mean Hormander condition}).
 Let $T_{\epsilon}$ be defined as in (\ref{def of T epsilon f}).
 Then,
 \begin{enumerate}[(i)]
 \item Both $\Re(K)$ and $\Im(K)$ satisfy (\ref{Size condition}) and (\ref{L2 mean Hormander condition}).
 \item If $(T_{\epsilon})_{\epsilon>0}$ is of strong type $(p_0,p_0)$ for some $p_0\in (1,\infty)$, then, both $(\Re(T_{\epsilon}))_{\epsilon>0}$ and $(\Im(T_{\epsilon}))_{\epsilon>0}$ are of strong type $(p_0,p_0)$.
 \item If $(\Re(T_{\epsilon}))_{\epsilon>0}$ and $(\Im(T_{\epsilon}))_{\epsilon>0}$ are of weak type $(1,1)$, so is $(T_{\epsilon})_{\epsilon>0}$.
 \end{enumerate}
\end{lemma}
By this lemma, we may assume that the kernel $K$ is real throughout this paper.

\begin{lemma}\label{reduction to lacunary sequence}
 Let $T$ be a noncommutative Calder\'on-Zygmund operator (defined as in (\ref{def of Tf})) whose kernel $K$ satisfies (\ref{Size condition}) and the $L_2$-mean H\"ormander condition (\ref{L2 mean Hormander condition}).
 Let $T_{\epsilon}^{i_{\epsilon}}$ be defined as in (\ref{T epsilon,i epsilon f(x)}).
 Then
 \begin{enumerate}[(i)]
 \item $(T_{\epsilon}^{i_{\epsilon}})_{\epsilon>0}$ is of strong type $(p,p)$ for $1<p\leq\infty$.
 \item $(T_{\epsilon}^{i_{\epsilon}})_{\epsilon>0}$ is of weak type $(1,1)$.
 \end{enumerate}
 \end{lemma}

The preceding two lemmas imply that Theorem \ref{Main theorem} follows directly from the weak type (1,1) boundedness of $S_i$ given in (\ref{Sif(x)}).
Thus, it remains to prove
\begin{theorem}\label{Second theorem}
 Let $T$ be a noncommutative Calder\'on-Zygmund operator defined as in (\ref{def of Tf}) with the real kernel $K$ satisfying (\ref{Size condition}) and the $L_2$-mean H\"ormander condition (\ref{L2 mean Hormander condition}).
 Let $S_i$ be defined as in (\ref{Sif(x)}).
 Then, the sequence of operators $(S_i)_{i\in\Z}$ is of weak type $(1,1)$, that is, for any $f\in L_1(\mN)$,
 \[
 \norm{(S_i f)_{i\in\Z}}_{\Lambda_{1,\infty}(\mN;\ell_{\infty})} \lesssim \norm{f}_{L_1(\mN)}.
 \]
 More precisely, for any $f\in L_1(\mN)$ and $\lambda>0$, there exists a projection $e\in\mN$ such that
 \[
 \sup_{i\in\Z}\norm{e S_if e}_{L_{\infty(\mN)}} \leq \lambda \quad\text{and}\quad \phi(e^{\bot})\lesssim \lambda^{-1} \norm{f}_{L_1(\mN)} .
 \]
\end{theorem}

\subsection{Estimate for the good function (\ref{estimate of good function}) }
For any $i\in\Z$, it follows from the definitions of $S_i$ and $T_{\epsilon}^{i_{\epsilon}}$ ((\ref{Sif(x)}) and (\ref{T epsilon,i epsilon f(x)})) that there exists $\epsilon_i > 0$ such that
 \[ S_i = S_{\epsilon_i}- T_{\epsilon_i}^i. \]
Under the assumptions of Theorem \ref{Main theorem} and Lemma \ref{reduction to lacunary sequence} $(i)$, both $(S_{\epsilon_i})_{i \in \mathbb{Z}}$ and $(T_{\epsilon_i}^i)_{i \in \mathbb{Z}}$ are of strong type $(p_0, p_0)$.
Therefore, from the above equality, $(S_i)_{i \in \mathbb{Z}}$ is also of strong type $(p_0, p_0)$.
In addition, since $g$ is positive (by Theorem \ref{nc CZ decomposition with convolution}) and the kernel $K$ is real-valued (as stated in Section \ref{Section: Two reductions}), the operator $S_i g$ is self-adjoint.
These two facts imply that for any $i\in\Z$, we can find a positive element $a\in\mN$ such that for any $i\in\Z$,
 \[
 -a \leq S_i g \leq a \quad\text{and}\quad \norm{a}_{L_{p_0}(\mN)}\lesssim \norm{g}_{L_{p_0}(\mN)}.
 \]
Taking $e_1 = \chi_{(0,\lambda]}(a)$. Then we have
 \[
 -\lambda \leq -e_1 a e_1 \leq e_1 S_i g e_1 \leq e_1 a e _1 \leq \lambda.
 \]
Finally, applying the Chebyshev inequality, the H\"older inequality, along with the boundedness of $g$ in Lemma \ref{properties of nc CZ decomposition with convolution} $(i)$, we obtain
 \begin{align*}
 \phi(e_1^{\bot})
 \leq \lambda^{-p_0} \norm{a}_{L_{p_0}(\mN)}^{p_0}
 \leq \lambda^{-p_0} \norm{g}_{L_{\infty}(\mN)}^{p_0-1} \norm{g}_{L_1(\mN)}
 \lesssim \lambda^{-1} \norm{f}_{L_1(\mN)},
 \end{align*}
which yields (\ref{estimate of good function}).

To estimate $F_1$.
We first observe that by the supports of $h_{r_{n-j}}$ and $\chi_Q$, the noncommutative $L_1$-norm in $F_1$ equals
 \begin{align*} \Big\|\int_Q \Big(\int_{|u-y|\leq r_{n-j}} (K_j(x,y)-K_j(x,c(Q))) h_{r_{n-j}}(y-u)\dif y \Big)p_Q f(u) q_Q\dif u \Big\|_{L_1(\mM)}.
 \end{align*}
By using Lemma \ref{a useful lemma for bad function} (in Appendix \ref{Appendix: Noncommutative Lp spaces and maximal norms}), the above estimate is bounded by a product
 \begin{align*}
 & \Big\| \Big(\int_{Q} \Big(\int_{B_{r_{n-j}}(u)} \abso{K_i(x,y)-K_i(x,c(Q))} |h_{r_{n-j}}(y-u)|\dif y \Big)^2 p_Q f(u)p_Q \dif u\Big)^{^{\frac{1}{2}}}\Big\|_{L_{1}(\mM)} \\
 & \cdot \Big\|\Big(\int_{Q} q_Q f(u) q_Q \dif u\Big)^{\frac{1}{2}} \Big\|_{L_{\infty}(\mM)}.
 \end{align*}
For the second term, an application of \eqref{q_Q f_Q q_Q < lambda q_Q} shows that
 \begin{align*} \Big\|\Big(\int_{Q} q_Q f(u) q_Q \dif u\Big)^{\frac{1}{2}} \Big\|_{L_{\infty}(\mM)} \lesssim (|Q|\lambda)^{\frac{1}{2}}.
 \end{align*}
Hence,
 \begin{align}
 F_1
 \lesssim &\sum_{n\geq 2} \sum_{j\leq n-1} \sum_{Q\in\mQ_{n-j}} (|Q|\lambda)^{\frac{1}{2}} \notag\\
 & \label{xxxyyy}\frac{1}{|B_{r_{n-j}}|}\int_{\R^d} \Big\|\int_{Q} \Big(\int_{B_{r_{n-j}}(u)} \abso{K_i(x,y)-K_i(x,c(Q))} \dif y \Big)^2 p_Q f(u)p_Q \dif u\Big\|_{L_{\frac{1}{2}}(\mM)}^{\frac{1}{2}} \dif x.
 \end{align}
The same argument as in (\ref{B(c(Q))}) allows us to majorize (\ref{xxxyyy}) by
 \begin{align*}
 \frac{1}{|B_{r_{n-j-1}}|}\int_{\R^d} \Big\|\int_{Q} \Big(\int_{B_{r_{n-j-1}}(c(Q))} \abso{K_j(x,y)-K_j(x,c(Q))} \dif y \Big)^2 p_Q f(u)p_Q \dif u\Big\|_{L_{\frac{1}{2}}(\mM)}^{\frac{1}{2}} \dif x.
 \end{align*}
By Lemma \ref{the second lemma for bad function} $(i)$ and the $L_2$-mean H\"ormander condition \eqref{L2 mean Hormander condition}, we obtain
 \begin{align*}
 F_1 &\lesssim \sum_{n\geq 2} \sum_{j\leq n-1} \sum_{Q\in\mQ_{n-j}}
 \lbracket{ \big(H_2^2(n-1) + H_2^2(n) + 2^{-2(n-1)}\big) \tau(p_Q) \phi(fp_Q \chi_{Q}) }^{\frac{1}{2}} (|Q| \lambda)^{\frac{1}{2}} \\
 &\lesssim \sum_{n\geq 2} \lbracket{2H_2(n-1)+2^{-n+1}} \sum_{j\leq n-1} \sum_{Q\in\mQ_{n-j}}\big(\tau(p_Q) \phi(fp_Q \chi_{Q}) |Q| \lambda \big)^{\frac{1}{2}} \\
 &\lesssim \sum_{m\geq 1} \sum_{Q\in\mQ_m} \big( \tau(p_Q) \phi(fp_Q \chi_{Q}) |Q| \lambda \big)^{\frac{1}{2}}.
 \end{align*}
Finally, applying the Cauchy-Schwarz inequality twice, we estimate $F_1$ as follows:
 \begin{align*}
 F_1 \lesssim \Big(\sum_{m=1}^{\infty} \lambda \phi(p_m)\Big)^{\frac{1}{2}}
 \Big(\sum_{m=1}^{\infty} \phi(f p_m)\Big)^{\frac{1}{2}}
 = \big(\lambda \phi(1-q)\big)^{\frac{1}{2}} \big(\phi(f(1-q))\big)^{\frac{1}{2}}
 &\lesssim \norm{f}_{L_1(\mN)}.
 \end{align*}

