			\partial_{t}w_{k}+\mathcal{L}_{k}w_{k}
			+\frac{\big[ik\sum_{l\in\mathbb{Z}}\partial_{r}(r^{-\frac12}\varphi_{l})w_{k-l}-r^{\frac12}\partial_{r}\big(\sum_{l\in\mathbb{Z}}ilr^{-1}\varphi_{l}w_{k-l} \big) \big]}{Ar}=-\frac{ik}{Ar}n_{k},\\
			\big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \big)\varphi_{k}=w_{k},\\
			n_{k}|_{r=1,R}=c_{k}|_{r=1,R}=w_{k}|_{r=1,R}=\varphi_{k}|_{r=1,R}=0.
