 \partial_tn+v\cdot\nabla n=\Delta n-\nabla\cdot(n\nabla c), \\
 \Delta c+n-c=0, \\
 \partial_tv+ v\cdot\nabla v+\nabla P=\Delta v+n\nabla\Phi,\quad\nabla\cdot v=0, \\
 (n,v)\big|_{t=0}=(n_{\rm in},v_{\rm in}),
 \end{array}
 \right.
 \end{equation}
 where $(x,y)\in\mathcal{D}$ and $\mathcal{D}\subset\mathbb{R}^2$ is an annular region.
 Here, $n$ is the cell density, $c$ denotes the concentration of chemoattractant, and $v$ denotes the velocity of fluid. In addition, $P$ is the pressure and $\Phi$ represents the given potential function. Assume that $\Phi=\sqrt{x^2+y^2}$ for simplicity.

It is a more realistic scenario that chemotactic processes take place in a moving fluid.
 As said in \cite{KX2015}:
 ``{\it A natural question is whether the presence of fluid flow
can affect singularity formation by mixing the bacteria thus making concentration
harder to achieve.}" 
 Kiselev-Xu \cite{KX2015} demonstrated this for stationary relaxation
 enhancing flows and time-dependent Yao-Zlatos near-optimal mixing flows in $\mathbb{T}^d~(d=2,3)$; Bedrossian-He \cite{Bedro2} for non-degenerate shear flows in $\mathbb{T}^2$; and He \cite{he0} for monotone shear flows in $\mathbb{T}\times\mathbb{R}$. For the fully coupled Patlak-Keller-Segel-Navier-Stokes (PKS-NS) system, global regularity for strong Couette flow was proven by Zeng-Zhang-Zi \cite{zeng} in $\mathbb{T}\times\mathbb{R}$. Furthermore, Li-Xiang-Xu \cite{Li0} utilized Poiseuille flow, while Cui-Wang \cite{cui1} considered Navier-slip boundary conditions in $\mathbb{T}\times \mathbb{I}$. Recently, Chen-Wang-Yang investigated the suppression of blow-up in solutions to the Patlak-Keller-Segel (-Navier-Stokes) system by a large Couette flow and established a precise relationship between the amplitude of the Couette flow and the initial data \cite{CWY2025}.
 More references on higher dimensional cases or other methods to suppress blow-up, we refer to \cite{TW2016, Hu0, Hu1, he24-1,he24-2,CWW1,CWWT3,CWWTIT} and the references therein.

In the plane coordinate, to deal with the pressure $P$, it is common to introduce the vorticity $\omega$ and the stream function $\phi$ satisfying
 $\omega=\partial_{x}v_{2}-\partial_{y}v_{1}$ and $v=(-\partial_{y}\phi, \partial_{x}\phi)^T$.
 When considering the radial vorticity $\omega(x,y)=\omega(r)$ and stream function $\phi(x,y)=\phi(r)$ with $r=\sqrt{x^{2}+y^{2}}$, the vorticity and the velocity field are reduced to
 \begin{equation}\label{radial}
 \left\{
 \begin{array}{lr}
 \omega(x,y)=\omega(r)=\Delta\phi=\phi''(r)+\frac{1}{r}\phi'(r), \\
 v(x,y)=\left(
 \begin{array}{c}
 -\partial_{y}\phi\\
 \partial_{x}\phi\\
 \end{array}
 \right)=\left(
 \begin{array}{c}
 -\sin\theta\\
 \cos\theta\\
 \end{array}
 \right)\phi'(r).
 \end{array}
 \right.
 \end{equation}
 When vorticity $\omega=const$, 
 the stream function $\phi$ defined by $(\ref{radial})_{1}$ indicates
 \begin{equation}\label{eq:phi}
 \phi''(r)+\frac{1}{r}\phi'(r)=const.
 \end{equation}
 In the polar coordinate, the functions $v(x,y)$ and $\omega(x,y)$ are denoted as $U(r, \theta)$ and $\Omega(r)$, respectively. Solving (\ref{eq:phi}) yields their expressions
 \begin{equation}\label{TC flow}
 U(r,\theta)=
 \left(
 \begin{array}{c}
 U_{1}\\
 U_{2}\\
 \end{array}
 \right)=\left(
 \begin{array}{c}
 -\sin\theta\\
 \cos\theta\\
 \end{array}
 \right)\left(Ar+\frac{B}{r}\right),\quad \Omega(r)=2A,
 \end{equation}
 where $A, B$ are constants and spatial variables $(r,\theta)$ belong to a domain $\mathcal{D}=[1,R]\times\mathbb{S}^{1}$. 
 The velocity field $U(r,\theta)$ given in (\ref{TC flow}) is called as Taylor-Couette (TC) flow,
 which is a steady-state solution of 2D incompressible NS equations. In the meanwhile, $\{n,c,v\}=\{0,0,U(r,\theta)\}$ is also a steady-state solution of the PKS-NS system (\ref{ini}).

Next, we focus on 
 the blow-up suppression for the PKS-NS system via Taylor-Couette flow in an annulus. 
 Introduce a perturbation around the two-dimensional TC flow $U(r,\theta)$ from (\ref{TC flow}) for the case $A=B$. Setting $w=\omega-\Omega, u=v-U$, with $\varphi$ being the stream function satisfying $\Delta\varphi=w$ and $u=(-\partial_{y}\varphi, \partial_{x}\varphi)$. After the time rescaling $t\mapsto\frac{t}{A}$, we rewrite the system (\ref{ini}) in polar coordinates:
 \begin{equation}\label{ini1}
 \left\{
 \begin{array}{lr}
 \partial_{t}n-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})n+(1+\frac{1}{r^{2}})\partial_{\theta}n+\frac{1}{Ar}(\partial_{r}\varphi\partial_{\theta}n-\partial_{\theta}\varphi\partial_{r}n)\\\qquad\qquad\qquad\qquad\qquad\qquad
 =-\frac{1}{Ar}\partial_{r}(rn\partial_{r}c)-\frac{1}{Ar^{2}}\partial_{\theta}(n\partial_{\theta}c), \\
 (\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})c+n-c=0,\\
 \partial_{t}w-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})w+(1+\frac{1}{r^{2}})\partial_{\theta}w+\frac{1}{Ar}(\partial_{r}\varphi\partial_{\theta}w-\partial_{\theta}\varphi\partial_{r}w)=-\frac{1}{Ar}\partial_{\theta}n, \\
 (\partial_{r}^{2}+\frac{1}{r}\partial_{r}+\frac{1}{r^{2}}\partial_{\theta}^{2})\varphi=w,
 \end{array}
 \right.
 \end{equation}
 together with the Dirichlet boundary conditions
 \begin{equation}\label{boundary condition}
 \begin{aligned}
 n|_{r=1,R}=0,\quad c|_{r=1,R}=0,\quad w|_{r=1,R}=0,\quad \varphi|_{r=1,R}=0
 \end{aligned}
 \end{equation}
 with $(r,\theta)\in\mathcal{D}=[1,R]\times\mathbb{S}^{1}$ and $t\geq 0$.

Our main result is stated as follows.

\section{The $L^{\infty}$ estimate of the density and proof of Proposition \ref{prop:n infty}}\label{estimate infty}
 \begin{proof}[Proof of Proposition \ref{prop:n infty}] Multiplying $(\ref{ini1})_{1}$ by $2pn^{2p-1}$ with $p=2^{j} ~(j\geq 1)$, and integrating by parts the resulting equation over $[1,R]\times\mathbb{S}^{1}$, one obtains
 \begin{align}
 &\frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}+\frac{2(2p-1)}{Ap}\Big\|\Big(\partial_{r}, \frac{1}{r}\partial_{\theta}\Big)n^{p}\Big\|_{L^{2}}^{2}\nonumber\\=&\frac{1}{A}\Big\|\frac{n^{p}}{r} \Big\|_{L^{2}}^{2}+\frac{1}{A}\int_{0}^{2\pi}\int_{1}^{R}\frac{1}{r^{2}}\partial_{\theta}\varphi n^{2p}dr d\theta+\frac{4p}{A}\int_{0}^{2\pi}\int_{1}^{R}\frac{1}{r}n^{p}c\partial_{r}n^{p}drd\theta\nonumber\\&-\frac{2p}{A}\int_{0}^{2\pi}\int_{1}^{R}\frac{1}{r^{2}}n^{2p}cdrd\theta+\frac{2(2p-1)}{A}\int_{0}^{2\pi}\int_{1}^{R}n^{p}\Big(\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)c\cdot\Big(\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)n^{p}drd\theta\nonumber\\\leq&\frac{1}{A}\left(1+\|\partial_{\theta}\varphi\|_{L^{\infty}L^{\infty}}+2p\|c\|_{L^{\infty}L^{\infty}} \right)\|n^{p}\|_{L^{2}}^{2}+\frac{4p}{A}\|n^{p}c\|_{L^{2}}\|\partial_{r}n^{p}\|_{L^{2}}\nonumber\\&+\frac{2(2p-1)}{A}\Big\|n^{p}\Big(\partial_{r},\frac{1}{r}\partial_{\theta}\Big)c\Big\|_{L^{2}}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta}\Big)n^{p} \Big\|\nonumber\\\leq&\frac{1}{A}\left(1+\|\partial_{\theta}\varphi\|_{L^{\infty}L^{\infty}}+2p\|c\|_{L^{\infty}L^{\infty}} \right)\|n^{p}\|_{L^{2}}^{2}+\frac{Cp^{2}}{A}\Big\|n^{p}\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c\Big\|_{L^{2}}^{2}\nonumber\\&+\frac{2p-1}{Ap}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}.\label{np 1}
 \end{align}
 Due to (\ref{assumption}), Lemma \ref{lem:varphi k>0} and $\varphi_{k}=r^{\frac12}{\rm e}^{ikt}\widehat{\varphi}_{k}$, there holds
 \begin{equation*}
 \begin{aligned}
 \|\partial_{\theta}\varphi\|_{L^{\infty}L^{\infty}}\leq&\sum_{k\neq 0, k\in\mathbb{Z}}|k|\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\widehat{\varphi}_{k}\|_{L^{\infty}L^{\infty}}\\\leq& R^{\frac12}\sum_{k\neq 0, k\in\mathbb{Z}}|k|\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}r^{-\frac12}\varphi_{k}\|_{L^{\infty}L^{\infty}}\\\leq &C(R)\sum_{k\neq 0, k\in\mathbb{Z}}|k|^{-\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}rw_{k}\|_{L^{\infty}L^{2}}\\\leq&C(R)\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}w_{k}\|_{L^{\infty}L^{2}}\leq C(R)\mathcal{Q}_{1}.
 \end{aligned}
 \end{equation*}
 Using (\ref{assumption}), Lemma \ref{lem:ck}, Lemma \ref{lem:c0} and Lemma \ref{lem:n0 w0}, we get
 \begin{equation*}
 \begin{aligned}
 \|c\|_{L^{\infty}L^{\infty}}\leq&\|\widehat{c}_{0}\|_{L^{\infty}L^{\infty}}+\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}c_{k}\|_{L^{\infty}L^{\infty}}\\\leq&C(R)\Big(\|r^{\frac12}\widehat{n}_{0}\|_{L^{\infty}L^{2}}+\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}n_{k}\|_{L^{\infty}L^{2}} \Big)\leq C(R)\left(D_{1}+\mathcal{Q}_{1} \right).
 \end{aligned}
 \end{equation*}
 Moreover, it follows from H$\ddot{\rm o}$lder's and Nash inequalities that
 \begin{equation*}
 \begin{aligned}
 \Big\|n^{p}\Big(1,\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{2}}^{2}\leq&\|n^{p}\|_{L^{4}}^{2}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{2}\\\leq& C\|n^{p}\|_{L^{2}}\|\nabla n^{p}\|_{L^{2}}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{2}.
 \end{aligned}
 \end{equation*}
 Substituting the above estimates into (\ref{np 1}), we arrive at
 \begin{align*}
 &\frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}+\frac{2(2p-1)}{Ap}\Big\|\Big(\partial_{r}, \frac{1}{r}\partial_{\theta} \Big)n^{p}\Big\|_{L^{2}}^{2}\\\leq&\frac{C(R)}{A}\Big(1+pD_{1}+p\mathcal{Q}_{1} \Big)\|n^{p}\|_{L^{2}}^{2}+\frac{Cp^{2}}{A}\|n^{p}\|_{L^{2}}\|\nabla n^{p}\|_{L^{2}}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^4}^{2}\\&+\frac{2p-1}{Ap}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}\\\leq&\frac{C(R)}{A}\Big(1+pD_{1}+p\mathcal{Q}_{1} \Big)\|n^{p}\|_{L^{2}}^{2}+\frac{Cp^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{4}\\&+\frac{5(2p-1)}{4Ap}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}.
 \end{align*}
 This implies that
 \begin{equation}\label{np 2}
 \begin{aligned}
 &\frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}+\frac{1}{2A}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{2}\\\leq&\frac{C(R)p^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big[\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{4}+\mathcal{Q}_{1}+D_{1}+1 \Big].
 \end{aligned}
 \end{equation}
 Using the Nash inequality again
 \begin{equation*}
 \|n^{p}\|_{L^{2}}\leq C(R)\|n^{p}\|_{L^{1}}^{\frac12}\Big\|\Big(\partial_{r},\frac{1}{r}\partial_{\theta} \Big)n^{p} \Big\|_{L^{2}}^{\frac12},
 \end{equation*}
 we infer from (\ref{np 2}) that
 \begin{equation}\label{np 3}
 \begin{aligned}
 \frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}\leq&-\frac{\|n^{p}\|_{L^{2}}^{4}}{2AC(R)\|n^{p}\|_{L^{1}}^{2}}+\frac{C(R)p^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big[\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{4}}^{4}+\mathcal{Q}_{1}+D_{1}+1 \Big]
 \end{aligned}
 \end{equation}
 Using (\ref{assumption}), Lemma \ref{lem:ck}, Lemma \ref{lem:c0}, Lemma \ref{lem:n0 w0} and Gagliardo-Nirenberg inequality, one obtains
 \begin{equation*}
 \begin{aligned}
 &\Big\|\Big(1,\partial_{r},\frac{1}{r}\partial_{\theta} \Big)c \Big\|_{L^{\infty}L^{4}}\leq\|(1,\partial_{r})\widehat{c}_{0}\|_{L^{\infty}L^{4}}+\sum_{k\neq 0, k\in\mathbb{Z}}\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(1,\partial_{r},\frac{|k|}{r} \Big)c_{k} \Big\|_{L^{\infty}L^{4}}\\\leq&C\|(1,\partial_{r})\widehat{c}_{0}\|_{L^{\infty}L^{2}}^{\frac34}\|(1,\partial_{r})\partial_{r}\widehat{c}_{0}\|_{L^{\infty}L^{2}}^{\frac14}\\+&C\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(\partial_{r},\frac{|k|}{r} \Big)c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\\+&C\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(\partial_{r},\frac{|k|}{r} \Big)c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\Big(\partial_{r}^{2}, \frac{1}{r}\partial_{r},\frac{|k|^{2}}{r^{2}} \Big)c_{k}\Big\|_{L^{2}} \Big)^{\frac12}\\\leq&C(R)\big(\|\widehat{n}_{0}\|_{L^{\infty}L^{2}}+\sum_{k\neq 0, k\in\mathbb{Z}}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}n_{k}\|_{L^{\infty}L^{2}}\big)\leq C(R)\left(D_{1}+\mathcal{Q}_{1} \right).
 \end{aligned}
 \end{equation*}
 This along with (\ref{np 3}) gives that
 \begin{equation}\label{np 4}
 \begin{aligned}
 \frac{d}{dt}\|n^{p}\|_{L^{2}}^{2}\leq-\frac{\|n^{p}\|_{L^{2}}^{4}}{2AC(R)\|n^{p}\|_{L^{1}}^{2}}+\frac{C(R)p^{4}}{A}\|n^{p}\|_{L^{2}}^{2}\Big(D_{1}^{4}+\mathcal{Q}_{1}^{4}+1 \Big).
 \end{aligned}
 \end{equation}

post_theorem_intro_text:
\begin{remark}
The Taylor-Couette flow has been successfully implemented in biomedical devices such as the  VFPR, where its unique vortex structure significantly enhances hemocompatibility. It reduces platelet activation and protein adsorption by promoting the accumulation of cellular components in the vortex center, thereby lowering the risk of thrombogenesis and improving the safety of extracorporeal circulation systems \cite{K2003, GG1999}. 
Increased platelet adhesion or protein adsorption on the device surface can induce platelet aggregation or thrombosis, which  poses a huge threat to human life. The above theorem shows  that sufficiently strong flow can prevent the aggregation or blow-up from occurring. As shown in \cite{K2003} at shear rates $ G\geq
	550 s^{-1}$, laminar flow resulted in a significantly higher platelet drop and PF4 release than Taylor vortex flow. Here $G$ is similar as $A$. In fact, let $w_1$ and $w_2$ denote the angular velocity of the
inner or outer cylinder, where  $w_1r_1=v_\theta|_{r_1}=A(r+\frac1r)|_{r_1}$ and $w_2r_2=v_\theta|_{r_2}=A(r+\frac1r)|_{r_2}$. Then
\begin{eqnarray*}
G=\frac{2(r_1^2w_1+r_2^2w_2)}{r_2^2-r_1^2},\end{eqnarray*}
which implies $G=2A\frac{3+R^2}{R^2-1}$ when $r_1=1, r_2=R.$ It is interesting to estimate the value of $A$ in mathematics, which will be investigated in our future work.
	\end{remark}

	\begin{remark}
		Compared with previous results on planar flows (e.g., Couette or Poiseuille flows) usually set in Cartesian coordinates, to our best knowledge, the above result gives the first rigorous proof of global regularity for the Patlak-Keller-Segel-Navier-Stokes system driven by a non-planar shear flow, specifically the Taylor-Couette flow in an annular domain. One of main difficulties lies in the $T_1$ term of the estimates of $n$:
		\begin{equation*}
			\begin{aligned}
				\|n\|_{Y_{a}}
				&\leq C\Big( \sum_{k\neq 0, k\in\mathbb{Z}}\|n_{k}(0)\|_{L^{2}}+\sum_{k\neq 0, k\in\mathbb{Z}}A^{\frac16}|k|^{-\frac13}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}kf_{1}\|_{L^{2}L^{2}}+\cdots\Big)\\
				&=:C\Big(\sum_{k\neq 0, k\in\mathbb{Z}}\|n_{k}(0)\|_{L^{2}}+T_{1}+\cdots \Big).
			\end{aligned}
		\end{equation*}
where
\begin{equation*}
				\begin{aligned}
					\|f_{1}\|_{L^{2}}&\leq \frac{C(R)}{A}\Big(\sum_{l\in\mathbb{Z}\backslash\{0,k\}}|l|^{-\frac12}\|w_{l}\|_{L^{2}}\|n_{k-l}\|_{L^{2}}+\cdots\Big)
				\end{aligned}
			\end{equation*}
(see \eqref{nk Xa} and \eqref{T2 0}). We estimate the norm by considering the characteristics of each of the four cases based on frequency.
Moreover, our result requires no smallness assumption on the initial cell mass or on the initial velocity field; the global bounded-ness is achieved solely by the strength of the Taylor-Couette flow (i.e., a sufficiently large $A$).
	\end{remark}

\begin{remark}\label{local well-posedness}
		The result of local well-posedness of the system (\ref{ini1}) is standard, which can be refered to \cite{Hu1, Wink2013}, and we omitted it.
	\end{remark}	
	The stabilizing phenomenon is fundamentally caused by the enhanced dissipation induced by the Taylor-Couette flow. We first recall the space-time estimate of the following system (see Proposition 6.1 in \cite{AHL2024}), which plays a crucial role in the subsequent analysis. Let
	\begin{equation}\label{eq:space time}
		\left\{
		\begin{array}{lr}
			\partial_{t}h-\frac{1}{A}\Big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \Big)h+\frac{ik}{r^{2}}h+\frac{1}{r}\big[ikh_{1}-r^{\frac12}\partial_{r}(r^{\frac12}h_{2}) \big]=0,\\
			h|_{t=0}=h(0),\quad h|_{r=1,R}=0,
		\end{array}
		\right.
	\end{equation}
	where $h_{1}$ and $ h_{2}$ are given functions.
	\begin{proposition}\label{prop:space time}
		For $k\in\mathbb{Z}\backslash\{0\}$, let $h$ be a solution to \eqref{eq:space time} with $h(0)\in L^{2}$. Given $\log R\leq CA^{\frac13}$, then there exists a constant $a>0$ independent of $A, k, R$, such that it holds
		\begin{equation*}
			\begin{aligned}
				&\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h\|_{L^{\infty}L^{2}}+A^{-\frac16}|k|^{\frac13}R^{-1}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h\|_{L^{2}L^{2}}\\&+A^{-\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\partial_{r}h\|_{L^{2}L^{2}}+A^{-\frac12}|k|\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\frac{h}{r}\Big\|_{L^{2}L^{2}}\\\leq&C\left(\|h(0)\|_{L^{2}}+A^{\frac16}|k|^{-\frac13}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}kh_{1}\|_{L^{2}L^{2}}+A^{\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h_{2}\|_{L^{2}L^{2}} \right).
			\end{aligned}
		\end{equation*}
	\end{proposition}

	Here are some notations used in this paper.

	\noindent\textbf{Notations}:
	\begin{itemize}

		\item The Fourier transform is defined by
		\begin{equation}
			f(t,r,\theta)=\sum_{k\in\mathbb{Z}}\widehat{f}_{k}(t,r){\rm e}^{ik\theta}, \nonumber
		\end{equation}
		where $\widehat{f}_{k}(t,r)=\frac{1}{2\pi}\int_{0}^{2\pi}f(t,r,\theta){\rm e}^{-ik\theta}d\theta$.

		\item For a given function $f=f(t,r,\theta)$,  we write its  zero mode by
		$$P_0f=\widehat{f}_0=\frac{1}{2\pi}\int_{0}^{2\pi}f(t,r,\theta)d\theta.$$ 

		\item  For  given functions $f=f(t,r,\theta)$ and $g=g(t,r)$, 
		their space norm  and  time-space norm  are defined as 
		$$\|f\|_{L^{p}([1,R]\times\mathbb{S}^{1})}=\left(\int_{0}^{2\pi}\int_{1}^{R}|f|^{p}drd\theta \right)^{\frac{1}{p}},
		\quad \|g\|_{L^{p}([1,R])}=\left(\int_{1}^{R}|g|^{p}dr \right)^{\frac{1}{p}}$$ 
		and 
		$$\|f\|_{L^{q}L^{p}}=\left\|\|f\|_{L^{p}([1,R]\times\mathbb{S}^{1})} \right\|_{L^{q}(0,t)},
		\quad \|g\|_{L^{q}L^{p}}=\left\|\|g\|_{L^{p}([1,R])} \right\|_{L^{q}(0,t)}.$$ Moreover, $\langle \cdot, \cdot\rangle$ denotes the standard $L^{2}$ scalar product.

		\item The total mass $\|n_{\rm in}\|_{L^{1}}$ is denoted by $M$. Clearly, Green’s identity gives
		\begin{equation*}
			\begin{aligned}
				&	\|n(t)\|_{L^{1}}\leq\|n_{\rm in}\|_{L^{1}}=:M.
			\end{aligned}
		\end{equation*}

		\item Throughout this paper, we denote by $ C $ a positive constant independent of $A$, $t$ and the initial data, and it may be different from line to line. $C(R)$  denotes a constant depending on the parameter $R$.
	\end{itemize}

	The rest part of this paper is organized as follows. In Section \ref{ideas}, some key ideas and the proof of
	Theorem \ref{thm:main} are presented. Section \ref{priori estimate} is devoted to providing a priori estimates and zero mode estimates, which are essential for the subsequent analysis.  The energy estimates for $E(t)$ and the proof of Proposition \ref{prop:E(t)} are established in Section \ref{estimate E(t)}. In Section \ref{estimate infty}, we complete the proof of Proposition \ref{prop:n infty}.

expanded_sketch:
The post-theorem introduction does not give a step-by-step proof of the main theorem, but it does indicate the main mechanism and key analytic input:

- The stabilization/global boundedness in the main theorem is attributed to enhanced dissipation: “The stabilizing phenomenon is fundamentally caused by the enhanced dissipation induced by the Taylor-Couette flow.”

- A “crucial role” is played by a recalled space-time estimate (Proposition~\ref{prop:space time}, from Proposition 6.1 in \cite{AHL2024}) for the linearized/Fourier-mode system
\begin{equation}\label{eq:space time}
		\left\{
		\begin{array}{lr}
			\partial_{t}h-\frac{1}{A}\Big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \Big)h+\frac{ik}{r^{2}}h+\frac{1}{r}\big[ikh_{1}-r^{\frac12}\partial_{r}(r^{\frac12}h_{2}) \big]=0,\\
			h|_{t=0}=h(0),\quad h|_{r=1,R}=0,
		\end{array}
		\right.
	\end{equation}
which yields weighted bounds of the form
  \[
  \|e^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}h\|_{L^\infty L^2}+\cdots \le C\big(\|h(0)\|_{L^2}+A^{\frac16}|k|^{-\frac13}\|e^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}kh_1\|_{L^2L^2}+A^{\frac12}\|e^{\cdots}h_2\|_{L^2L^2}\big).
  \]
This estimate is described as the tool that “plays a crucial role in the subsequent analysis.”

- A main technical difficulty in proving the main theorem is identified in controlling the “$T_1$ term” in the estimates of $n$:
  \[
  \|n\|_{Y_a}\le C\Big(\sum_{k\ne0}\|n_k(0)\|_{L^2}+\underbrace{\sum_{k\ne0}A^{\frac16}|k|^{-\frac13}\|e^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}k f_1\|_{L^2L^2}}_{=:T_1}+\cdots\Big),
  \]
  with
  \[
  \|f_1\|_{L^2}\le \frac{C(R)}{A}\Big(\sum_{l\in\mathbb{Z}\setminus\{0,k\}}|l|^{-\frac12}\|w_l\|_{L^2}\|n_{k-l}\|_{L^2}+\cdots\Big).
  \]
  They state: “We estimate the norm by considering the characteristics of each of the four cases based on frequency.”

- The theorem’s global boundedness is emphasized as coming “solely by the strength of the Taylor-Couette flow (i.e., a sufficiently large $A$),” i.e. “no smallness assumption on the initial cell mass or on the initial velocity field.”

- Finally, the paper roadmap says that “some key ideas and the proof of the main theorem are presented” in
\begin{aligned}
				&	\|n(t)\|_{L^{1}}\leq\|n_{\rm in}\|_{L^{1}}=:M.
			\end{aligned}
		\end{equation*}

		\item Throughout this paper, we denote by $ C $ a positive constant independent of $A$, $t$ and the initial data, and it may be different from line to line. $C(R)$  denotes a constant depending on the parameter $R$.
	\end{itemize}

	The rest part of this paper is organized as follows. In Section \ref{ideas}, some key ideas and the proof of
	Theorem \ref{thm:main} are presented. Section \ref{priori estimate} is devoted to providing a priori estimates and zero mode estimates, which are essential for the subsequent analysis.  The energy estimates for $E(t)$ and the proof of Proposition \ref{prop:E(t)} are established in Section \ref{estimate E(t)}. In Section \ref{estimate infty}, we complete the proof of Proposition \ref{prop:n infty}.

	\section{Sketch of the proof of Theorem \ref{thm:main}}\label{ideas}
	In this section, we present some
	key ideas and the proof of Theorem \ref{thm:main}.

	Note that the coordinate $\theta$ in TC flow is defined on $\mathbb{S}^{1}$, and it is natural to applying Fourier transform on the $\theta$ direction. Then taking Fourier transform for (\ref{ini1})-(\ref{boundary condition}) with respect to $\theta$, we obtain
	\begin{equation}\label{eq:fourier}
		\left\{
		\begin{array}{lr}
			\partial_{t}\widehat{n}_{k}-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{n}_{k}+(1+\frac{1}{r^{2}})ik\widehat{n}_{k}+\frac{1}{Ar}\sum_{l\in\mathbb{Z}}i(k-l)\partial_{r}\widehat{\varphi}_{l}\widehat{n}_{k-l}\\-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}il\widehat{\varphi}_{l}\partial_{r}\widehat{n}_{k-l}=-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}\partial_{r}(r\widehat{n}_{l}\partial_{r}\widehat{c}_{k-l})-\frac{ik}{Ar^{2}}\sum_{l\in\mathbb{Z}}i(k-l)\widehat{n}_{l}\widehat{c}_{k-l},\\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{c}_{k}+\widehat{n}_{k}-\widehat{c}_{k}=0,\\
			\partial_{t}\widehat{w}_{k}-\frac{1}{A}(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{w}_{k}+(1+\frac{1}{r^{2}})ik\widehat{w}_{k}+\frac{1}{Ar}\sum_{l\in\mathbb{Z}}i(k-l)\partial_{r}\widehat{\varphi}_{l}\widehat{w}_{k-l}\\-\frac{1}{Ar}\sum_{l\in\mathbb{Z}}il\widehat{\varphi}_{l}\partial_{r}\widehat{w}_{k-l}=-\frac{ik}{Ar}\widehat{n}_{k},\\
			(\partial_{r}^{2}+\frac{1}{r}\partial_{r}-\frac{k^{2}}{r^{2}})\widehat{\varphi}_{k}=\widehat{w}_{k},\\
			\widehat{n}_{k}|_{r=1,R}=\widehat{c}_{k}|_{r=1,R}=\widehat{w}_{k}|_{r=1,R}=\widehat{\varphi}_{k}|_{r=1,R}=0.

		\end{array}
		\right.
	\end{equation}
	Inspired by  An-He-Li \cite{AHL2024}, we introduce the weight $r^{\frac12}$ to eliminate the derivative $\frac{1}{r}\partial_{r}$. Specifically,  define 
	\begin{equation*}
		n_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{n}_{k},\quad c_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{c}_{k},\quad 
		w_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{w}_{k},\quad 
		\varphi_{k}:=r^{\frac12}{\rm e}^{ikt}\widehat{\varphi}_{k}.
	\end{equation*}
	It follows that
	\begin{equation}\label{define nk ck wk}
		\|F_{k}\|_{L^{p}}\leq R^{\frac12}\|\widehat{F}_{k}\|_{L^{p}},\quad {\rm for}\quad F\in\{n, c, w, \varphi \}~{\rm and}~p\in\{2, \infty\}.
	\end{equation}
	Denote the operator $\mathcal{L}_{k}$ as
	\begin{equation}\label{define:Lk}
		\mathcal{L}_{k}f:=-\frac{1}{A}\Big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \Big)f+\frac{ik}{r^{2}}f.
	\end{equation}
	Thus, the system (\ref{eq:fourier})  is transformed into
	\begin{equation}\label{eq:fourier 1}
		\left\{
		\begin{array}{lr}
			\partial_{t}n_{k}+\mathcal{L}_{k}n_{k}+\frac{\big[ik\sum_{l\in\mathbb{Z}}\partial_{r}(r^{-\frac12}\varphi_{l})n_{k-l}-r^{\frac12}\partial_{r}\left(\sum_{l\in\mathbb{Z}}ilr^{-1}\varphi_{l}n_{k-l} \right) \big]}{Ar}
			\\=-\frac{1}{Ar^{\frac12}}\partial_{r}\big[\sum_{l\in\mathbb{Z}}r^{\frac12}n_{l}\partial_{r}(r^{-\frac12}c_{k-l}) \big]-\frac{ik}{Ar^{\frac52}}\sum_{l\in\mathbb{Z}}i(k-l)n_{l}c_{k-l},\\
			\big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \big)c_{k}+n_{k}-c_{k}=0,\\
			\partial_{t}w_{k}+\mathcal{L}_{k}w_{k}
			+\frac{\big[ik\sum_{l\in\mathbb{Z}}\partial_{r}(r^{-\frac12}\varphi_{l})w_{k-l}-r^{\frac12}\partial_{r}\big(\sum_{l\in\mathbb{Z}}ilr^{-1}\varphi_{l}w_{k-l} \big) \big]}{Ar}=-\frac{ik}{Ar}n_{k},\\
			\big(\partial_{r}^{2}-\frac{k^{2}-\frac14}{r^{2}} \big)\varphi_{k}=w_{k},\\
			n_{k}|_{r=1,R}=c_{k}|_{r=1,R}=w_{k}|_{r=1,R}=\varphi_{k}|_{r=1,R}=0.
		\end{array}
		\right.
	\end{equation}

	We introduce the following norms
	\begin{equation}\label{X_a^k}
		\begin{aligned}
			\|f_k\|_{X_{a}^{k}}&=\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}f_k\|_{L^{\infty}L^{2}}+A^{-\frac16}|k|^{\frac13}R^{-1}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}f_k\|_{L^{2}L^{2}}\\&\quad +A^{-\frac12}\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\partial_{r}f_k\|_{L^{2}L^{2}}
			+A^{-\frac12}|k|\Big\|{\rm e}^{aA^{-\frac13}|k|^{\frac23}R^{-2}t}\frac{f_k}{r}\Big\|_{L^{2}L^{2}}
		\end{aligned}
while later sections provide “a priori estimates and zero mode estimates,” “energy estimates for $E(t)$,” and an $L^\infty$ estimate used to “complete the proof,” namely the following result:

\begin{proposition}\label{prop:n infty}
		Under the assumptions of Proposition \ref{prop:E(t)}, there exists a positive constant $\mathcal{Q}_{2}$ depending on $\|u_{\rm in}\|_{H^{2}(\mathcal{D})}$ and $\|n_{\rm in}\|_{L^{\infty}\cap H^{1}(\mathcal{D})}$, such that 
		\begin{equation*}
			\|n\|_{L^{\infty}L^{\infty}}\leq\mathcal{Q}_{2}
		\end{equation*}
		for all $t\in[0,T]$.
	\end{proposition}

