B_{p,\beta}^n
=\{A\in \IF_{\beta}^{n\times n}\colon \|A\|_p\le 1\}\quad \text{and}\quad
\mathbb{B}_{p,\beta}^n
= B_{p,\beta}^n \cap \cH_n(\IF_{\beta}).
\]
For self-adjoint matrices the Schatten $p$-norm $\|A\|_p$ becomes a $p$-norm of eigenvalues. In case of non-self adjoint matrices one can also study the rectangular case, see e.g. \cite{JKP24}.

We shall identify $\IF_{\beta}^{n\times n}$ with $\mathbb{R}^{\beta n^2}$ and $\cH_n(\IF_{\beta})$ with $\mathbb{R}^{d_n}$, where 
\begin{align}\label{eq:dn}
d_n:=\beta\frac{n(n-1)}{2}+n.
\end{align}
Then $B_{p,\beta}^n$ and $\mathbb{B}_{p,\beta}^n$ are convex bodies (i.e. compact convex sets with nonempty interior) in $\mathbb{R}^{\beta n^2}$ and $\mathbb{R}^{d_n}$, respectively. In the following, we study their volumes $\mathrm{vol}(B_{p,\beta}^n)$ and $\mathrm{vol}(\mathbb{B}_{p,\beta}^n)$. Our aim is to give more precise asymptotics of the volume of $\mathbb{B}_{p,\beta}^n$ as $n\to \infty$.

The exact volume of $B_{p,\beta}^n$ and $\mathbb{B}_{p,\beta}^n$ is only known in the cases $p=2$ and $p=\infty$. For $p=2$, the Schatten $2$-balls are Euclidean unit balls of corresponding dimension and thus
\begin{equation*} 
\mathrm{vol}(B_{2,\beta}^n)
=\frac{\pi^{\beta n^2/2}}{\Gamma(1+\frac{\beta n^2}{2})}
\qquad\text{and}\qquad
\mathrm{vol}(\IB_{2,\beta}^n)
=\frac{\pi^{d_n/2}}{\Gamma(1+\frac{d_n}{2})},
\end{equation*} 
where $\Gamma(x)=\int_0^{\infty}t^{x-1}e^{-t}\mathrm{d} t$ denotes the Gamma function. For $p=\infty$ it follows from Saint Raymond's work \cite{SR84} and Selberg's integral formula \cite{And91,Sel44} that
\begin{equation} \label{eq:inf-exact}
\mathrm{vol}(B_{\infty,\beta}^n)
=\frac{\prod_{j=0}^{n-1}\Gamma( 1+j\frac{\beta}{2} )}{\prod_{j=n}^{2n-1}\Gamma( 1+j\frac{\beta}{2})}\pi^{\beta n^2/2},
\end{equation}
and in the self-adjoint case it holds that
\begin{equation} \label{eq:inf-sa-exact}
\mathrm{vol}(\IB_{\infty,\beta}^n)
=2^{d_n}(2\pi)^{\beta n(n-1)/4}\prod_{j=0}^{n-1}\frac{\Gamma( 1+j\frac{\beta}{2})^2\Gamma( (j+1)\frac{\beta}{2} )}{\Gamma( 2+(n+j-1)\frac{\beta}{2} )\Gamma( j\frac{\beta}{2} )}.
\end{equation}
For general $1\le p\le \infty$, exact volumes are unknown and instead their asymptotic behavior has been studied. Saint Raymond \cite{SR84} derived $A(p)>0$ such that, for $\beta\in\{1,2\}$, 
\begin{equation} \label{eq:sim-asym}
\lim_{n\to \infty}n^{1/2+1/p}\mathrm{vol}(B_{p,\beta}^n)^{1/\beta n^2}
=\sqrt{\frac{2\pi}{\beta}}e^{3/4}A(p)
\end{equation}
and determined $A(2)=e^{-1/4}$ and $A(\infty)=\frac{1}{2}$. Gu\'{e}don and Paouris \cite{GP07} showed that $\mathrm{vol}(B_{p,4}^n)^{1/4 n^2}$ and $\mathrm{vol}(\mathbb{B}_{p,\beta}^n)^{1/d_n}, \beta\in\{1,2,4\}$ are of the same order $n^{-1/2-1/p}$. Kabluchko, Prochno and Thäle \cite{KPT20a} determined
\begin{equation} \label{eq:delta}
A(p)
=\frac{1}{2}\bigg(\frac{p\sqrt{\pi}\Gamma(\frac{p}{2})}{\sqrt{e}\Gamma(\frac{p+1}{2})}\bigg)^{1/p}
\end{equation}
and moreover showed in \cite{KPT20b} that, for $\beta\in \{1,2,4\}$,
\begin{equation} \label{eq:sim-sym}
 \lim_{n\to \infty}n^{1/2+1/p}\mathrm{vol}(\mathbb{B}_{p,\beta}^n)^{1/d_n}
 =\sqrt{\frac{4\pi}{\beta}}e^{3/4}A(p).
\end{equation}
We remark that one way to see that $A(p)$ is decreasing in $p$ is to observe that the same is true for the normalized volume $\mathrm{vol}(n^{1/p}\mathbb{B}_{p,\beta}^n)$. Recently, Dadoun, Fradelizi, Gu\'{e}don and Zitt \cite[Remark 4.8]{DFG+23} showed \eqref{eq:sim-asym} for $\beta=4$. Thus, the asymptotics in \eqref{eq:sim-asym} and \eqref{eq:sim-sym} hold in all cases $\beta\in \{1,2,4\}$ and $1\le p\le \infty$.

In case of $p<\infty$, the quantity $A(p)$ in \eqref{eq:delta} can be expressed as 
\[
A(p)
=\frac{1}{2}\Big(\frac{p\sqrt{\pi}\Gamma(\frac{p}{2})}{\sqrt{e}\Gamma(\frac{p+1}{2})}\Big)^{1/p}
=\frac{1}{2}\Big(\frac{1}{\sqrt{e}\alpha_p}\Big)^{1/p},
\]
where $\alpha_p=\int_{\mathbb{R}} |x|^p\mathrm{d}\mu_p(x)$ is the $p$-th absolute moment of the Ullman distribution $\mu_p$ which has density
\begin{equation} \label{eq:ullman-1}
f_p(x)
= \frac{p}{\pi}\int_{|x|}^1 \frac{t^{p-1}}{\sqrt{t^2-x^2}}\mathrm{d} t, \qquad x\in [-1,1].
\end{equation}

Our main contribution is the following asymptotic expansion for the logarithmic volume $\ln \mathrm{vol}(\mathbb{B}_{p,\beta}^n)$. Recall that the differential entropy of a probability measure $\mu$ on $\mathbb{R}$ is
\[
\mathrm{Ent}(\mu)
= -\int_{\mathbb{R}}\ln(f(x))f(x)\mathrm{d} x, 
\]
whenever $\mu$ admits a Lebesgue density $f$ and $\mathrm{Ent}(\mu)=-\infty$ otherwise.

\begin{equation} \label{eq:sim-asym}
\lim_{n\to \infty}n^{1/2+1/p}\vol(B_{p,\beta}^n)^{1/\beta n^2}
=\sqrt{\frac{2\pi}{\beta}}e^{3/4}A(p)
\end{equation}

\begin{equation} \label{eq:sim-sym}
	\lim_{n\to \infty}n^{1/2+1/p}\vol(\bpb)^{1/d_n}
	=\sqrt{\frac{4\pi}{\beta}}e^{3/4}A(p).
\end{equation}

Our main contribution is the following asymptotic expansion for the logarithmic volume $\ln \vol(\bpb)$. Recall that the differential entropy of a probability measure $\mu$ on $\IR$ is
\[
\Ent(\mu)
= -\int_{\IR}\ln(f(x))f(x)\dd x, 
\]
whenever $\mu$ admits a Lebesgue density $f$ and $\Ent(\mu)=-\infty$ otherwise.

In case of $p=2$ it is known that $\Ent(\mu_2)=\ln \pi -\frac{1}{2}$ where $\mu_2$ is the semi-circle law. Otherwise the entropy $\Ent(\mu_p)$ of the Ullman distribution appears to be unknown. Independently, the expansion in \eqref{eq:main-1} was recently obtained by Dworaczek Guera, Memin and Pain \cite{GMP25} in case of $p\ge 2$.

In this context the Ullman distribution arises as the corresponding equilibrium measure minimizing the functional
\[
\mu\mapsto I_p(\mu)
=-\int_{\IR}\int_{\IR} \ln|x-y|\dd\mu(x)\dd\mu(y)+v_p\int_{\IR} |x|^p\dd\mu(x)
\]
over $\mu\in \cP(\IR)$, where $\cP(\IR)$ denotes the space of probability measures on $\IR$. More precisely, if $X=(X_1,\dots,X_n)$ is distributed according to the density $f_{n,p,\beta}$, then the random empirical measure $ \mu_{n,p} =\frac{1}{n}\sum_{i=1}^{n}\delta_{X_i} $ tends to $\mu_p$ as $n\to\infty$. Moreover, large deviation principles due to \cite{BG97} and \cite{HP00} yield 
\begin{equation} \label{eq:Z-first}
\lim_{n\to\infty}\frac{2}{\beta n^2}\ln Z_{n,p,\beta}
= I_p(\mu_p)
=\ln 2+\frac{3}{2p}.
\end{equation}
Earlier work \cite{DPS95,Joh98} also identified the limiting constant but with different techniques. In \cite{DFG+23}, the limit \eqref{eq:Z-first} is used to prove \eqref{eq:sim-sym}. The large deviation principle for tagged empirical fields due to Lebl\'e and Serfaty \cite{LS17} allows to refine \eqref{eq:Z-first}. The following result forms the core of the proof of \eqref{eq:main-1} in Theorem~\ref{thm:main}.

\begin{theorem} \label{thm:LS}
Let $\beta>0$ and $p\ge \frac{3}{2}$. As $n\to\infty$,
\[
\ln Z_{n,p,\beta}
=-\frac{\beta}{2}n^2 I_p(\mu_p)+\frac{\beta}{2}n\ln n- C(\beta)n+\Big(1-\frac{\beta}{2}\Big)\Ent(\mu_p)n +o(n),
\]
where 
\begin{equation} \label{eq:c-beta}
C(\beta)
=\Big(1-\frac{\beta}{2}\Big)\ln \frac{\beta}{2}-\frac{\beta}{2}\ln 2\pi+\frac{\beta}{2}+\ln \Gamma\Big(\frac{\beta}{2}\Big).
\end{equation}
\end{theorem}

It remains to check Hölder continuity at zero. Let $h\in (0,1)$ and write
\begin{align*}
\frac{\pi}{p}\big(f_p(h)-f_p(0)\big)
&=\int_h^1 \frac{t^{p-1}}{\sqrt{t^2-h^2}}\dd t - \int_0^1 t^{p-2}\dd t\\
&=\int_h^1 t^{p-1}\Big(\frac{1}{\sqrt{t^2-h^2}}-\frac{1}{t}\Big)\dd t -\frac{h^{p-1}}{p-1}.
\end{align*}
The latter integral can be estimated by
\begin{align*}
\int_h^1 t^{p-1}\Big(\frac{1}{\sqrt{t^2-h^2}}-\frac{1}{t}\Big)\dd t
&\le h^2\int_h^1 \frac{t^{p-3}}{\sqrt{t^2-h^2}}\dd t\\
&= h^{p-1}\int_1^{1/h} \frac{u^{p-3}}{\sqrt{u^2-1}}\dd u.
\end{align*}
In particular, if $1< p<2$, then
\begin{equation} \label{eq:hoelder}
0\le \frac{\pi}{p}\frac{f_p(h)-f_p(0)}{h^{p-1}}
\le \int_1^{\infty} \frac{u^{p-3}}{\sqrt{u^2-1}}\dd u
<\infty.
\end{equation}
Thus, in this case we obtain that $f_p$ is Hölder continuous of order $p-1$ at $0$. For $p\ge 2$, a similar argument shows that $f_p$ is continuously differentiable at $0$ with $f_p'(0)=0$. In conclusion, if $p\ge\frac{3}{2}$, the function $f_p$ is Hölder continuous of order $\frac{1}{2}$ on $[-1,1]$. This completes the proof.
\end{proof}

\begin{lemma} \label{lem:cn}
Let $\beta\in \{1,2,4\}$. Then, as $n\to\infty$,
\begin{align*}
\ln c_{n}
=&-\frac{\beta}{4}n^2\ln n + \frac{\beta}{2}\Big(\frac{1}{2}\ln \frac{4\pi}{\beta}+\frac{3}{4}\Big)n^2-\frac{1}{2}\Big(1+\frac{\beta}{2}\Big)n\ln n\\
&+\Big(\frac{1}{2}\Big(1-\frac{\beta}{2}\Big)\ln \beta -\frac{1}{2}\Big(1+\frac{\beta}{2}\Big)(\ln \pi-1)-\ln 2+\ln \Gamma\Big(\frac{\beta}{2}\Big)\Big)n\\
&-\frac{3+\frac{\beta}{2}+\frac{2}{\beta}}{12}\ln n
+a_{\beta}+o(1),
\end{align*}
where $a_{\beta}\in \IR$ is some constant.
\end{lemma}
\begin{proof}
It follows from the definition of $c_{n}$ that 
\[
c_{n}
=\frac{1}{n!}\Gamma_2\Big(n+1;\frac{2}{\beta},1\Big)\bigg(\frac{\Gamma(\frac{\beta}{2})}{(\frac{\beta}{2})^{\frac{\beta}{2}}}\bigg)^n\Big(\frac{4\pi}{\beta}\Big)^{\frac{\beta}{4}n^2-(\frac{1}{2}+\frac{\beta}{4})n},
\]
where $\Gamma_2(x;\frac{2}{\beta},1)$ is a particular instance of the Barnes double Gamma function, see \cite{BG24,Spr09}. Adapting \cite[eq. (7.17)]{BG24}, the following asymptotic expansion holds
\begin{align*}
\ln \Gamma_2\Big(n+1;\frac{2}{\beta},1\Big) 
=&-\frac{\beta}{4}n^2\ln n+\frac{3\beta}{8}n^2+\frac{1}{2}\Big(1-\frac{\beta}{2}\Big)n\ln n-\frac{1}{2}\Big(1-\frac{\beta}{2}\Big)n\\
&+\bigg(\frac{1}{2} -\frac{3+\frac{\beta}{2}+\frac{2}{\beta}}{12}\bigg)\ln n +a_{\beta}'+o(1),
\end{align*}
where $a_{\beta}'\in \IR$ is some constant. Combined with Stirling's approximation $\ln n!=n\ln n-n+\frac{1}{2}\ln(2\pi n)+o(1)$ we deduce the claimed expansion.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
Let $\beta\in \{1,2,4\}$ and $p\ge \frac{3}{2}$. Recall that $d_n=\frac{\beta}{2}n^2+(1-\frac{\beta}{2})n$. By Lemma~\ref{lem:vol-partition} it holds that
\begin{equation} \label{eq:vol-asymp-parts}
\ln \vol(\bpb)
=\ln c_{n}+\frac{d_n}{p}\ln \Big(\frac{\beta nv_p}{2}\Big)-\ln \Gamma\Big(1+\frac{d_n}{p}\Big)+\ln Z_{n,p,\beta}.
\end{equation}
By Stirling's approximation, as $n\to\infty$,
\begin{align}\label{eq:p-term-1}
\ln \Gamma\Big(1+\frac{d_n}{p}\Big)
&=\frac{d_n}{p}\Big(\ln \frac{d_n}{p}-1\Big)+o(n)\notag\\
&=\frac{d_n}{p}\Big(2\ln n+\ln \frac{\beta}{2p}-1+\Big(1-\frac{\beta}{2}\Big)\frac{2}{\beta n}\Big)+o(n).
\end{align}
Therefore, 
\begin{align}\label{eq:p-term-2}
\frac{d_n}{p}\ln\Big(\frac{\beta n v_p}{2}\Big)
-\ln \Gamma\Big(1+\frac{d_n}{p}\Big)
=&-\frac{d_n}{p}\Big(\ln n -\ln(p v_p)-1+\Big(1-\frac{\beta}{2}\Big)\frac{2}{\beta n}\Big)\notag\\
=&-\frac{\beta}{2p}n^2\ln n+\frac{\beta}{2p}\big(\ln(pv_p)+1\big)n^2\notag\\
&-\frac{1}{p}\Big(1-\frac{\beta}{2}\Big)n\ln n+\frac{\ln(pv_p)}{p}\Big(1-\frac{\beta}{2}\Big)n +o(n).
\end{align}

post_theorem_intro_text:
In case of $p=2$ it is known that $\mathrm{Ent}(\mu_2)=\ln \pi -\frac{1}{2}$ where $\mu_2$ is the semi-circle law. Otherwise the entropy $\mathrm{Ent}(\mu_p)$ of the Ullman distribution appears to be unknown. Independently, the expansion in \eqref{eq:main-1} was recently obtained by Dworaczek Guera, Memin and Pain \cite{GMP25} in case of $p\ge 2$. 

The proof of Theorem~\ref{thm:main} relies on the fact that the volume of $\mathbb{B}_{p,\beta}^n$ can be expressed in terms of the integral
\begin{equation} \label{eq:Z}
Z_{n,p,\beta}
=\int_{\mathbb{R}^n}\prod_{1\le i<j\le n}|x_i-x_j|^{\beta} e^{-\frac{\beta}{2}n\, v_p\sum_{i=1}^{n}|x_i|^p}\mathrm{d} x,
\end{equation}
where
\[
v_p =\frac{\sqrt{\pi}\Gamma(\frac{p}{2})}{\Gamma(\frac{p+1}{2})}=\frac{1}{p\alpha_p}.
\]
The quantity $Z_{n,p,\beta}$ is the partition function of a one-dimensional $\beta$-ensemble with potential $V(x)=v_p |x|^p$, where eigenvalues/particles are distributed with joint density 
\begin{equation} \label{eq:density}
f_{n,p,\beta}(x)
=\frac{1}{Z_{n,p,\beta}}\prod_{1\le i<j\le n}|x_i-x_j|^{\beta} e^{-\frac{\beta}{2}n\, v_p\sum_{i=1}^{n}|x_i|^p}\mathrm{d} x, \qquad x\in \mathbb{R}^n.
\end{equation}
The parameter $\beta$ stands for the inverse temperature and may take any positive value, while for the matrix representation we restrict to $\beta\in \{1,2,4\}$. We refer to \cite{AGZ10} and \cite{For10} for more information on $\beta$-ensembles. 

In this context the Ullman distribution arises as the corresponding equilibrium measure minimizing the functional
\[
\mu\mapsto I_p(\mu)
=-\int_{\mathbb{R}}\int_{\mathbb{R}} \ln|x-y|\mathrm{d}\mu(x)\mathrm{d}\mu(y)+v_p\int_{\mathbb{R}} |x|^p\mathrm{d}\mu(x)
\]
over $\mu\in \mathcal{P}(\mathbb{R})$, where $\mathcal{P}(\mathbb{R})$ denotes the space of probability measures on $\mathbb{R}$.  More precisely, if $X=(X_1,\dots,X_n)$ is distributed according to the density $f_{n,p,\beta}$, then the random empirical measure $ \mu_{n,p} =\frac{1}{n}\sum_{i=1}^{n}\delta_{X_i} $  tends to $\mu_p$ as $n\to\infty$. Moreover, large deviation principles due to \cite{BG97} and \cite{HP00} yield 
\begin{equation} \label{eq:Z-first}
\lim_{n\to\infty}\frac{2}{\beta n^2}\ln Z_{n,p,\beta}
= I_p(\mu_p)
=\ln 2+\frac{3}{2p}.
\end{equation}
Earlier work \cite{DPS95,Joh98} also identified the limiting constant but with different techniques. In \cite{DFG+23}, the limit \eqref{eq:Z-first} is used to prove \eqref{eq:sim-sym}. The large deviation principle for tagged empirical fields due to Lebl\'e and Serfaty \cite{LS17} allows to refine \eqref{eq:Z-first}. The following result forms the core of the proof of \eqref{eq:main-1} in Theorem~\ref{thm:main}. 

\begin{theorem} \label{thm:LS}
Let $\beta>0$ and $p\ge \frac{3}{2}$. As $n\to\infty$,
\[
\ln Z_{n,p,\beta}
=-\frac{\beta}{2}n^2 I_p(\mu_p)+\frac{\beta}{2}n\ln n- C(\beta)n+\Big(1-\frac{\beta}{2}\Big)\mathrm{Ent}(\mu_p)n +o(n),
\]
where 
\begin{equation} \label{eq:c-beta}
C(\beta)
=\Big(1-\frac{\beta}{2}\Big)\ln \frac{\beta}{2}-\frac{\beta}{2}\ln 2\pi+\frac{\beta}{2}+\ln \Gamma\Big(\frac{\beta}{2}\Big).
\end{equation}
\end{theorem}

Independently, in the recent work \cite{GMP25} the authors deduced the statement of Theorem~\ref{thm:LS} in case of $p\ge 2$ from a central limit theorem for linear eigenvalue statistics. The restriction to $p\ge 2$ results from regularity requirements of the underlying approach, see also \cite{DFG+23}. The slightly milder restriction on $p$ in Theorem~\ref{thm:LS} is due to the fact that the Ullman density $f_p$ is Hölder continuous of order $\frac{1}{2}$ if and only if $p\ge\frac{3}{2}$. This is required to apply the results in \cite{LS17}. 

The term $\mathrm{Ent}(\mu_p)$ in Theorem~\ref{thm:LS} arises via a rescaling property of the specific entropy which is part of the rate function in the large deviation principle in \cite{LS17}. In case of $\beta=2$, the contribution of $\mathrm{Ent}(\mu_p)$ vanishes and more precise asymptotics hold. The following is a consequence of \cite[Prop.~1.1]{CKM23} which is based on \cite{KM99}.

\begin{theorem} \label{thm:CKM}
Let $p\ge 1$. There exists $M_p'\in \mathbb{R}$ such that, as $n\to\infty$,
\[
\ln Z_{n,p,2}
=-n^2 I_p(\mu_p)+n\ln n+(\ln 2\pi -1) n +\frac{5}{12}\ln n +M_p'+o(1).
\]
\end{theorem}

Theorem~\ref{thm:CKM} combined with Lemma~\ref{lem:vol-partition} and Lemma~\ref{lem:cn} below yields \eqref{eq:main-2} in Theorem~\ref{thm:main}. In case of $p$ an even integer, the potential $V(x)=v_p |x|^p$ is an analytic function and results of \cite{BG13} yield a full asymptotic expansion of $\ln Z_{n,p,\beta}$, and consequently of $\ln \mathrm{vol}(\mathbb{B}_{p,\beta}^n)$. In case of $p=2$ the integral $Z_{n,2,\beta}$ is known via a Mehta-Selberg integral. For $p\neq 2$ the coefficients in the full asymptotic expansion are defined in terms of integrals of the Stieltjes transform of $\mu_p$, see also \cite[Section 7]{BG24} and \cite{Shc13,Shc14}.

In the case of non self-adjoint matrices, the volume of the unit ball $B_{p,\beta}^n$ may be written in terms of 
\[
\tilde{Z}_{n,p,\beta}
=\int_{(\IR_+)^n}\prod_{1\le i<j\le n}|x_i-x_j|^{\beta}\prod_{i=1}^n x_i^{\beta/2-1} e^{-\beta n\, v_p\sum_{i=1}^{n}x_i^{p/2}}\mathrm{d} x,
\]
see e.g.~\cite[Sec.~4.2]{DFG+23}. This corresponds to the partition function of a Laguerre $\beta$-ensemble with potential $V(x)=v_p|x|^{p/2}$. The leading order asymptotics for $\tilde{Z}_{n,p,\beta}$ can again be obtained via large deviations, leading to \eqref{eq:sim-asym}. However, the results in \cite{LS17} do not apply and it goes beyond the scope of the present work to derive next-order asymptotics for $\tilde{Z}_{n,p,\beta}$ and $B_{p,\beta}^n$. 

\begin{remark}
	The unit balls $B_{p,\beta}^n$ and $\mathbb{B}_{p,\beta}^n$ can also be studied for $0<p<1$. Then \eqref{eq:sim-asym} and \eqref{eq:sim-sym} as well as Theorem~\ref{thm:CKM} continue to hold. However, even neglecting regularity assumptions, the proof of Theorem~\ref{thm:main} and the underlying large deviation principle in \cite{LS17} are limited to $p\ge 1$. This is because, while the microscopic limit point process in the bulk is the universal sine$_2$-process for $p\ge 1$, it becomes dependent on $p$ for $p<1$, see \cite{BEY14,CKM23}. Since the minimizer of the rate function is the free energy which is uniquely given by the sine$_{\beta}$-process, see \cite{EHL21,HM25}, the large deviation principle in \cite{LS17} cannot hold in its present form if $p<1$. 
\end{remark}

\begin{remark}
	Heuristically, the unit balls $B_{p,\beta}^n$ and $\IB_{p,\beta}^n$ are non-commutative versions of $\IB_p^n=\{x\in \mathbb{R}^n\colon \sum_{i=1}^{n}|x_i|^p\le 1\}$. To compare, note that
\[
\mathrm{vol}(n^{1/p}\IB_{p}^n)
=n^{n/p}\frac{2^n\Gamma(1+\frac{1}{p})^n}{\Gamma(1+\frac{n}{p})}
=\frac{1+o(1)}{\sqrt{2\pi n/p}} e^{\mathrm{Ent}(\nu_p)n},
\]
where $\nu_p$ has density proportional to $e^{-|x|^p/p}$ and maximizes entropy over $\mu\in \mathcal{P}(\mathbb{R})$ with $\int |x|^p\mathrm{d}\mu(x) \le 1$, see also \cite{KP21}. Similarly, the Ullman distribution $\mu_p$ maximizes free entropy over $\mu\in \mathcal{P}(\mathbb{R})$ with $\int |x|^p\mathrm{d}\mu(x)\le \alpha_p$, see \cite[Prop.~5.34]{HP00}. In case of $p=\infty$, one can interpret $\nu_{\infty}$ as the uniform distribution on $[-1,1]$, which maximizes entropy, and $\mu_{\infty}$ as the arcsine distribution, which maximizes free entropy. Formally, see Lemma~\ref{lem:vol-partition} below, the case $\beta=0$ corresponds to the commutative case where a Poisson point process appears in the microscopic limit, see also \cite{AD14,BP15,Leb16}. 
\end{remark}

\begin{remark}
Theorem~\ref{thm:main} can be combined with the stochastic representation in [Cor.~4.3]{KPT20b} of a random matrix drawn uniformly from a Schatten ball $\mathbb{B}_{p,\beta}^n$ to obtain information on critical intersections of Schatten $p$-balls in the spirit of \cite{KPT20b} and \cite{ST25}. 
\end{remark}

expanded_sketch:
The proof of the main theorem is based on rewriting $\mathrm{vol}(\mathbb{B}_{p,\beta}^n)$ in terms of the partition function
\[
Z_{n,p,\beta}=\int_{\mathbb{R}^n}\prod_{1\le i<j\le n}|x_i-x_j|^{\beta}\, e^{-\frac{\beta}{2}n\, v_p\sum_{i=1}^{n}|x_i|^p}\,\mathrm{d} x,
\]
which is the partition function of a one-dimensional $\beta$-ensemble with potential $V(x)=v_p|x|^p$ and joint density $f_{n,p,\beta}$.

In this setting, the Ullman distribution $\mu_p$ appears as the equilibrium measure minimizing
\[
I_p(\mu)=-\iint\ln|x-y|\,\mathrm{d}\mu(x)\mathrm{d}\mu(y)+v_p\int |x|^p\,\mathrm{d}\mu(x),
\]
and the empirical measure $\mu_{n,p}=\frac1n\sum_{i=1}^n\delta_{X_i}$ (for $X\sim f_{n,p,\beta}$) converges to $\mu_p$. Large deviations yield the leading-order limit
\[
\lim_{n\to\infty}\frac{2}{\beta n^2}\ln Z_{n,p,\beta}=I_p(\mu_p)=\ln 2+\frac{3}{2p}.
\]

To obtain the next-order terms needed for
\begin{align}\label{eq:main-1}
\ln \vol(\bpb)
=&-\frac{\beta}{2}\Big(\frac{1}{2}+\frac{1}{p}\Big)n^2\ln n\notag\\
&+\frac{\beta}{2}\Big(\frac{1}{2}\ln\frac{4\pi}{\beta}+\frac{3}{4}+\ln A(p)\Big)n^2\notag\\
&-\Big(1-\frac{\beta}{2}\Big)\Big(\frac{1}{2}+\frac{1}{p}\Big)n\ln n\notag\\
&+\Big(1-\frac{\beta}{2}\Big)\Big(\frac{1}{2}\ln\frac{4}{\beta\pi}+\frac{1}{2}+\frac{1}{2p}+\ln A(p)+\Ent(\mu_p)\Big)n +o(n).
\end{align}
the argument uses the large deviation principle for tagged empirical fields of Lebl\'e--Serfaty (LS17) to refine this to the following result.

\begin{theorem} \label{thm:LS}
Let $\beta>0$ and $p\ge \frac{3}{2}$. As $n\to\infty$,
\[
\ln Z_{n,p,\beta}
=-\frac{\beta}{2}n^2 I_p(\mu_p)+\frac{\beta}{2}n\ln n- C(\beta)n+\Big(1-\frac{\beta}{2}\Big)\Ent(\mu_p)n +o(n),
\]
where 
\begin{equation} \label{eq:c-beta}
C(\beta)
=\Big(1-\frac{\beta}{2}\Big)\ln \frac{\beta}{2}-\frac{\beta}{2}\ln 2\pi+\frac{\beta}{2}+\ln \Gamma\Big(\frac{\beta}{2}\Big).
\end{equation}
\end{theorem}

The restriction $p\ge\tfrac32$ is tied to the requirement that the Ullman density is H\"older $1/2$, which is needed to apply LS17. The appearance of $\mathrm{Ent}(\mu_p)$ is attributed to a rescaling property of the specific entropy in the rate function of LS17.

For the $\beta=2$ refinement
\begin{equation} \label{eq:main-2}
\ln \vol(\IB_{p,2}^n)
=-\Big(\frac{1}{2}+\frac{1}{p}\Big)n^2\ln n
+\Big(\frac{1}{2}\ln 2\pi +\frac{3}{4}+\ln A(p)\Big)n^2
-\ln n+M_p+o(1).
\end{equation}
one notes that the $\mathrm{Ent}(\mu_p)$ contribution vanishes and one invokes the following sharper asymptotics.

\begin{theorem} \label{thm:CKM}
Let $p\ge 1$. There exists $M_p'\in \IR$ such that, as $n\to\infty$,
\[
\ln Z_{n,p,2}
=-n^2 I_p(\mu_p)+n\ln n+(\ln 2\pi -1) n +\frac{5}{12}\ln n +M_p'+o(1).
\]
\end{theorem}

Then the theorem above, combined with the following two lemmas,

\begin{lemma} \label{lem:vol-partition}
Let $\beta\in\{1,2,4\}$ and $1\le p<\infty$. Then
\begin{align*}
\vol(\bpb)
&=c_n\int_{\IB_p^n} \prod_{1\le i< j\le n}|x_i-x_j|^{\beta}\dd x_1 \cdots \dd x_n\\
&=\frac{c_{n}}{\Gamma(1+\frac{d_n}{p})}\Big(\frac{n\beta v_p}{2}\Big)^{d_n/p}Z_{n,p,\beta}
\end{align*}
where $Z_{n,p,\beta}$ and $v_p$ are as in \eqref{eq:Z} and
\[
c_{n}
=\frac{1}{n!}\bigg(\frac{\Gamma(\frac{\beta}{2})}{(2\pi)^{\beta/2}}\bigg)^{n}\prod_{k=1}^n\frac{(2\pi)^{\beta k/2}}{\Gamma(\frac{\beta k}{2})}.
\]
\end{lemma}

\begin{lemma} \label{lem:cn}
Let $\beta\in \{1,2,4\}$. Then, as $n\to\infty$,
\begin{align*}
\ln c_{n}
=&-\frac{\beta}{4}n^2\ln n + \frac{\beta}{2}\Big(\frac{1}{2}\ln \frac{4\pi}{\beta}+\frac{3}{4}\Big)n^2-\frac{1}{2}\Big(1+\frac{\beta}{2}\Big)n\ln n\\
&+\Big(\frac{1}{2}\Big(1-\frac{\beta}{2}\Big)\ln \beta -\frac{1}{2}\Big(1+\frac{\beta}{2}\Big)(\ln \pi-1)-\ln 2+\ln \Gamma\Big(\frac{\beta}{2}\Big)\Big)n\\
&-\frac{3+\frac{\beta}{2}+\frac{2}{\beta}}{12}\ln n
+a_{\beta}+o(1),
\end{align*}
where $a_{\beta}\in \IR$ is some constant.
\end{lemma}

yields the stated $\beta=2$ volume asymptotics, completing that part of the main theorem.

