\section{Non-minimality}\label{nonminimal}
\setcounter{equation}{0}
In this section we prove the following theorem, which provides a necessary condition for real matrix Schubert varieties to be minimal.
\begin{thm}\label{Thm41}
Let $\omega\in\mathfrak{M}_{m,n}(\mathbb{R})$ be a partial permutation. If $\omega$ is a non-vexillary partial permutation, then $X_{\omega}\subset\mathfrak{M}_{m,n}(\mathbb{R})$ is not minimal.
\end{thm}

\subsection{Non-minimal example}\label{subsec41}
We begin by observing the smallest non-minimal example. Consider the partial permutation
\begin{align*}
\omega=
\begin{pmatrix}
0 & 1 & 0\\
1 & 0 & 0\\
0 & 0 & 0
\end{pmatrix},
\end{align*}
which is not vexillary by Lemma \ref{vex}. The corresponding real matrix Schubert variety $\overline{X}_{\omega}\subset\mathfrak{M}_{3,3}(\mathbb{R})$ is defined by the equations
\begin{align*}
x_{11}=0,\quad\det
\begin{pmatrix}
x_{11} & x_{12} & x_{13}\\
x_{21} & x_{22} & x_{23}\\
x_{31} & x_{32} & x_{33}
\end{pmatrix}=0.
\end{align*}
For nonzero real numbers $y_1$, $y_2$, $y_3$, set
\begin{align*}
\omega(y_1,y_2,y_3):=
\begin{pmatrix}
0 & 1 & y_1\\
1 & y_3 & 0\\
0 & y_2 & y_1y_2
\end{pmatrix}.
\end{align*}
It is straightforward to verify that $\omega(y_1,y_2,y_3)\in X_{\omega}\subset \overline{X}_{\omega}$. We next check the minimality of $X_{\omega}$ along these points using Lemma \ref{minimalcheck}.

Since the Rothe diagram $\mathcal{D}(\omega)$ is $\{(1,1),(3,3)\}$, by Proposition \ref{Prop26} we have a normal frame $\left\{\overline{\nabla}f_{(1,1)}, \overline{\nabla}f_{(3,3)}\right\}$. At $\omega(y_1,y_2,y_3)\in X_{\omega}$, these are 
\begin{align*}
\overline{\nabla}f_{(1,1)}=
\begin{pmatrix}
1 & 0 & 0\\
0 & 0 & 0\\
0 & 0 & 0
\end{pmatrix},\quad
\overline{\nabla}f_{(3,3)}=
\begin{pmatrix}
y_1y_2y_3 & -y_1y_2 & y_2\\
0 & 0 & 0\\
-y_1y_3 & y_1 & -1
\end{pmatrix}.
\end{align*}
Then the Gram matrix is given by
\begin{align*}
G:&=
\begin{pmatrix}
\left\langle\overline{\nabla}f_{(1,1)}, \overline{\nabla}f_{(1,1)}\right\rangle & \left\langle\overline{\nabla}f_{(1,1)}, \overline{\nabla}f_{(3,3)}\right\rangle\\
\left\langle\overline{\nabla}f_{(3,3)}, \overline{\nabla}f_{(1,1)}\right\rangle & \left\langle\overline{\nabla}f_{(3,3)}, \overline{\nabla}f_{(3,3)}\right\rangle
\end{pmatrix}\\&=
\begin{pmatrix}
1 & y_1y_2y_3\\
y_1y_2y_3 & (1+y_2^2)(1+y_1^2+y_1^2y_3^2)
\end{pmatrix},
\end{align*}
and its inverse is 
\begin{align*}
G^{-1}=\frac{1}{1+y_1^2+y_2^2+y_1^2y_2^2+y_1^2y_3^2}
\begin{pmatrix}
(1+y_2^2)(1+y_1^2+y_1^2y_3^2) & -y_1y_2y_3\\
-y_1y_2y_3 & 1
\end{pmatrix}.
\end{align*} 
Furthermore, we have
\begin{align*}
\text{Hess}f_{(3,3)}\left(\overline{\nabla}f_{(1,1)},\overline{\nabla}f_{(1,1)}\right)=\text{Hess}f_{(3,3)}\left(\overline{\nabla}f_{(3,3)},\overline{\nabla}f_{(3,3)}\right)=0,
\end{align*}
while
\begin{align*}
\text{Hess}f_{(3,3)}\left(\overline{\nabla}f_{(1,1)},\overline{\nabla}f_{(3,3)}\right)=-y_3.
\end{align*}
It follows that the trace of the Hessian of $f_{(3,3)}$ in the normal space is 
\begin{align*}
\frac{2y_1y_2y_3^2}{1+y_1^2+y_2^2+y_1^2y_2^2+y_1^2y_3^2},
\end{align*}
and hence nonzero. By Lemma \ref{minimalcheck}, the mean curvature vector of $X_{\omega}$ is therefore nonzero along the points $\omega(y_1,y_2,y_3)$. 

As we shall see, the method used in this example provides the basis for the arguments in the proof of the theorem.

\subsection{Perturbation of $\omega$ in $X_\omega$}\label{subsec42}

Let $\omega\in\mathfrak{M}_{m,n}(\mathbb{R})$ be a non-vexillary partial permutation. Then Lemma \ref{vex} implies that there exists $(\alpha,\beta)\in\mathcal{D}(\omega)$ such that 
\begin{align}\label{star}
\text{rk}\left(\omega_{[\alpha,\beta]}\right)\geq2\quad\text{and}\quad \omega\big|_{\mathcal{R}(\alpha,\beta),\mathcal{C}(\alpha,\beta)}\text{ is not the identity matrix}. 
\end{align}
We take $(\alpha,\beta)\in\mathcal{D}(\omega)$ as one of the pairs that minimize the sum $\alpha+\beta$ so that it is located at the top-left corner within its connected component.

Write $\mathcal{R}(\alpha,\beta)=\{r_1<\cdots<r_k\}$ and $\mathcal{C}(\alpha,\beta)=\{c_1<\cdots<c_k\}$. Under the identification (\ref{corres}), the restriction $\omega\big|_{\mathcal{R}(\alpha,\beta),\mathcal{C}(\alpha,\beta)}$ can be viewed as an element of $\mathfrak{S}_k\setminus\{id\}$, denoted by $\omega^{(\alpha,\beta)}$. As in Section \ref{lemmaminor}, set
\begin{align*}
L:=\min\left\{i\in[1,k]\Bigm| \omega^{(\alpha,\beta)}(i)>\omega^{(\alpha,\beta)}(i+1)\right\}.
\end{align*}
Define $\widehat{\omega}^{(\alpha,\beta)}(y_1,y_2,y_3)\in\mathfrak{M}_{m,n}(\mathbb{R})$ by
\begin{align}\label{omegappp}
\widehat{\omega}^{(\alpha,\beta)}&(y_1,y_2,y_3)\nonumber\\
&=\omega+y_1E_{r_L,\beta}+y_2E_{\alpha,c_{\omega^{(\alpha,\beta)}(L)}}+y_1y_2E_{\alpha,\beta}+y_3E_{r_{L+1},c_{\omega^{(\alpha,\beta)}(L)}},
\end{align}
where $y_1,y_2,y_3$ are nonzero real numbers, and $E_{i,j}$ denotes the matrix with a $1$ in the $(i,j)$ entry and zeros elsewhere. Restricting the rows and columns of $\widehat{\omega}^{(\alpha,\beta)}(y_1,y_2,y_3)$ to $\mathcal{R}(\alpha,\beta)\cup\{\alpha\}$ and $\mathcal{C}(\alpha,\beta)\cup\{\beta\}$, respectively, yields
\begin{align}\label{hathat}
\widehat{\omega}^{(\alpha,\beta)}(y_1,y_2,y_3)\big|_{\mathcal{R}(\alpha,\beta)\cup\{\alpha\},\mathcal{C}(\alpha,\beta)\cup\{\beta\}}=\widehat{\omega^{(\alpha,\beta)}}(y_1,y_2,y_3),
\end{align}
where the last term is defined in Section \ref{lemmaminor}. Since $\widehat{\omega}^{(\alpha,\beta)}(y_1,y_2,y_3)$ is obtained from $\omega$ by applying elementary column operations to the right and row operations to the bottom, it follows that $\widehat{\omega}^{(\alpha,\beta)}(y_1,y_2,y_3)\in X_\omega$. 

In the following subsections, we will show that the trace of the Hessian of $f_{(\alpha,\beta)}$ in the normal space does not vanish at these points. By Lemma \ref{minimalcheck}, this implies that the mean curvature vectors at these points are nonzero, thereby completing the proof.

\subsection{The first and second derivatives of $f_{(i.j)}$}
We consider the first and second derivatives of $f_{(i,j)}$ for $(i,j)\in\mathcal{D}(\omega)$. The next two lemmas are immediate consequences of Lemma \ref{Lem32} and \ref{Lem33}.
\begin{lemma}\label{Lem42}
For simplicity, let us write $\delta=\det \left(\omega^{(\alpha,\beta)}\right)$. Then
\begin{align*}
\frac{\partial f_{(\alpha,\beta)}}{\partial x_{ab}}\left(\widehat{\omega}^{(\alpha,\beta)}(y_1,y_2,y_3)\right)=
\begin{cases}
\delta &\text{if }(a,b)=(\alpha,\beta),\\
-y_1\delta &\text{if }(a,b)=(\alpha,c_{\omega^{(\alpha,\beta)}(L)}),\\
y_1y_3\delta &\text{if }(a,b)=(\alpha,c_{\omega^{(\alpha,\beta)}(L+1)}),\\
-y_2\delta &\text{if }(a,b)=(r_L,\beta),\\
y_1y_2\delta &\text{if }(a,b)=(r_L,c_{\omega^{(\alpha,\beta)}(L)}),\\
-y_1y_2y_3\delta &\text{if }(a,b)=(r_L,c_{\omega^{(\alpha,\beta)}(L+1)}),\\
0 &\text{otherwise}.
\end{cases}

