$$\mathcal{F}^{k}_{\varepsilon}(v,B_R):= \, \int_{B_R} \left( f^k(x,Dv)+ \varepsilon(1+ |Dv|^2)^{\frac{p_n}{2}}- \omega^k(x)v(x) \right) dx.$$
\begin{flushleft}
One can easily check that $f^k(x, \xi)$ satisfies assumptions \eqref{A2}--\eqref{A3} and \eqref{A'4}, with $K = \sup_{B_R} |g_k(x)| $ that is finite since $a^k_i(x) \in W^{1, \infty}(B_R)$ and then $g_k \in L^{\infty}(B_R)$.\\
\end{flushleft}

We are in position to prove our main result.

\begin{proof}[\textit{{Proof of Theorem~\ref{thmBfinito}}}]
We consider the variational problems
\begin{equation}\label{Pfj}
    \inf \left\{  \int_{B_R} \left( f^k(x,Dv)+ \varepsilon(1+ |Dv|^2)^{\frac{p_n}{2}} -\omega^k(x)v(x)\right) dx \ : \ v \in W^{1,p_n}_0(B_R)+u^\eta \right\},
\end{equation}
where $$u^\eta = u * \varsigma_\eta$$ is the mollification of the local minimizer $u$ of \eqref{functional}, for a sequence of mollifier $\varsigma_n$.\\
It is well known that, by the direct methods of the calculus of variations, there exists a unique solution $u^\eta_{k,\varepsilon} \in  W^{1,p_n}_0(B_R)+u^\eta $ of the problem \eqref{Pfj}. Since the integrand $$f^k(x,Dv)+ \varepsilon(1+ |Dv|^2)^{\frac{p_n}{2}}-\omega^k(x)v(x)$$ satisfies the assumptions of  Theorem \ref{thm2Mascolo}, we have that $$V_{p_i}((u^\eta_{k,\varepsilon})_{x_i}) \in W_{\mathrm{loc}}^{1,2}(B_R) \quad \forall i=1,...,n.$$
