     &  \leq c(\lambda) \left(1+ \sum_{i=1}^{n} \left( \int_{B_R} a_i^k(x)\, \lvert (u^\eta_{k,\varepsilon})_{x_i}\rvert^{p_i} \ dx +  \Vert \omega^k_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})} \right) + \Vert g_k \Vert_{L^r (B_{R})} \right)^\sigma, \label{der}
\end{align}

