\section{A regularized problem}\label{PreREG}
In this section we prove a regularity result for more regular problems with respect to \eqref{functional} that will be needed in the approximation procedure. More precisely, for $\varepsilon \geq 0$ we consider 
\begin{equation}\label{Eqconepsilon}
 f_\varepsilon(x,u, \xi)= \sum_{i=1}^{n} \, \dfrac{b_i(x)}{p_i} \lvert \xi_i \rvert^{p_i} + \varepsilon(1+|\xi|^\frac{p_n}{2})^2 -\overline{\omega}(x)u
\end{equation}
with
$b_i(x):\Omega \to [0,+\infty), \, i=1, \dots, n$, non-negative, Lipschitz continuous coefficients,
i.e., the following conditions hold
\begin{equation}\label{atilde}
L_i= \sup_{x,y \in \Omega, x \neq y} \frac{|b_i(x)-b_i(y)|}{|x-y|}< \infty , \quad i=1,..,n.
\end{equation}
Setting $\tilde{f}(x, \xi)= \sum_{i=1}^{n} \, b_i(x) \lvert \xi_i \rvert^{p_i},$ one can easily check that
\begin{equation}\label{A'4}
 |D_\xi \tilde{f}(x,\xi)-D_\xi \tilde{f}(y, \xi)| \leq K |x-y|\, \, \sum_{i=1}^{n} |\xi_i|^{p_i-1} \tag{A3'}
\end{equation}
\noindent for a.e.\ $x,y \in \Omega $ and every $\xi \in \mathbb{R}^{ n}$, where $K=K(L_i, p_i)$
.\\
We recall a Lipschitz regularity Theorem for the minimizers of the functional 
\begin{equation}\label{functional2}
 \mathcal{F}_\varepsilon (x, Dv) =\int_\Omega f_\varepsilon(x,v, Dv) \, dx,
\end{equation}
that can be deduced by \cite[Theorem $8.9$]{giusti} in the case $p=p_n$, where $f_\varepsilon$ was defined at \eqref{Eqconepsilon}. 
\begin{thm}\label{thm2Mascolo}
 Let $\tilde{f} $ satisfy \eqref{A2}, \eqref{A3} and \eqref{A'4} and $\overline{\omega} \in L^\infty(\Omega)$.
 Let $u_\varepsilon \in W^{1,p_n}_{\mathrm{loc}}(\Omega)$ be a local minimizer of \eqref{functional2}.
Then, $u_\varepsilon \in W^{1,\infty}_{\mathrm{loc}}(\Omega)$ 
\end{thm}

\begin{align}
 \sum_{i=1}^n \int_{B_{\rho}} |\tau_{j,h} V_{p_i} ((u_\varepsilon)_{x_i})|^2 dx & \leq \,|h|^2 \Biggl\{ \frac{c_\beta}{(t-\rho)^2} + 
\frac{c(K)}{(t-\rho)} 
+ c_{\beta} 
 + \frac{c \varepsilon}{(t-\rho)^2} \notag\\
& \qquad + \sum_{i=1}^n \left( \int_{B_R}|\omega_{x_i}|^{\frac{p_i+2}{p_i+1}} \, dx\right)^\frac{p_i+1}{p_i+2} \Biggr\}, \notag 
 \end{align}
 and so
\begin{align}
 &\sum_{i=1}^n \int_{B_{\rho}} |\tau_{j,h} V_{p_i} ((u_\varepsilon)_{x_i})|^2 dx \leq c |h|^{2} \,\left[ 1+ \sum_{i=1}^{n} \Vert \omega_{x_i} \Vert_{L^{\frac{p_i+2}{p_i+1}}(B_{R})} \right], \label{StimaLemma}
\end{align}
for a positive constant $c = c(n,p_i,\rho, R, \lambda, K, \lvert \lvert Du \rvert \rvert_{\infty})$.
Then we have that 
 $$V_{p_i}((u_\varepsilon)_{x_i}) \in W^{1,2}_{\mathrm{loc}}(\Omega), \qquad \forall i=1, \dots, n,$$ 
 which implies in particular that $$|(u_\varepsilon)_{x_i x_j}|^2|(u_\varepsilon)_{x_i}|^{p_i-2} \in L^1_{\mathrm{loc}}(\Omega), \qquad \forall i=1, \dots, n \text{ and } \forall j=1, \dots, n. $$
\end{proof}

\section{A priori estimates}\label{Apriorisec}
The main aim of this section is to establish the following a priori estimate which is the main step in the proof of our main result.
\begin{thm}\label{AppThm}
Let $\omega \in W^{1,\frac{\mathbf{p}+2}{\mathbf{p}+1}}_{\mathrm{loc}}(\Omega)$ and let $u \in W^{1, \mathbf{p}}_{\mathrm{loc}}(\Omega) \cap L^\infty_{\mathrm{loc}}(\Omega)$ be a local minimizer of \eqref{functional} under assumptions \eqref{A2}--\eqref{A4}, with exponents $p_i\geq 2, \forall i=1,\dots,n $, such that $p_n < p_1+2$,
and with a function $g \in L^{r}_{\mathrm{loc}}{(\Omega)}$, where $r$ satisfies the condition
\eqref{Ipotesir}.
If we assume that 
\begin{equation}\label{Apriori}
V_{p_i}(u_{x_i}) \in {W^{1,2}_{\mathrm{loc}}(\Omega)}, \qquad\forall i=1,\dots,n,
\end{equation}
then the following estimates
\begin{align}\label{uxistima}
 \sum_{i=1}^{n} \left( \int_{B_{R/4}} |u_{x_i}|^{p_i +2 } dx \right) & \leq c \left(1+ \sum_{i=1}^{n} \left(\Vert u_{x_i} \Vert_{L^{p_i}(B_R)} + \Vert \omega_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})} \right) + \Vert g \Vert_{L^r (B_{R})} \right)^\gamma 
\end{align}
and
\begin{align}
 \sum_{i=1}^{n} \left( \int_{B_{R/4}} |u_{x_i x_j}|^2|u_{x_i}|^{p_i-2}dx \right) & \leq c \left( 1+\sum_{i=1}^{n} \left(\Vert u_{x_i} \Vert_{L^{p_i}(B_R)} + \Vert \omega_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})} \right)+ \Vert g \Vert_{L^r (B_{R})} \right)^\gamma 
 \label{StimaTeo1}
\end{align}
hold for every pair of concentric balls $B_{R/4} \subset B_{R} \Subset \Omega$, where $c = c(n,p_i,\lambda, \Lambda,R, {\Vert u \Vert_{\infty}})$ and $\gamma= \gamma (n,p_i, {r})$ are positive constants.
\end{thm}
\begin{proof}
We start by observing that, thanks to assumption \eqref{Ipotesip}, Theorem \ref{ulimitatoCupini} and Lemma \ref{LemmaTroisi}, we have $u \in L^\infty_{\mathrm{loc}}(\Omega)$. Therefore, by virtue of the local boundedness of $u$ and of assumption \eqref{Apriori}, an application of Proposition \ref{LemmaBrasco} gives that
\begin{equation}
 u_{x_k} \in L^{p_k+2}_{\mathrm{loc}}(\Omega) \qquad \text{for every } k \in \mathbb{N}. \label{highint}
\end{equation}
Fix a ball $B_R \Subset \Omega$ and consider radii $\frac{R}{4}< \rho< s<t<t'<{\sigma}<R$, a cut-off function $\eta \in C_0^{\infty}(B_t)$, with $\eta=1$ on $B_{s}$, $0 \leq \eta \leq 1$, $|D \eta | \leq \frac{c}{t-s}$ and $|h|\leq \frac{t' - t}{2}$.
We test the Euler-Lagrange equation of \eqref{functional} with the function $$\varphi = \tau_{j,-h}(\eta^2 \tau_{j,h}u),$$ 
thus getting
\begin{align}\label{SommaIntera}
 0= \int_{\Omega} &\langle f_{\xi} (x+e_jh, Du(x+e_jh))- f_{\xi} (x+e_jh, Du(x)) , \eta^2 \tau_{j,h} Du \rangle \, dx \notag \\
 &+ \int_{\Omega} \langle f_{\xi} (x+e_jh, Du(x+e_jh))- f_{\xi} (x+e_jh, Du(x)) , 2 \eta D \eta \tau_{j,h} u \rangle \, dx \notag \\
 &+ \int_{\Omega} \langle f_{\xi} (x+e_jh, Du(x))- f_{\xi} (x, Du(x)) , 2 \eta D \eta \tau_{j,h} u \rangle \, dx \notag \\
 &+ \int_{\Omega} \langle f_{\xi} (x+e_jh, Du(x))- f_{\xi} (x, Du(x)) , \eta^2 \tau_{j,h} Du \rangle \, dx \notag \\
 &- \int_{\Omega} \tau_{j,h}\omega(x)\eta^2 \tau_{j,h} u(x) \, dx \notag\\
