\section{Proof of Theorem~\ref{thm.bdd}}\label{Caccio.bounded}
The following Caccioppoli type estimate can be proved in a standard way, see for instance \cite[Lemma~4.2]{BOS}.

\begin{lemma}\label{caccioppoli2}
Let $u\in\mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak solution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{a.bound}. 
There exists a constant $c\equiv c(n,s,t,p,\nu,L)>0$ such that
\begin{equation}\label{caccio.2}
\begin{aligned}
& \int_{B_{\rho}}\int_{B_{\rho}}\left(a(x,y)\frac{|w_{\pm}(x)-w_{\pm}(y)|^{p}}{|x-y|^{n+sp}} + b(x,y)\frac{|w_{\pm}(x)-w_{\pm}(y)|^{p}}{|x-y|^{n+tp}}\right)\,dx\,dy  \\
& \le \frac{c}{(r-\rho)^{p}}\int_{B_{r}}\int_{B_{r}}\left(a(x,y)\frac{w_{\pm}^{p}(x)}{|x-y|^{n+(s-1)p}}+ b(x,y)\frac{w_{\pm}^{p}(x)}{|x-y|^{n+(t-1)p}}\right)\,dx\,dy \\
& \quad\; + c\left(\frac{r}{r-\rho}\right)^{n+tp}T(w_{\pm};r,r)\int_{B_{r}}w_{\pm}\,dx
\end{aligned}
\end{equation}
holds whenever $B_{\rho} \subset  B_{r} \Subset \Omega$ are concentric balls, where $w_{\pm} \coloneqq (u-k)_{\pm}$ for any $k\in\mathbb{R}$.
Moreover, estimate \eqref{caccio.2} continues to hold for $w_{+}$ (resp. $w_{-}$) when $u$ is merely a weak subsolution (resp. supersolution) to \eqref{main.eq}.
\end{lemma}

