G_{B_{r}}(\tau) \coloneqq \sup_{x,y\in B_{r}}\left(a(x,y)\frac{\tau^{p}}{r^{sp}} + b(x,y)\frac{\tau^{p}}{r^{tp}}\right), \qquad g_{B_{r}}(\tau) \coloneqq \frac{G_{B_{r}}(\tau)}{\tau}, \qquad \tau \ge 0.
\end{equation}
then we have
\begin{align}\label{alt.dG}
b^{+}_{B_r} \le \frac{\nu}{4} & \;\; \Longrightarrow \;\; G_{B_r}(\tau) \approx \frac{\tau^p}{r^{sp}} + b^+_{B_r}\frac{\tau^p}{r^{tp}}\approx \frac{\tau^p}{r^{sp}} + b^-_{B_r}\frac{\tau^p}{r^{tp}},
\end{align}
\begin{align}\label{alt.G}
b^{+}_{B_r} > \frac{\nu}{4} & \;\; \Longrightarrow \;\; G_{B_r}(\tau) \approx \frac{\tau^p}{r^{tp}}.
\end{align}
\end{remark}

We next introduce the nonlocal tail, which is one of the essential tools in analyzing local regularity for fractional equations. 
For $f:\mathbb{R}^{n}\rightarrow \mathbb{R}$, $x_{0} \in \mathbb{R}^{n}$ and $r,\rho>0$, we denote
\begin{equation}\label{def.T}
T(f;x_{0},r,\rho) \coloneqq \sup_{x \in B_{\rho}(x_{0})}\int_{\mathbb{R}^{n}\setminus B_{r}(x_{0})}\left(a(x,y)\frac{|f(y)|^{p-1}}{|y-x_{0}|^{n+sp}} + b(x,y)\frac{|f(y)|^{p-1}}{|y-x_{0}|^{n+tp}}\right)\,dy.
\end{equation}
We will omit the point $x_{0}$ if it is clear from context.

With the definitions of weak solutions and relevant function spaces to be introduced in the next section, here we state our main results.

\begin{theorem}[Harnack inequality]\label{thm.harnack}
Let $u \in \mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak solution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{assumption.hol} with $a(\cdot,\cdot)\equiv 1$. If $u$ is nonnegative in a ball $B_{10r} \Subset \Omega$ with $10r \leq R_{0}$, where $R_{0}$ is given in \eqref{R0.choice}, then we have
\begin{equation}\label{Harnack}
\sup_{B_{r}}u \le c\inf_{B_{r}}u + cg_{B_{r}}^{-1}(T(u_{-};10r,10r)) 
\end{equation}
for a constant $c \equiv c(n,s,t,p,\nu,L,\alpha,[b]_{\alpha})>0$.
\end{theorem}
\begin{remark}
In Theorem~\ref{thm.harnack}, the condition $a(\cdot,\cdot)\equiv 1$ can be weakened as $\inf_{\mathbb{R}^n \times \mathbb{R}^n}a(\cdot,\cdot)>0$. Such a restriction is concerned with the tail estimate given in Lemma~\ref{tail.pm} below. 
Indeed, even if $a(\cdot,\cdot)\not\equiv1$, we can prove an estimate similar to \eqref{Harnack} which involves nonlocal tails of $u$ instead of $u_{-}$. 
However, in view of the natural Harnack inequalities obtained in \cite{coz,DKP14,Kas11}, we confine ourselves to the case $a(\cdot,\cdot)\equiv1$ in Theorem~\ref{thm.harnack}. 
\end{remark}

\begin{lemma}\label{caccioppoli2}
Let $u\in\mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak solution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{a.bound}. 
There exists a constant $c\equiv c(n,s,t,p,\nu,L)>0$ such that
\begin{equation}\label{caccio.2}
\begin{aligned}
& \int_{B_{\rho}}\int_{B_{\rho}}\left(a(x,y)\frac{|w_{\pm}(x)-w_{\pm}(y)|^{p}}{|x-y|^{n+sp}} + b(x,y)\frac{|w_{\pm}(x)-w_{\pm}(y)|^{p}}{|x-y|^{n+tp}}\right)\,dx\,dy \\
& \le \frac{c}{(r-\rho)^{p}}\int_{B_{r}}\int_{B_{r}}\left(a(x,y)\frac{w_{\pm}^{p}(x)}{|x-y|^{n+(s-1)p}}+ b(x,y)\frac{w_{\pm}^{p}(x)}{|x-y|^{n+(t-1)p}}\right)\,dx\,dy \\
& \quad\; + c\left(\frac{r}{r-\rho}\right)^{n+tp}T(w_{\pm};r,r)\int_{B_{r}}w_{\pm}\,dx
\end{aligned}
\end{equation}
holds whenever $B_{\rho} \subset B_{r} \Subset \Omega$ are concentric balls, where $w_{\pm} \coloneqq (u-k)_{\pm}$ for any $k\in\mathbb{R}$.
Moreover, estimate \eqref{caccio.2} continues to hold for $w_{+}$ (resp. $w_{-}$) when $u$ is merely a weak subsolution (resp. supersolution) to \eqref{main.eq}.
\end{lemma}

\begin{lemma}\label{density.improve}
Let $u \in \mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak supersolution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{assumption.hol}, which is nonnegative in a ball $B_{R} \equiv B_{R}(x_{0}) \Subset \Omega$ with $R \le R_{0}$. Let $k > 0$ and assume that there exists $\sigma \in (0,1]$ satisfying
\begin{equation}\label{density.assumption}
|B_{2r} \cap \{ u \ge k \}| \ge \sigma|B_{2r}| \qquad \text{for some} \quad r \in (0,R/4].
\end{equation}
Then there exists a constant $\delta \equiv \delta(\data,\sigma) \in (0,1/4)$ such that if
\begin{equation}\label{T.assumption}
d \coloneqq \left[\frac{1}{G_{B_{2r}}(1)}T(u_{-};R,2r) \right]^{1/(p-1)} = g_{B_{2r}}^{-1}(T(u_{-};R,2r)) \le \delta k,
\end{equation}
then
\begin{equation}\label{lower.bound}
\essinf_{B_{r}}u \ge \delta k.
\end{equation}
\end{lemma}
\begin{proof}
We divide the proof into two steps.

Using Lemmas~\ref{density.improve} and \ref{KrySaf}, we obtain a weak Harnack type estimate.
\begin{lemma}\label{weak.harnack}
Let $u\in\mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak supersolution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{assumption.hol} with $a(\cdot,\cdot)\equiv 1$, which is nonnegative in a ball $B_{10r} \equiv B_{10r}(x_{0}) \Subset \Omega$ with $10r \le R_{0}$. Then there exist constants $p_{0} \in (0,1)$ and $c \ge 1$, both depending only on $\data$, such that 
\begin{equation*}
\left(\mean{B_{2r}}u^{p_{0}}\,dx\right)^{1/p_{0}} \le c \essinf_{B_{r}}u + cg_{B_{6r}}^{-1}(T(u_{-};10r,10r)). 
\end{equation*}
\end{lemma}
\begin{proof}
We set $\bar{\delta} \coloneqq 2^{-n-1}$ and $T_{0}\coloneqq c_{2}g_{B_{6r}}^{-1}(T(u_{-};10r,10r))$, with $c_{2}\equiv c_{2}(\data)$ being a constant whose precise value will be determined in \eqref{dT} below. 
For each $i \in \mathbb{N}\cup\{0\}$ and $\tau>0$, we define
\begin{equation*}
A^{i}_{\tau} \coloneqq \left\{ x\in B_{2r}:u(x)>\tau\delta^{i}-\frac{T_{0}}{1-\delta}\right\},
\end{equation*}
where $\delta \equiv \delta(\data) \in (0,1/4)$ is the constant determined in Lemma~\ref{density.improve} in the case $\sigma=\bar{\delta}/6^{n}$. 
It is obvious that $A^{i-1}_{\tau} \subset A^{i}_{\tau}$.

The following lemma allows us to capture the precise tail contribution in the Harnack inequality.
\begin{lemma}\label{tail.pm}
Let $u \in \mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak solution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{assumption.hol} with $a(\cdot,\cdot) \equiv 1$, which is nonnegative in a ball $B_{R}\equiv B_{R}(x_{0}) \Subset \Omega$ with $R\le R_{0}$. Then 
\[ T(u_{+};r,2r) \le cg_{B_{r}}\left(\sup_{B_{r}}u\right) + cT(u_{-};R,r) \]
holds for any $r\in(0,R/2]$, where $c\equiv c(\data)>0$.
\end{lemma}
\begin{proof}
We set $w \coloneqq u-2k$ for $k \coloneqq \sup_{B_{r}}u$, and take a cut-off function $\phi \in C^{\infty}_{0}(B_{r})$ such that $\supp\,\phi \subseteq B_{3r/4}$, $0 \le \phi \le 1$, $\phi \equiv 1$ in $B_{r/2}$ and $|D\phi| \le 8/r$. Recalling the notation \eqref{phip}, we test \eqref{main.eq} with $w\phi^{p}$ in order to have
\begin{equation}\label{test}
\begin{aligned}
0 & = \int_{B_{r}}\int_{B_{r}}\Phi_{p}(u(x)-u(y))(w(x)\phi^{p}(x)-w(y)\phi^{p}(y))\left[K_{sp}(x,y) + b(x,y)K_{tp}(x,y)\right] \,dx\,dy \\
& \quad\; + 2\int_{\mathbb{R}^{n}\setminus B_{r}}\int_{B_{r}}\Phi_{p}(u(x)-u(y))w(x)\phi^{p}(x)\left[K_{sp}(x,y) + b(x,y)K_{tp}(x,y)\right]\,dx\,dy \\
& \eqqcolon I_{1} + I_{2}.
\end{aligned}
\end{equation}
We first estimate $I_{1}$. By the calculations done in the proof of \cite[Lemma 4.2]{BOS}, we have
\begin{equation*}
\begin{aligned}
& \Phi_{p}(w(x)-w(y))(w(x)\phi^{p}(x)-w(y)\phi^{p}(y)) \\
& \ge \frac{1}{4}|w(x)-w(y)|^{p}(\phi^{p}(x)+\phi^{p}(y)) - c|\phi(x)-\phi(y)|^{p}(w(x)+w(y))^{p} \\
& \ge -ck^{p}\frac{|x-y|^{p}}{r^{p}}
\end{aligned}
\end{equation*}
and therefore
\begin{equation}\label{I1}
\begin{aligned}
I_{1} & \ge -c\int_{B_{r}}\int_{B_{r}}\left(\frac{k^{p}}{r^{p}}\frac{1}{|x-y|^{n+(s-1)p}} + b(x,y)\frac{k^{p}}{r^{p}}\frac{1}{|x-y|^{n+(t-1)p}}\right)\,dx\,dy \\
& \ge -c\left(k^{p}r^{n-sp} + b^{+}_{B_{r}}k^{p}r^{n-tp}\right) \\
& \ge -cr^{n}G_{B_{r}}(k).
\end{aligned}
\end{equation}
We next split $I_{2}$ as
\begin{equation}\label{I2.split}
\begin{aligned}
I_{2} & \ge 2 \int_{\mathbb{R}^{n}\setminus B_{r}}\int_{B_{r}}k(u(y)-k)_{+}^{p-1}\phi^{p}(x)\left[K_{sp}(x,y) + b(x,y)K_{tp}(x,y)\right]\,dx\,dy \\
& \quad\; -2\int_{\mathbb{R}^{n}\setminus B_{r}}\int_{B_{r}}2k\chi_{\{u(y)<k\}}(u(x)-u(y))_{+}^{p-1}\phi^{p}(x)\left[K_{sp}(x,y) + b(x,y)K_{tp}(x,y)\right]\,dx\,dy \\
& \eqqcolon I_{2,1} - I_{2,2}.
\end{aligned}
\end{equation}
We note that 
\[ \frac{1}{4}|y-x_{0}| \le |y-x_{0}| - |x-x_{0}| \le |x-y| \le |x-x_{0}| + |y-x_{0}| \le \frac{7}{4}|y-x_{0}|\] 
for any $x\in B_{3r/4}$ and $y\in\mathbb{R}^{n}\setminus B_{r}$,
in order to estimate $I_{2,1}$ as
\begin{equation}\label{I21}
\begin{aligned}
I_{2,1} & \ge \frac{k}{c}\int_{\mathbb{R}^{n}\setminus B_{r}}\int_{B_{r}}\left(\frac{(u_{+}(y))^{p-1}}{|x-y|^{n+sp}}+b(x,y)\frac{(u_{+}(y))^{p-1}}{|x-y|^{n+tp}}\right)\phi^{p}(x)\,dx\,dy \\
& \quad\; - c\int_{\mathbb{R}^{n}\setminus B_{r}}\int_{B_{r}}\left(\frac{k^{p}}{|x-y|^{n+sp}} + b(x,y)\frac{k^{p}}{|x-y|^{n+tp}}\right)\phi^{p}(x)\,dx\,dy \\
& \ge \frac{kr^{n}}{c}\int_{\mathbb{R}^{n}\setminus B_{r}}\left(\frac{(u_{+}(y))^{p-1}}{|y-x_{0}|^{n+sp}} + \inf_{B_{r/2}}b(\cdot,y)\frac{(u_{+}(y))^{p-1}}{|y-x_{0}|^{n+tp}}\right)\,dy - cr^{n}G_{B_{r}}(k).
