\nonumber
p < 2 + \frac{8}{3n-2} & \qquad \textrm{if $n$ is even.}
\end{align}
\end{theorem}

Estimates for oscillatory integral operators satisfying the cinematic curvature condition are closely related to several central problems in modern harmonic analysis, most notably the local smoothing problem and the cone restriction problem. These operators, by incorporating variable coefficients and geometric curvature conditions, provide a unifying analytic framework that captures many classical oscillatory phenomena while extending beyond the constant-coefficient cone scenario. Because sharp bounds in this setting would deepen our understanding of decoupling, restriction, and dispersive regularity estimates, progress on this problem has the potential to inform a broad range of techniques in Fourier analysis, partial differential equations, and geometric measure theory. Accordingly, the study of such estimates carries substantial intrinsic value, both from a conceptual standpoint and in terms of possible applications to longstanding conjectures in harmonic analysis.
\bigskip

\subsection{Structure of the article}

The structure of this paper is as follows. In Section \ref{necessary condition} , we construct a counterexample demonstrating that the estimate \eqref{linear estimate} may fail when $p$ lies inside the range \eqref{necessary range}. Section \ref{section-preliminary} presents several preliminary reductions and methodological tools, including the narrow–broad argument and wave packet decomposition. Section \ref{section-algorithm} is devoted to the two-ends reduction. In Section \ref{concludetheproof}, we complete the proof of the main theorem. Finally, Section \ref{epsilon removal} establishes an $\varepsilon$-removal lemma for oscillatory integral operators satisfying the cinematic curvature condition.

\bigskip

\subsection{Notations} We write $\#E$ for the cardinality of a finite set $E$. If $\mathcal{E}$ is a family of sets in $\mathbb{R}^n$, we use $\cup \mathcal{E}$ to denote $\bigcup_{E \in \mathcal{E}} E$. For $A,B \ge 0$, we write $A \lesssim B$ to mean $A \le C B$ for some absolute constant $C$, and $A \sim B$ to mean both $A \lesssim B$ and $B \lesssim A$. For $R>1$, we write $A \lesssim_\eta B$ to indicate that $A \le C_\eta R^\eta B$ for all $\eta>0$. We use $\mathrm{RapDec}(R)$ to denote a rapidly decaying quantity, meaning that for all $R \ge 1$,
\[
\mathrm{RapDec}(R) \le C_N R^{-N} \qquad \textrm{for some very large $N$} .
\]

Finally, for a set $X$, we write $N_r(X)$ for its $r$-neighborhood.
\medskip

\subsection{Choice of Parameters} \(0 < \varepsilon \ll 1,\ 1 \leq R \leq \lambda,\ \
K = R^{\varepsilon^{50}},\ K_{\circ} = R^{\varepsilon^{100}},\ \kappa = R^{\varepsilon^{500}},\ 
\delta = \varepsilon^{1000}.\) With this choice of parameters, we obtain
\[
R^{\delta} \ll \kappa \ll K_{\circ} \ll K \ll R \leq \lambda .
\]
\medskip

\subsection{Acknowledgments} The author would like to express sincere gratitude to Prof. Xiaochun Li for suggesting this research topic, for numerous insightful discussions, and for carefully reading earlier versions of this manuscript. His guidance and suggestions were invaluable throughout the development of this work. The author is also grateful to Prof. Shukun Wu for several helpful conversations and constructive comments that contributed to clarifying some technical aspects of this paper.

\bigskip

\section{Necessary Conditions} \label{necessary condition}
In this section, we examine an example of oscillatory integral operators that satisfy the cinematic curvature condition, with the aim of demonstrating the necessity of the $p$-range stated in Theorem \ref{main conjecture}. The construction is motivated by the work of Bourgain–Guth \cite{BG} (see also \cite{MS} \cite{Wisewell} \cite{GHI}) and is closely related to the Kakeya compression phenomenon, in which a large collection of tubes is efficiently packed into a neighbourhood of a low-dimensional set.

Define $\bm{A}: \mathbb{R} \rightarrow \mathrm{Sym}(n-2, \mathbb{R})$ by
\begin{equation*}
\bm{A}(t) := 
\begin{cases}
\underbrace{\begin{pmatrix}
t & t^2 \\
t^2 & t + t^3
\end{pmatrix}
\oplus \dots \oplus 
\begin{pmatrix}
t & t^2 \\
t^2 & t + t^3
\end{pmatrix}}_{\text{$\lfloor \frac{n-2}{2} \rfloor$-fold}}
\oplus \,(t),
& \text{if $n$ is odd}, \\[4pt]
\underbrace{\begin{pmatrix}
t & t^2 \\
t^2 & t + t^3
\end{pmatrix}
\oplus \dots \oplus 
\begin{pmatrix}
t & t^2 \\
t^2 & t + t^3
\end{pmatrix}}_{\text{$\lfloor \frac{n-2}{2} \rfloor$-fold}},
& \text{if $n$ is even}.
\end{cases}
\end{equation*}

Let $a$ be a bump function such that $a(x,\xi) = 1$ for all $(x,\xi) \in B^n_{1/2}(0) \times 0.8\mathbb{A}$ where
\[0.8\A:=\{ (\xi',\xi_{n-1})\in\R^{n-1}: 1.1\le \xi_{n-1}\le 1.9, |\xi'|\le 0.8\xi_{n-1} \}. \] and
\begin{equation*}\label{model phase}
\phi(x',x_n;\xi',\xi_{n-1}) := \langle x', (\xi',\xi_{n-1}) \rangle + \frac{1}{2\xi_{n-1}}\langle \bm{A}(x_n)\xi', \xi'\rangle
\end{equation*}
We claim that $\phi$ satisfies \textbf{(H1)}, \textbf{(H2)} and \textbf{(H3)}. 
\begin{proposition} 
$\phi$ satisfies \textbf{(H1)}, \textbf{(H2)} and \textbf{(H3)}.
\end{proposition}
\begin{proof}
It is clear that $\phi$ satisfies \textbf{(H1)} and \textbf{(H2)}. Therefore, it remains to verify that $\phi$ also satisfies \textbf{(H3)}. For any $x =(x',x_n) \in B^n_1(0)$ and $\xi = (\xi',\xi_{n-1}),\xi_0 = (\xi_0',\xi_{0,n-1})\in \mathbb{A}$,
\begin{align*}
\partial_x \phi(x,\xi) = (\xi,\frac{\langle A'(x_n)\xi',\xi' \rangle}{2\xi_{n-1}}), \qquad
G(x,\xi_0) = C(x,\xi_0)(-\frac{A'(x_n)\xi_0'}{\xi_{0,n-1}},\frac{A(x_n)\xi_0'}{\xi^2_{0,n-1}},1)
\end{align*}
where $C(x,\xi_0) > 0$ denotes a normalization constant. Now
\begin{equation*}
    \partial^2_{\xi\xi}\langle \partial_ \phi(x,\xi),G(x,\xi_0) \rangle|_{\xi=\xi_0} = \frac{C(x,\xi_0)}{\xi_{0,n-1}}\begin{pmatrix}
    A'(x_n) & -\frac{A'(x_n)\xi_0'}{\xi_{0,n-1}} \\
    -(\frac{A'(x_n)\xi_0'}{\xi_{0,n-1}})^\top & \frac{\langle A'(x_n)\xi_0',\xi_0' \rangle}{\xi_{0,n-1}^2}
    \end{pmatrix}
\end{equation*}
Let
\begin{equation*}
    M = \begin{pmatrix}
    A'(x_n) & -\frac{A'(x_n)\xi_0'}{\xi_{0,n-1}} \\
    -(\frac{A'(x_n)\xi_0'}{\xi_{0,n-1}})^\top & \frac{\langle A'(x_n)\xi_0',\xi_0' \rangle}{\xi_{0,n-1}^2}
    \end{pmatrix}
\end{equation*}
It remains to show that $M$ has rank $n-2$ with $n-2$ positive eigenvalues. Obviously, the rank of this matrix is $n-2$. In addition, for any $v=(v',v_{n-1}) \in \mathbb{R}^{n-1}$ with $v \ne 0$
\begin{equation*}
v^\top M v = \\ 
    \left(v'- \frac{A'(x_n)\xi_0'}{\xi_{0,n-1}}v_{n-1}\right)^\top A'(x_n) \left(v'- \frac{A'(x_n)\xi_0'}{\xi_{0,n-1}}v_{n-1}\right) \geq 0
\end{equation*}
since $A'(x_n)$ is positive definite. This finishes the proof. 
\end{proof}
\medskip
Cover $B^{n-2}_{4/5}(0)$ by finite-overlapping caps $\theta$ of diameter $\sim\lambda^{-1/2}$. Let $\{\psi_\theta\}$ be a smooth partition of unity subordinate to this cover. For each $\theta$ let $\omega_\theta$ denote the center of $\theta$ and define $f_\theta: \mathbb{R}^{n-1} \rightarrow \mathbb{R}$ by
\begin{equation*}
    f_\theta(\xi',\xi_{n-1})
:=
\begin{cases}
e^{2\pi i \lambda \langle v_\theta,\xi \rangle}
\,\psi_\theta(\xi'/\xi_{n-1}),
& \text{if } (\xi',\xi_{n-1}) \in \mathbb{A}, \\[4pt]
0,
& \text{otherwise}.
\end{cases}
\end{equation*}
where $\xi = (\xi',\xi_{n-1})$ and
\begin{equation*}
    v_{\theta,2j-1} := -\omega_{\theta,2j}, \qquad  v_{\theta,2j} = v_{\theta,n-2} = v_{\theta,n-1} =0, \qquad \mathrm{for} \quad 1\leq j \leq \left\lfloor \frac{n-2}{2} \right\rfloor
\end{equation*}
For $(u',u_{n-1},x_n) \in B^n_\lambda(0)$ let
\begin{equation*}
\gamma^\lambda_\theta(u',u_{n-1},x_n) := (u'-\lambda\mathbb{A}(\frac{x_n}{\lambda})\omega_\theta, u_{n-1}+\frac{\lambda}{2}\langle \mathbb{A}(\frac{x_n}{\lambda})\omega_\theta,\omega_\theta\rangle) 
\end{equation*}
Let $\tilde{\theta} \subset \mathbb{R}^{n-1}$ be a box of dimensions $1 \times \lambda^{-1/2} \times ...\times \lambda^{-1/2}$ such that
\begin{equation*}
\{(\xi',\xi_{n-1}):\frac{\xi'}{\xi_{n-1}} \in \theta, 1 \leq \xi_{n-1} \leq 2\} \subset \tilde{\theta}
\end{equation*}
and $\bar{T}_\theta$ denote the dual box of $\tilde{\theta}$ centered at $\lambda v_\theta$. Define $T_\theta \subset \mathbb{R}^n$ by
\begin{equation*}
T_\theta := \{(\gamma^\lambda_\theta(u,x_n),x_n):u \in \lambda^\delta \bar{T}_\theta\ ,\quad -\lambda \leq x_n \leq \lambda\} \cap B^n_\lambda(0)
\end{equation*}

For each $\theta$, there exists a significant portion of $T_\theta$ that guarantees $T^\lambda f_\theta$ maintains a nontrivial size. 
\begin{proposition}\label{lower bound}
For each $\theta$ there exists $S \subset T_\theta$ such that $|S| \gtrsim \lambda^{n/2}$ and for all $x \in S$
\begin{equation}\label{lower bound example}
T^\lambda f_\theta(x) \gtrsim \lambda^{-O(\delta)-\frac{n-2}{2}}
\end{equation}
\end{proposition}
\begin{proof}
Fix $t \in [-\lambda/2,\lambda/2]$ and define $T_{\theta,t} := T_\theta \cap \{x_n=t\}$. It suffices to show that there exists $S_t \subset T_{\theta,t}$ with $|S_t| \gtrsim \lambda^{\frac{n-2}{2}}$ and \eqref{lower bound example} holds for all $x \in S_t$. Since
\begin{equation*}
T^\lambda f_\theta(x',t) = \int e^{-2\pi i \langle x',\xi \rangle} e^{-\frac{\pi i}{\xi_{n-1}}\langle \bm{A}(t/\lambda)\xi', \xi'\rangle} a^\lambda(x',t,\xi)f_\theta(\xi)d\xi = \hat{f_{\theta,x',t}}(x')
\end{equation*}
where
\begin{equation*}
f_{\theta,x',t}(\xi) =e^{-\frac{\pi i}{\xi_{n-1}}\langle \bm{A}(t/\lambda)\xi', \xi'\rangle} a^\lambda(x',t,\xi) f_\theta(\xi)
\end{equation*}
Since $T^\lambda f_\theta$ is essentially supported in $T_\theta$ (see Lemma \ref{lemsuppT}), the Plancherel theorem gives
\begin{equation} \label{plancherel 1}
\|T^\lambda f_\theta\|^2_{L^2(T_{\theta,t})} \sim \|f_\theta\|^2_{L^2(\mathbb{R}^{n-1})} \sim \lambda^{-\frac{n-2}{2}}
\end{equation}
Also,
\begin{equation}\label{upper bound example}
|T^\lambda f_\theta| \leq  \int f_\theta \leq \lambda^{-\frac{n-2}{2}}
\end{equation}
Let $S_t$ be the set of all points in $T_{\theta,t}$ satisfying \eqref{lower bound example}. By \eqref{plancherel 1} and \eqref{upper bound example},
\begin{equation*}
\lambda^{-\frac{n-2}{2}} \lesssim \|T^\lambda f_\theta\|^2_{L^2(T_{\theta,t})} \lesssim |S_t| \lambda^{-(n-2)}
\end{equation*}
Thus, $|S_t| \gtrsim \lambda^{\frac{n-2}{2}}$.
\end{proof}
\medskip
By a slight abuse of notation, we continue to use $T_\theta$ to denote this significant portion. Thus,
\begin{equation}
T^\lambda f_\theta \gtrsim \lambda^{-O(\delta)-\frac{n-2}{2}} \chi_{T_\theta}
\end{equation}

Next, we show that $\bigcup_{\theta:\lambda^{-1/2}\mathrm{-cap}} T_\theta$ is contained in a neighborhood of a low-dimensional set, illustrating the Kakeya compression phenomenon. 
\begin{proposition} \label{KakeyaCompress}
There exists an algebraic variety $Z$ of dimension $m:=n-\lfloor\frac{n-2}{2}\rfloor$ and degree $O_n(1)$ such that
\begin{equation} \label{kacompress}
\bigcup_{\theta:\lambda^{-1/2}\mathrm{-cap}} T_\theta \subset N_{\lambda^{1/2+\delta}}(Z) \cap B^n_\lambda(0)
\end{equation}
\end{proposition}
\begin{proof}
Let 
\begin{equation*}
c(T_\theta) := \{(\gamma^\lambda_\theta(\lambda v_\theta,x_n),x_n):,\quad -\lambda \leq x_n \leq \lambda\} \cap B^n_\lambda(0)
\end{equation*}
denote the center of $T_\theta$. A direct computation gives that $c(T_\theta)$ lies in the common zero set $Z$ of the polynomials
\begin{equation*}
P_j:=\lambda x_{2j} - x_{2j-1}x_n \qquad \mathrm{for} \quad 1 \leq j \leq \lfloor\frac{n-2}{2}\rfloor
\end{equation*}
for all $\theta$. Since $T_\theta \subset N_{\lambda^{1/2+\delta}}(c(T_\theta))$, it follows that \eqref{kacompress} holds.
\end{proof}
\medskip
We now construct a function $f$ that causes estimate \eqref{linear estimate} to fail whenever $p$ lies in the range\eqref{necessary range}. 
\begin{proposition}
There exists a map $\epsilon: \{\theta\} \mapsto \{-1,1\}$ such that
\begin{equation*}
f := \sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} \epsilon(\theta)f_\theta
\end{equation*}
forces estimate \eqref{linear estimate} to fail whenever $p$ lies within the range\eqref{necessary range}.
\end{proposition}
\begin{proof}
Let $\epsilon_\theta$ be uniformly distributed independent random signs and
\begin{equation*}
    f := \sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} \epsilon_\theta f_\theta
\end{equation*}
For $x \in B_{\lambda}^n(0)$ Khintchine’s theorem (see \cite{Yang}, page 44) gives,
\begin{equation} \label{2.6}
    \mathbb{E}[|T^\lambda f(x)|] \sim (\sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} |T^\lambda f_\theta(x)|^2)^{1/2} \gtrsim \lambda^{-O(\delta)-\frac{n-2}{2}} (\sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} \chi_{T_\theta})^{1/2}
\end{equation}
Let $p > 2$. 
By H\"older inequality and Proposition \ref{lower bound},
\begin{multline}\label{2.7}
    \| (\sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} \chi_{T_\theta})^{1/2} \|_{L^p(\mathbb{R}^n)} |\bigcup_{\theta:\lambda^{-1/2}\mathrm{-cap}}T_\theta|^{1/2-1/p}\geq \\ \| (\sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} \chi_{T_\theta})^{1/2} \|_{L^2(\mathbb{R}^n)} \gtrsim \lambda^{\frac{n-1}{2}}
\end{multline}
By Proposition \ref{KakeyaCompress},
\begin{equation} \label{2.8}
    |\bigcup_{\theta:\lambda^{-1/2}\mathrm{-cap}}T_\theta|^{1/2-1/p} \lesssim \lambda^{\frac{n+m}{2}(\frac{1}{2}-\frac{1}{p})+O(\delta)}
\end{equation}
By Minkowski’s inequality, \eqref{2.7} and \eqref{2.8},
\begin{equation*}
    \mathbb{E}[\|T^\lambda f\|_{L^p(\mathbb{R}^n)}] \geq \| \mathbb{E}[|T^\lambda f|] \|_{L^p(\mathbb{R}^n)} \gtrsim \lambda^{-O(\delta)+\frac{1}{2}-\frac{n+m}{2}(\frac{1}{2}-\frac{1}{p})}
\end{equation*}
Thus, there exists a map $\epsilon: \{\theta\} \mapsto \{-1,1\}$ such that $f := \sum_{\theta:\lambda^{-1/2}\mathrm{-cap}} \epsilon(\theta)f_\theta $ satisfies
\begin{equation} \label{2.9}
    \|T^\lambda f\|_{L^p(\mathbb{R}^n)} \gtrsim \lambda^{-O(\delta)+\frac{1}{2}-\frac{n+m}{2}(\frac{1}{2}-\frac{1}{p})}
\end{equation}
Suppose the estimate \eqref{linear estimate}) holds. Since $\|f\|_{L^p(\mathbb{R}^{n-1})} \sim 1$, \eqref{2.9} gives
\[\lambda^{-O(\delta)+\frac{1}{2}-\frac{n+m}{2}(\frac{1}{2}-\frac{1}{p})} \lesssim 1\]
which is equivalent to
\[p \geq 2+\frac{4}{n+m-2}\]
\end{proof}
\medskip
This gives Theorem \ref{main conjecture}.
Observe that when $n \leq 5$, the Knapp example yields a larger range of exponents for which estimate \eqref{linear estimate} may fail. Consequently, the necessary conditions established in this paper are not optimal. It is reasonable to anticipate that a sharper counterexample will be identified in subsequent work.

\bigskip

\section{Preliminaries}\label{section-preliminary}

In this section, we introduce the notation and basic properties for oscillatory integral operators satisfying the cinematic curvature condition. Throughout the remainder of the paper, we write $x=(x',x_n)\in \R^n$ and $\xi=(\xi',\xi_{n-1})\in\R^{n-1}$.

\subsection{Some Basic Reductions}\label{subsecquant}
One can reduce Proposition \ref{epsilon main theorem} to the case  $1 \le R \le \lambda^{1-\varepsilon}$ and $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$. Moreover, after an appropriate rescaling, we may further assume that $B^n_R=B^n_R(0)$ and
\begin{equation} \label{assumpetion 1}
    \|\partial_{x,\xi}^\beta a\|_{L^\infty(B^n_1(0) \times \mathbb{A})} \lesssim_\beta 1\qquad \textrm{for all $1 \leq |\beta| \leq N$.} 
\end{equation}
where $N=N_{\e,M,p}\in\N$ is some large number depending only on the dimension $n$ and the fixed choice of $\e,M$ and $p$. Hence, to prove Proposition \ref{epsilon main theorem},it suffices to show that:
\begin{proposition} \label{reduction 1}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition. Then the estimate
\begin{equation*}
    \|T^{\lambda}f\|_{L^p(B^n_R(0))} \lesssim_{\phi,\varepsilon,p} R^\varepsilon \|f\|_{L^{p}(B^{n-1})}
\end{equation*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$, provided that the amplitude $a$ satisfies \eqref{assumpetion 1} and the exponent $p$ lies in the range \eqref{range of result}.
\end{proposition}

To obtain uniform estimates for a family of oscillatory integral operators satisfying the cone condition, it is necessary to strengthen Proposition \ref{reduction 1} This strengthening is essential for implementing an induction-on-scales argument, since a single operator $T^\lambda$ is not stable under rescaling. Nevertheless, the rescaling procedure preserves certain structural features of this class of operators, allowing one to carry out the induction simultaneously over a larger family. In what follows, we work within the framework introduced in \cite[Section 2.3]{BHS}.

Fix a small constant $\cpar>0$ be a small fixed constant. For $\bA=(A_1,A_2,A_3)\in[1,\infty)^3$, we impose the following conditions on the phase function:

\begin{enumerate}
    \item[$(\text{H1}_{\bA})$]  $\|\partial^2_{\xi x'}\phi(x;\xi)-I_{n-1}\|_{\mathrm{op}}\le \cpar A_1$ for all $(x;\xi)\in B^n_1(0)\times \mathbb{A}$.
    \item[$(\text{H2}_{\bA})$] $\|\partial^2_{\xi'\xi'}\partial_{x_n}\phi(x;\xi)-\frac{1}{\xi_{n-1}}I_{n-2}\|_{\mathrm{op}}\le \cpar A_2$ for all $(x;\xi)\in B^n_1(0)\times \mathbb{A}$.
    \item[$(\textup{D1}_\bA)$]$\|\partial_\xi^\beta\partial_{x_k}\phi\|_{L^\infty(B_1^n(0)\times \mathbb{A})}\le \cpar A_1$ for all $1\le k\le n-1$ and $\beta\in\N_0^{n-1}$ with $2\le|\beta|\le 3$ satisfying $|\beta'|\ge 2$;

    \noindent $\|\partial_{\xi'}^{\beta'}\partial_{x_k}\phi\|_{L^\infty(B_1^n(0)\times \mathbb{A})}\le \frac{\cpar}{2n} A_1$ for all $1\le k\le n-1$ and $\beta'\in\N_0^{n-2}$ with $|\beta'|=3$. 
    \item[$(\textup{D2}_\bA)$] $
        \|\partial_\xi^\beta\partial_z^\al\phi\|_{L^\infty(B_1^n(0)\times \mathbb{A})}\le \frac{\cpar}{2n}A_3 $
    for all $(\al,\beta)\in\N_0^n\times \N_0^{n-1}$ with $2\le |\al|\le 4N$ and $1\le |\beta|\le 4N+2$ satisfying $1\le |\beta|\le 4N$ or $|\beta'|\ge 2$. 
    \item[$(\textup{M}_\bA)$] $\dist(\supp_x a, \R^n\setminus B_1^n)\ge \frac{1}{4A_3}$.

\end{enumerate}

\medskip

A pair $(\phi,a)$ is said to be of \textit{type} $\bA$ if it satisfies the conditions $(\textup{H1}_\bA),(\textup{H2}_\bA),\\(\textup{D1}_\bA),(\textup{D2}_\bA)$ and $(\textup{M}_\bA)$ (in addition to (\textbf{H1}) and (\textbf{H2})) is said to be of \textit{type} $\bA$. By decomposing the amplitude function and applying suitable rescaling arguments, one may reduce to the normalized case $\bA=\mathbf{1}:=(1,1,1)$; see \cite[Section 2.5]{BHS} for details.

In the remainder of this paper, we assume that the operator $T^\lambda$ is of type \textbf{1}. Under this normalization, Proposition \ref{reduction 1} admits the following strengthened formulation.

\begin{proposition}\label{main theorem type 1}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1}, then for all $p$ satisfies \eqref{main range}, the estimate
\begin{equation*}
    \|T^{\lambda}f\|_{L^p(B_R^n(0))} \lesssim_{\varepsilon,p,\phi}R^\varepsilon \|f\|_{L^{p}(\mathbb{R}^{n-1})}
\end{equation*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$.
\end{proposition}

\bigskip

\subsection{Wave packet decomposition}

Fix $0<\e \ll 1$. In this subsection, we recall the wave packet decomposition for a function $f \in \mathcal{S}(\mathbb{R}^{n-1})$ at scale $R$ satisfying $1 \ll R \leq \la^{1-\e}$, following the presentation in \cite[Section 3.3]{GW}. 

Condition \textbf{(H1)} guarantees that the mapping
$\partial_\xi \phi(\cdot, x_n; \xi)$ is locally invertible. More precisely, for each
fixed pair $(x_n,\xi)$, the map $x' \mapsto \partial_\xi \phi(x;\xi)$ has a
non-vanishing Jacobian determinant. After a suitable rescaling, we may further assume
that
\begin{equation} \label{assumption2}
\partial_\xi \phi(\cdot, x_n; \xi) \quad \text{defines a diffeomorphism on}\quad
B_1^{n-1}(0) \quad \text{for all} (x_n,\xi) \in [-1,1] \times \mathbb{A}. 
\end{equation}
Consequently, this
mapping admits a well-defined inverse, which we introduce below.

\begin{definition} \cite[Definition 3.3]{GW}
    For $(x_n,\xi)\in [-1,1]\times \mathbb{A}$, let $\Phi(u,x_n;\xi)$ be the unique solution to
    \begin{equation}\label{defPhi}
        \partial_\xi\phi(\Phi(u,x_n;\xi),x_n;\xi)=u.
    \end{equation}
Here, we may assume the equation holds for $u$ in a small neighborhood of the origin.
\end{definition}

Since the phase function $\phi$ is homogeneous of degree one in $\xi$, we have
$\partial_\xi \phi(u;\xi)=\partial_\xi \phi(u;s\xi)$ for any $s>0$. Consequently,
\begin{equation}
\label{1-homo}
    \Phi(u;\xi)=\Phi(u;s\xi)
\end{equation}

Moreover, by invoking the inverse function theorem together with conditions
$(\textup{D1}_\bA)$ and $(\textup{D2}_\bA)$, we obtain uniform $L^\infty$ bounds for
$\Phi$ and its derivatives. Differentiating \eqref{defPhi} with respect to $u$ yields
\[
\partial^2_{\xi, x'= \Phi(u,x_n;\xi)} \phi \cdot \partial_u \Phi = I_n.
\]
As a consequence,
\[
\det \partial_u \Phi(u,x_n;\xi) \gtrsim 1,
\]
That is, the matrix $\partial_u \Phi(u,x_n;\xi)$ is quantitatively non-singular.

Define $\gamma^\lambda: \mathbb{R}^{n-1} \times \mathbb{R} \times \mathbb{A} \mapsto \mathbb{R}^{n-1}$ by
\begin{equation}
\nonumber
    \ga^\la(u,x_n;\xi):=\la \Phi(u/\la,x_n/\la;\xi). 
\end{equation}

Then one has
\begin{equation}
\label{transformation-id}
    \partial_\xi\phi^\la(\ga^\la(u,x_n;\xi),t;\xi)=u.
\end{equation}

For each fixed pair $(u,\xi)$, the mapping $x_n \mapsto (\gamma^\lambda(u,x_n;\xi), x_n)$, with $x_n \in [-R,R]$, traces out a curve. The wave packets considered here will be defined as certain non-isotropic neighborhoods surrounding these curves.

\medskip
We proceed to describe the wave packet decomposition of $T^\lambda f$ at scale $R$. Cover $B^{n-2}_1(0)$ by finite-overlapping caps $\theta$ of diameter $\sim R^{-1/2}$. Let $\Theta_{R^{-1/2}} := \{\theta\}$ and $\{\psi_\theta\}$ be a smooth partition of unity subordinate to this cover. For each $\theta$ let $\omega_\theta$ denote the center of $\theta$ and define $\tilde{\psi_\theta}$ by
\begin{equation*}
\tilde{\psi_\theta}(\xi',\xi_{n-1}) :=
\begin{cases}
\psi_\theta(\xi'/\xi_{n-1}),
& \text{if } (\xi',\xi_{n-1}) \in \mathbb{A}, \\[4pt]
0,
& \text{otherwise}.
\end{cases}
\end{equation*}
Let $f_\theta := \tilde{\psi}_\theta f$. Now we can write
\[ f = \sum_{\theta\in\Theta_{r^{-1/2}}}f_\theta\]
Let $\tilde{\theta} \subset \mathbb{R}^{n-1}$ be a box of dimensions $1 \times R^{-1/2} \times ...\times R^{-1/2}$ such that
\[\{(\xi',\xi_{n-1}):\frac{\xi'}{\xi_{n-1}} \in \theta, 1 \leq \xi_{n-1} \leq 2\} \subset \tilde{\theta}\]
In addition, we denote $C\tilde{\theta}$ by a $1 \times CR^{-1/2} \times ...\times CR^{-1/2}$ box satisfying
\[\{(\xi',\xi_{n-1}):\frac{\xi'}{\xi_{n-1}} \in C\theta, 0.9 \leq \xi_{n-1} \leq 2.1\} \subset C\tilde{\theta}\]
\smallskip

We first introduce some notations before decomposing in physical space.
\begin{definition} \cite[Definition 3.4]{GW} \label{dual-box}
Let $U\subset \R^m$ be a box of dimensions $a_1\times \dots\times a_m$. Define $U^*$ to be the {\bf dual box} of $U$ centered at the origin of dimensions $a_1^{-1}\times \dots\times a_m^{-1}$, and with edges parallel to the corresponding edges of $U$.
\end{definition}
\begin{definition} \cite[Remark 3.6]{GW} \label{dilation}
For a slab $U\subset \R^{n-1}$ of dimensions $Rs^2\times Rs\times \dots\times Rs$ with $s\in[R^{-1/2},1]$ and a constant $C>0$, define $CU$, the non-isotropic $C$-dilation of $U$, to be a slab of dimensions $C^2Rs^2\times CRs\times \dots\times CRs$ with the same center as $U$.

For two slabs $U_1, U_2\subset \R^n$, we say they are \textbf{comparable} if 
    \[\frac{1}{C}U_1\subset U_2\subset C U_1.\] 
Here, $C=C_\phi$ is a constant that may vary from line to line, but eventually only depends on $\phi$. 

\end{definition}

We now carry out the wave packet decomposition of $f$. Fix $\theta \in \Theta_{R^{-1/2}}$.
We cover $\mathbb{R}^{n-1}$ by a finitely overlapping family of
$R^{2\delta} \times R^{1/2+\delta} \times \cdots \times R^{1/2+\delta}$ slabs
that are parallel to $R^\delta\tilde{\theta}^*$. Denote this collection by
\begin{equation}
\label{T-flat}
\mathcal{T}_\theta^\flat := \{T^\flat\}.
\end{equation}

Let $\{\eta_{T^\flat}\}$ be a smooth partition of unity subordinate to this cover.
Then we may decompose $\widehat{f}$ as
\[
\widehat{f}
= \sum_{\theta \in \Theta_{R^{-1/2}}}
  \sum_{T^\flat \in \mathcal{T}_\theta^\flat}
  \eta_{T^\flat}\,\widehat{f}_\theta .
\]

For each $\theta \in \Theta_{R^{-1/2}}$ and $T^\flat \in \mathcal{T}_\theta^\flat$,
the function
$\widecheck{\eta_{T^\flat}\widehat{f}_\theta}
= \widecheck{\eta_{T^\flat}} * f_\theta$
is essentially supported in $2\tilde{\theta}$.
Consequently,
\begin{equation}
\label{wave packet 1}
f
= \sum_{\theta \in \Theta_{R^{-1/2}}}
  \sum_{T^\flat \in \mathcal{T}_\theta^\flat}
  (\widecheck{\eta_{T^\flat}} * f_\theta)\,\psi_{\tilde{\theta}}
  + \mathrm{Rap}(r)\|f\|_2 ,
\end{equation}
where $\psi_{\tilde{\theta}}$ is a smooth bump function satisfying
$\supp \psi_{\tilde{\theta}} \subset \tilde{3\theta}$ and
$\psi_{\tilde{\theta}}(\xi)=1$ for all $\xi \in \tilde{2\theta}$.

For each $\theta \in \Theta_{R^{-1/2}}$ and $T^\flat \in \mathcal{T}_\theta^\flat$,
we associate a tube
\[
T
:= \bigl\{
\bigl(\gamma^\lambda(u,x_n;\omega_\theta,1),x_n\bigr)
: u \in R^\delta T^\flat,\ -R \le x_n \le R
\bigr\}.
\]
and define
\begin{equation} \label{def fT}
f_T := (\widecheck{\eta_{T^\flat}} * f_\theta)\,\psi_{\tilde{\theta}}.
\end{equation}

$T^\lambda f_T$ is concentrated on $T$. A more precise statement is as follows:
\begin{lemma}\label{lemsuppT} \cite[Lemma 3.12]{GW}
    $(T^\lambda f_T)\Id_{B_R^n(0)}$ is essentially supported in $ T$. In other words, \[(T^\lambda f_T)\Id_{B_R^n(0)\setminus  T}=\rap(R)\|f\|_2.\]
\end{lemma}
With this notation \eqref{def fT}, \eqref{wave packet 1} may be rewritten as
\[
f
= \sum_{\theta \in \Theta_{R^{-1/2}}}
  \sum_{T \in \mathcal{T}_\theta} f_T
  + \mathrm{Rap}(R)\|f\|_2 .
\]
We write $\mathcal{T}_\theta := \{T : T^\flat \in \mathcal{T}_\theta^\flat\}$ and $\mathcal{T} := \bigcup_{\theta \in \Theta_{R^{-1/2}}} \mathcal{T}_\theta$. 

This yields the wave packet decomposition of $f$ at scale $R$. From Plancherel theorem, we see that
\begin{lemma}\label{l2-orthogonalty}
    Suppose $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$ and $\mathcal{T}' \subset \mathcal{T}$, then
    \begin{equation*}
        \|\sum_{T \in \mathcal{T}'}f_T\|_{L^2(\mathbb{R}^{n-1})}^2 \sim \sum_{T \in \mathcal{T}'} \|f_T\|_2^2
    \end{equation*}
\end{lemma}

For each tube $T \in \mathcal{T}$ and each $-R \le t \le R$, the cross-section $T \cap \{x_n = t\}$ is a rectangular box with dimensions $R^{2\delta} \times R^{1/2+\delta} \times \cdots \times R^{1/2+\delta}$. To state this more precisely, we introduce the following definition.

\begin{definition}\cite[Definition 3.5]{GW}
\label{defgaV}
Given $\xi_0\in \mathbb{A}$ and a box $V\subset B_R^{n-1}(0)$, define
\begin{equation}\label{defgaVeq}
    \Ga_V(\xi_0;R):=\{ (\ga^\la(u,x_n;\xi_0),t):u\in V,|x_n|\le R \}.
\end{equation}
$\Ga_V(\xi_0;R)$ is called a curved plank with base $V$ and direction $\xi_0$.
\end{definition}
Using the notation of curved planks, each tube $T\in \mathcal{T}$ can be represented as
    \[T= \Ga_{R^\de T^\flat}(\omega_\theta,1;R), \]
that is, a curved plank with base $R^\de T^\flat$ and direction $(\omega_\theta,1)$. We refer to each such $T$ as an \textbf{$R$-plank}. Formally,
\begin{lemma}\label{geometric} \cite[Lemma 3.9]{GW}
Let $s\in[R^{-1/2},1]$ and $\xi_0 \in \mathbb{A}$. Let $V\subset \mathbb{R}^{n-1}$ be a slab of dimensions $Rs^2\times Rs \times \dots\times Rs $. Then for $|t|\leq R$, each $t$-slice $\Ga_V(\xi_0;R)\cap \{x_n=t\} $ is comparable to a $Rs^2\times Rs\times \dots\times Rs$-slab.
\end{lemma}

\bigskip
\subsection{Some simple estimates} The following standard estimates will play an important role in the decoupling argument that follows. Roughly they assert that $T^\lambda f_T$ behaves essentially like a constant on $T$. 
\begin{lemma} \label{essential constant}
    Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1}. Suppose  $q \geq 2$ and $g \in \mathcal{S}(\mathbb{R}^{n-1})$ is supposed in $\mathbb{A}$, then the estimate
    \[ \| T^\lambda g\|_{L^q(\mathbb{R}^{n-1} \times \{t\})}^q \lesssim_{\phi,q} |\supp\ g|^{\frac{q}{2}-1}\|g\|_2^q\]
    holds uniformly for all $t \in \mathbb{R}$. 
\end{lemma}
Two direct corollaries are
\begin{corollary} \label{essential constant decoupling}
    Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Suppose $a$ satisfies \eqref{assumpetion 1}). Let $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$ and $T \in \mathcal{T}$. Let $q = 2 + \frac{4}{n-2}$, then we have
    \begin{equation*}
    \|T^{\lambda}f_T\|_{L^q(B_{2R}^n(0))} \lesssim_{\phi}\|f_T\|_{L^{2}(\mathbb{R}^{n-1})}
    \end{equation*}
\end{corollary}
\begin{proof}[Proof of Corollary \ref{essential constant decoupling} assuming Lemma \ref{essential constant}] Since $f_T$ is supported in $\tilde{\theta}$ for some $\theta \in \Theta_{R^{-1/2}}$, we have $|\supp\ f_T| \lesssim R^{-\frac{n-2}{2}}$. Thus, Lemma \ref{essential constant} gives
\[\|T^{\lambda}f_T\|_{L^q(B_R^n(0))}^q \leq \int_{-2R}^{2R} \|T^\lambda f_T\|_{L^q(\mathbb{R}^{n-1} \times \{t\})}^q dt \lesssim_{\phi}\|f_T\|_{L^{2}(\mathbb{R}^{n-1})}^q\]
\end{proof}
\begin{corollary} \label{l2 estimate}
    Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1}, then the estimate
    \begin{equation*}
    \|T^{\lambda}f\|_{L^2(Q)}^2 \lesssim_{\phi}R^{1/2}\|f\|_{L^{2}(\mathbb{R}^{n-1})}^2
    \end{equation*}
    holds uniformly for all $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$ and all cubes $Q$ of sidelength $R^{1/2}$. 
\end{corollary}

To prove Lemma \ref{essential constant}, we will require the following result,
due to H\"ormander, which generalizes the Hausdorff--Young inequality.

\begin{lemma} \label{General Hausdorﬀ–Young} \cite[Theorem 1.1]{H}
    Suppose $q \geq 2$. Let $S^\lambda$ be an oscillatory integral operator defined as follows:
    \[ S^\lambda h(x):= \int e^{-2\pi \lambda i \bar{\phi}(x,y)} \bar{a}(x,y) h(y) dy\]
    where $\bar{\phi}:B^{n-1}_1(0) \times \mathbb{A} \mapsto \mathbb{R}$ and $\bar{a}:B^{n-1}_1(0) \times \mathbb{A} \mapsto \mathbb{R}^{+}$ satisfy
    \begin{align}
    \det \partial^2_{x,y}\bar{\phi}(x,y) > 0 \qquad \text{for all $ (x,y)\in B^{n-1}_1(0)\times \mathbb{A}$} \label{sh1} \\
    \|\partial_{x,y}^\beta \bar{a}\|_{L^\infty(B^{n-1}_1(0) \times \mathbb{A})} \lesssim_\beta 1 \qquad \qquad \text{for all $1 \leq |\beta| \leq N-1$.}\label{sh2}
    \end{align}

