\subsection{Statement of results}
Let $n \ge 3$ and $B^m_r(y) \subset \mathbb R^m$ denote the ball of radius $r$ centered at the $y \in \mathbb{R}^m$.

Let 
\[\mathbb A:=\{ (\xi',\xi_{n-1})\in\mathbb{R}^{n-1}: 1\le \xi_{n-1}\le 2, |\xi'|\le \xi_{n-1} \}. \]

Suppose $a \in C_c^{\infty}(\mathbb R^n \times \mathbb R^{n-1})$ is non-negative and supported in $B^n_1(0) \times \mathbb{A}$. Let $\phi:B^n_1(0) \times \mathbb{A} \mapsto \mathbb R$ satisfy the Cinematic Curvature Condition:

\textup{rank} $\partial^2_{x'\xi}\phi(x',x_n;\xi)=n-1$ for all $(x',x_n;\xi)\in{\rm supp}\ a$ with $\xi \ne 0$.

Consider the Gauss map $G: {\rm supp}\ a\rightarrow S^{n-1}$ by $G(x;\xi):=\frac{G_0(x;\xi)}{|G_0(x;\xi)|}$, where
 \[G_0(x;\xi):=\bigwedge_{j=1}^{n-1}\partial_{\xi_j}\partial_{x}\phi(x;\xi). \]
Then for all $(x,\xi_0)\in{\rm supp}\ a$,
\begin{equation}
\nonumber
 \partial^2_{\xi\xi}\langle \partial_z \phi(x,\xi),G(x,\xi_0) \rangle|_{\xi=\xi_0} 
\end{equation} 
has rank $n-2$ with $n-2$ positive eigenvalues. \\\\
\smallskip
For any $\lambda \geq 1$ let $a^{\lambda}(x; \omega) := a(x/\lambda; \omega)$, $\phi^{\lambda}(x;\omega) :=\lambda\phi(x/\lambda;\omega)$ and define the operator $T^{\lambda}$ by $$
 T^{\lambda}f(x) := \int e^{-2\pi i\phi^{\lambda}(x;\xi)}a^{\lambda}(x;\xi)f(\xi)d\xi.
$$for all integrable $f \colon B^{n-1} \to \mathbb{C}$. In this case $T^{\lambda}$ is said to be an oscillatory integral operator satisfying the cinematic curvature condition (or cone condition).

The main result of this article is the following.

\begin{lemma} \label{General Hausdorﬀ–Young} \cite[Theorem 1.1]{H}
 Suppose $q \geq 2$. Let $S^\lambda$ be an oscillatory integral operator defined as follows:
 \[ S^\lambda h(x):= \int e^{-2\pi \lambda i \bar{\phi}(x,y)} \bar{a}(x,y) h(y) dy\]
 where $\bar{\phi}:B^{n-1}_1(0) \times \mathbb{A} \mapsto \mathbb{R}$ and $\bar{a}:B^{n-1}_1(0) \times \mathbb{A} \mapsto \mathbb{R}^{+}$ satisfy
 \begin{align}
 \det \partial^2_{x,y}\bar{\phi}(x,y) > 0 \qquad \text{for all $ (x,y)\in B^{n-1}_1(0)\times \mathbb{A}$} \label{sh1} \\
 \|\partial_{x,y}^\beta \bar{a}\|_{L^\infty(B^{n-1}_1(0) \times \mathbb{A})} \lesssim_\beta 1 \qquad \qquad \text{for all $1 \leq |\beta| \leq N-1$.}\label{sh2}
 \end{align}
 then we have
 \begin{equation*}
 \|S^\lambda g\|_{L^q(\mathbb{R}^{n-1})} \lesssim_{\phi,q} \lambda^{-\frac{n-1}{q}} \|g\|_{L^{q'}(\mathbb{R}^{n-1})}
 \end{equation*}
 where $q'$ is the H\"older conjugate of $q$. 
\end{lemma}
\begin{proof} [Proof of Lemma \ref{essential constant}]
 Define $S^\lambda g$ by
 \[S^\lambda g(u) := T^\lambda g(\lambda u,t)\]
 Since $T^\lambda$ satisfies \textbf{(H1)} and assumption $\eqref{assumpetion 1}$, conditions $\eqref{sh1}$ and $\eqref{sh2}$ are satisfied. Consequently, Lemma \ref{General Hausdorﬀ–Young} yields
 \[ \| T^\lambda g\|_{L^q(\mathbb{R}^{n-1} \times \{t\})}^q = \lambda^{n-1} \|S^\lambda g\|_{L^q(\mathbb{R}^{n-1})} \lesssim_{\phi,q} \|g\|_{L^{q'}(\mathbb{R}^{n-1})}\]
 The proof is then completed by an application of H\"older's inequality.
\end{proof}
\bigskip
\subsection{Mixed Norm}
Since the $L^2$ behavior of wave packets is significantly simpler to analyze, one can reduce Proposition \ref{main theorem type 1} to the following via a real interpolation of strict-type. Similar reductions can be found in \cite{G,Wang}.
\begin{proposition}\label{reduction 2}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1} and \eqref{assumption2},then for all $p$ satisfies \eqref{main range}, the estimate
\begin{align*}
 \|T^{\lambda}f\|_{L^p(B_R^n(0))} \lesssim_{\varepsilon,p,\phi}R^\varepsilon \|f\|_{L^{2}(\mathbb{R}^{n-1})}^\frac{2}{p} \max_{\theta \in \Theta_{R^{-1/2}}}\|f\|_{L^{2}_\mathrm{avg}(3\tilde{\theta})}^{1-\frac{2}{p}}\\
 \|f\|_{L^{2}_\mathrm{avg}(3\tilde{\theta})}:= \left(\frac{1}{|3\tilde{\theta}|}\int_{3\tilde{\theta}} |f|^2\right)^{1/2}
\end{align*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$.
\end{proposition}

\bigskip
\subsection{Simplification of phase function} From \cite[Proof of Lemma 5.4]{GW}, one can reduce Proposition \ref{reduction 2} to the case
\begin{equation} \label{assumption 3}
 \phi(x;\xi) = \langle x',\xi\rangle + x_n\frac{h(\xi')}{\xi_{n-1}} + \cE(x;\xi'/\xi_{n-1})\xi_{n-1}
\end{equation}
where $h$ is quadratic and the error term is bounded by 
\begin{equation} \label{assumption 4}
\cE(x;\om) \lesssim |x_n| |\om|^3+|x|^2|\om|^2
\end{equation}
Formally, 
\begin{proposition}\label{redution 3}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1}, \eqref{assumption2}, \eqref{assumption 3} and \eqref{assumption 4}, then for all $p$ satisfies \eqref{main range}, the estimate
\begin{align*}
 \|T^{\lambda}f\|_{L^p(B_R^n(0))} \lesssim_{\varepsilon,p,\phi}R^\varepsilon \|f\|_{L^{2}(\mathbb{R}^{n-1})}^\frac{2}{p} \max_{\theta \in \Theta_{R^{-1/2}}}\|f\|_{L^{2}_\mathrm{avg}(3\tilde{\theta})}^{1-\frac{2}{p}}\\
 \|f\|_{L^{2}_\mathrm{avg}(3\tilde{\theta})}:= \left(\frac{1}{|3\tilde{\theta}|}\int_{3\tilde{\theta}} |f|^2\right)^{1/2}
\end{align*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$.
\end{proposition}
