\subsection{Broad Norm}\label{sectionbroadnorm} We recall the definition of the broad norm, which plays a central role in the subsequent decoupling analysis in this article. Related definitions can be found in \cite{BG,GHI,GW,G,OW}.

\section{Complete the proof} \label{concludetheproof}
In this section, we complete the proof of Proposition \ref{redution 3}. For the reader’s convenience, we restate the proposition below.
\begin{proposition}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition of type $\bfone$. Assume \eqref{assumpetion 1}, \eqref{assumption2}, \eqref{assumption 3} and \eqref{assumption 4}, then for all $p$ satisfies \eqref{main range}, the estimate
\begin{align*}
 \|T^{\lambda}f\|_{L^p(B_R^n(0))} \lesssim_{\varepsilon,p,\phi}R^\varepsilon \|f\|_{L^{2}(\mathbb{R}^{n-1})}^\frac{2}{p} \max_{\theta \in \Theta_{R^{-1/2}}}\|f\|_{L^{2}_\mathrm{avg}(3\tilde{\theta})}^{1-\frac{2}{p}}\\
 \|f\|_{L^{2}_\mathrm{avg}(3\tilde{\theta})}:= \left(\frac{1}{|3\tilde{\theta}|}\int_{3\tilde{\theta}} |f|^2\right)^{1/2}
\end{align*}
holds uniformly for $f \in \mathcal{S}(\mathbb{R}^{n-1})$ with $\supp f \subset \mathbb{A}$, $1 \leq R \leq \lambda^{1-\varepsilon}$ and $\varepsilon > 0$.
\end{proposition}
We work under the same setting as in Section \ref{section-algorithm}. 
Cover $B_R^n(0)$ by finite-overlapping $R/\Kc$-balls $B_k$. For each $B_k$ define $\mathbb{T}_k$ by
\[\mathbb{T}_k := \{ T \in \mathbb{T}, 100T \cap B_k \cap \big(\cup \cG(T)\big) \neq \emptyset \}\]
and $f_k$ by
\[f_k := \sum_{T \in \mathbb{T}_k} f_T\]
Now we can rewrite \eqref{finalstage} as
\begin{equation} \label{cp1}
 \|T^\la f\|_{L^p(B_R^n(0))}^p \lesssim (\log R)^{O_\varepsilon(1)} \sum_{B_k} \|T^\la f_k\|_{L^p(B_k)}^p + \rap(R)\,\|f\|_2^p
\end{equation}
In the rest of this section, we will consider the following two cases separately:
\begin{enumerate}
 \item \textbf{One-end}: $\beta\le 100$.
 \item \textbf{Two-ends}: $\beta > 100$. 
\end{enumerate}

\begin{lemma}\label{redution 5} \cite[Lemma 12.2]{GHI} Suppose $p_0 \geq 2$. Let $T^{\lambda}$ be an oscillatory integral operator satisfying the cinematic curvature condition. Assume that \eqref{assumpiton 4} holds uniformly for $1 \leq R \leq \lambda$ whenever $p \geq p_0$. To prove \eqref{globalestimate} for all $p > p_0$ it suffices to show that for all $\varepsilon >0$ the estimate 
\begin{equation}\label{sparse estimate} \|T^{\lambda}f\|_{L^{p_0}(S)} \lesssim_{\varepsilon, \phi, a} R^{\varepsilon}\|f\|_{L^{p_0}(B^{n-1})} 
\end{equation} holds whenever $R \geq 1$ and $S \subseteq \R^n$ is a union of $R$-balls belonging to a sparse collection. \end{lemma}
The main result of this subsection is stated below and can be deduced by a minor modification of the argument in \cite[Lemma 12.3]{GHI}. 
\begin{proposition}
 Suppose $p_0 \geq 2$. Let $T^{\lambda}$ be an oscillatory integral operator satisfying the cinematic curvature condition. Assume that \eqref{assumpiton 4} holds uniformly for $1 \leq R \leq \lambda$ whenever $p \geq p_0$. Then for all $\varepsilon >0$ the estimate 
\begin{equation}\label{sparse estimate} \|T^{\lambda}f\|_{L^{p_0}(S)} \lesssim_{\varepsilon, \phi, a} R^{\varepsilon}\|f\|_{L^{p_0}(B^{n-1})} 
\end{equation} holds whenever $R \geq 1$ and $S \subseteq \R^n$ is a union of $R$-balls belonging to a sparse collection. 
\end{proposition}
\begin{proof}
Let $\{B(x_j,R)\}_{j=1}^N$ be a sparse collection of balls whose union equals
the set $S$. It is clear that we may assume $R \ll \lambda$ and that each
ball $B(x_j,R)$ intersects the $x$-support of $a^{\lambda}$. Moreover, let
$c_{\mathrm{diam}} > 0$ be a sufficiently small constant, chosen to meet the
requirements of the argument below. By applying a partition of unity, we may
further assume that $\operatorname{diam} X < c_{\mathrm{diam}}$, and hence
\begin{equation}\label{not too bad separation}
\frac{|x_{j_1} - x_{j_2}|}{\lambda} \lesssim c_{\mathrm{diam}} \qquad \textrm{for all $1 \leq j_1, j_2 \leq N$.}
\end{equation}

post_theorem_intro_text:
Observe that the Knapp example indicates that estimate \eqref{linear estimate} may fail when $n =3$ and $p \leq 4$. Consequently, the range \eqref{main range} is sharp in the case $n=3$.

We denote by $B_r^m$ any ball of radius $r$ in $\mathbb{R}^m$. By an $\varepsilon$-removal trick, Theorem \ref{main theorem} can be reduced to
\begin{proposition} \label{epsilon main theorem}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition. Then the estimate
\begin{equation*}
    \|T^{\lambda}f\|_{L^p(B^n_R)} \lesssim_{\phi,a,\varepsilon,p} R^\varepsilon \|f\|_{L^{p}(\mathbb{R}^{n-1})}
\end{equation*}
holds uniformly for $1 \leq R \leq \lambda$ and all $\varepsilon > 0$ whenever
\begin{align}\label{range of result}
p \geq 2 + \frac{8}{3n-5}
\end{align}
\end{proposition}

Although estimates for oscillatory integral operators satisfying the cinematic curvature condition may be regarded as a generalized extension of cone restriction estimates, the polynomial partitioning techniques that have recently proved effective in the study of the cone restriction problem (see \cite{OW} and \cite{Wang}) do not seem to apply directly in this setting. The main obstacle lies in the fact that the transverse equidistribution estimate, which plays a crucial role in the polynomial partitioning framework, may not hold for oscillatory integral operators under cinematic curvature. 

Our proof of Proposition \ref{epsilon main theorem} relies primarily on Wolff’s two-ends reduction and refined decoupling inequalities. This methodological framework has recently been applied in the study of local smoothing estimates by Gan-Wu \cite{GW} and in the the restriction problem by Wang–Wu \cite{WW}. Accordingly, our argument may be viewed as similar in spirit to their approach in the present setting of oscillatory integral operators satisfying the cinematic curvature condition.

In addition, we provide a counterexample showing that when the estimate \eqref{linear estimate} may fail. This example is inspired by the work of Bourgain-Guth \cite{BG} and arises from the Kakeya compression phenomenon, where tubes are arranged within a neighborhood of a low-dimensional set. A detailed discussion of this example is given in Section \ref{necessary condition}.\\

\begin{theorem} \label{main conjecture}
Suppose $T^{\lambda}$ is an oscillatory integral operator satisfying the cinematic curvature condition. The estimate \eqref{linear estimate} may fail when
\begin{align}\label{necessary range}
p < 2 + \frac{8}{3n-1} & \qquad \textrm{if $n$ is odd;} \\
\nonumber
p < 2 + \frac{8}{3n-2} & \qquad \textrm{if $n$ is even.}
\end{align}
\end{theorem}

Estimates for oscillatory integral operators satisfying the cinematic curvature condition are closely related to several central problems in modern harmonic analysis, most notably the local smoothing problem and the cone restriction problem. These operators, by incorporating variable coefficients and geometric curvature conditions, provide a unifying analytic framework that captures many classical oscillatory phenomena while extending beyond the constant-coefficient cone scenario. Because sharp bounds in this setting would deepen our understanding of decoupling, restriction, and dispersive regularity estimates, progress on this problem has the potential to inform a broad range of techniques in Fourier analysis, partial differential equations, and geometric measure theory. Accordingly, the study of such estimates carries substantial intrinsic value, both from a conceptual standpoint and in terms of possible applications to longstanding conjectures in harmonic analysis.
\bigskip

\subsection{Structure of the article}

The structure of this paper is as follows. In Section \ref{necessary condition} , we construct a counterexample demonstrating that the estimate \eqref{linear estimate} may fail when $p$ lies inside the range \eqref{necessary range}. Section \ref{section-preliminary} presents several preliminary reductions and methodological tools, including the narrow–broad argument and wave packet decomposition. Section \ref{section-algorithm} is devoted to the two-ends reduction. In Section \ref{concludetheproof}, we complete the proof of the main theorem. Finally, Section \ref{epsilon removal} establishes an $\varepsilon$-removal lemma for oscillatory integral operators satisfying the cinematic curvature condition.

\bigskip

\subsection{Notations} We write $\#E$ for the cardinality of a finite set $E$. If $\mathcal{E}$ is a family of sets in $\mathbb{R}^n$, we use $\cup \mathcal{E}$ to denote $\bigcup_{E \in \mathcal{E}} E$. For $A,B \ge 0$, we write $A \lesssim B$ to mean $A \le C B$ for some absolute constant $C$, and $A \sim B$ to mean both $A \lesssim B$ and $B \lesssim A$. For $R>1$, we write $A \lesssim_\eta B$ to indicate that $A \le C_\eta R^\eta B$ for all $\eta>0$. We use $\mathrm{RapDec}(R)$ to denote a rapidly decaying quantity, meaning that for all $R \ge 1$,
\[
\mathrm{RapDec}(R) \le C_N R^{-N} \qquad \textrm{for some very large $N$} .
\]

Finally, for a set $X$, we write $N_r(X)$ for its $r$-neighborhood.
\medskip

\subsection{Choice of Parameters} \(0 < \varepsilon \ll 1,\ 1 \leq R \leq \lambda,\ \
K = R^{\varepsilon^{50}},\ K_{\circ} = R^{\varepsilon^{100}},\ \kappa = R^{\varepsilon^{500}},\ 
\delta = \varepsilon^{1000}.\) With this choice of parameters, we obtain
\[
R^{\delta} \ll \kappa \ll K_{\circ} \ll K \ll R \leq \lambda .
\]
