\section{Self similar supersolutions}
\label{s:sss}

We assume here $\varGamma\ge 1$ and
\begin{equation}
  \label{eq:sss_ups_t0r0}
  \excf(\rpol_{0})
  <
  \log t_{0}
  \le
  \varGamma
  \log t_{0}
  \,,
\end{equation}
so that the support of $\ups(t)$ contains the ball $\rpol\le\rpol_{0}$ for all $t\ge 0$; this follows from the fact that $\rat$, and therefore $\tar$, is an increasing function as proved in Lemma~\ref{l:sss_rat}. By the same token, the support of $\ups(t)$ is the ball of radius $\excf^{(-1)}(\tau)$.

For the reader's convenience we recall that we assume $\alpha_{2}<p$, and note that $\rpol_{0}$ will be chosen as in \eqref{eq:sss_ups_r0}, $C_{*}$ as in \eqref{eq:sss_ups_C}, $\nu_{0}$ as in \eqref{eq:sss_ups_c1}, $\varGamma$ as in \eqref{eq:sss_ups_Gamma0}, while $t_{0}$ is required to satisfy \eqref{eq:sss_ups_t0r0} and \eqref{eq:sss_ups_ineqs5}.

1) Case $\rpol\ge \rpol_{0}$.
With the notation above, we write
\begin{equation}
  \label{eq:sss_sup_2}
  \ups(x,t)
  =
  \frac{C_{*}\brt(\rpol,\tau)^{\frac{p-1}{p+m-3}}}{(t+t_{0})^{\frac{1}{p+m-3}}}
  \,,
  \quad
  \brt(\rpol,\tau)
  :=
  \big[
  \tar(\tau)^{\frac{1}{p-1}}
  -
  \rat(\rpol)^{\frac{1}{p-1}}
  \big]_{+}
  \,.
\end{equation}
Clearly we may restrict in our calculations to the open set where $\brt>0$. Thus we compute
\begin{equation}
  \label{eq:sss_ups_pow}
  \ups(x,t)^{m-1}
  =
  \frac{C_{*}^{m-1}\brt(\rpol,\tau)^{\frac{(m-1)(p-1)}{p+m-3}}}{(t+t_{0})^{\frac{m-1}{p+m-3}}}
  \,,
\end{equation}
and
\begin{equation}
  \label{eq:sss_ups_rder}
  \ups_{\rpol}(x,t)
  =
  -
  \frac{1}{p+m-3}
  \frac{C_{*}\brt(\rpol,\tau)^{\frac{p-1}{p+m-3}-1}}{(t+t_{0})^{\frac{1}{p+m-3}}}
  \rat(\rpol)^{\frac{1}{p-1}-1}
  \rat'(\rpol)
  \,.
\end{equation}
Thus, on recalling $\rat'(\rpol)\ge 0$, we obtain
\begin{equation}
  \label{eq:sss_ups_diff}
  \begin{split}
    I_{1}
    &:=
      \ups^{m-1}
      \abs{\ups_{\rpol}}^{p-2}
      \ups_{\rpol}
    \\
    &=
      -
      \frac{
      C_{*}^{p+m-2}
      }{
      (p+m-3)^{p-1}
      }
      \,
      \frac{
      \brt(\rpol,\tau)^{\frac{p-1}{p+m-3}}
      }{
      (t+t_{0})^{\frac{p+m-2}{p+m-3}}
      }
      \rat(\rpol)^{2-p}
      \rat'(\rpol)^{p-1}
      \,.
  \end{split}

