\begin{theorem}
  \label{t:sub_sub}
  Assume \eqref{eq:degen} and \eqref{eq:powerlike}. Let $u$ be a strong solution to \eqref{eq:pde}--\eqref{eq:initd} with a compactly supported and bounded data $u_{0}$, such that $u_{0}(x)\ge \varepsilon>0$ for $\lvertx\rvert\le\ell$, $\ell>0$.
  \\
  Then there exist constants $t_{0}$, $C_{*}$, $\rpol_{0}$ and $\varGamma$ such that $\widetilde u$ as in \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} is a subsolution and
  \begin{equation}
    \label{eq:sub_sub_n}
    u(x,t)
    \ge
    \widetilde u(x,t)
    \,,
    \qquad
    (x,t)\in S_{\infty}
    \,.
  \end{equation}
  We have also
  \begin{equation}
    \label{eq:sub_sub_nn}
    \supp u(t)
    \supset
    B_{R(t)}(0)
    \,,
    \quad
    R(t)
    =
    \gamma
    g^{(-1)}(\log t)
    \,,
    \qquad
    t>t_{0}
    \,,
  \end{equation}
  for a suitable constant $\gamma>0$. The constants here depend on the parameters appearing in the assumptions and on $\varepsilon$, $\ell$.
\end{theorem}

\begin{proof}[Proofs of Theorems \ref{t:sup_sup} and \ref{t:sub_sub}]
  The proof follows straightforwardly from an application of the method given in the proof of \cite[Theorem~1]{Tsutsumi:1988}, when we take into account Proposition~\ref{p:main_sup_sub} and Lemmas \ref{l:sss_comp} and \ref{l:ssb_comp}.
\end{proof}

Next we apply our results to a different kind of equation, that is \eqref{eq:rad_N}; see also \cite{Vazquez:2015}, \cite{Grillo:Muratori:Vazquez:2017} for the case of the porous media equation.

\begin{theorem}
  \label{t:transform}
Radial solutions $U(r,t)$ [respectively, supersolutions and subsolutions] of \eqref{eq:pde} correspond, thru a suitable transformation of the space variable, to radial solutions $v(s,t)$ [respectively, supersolutions and subsolutions] of \eqref{eq:rad_N},
for a suitable positive function $\rho\in C([0,+\infty))$ such that $\rho(0)=1$ and
\begin{equation}
  \label{eq:rad_rw_est}
  \rho(s)
  \sim
  \frac{g^{(-1)}(\log s)^{p}}{(\log s)^{p}}
  \frac{1}{s^{p}}
  \,.
\end{equation}
In fact, the transformation $r=\hat\rpol(s)$, $s>0$, is such that
\begin{equation}
  \label{eq:rad_r_asy_n}
  \hat\rpol(s)
  \sim
  g^{(-1)}(\log s)
  \,.
\end{equation}
\end{theorem}

Here and in the following we use the notation, for positive functions $F_{1}$, $F_{2}$,
\begin{equation}
  \label{eq:rad_sim}
  F_{1}(s)\sim F_{2}(s)
  \quad
  \text{if and only if}
  \quad
  C_{1}
  \le
  \frac{F_{2}(s)}{F_{1}(s)}
  \le
  C_{2}
  \,,
  \quad
  s\ge \bar s
  \,,
\end{equation}
for suitable $C_{1}$, $C_{2}$, $\bar s>0$.

Owing to Theorem~\ref{t:transform}, supersolutions and subsolutions of the type \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} yield radial counterparts for equation \eqref{eq:rad_N}. Thus, from our  Theorems \ref{t:sup_sup}, \ref{t:sub_sub} the following comparison results follow immediately.

\begin{theorem}
  \label{t:sup_sup_dens}
  Let $v$ be a strong solution to \eqref{eq:rad_N}, for the specific $\rho$ found in Theorem~\ref{t:transform}, under assumptions \eqref{eq:degen} and \eqref{eq:powerlike}, such that $v(x,0)$ is compactly supported and bounded.
  \\
  Then there exist constants $t_{0}$, $C_{*}$, $\rpol_{0}$ and $\varGamma$ such that $\widetilde u(\hat\rpol(\lvertx\rvert),t)$ as in \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} is a supersolution to \eqref{eq:rad_N}, and
  \begin{equation}
    \label{eq:sup_sup_dens_n}
    v(x,t)
    \le
    \widetilde u(\hat\rpol(\lvertx\rvert),t)
    \,,
    \qquad
    (x,t)\in S_{\infty}
    \,.
  \end{equation}
  We have also
  \begin{equation}
    \label{eq:sup_sup_dens_nn}
    \supp v(t)
    \subset
    B_{\tilde R(t)}(0)
    \,,
    \qquad
    \log \tilde R(t)
    \sim
    \log t
    \,,
    \qquad
    t>t_{0}
    \,.
  \end{equation}
  The constants involved in \eqref{eq:sup_sup_dens_n}--\eqref{eq:sup_sup_dens_nn} depend on the parameters appearing in the assumptions and on $v(x,0)$.
\end{theorem}

\begin{theorem}
  \label{t:sub_sub_dens}
  Let $v$ be a strong solution to \eqref{eq:rad_N}, for the specific $\rho$ found in Theorem~\ref{t:transform}, under assumptions \eqref{eq:degen} and \eqref{eq:powerlike}, such that $v(x,0)$ is compactly supported, bounded and
$v(x,0)\ge \varepsilon>0$ for $\lvertx\rvert\le\ell$, $\ell>0$.
  \\
  Then there exist constants $t_{0}$, $C_{*}$, $\rpol_{0}$ and $\varGamma$ such that $\widetilde u(\hat\rpol(\lvertx\rvert),t)$ as in \eqref{eq:sss_sup}--\eqref{eq:sss_ups_2} is a subsolution \eqref{eq:rad_N}, and
  \begin{equation}
    \label{eq:sub_sub_dens_n}
    v(x,t)
    \ge
    \widetilde u(\hat\rpol(\lvertx\rvert),t)
    \,,
    \qquad
    (x,t)\in S_{\infty}
    \,.
  \end{equation}
  We have also
  \begin{equation}
    \label{eq:sub_sub_dens_nn}
    \supp v(t)
    \supset
    B_{\tilde R(t)}(0)
    \,,
    \quad
    \log\tilde R(t)
    \sim
    \log t
    \,,
    \qquad
    t>t_{0}
    \,,
  \end{equation}
  The constants involved in \eqref{eq:sub_sub_dens_n}--\eqref{eq:sub_sub_dens_nn} depend on the parameters appearing in the assumptions and on $v(x,0)$.
\end{theorem}

\begin{remark}
  \label{r:rad_N}
  Clearly the sup estimate valid for $v$ as in Theorems
  \ref{t:sup_sup_dens} and \ref{t:sub_sub_dens} is the same as in
  \eqref{eq:sup_decay}, which should be compared with the result valid for $\rho(s)\sim s^{-\alpha}$, $\alpha>p$, that is the universal bound $t^{-1/(p+m-3)}$ (see \cite{Andreucci:Tedeev:2021b}). Our present bound however depends on the initial data, as the known bound valid in the subcritical case $\alpha<p$, whose decay rate is $t^{-(N-\alpha)/K}$, $K=(N-\alpha)(p+m-3)+p-\alpha$.
\end{remark}

\textbf{Plan of the paper.}
Section~\ref{s:pre} contains some elementary auxiliary results.
Then Proposition~\ref{p:main_sup_sub} is proved in Sections \ref{s:sss} (supersolutions) and \ref{s:ssb} (subsolutions).
Finally in Section~\ref{s:rad} we carry out the transformation of variables linking \eqref{eq:pde} and \eqref{eq:rad_N}.

