 \end{align}
 for some $(k+1)$-dimensional subspace $P$, then 
 $S^k_{\ep,\overline{r}}(J)\cap B_{1/2}(p)=\emptyset$ for $\overline{r}=\delta_3^{\frac{1}{2(m-2)}}$. In particular, $0\not\in \exp^{-1}S^k_{\ep,\overline{r}}(J)$, i.e. $p\not\in S^k_{\ep,\overline{r}}(J)$.
 \end{lemma}
 The proof of Lemma \ref{lemma: almost translation invariant} is similar to Naber-Valtorta \cite[Lemma 4.8]{Naber-V-2018}. 
 \begin{proof} 
 Identify $B_3(p)\subset M$ with $B_3(0)\subset \R^m$ via the exponential map $\exp$, and still denote the pullback maps $\exp_p^*J$ and $\exp_p^*g$ by $J$ and $g$, respectively.
 We claim that there is a constant $C(m,\Lambda)>0$ such that for every $x\in B_{1/2}(p)$, there exists $r_x\in[\overline{r},1/2]$ such that
 \begin{equation}\label{eq: lemma 3-11-1}
 \Phi_J(x,r_x)-\Phi_J(x,r_x/2)<\frac{C(m,\Lambda)}{-\log\delta_3}.
 \end{equation}
 Indeed, if this is not true, then for $J\in W^{1,2}_\La(\cJ_g(B_3(p)))$ we may assume by choosing a good radius that $\Phi_J(x,1/2)\le C_0(m,\Lambda)$. Then 
 \begin{align*}
 C_0(m,\Lambda)\geq\Phi_J(x,1/2)&\geq\sum_{i=1}^{-\log\overline{r}+1}(\Phi_J(x,2^{-i})-\Phi_J(x,2^{-i-1}))\geq c(m)C(m,\Lambda),
 \end{align*}
 which is impossible if we let $C(m,\Lambda)=\frac{2C_0(m,\Lambda)}{c(m)}$. This proves the claim.

The next result shows that $\Phi_J$ remains almost constant on all pinched points.
 \begin{lemma}\label{lemma: Phi_J almost const}
 Let $\rho,\eta>0$ be fixed and {$J\in W^{1,2}_\La(\cJ_g(B_3(p)))$} is a minimizing harmonic almost complex structure. Let 
 {$$E:=\sup_{y\in B_2(p)}\Phi_J(y,1).$$ }
 Then there exists $\de_4=\de_4(m,g,\Lambda,\rho,\eta)>0$ such that, if the set 
 $$F:=\{y\in B_2(p):\Phi_J(y,\rho)>E-\delta_4\}$$
 $\rho$-effectively spans a $k$-dimensional affine subspace $L\subset\mathbb{R}^m$, then
 {$$\Phi_J(x,\rho)\ge E-\eta \qquad \text{for all } x\in \exp_p(L\cap B_2(0)).$$}
 \end{lemma}
 \begin{proof}
 We prove by contradiction. Suppose {$J\in W^{1,2}_\La(\cJ_g(B_3))$} is a sequence of minimizing harmonic almost complex structure with
 $$\sup_{y\in B_2(p)}\Phi_{J_i}(y,1)\leq E.$$
 {For each $i\ge 1$, we assume that there exists $\{y^i_j\}_{j=0}^k\subset F_i:=\{y\in B_2(p):\Phi_{J_i}(y,\rho)>E-i^{-1}\}$ spanning $\rho$-effectively a $k$-dimensional affine subspace $L_i\subset\mathbb{R}^m$, and there exists $x_i\in \exp_p(L_i\cap B_2(0))$} such that
 \begin{equation}\label{eq: Phi_J almost const-1}
 \Phi_{J_i}(x_i,\rho)\leq E-\eta.
 \end{equation}
 It follows from the assumption that
 \begin{equation}\label{eq: Phi_J almost const-2}
 \Phi_{J_i}(y^i_j,1)-\Phi_{J_i}(y^i_j,\rho)<1/i,\qquad \text{for all }\,i\ge 1,\, 0\le j\le k. 
 \end{equation}
 Without loss of generality, we assume that for each $0\le j\le k$, 
 $$y^i_j\to y_j,\quad x_i\to x\quad\text{and}\quad L_i\to L$$
 as $i\to \infty$ with {$x\in \exp_pL$} and $J_i\wto J$ in $W^{1,2}$.

Let $\de=\de(m,\Lambda,\ep)$ be fixed. By Lemma \ref{lemma: main covering lemma}, for all $0<r<\delta$,
 \begin{equation}\label{eq: main thm proof-1}
 \mbox{Vol}(T_r(S^k_{\ep,r}(J))\cap B_1(p))\le \mbox{Vol}\Big(T_r\Big(S^k_{\ep,\de }(J)\cap B_1(p)\Big)\Big) \leq C'_\ep r^{m-k}
 \end{equation}
 with $C'_{\ep}=C'_\ep(m,\Lambda,\ep)$. For $r\in[\de,1)$, we have 
 \begin{equation}\label{eq: main thm proof-2}
 \mbox{Vol}\Big(T_r\Big(S^k_{\ep,r}(J)\cap B_1(p)\Big)\Big) \le \mbox{Vol}(T_1( B_1(p)) \leq C_m \le C_m \left(\frac{r}{\de} \right)^{m-k}.
 \end{equation}
