In this section, we provide energy estimates. The first estimate is the Caccioppoli inequality.
\begin{lemma}\label{caccio_lem}
	Let $u$ be a weak solution to \eqref{eq} in $\Omega_T$. Then for every $Q_{R,\ell}(z_0)\subset\Omega_T$, with $R,\ell>0$, and for $r\in [R/2,R)$ and $\tau^2\in[\ell^2/2^2,\ell^2)$, there exists a constant $c=c(n,p,q,\nu,L)$, such that
	\begin{align*}
		\begin{split}
int_{Q_{r,\tau}(z_0)}(|\na u|^p+a(z)|\na u|^q)\,dz\\
int_{Q_{R,\ell}(z_0)}\left(\frac{|u-u_{Q_{R,\ell}(z_0)}|^p}{(R-r)^p}+a(z)\frac{|u-u_{Q_{R,\ell}(z_0)}|^q}{(R-r)^q}\right)\,dz\\
int_{Q_{R,\ell}(z_0)} (|F|^p+a(z)|F|^q)  \,dz\,.
		\end{split}
	\end{align*}
\end{lemma}

