we assume $\mathcal{A}(z,\nabla u):\Omega_T\times \mathbb{R}^{Nn}\longrightarrow \mathbb{R}^{Nn}$ with $N\ge1$ is a Carath\'eodory vector field satisfying the following structure assumptions: there exist constants $0<\nu\le L<\infty$ such that
 \begin{align}\label{str}
 \mathcal{A}(z,\xi)\cdot \xi\ge \nu(|\xi|^p+a(z)|\xi|^q)
 \quad\text{and}\quad
 |\mathcal{A}(z,\xi)|\le L(|\xi|^{p-1}+a(z)|\xi|^{q-1}),
 \end{align}
for almost every $z\in \Omega_T$ and every $\xi\in \mathbb{R}^{Nn}$. Throughout the rest of the paper, we use the notation for $z\in\Omega_T$ and $s\geq 0$ \begin{equation}
 \label{H-def}
H(z,s)=s^p+a(z) s^q\,.
\end{equation}

We focus of gradient higher integrability of the solutions in the spirit of \cite{KiLe-Duke}. We prove it for a priori bounded $u$, $a \geq 0$ and $a\in \mathcal{C}^{\alpha,\frac\alpha 2}(\Omega_T)$ for some $\alpha \in (0,1]$ and 
\begin{align} \label{range_pq}
2\le p <\infty, \quad p<q\le p+\alpha\,. 
\end{align}
Here $a\in \mathcal{C}^{\alpha,\frac\alpha 2}(\Omega_T)$ means that $a\in L^{\infty}(\Omega_T)$ and there exist constants $c_a>0$, such that
\begin{align}
 \label{def_holder}
 |a(x,t)-a(y,s)|\le c_a\left(\max\{ |x-y|^\alpha,|t-s|^\frac{\alpha}{2} \}\right)
\end{align}
for every $(x,y)\in\Omega$ and $(t,s)\in (0,T)$.

The main result of this paper is the following higher integrability estimate for the gradient of a weak solution to (\ref{eq}) assuming that the forcing term $H(z,|F|)\in L^\gamma$,
where $\gamma=\tfrac{n+p}{p}$. We denote the constant $c=c(\mathit{data})$ if $c$ depends on the following
 \begin{align*}
 \begin{split}
 \mathit{data}=&(n,N,p,q,\nu,L,c_a,\|u\|_{L^\infty(\Om_T)},\|H(z,|F|)\|_{L^\gamma(\Om_T)})\,.
 \end{split}
\end{align*} Now we state our main result.

\begin{align}\label{eq}
	u_t-\dv\mA(z,\na u)=-\dv(|F|^{p-2}F+a(z)|F|^{q-2}F)\quad \text{in $\Omega_T=\Omega\times(0,T)$\,,}
\end{align}

\subsection{Proof of Theorem~\ref{main_theorem}}
Recall we have set $r\le r_1<r_2\le 2r$ with $r\in(0,1)$.
For selected subcollection $\mathcal{G}$ in Lemma~\ref{vitali_lem}, we simply write
\[
 \mathcal{G}=\{ \mQ_i \}_{1\le i \le \infty}\,,
\]
where $\mQ_i=\mQ(w_i)$ for some $w_i\in \Psi(\La,r_1)$. Depending on the intrinsic geometry of $\mQ_i\in \mathcal{G}$, it follows by Proposition~\ref{p_est_vitali} and Proposition~\ref{q_est_vitali} that for any $i\in \mathbb{N}$
\begin{align*}
 \begin{split}
 \iint_{\cv\mQ _{i}}H(z,|\na u|)\,dz
 &\le c\La^{1-\theta}\iint_{\mQ _i\cap \Psi(c^{-1}\La)}H(z,|\na u|)^\theta\,dz\\
 &\qquad + c\iint_{U_i\cap \Theta(c^{-1} \la) } H(z,|F|)\,dz\,,
 \end{split}
\end{align*}
where $c=c(\data)>1$ is a constant and fixed $\theta\in (0,1)$.
Employing disjointedness and covering property in Lemma~\ref{vitali_lem}, we get
\begin{align*}
 \begin{split}
 \iint_{\Psi(\La,r_1)}H(z,|\na u|)\,dz
&\le\sum_{i=1}^\infty\iint_{\cv\mQ _{i}}H(z,|\na u|)\,dz\\
&\le c\La^{1-\theta}\sum_{i=1}^\infty\iint_{\mQ _i\cap \Psi(c^{-1}\La)}H(z,|\na u|)^\theta\,dz\\
&\qquad +c \sum_{i=1}^\infty\iint_{\mQ _i\cap \Theta(c^{-1}\La)}H(z,|F|)\,dz\\
&\le c\La^{1-\theta}\iint_{\Psi(c^{-1}\La,r_2)}H(z,|\na u|)^\theta\,dz\\
&\qquad+ c\iint_{\Theta(c^{-1}\La,r_2)}H(z,|F|)\,dz\,.
 \end{split}
\end{align*}
On the other hand, since we have
\[
\iint_{\Psi(c^{-1}\La,r_1)\setminus \Psi(\La,r_1)}H(z,|\na u|)\,dz
\le\La^{1-\theta}\iint_{\Psi(c^{-1}\La,r_2)}H(z,|\na u|)^{\theta}\,dz\,,
\]
we deduce that
\begin{align}\label{covering_est_1}
\begin{split}
 \iint_{\Psi(c^{-1}\La,r_1)}H(z,|\na u|)\,dz
 &\le c\La^{1-\theta}\iint_{\Psi(c^{-1}\La,r_2)}H(z,|\na u|)^\theta\,dz\\
 &\qquad +c \iint_{\Theta(c^{-1}\La,r_2)}H(z,|F|)\,dz\,,
\end{split}
\end{align}
where $c=c(data)>1$ is a constant.
We now take $k\in\mathbb N$ and consider
\[ 
H(z,|\na u|)_k=\min\{H(z,|\na u|),k\}
\]
and
\[
\Psi_k(\La,\rho)=\{z\in Q_{\rho}(z_0):H(z,|\na u(z)|)_k>\La\}\,.
\]
It is easy to see that if $\La>k$, then $\Psi_k(\La,\rho)=\emptyset$, and if $\La\le k$, then $\Psi_k(\La,\rho)=\Psi(\La,\rho)$. Therefore, along with these notations, \eqref{covering_est_1} becomes
\begin{align*}
 \begin{split}
 \iint_{\Psi_k(c^{-1}\La,r_1)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz
 &\le c\La^{1-\theta}\iint_{\Psi_k(c^{-1}\La,r_2)}H(z,|\na u|)^\theta\,dz\\
 &\qquad +c \iint_{\Theta(c^{-1}\La,r_2)}H(z,|F|)\,dz
 \end{split}
\end{align*}
for any 
\[
\La>(4\ccc)^{q}\left(\frac{8\cv r}{r_2-r_1}\right)^{\frac{q^2}{p}+\frac{q(n+2)}{2} }\La_0\,.
\]
Denoting
\[
 \La_1= c^{-1}(4\ccc)^q\left(\frac{8\cv r}{r_2-r_1}\right)^{\frac{q^2}{p}+\frac{q(n+2)}{2}}\La_0\,,
\]
for any $\La>\La_1$ we obtain
\begin{align*}
 \begin{split}
 &\iint_{\Psi_k(\La,r_1)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz\\
 &\le c\La^{1-\theta}\iint_{\Psi_k(\La,r_2)}H(z,|\na u|)^\theta\,dz+c\iint_{\Theta(\La,2r)}H(z,|F|)\,dz\,.
 \end{split}
\end{align*}

Let $\ep\in(0,1)$ will be determined later. We multiply the inequality above by $\La^{\ep-1}$ and integrate over $(\La_1,\infty)$. Then, we get
\begin{align*}
 \begin{split}
 \mathrm{I}&=\int_{\La_1}^{\infty}\La^{\ep-1}\iint_{\Psi_k(\La,r_1)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz\,d\La\\
 &\le c\int_{\La_1}^{\infty}\La^{\ep-\theta}\iint_{\Psi_k(\La,r_2)}H(z,|\na u|)^\theta\,dz\,d\La + c \int_{\La_1}^{\infty}\La^{\ep-1} \iint_{\Theta(\La,2r)}H(z,|F|)\,dz \, d\La \\
 &= \mathrm{II} + \mathrm{III}\,.
 \end{split}
\end{align*}
Applying Fubini's theorem to $\mathrm{I}$, it follows that
\begin{align*}
 \begin{split}
 \mathrm{I}
 &=\frac{1}{\ep}\iint_{\Psi_k(\La_1,r_1)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta\,dz\\
 &\qquad-\frac{1}{\ep}\La_1^\ep\iint_{\Psi_k(\La_1,r_1)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz\,.
 \end{split}
\end{align*}
Meanwhile, since we have
\begin{align*}
 \begin{split}
 &\iint_{Q_{r_1}(z_0)\setminus \Psi_k(\La_1,r_1)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta\,dz\\
 &\le \La_1^{\ep}\iint_{Q_{2r}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz\,,
 \end{split}
\end{align*}
we obtain
\begin{align*}
 \begin{split}
 \mathrm{I}\ge& \frac{1}{\ep}\iint_{Q_{r_1}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta\,dz\\
 &\qquad-\frac{2}{\ep}\La_1^\ep\iint_{Q_{2r}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz\,.
 \end{split}
\end{align*}
Similarly, by Fubini's theorem, we have
\[
 \mathrm{II}
 \le\frac{1}{1-\theta+\ep}\iint_{Q_{r_2}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta \,dz
\]
and
\[
\mathrm{III}\le \frac{1}{\ep}\iint_{Q_{2r}(z_0)}H(z,|F|)^{1+\ep} \,dz\,.
\]
Combining the estimates above, we obtain
\begin{align*}
 \begin{split}
 &\iint_{Q_{r_1}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta\,dz\\
 &\le \frac{c\ep}{1-\theta+\ep}\iint_{Q_{r_2}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta \,dz\\
 &\qquad+c\La_1^\ep\iint_{Q_{2r}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz \\
 &\qquad + c\iint_{Q_{2r}(z_0)}H(z,|F|)^{1+\ep} \,dz
 \end{split}
\end{align*}
for $c=c(\data)$ and $\theta=\theta(\data)\in(0,1)$. We choose $\ep_0=\ep_0(\data)\in(0,1)$ so that for any $\ep\in(0,\ep_0)$,
\[
 \frac{c\ep}{1-\theta+\ep}\le\frac{1}{2}\,.
\]
Then, there holds
\begin{align*}
 \begin{split}
 &\iint_{Q_{r_1}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta\,dz\\
 &\le \frac{1}{2}\iint_{Q_{r_2}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta \,dz\\
 &\qquad+c\La_1^\ep\iint_{Q_{2r}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz \\
 &\qquad+ c\iint_{Q_{2r}(z_0)}H(z,|F|)^{1+\ep} \,dz\,.
 \end{split}
\end{align*}
Recalling $r\le r_1<r_2\le 2r$, we conclude from Lemma~\ref{tech_lem} that
\begin{align*}
 \begin{split}
 &\iint_{Q_{r}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta+\ep}H(z,|\na u|)^\theta\,dz\\
 &\le c\La_0^\ep\iint_{Q_{2r}(z_0)}\left(H(z,|\na u|)_k\right)^{1-\theta}H(z,|\na u|)^\theta\,dz\\
 &\qquad+ c\iint_{Q_{2r}(z_0)}H(z,|F|)^{1+\ep} \,dz\,.
 \end{split}
\end{align*}
Letting $k$ go to $\infty$ and recalling \eqref{def_la} and $\eqref{def_La}$, we have 
\begin{align*}
 \begin{split}
int_{Q_{r}(z_0)}H(z,|\na u|)^{1+\epsilon}\,dz\\
 &\le c\left(\frac{\|u\|^p_{\infty}}{r^p} +\|a\|_{\infty} \frac{\|u\|^q_{\infty}}{r^q} + 
int_{Q_{4r}(z_0)}H(z,|F|)\,dz \right)^\frac{p}{2} +1\right)^{\frac{q\epsilon}{p}}\\
int_{Q_{2r}(z_0)}H(z,|F|)^{1+\ep} \,dz\,,
 \end{split}
\end{align*}
where we abbreviated $\| \cdot \|_{\infty}= \| \cdot \|_{L^\infty(\Om_T)}$.
Finally, applying Lemma~\ref{caccio_lem} with $Q_{2r}(z_0)$ and $Q_{4r}(z_0)$, we obtain
\begin{align*}
 \begin{split}
int_{Q_{r}(z_0)}H(z,|\na u|)^{1+\epsilon}\,dz\\
 &\le c\left(\frac{\|u\|^p_{\infty}}{r^p} +\|a\|_{\infty} \frac{\|u\|^q_{\infty}}{r^q} + 
int_{Q_{4r}(z_0)}H(z,|F|)\,dz \right)^\frac{p}{2} +1\right)^{\frac{q\epsilon}{p}}\\
int_{Q_{4r}(z_0)}H(z,|F|)\,dz \right)\\
int_{Q_{2r}(z_0)}H(z,|F|)^{1+\ep} \,dz\,,
 \end{split}
\end{align*}
where $c=c(\data,\|a\|_{L^\infty(\Om_T)})$.
Since $p\ge2$, we apply Young's inequality to the term with exponent $2$ on the right hand side in order to have
\begin{align*}
 \begin{split}
int_{Q_{r}(z_0)}H(z,|\na u|)^{1+\epsilon}\,dz
 &\le c\left(\frac{\|u\|^p_{\infty}}{r^p} +\|a\|_{\infty}\frac{\|u\|^q_{\infty}}{r^q} +1\right)^{1+\frac{q\epsilon}{p}} \\
int_{Q_{4r}(z_0)}H(z,|F|)^{1+\ep} \,dz\right)^{1+\frac{q}{2}}\,.
 \end{split}
\end{align*}
The proof is completed. \qed

expanded_sketch:
{\bf Methods.} To prove the main theorem, one follows the typical double phase strategy: one uses \emph{phase separation} into regions where the contribution of $a$ is small or dominating. A key ingredient is an \emph{exit time} (stopping time) argument, exploiting “a delicate relation between the radii of the exit time balls and the level at which we perform the exit time argument,” where “the stopping time depends on the energy of $\nabla u$ and of $F$.”

Compared to earlier work, the phase analysis is “formulated on integrated quantities,” which “allow[s] us to absorb the $q$-phase into the $p$-phase inside appropriate intrinsic cylinders and vice versa.” Then “the energy control (including the Caccioppoli type inequality) can be considered as perturbation corresponding estimates known for the $p$-Laplace systems,” requiring a “delicate interplay between the homogeneity of the scaling factors of cubes and their radii.”

The analytic backbone is a \emph{reverse H\"older inequality} “within the intrinsic and locally varying scaling,” adapted to the intrinsic geometry and split into:
\begin{itemize}
\item the \emph{$p$-intrinsic case}, when the problem is a perturbed $p$-Laplace evolution and the perturbation is controlled by $\|u\|_{L^\infty}$; for some $K>1$ and relevant cube $Q_\rho$ one has
\[K\ge (\|u\|_{\infty}/\rho)^{q-p}\sup_{cQ_{\rho}} a\,;\]
\item the \emph{$(p,q)$-intrinsic case}, when the above condition fails and the problem resembles the $q$-Laplace problem.
\end{itemize}
We first record the corresponding reverse H\"older inequalities.
\begin{lemma}\label{p_reverse_lem}
Suppose \ref{p1} and \ref{p2}.
\tThere exist constants $c=c(\data)$ and $\theta_0=\theta_0(n,p)\in(0,1)$ such that for any $\theta\in(\theta_0,1)$ there holds
\t\begin{align*}
int_{Q_{\rho}^\la(z_0)}H(z,|\na u|)\,dz
int_{Q_{2\rho}^\la(z_0)}H(z,|F|)\,dz\,.
\t\end{align*}\t
\end{lemma}
\begin{lemma}\label{q_reverse_lem}
Suppose \ref{q1} and \ref{q2}.
\tThere exist constants $c=c(n,N,p,q,\nu,L,\ca)$ and $\theta_0=\theta_0(n,p,q)\in(0,1)$ such that for any $\theta\in(\theta_0,1)$ there holds
\t\begin{align*}
int_{G_{\rho}^\la(z_0)}H(z,|\na u|)\,dz
int_{G_{2\rho}^\la(z_0)}H(z,|F|) \,dz\,.
\t\end{align*}\t
\end{lemma}

This separation “is effective in the presence of $F$ under the sharp range of phase parameters
\begin{align} \label{range_pq}
2\le p <\infty, \quad p<q\le p+\alpha\,.    
\end{align}
,” and “is possible due to” the following decay property, which yields a key decay estimate enabling the datum $F$ to be nonzero.
\begin{lemma}\label{lemma_decay}
   Suppose \ref{p1} and \ref{p2}. Then there exists a constant $\cc=\cc(\data)\ge K^\frac{1}{p}$
   such that
   \[
   \rho\le \cc \la^{-1}\,.
   \]
\end{lemma}

Finally, “the arguments are closed with use of the Vitali covering theorem,” via the following Vitali-type selection.
\begin{lemma}\label{vitali_lem}
    Let $\mathcal{F}$ be defined as above and $\kappa$ is in \eqref{K_and_kappa}, Then there exists a pairwise disjoint countable subcollection $\mathcal{G}$ of $\mathcal{F}$ such that for any $U(w)\in \mathcal{F}$, there exists $U(v)\in \mathcal{G}$ with
    \[
    U(w)\subset \kappa U(v)\,.
    \]
\end{lemma}
Together with the consequences of the reverse H\"older inequalities encoded in the Vitali-estimate propositions for the $p$-phase and $(p,q)$-phase:
\begin{proposition}\label{p_est_vitali} 
Suppose \ref{p1} and \ref{p2}.
\tThere exist constants $c=c(\data)$ and $\theta_0=\theta_0(n,p)\in(0,1)$, such that for any $\theta\in(\theta_0,1)$ we have
\t\begin{align*}
\t\t\t\begin{split}
\t\t\t    \iint_{Q_{2\cv\rho}^\la(z_0)}H(z,|\na u|)\,dz
\t\t\t&\le c\La^{1-\theta}\iint_{Q_{2\rho}^\la(z_0)\cap \Psi(c^{-1}\La)}H(z,|\na u|)^\theta\,dz\\
            &\qquad+c\iint_{Q_{2\rho}^\la(z_0)\cap \Theta(c^{-1}\La)}H(z,|F|) \,dz\,.
\t\t\t\end{split}
\t\end{align*}
    Here, $\kappa$ is defined in \eqref{K_and_kappa} and it appears in \ref{p4}.
 \end{proposition}
\begin{proposition}
    \label{q_est_vitali}
Suppose \ref{q1} and \ref{q2}.
\tThere exist constants $\theta_0=\theta_0(n,p,q)\in(0,1)$ and $c=c(n,N,p,q,\nu,L,\ca)$  such that for any $\theta\in(\theta_0,1)$ we have
\t\begin{align*}
\t\t\t\begin{split}
\t\t\t    \iint_{G_{2\cv\rho}^\la(z_0)}H(z,|\na u|)\,dz
\t\t\t&\le c\La^{1-\theta}\iint_{G_{2\rho}^\la(z_0)\cap \Psi(c^{-1}\La)}H(z,|\na u|)^\theta\,dz \\
            &\qquad+c\iint_{G_{2\rho}^\la(z_0)\cap \Theta(c^{-1}\La)}H(z,|F|)\,dz\,.
\t\t\t\end{split}
\t\end{align*}
    Here, $\kappa$ is defined in \eqref{K_and_kappa} and it appears in \ref{q5},
\end{proposition}
Since “intrinsic geometries may vary from point to point,” a standard Vitali lemma cannot be applied directly; “comparability of the scaling factors is ensured” by the following comparability statement.
\begin{lemma}\label{la_comp_lem}
    Suppose $U(w), U(v)\in \mathcal{F}$ with $U(w)\cap U(v)\ne \emptyset$ and $l_w\le 2l_v$. Then for $\cc\ge 2$ defined in Lemma~\ref{p_decay_lem}, we have
    \[
    \lav\le (2(1+\ca+10\cc\ca))^\frac{1}{p}\law\,.
    \]
    Moreover, if $U(v)$ is $(p,q)$-intrinsic, then we also have
    \[
    \law\le (2(1+\ca+10\cc\ca))^\frac{1}{p}\lav\,.
    \]
\end{lemma}
The range “$q\le p+\alpha$” in \eqref{range_pq} is stated to guarantee the needed small oscillation of $a(\cdot)$ over cylinders for the stopping-time/Vitali argument to work.

