for some $c_1 \ge 1$.
Assume that for some $S \in \pr{2^8, \frac R 2}$, there exists $z_0 \in \overline{B}_{R-S}$ and $L \ge 0$ such that
\begin{equation}
\label{propLB}
\abs{v(z_0)} \ge e^{- L}.
\end{equation}
Then there exists $r_0(a, R) > 1$ so that whenever $r \in (0, r_0)$, it holds that
\begin{align}
\label{propConc}
\norm{v}_{L^\iny(B_r)}
&\ge \pr{\frac{r} {R}}^{\tau},
\end{align}
with
$$\tau(R, S, L, a, c_1) = \max \set{3 a C_H\sqrt{\frac{C_K }{32\ln 2}} R \sqrt{\log R}, 2^{14} \pr{c_1 R + L + \frac {c_d}{\log R}} RS^{-1}} +\frac 1 5 \pr{L + \frac{c_d}{\log R}},$$
where $C_K$ and $c_d$ are universal constants, and $C_H$ is the Harnack constant from Lemma \ref{discBounds}.
\end{prop}

Define $\Om = B_R \setminus \pr{F_0 \bigcup F_1}$ and $\Om_1 = B_R \setminus F_1$.
As shown in \cite[\S 3.1]{LMNN20}, there exists a universal constant $c_P$ (that depends on $c_s$) so that $\Om$ has Poincar\'e constant bounded above by $c_P \rho^2$.
In particular, since $c_P \rho^2 \norm{W}_{L^\iny(B_R)} \le c_P \rho^2 a^2$, then by choosing $\rho \le \rho_0$, a universal constant, we can apply \cite[Lemma 3.2]{LMNN20}.
For $\eps \ll 1$ to be defined later on, let 
\begin{equation}
\label{rhoDef}
\rho = \eps a^{-1}.
\end{equation}
An application of the arguments in \cite[\S 3.2]{LMNN20} then shows that there exists $\phi : \Om \to \R$ with the properties that
\begin{align}
&\LP \phi - W \phi = 0 \text{ in } \Om
\nonumber \\
&\phi -1 \in W^{1,2}_0(\Om)
\nonumber \\
&\norm{\phi -1}_\iny \le c_b \pr{\rho a}^2 = c_b \eps^2,
\label{vpuBound}
\end{align}
where $c_b$ is a universal constant that depends on $c_P$, and we have used \eqref{rhoDef}.
By extending $\phi$ to equal $1$ across $F_0 \bigcup F_1$, it is then shown in \cite[Lemma 4.1]{LMNN20} that $\disp f := \frac v \phi \in W^{1,2}_{\loc}(B_R)$ is a weak solution to the divergence-form equation
$$\di\pr{\phi^2 \gr f} = 0 \; \text{ in } \Om_1.$$
Moreover, the bound in \eqref{vpuBound} implies that for any $z \in B_R$,
\begin{equation}
\label{ufComparison}
\pr{1 - c_b \eps^2} \abs{f(z)} \le \abs{v(z)} \le \pr{1 + c_b \eps^2} \abs{f(z)}.
\end{equation}

We introduce the Beltrami coefficient $\mu$, defined as follows:
\begin{equation*}
\mu = \left\{ \begin{array}{ll}
\frac{1 - \phi^2}{1 + \phi^2} \frac{f_x + i f_y}{f_x - i f_y} & \text{ in } \Om_1 \text{ when } \, \gr f \ne 0 \\
0 & \text{ otherwise}
\end{array} \right..
\end{equation*}
Since $\abs{\mu} \lesssim \eps^2$, then as shown in \cite{AIM09}, there exists a $K$-quasiconformal homeomorphism of the complex plane where $K \le 1 + C_K \eps^2$ and $C_K$ depends on $c_b$.
That is, there exists some $w \in W^{1,2}_{\loc}$ that satisfies the Beltrami equation $\disp \frac{\del w}{\del \overline{z}} = \mu \frac{\del w}{\del z}$. 
In fact, an application of the Riemann uniformization theorem shows that there exists a $K$-quasiconformal homeomorphism $g: B_R \to B_R$ that is onto with $g(0) = 0$.
Moreover, the function $h : = f \circ g^{-1}$ is harmonic in $g(\Om_1)$.

\begin{thm}[Initialization step]
\label{LandisGrowth}
For some $a_0 > 0$, let $V : \R^2 \to \R$ satisfy $\norm{V}_{L^\iny} \le a_0^2$.
Assume that $u : \R^2 \to \R$ is a solution to \eqref{ellipEq} that satisfies \eqref{solNorm} and for each $w \in \R^2$,
$$\abs{u(w)} \le \exp\pr{c_0 \abs{w}}.$$
Then there exists constants $\overline{C}_0 = \overline{C}_0\pr{a_0, c_0} > 0$ and $\overline{R}_0 > 0$ so that whenever $R \ge \overline{R}_0$, it holds that
\begin{equation}
\label{uLower0}
\inf_{\abs{w_0} = R}\norm{u}_{L^\iny\pr{B_1(w_0)}} \ge \exp\pr{- \overline{C}_0 R \log^{\frac 3 2} R}.
\end{equation}
\end{thm}

Now assume that \eqref{claim} holds for $k-1 \in \N$.
Define $S_k = \frac 1 2 \abs{z_{k-1}}$ and $R_k = \abs{z_{k-1}}^{\al_{k-1} +\de}$. 
Comparing with \eqref{zkNorm}, we see that $\abs{z_k} = R_k + S_k - 1$.
Since $B_1(z_{k-1}) \su B_{R_k - S_k}(z_k)$, then the inductive hypothesis shows that there exists $z_0 \in \overline{B}_{R_k - S_k}(z_k)$ so that
\begin{align*}
\abs{v(z_0)}
\ge \exp\pr{- \abs{z_{k-1}}^{\al_{k-1} + \de}}
= \exp\pr{- R_k}.
\end{align*}
The bound in \eqref{uBound} shows that $\disp \abs{v(z)} = \abs{u(T_\al(z))} \le \exp\pr{c_0 \abs{z}^{\al\pr{1 - \frac N 2}}} = \exp\pr{c_0 \abs{z}}$ from which it follows that
\begin{align*}
\norm{v}_{L^\iny\pr{B_{R_k}(z_k)}}
\le \exp\pr{c_0 \pr{\abs{z_k} + R_k}}
\le \exp\pr{\frac {5c_0} 2 R_k}.
\end{align*}
Let $W : \R^2_+ \to \R$ be given by $W(z) = \al^2 \abs{z}^{2\al - 2} V(T_\al(z))= \al^2 \abs{w}^{2 - \frac 2 \al} V(w)$ so that by \eqref{Vbound},
\begin{align*}
\abs{W(z)} = \al^2 \abs{w}^{2 - \frac 2 \al} \abs{V(w)} \le a_0^2 \al^2 \abs{w}^{2 - N - \frac 2 \al} = \pr{a_0 \al}^2.
\end{align*}
An application of Lemma \ref{transformEqLemma} with assumption \eqref{ellipEq} shows that
\begin{equation*}
- \LP v + W v = 0 \; \text{ in } \R^2_+.
\end{equation*}
As $R_k \ge \bar{r}_1$ implies that $R_k \ge \hat R_0(a_0 \al)$ and $S_k \in \pr{2^8, \frac {R_k} 2}$, Proposition \ref{InductiveProp} is applicable with $a = a_0 \al$, $R= R_k$, $S= S_k$, $L = R_k$, and $c_1 = \frac {5c_0} 2$.
With $r = 1$, Proposition \ref{InductiveProp} shows that
\begin{align}
\label{vkBd}
\norm{v}_{L^\iny(B_1(z_k))}
&\ge \exp\pr{-\tau_k(R_k) \log R_k},
\end{align}
where
\begin{equation}
\label{taukDefn}
\begin{aligned}
\tau_k(R_k) &= \max \set{3 a_0 \al C_H\sqrt{\frac{C_K }{32\ln 2}} R_k \sqrt{\log R_k}, 2^{15} \pr{\frac {5c_0} 2 + 1 + \frac {c_d}{R_k \log R_k}} R_k^{2 - \frac 1 {\al_{k-1} + \de}}} \\
&+\frac 1 5 \pr{R_k + \frac{c_d}{\log R_k}}.
\end{aligned}
\end{equation}
Because $R_k \ge \bar{r}_1$ and $\al_{k - 1} > 1$, conditions \eqref{rBig2} and \eqref{rBig3} imply that
\begin{align}
\label{tauKBound}
\tau_k(R_k) &\le \brac{2^{14} \pr{5c_0 + 4} + \frac 2 5} R_k^{2 - \frac 1 {\al_{k-1} + \de}} 
\end{align}
while condition \eqref{rBig4} implies that
$$ \brac{2^{14} \pr{5c_0 + 4} + \frac 2 5} \log R_k \le R_k^{\frac {\de^2} 2}.$$
Since $\al > 1$ and $\de \le 1$ implies that $2 - \frac{1}{\al + \de} + \frac{\de^2}2 < 2 - \frac 1 \al + \de$, then combining these bounds shows that
$$\tau_k(R_k) \log R_k \le R_k^{2 - \frac 1 {\al_{k-1}} + \de} = R_k^{\al_{k} + \de}.$$
Returning to \eqref{vkBd}, we conclude that
\begin{align*}
\norm{v}_{L^\iny(B_1(z_k))}
&\ge \exp\pr{-R_k^{\al_{k} + \de}}
\ge \exp\pr{-\abs{z_k}^{\al_{k} + \de}},
\end{align*}
establishing the claim given by \eqref{claim}.

expanded_sketch:
To prove the main theorem, the paper uses “an iterative argument that is reminiscent of the one in \cite{Dav14}.”

Key steps (as described):
\begin{itemize}
\item \textbf{Initialize the iteration.} “To initialize the iteration, we apply a quantitative estimate of the form
\begin{equation}
 \inf_{|x_0| = R}\norm{u}_{L^\iny\pr{B_1(x_0)}} \ge \exp{(-CR^{\be}\log R)},
\label{est}
\end{equation}
with $\beta = 1$,” namely the real-valued planar Landis growth result proved in \cite{LMNN20} and stated as
\begin{thm}[Initialization step]
\label{LandisGrowth}
For some $a_0 > 0$, let $V : \R^2 \to \R$ satisfy $\norm{V}_{L^\iny} \le a_0^2$.
Assume that $u : \R^2 \to \R$ is a solution to \eqref{ellipEq} that satisfies \eqref{solNorm} and for each $w \in \R^2$,
$$\abs{u(w)} \le \exp\pr{c_0 \abs{w}}.$$
Then there exists constants $\overline{C}_0 = \overline{C}_0\pr{a_0, c_0} > 0$ and $\overline{R}_0 > 0$ so that whenever $R \ge \overline{R}_0$, it holds that
\begin{equation}
\label{uLower0}
\inf_{\abs{w_0} = R}\norm{u}_{L^\iny\pr{B_1(w_0)}} \ge \exp\pr{- \overline{C}_0 R \log^{\frac 3 2} R}.
\end{equation}
\end{thm}

\item \textbf{Inductive improvement via a three-ball type step.} The iteration “relies on repeated applications of
\begin{prop}[Iterative Proposition]
\label{InductiveProp}
Given $a > 0$ and $R \ge \hat R_0(a)$, let $W : B_R \to \R$ satisfy $\norm{W}_{L^\iny(B_R)} \le a^2$ and let $v : B_R \to \R$ be a solution to 
$$-\LP v + W v = 0 \; \text{ in } B_R$$
with
\begin{equation}
\label{propUB}
\norm{v}_{L^\iny(B_R)} \le e^{c_1 R}
\end{equation}
for some $c_1 \ge 1$.
Assume that for some $S \in \pr{2^8, \frac R 2}$, there exists $z_0 \in \overline{B}_{R-S}$ and $L \ge 0$ such that
\begin{equation}
\label{propLB}
\abs{v(z_0)} \ge e^{- L}.
\end{equation}
Then there exists $r_0(a, R) > 1$ so that whenever $r \in (0, r_0)$, it holds that
\begin{align}
\label{propConc}
\norm{v}_{L^\iny(B_r)}
&\ge \pr{\frac{r} {R}}^{\tau},
\end{align}
with
$$\tau(R, S, L, a, c_1) = \max \set{3 a C_H\sqrt{\frac{C_K }{32\ln 2}} R \sqrt{\log R}, 2^{14} \pr{c_1 R + L + \frac {c_d}{\log R}} RS^{-1}} +\frac 1 5 \pr{L + \frac{c_d}{\log R}},$$
where $C_K$ and $c_d$ are universal constants, and $C_H$ is the Harnack constant from Lemma \ref{discBounds}.
\end{prop}
Roughly, this proposition shows that if an estimate like the equation above holds with exponent $\beta=\be_0$, then for some $x_1$ with “$|x_1|\gg |x_0|$,” another estimate like the equation above holds with $x_0$ replaced by $x_1$ and “$\beta=\be_1\in[1,\be_0]$.” Moreover, “when $\be_0>1$, we can decrease the exponent, i.e., make $\be_1<\be_0$.”

\item \textbf{Create a regime with $\beta>1$ via a power map.} Since “when $\be_0=1$, the iterative proposition above isn’t useful,” they “transform to a situation where $\be_0>1$” by composing $u$ with “the real-variable version of the conformal transformation $z\mapsto z^\alpha$,” noting the composed function still “satisfies a Schr\"odinger equation.” Choosing “$\alpha>1$ appropriately,” they ensure “the new potential function is bounded” and the new solution satisfies a version of the equation above “with $\beta>1$.”

\item \textbf{Iterate to push $\beta$ down to $1$.} “By repeatedly applying the iterative proposition above to the transformed equation, we can make $\beta$ arbitrarily close to $1$.”

\item \textbf{Conclude by reversing the change of variables.} “Finally, to reach the conclusion, we undo the change of variables.” This completes the proof of the main theorem.
\end{itemize}

