To prove the latter, we need several lemmas. The first two concern how fast two automorphisms of the disk diverge from each other if they are close in~$0$. The first one comes from our previous work. The formulation is slightly modified for our purposes, but the statement is exactly the one that is proven (with the notations below, because $e^{-R}\leq1-\Cmod{\xi}^2\leq2e^{-R}$, if~$R$ is sufficiently large). The second one comes from Dinh, Nguy\^{e}n and Sibony's work on the entropy of foliations. A more precise version of it can be found in~\cite[Lemma~3.14]{Bac4}, but the one here is sufficient for our needs.

\begin{lem}[{\cite[Lemma~3.11]{Bac4}}]\label{lemBac4angles} Let~$\eps>0$ be sufficiently small, $\theta\in\intcc{-\pi}{\pi}$ and $\xi\in\set{D}$ be such that $R=\dPC{0}{\xi}$ is sufficiently large.
  \begin{enumerate}[label=(\roman*),ref=\roman*]
  \item \label{lemBac4<} If $e^{-R}\geq 8\eps^{-1}\Cmod{\sin(\theta/2)}$, then $\dPC{\xi}{e^{i\theta}\xi}\leq\eps$.
  \item \label{lemBac4>} If $e^{-R}\leq \frac{1}{4}\eps^{-1}\Cmod{\sin(\theta/2)}$, then $\dPC{\xi}{e^{i\theta}\xi}\geq\eps$.
  \end{enumerate}
\end{lem}

\begin{lem}[{\cite[Lemma~3.8]{DNSI}}]\label{lemDNS1Aut}
  Let $\eps>0$ be sufficiently small. There exists $A>1$ such that for all $a,b\in\set{D}$, we have the following.
  \begin{enumerate}[label=(\roman*),ref=\roman*]
  \item\label{lemDNSI<} If $\dPC{a}{b}\leq A^{-1}e^{-R}$, then there exist $\tau_a,\tau_b\in\Aut(\set{D})$ such that $\tau_a(0)=a$, $\tau_b(0)=b$ and $\dPCs{\adhDR{R}}{\tau_a}{\tau_b}\leq\eps$.
  \item\label{lemDNSI>} If $\dPC{a}{b}\geq Ae^{-R}$, then for all $\tau_a,\tau_b\in\Aut(\set{D})$ such that $\tau_a(0)=a$ and $\tau_b(0)=b$, $\dPCs{\adhDR{R}}{\tau_a}{\tau_b}\geq\eps$.
  \end{enumerate}
\end{lem}
  Above, recall the notation
  \[\dPCs{K}{\tau}{\sigma}=\sup_{\xi\in K}\,\dPC{\tau(\xi)}{\sigma(\xi)},\]
  for $K\subset\set{D}$ and $\tau,\sigma\in\Aut(\set{D})$.

  Now, we also need a simple result which compares the Poincaré metric on the disk and on close points in~$S$. Recall the notation~$\phi_t$, for $t\in\set{T}_0$, introduced in~\eqref{defphit}.

  \begin{lem}\label{lemh>dp>eps} There exist $h>0$ and $c>1$ such that
    \begin{enumerate}[label=(\roman*),ref=\roman*]
    \item \label{dp<eps} if $t\in\set{T}_0$ and $\zeta,\xi\in\set{D}$, then $d(\phi_t(\zeta),\phi_t(\xi))\leq c\dPC{\zeta}{\xi}$;
    \item \label{dp>eps} if $t,s\in\set{T}_0$, $\zeta,\xi\in\set{D}$ are such that $\dPC{\zeta}{\xi}\leq h$, then $d(\phi_t(\zeta),\phi_s(\xi))\geq c^{-1}\dPC{\zeta}{\xi}$.
    \end{enumerate}
  \end{lem}

  \begin{proof} Note that $\phi_t(\zeta)=\phi_{t'}(\zeta')$, for some $\zeta'\in D$ and $t'\in\set{T}_0$. Then, the statement~\eqref{dp<eps} follows immediatly from the equivalence of Hermitian metrics~\eqref{bndeta} and a compactness argument. For statement~\eqref{dp>eps}, let us choose $h>0$ such that
    \begin{equation}\label{condh}\dPC{\xi}{\alpha(\xi)}>2h,\qquad\xi\in\set{D},\alpha\in\Gamma\setminus\{\id\}.\end{equation}
    It is classical that such an~$h$ exists, since~$\Gamma$ is cocompact and since each $\alpha\in\Gamma\setminus\{\id\}$ has no fixed point. Reducing~$h$ if necessary, it is sufficient to prove the statement only for $\phi_t(\zeta)$ and $\phi_s(\xi)$ belonging to a common chart $U\simeq\set{D}\times\set{B}^p$ of the ambient Riemannian manifold~$\mani{M}$, where $\set{B}^p$ is the unit ball of some~$\set{R}^p$. Take a Riemannian geodesic joining $\phi_t(\zeta)$ and $\phi_s(\xi)$. If~$h$ is sufficiently small, it stays inside~$U$ and its projection in the leafwise direction joins~$\zeta$ to some~$\alpha(\xi)$, $\alpha\in\Gamma$. So that it is of Poincaré length at least~$\dPC{\zeta}{\xi}$, thanks to condition~\eqref{condh}. We conclude by compactness of $D\times\set{T}_0$, the equivalence of Riemannian metrics and~\eqref{bndeta}.  \end{proof}

