\subsection{Hyperbolic entropy}\label{subsechypent} Consider a lamination~$\fol=\nspllam$, the leaves of which are hyperbolic, where $(X,d_X)$ is a compact metric space. For each~$x\in X$, denote by~$\leafu{x}$ the leaf of~$\fol$ through~$x$ and by $\phi_x\colon\set{D}\to\leafu{x}$ a uniformization of~$\leafu{x}$ such that $\phi_x(0)=x$. Such a uniformization is unique up to precomposition by a rotation.

\begin{defn}[See~{\cite[Section~3]{DNSI}}]\label{defnN(Y,R,E)} For $R>0$, denote by~$\DR{R}=\{\xi\in\set{D}~;~\dPC{0}{\xi}<R\}$, where~$\dPCnov{}$ is the Poincaré distance on~$\set{D}$. Define the \emph{Bowen distance}
  \begin{equation}\label{defdR}d_R(x,y)=\inf_{\theta\in\set{R}}\sup_{\xi\in\adhDR{R}}\,d_X(\phi_x(\xi),\phi_y(e^{i\theta}\xi)),\qquad x,y\in X.\end{equation}

