In this case, we we reduce \eqref{eq: crucialreduce} to proving that for all $\omega \in F_\epsilon - G_\epsilon$, one has
 \begin{equation}\label{eq: I-I-II}
 \sup_{0\leq \tau\leq t} \sum_{R_{n}(n_1,n_2,n_3)} \frac{|g_{n_1}g_{n_2}h_{n_3}|}{\<n_1\>^{\frac{1}{2}+\theta }\<n_2\>^{\frac{1}{2}+\theta }} 
 \lesssim \<n\>^{-\theta + \delta_5} \epsilon ^{-3/2-3\delta_1}.
 \end{equation}
 Using Cauchy-Schwarz inequality and \eqref{eq: gepsic}, for all $\omega \in F_\epsilon - G_\epsilon$, we have
 \begin{equation}\label{eq: uniformI-I-II}
 \begin{aligned}
 &\sup_{0\leq \tau\leq t} \sum_{R_{n}(n_1,n_2,n_3)} \frac{|g_{n_1}g_{n_2}h_{n_3}|}{\<n_1\>^{\frac{1}{2}+\theta }\<n_2\>^{\frac{1}{2}+\theta }}\\
 &\lesssim \|h\|_{C_t[0,T]H^s} \left(\sum_{n_3} \<n_3\>^{-2s} \left|\sum_{R_{n_3,n}(n_1,n_2)} \frac{\epsilon ^{-1-2\delta_1 } }{\left\langle n_1 \right\rangle ^{1/2+ \theta -\delta_4 } \left\langle n_2 \right\rangle ^{1/2 + \theta -\delta_4}}\right|^2\right)^\frac{1}{2}\\
 &\lesssim \epsilon ^{-3/2 -3\delta_1 } \left(\sum_{n_3} \<n_3\>^{-2s} \left|\sum_{R_{n_3,n}(n_1,n_2)} \frac{1}{\left\langle n_1 \right\rangle ^{1/2+ \theta -\delta_4 } \left\langle n_2 \right\rangle ^{1/2 + \theta -\delta_4}}\right|^2\right)^\frac{1}{2},
 \end{aligned}
 \end{equation}
 where for fixed $n,n_3$, we denote $R_{n_3,n}(n_1,n_2) := \{(n_1,n_2)\in\mathbb{Z}^2:n=n_1-n_2+n_3,n_2\neq n_1,n_3\}$.
 Next, we aim to reduce \eqref{eq: I-I-II} to following
 \begin{equation}\label{eq: mainreductionI-I-II}
 \sum_{R_{n_3,n}(n_1,n_2)} \frac{1}{\left\langle n_1 \right\rangle ^{1/2+ \theta -\delta_4 } \left\langle n_2 \right\rangle ^{1/2 + \theta -\delta_4}}
 \lesssim \left\langle n-n_3 \right\rangle ^{-2\theta +2\delta_5} .
 \end{equation}
 If \eqref{eq: mainreductionI-I-II} holds, noting that
 \begin{equation*}
 \sum_{|n_3|\ll |n|} \<n_3\>^{-2s} \left\langle n-n_3 \right\rangle ^{-4\theta +4\delta_5}
 \lesssim \<n\>^{-4\theta +4\delta_5} 
 \end{equation*}
 and
 \begin{equation*}
 \sum_{|n_3|\gg |n|} \<n_3\>^{-2s} \left\langle n-n_3 \right\rangle ^{-4\theta +4\delta_5}
 \sim \sum_{|n_3|\gg |n|} \<n_3\>^{-2s-4\theta +4\delta_5} 
 \lesssim \<n\>^{-4\theta +4\delta_5} 
 \end{equation*}
 and
 \begin{equation*}
 \sum_{|n_3|\sim |n|} \<n_3\>^{-2s} \left\langle n-n_3 \right\rangle ^{-4\theta +4\delta_5}
 \sim \<n\>^{-2s} \sum_{|n_3|\sim |n|} \<n_3-n\>^{-4\theta +4\delta_5} 
 \lesssim \<n\>^{1-2s-4\theta +4\delta_5},
 \end{equation*}
 then we have
 \begin{equation*}
 \sum_{n_3} \<n_3\>^{-2s} \left\langle n-n_3 \right\rangle ^{-4\theta +4\delta_5}
 \lesssim \<n\>^{-4\theta +4\delta_5},
 \end{equation*}
 which, along with \eqref{eq: mainreductionI-I-II} and \eqref{eq: uniformI-I-II}, yields \eqref{eq: I-I-II}. So we reduce \eqref{eq: I-I-II} to \eqref{eq: mainreductionI-I-II} if we take \fbox{$\delta_5< \theta $}. Similarly, 
 noting that
 \begin{equation*}
 \sum_{|n_1|\ll |n-n_3|} \<n_1\>^{\delta_4-\frac{1}{2}-\theta } \left\langle n-n_3-n_1 \right\rangle ^{\delta_4-\frac{1}{2}-\theta}
 \lesssim \left\langle n-n_3\right\rangle ^{\delta_4-\frac{1}{2}-\theta} \sum_{|n_1|\ll |n-n_3|} \<n_1\>^{\delta_4-\frac{1}{2}-\theta }
 \lesssim \left\langle n-n_3\right\rangle ^{2\delta_4-2\theta} 
 \end{equation*}
 and
 \begin{equation*}
 \sum_{|n_1|\gg |n-n_3|} \<n_1\>^{\delta_4-\frac{1}{2}-\theta } \left\langle n-n_3-n_1 \right\rangle ^{\delta_4-\frac{1}{2}-\theta}
 \sim \sum_{|n_1|\gg |n-n_3|} \<n_1\>^{2\delta_4-1-2\theta } 
 \lesssim \<n-n_3\>^{-2\theta +2\delta_4} 
 \end{equation*}
 and
 \begin{equation*}
 \sum_{|n_1|\sim |n-n_3|} \<n_1\>^{\delta_4-\frac{1}{2}-\theta } \left\langle n-n_3-n_1 \right\rangle ^{\delta_4-\frac{1}{2}-\theta}
 \sim \left\langle n-n_3\right\rangle ^{\delta_4-\frac{1}{2}-\theta} \sum_{|n_1|\sim |n-n_3|} \left\langle n-n_3-n_1 \right\rangle ^{\delta_4-\frac{1}{2}-\theta}
 \lesssim \<n-n_3\>^{-2\theta +2\delta_4} ,
 \end{equation*}
 then we have \eqref{eq: mainreductionI-I-II}
 if we take \fbox{$\delta_5\leq \delta_4$}.

post_theorem_intro_text:
\begin{rem}
Upon finishing of this work, we notice a recent preprint of Liang-Wang, \cite{liang2025random},  which handles Theorem \ref{thm: main} in the case $\theta>\frac{1}{2}$. It should be noted that when $\theta>\frac{1}{2}$, the Fourier coefficient is in $l^{1}$, which forms an algebra. We handle all $\theta>0$.\\

Both \cite{garrido2023large}, \cite{liang2025random}, and this work actually work for time scale for $c\epsilon^{-1}|\ln \epsilon|$, for some $c$ small but universal. Such improvement comes from standard improvement in Gronwall argument. In \cite{liang2025random}, they state the time scale as $O(\epsilon^{-1}|\ln \epsilon|)$, however, it seems hard to cover time scale for $C\epsilon^{-1}|\ln \epsilon|$ for $C$ large, see the line below (3.30) in \cite{liang2025random}.
\end{rem}

\subsection{Background and motivation}
This work is inspired by the pioneering work \cite{garrido2023large}. Motivated by rogue wave phenomena, Garrido, Grande, Kurianski and Staffilani study \eqref{eq: main}, with random initial data of form \eqref{eq: rmain}, but for $c_{n}=ae^{-b|n|}$. They essentially
\footnote{They state the result for pointwise in $t\leq T_{\epsilon}\sim \epsilon^{-1}$. We take this chance to cover $\|u\|_{L_{t,x}^{\infty}}$ rather than estimate pointwise in $t$.} obtained \eqref{eq: estimatemain} for such types of random initial data. It has been remarked in \cite[Remark 1.3]{garrido2023large}, \textit{finding optimal family of coefficients (in terms of decay)}, rather than considering exponential decay $c_{n}$, remains an interesting open question.

By combining random data type techniques in \cite{bourgain1994periodic,bourgain1996invariant} and some ideas in \cite{compaan2021pointwise} (which also goes back to Bourgain's 1990s seminal work), we are able to extend the result in \cite{garrido2023large} to coefficients with polynomial decay $\langle n\rangle^{-\frac{1}{2}-\theta}$, $\theta>0$. Such constraint is optimal in the sense when $
\theta\leq 0$, even the initial data will leave $L_{x}^{\infty}$. It remains an interesting question to go beyond the time scale $T_{\epsilon}$. We note that this $\epsilon^{-1}$ time scale (neglecting logarithm corrections) is in some sense critical and we refer to \cite[Remark 1.7]{garrido2023large} for more details.
We note that both current work and \cite{garrido2023large},  can cover time scale of form $c\frac{|\ln \epsilon|}{\epsilon}$, where $c$ is some small universal number.\\

The overall proof scheme of current article follows \cite{garrido2023large}, which contains a large deviation principle for the (modified) linear flow and a smoothing estimate for the Duhamel part, (there is some subtle part here since one needs to first slightly perturb the free linear flow, we will discuss it later).\\

 Our main contributions in this work are
\begin{itemize}
\item We find a rather straightforward proof for the large deviation principle for the linear flow, which simplifies the arguments in \cite{garrido2023large}, and more importantly, extends to random initial data of form $\sum_{n}\frac{g^\omega _n}{\<n\>^{\frac{1}{2}+\theta}}e^{inx}$, $\forall \theta>0$. Our techniques for this part are crucial for our further analysis in the nonlinear smoothing part.
\item We adapt the $X^{s,b}$ analysis in \cite{bourgain1994periodic,bourgain1996invariant} in the setting of long time analysis of \cite{garrido2023large}, which gives the desired nonlinear smoothing\footnote{On one hand, we will use the $X^{s,b}$ analysis in the local random data theory as a black box;  on the other hand, the long time analysis we use to get nonlinear smoothing does explicitly use computations of $X^{s,b}$ type, but without going to the explicit form of $X^{s,b}$ analysis.}.
\end{itemize}

We end this session by pointing out ever since the seminal work \cite{bourgain1994periodic,bourgain1996invariant}, random initial data theory in nonlinear dispersive PDEs has become a very active research field. Many researchers contribute to this field and it is impossible to survey the field here. We simply mention that  in the perspective of  regularity in NLS model, the recent breakthrough \cite{deng2022random} gives a quite complete answer. We refer to \cite{deng2022random}, \cite{garrido2023large} and reference therein for more related reference.

\subsection{Notation}
Many terms $g_{n}^{\omega}, u^{\omega}, u_{0}^{\omega}$ are random, and thus depend on $\omega$. For simplicity, we will hide the implicit $\omega$ and simply denote them as $g_{n}, u,u_{0}$.\\

We introduce $\NNN_{1}, \NNN_{2}$ as 
\begin{equation}\label{eq: n1}
\NNN_{1}(f_{1},f_{2},f_{3})=\sum_{n_{2}\neq n_{1}, n_{3}}\hat{f}_{1}(n_{1})\overline{\hat{f}_{2}}(n_{2})\hat{f}_{3}(n_{3})e^{i(n_{1}-n_{2}+n_{3})x},
\end{equation}
\begin{equation}\label{eq: n_{2}}
\NNN_{2}(f_{1},f_{2},f_{3})=\sum_{n}\hat{f}_{1}(n)\overline{\hat{f}_{2}}(n)\hat{f}_{3}(n)e^{inx}	
\end{equation}
and one has 
\begin{equation}\label{eq: algebra}
|f|^{2}f-2\frac{1}{2\pi}(\int |f|^{2})f=\NNN_{1}(f,f,f)-\NNN_{2}(f,f,f)	
\end{equation}
We sometimes short $\NNN_{i}(f,f,f)$ as $\NNN_{i}(f)$.

