\begin{theorem} \label{nc CZ decomposition with convolution}
	Fix $f\in\mN_{c,+}$, $\lambda>0$, and $s\in\N$.
	Let $(q_n)_{n\in\Z}$ and $(p_n)_{n\in\Z}$ be the sequences of projections in Lemma \ref{cuculescu's construction}, where $q_n = \sum\limits_{Q\in\mQ_n} q_Q \chi_Q$, $p_n = \sum\limits_{Q\in\mQ_n} p_Q \chi_Q$.
	Suppose $h\in C_{c}^{\infty} (\R^d)$ satisfies
    \begin{align*}
    \supp h \subset B_1,\quad \int_{\R^d} h =1, \quad h\geq 0.
    \end{align*}
    Define $h_r(x)= \frac{1}{r^d} h(\frac{x}{r})$ and $r_n= 2^{-n-1}\sqrt{d}$.
	Then, $f$ admits the decomposition:
	\begin{align*}
	f = g+ b
	  = g + \widetilde{b}_{\text{d}} + b_{\text{d}}^0 + \widetilde{b}_{\text{off}} + b_{\text{off}}^0,
	\end{align*}
	where $g$ is positive and $b$ is self-adjoint in $\mN$.
	More precisely, these components are defined as follows:
	    \[g=qfq + \sum\limits_{n\in\Z}p_n f_n p_n,\]
        \begin{gather*}
        \widetilde{b}_{\text{d}} = \sum\limits_{n\in\Z} \widetilde{b}_{\text{d},n} = \sum\limits_{n\in\Z}\sum\limits_{Q\in\mQ_n}\widetilde{b}_{\text{d},n}^Q ,\quad
        b_{\text{d}}^0 = \sum\limits_{n\in\Z} b_{\text{d},n}^0=\sum\limits_{n\in\Z} \sum\limits_{Q\in\mQ_n}(b_{\text{d},n}^Q-\widetilde{b}_{\text{d},n}^Q),\\
        \widetilde{b}_{\text{off}} = \sum\limits_{n\in\Z} \widetilde{b}_{\text{off},n} = \sum\limits_{n\in\Z} \sum\limits_{Q\in\mQ_n} \widetilde{b}_{\text{off},n}^Q ,\quad
        b_{\text{off}}^0 = \sum\limits_{n\in\Z} b_{\text{off},n}^0 = \sum\limits_{n\in\Z}\sum\limits_{Q\in\mQ_n}(b_{\text{off},n}^Q-\widetilde{b}_{\text{off},n}^Q),
        \end{gather*}
     where for each $Q\in\mQ_n$,
        \begin{gather*}
     	b_{\text{d},n}^Q = p_Q(f-f_n)p_Q\chi_Q,
     	\quad b_{\text{off},n}^Q = p_Q(f-f_n)q_Q\chi_Q + q_Q(f-f_n)p_Q\chi_Q, \\
     	\widetilde{b}_{\text{d},n}^Q = b_{\text{d},n}^Q * h_{r_n},
     	\quad \widetilde{b}_{\text{off},n}^Q = b_{\text{off},n}^Q * h_{r_n}.
        \end{gather*}
    \end{theorem}

