\textbf{Step 1.}
Let $T_{\epsilon}$ be a noncommutative Calder\'on-Zygmund truncated operator with a complex kernel $K$ (defined as in (\ref{def of T epsilon f})).
We decompose $K$ into its real and imaginary parts: $\Re(K)$ and $\Im(K)$.
The truncated operators associated with $\Re(K)$ and $\Im(K)$ are then given by
 \begin{align*}
 \Re(T_{\epsilon})f(x) = \int_{|x-y|>\epsilon} \Re(K)(x,y) f(y) \dif y
 \end{align*}
and
 \begin{align*}
 \Im(T_{\epsilon})f(x) = \int_{|x-y|>\epsilon} \Im(K)(x,y) f(y) \dif y.
 \end{align*}
\begin{lemma}\label{reduction to real kernel}
 Let $T$ be a noncommutative Calder\'on-Zygmund operator (defined as in (\ref{def of Tf})) whose kernel $K$ satisfies (\ref{Size condition}) and the $L_2$-mean H\"ormander condition (\ref{L2 mean Hormander condition}).
 Let $T_{\epsilon}$ be defined as in (\ref{def of T epsilon f}).
 Then,
 \begin{enumerate}[(i)]
 \item Both $\Re(K)$ and $\Im(K)$ satisfy (\ref{Size condition}) and (\ref{L2 mean Hormander condition}).
 \item If $(T_{\epsilon})_{\epsilon>0}$ is of strong type $(p_0,p_0)$ for some $p_0\in (1,\infty)$, then, both $(\Re(T_{\epsilon}))_{\epsilon>0}$ and $(\Im(T_{\epsilon}))_{\epsilon>0}$ are of strong type $(p_0,p_0)$.
 \item If $(\Re(T_{\epsilon}))_{\epsilon>0}$ and $(\Im(T_{\epsilon}))_{\epsilon>0}$ are of weak type $(1,1)$, so is $(T_{\epsilon})_{\epsilon>0}$.
 \end{enumerate}
\end{lemma}
By this lemma, we may assume that the kernel $K$ is real throughout this paper.

\begin{lemma}\label{reduction to lacunary sequence}
 Let $T$ be a noncommutative Calder\'on-Zygmund operator (defined as in (\ref{def of Tf})) whose kernel $K$ satisfies (\ref{Size condition}) and the $L_2$-mean H\"ormander condition (\ref{L2 mean Hormander condition}).
 Let $T_{\epsilon}^{i_{\epsilon}}$ be defined as in (\ref{T epsilon,i epsilon f(x)}).
 Then
 \begin{enumerate}[(i)]
 \item $(T_{\epsilon}^{i_{\epsilon}})_{\epsilon>0}$ is of strong type $(p,p)$ for $1<p\leq\infty$.
 \item $(T_{\epsilon}^{i_{\epsilon}})_{\epsilon>0}$ is of weak type $(1,1)$.
 \end{enumerate}
 \end{lemma}

The preceding two lemmas imply that Theorem \ref{Main theorem} follows directly from the weak type (1,1) boundedness of $S_i$ given in (\ref{Sif(x)}).
Thus, it remains to prove
\begin{theorem}\label{Second theorem}
 Let $T$ be a noncommutative Calder\'on-Zygmund operator defined as in (\ref{def of Tf}) with the real kernel $K$ satisfying (\ref{Size condition}) and the $L_2$-mean H\"ormander condition (\ref{L2 mean Hormander condition}).
 Let $S_i$ be defined as in (\ref{Sif(x)}).
 Then, the sequence of operators $(S_i)_{i\in\Z}$ is of weak type $(1,1)$, that is, for any $f\in L_1(\mN)$,
 \[
 \norm{(S_i f)_{i\in\Z}}_{\Lambda_{1,\infty}(\mN;\ell_{\infty})} \lesssim \norm{f}_{L_1(\mN)}.
 \]
