 & \cdot \Big\|\Big(\int_{Q} q_Q f(u) q_Q \dif u\Big)^{\frac{1}{2}} \Big\|_{L_{\infty}(\mM)}.
 \end{align*}
For the second term, an application of \eqref{q_Q f_Q q_Q < lambda q_Q} shows that
 \begin{align*} \Big\|\Big(\int_{Q} q_Q f(u) q_Q \dif u\Big)^{\frac{1}{2}} \Big\|_{L_{\infty}(\mM)} \lesssim (|Q|\lambda)^{\frac{1}{2}}.
 \end{align*}
Hence,
 \begin{align}
 F_1
 \lesssim &\sum_{n\geq 2} \sum_{j\leq n-1} \sum_{Q\in\mQ_{n-j}} (|Q|\lambda)^{\frac{1}{2}} \notag\\
 & \label{xxxyyy}\frac{1}{|B_{r_{n-j}}|}\int_{\R^d} \Big\|\int_{Q} \Big(\int_{B_{r_{n-j}}(u)} \abso{K_i(x,y)-K_i(x,c(Q))} \dif y \Big)^2 p_Q f(u)p_Q \dif u\Big\|_{L_{\frac{1}{2}}(\mM)}^{\frac{1}{2}} \dif x.
 \end{align}
The same argument as in (\ref{B(c(Q))}) allows us to majorize (\ref{xxxyyy}) by
 \begin{align*}
 \frac{1}{|B_{r_{n-j-1}}|}\int_{\R^d} \Big\|\int_{Q} \Big(\int_{B_{r_{n-j-1}}(c(Q))} \abso{K_j(x,y)-K_j(x,c(Q))} \dif y \Big)^2 p_Q f(u)p_Q \dif u\Big\|_{L_{\frac{1}{2}}(\mM)}^{\frac{1}{2}} \dif x.
