\right.
\end{equation}
\end{thmx}

Suppose that $f\in C^{4,\alpha}(\bar\B_1)$ and $g\in C^{6,\alpha}(\partial\B_1)$ for some $\alpha\in (0,1)$. Then, there exists a $C^6(\bar\B_1)$-extension of $g$ such that the solutions $u, \bar u$ of
\begin{equation}\label{eq:elliptic-dirich}
\left\{
