and
\begin{align*}
        &\sum_{i=1}^{n}  \left( \int_{B_{R/4}} |u_{x_i x_j}|^2|u_{x_i}|^{p_i-2}dx \right) \notag\\
         &\leq c  \left( 1+\sum_{i=1}^{n} \left(\Vert u_{x_i} \Vert_{L^{p_i}(B_R)} + {\Vert \omega_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})}} \right) +\Vert \omega\Vert_{L^t(B_R)}+ \Vert g \Vert_{L^r (B_{R})} \right)^\sigma 
\end{align*}
hold for every pair of concentric balls $B_{R/4} \subset B_{R} \Subset \Omega$, where $c = c(n,p_i,\lambda, \Lambda,R, \Vert u \Vert_{\infty})$ and $\sigma= \sigma (n,p_i, r)$ are positive constants.

