\section{A priori estimates}\label{Apriorisec}
The main aim of this section is to establish the following a priori estimate which is the main step in the proof of our main result.
\begin{thm}\label{AppThm}
Let $\omega \in W^{1,\frac{\mathbf{p}+2}{\mathbf{p}+1}}_{\mathrm{loc}}(\Omega)$ and let $u \in  W^{1, \mathbf{p}}_{\mathrm{loc}}(\Omega) \cap L^\infty_{\mathrm{loc}}(\Omega)$  be a local minimizer of \eqref{functional} under assumptions \eqref{A2}--\eqref{A4}, with exponents $p_i\geq 2, \forall i=1,\dots,n $, such that $p_n < p_1+2$,
and with a function $g \in L^{r}_{\mathrm{loc}}{(\Omega)}$, where $r$ satisfies the condition
\eqref{Ipotesir}.
If we assume that 
\begin{equation}\label{Apriori}
V_{p_i}(u_{x_i}) \in {W^{1,2}_{\mathrm{loc}}(\Omega)}, \qquad\forall i=1,\dots,n,
\end{equation}
then the following estimates
\begin{align}\label{uxistima}
    \sum_{i=1}^{n} \left(  \int_{B_{R/4}} |u_{x_i}|^{p_i +2 } dx \right) & \leq c  \left(1+ \sum_{i=1}^{n} \left(\Vert u_{x_i} \Vert_{L^{p_i}(B_R)} + \Vert \omega_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})} \right) + \Vert g \Vert_{L^r (B_{R})} \right)^\gamma 
\end{align}

