\begin{lem}\label{LemmaTroisi}
    Let $E \subset \mathbb{R}^n$ be a bounded open set and consider $u \in W^{1, \mathbf{p}}(E)$, with $  p_i \geq 1$, for all $i=1, ..., n$.\\
    If $\overline{p} \le n$, then there exists a positive constant $\gamma_1$ depending on $n, p_i$ and, only in the case $\overline{p}=n$, also on $\overline{p}^*$ and $E$, such that
    \begin{align*}
        \lvert \lvert u \rvert \rvert_{L^{\overline{p}^*}(E)} \leq \gamma_1  \left[ \sum_{i=1}^{n} \lvert \lvert u_{x_i} \rvert \rvert_{L^{p_i}(E)} + \lvert \lvert u \rvert \rvert_{L^1(E)} \right].
    \end{align*}
      If $\overline{p} > n$,  there exists a positive constant $\gamma_2$ depending only on $ n, p_i$ and $E$, such that
    \begin{align*}
        \lvert \lvert u \rvert \rvert_{L^{\infty}(E)} \leq \gamma_2  \left[ \sum_{i=1}^{n} \lvert \lvert u_{x_i} \rvert \rvert_{L^{p_i}(E)} + \lvert \lvert u \rvert \rvert_{L^1(E)} \right].
    \end{align*}
\end{lem}

