\section{Approximation}\label{Appro}

In order to perform the approximation argument, let us fix a non-negative smooth kernel $\phi \in \mathcal{C}^\infty_0(B_1(0))$ such that $\int_{B_1(0)} \phi =1$ and consider the corresponding family of mollifiers $(\phi_k)_{k >0}$. We set, for a given ball $B_R \Subset \Omega$ ,
$$a_i^k=a_i * \phi_k, \quad \omega^k= \omega * \phi_k,$$
\begin{equation}\label{gk}
g_k(x)=\underset{i}{\max} \{ |D a_i^k (x)|\}
\end{equation}
and, for $x \in B_R$, we define
\begin{equation}\label{fvarepsilon}
f^k (x,\xi)= \sum_{i=1}^{n} a_i^k(x)|\xi|^{p_i} ,
\end{equation}
 for every $k < \text{dist}(B_R,\Omega)$. We shall use the following $$\mathcal{F}^{k}(v,B_R):=\int_{_{B_R} }\left( f^{k}(x, Dv)-\omega(x)v(x) \right) dx$$ and
$$\mathcal{F}^{k}_{\varepsilon}(v,B_R):= \, \int_{B_R} \left( f^k(x,Dv)+ \varepsilon(1+ |Dv|^2)^{\frac{p_n}{2}}- \omega^k(x)v(x) \right) dx.$$
\begin{flushleft}
One can easily check that $f^k(x, \xi)$ satisfies assumptions \eqref{A2}--\eqref{A3} and \eqref{A'4}, with $K = \sup_{B_R} |g_k(x)| $ that is finite since $a^k_i(x) \in W^{1, \infty}(B_R)$ and then $g_k \in L^{\infty}(B_R)$.\\
\end{flushleft}

We are in position to prove our main result.

\begin{proof}[\textit{{Proof of Theorem~\ref{thmBfinito}}}]
We consider the variational problems
\begin{equation}\label{Pfj}
    \inf \left\{  \int_{B_R} \left( f^k(x,Dv)+ \varepsilon(1+ |Dv|^2)^{\frac{p_n}{2}} -\omega^k(x)v(x)\right) dx \ : \ v \in W^{1,p_n}_0(B_R)+u^\eta \right\},
\end{equation}
where $$u^\eta = u * \varsigma_\eta$$ is the mollification of the local minimizer $u$ of \eqref{functional}, for a sequence of mollifier $\varsigma_n$.\\
It is well known that, by the direct methods of the calculus of variations, there exists a unique solution $u^\eta_{k,\varepsilon} \in  W^{1,p_n}_0(B_R)+u^\eta $ of the problem \eqref{Pfj}. Since the integrand $$f^k(x,Dv)+ \varepsilon(1+ |Dv|^2)^{\frac{p_n}{2}}-\omega^k(x)v(x)$$ satisfies the assumptions of  Theorem \ref{thm2Mascolo}, we have that $$V_{p_i}((u^\eta_{k,\varepsilon})_{x_i}) \in W_{\mathrm{loc}}^{1,2}(B_R) \quad \forall i=1,...,n.$$
Hence we are legitimate to use estimate \eqref{uxistima} of Theorem \ref{AppThm}, to obtain that
\begin{align}
   & \sum_{i=1}^{n}  \int_{B_{R/4}}|(u^\eta_{k,\varepsilon})_{x_i}|^{p_i +2 } dx \notag \\
    & \leq c \left(1+ \sum_{i=1}^{n} \left(\int_{B_R}\, \lvert(u^\eta_{k,\varepsilon})_{x_i} \rvert^{p_i} \ dx+  \Vert \omega^k_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})} \right)  + \Vert g_k \Vert_{L^r (B_{R})} \right)^\sigma \notag \\
     &  \leq c(\lambda) \left(1+ \sum_{i=1}^{n} \left( \int_{B_R} a_i^k(x)\, \lvert (u^\eta_{k,\varepsilon})_{x_i}\rvert^{p_i} \ dx +  \Vert \omega^k_{x_i} \Vert_{L^\frac{p_i+2}{p_i+1}(B_{R})} \right) + \Vert g_k \Vert_{L^r (B_{R})} \right)^\sigma, \label{der}
\end{align}

