Let us introduce some notation used throughout this work. From now on, we have the following: 
	 \begin{itemize}
	 \item[i.] The vector $u$ is given by $u=(u_1,...,u_N) \in \mathbb{L}^2(\mathcal{T})=\displaystyle\prod_{j=1}^NL^2(0,l_j)$
	and initial data is $u^0=(u^0_1,...,u^0_N)$. 
	 \item[ii.] The inner product in $\mathbb{L}^2(\mathcal{T})$ will be given by  $$\left(u,z\right)_{\mathbb{L}^2(\mathcal{T})}=\sum_{j=1}^N\int_0^{l_j}u_jz_jdx,\ \ u,z\in \mathbb{L}^2(\mathcal{T}).$$
	Moreover,  $$\mathbb{H}^s(\mathcal{T})=\displaystyle\prod_{j=1}^NH^s(0,l_j), \ \ s \in \mathbb{R}.$$
	 \end{itemize}
	\begin{itemize}
		\item[iii.] Define also the following spaces:
		$$\mathbb{H}_0^k(\mathcal{T})=\displaystyle\prod_{j=1}^{N}H_0^k(0,l_j),\ k\in \mathbb{N}$$
		and
		$$H_r^k(0,l_j)=\left\{v \in H^k(0,l_j),\ \partial_x^iv(l_j)=0,\ 0\leq i\leq k-1\right\},\ k=1,...,N,$$ 
		where $v^{(m)}=\frac{dv}{dx^m}$ and the index $r$ is related to the null right boundary conditions. In addition, 
		$$\mathbb{H}^k_r(\mathcal{T})=\prod_{j=1}^{N}H_r^k(0,l_j)\quad \text{and} \quad \|u\|_{\mathbb{H}^k_r(\mathcal{T})}^2=\sum_{j=1}^{n}\|u_j\|_{H^k(0,l_j)}^2\ k \in \mathbb{N}.$$
		\item[iv.] Consider the following characterization: 
		$$H_r^{-1}(0,l_j)=\left(H_r^{1}(0,l_j)\right)'$$ 
		as the dual space of $H_r(0,l_j)$ with respect to the pivot space $L^2(0,l_j)$ and $\mathbb{H}_r^{-1}$ denotes the cartesian product of $H_r^{-1}(0,l_j)$. 
\item[v.] For $k\in \mathbb{N}$, the derivative $\partial_x^ku$ means the row vector
\begin{align*}
\partial_x^k u:=(\partial_x^ku_1,...,\partial_x^ku_N).
\end{align*}
The derivative $\partial_t^ku$ is understood in the same way.
\item[vi.] Under the above notation, we have
\begin{align*}
	C^k\left([0,T];\mathbb{H}^s(\mathcal{T})\right)=\prod_{j=1}^NC^k\left([0,T];H^s(0,l_j)\right),\ k=0,1,2,... \text{ \ and \ }s \in \mathbb{R}
\end{align*}
as well as
\begin{align*}
	L^p\left(0,T;\mathbb{H}^s(\mathcal{T})\right)=\prod_{j=1}^NL^p\left(0,T;H^s(0,l_j)\right),\ p\geq 1 \text{ \ and \ }s \in \mathbb{R}.
\end{align*}
Hence, for $f \in 	C^k\left([0,T];\mathbb{H}^s(\mathcal{T})\right)$ and $q \in L^p\left(0,T;\mathbb{H}^s(\mathcal{T})\right)$ we can write
\begin{align*}
f=(f_1,...,f_N)\text{ \ and \ }q=(q_1,...,q_N)
\end{align*}
with
\begin{align*}
f_j \in C^k\left([0,T];H^s(0,l_j)\right)\text{ \ and \ }q_j \in L^p\left(0,T;H^s(0,l_j)\right),\ j=1,...N.
\end{align*}
\item[vii.] We will consider the spaces
