$$\mathcal{X}_{s,T}=\left\{v \in \mathbb{B}^{*}_{s,T};\ \partial_x^ku_j\in L_x^\infty(0,l_j;H^\frac{s+1-k}{3}(0,T)),\ k=0,1,2,\ j=1,2,...,N\right\},$$
\begin{align*}
	\mathbb{B}_{s,T}^*:=\mathbb{B}_{s,T}\cap H^\frac{s}{3}(0,T;\mathbb{H}^1(\mathcal{T})).
\end{align*}

theorem.content:
\label{main1}
Let $\Om$ be a bounded Lipschitz domain in $\mathbb{R}^2$ with Lipschitz constant $L < L_0$, where $0<L_0<1$ is a sufficiently small constant. Assume $b\in L^{2,\infty}(\Omega)^2$ and $\mathop{\rm div}\nolimits b=0$.
Then there exists $p_0(\|b\|_{L^{2,\infty}})>2$ such that for any $p_0'<q<p_0$ and $\mathbb{G}\in L^q(\Om)^{2\times 2}$, there exists a  weak solution pair $u\in W^{1,q}_{0,\si}(\Omega)$ and $\pi\in L^q_0(\Omega)$ of \eqref{drifteq} such that
\EQ{\label{main1-eq}
\|u\|_{ W^{1,q}(\Omega)}+\|\pi\|_{L^q(\Omega)}\le C(\Omega,\|b\|_{L^{2,\infty}})\|\mathbb{G}\|_{L^q(\Omega)}.
}
For $p_0'<q<p_0$, the above pair $(u,\pi)$ is the unique weak solution pair  in $W^{1,q}_0\times L^q_0(\Om)$ without assuming \eqref{main1-eq}.

