\hspace{0.5cm}
In this paper, we consider the following three-dimensional Boussinesq equations:
\begin{equation}\label{micropolar}
\left\{
\begin{array}{l}
u_t
\;\!+\,
u \cdot \nabla u
\,+\,
\nabla \;\!p \:\!\,+\, \:\!(-\Delta)^\alpha u
\;=\;
\theta e_3, \quad x\in \mathbb{R}^3, \quad t > 0,\\
\theta_t
\;\!+\,
u \cdot \nabla \theta\,+\, \,(-\Delta)^\beta \theta
\;=\;
0, \quad x\in \mathbb{R}^3, \quad t > 0,\\
\mbox{div}\:u \;=\; 0, \quad x\in \mathbb{R}^3, \quad t > 0,\\
u(x,0) \,=\, u_0(x),
\;\,
\theta(x,0) \,=\, \theta_0(x), \quad x\in \mathbb{R}^3,
\end{array}
\right.
\end{equation}
where $u(x,t) = \left(u_{1}(x,t), u_{2}(x,t), u_{3}(x,t)\right) \in \mathbb{R}^3$ denotes the incompressible velocity field, and 
$\theta(x,t) \in \mathbb{R}$ represents the temperature of the fluid. The parameters $\alpha$ and $\beta$ belong to 
$(\tfrac{1}{2},\infty)$, and we set $e_{3} = (0,0,1)$. The initial velocity field $u_{0}$ in \eqref{micropolar} is assumed to be divergence-free, that is,
$$
\operatorname{div} u_{0} = 0,
$$
and we denote by $(-\Delta)^{\gamma}$ the fractional Laplacian, defined for a suitable function $f$ by
$$
\mathcal{F}[(-\Delta)^{\gamma} f](\xi) = |\xi|^{2\gamma} \widehat{f}(\xi) .
$$

Observe that, in the case $\theta \equiv 0$ and $\alpha = 1$, the system \eqref{micropolar} reduces to the classical incompressible Navier-Stokes equations
\begin{equation}\label{NS}
\left\{
\begin{array}{l}
u_t
\;\!+\,
u \cdot \nabla u
\,+\,
\nabla \;\!p 
\;=\;
\Delta u, \quad x\in \mathbb{R}^3, \quad t > 0,\\

In this work, we are concerned with the time evolution of solutions. More precisely, we aim to establish finite-time blow-up criteria for mild solutions of \eqref{micropolar} in Sobolev-Gevrey type spaces. For $a \ge 0$, $\sigma \ge 1$, and $s \in \mathbb{R}$, the (homogeneous) Sobolev-Gevrey space is defined by
$$
\dot{H}_{a,\sigma}^s=\dot{H}_{a,\sigma}^s(\mathbb{R}^3)
 = \left\{ f \in \mathcal{S}' : \widehat{f} \in L^1_{\operatorname{loc}}\,\, \text{and} \,\, \ 
 \|f\|_{\dot{H}_{a,\sigma}^s}:=\Big[\int_{\mathbb{R}^3} |\xi|^{2s} e^{2a |\xi|^{1/\sigma}} |\widehat{f}(\xi)|^2\, d\xi\Big]^{\frac{1}{2}} < \infty
 \right\},
$$
where $\widehat{f}$ denotes the Fourier transform
$$
\mathcal{F}(f)(\xi)=\widehat{f}(\xi):=\int_{\mathbb{R}^3}e^{-i\xi\cdot x}f(x)\,dx.
$$
Essentially, $\dot{H}_{a,\sigma}^s \equiv L^{2}\!(|\xi|^{s} e^{a|\xi|^{1/\sigma}}\, d\xi)$ and, in particular, $\dot{H}_{0,\sigma}^s \equiv \dot{H}^s$, \textit{i.e.}, the classical (homogeneous) Sobolev space. This class of functions plays a crucial role because, according to Paley--Wiener Theorem (see \cite{HormanderALPDO1}, Chapter~7, for further details), for $\sigma=1$ a function $ f $ belongs to the space $ \dot{H}_{a,1}^s(\mathbb{R}^d) $ if, and only if, it admits a holomorphic extension $ F $ to the strip

$$
S_a = \{ x + i y \in \mathbb{C}^d: x, y \in \mathbb{R}^d,\ |y| < a \},
$$
such that
$$
 \sup_{|y| < a} \| F(x + i y) \|_{\dot{H}^s} < \infty.
$$
In other words, the parameter $ a \geq 0 $ determines the width of the complex strip to which 
functions in $ \dot{H}_{a,1}^s(\mathbb{R}^d) $ can be analytically extended. For $\sigma>1$, the regularity falls into a non-analytic Gevrey regime, meaning that derivatives grow in a controlled but non-analytic manner, which is equivalently reflected by a subexponential decay at high frequencies.

Consequently, the study of 
differential equations in such analyticity-based function classes has attracted significant attention in recent years. See, for instance, \cite{MR3504420, MR4632081, MR4369830, MR2169876, MR1026858, MR2265624} and references therein for more details on this topic.

The first main result of this work establishes the local well-posedness of the Cauchy problem \eqref{micropolar} in Sobolev-Gevrey class. Recall that, we say that $(u,\theta)=(u,\theta)(x,t)$ is a mild solution to the Boussinesq equations (\ref{micropolar}) if this application satisfies the associated integral formulations (\ref{wilber15}) and (\ref{wilber16}), which are established via the fractional heat semigroup.

\begin{equation}\label{micropolar}
\left\{
\begin{array}{l}
u_t
\;\!+\,
u \cdot \nabla u
\,+\,
\nabla \;\!p \:\!\,+\,  \:\!(-\Delta)^\alpha u
\;=\;
\theta e_3, \quad x\in \mathbb{R}^3, \quad t > 0,\\
\theta_t
\;\!+\,
u \cdot \nabla \theta\,+\, \,(-\Delta)^\beta \theta
\;=\;
0, \quad x\in \mathbb{R}^3, \quad t > 0,\\
\mbox{div}\:u  \;=\; 0, \quad x\in \mathbb{R}^3, \quad t > 0,\\
u(x,0) \,=\, u_0(x),
\;\,
\theta(x,0) \,=\, \theta_0(x), \quad x\in \mathbb{R}^3,
\end{array}
\right.
\end{equation}

\begin{align}\label{wilber15}
u(t)= e^{- t(-\Delta)^{\alpha}}u_0 - \int_{0}^te^{- (t-\tau)(-\Delta)^{\alpha}} \mathbb{P}(u\cdot\nabla u)\,d\tau + \int_{0}^te^{- (t-\tau)(-\Delta)^{\alpha}} \mathbb{P}(\theta e_3)\,d\tau,\quad\forall t>0.
\end{align}

\begin{align}\label{wilber16}
\theta(t)= e^{- t(-\Delta)^{\beta}}\theta_0 - \int_{0}^te^{-  (t-\tau)(-\Delta)^{\beta}} [u\cdot \nabla\theta]\,d\tau ,\quad\forall t>0.
\end{align}

The first main result of this work establishes the local well-posedness of the Cauchy problem \eqref{micropolar} in Sobolev-Gevrey class. Recall that, we say that $(u,\theta)=(u,\theta)(x,t)$ is a mild solution to the Boussinesq equations (\ref{micropolar}) if this application satisfies the associated integral formulations (\ref{wilber15}) and (\ref{wilber16}), which are established via the fractional heat semigroup.

Next, we investigate the qualitative behavior of the local solution provided by Theorem \ref{teoremaexistenciaB}, assuming that its maximal lifespan is finite.

First of all, apply Helmholtz's projector $\mathbb{P}$, defined via Fourier transform (see \cite{PN} for more details)
$$
\mathcal{F}[\mathbb{P}f](\xi) := \widehat{f}(\xi) - \frac{\widehat{f}(\xi)\cdot \xi}{|\xi|^2}\, \xi,
$$
the heat semigroup $e^{-(t-\tau)(-\Delta)^{\alpha}}$ to the first equation in (\ref{micropolar}), and integrate the result obtained over $[0,t]$ to obtain
\begin{align}\label{wilber15}
u(t)= e^{- t(-\Delta)^{\alpha}}u_0 - \int_{0}^te^{- (t-\tau)(-\Delta)^{\alpha}} \mathbb{P}(u\cdot\nabla u)\,d\tau + \int_{0}^te^{- (t-\tau)(-\Delta)^{\alpha}} \mathbb{P}(\theta e_3)\,d\tau,\quad\forall t>0.
\end{align}
Similarly, by using the heat semigroup $e^{- (t-\tau)(-\Delta)^{\beta}}$ in the second equation of (\ref{micropolar}), and integrating over $[0,t]$, we deduce
\begin{align}\label{wilber16}
\theta(t)= e^{- t(-\Delta)^{\beta}}\theta_0 - \int_{0}^te^{- (t-\tau)(-\Delta)^{\beta}} [u\cdot \nabla\theta]\,d\tau ,\quad\forall t>0.
\end{align}
Hence, we are able to write the following equality:
\begin{align}\label{estimativaprojecao3}
(u,\theta)(t)&= (e^{- t(-\Delta)^{\alpha}}u_0,e^{- t (-\Delta)^{\beta}}\theta_0) + B((u,\theta),(u,\theta))(t)+L(u,\theta)(t),\quad\forall t>0.
\end{align}
where
\begin{align}\label{bilinearB}
B((w,v),(\gamma,\phi))(t)=(B_1((w,v),(\gamma,\phi)),B_2((w,v),(\gamma,\phi)))(t),\quad\forall t>0,
\end{align}
and also
\begin{align}\label{linearL}
L(w,v)(t)=(L_1(w,v)(t),L_2(w,v)(t)),\quad\forall t>0,
\end{align}
with
\begin{align}\label{bilinearB1}
B_1((w,v),(\gamma,\phi))(t)= - \int_{0}^te^{- (t-\tau)(-\Delta)^{\alpha}} \mathbb{P}(w\cdot\nabla \gamma)\,d\tau,
\end{align}
\begin{align}\label{bilinearB2}
B_2((w,v),(\gamma,\phi))(t)= - \int_{0}^te^{- (t-\tau)(-\Delta)^{\beta}} [w\cdot \nabla \phi]\,d\tau,
\end{align}
\begin{align}\label{linearL1eL2}
L_1(w,v)(t)= \int_{0}^te^{- (t-\tau)(-\Delta)^{\alpha}} \mathbb{P}[ve_3]\,d\tau \quad \hbox{ and }\quad L_2(w,v)(t)= 0,
\end{align}
for all $w,v,\gamma,\phi\in C_T(\dot{H}_{a,\sigma}^s)$ ($T>0$ will be revealed below). Denote $X= [C_T (\dot{H}_{a,\sigma}^{s})]^3$ $\times C_T (\dot{H}_{a,\sigma}^{s}) (\equiv C_T (\dot{H}_{a,\sigma}^{s})$ throughout this work)$\footnote{Here, $\|(f,g)\|_{X}:=[\|f\|^2_{L^\infty_T(\dot{H}_{a,\sigma}^s)}+\|g\|^2_{L^\infty_T(\dot{H}_{a,\sigma}^s)}]^{\frac{1}{2}}$}$ and notice that $B$ and $L$ are bilinear and linear operators on $X\times X$ and $X$, respectively.

At last, notice that 
\begin{align}\label{mudanca1}
\displaystyle\|e^{- t(-\Delta)^{\alpha}} u_0\|^2_{\dot{H}_{a,\sigma}^s}&=\int_{\mathbb{R}^3} e^{-2 t|\xi|^{2\alpha}}|\xi|^{2s} e^{2a|\xi|^{\frac{1}{\sigma}}} |\widehat{u}_0(\xi)|^2\,d\xi\leq \|u_0\|_{\dot{H}_{a,\sigma}^{s}}^2,\quad\forall t\in [0,T],
\end{align}
and also that
\begin{align}\label{mudanca2}
\displaystyle\|e^{- t(-\Delta)^{\beta}} \theta_0\|_{\dot{H}_{a,\sigma}^s}\leq \|\theta_0\|_{\dot{H}_{a,\sigma}^{s}},\quad\forall t\in [0,T].
\end{align}
From (\ref{mudanca1}) and (\ref{mudanca2}), it follows that
\begin{align}\label{dadoincial}
\|(e^{-t(-\Delta)^{\alpha}}u_0,e^{-t (-\Delta)^{\beta}}\theta_0)\|_{X}\leq\|(u_0,\theta_0)\|_{\dot{H}_{a,\sigma}^{s}}.
\end{align}
Thus, we are able to determine $T>0$ as follows: 
$$T< \min\Big\{\Big[\sqrt{8C_{a,\sigma,s,\alpha,\beta}\|(u_0,\theta_0)\|_{\dot{H}_{a,\sigma}^{s}}}+1\Big]^{-\frac{4\alpha}{2\alpha-1}},\Big[\sqrt{8C_{a,\sigma,s,\alpha,\beta}\|(u_0,\theta_0)\|_{\dot{H}_{a,\sigma}^{s}}}+1\Big]^{-\frac{4\beta}{2\beta-1}}\Big\},$$
where $C_{a,\sigma,s,\alpha,\beta}$ is established in (\ref{w5}). Therefore, by Lemma \ref{pontofixo}, there exists a unique solution $(u,\theta)\in X$ for the equation (\ref{estimativaprojecao3}) (it is enough to take a look at (\ref{lwfinal}), (\ref{w5}) and (\ref{dadoincial})) that satisfies the following inequality:
$$\|(u,\theta)\|_{X}\leq \frac{1-T}{2C_{a,\sigma,s,\alpha,\beta}[T^{1-\frac{1}{2\alpha}}+T^{1-\frac{1}{2\beta}}]}.$$

Now, let us assume that $\displaystyle \limsup_{t\nearrow T^*} \|(u,\theta)(t)\|_{\dot{H}_{a,\sigma}^{s}} < \infty$. Thus, apply Theorem \ref{teoremaexistenciaB} to obtain a positive constant $C_{a,\sigma,s}$ such that
\begin{align}\label{limitacao}
\displaystyle \|(u,\theta)(t)\|_{\dot{H}_{a,\sigma}^{s}} \leq C_{a,\sigma,s},\quad\forall\,t\in[0,T^*).
\end{align}
Thereby, by integrating over $[0,t]$ the inequality (\ref{esqueci}) and using (\ref{limitacao}), we can write the following inequality:
\begin{align*}
&\nonumber\|(u,\theta)(t)\|_{\dot{H}_{a,\sigma}^s}^2+\int_0^t\|u(\tau)\|_{\dot{H}_{a,\sigma}^{s+\alpha}}^2+\int_0^t\|\theta(\tau)\|_{\dot{H}_{a,\sigma}^{s+\beta}}^2\,d\tau \leq \|(u_0,\theta_0)\|_{\dot{H}_{a,\sigma}^s}^2+C_{a,\sigma,s,\alpha,\beta}T^*,
\end{align*}
for all $t\in[0,T^*).$ As a result, particularly, one has
\begin{align}\label{e4}
\int_0^t\|u(\tau)\|_{\dot{H}_{a,\sigma}^{s+\alpha}}^2d\tau+\int_0^t\|\theta(\tau)\|_{\dot{H}_{a,\sigma}^{s+\beta}}^2\,d\tau \leq C_{a,\sigma,s,\alpha,\beta,u_0,\theta_0,T^*},\quad\forall\,t\in[0,T^*).
\end{align}

On the other hand, take $L^2$-inner product of the Boussinesq equations (\ref{micropolar}), with $u$ and $\theta$, respectively, and integrate the results obtained over $[0,t]$ in order to be capable of writing the following inequality:
\begin{align}\label{wilber32}
\frac{1}{2}\frac{d}{dt}\|(u,\theta)(t)\|_{L^2}^2+\|(-\Delta)^{\frac{\alpha}{2}}u(t)\|_{L^2}^2+\|(-\Delta)^{\frac{\beta}{2}}\theta(t)\|_{L^2}^2 &\leq \|(u,\theta)(t)\|_{L^2}^{2},\quad\forall t\in [0,T^*).
\end{align}
By Gronwall's Lemma, we have 
\begin{align}\label{normal2}
 \|(u,\theta)(t)\|_{L^2}\leq e^{T^*}\|(u_0,\theta_0)\|_{L^2},\quad\forall t\in [0,T^*).
\end{align}
Thereby, by using (\ref{wilber12}) and (\ref{normal2}), one infers
\begin{align*}
\frac{C_{s,\alpha,u_0,\theta_0,T^*}}{[e^{C_\alpha(T^*-t)}-1]^{\frac{2s(2\alpha-1)}{3\alpha}}}\left(\frac{C'_{\sigma,s,\alpha,u_0,\theta_0,T^*}}{[e^{C_\alpha(T^*-t)}-1]^{\frac{2\alpha-1}{3\alpha\sigma}}}\right)^k \leq \|(u,\theta)(t)\|_{\dot{H}^{s+\frac{k}{2\sigma}}}^2,\quad\forall t\in [0,T^*).
\end{align*}
As a consequence, we have the inequality below:
\begin{align}\label{wnovo1}
\frac{C_{s,\alpha,u_0,\theta_0,T^*}}{[e^{C_\alpha(T^*-t)}-1]^{\frac{2s(2\alpha-1)}{3\alpha}}}\frac{\left(\frac{2aC'_{\sigma,s,\alpha,u_0,\theta_0,T^*}}{[e^{C_\alpha(T^*-t)}-1]^{\frac{2\alpha-1}{3\alpha\sigma}}}\right)^k }{k!} &\leq \int_{\mathbb{R}^3} \frac{(2a|\xi|^{\frac{1}{\sigma}})^k}{k!}|\xi|^{2s}|(\widehat{u},\widehat{\theta})(t)|^{2}\,d\xi,\quad\forall t\in [0,T^*).
\end{align}
Hence, by using Monotone Convergence Theorem in the inequality (\ref{wnovo1}), we deduce
\begin{align}\label{wilber14}
\nonumber\frac{C_{s,\alpha,u_0,\theta_0,T^*}}{[e^{C_\alpha(T^*-t)}-1]^{\frac{2s(2\alpha-1)}{3\alpha}}}\sum_{k=2\sigma_0+1}^{\infty}\frac{\left(\frac{2aC'_{\sigma,s,\alpha,u_0,\theta_0,T^*}}{[e^{C_\alpha(T^*-t)}-1]^{\frac{2\alpha-1}{3\alpha\sigma}}}\right)^k }{k!} &\leq \int_{\mathbb{R}^3} \sum_{k=2\sigma_0+1}^{\infty}\frac{(2a|\xi|^{\frac{1}{\sigma}})^k}{k!}|\xi|^{2s}|(\widehat{u},\widehat{\theta})(t)|^{2}\,d\xi\\
&\leq \|(u,\theta)(t)\|_{\dot{H}_{a,\sigma}^s}^2,
\end{align}
for all $t\in [0,T^*)$, where $2\sigma_0$ is the integer part of $2\sigma\mu$.

