The proof of this result relies on a fixed-point argument. However, for both the classical and the fractional Boussinesq equations, a major difficulty arises in handling the coupling terms $\theta e_{3}$ and $(u \cdot \nabla)\theta$, which demand delicate estimates within the chosen functional framework.

Next, we investigate the qualitative behavior of the local solution provided by Theorem \ref{teoremaexistenciaB}, assuming that its maximal lifespan is finite.

\begin{theorem}\label{teoremaB}
Assume that $a>0$, $\sigma>1$, $\alpha\geq 1, \beta \geq 1, 0\leq s<\frac{3}{2}$ and $n\in \mathbb{N}$. Let $(u_0,\theta_0)\in \dot{H}_{a,\sigma}^s$ such that $\hbox{\emph{div}}\,u_0=0$. Consider that $(u,\theta)\in C([0,T^*);\dot{H}_{a,\sigma}^s)$ is the  solution
for the Boussinesq equations \emph{(\ref{micropolar})} in the maximal time interval $0\leq t < T^*$  given in Theorem \emph{\ref{teoremaexistenciaB}}. If $T^*<\infty$, then the following statements hold:
      \begin{enumerate}
  \item[\textbf{\emph{i)}}]  $\displaystyle \limsup_{t\nearrow T^*} \|(u,\theta)(t)\|_{\dot{H}_{\frac{a}{(\sqrt{\sigma})^{(n-1)}},\sigma}^s}=+\infty$;
  \item[\textbf{\emph{ii)}}] $\displaystyle\int_{t}^{T^*} [\|e^{\frac{a}{\sigma(\sqrt{\sigma})^{(n-1)}}|\cdot|^{\frac{1}{\sigma}}}(\widehat{u},\widehat{\theta})(\tau)\|_{L^1}
^{\frac{2\alpha}{2\alpha-1}}+\|e^{\frac{a}{\sigma(\sqrt{\sigma})^{(n-1)}}|\cdot|^{\frac{1}{\sigma}}}(\widehat{u},\widehat{\theta})(\tau)\|_{L^1}^{\frac{2\beta}{2\beta-1}}]\,d\tau=\infty$;
 \item[\textbf{\emph{iii)}}]  $\displaystyle \|e^{\frac{a}{\sigma(\sqrt{\sigma})^{(n-1)}}|\cdot|^{\frac{1}{\sigma}}}(\widehat{u},\widehat{\theta})(t)\|_{L^1}^{\frac{2\alpha}{2\alpha-1}}
    +\|e^{\frac{a}{\sigma(\sqrt{\sigma})^{(n-1)}}|\cdot|^{\frac{1}{\sigma}}}(\widehat{u},\widehat{\theta})(t)\|_{L^1}^{\frac{2\beta}{2\beta-1}}\geq  (e^{C(T^*-t)}-1)^{-1};$
  \item [\textbf{\emph{iv)}}] $\displaystyle \|(u,\theta)(t)\|_{\dot{H}_{\frac{a}{(\sqrt{\sigma})^n},\sigma}^s}^{\frac{2\alpha}{2\alpha-1}}+
\|(u,\theta)(t)\|_{\dot{H}_{\frac{a}{(\sqrt{\sigma})^n},\sigma}^s}^{\frac{2\beta}{2\beta-1}}\gtrsim(e^{C(T^{*}-t)}-1)^{-1}.$
  \end{enumerate}
for all $t\in [0,T^{*})$ and $C>0$ is a positive constant.
\end{theorem}

 As a corollary, we obtain that the local solutions provided by Theorem \ref{teoremaexistenciaB} exhibit exponential growth, which in turn ensures finite-time blow-up with an explicit exponential rate.

\begin{corollary}\label{corolario}
Assume that $a>0$, $\sigma>1$, $\alpha=\beta\geq 1 \hbox{  and  } 0\leq s<\frac{3}{2}$. Let $(u_0,\theta_0)\in \dot{H}_{a,\sigma}^s\cap L^2$ such that $\hbox{\emph{div}}\,u_0=0$. Consider that $(u,\theta)\in C([0,T^*);\dot{H}_{a,\sigma}^s)$ is the  solution
for the Boussinesq equations \emph{(\ref{micropolar})} in the maximal time interval $0\leq t < T^*$  given in Theorem \emph{\ref{teoremaexistenciaB}}. If $T^*<\infty$, then the following statement holds:
   $$
   \displaystyle
\|(u,\theta)(t)\|_{\dot{H}_{a,\sigma}^s} \gtrsim  {(e^{C_1(T^*-t)}-1)^{\varrho_1}}
\exp\{C_2(e^{C_1(T^*-t)}-1)^{\varrho_2}\},
$$
for all \(t \in [0, T^{*})\), where $\varrho_1 := \frac{(1 - 2\alpha)\,[\,2(s\sigma + \sigma_{0}) + 1\,]}{6\alpha\sigma}<0$, $\varrho_2:=\frac{1-2\alpha}{3\alpha\sigma}<0$ and \(2\sigma_{0}\) denotes the integer part of \(2\sigma\mu\) \emph{(}with \(\mu > \tfrac{3}{2}\)\emph{)}.  
Here, $C_1=C_1(\alpha)$ and $C_2=C_2(a,\alpha,\sigma,s,u_0,\theta_0,T^*)$ are constants. In particular
$$
\lim_{t \nearrow T^*}\|(u,\theta)(t)\|_{\dot{H}_{a,\sigma}^s} = +\infty,
$$
exponentially.
\end{corollary}

