\begin{theorem}\label{theorem:main}
	Let $\lambda\in DP_n$ and $(\rho_\lambda,V_\lambda)$ be the corresponding irreducible spin representation of $\tilde S_n$.
	Let $g\in \tilde S_n$ be an element with cycle type $\mu=(\mu_1,\mu_2,\dotsc,\mu_k)$ and let $k=\lcm(\mu)$.
	Then the minimal polynomial $p_\lambda(g)$ of $\rho_\lambda(g)$ has $k$ distinct roots except in the following cases:

	\noindent For $n\leq 8$, $(\lambda,\mu)$ is one of the pairs listed in Table~\ref{table:exceptional_cases_1_8}.

	For $n>8$, the following four exceptions occur:
\begin{itemize}
		\item $\lambda=(n)$ and $\mu$ contains $3$ with the remaining parts are not divisible by $3$ and $5$ is not the unique part which is divisible by $5$. In this case, the minimal polynomial is given by $\frac{x^{k}\pm 1}{x^{k/3}\pm 1}$.
		\item $\lambda=(n)$ and $\mu$ contains $5$ with the remaining parts are not divisible by $5$ and $3$ is not the unique part which is divisible by $3$. In this case, the minimal polynomial is given by $\frac{x^{k}\pm 1}{x^{k/5}\pm 1}$
		\item $\lambda=(n)$ and $\mu$ contains $3$ and $5$ and all other parts of $\mu$ are not divisible by $3$ or $5$. In this case, the minimal polynomial is given by $\frac{(x^{k}\pm1)(x^{k/15}\pm 1)}{(x^{k/3}\pm1)(x^{k/5}\pm 1)}$.
		\item $\lambda=(n-1,1)$ and $\mu$ contains $3$ and $5$, and all other parts of $\mu$ are not divisible by $3$ or $5$. In this case, the minimal polynomial is given by $\frac{(x^{k}\pm1)}{(x^{k/15}\pm1)}$.
	\end{itemize}
\end{theorem}

