\section{Expansion of positivity}\label{Holder}

Throughout this section, we assume that the modulating coefficient $b(\cdot,\cdot)$ satisfies \eqref{a.holder} with \eqref{assumption.hol}. 
We start this section with the following logarithmic type estimate, whose proof is analogous to those of \cite[Corollary~3.2]{DKP16} and \cite[Corollary~5.2]{BOS}.

\begin{lemma}\label{log.lemma}
Let $u \in \mathcal{A}(\Omega) \cap \mathcal{T}(\mathbb{R}^{n})$ be a weak supersolution to \eqref{main.eq} under assumptions \eqref{kernel.growth}--\eqref{assumption.hol}, which is nonnegative in a ball $B_{R} \equiv B_{R}(x_{0})$ with $R \le R_{0}$. For any $d,\zeta > 0$ and $\xi>1$, define
\begin{equation*}
v \coloneqq \min\{(\log(\zeta+d)-\log(u+d))_{+}, \log\xi\}.
\end{equation*} 
Then for any $r \in (0, R/2]$ and $d>0$, we have
\begin{equation}\label{log.est}
\mean{B_{r}}|v-(v)_{B_{r}}|\,dx
\leq c + cd^{1-p}\frac{1}{G_{B_{2r}}(1)}T(u_{-};R,2r)
\end{equation}
for a constant $c \equiv c(\data)>0$.
\end{lemma}
\begin{proof}
In the case $b^{+}_{B_{R}} \le \nu/4$, since $\nu/4 \le a(x,y) \le L$, the estimate is proved in \cite[Lemma~5.1]{BOS} with $q=p$. Note that, in the setting of the present paper, \cite[(5.10)]{BOS} can be replaced by
\begin{equation*}
\begin{aligned}
& \int_{B_{3r/2}}\int_{\mathbb{R}^{n}\setminus B_{R}}\frac{1}{g_{B_{2r}}(u(x)+d)}\left(a(x,y)\frac{(u_{-}(y))^{p-1}}{|x-y|^{n+sp}}+b(x,y)\frac{(u_{-}(y))^{p-1}}{|x-y|^{n+tp}}\right)\,dy\,dx \\
& \le \frac{cr^{n}}{g_{B_{2r}}(d)}\sup_{x\in B_{2r}}\int_{\mathbb{R}^{n}\setminus B_{R}}\left(a(x,y)\frac{(u_{-}(y))^{p-1}}{|y-x_{0}|^{n+sp}}+b(x,y)\frac{(u_{-}(y))^{p-1}}{|y-x_{0}|^{n+tp}}\right)\,dy \\
& = \frac{cr^{n}d^{1-p}}{G_{B_{2r}}(1)}T(u_{-};R,2r).
\end{aligned}

