\frac{\nu}{|x-y|^{n+tp}} \leq K_{tp}(x,y) \leq \frac{L}{|x-y|^{n+tp}}
\end{equation}
--\begin{equation}\label{assumption.hol}
\quad (t-s)p \le \alpha.
\end{equation}
 Then there exists an exponent $\gamma \equiv \gamma(n,s,t,p,\nu,L,\alpha,[b]_{\alpha}) \in (0,1)$ such that $u \in C^{0,\gamma}_{\loc}(\Omega)$. Moreover, for any ball $B_{r} \Subset \Omega$ with $r\le R_{0}$, where $R_{0}$ is given in \eqref{R0.choice}, we have
\begin{equation}\label{est:hol}
[u]_{C^{0,\gamma}(B_{r/2})} \le cr^{-\gamma}\left[\left(\mean{B_{r}}|u|^{p}\,dx\right)^{1/p} + g_{B_{r}}^{-1}(T(u;r/2,r))\right]
