\section{Preliminaries}
 \subsection{Terminology and Notation}
 In this subsection, we introduce some defnitions and notation in complex geometry. For the details, refer to [Dem2, Chapter V], [GH, Chapter 0] for example. In the present paper, we use the following notation for a holomorphic line bundle $L$ on a complex manifold $X$, submanifold $Y\subset X$, and an open subset $U\subset X$:
\begin{itemize}
 \item $\mathbb{C}$ : the field of complex numbers,
 \item $\mathbb{Z}$ : the field of real integers,
 \item ${\rm deg}\,L$ : the degree of the line bundle $L$,
 \item $\mathrm{dim}\,X$ : the complex dimension of $X$,
 \item $K_X$: the canonical line bundle of $X$,
 \item $N_{Y/X}$: the normal bundle of $Y$ in $X$, 
 \item $L^{m}$: For an integer $m \in \mathbb{Z}$, we denote by $L^{\otimes m}$ the $m$-th tensor power of $L$. Note that $L^{-1}$ denotes the dual line bundle of $L$.
 \item $H^i(X, \mathcal{F})$ : the $i$-th sheaf cohomology group of $\mathcal{F}$ on $X$, where $\mathcal{F}$ is one of following:
 \item $\mathcal{O}_X$ defined by $\mathcal{O}_X(U)$:=\{all holomorphic functions on $U$\},
 \item $\mathcal{O}^*_X$ defined by $\mathcal{O}^*_X(U)$:=\{all nowhere vanishing holomorphic functions on $U$\},
 \item $\mathcal{O}_X(L)$ defined by $\mathcal{O}_X(L)(U)$ :=\{all holomorphic sections of $L$ on $U$\}.
 \end{itemize}

\begin{definition}[{\it Nef}]
 Let $X$ be a projective variety and let $L$ be a holomorphic line bundle on $X$. We say that $L$ is {\it nef} if for any algebraic curve $C \subset X$, $(L.C)=\int_{C} c_{1}(L) \ge 0$.
 \end{definition}

\begin{theorem}[{\cite[Proposition~1, p.~584]{U}}]
 Let $X$ be a compact Kähler manifold, and let $L$ be a holomorphic line bundle over $X$. 
 If $L$ is topologically trivial, then it admits a unitary flat structure. That is, there exists a Hermitian metric $h$ on $L$ such that $\Theta_{L,h} = 0$ at every point of $X$.
\end{theorem}
\end{center}
 \subsection{Grauert's example}
In this subsection, we introduce the construction in Grauert’s example following \cite[p. 365--366]{G}, which will be used in later calculations, together with some related results.
 Let $R$ be a compact Riemann surface of genus $g \geq 2$, and let $F$ be a holomorphic line bundle over $R$ with ${\rm deg}\,F=1$. Assume that $H^1(R, \mathcal{O}_R(F)) \neq 0$.
 \begin{lemma}
 There exists a line bundle $F$ of degree $1$ such that $H^1(R, \mathcal{O}_R(F)) \ne 0$.
 \end{lemma}

