This paper is organized as follows. In \cref{sec:pre}, we recall necessary concepts and known results. In \cref{sec:pf}, we provide a proof of \cref{thm:e+.trinacria1}. We write $X_{T_{(b+2)b2}}=Y_2e_1^2+Y_1e_1+Y_0$, where each symmetric function $Y_i$ is free of a factor $e_1$, and prove that each symmetric function $Y_i$ is $e$-positive. For $Y_2$ and $Y_1$, we apply charging arguments; for $Y_0$, we employ a progressive repair method, in which each round addresses the remaining negative contributions.

\section{Preliminaries}\label{sec:pre}
This section provides necessary background on chromatic symmetric functions. We adopt the terminology system from \citet{GKLLRT95} and \citet{Sta11B}. Let $n$ be a positive integer. Denote $[n]=\{1,2,\dots,n\}$. A \emph{composition} of $n$ is a sequence of positive integers whose sum is~$n$, denoted by $I=i_1 \dotsm i_z\vDash n$, with \emph{size} $\abs{I}=n$, \emph{length} $\ell(I)=z$, and \emph{parts} $i_1,\dots,i_z$. When all parts $i_k$ are equal to a common value $i$, we write $I=i^z$. When a capital letter like $I$ or~$J$ stands for a composition, its small letter counterpart with integer subscripts refers to the parts. A \emph{partition}\index{partition} of~$n$ is a multiset of positive integers $\lambda_i$ whose sum is~$n$, denoted $\lambda=\lambda_1\lambda_2\dotsm\vdash n$, where $\lambda_1\ge \lambda_2\ge\dotsm\ge 1$.

\begin{lemma}\label{lem:e+:trinacria1.Y2}
The symmetric function $Y_2$ defined by \cref{def:Y2} has the positive $e_I$-expansion
\[
Y_2=\sum_{K\in\mathcal A\cup \mathcal B} w_{1K}e_K
+\sum_{K\in\mathcal C}\brk1{1+\chi(k_1=2)} w_{1K}e_K
+\sum_{K\in\mathcal D}\brk1{2+\chi(k_1=2)} w_{1K}e_K, 
\]
where 
\begin{align*}
\mathcal A&=
\{I\!J\in\mathcal W_{2b+5}\colon\abs{I}=b+3,\ i_1\ge 4\},\\
\mathcal B&=
\{I\!J\in\mathcal W_{2b+5}\colon\abs{I}=b+4,\ i_1=2,\ i_{-1}\ge 3\},\\
\mathcal C&=
\{I\!J\in\mathcal W_{2b+5}\colon\abs{I}=b+5,\ i_{-1}\ge 4\}, 
\end{align*}
and $\mathcal D$ is the set of compositions in $\mathcal W_{2b+5}$ with no prefix of size $b+\delta$ for any $\delta\in\{2, 3, 4, 5\}$.
\end{lemma}
\begin{proof}
Let $\mathcal W=\mathcal W_{2b+5}$.
For $K\in\mathcal W$, let $L_K$ be the set of numbers $l\in[3]$ such that $K$ has a prefix of size $b+6-l$. By \cref{def:Y2}, 
\begin{equation}\label{pf:Y2}
Y_2=\sum_{K\in\mathcal W}c_K w_{1K}e_K,
\end{equation}
where
\begin{equation}\label{pf:f.Y2}
c_K=2+\chi(k_1=2)-\sum_{l\in L_K}l.
\end{equation}
We can decompose~$\mathcal W$ into $11$ pairwise disjoint sets:
\[
\mathcal W
=\mathcal A_2
\cup
(\mathcal A_{30}\cup\mathcal A_{31}\cup\mathcal A_{32}\cup\mathcal A)
\cup
(\mathcal A_{40}\cup \mathcal A_{41}\cup\mathcal B)
\cup
(\mathcal A_5\cup\mathcal C)
\cup
\mathcal D,
\]
where
\begin{align*}
\mathcal A_2
&=\{I\!J\in\mathcal W\colon\abs{I}=b+2,\ j_1\ge 4\},\\
\mathcal A_{30}
&=\{I\!J\in\mathcal W\colon\abs{I}=b+3,\ i_1=2,\ j_1\ge 3\},\\
\mathcal A_{31}
&=\{I\!J\in\mathcal W\colon\abs{I}=b+3,\ i_1=2,\ j_1=2\},\\
\mathcal A_{32}
&=\{I\!J\in\mathcal W\colon\abs{I}=b+3,\ i_1=3\},\\
\mathcal A_{40}
&=\{I\!J\in\mathcal W\colon\abs{I}=b+4,\ i_1\ge 3\},\\
\mathcal A_{41}
&=\{I\!J\in\mathcal W\colon\abs{I}=b+4,\ i_1=2,\ i_{-1}=2\},\quad\text{and}\\
\mathcal A_5
&=\{I\!J\in\mathcal W\colon\abs{I}=b+5,\ i_{-1}=3\}.
\end{align*}
Consider the map $\varphi\colon\mathcal W(b+3)\to\mathcal W(b+2)$
defined by $\varphi(I\!J)=J\!I$, where $\abs{I}=b+3$. It is clear that~$\varphi$ is a bijection. Moreover, 
\[
\varphi(\mathcal A_{31})=\mathcal A_{41},
\quad
\varphi(\mathcal A_{32})=\mathcal A_5,
\quad\text{and}\quad 
\varphi(\mathcal A)=\mathcal A_2.
\]
Let $H=\varphi(K)$. Then $w_{1H}e_H=w_{1K}e_K$ as symmetric functions. By \cref{pf:f.Y2}, 
\[
c_K+c_H=\begin{dcases*}
0,& if $K\in\mathcal A_{31}\cup \mathcal A_{32}$,\\
1,& if $K\in\mathcal A$,
\end{dcases*}
\quad\text{and}\quad
c_K=\begin{dcases*}
0,& if $K\in\mathcal A_{30}\cup \mathcal A_{40}$,\\
1,& if $K\in\mathcal B$,\\
1+\chi(k_1=2),& if $K\in\mathcal C$,\\
2+\chi(k_1=2),& if $K\in\mathcal D$.
\end{dcases*}
\]
Substituting them into \cref{pf:Y2}, we obtain the desired formula.
\end{proof}

Now we can set up the $e$-positivity of $Y_1$.
\begin{lemma}\label{lem:e+:trinacria1.Y1}
The symmetric function $Y_1$ in \cref{prop:X.3sun:b+2.b.2} is $e$-positive.
\end{lemma}
\begin{proof}
\Cref{lem3,lem4,lem5,lem6} completes the first two steps of our strategy at the beginning of \cref{sec:Y1}. For $3\le k\le 6$, denote by $\mathcal B_k$ (resp., $\mathcal C_k$) the union $\bigcup\mathcal B$ (resp., $\bigcup\mathcal C$) for $\mathcal F_k$. By \cref{lem3,lem4,lem5,lem6},
\begin{align*}
\mathcal B_3
&=\{I\!J\in\mathcal W_{2b+4}\colon\abs{J}=b+3,\ j_1\ge 4\},
&
\mathcal C_3
&=\emptyset,
\\
\mathcal B_4
&=\{I\!J\in\mathcal W_{2b+4}\colon\abs{J}=b+2,\ j_1\ge 3\},
&
\mathcal C_4
&=\{I\!J\in\mathcal W_{2b+3}\colon\abs{J}=b+2,\ j_1\ge 3,\ i_1\ge 3\},
\\
\mathcal B_5
&=\{I\!J\in\mathcal W_{2b+4}\colon\abs{J}=b+1\},
&
\mathcal C_5
&=\{I\!J\in\mathcal W_{2b+3}\colon\abs{J}=b+1,\ i_1\ge 3,\ i_{-1}\ge 3\},
\\
\mathcal B_6
&=\{I\!J\in\mathcal W_{2b+4}\colon\abs{J}=b\},
&
\mathcal C_6
&=\{I\!J\in\mathcal W_{2b+3}\colon\abs{J}=b\}.
\end{align*}
It is clear that these sets $\mathcal B_k$ and $\mathcal C_k$ are pairwise disjoint. This completes the proof.
\end{proof}

Now we are in a position to give a proof for the $e$-positivity of $Y_0$.
\begin{lemma}\label{lem:e+:trinacria1.Y0}
The symmetric function $Y_0$ is $e$-positive.
\end{lemma}
\begin{proof}
For the decomposition in \cref{prop:f<0.Y0}, we further decompose $\mathcal B=\mathcal B_1\sqcup \mathcal B_2$, where
\[
\mathcal B_1=\{K\in\mathcal B\colon j_2\ge 3\}
\quad\text{and}\quad
\mathcal B_2=\{K\in\mathcal B\colon j_2=2\};
\]
decompose $\mathcal C=\mathcal C_1\sqcup\mathcal C_2\sqcup\mathcal C_3$, where
\[
\mathcal C_1
=\{K\in\mathcal C\colon j_1\not\in\{2, 4\}\}, 
\quad
\mathcal C_2
=\{K\in\mathcal C\colon j_1=2\}, 
\quad\text{and}\quad
\mathcal C_3
=\{K\in\mathcal C\colon j_1=4\};
\]
decompose $\mathcal D=\mathcal D_1\sqcup\dots\sqcup\mathcal D_4$, where
\[
\mathcal D_1
=\{K\in\mathcal D\colon j_2=2\}, 
\quad
\mathcal D_2
=\{K\in\mathcal D\colon j_2=3\}, 
\quad
\mathcal D_3
=\{K\in\mathcal D\colon j_2=4,\ i_2\ge 4\}, 
\]
and 
$\mathcal D_4
=\mathcal D\backslash \mathcal D_1\backslash \mathcal D_2\backslash \mathcal D_3$; and decompose 
$\mathcal E=\mathcal E_1\sqcup\dots\sqcup\mathcal E_5$, where
\begin{align*}
\mathcal E_1
&=\{K\in\mathcal E\colon (l_K, i_1, j_1)=(2, 4, 3),\ i_2\ge 3\}, 
\\
\mathcal E_2
&=\{K\in\mathcal E\colon (l_K, i_1, i_2)=(2, 4, 2),\ j_1\ge 4,\ k_3=2\}, 
\\
\mathcal E_3
&=\{K\in\mathcal E\colon (l_K, i_1, i_2)=(2, 4, 2),\ j_1\ge 4,\ k_3\ge 3\},\\
\mathcal E_4
&=\{K\in\mathcal E\colon (l_K, i_1, i_2)=(2, 4, 3),\ j_1\in\{4, 5\}\}, 
\end{align*}
and $\mathcal E_5
=\mathcal E\backslash \mathcal E_1\backslash \dotsm\backslash \mathcal E_4$.
Let 
\[
\mathcal F_1=\mathcal A\cup\mathcal B_1\cup\mathcal C_1\cup\mathcal D_1\cup\mathcal E_5
\quad\text{and}\quad
\mathcal F_2=\mathcal D_4\cup\mathcal E_3\cup\mathcal E_4.
\]
We define the aforementioned involution $\xi$ on $\mathcal K^-$ as follows:
\begin{itemize}
\item
define $\xi(K)=K$ to be the identity map for $K\in\mathcal F_1\cup\mathcal F_2$, 
\item
define $\xi\colon\mathcal C_2\to\mathcal C_2$ by $\xi(3P2Q)=3Q2P$, 
where $(\abs{P}, \abs{Q})=(b+1, \,b+1)$, 
\item
define $\xi\colon\mathcal C_3\to\mathcal E_1$ by $\xi(3P4Q)=4P3Q$, 
where $(\abs{P}, \abs{Q})=(b+1, \,b-1)$ and $p_1\ge 3$, 
\item
define $\xi\colon\mathcal D_2\to\mathcal B_2$ by $\xi(2P23Q)=3P22Q$, 
where $(\abs{P}, \abs{Q})=(b+2, \,b-2)$, 
\item
define $\xi\colon\mathcal D_3\to\mathcal E_2$ by $\xi(2P24Q)=422QP$, 
where $(\abs{P}, \abs{Q})=(b+2, \,b-3)$ and $p_1\ge 4$.
\end{itemize}

