\end{theorem}

\begin{abstract} 
We show that the sheaf of $\A^1$-connected components of a quasi-split group over a perfect field is a strictly $\A^1$-invariant sheaf with (Voevodsky) transfers. As a consequence, we show that the norm principle holds for any quasi-split group over a perfect field.
\end{abstract}

In view of this connection, a natural question is whether the sheaf of $\A^1$-connected components of a reductive algebraic groups admits appropriate transfers and whether the norm principle can be deduced from this. The aim of this paper is to answer this question in the affirmative for quasi-split groups over perfect fields. Standard arguments (see \cite{Balwe-Sawant-reductive}, \cite{Balwe-Hogadi-Sawant-JTop} for example) reduce the study of $\A^1$-connected components of a reductive algebraic group to that of the simply connected cover of its derived subgroup. The sheaf of $\A^1$-connected components of a split, semisimple, simply connected group is trivial (see \cite[Theorem 5.2]{Balwe-Sawant-reductive}). As a result, quasi-split groups give the first class of algebraic groups whose $\A^1$-connected components are a priori nontrivial. The main result of this paper is as follows (see Theorem \ref{theorem transfers} for a more precise statement).

We observe that if $\pi_0^{\A^1}(G)$ has transfers for field extensions, then the norm principle holds for $G$ (Theorem \ref{theorem pi0norm}). We thus have the following consequence (see Corollary \ref{corollary norm principle}) for all quasi-split groups over perfect fields.

\item Since $G/B$ is $\A^1$-connected, by the $\A^1$-Hurewicz theroem one has $$\pi_1^{\A^1}(G/B) \cong \HA_1(G/B) \cong \Hcell_1(G/B).$$ The terms of the cellular $\A^1$-chain complex of $G/B$ admits field transfers (see Definition \ref{defn field transfers}). 
\item Since any torus is a strictly $\A^1$-invariant sheaf with transfers in the sense of Voevodsky, it remains to show that the morphism $\pi_1^{\A^1}(G/B) \to T$ in \eqref{eqn intro exact sequence} preserves transfers. This is done in Theorem \ref{theorem transfers} by using the identification as a cellular $\A^1$-homology group, reducing to the case of field transfers and observing that any homomorphism from a Weil restriction of $\KMW_1$ to any torus preserves transfers (Lemma \ref{lemma transfers}, Lemma \ref{lemma WR transfers}).
\end{itemize}

\begin{proposition}
\label{prop solvable}
For any solvable algebraic group $B$ over a field $k$, the sheaf $\pi_0^{\A^1}(B)$ is strongly $\A^1$-invariant. Moreover, if $k$ is perfect, then $\pi_0^{\A^1}(B)$ is strictly $\A^1$-invariant.
\end{proposition}
\begin{proof}
We first consider the special case of a torus $T$ over $k$. Since $T$ is $\A^1$-rigid, $\pi_0^{\A^1}(T) = T$, which is strongly $\A^1$-invariant by Lemma \ref{lemma torus} and Lemma \ref{lemma nistoet}.

\begin{corollary}
\label{corollary G/T}
Let $G$ be a split group over a perfect field $k$. Fix a Borel subgroup $B$ of $G$. Then the sheaves $\Hcell_n(G)$, $\Hcell_n(G/B)$ admit field transfers for all $n \in \#N$.
\end{corollary}
\begin{proof}
Under the hypotheses on $G$, we have shown in Theorem \ref{theorem quasi-split} that $G/B$ is $\#A^1$-connected. Hence, by \cite{Morel-Sawant-pi1}, we have isomorphisms
\[
\pi_1^{\A^1}(G/B) \cong \HA_1(G/B) \cong \Hcell_1(G/B).
\]
Therefore, the corollary follows from Theorem \ref{theorem cellular transfers}.
\end{proof}

Recall that a \emph{sheaf with (Voevodsky) transfers} over a field $k$ is a contravariant functor from the category of finite correspondences over $k$ to the category of abelian groups (see \cite[Chapter 2]{MVW}). The aim of this section is to give a proof of the main theorem (Theorem \ref{theorem intro main} = Theorem \ref{theorem transfers}), which says that the sheaf of $\A^1$-connected components of a quasi-split group over a perfect field is a presheaf with transfers.

\begin{theorem}
\label{theorem transfers}
Let $G$ be a quasi-split group over a perfect field $k$. Fix a Borel subgroup $B$ of $G$ and the corresponding maximal torus $T$ of $G$. Then the composition of natural maps $T \to G \to \pi_0^{\A^1}(G)$ is an epimorphism of Nisnevich sheaves. Moreover, the sheaf $\pi_0^{\A^1}(G)$ is a strictly $\A^1$-invariant sheaf with transfers. 
\end{theorem}
\begin{proof}
We have an $\#A^1$-fibration $T \to G \to G/T$ and the corresponding long exact sequence of $\A^1$-homotopy sheaves has the form
\[
\cdots \to \pi_1^{\#A^1}(G/T) \xrightarrow{\theta} T \to \pi_0^{\#A^1}(G) \to \pi_0^{\#A^1}(G/T). 
\]
By Theorem \ref{theorem quasi-split}, $G/T$ is $\#A^1$-connected, so we have an exact sequence
\[
\pi_1^{\#A^1}(G/T) \xrightarrow{\theta} T \to \pi_0^{\#A^1}(G) \to 0. 
\]
Since $T$ has transfers, in order to show that $\pi_0^{\#A^1}(G)$ has transfers, it suffices to show that the image of $\theta$ is stable under transfers of $T$. By Lemma \ref{lemma torus subsheaf}, it suffices to show that the image of $\theta$ is stable under field transfers.

\begin{corollary}
\label{corollary norm principle}
The norm principle holds for any quasi-split group over a perfect field $k$.
\end{corollary}

\begin{definition}
\label{defn field transfers}
Let $M \in Ab_{\#A^1}(k)$. Let $F \subset E$ be an extension of finitely generated, separable field extensions of $k$. Choose a sequence of field extensions
\[
F = E_0 \subset E_1 \subset \cdots E_r = E, 
\]
where each $E_i/E_{i-1}$ is a monogenic extension and choose a generator $\alpha_i$ of $E_i$ over $E_{i-1}$. By a \emph{field transfer} on $M_{-1}$, we mean a composite of geometric transfers 
\[
M_{-1}(E) \xrightarrow{tr^{\alpha_r}} M_{-1}(E_{r-1}) \to \cdots \to M_{-1}(E_1) \xrightarrow{tr^{\alpha_1}} M_{-1}(F). 
\]
Note that a field transfer depends upon the choices of the tower of monogenic extensions and the generators.
\end{definition}

\begin{equation}
\label{eqn intro exact sequence}
\cdots \pi_1^{\A^1}(G/B) \to T \to \pi_0^{\A^1}(G) \to \pi_0^{\A^1}(G/B). 
\end{equation}

\begin{lemma}
\label{lemma WR transfers}
Let $T$ be a torus over a field $k$ and let $L$ be a finite separable extension of $k$. Then any homomorphism ${\KMW_1}^{[L]} \to T$ of strictly $\A^1$-invariant sheaves preserves transfers.
\end{lemma}

\begin{lemma}
\label{lemma transfers}
Let $T$ be a torus over a field $k$. Then any homomorphism $\KMW_1 \to T$ of strictly $\A^1$-invariant sheaves preserves transfers.
\end{lemma}

\begin{theorem}
\label{theorem intro main}
Let $G$ be a quasi-split group over a perfect field $k$.  Then the sheaf $\pi_0^{\A^1}(G)$ is a strictly $\A^1$-invariant sheaf with Voevodsky transfers.
\end{theorem}

\begin{theorem}
\label{theorem pi0norm}
Let $G$ be any a connected reductively algebraic group over a field $k$ such that $\pi_0^{\A^1}(G)$ has transfers. Then the norm principle holds for $G$. 
\end{theorem}

\begin{theorem}
\label{theorem quasi-split}
Let $k$ be a perfect field and let $G$ be a quasi-split algebraic group over $k$.  Fix a Borel subgroup $B$ of $G$ and a maximal torus $T$ of $G$ contained in $B$.  Then $G/B$ is $\#A^1$-connected.  
\end{theorem}

\begin{theorem}
\label{theorem transfers}
Let $G$ be a quasi-split group over a perfect field $k$. Fix a Borel subgroup $B$ of $G$ and the corresponding maximal torus $T$ of $G$.  Then the composition of natural maps $T \to G \to \pi_0^{\A^1}(G)$ is an epimorphism of Nisnevich sheaves.  Moreover, the sheaf $\pi_0^{\A^1}(G)$ is a strictly $\A^1$-invariant sheaf with transfers. 
\end{theorem}

post_theorem_intro_text:
We observe that if $\pi_0^{{\mathbb A}^1}(G)$ has transfers for field extensions, then the norm principle holds for $G$ (Theorem \ref{theorem pi0norm}). We thus have the following consequence (see Corollary \ref{corollary norm principle}) for all quasi-split groups over perfect fields.

\begin{corollary}
\label{corollary intro main} 
For any quasi-split group $G$ over a perfect field $k$, the norm principle (see Definition \ref{defn norm principle}) holds with respect to any morphism $G \to H$, where $H$ is a torus.
\end{corollary}

We emphasize that our proofs of our main results are independent of the classification of algebraic groups, unlike previous approaches to the norm principle. The proof makes key use of techniques from ${\mathbb A}^1$-homotopy theory. The main novelty is the use of the theory of cellular ${\mathbb A}^1$-homology developed in \cite{Morel-Sawant-pi1}. The outline of our proof of Theorem \ref{theorem intro main} and the key ingredients are as follows:
\begin{itemize}
\item Fix a Borel subgroup $B$ and the corresponding maximal torus $T$ of $G$. The ${\mathbb A}^1$-fiber sequence $B \to G \to G/B$ induces a long exact sequence
\begin{equation}
\label{eqn intro exact sequence}
\cdots \pi_1^{{\mathbb A}^1}(G/B) \to T \to \pi_0^{{\mathbb A}^1}(G) \to \pi_0^{{\mathbb A}^1}(G/B). 
\end{equation}

\item Theorem \ref{theorem quasi-split} shows that the scheme $G/B$ is ${\mathbb A}^1$-connected using the Bruhat decomposition and the geometric criterion for ${\mathbb A}^1$-connectedness proved in \cite{Balwe-Hogadi-Sawant-JAG}. 

\item Since $G/B$ is ${\mathbb A}^1$-connected, by the ${\mathbb A}^1$-Hurewicz theroem one has $$\pi_1^{{\mathbb A}^1}(G/B) \cong \HA_1(G/B) \cong \Hcell_1(G/B).$$ The terms of the cellular ${\mathbb A}^1$-chain complex of $G/B$ admits field transfers (see Definition \ref{defn field transfers}). 
\item Since any torus is a strictly ${\mathbb A}^1$-invariant sheaf with transfers in the sense of Voevodsky, it remains to show that the morphism $\pi_1^{{\mathbb A}^1}(G/B) \to T$ in \eqref{eqn intro exact sequence} preserves transfers. This is done in Theorem \ref{theorem transfers} by using the identification as a cellular ${\mathbb A}^1$-homology group, reducing to the case of field transfers and observing that any homomorphism from a Weil restriction of $\KMW_1$ to any torus preserves transfers (Lemma \ref{lemma transfers}, Lemma \ref{lemma WR transfers}).
\end{itemize}

It is an open question whether the sheaf of ${\mathbb A}^1$-connected components of any reductive algebraic group admits transfers (or at least, \emph{field transfers} in the sense of Definition \ref{defn field transfers}). We are optimistic that classification-independent proofs of the norm principle in new cases can be obtained via this approach using ${\mathbb A}^1$-homotopy theory.

\subsection*{Acknowledgements}

Anand Sawant thanks Fabien Morel for encouraging him to explore the existence of transfers on ${\mathbb A}^1$-connected components and for helpful discussions. We also thank Alexey Ananyevskiy and Sandeep Varma for their helpful comments and discussions. Hospitality of IISER Pune while this work was being done is gratefully acknowledged.

