Truncations of supersolutions to~\eqref{eq_main} are themselves supersolutions, see \cite[Lemma 3.2]{kortekuusiparviainen2010-superparabolic} for the proof in our setting.
Tracing the two Riesz measures in this proof produces the estimate in the following lemma. For the convenience of the reader, we give the full proof.
\begin{lemma}\label{lem:meas-inq}
Let $\Omega \subset \mathbb{R}^n$ be open. Let $u$ be a continuous supersolution to \eqref{eq_main} in $\Omega_T$ and let 
\begin{equation*}
 \mu = \partial_t u - \div \cA (x,t,\nabla u)
\end{equation*}
be the associated Riesz measure. Let $k\in\mathbb R$. Then, $u_k=\min(u,k)$ is a supersolution to \eqref{eq_main}. Additionally, let
\begin{equation}\label{eq:nov10-1}
 \mu_k=\partial_t u_k -\div \mathcal A(x,t,\nabla u_k)
\end{equation}
be the Riesz measure of $u_k$. Then, for any $\varphi\in \Cz^\infty_0(\Omega_T)$, it holds
\begin{equation}
 \label{eq: ineq for measure of cutoff supersol}
 \int_{\Omega_T} \chi_{\{u<k\}}\varphi\dmu \leq \int_{\Omega_T} \varphi \d\mu_k\,.
\end{equation}

The proof of \Cref{thm: necessity of Hausdorff zero} follows in a straightforward way from the previous results.
\begin{proof}[Proof of \Cref{thm: necessity of Hausdorff zero}]
Let $\mu$ be a measure as in \Cref{cor:parabolic-frostman}, with $\sigma=n+\alpha$. By Lemma \ref{lemma:exis_measure}, there exists an $\mathcal A$-superparabolic function $u$ in $\Omega_T$ satisfying~\eqref{eq: measure RHS}, which is a weak solution in $\Omega_T\backslash E$, since $\supp \mu\subset E$. By \Cref{thm: measure condition implies hölder cont}, $u$ is locally $\alpha$-Hölder continuous with respect to $d_\alpha$. To see this, let $z_0\in \Omega_T$ be a Lebesgue point of $u^{p-1}$ and let $C$ be as in \eqref{eq: intrinsic parameter in osc of sol meas data}. Let $0<R_0<1$ be such that $Q_{R_0,C R_0^\alpha}(z_0)\Subset\Omega_T$. Let $0<R<R_0$. We have $C\max(1,R^-\alpha)=CR^{-\alpha}$. Moreover, choosing $R$ small enough, since $z_0$ is a Lebesgue point, we have
\begin{equation*}
 \left(\dashint_{Q_{R, C R^\alpha}(z_0)} \lvert u-u_{Q_{R,C R^\alpha}(z_0)}\rvert^{p-1}\dx\dt\right)^\frac{1}{p-1} < 1,
\end{equation*}
and hence \eqref{eq: Hölder cont of meas data sol} together with a simple covering argument implies the local Hölder continuity. Finally, $u$ does not solve \eqref{eq_main} in $\Omega_T$, since $\mu\not \equiv 0$.
\end{proof}

