Since there are \(d + 1\) vectors \((1, t_i, \ldots, t_i^{d + 1})\), they span \(\mathbb{R}^{d + 1}\), and so there are constants \(b_i^j\) such that
 \begin{equation}\label{bdefinitions}
 e_j = b_i^j(1, t_i, \ldots, t_i^{d}).
 \end{equation}
 It now follows that
 \begin{equation}\label{expression of p in b}
 p_j(x) = b_i^ju(x, t_i), \quad \nabla p_j(x) = b_i^j\nabla u(x, t_i),
 \end{equation}
 and we conclude that \(p_j\) can grow at most polynomially of degree \(4k\) and \(\nabla p_j\) can grow at most polynomially of degree \(4\ell\). Because \(p_j\) vanishes when \(j > k\) and \(\nabla p_j\) vanishes when \(j > \ell + 1\), we have
 \begin{equation}
 u = p_0 + t p_1 + \ldots + t^{k}p_{k} \quad \text{and} \quad \nabla u = \nabla p_0 + t\nabla p_1 + \ldots + t^{\ell}\nabla p_{\ell},
 \end{equation}
 it follows that
 \begin{equation}
 \begin{split}
 |u(x, t)| \le C(1 + |t|^k + |x|^{4k}) \quad \text{and} \quad |\nabla u(x, t)| \le C(1 + |t|^{\ell} + |x|^{4\ell})
 \end{split}
 \end{equation}
 From equation (\ref{bdefinitions}) we have
 \begin{equation}
 \begin{split}
 \sum_i b_i^ju(x, R^4t_i) & = \sum_i\sum_{m}b_i^jp_{m}(x)R^{4j}t_i^{m} = R^{4j}\sum_mp_m(x)\left(\sum_ib_{i}^jt_i^m\right) \\ & = \sum R^{4j}\sum_m p_m(x)\delta_{mj} \\ & = R^{4j}p_j(x).
 \end{split}
 \end{equation}
 Similarly,
 \begin{equation}
 \sum_i b_i^j\nabla u(x, R^4t_i) = R^{4j}\nabla p_j(x)
 \end{equation}
 Thus
 \begin{equation}
 \begin{split}
 |R^{4j}p_j(x)| & = \left|\sum_i b_i^ju(x, R^4t_i)\right| \le A\sum_i\left|u(x, R^4t_i)\right| \\ & \le A(1 + |x|^{4k} + \sum_i|Rt_i|^{4d}) \le AR^{4k}
 \end{split}
 \end{equation}
 and similarly
 \begin{equation}
 \begin{split}
 |R^{4j}\nabla p_j(x)| & \le A'(1 + |x|^{4\ell} + \sum_i|Rt_i|^{4\ell}) \le A'R^{4\ell},
 \end{split}
 \end{equation}
 so that \(|p_j(x)| \le A_jR^{4(k - j)}\) and \(|p_j(x)| \le A_j'R^{4(\ell - j)}\).
\end{proof}
\begin{proof}[Proof of Theorem \ref{dimension bound theorem}]
 Choose some \(u \in {P}_{4k, 4\ell}(M)\) and suppose \(u = p_0(x) + tp_1(x) + \cdots + t^dp_d(x)\), as in lemma \ref{coefficientbound}. Then \(\Delta\Delta p_{d} = 0\) and for \(j < d\), \(\Delta\Delta p_j = -(j+1)p_{j + 1}\). Thus, there a linear map \(\Psi_0: \mathcal{P}_{4k, 4\ell} \rightarrow \mathcal{H}_{4k, 4\ell}\) defined by \(\Psi_0u = p_{d}\) (here we use the coefficient estimate in (\ref{coefficients in polynomial expression bounds})). If we let \(\mathcal{K}_0 = \ker \Psi_0\) we find
 \begin{equation}
 \dim \mathcal{P}_{4k, 4\ell} \le \dim \mathcal{K}_0 + \dim \mathcal{H}_{4k, 4\ell}
 \end{equation}
 If \(u \in \mathcal{K}_0\), then \(p_{d} = 0\) and \(\Delta\Delta p_{d - 1} = -dp_{d} = 0\), and so we have a map \(\Psi_1: \mathcal{K}_0 \rightarrow \mathcal{H}_{4(k - 1), 4(\ell - 1)}\) defined by setting \(\Psi_1u = p_{d - 1}\). Letting \(\ker \Psi_1 = \mathcal{K}_1\) then
 \begin{equation}
 \dim \mathcal{K}_0 \le \dim \mathcal{K}_1 + \dim \mathcal{H}_{4k, 4\ell}
 \end{equation}
 When \(k \le \ell + 1\), we can repeat this \(k\) times to get
 \begin{equation}
 \dim \mathcal{P}_{4k, 4\ell}(M) \le \sum_{i = 0}^{k} \dim \mathcal{H}_{4(k - i), 4(\ell - i)}(M)
 \end{equation}
 When \(k > \ell + 1\), we have from lemma \ref{coefficientbound} that \(\nabla p_{\ell + 1} = 0\), and so \(p_{\ell + 1} = p_d\) is a constant. Thus in this case \(p_d\) lies in a one dimensional subspace of \(H_{4k, 4\ell}(M)\), so that
 \begin{equation}
 \dim \mathcal{P}_{4k, 4\ell} = \dim \mathcal{K}_0 + 1.
 \end{equation}
 We then iterate the same argument as before, \(\ell\) times, to get the second inequality in (\ref{equation in the first statement of the main theorem}).

\end{proof}
\subsection{Bicaloric Polynomials in \(\mathbb{R}^n\)}
Now we consider polynomially bounded solutions to the biharmonic heat equation in \(\mathbb{R}^n\).
\begin{proposition}\label{bicaloric functions in Rn are polynomials}
 Let \(u \in \mathcal{P}_{k, \ell}(\mathbb{R}^n)\). Then \(u\) is a polynomial in \(x_i\) and \(t\).
\end{proposition}
\begin{proof}
 As before, this follows from the reverse Poincaré estimate and the fact that the operators \(\partial_{x_i}\), \(\partial_t\), and \(\Delta\) commute in \(\mathbb{R}^n\).
\end{proof}
\begin{corollary}
 If \(u \in \mathcal{P}_{k, \ell}(\mathbb{R}^n)\), then there is some \(d\) such that \(u \in \mathcal{P}_{d, d-1}(\mathbb{R}^n)\).
\end{corollary}\label{fewer caloric spaces in R^n}
\begin{proof}
 This follows the same way as before.
\end{proof}
Given a monomial in \(x_i\) and \(t\), we define its biparabolic degree as follows: for \(t^{n_0}\prod x_i^{n_i}\), the biparabolic degree is \(4n_0 + \sum n_i\). The degree of a polynomial is then the maximal degree of the monomials summing to it. Let \(\mathcal{A}_j^n\) be the set of homogeneous polynomials in \(\mathbb{R}^n\) of biparabolic degree \(j\). We have
\begin{equation}
 \mathcal{A}_d^n = A_d^n \oplus t A_{d - 4}^n \oplus t^2A_{d - 8}^n \oplus \cdots
\end{equation}
\begin{lemma}\label{dim for bicaloric polynomials}
 For \(d > 0\) we have \(\dim(\mathcal{P}_{d, d-1}(\mathbb{R}^n) \cap \mathcal{A}_d^n) = \dim A_d^n\) and
 \begin{equation}
 \dim \mathcal{P}_{d, d-1}(\mathbb{R}^n) = \sum_{j = 0}^d\dim A_j^n.
 \end{equation}
\end{lemma}
\begin{proof}
 Both \(\partial_t\) and \(\Delta\Delta\) map \(\mathcal{A}_d^n\) to \(\mathcal{A}_{d-4}^n\). We note that for \(u \in \mathcal{A}_{d-4}^n\) we have
 \begin{equation}
 (\partial_t + \Delta\Delta)\left(tu - \frac{1}{2}t^2(\partial_t + \Delta\Delta)u + \frac{1}{6}t^3(\partial_t + \Delta\Delta)^2 u - \cdots\right) = u,
 \end{equation}
 so that \(\partial_t + \Delta\Delta\) is surjective. Thus,
 \begin{equation}
 \dim (\mathcal{P}_{d, d-1}(\mathbb{R}^n) \cap \mathcal{A}_d^n) = \dim \mathcal{A}_d^n - \dim\mathcal{A}_{d-4}^n = \dim A_d^n
 \end{equation}
 since \(\mathcal{P}_{d, d-1}(\mathbb{R}^n) \cap \mathcal{A}_d^n\) is the kernel of \(\partial_t + \Delta\Delta\) restricted to \(\mathcal{A}_d^n\). Summing gives the second claim.

\end{proof}
Now finally we show that the estimate in Theorem \ref{dimension bound theorem} is sharp in \(\mathbb{R}^n\).
\begin{corollary}\label{sharp in Rn}
 For positive integers \(d > 0\)
 \begin{equation}
 \dim \mathcal{P}_{4d, 4d - 1}(\mathbb{R}^n) = \sum_{i = 0}^{d} \dim \mathcal{H}_{4(d - i), 4(d - i) - 1}(\mathbb{R}^n).
 \end{equation}
\end{corollary}
\begin{proof}
 From lemmas \ref{dim for bicaloric polynomials} and \ref{dim for biharmonic polynomials} we have
 \begin{equation}
 \begin{split}
 \dim \mathcal{P}_{4d, 4d-1}(\mathbb{R}^n) & = \sum_{j = 0}^{4d}\dim A_j^n = \sum_{j = 0}^d(\dim A_{4j}^n + \dim A_{4j - 1}^n + \dim A_{4j - 2}^n + \dim A_{4j - 3}^n) \\ & = \sum_{j = 0}^d\dim \mathcal{H}_{4d, 4d - 1}(\mathbb{R}^n).
 \end{split}
 \end{equation}
 Setting \(k = \ell = d\) in Theorem \ref{dimension bound theorem} and noting \(\mathcal{P}_{4d, 4d}(\mathbb{R}^n) = \mathcal{P}_{4d, 4d-1}(\mathbb{R}^n)\) and \(\mathcal{H}_{4d, 4d}(\mathbb{R}^n) = \mathcal{H}_{4d, 4d-1}(\mathbb{R}^n)\) shows that the estimate in Theorem \ref{dimension bound theorem} is sharp.

