Given a complex holomorphic vector bundle $E$ on a compact complex manifold $X$, one can associate to it a \emph{Schur bundle}
 \[ \Schur^\alpha E, \]
 where $\alpha$ is a Young diagram of length at most $\rk(E)$.
 If we denote by $V$ any fibre of $E$, then the corresponding fibre of $\Schur^\alpha E$ is the irreducible Schur $\GL(V)$-module $\Schur^\alpha V$.

An important problem in computational algebraic geometry is to compute Chern classes of $\Schur^\alpha E$ in terms of those of $E$. It is in principle possible to perform such computations using the splitting principle, but the combinatorics behind this approach is very cumbersome, see for example \cite{Dragutin, Manivel}, where the cases of symmetric and alternating powers were treated.
 In this short paper we provide a compact and effective solution to this problem.

\begin{thm}\label{thm:Chern}
		With notations as above, we have
		\[ \ch_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,\ch^{(\nu)}(E). \]
	\end{thm}

An important problem in computational algebraic geometry is to compute Chern classes of $\Schur^\alpha E$ in terms of those of $E$. It is in principle possible to perform such computations using the splitting principle, but the combinatorics behind this approach is very cumbersome, see for example \cite{Dragutin, Manivel}, where the cases of symmetric and alternating powers were treated.
 In this short paper we provide a compact and effective solution to this problem.

The quantity $\D^{\nu}(\schur_\alpha)$, which is the new ingredient in the formula, is a purely combinatorial object which is easily computed in explicit examples, see Examples~\ref{example:2} and \ref{example:3} and Proposition~\ref{prop:ch of sym}.
 \medskip

\begin{thmB}[Theorem~\ref{thm:k}]
 For any $n\geq0$, the $n^{\operatorname{th}}$ twisted Chern character coefficient of $\Schur^\alpha E$ is
 \[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,k^{(\nu)}(E), \]
 where the sum may be taken over the partitions of $n$ into parts that are all strictly larger than $1$.
 \end{thmB}

In our previous work \cite{DAFOa} we proved formulas expressing $k_2(\Schur^\alpha E)$ and $k_3(\Schur^\alpha E)$ as certain multiples of $k_2(E), k_3(E)$. Theorem B reinterprets those results as 
 \begin{align*}
 k_2(\Schur^\alpha E) = & \, \rk(\D_2(\schur_\alpha)) \, k_2(E)\, , \\
 k_3(\Schur^\alpha E) = & \, \rk(\D_3(\schur_\alpha)) \, k_3(E)\, ,
 \end{align*}
 and provides generalizations to all twisted Chern character coefficients $k_n$, see \S~\ref{section:k}.

\begin{thm}\label{thm:Chern}
 With notations as above, we have
 \[ \ch_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,\ch^{(\nu)}(E). \]
 \end{thm}

\begin{corollary}[\cite{Rubei}]\label{corollary:Rubei}
 With notations as above,
 \[ \ch_1(\Schur^\alpha E)=|\alpha|\frac{r_\alpha}{r}\ch_1(E), \]
 where $r_\alpha=\rk(\Schur^\alpha E)$.
 \begin{proof}
 From Theorem~\ref{thm:Chern} we obtain that
 $$\ch_1(\Schur^\alpha E) = \rk(\D_1(\schur_\alpha)) \ch_1(E).$$
 As $$\D_1 = \sum_{k \geq 0} \frac{\partial}{\partial \power_k}$$ and $\rk(\power_k) = r$ for every $k$, then
 $$\rk(\D_1(\schur_\alpha)) = \frac{1}{r} \rk\left(\sum_k \power_k \frac{\partial}{\partial \power_k} (\schur_\alpha)\right).$$ 
 The claim follows now by noticing that $\sum_k \power_k {\partial}/{\partial \power_k}$ acts on homogeneous elements via multiplication by their degree.
 \end{proof}
 \end{corollary}

\begin{thm}\label{thm:k}
 With notations as above,
 \[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,k^{(\nu)}(E). \]
 \end{thm}

First of all, it is enough to prove that 
 \begin{equation}\label{eqn:in the proof of ch of sym} 
 \rk(\D_{\aaa_\nu}(\schur_m))=\sum_{1\leq\bbb\leq\aaa_\nu}\E(\overleftarrow{\aaa_\nu},\overleftarrow{\bbb})\binom{r+m+|\bbb|-\nu_1-1}{r+|\aaa_\nu|-1}. 
 \end{equation}
 In fact, this is exactly the coefficient in front of $\ch^{(\nu)}(E)$ in the formula for the Chern character, while for the twisted Chern character it is enough to notice that $k_1(E)=0$, so that every partition $\nu$ such that $\nu_1\geq1$ does not contribute to the formula. (The shift $\overleftarrow{\aaa_\nu}$ in the formula for the twisted Chern character is explained in Remark~\ref{rmk:bound}.)

\begin{example}[Schur bundles of size $2$]\label{example:2}
		Let us compute $\ch(\Schur^{\alpha}E)$ when $|\alpha|=2$. We have only two cases, namely the symmetric power $\Schur^2E$ and the exterior power $\extp^2 E$, corresponding to $\alpha=(1,1)$. 
		\begin{description}
			\item[$\alpha=(2)$] it is easy to see that the only non-zero derivatives of $\schur_2$ are
			\[ \D_a(\schur_2)=\schur_1+2^{a-1}\implies \rk(\D_a(\schur_2))=r+2^{a-1} \qquad\mbox{ and }\qquad\D_a\D_b(\schur_2)=1. \]
			Then the first values of $\ch_n(\Schur^2 E)$ are:
			\begin{align*}
				\ch_1(\Schur^{2}E) = & \, (r+1)\ch_1(E), \\
				\ch_2(\Schur^{2}E) = & \, (r+2)\ch_2(E)+\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{2}E) = & \, (r+4)\ch_3(E)+\ch_2(E)\ch_1(E), \\
				\ch_4(\Schur^{2}E) = & \, (r+8)\ch_4(E)+\ch_3(E)\ch_1(E)+\frac{\ch_2(E)^2}{2}, \dots
			\end{align*}

			\item[$\alpha=(1,1)$] it is easy to see that the only non-zero derivatives of $\schur_{(1,1)}$ are
			\[ \D_a(\schur_{(1,1)})=\schur_1-2^{a-1}\implies \rk(\D_a(\schur_2))=r-2^{a-1}\qquad\mbox{ and }\qquad\D_a\D_b(\schur_{(1,1)})=1. \]
			Then the first values of $\ch_n(\extp^2 E)$ are:
			\begin{align*}
				\ch_1(\extp^2E) = & \, (r-1)\ch_1(E), \\
				\ch_2(\extp^2E) = & \, (r-2)\ch_2(E)+\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\extp^2E) = & \, (r-4)\ch_3(E)+\ch_2(E)\ch_1(E), \\
				\ch_4(\extp^2E) = & \, (r-8)\ch_4(E)+\ch_3(E)\ch_1(E)+\frac{\ch_2(E)^2}{2}, \dots
			\end{align*}
		\end{description}
	\end{example}

\begin{example}[Schur bundles of size $3$]\label{example:3}
		In this case we have three cases, namely $\alpha=(3),(2,1)$ and $(1,1,1)$. 
		\begin{description}
			\item[$\bullet\;\alpha=(3)$] It is easy to compute
			\[ \D_a(\schur_3)=\schur_2+\schur_1 2^{a-1}+3^{a-1},\quad \D_a\D_b(\schur_3)=\schur_1+2^{a-1}+2^{b-1}\quad\mbox{and}\quad \D_a\D_b\D_c(\schur_3)=1, \]
			from which we deduce the first values of $\ch_n(\Schur^3E)$:
			\begin{align*}
				\ch_1(\Schur^{3}E) = & \, \binom{r+2}{2}\ch_1(E), \\
				\ch_2(\Schur^{3}E) = & \, \binom{r+3}{2}\ch_2(E)+(r+2)\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{3}E) = & \, \frac{(r+3)(r+6)}{2}\ch_3(E)+(r+3)\ch_2(E)\ch_1(E) + \frac{\ch_1(E)^3}{6}, \\
				\ch_4(\Schur^{3}E) = & \, \frac{r^2+17r+54}{2}\ch_4(E)+(r+5)\ch_3(E)\ch_1(E)+(r+4)\frac{\ch_2(E)^2}{2}+\frac{\ch_2(E)\ch_1(E)^2}{2}.
			\end{align*}

			\item[$\bullet\;\alpha=(2,1)$] It is easy to see that
			\[ \D_{a}(\schur_{(2,1)})=\schur_{2}+\schur_{(1,1)}-3^{a-1},\quad \D_a\D_b(\schur_{(2,1)})=2\schur_1\qquad \mbox{and}\qquad \D_a\D_b\D_c(\schur_{(2,1)})=2, \]
			from which we deduce the first values of $\ch_n(\Schur^{(2,1)}E)$:
			\begin{align*}
				\ch_1(\Schur^{(2,1)}E) = & \, (r^2-1)\ch_1(E), \\
				\ch_2(\Schur^{(2,1)}E) = & \, (r^2-3)\ch_2(E)+2r\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{(2,1)}E) = & \, (r^2-9)\ch_3(E)+2r\ch_2(E)\ch_1(E) + 2 \frac{\ch_1(E)^3}{6}, \\
				\ch_4(\Schur^{(2,1)}E) = & \, (r^2-27)\ch_4(E)+2r\ch_3(E)\ch_1(E)+2r\frac{\ch_2(E)^2}{2}+2\frac{\ch_2(E)\ch_1(E)^2}{2}, \dots
			\end{align*}

			\item[$\bullet\;\alpha=(1,1,1)$] It is easy to compute
			\[ \D_a(\schur_{(1,1,1)})=\schur_{(1,1)}-\schur_1 2^{a-1}+3^{a-1},\quad \D_a\D_b(\schur_3)=\schur_1-2^{a-1}-2^{b-1}\quad\mbox{and}\quad \D_a\D_b\D_c(\schur_3)=1, \]
			from which we deduce the first values of $\ch_n(\extp^3E)$:
			\begin{align*}
				\ch_1(\extp^3E) = & \, \binom{r-1}{2}\ch_1(E), \\
				\ch_2(\extp^3E) = & \, \binom{r-2}{2}\ch_2(E)+(r-2)\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\extp^3E) = & \, \frac{(r-3)(r-6)}{2}\ch_3(E)+(r-3)\ch_2(E)\ch_1(E) + \frac{\ch_1(E)^3}{6}, \\
				\ch_4(\extp^3E) = & \, \frac{r^2-17r+54}{2}\ch_4(E)+(r-5)\ch_3(E)\ch_1(E)+(r-4)\frac{\ch_2(E)^2}{2}+\frac{\ch_2(E)\ch_1(E)^2}{2}, \dots
			\end{align*}
		\end{description}
	\end{example}

\begin{proposition}\label{prop:ch of sym}
		With notations as above, we have
		\begin{equation*}
			\ch_n(\Schur^m E)=\sum_{\nu\vdash n}\sum_{1\leq\bbb\leq\aaa_\nu}\E(\overleftarrow{\aaa_\nu},\overleftarrow{\bbb})\binom{r+m+|\bbb|-\nu_1-1}{r+|\aaa_\nu|-1}\,\ch^{(\nu)}(E) 
		\end{equation*}
		and
		\begin{equation*}
			k_n(\Schur^m E)=\sum_{\substack{\nu\vdash n \\ \nu_1=0}}\sum_{1\leq\bbb\leq\overleftarrow{\aaa_\nu}}\E(\overleftarrow{\aaa_\nu},\overleftarrow{\bbb})\binom{r+m+|\bbb|-1}{r+|\aaa_\nu|-1}\,k^{(\nu)}(E). 
		\end{equation*}
	\end{proposition}

\begin{thm}\label{thm:Chern}
		With notations as above, we have
		\[ \ch_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,\ch^{(\nu)}(E). \]
	\end{thm}

\begin{thm}\label{thm:k}
		With notations as above,
		\[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,k^{(\nu)}(E). \]
	\end{thm}

post_theorem_intro_text:
Let us explain the formula above:
	\begin{itemize}
		\item the sum runs over all partitions $\nu=(1^{\nu_1},2^{\nu_2},\dots)$ of the number $n$;
		\item $\schur_\alpha$ is the Schur polynomial in $\rk(E)$ variables associated to the Young diagram $\alpha$;
		\item $\mathsf{D}^\nu(\schur_\alpha)$ is the $\nu$-\emph{derived symmetric polynomial} which we define in Section~\ref{section:D};
		\item $\rk\colon\mathbb{Q}[x_1,\dots,x_r]^{\mathfrak{S}_r}\to\mathbb{Q}$ is the function associating to each Schur polynomial the dimension of the corresponding irreducible polynomial $\GL(r)$-representation;
		\item $\ch^{(\nu)}(E)=\frac{\ch_1(E)^{\nu_1}}{\nu_1!}\frac{\ch_2(E)^{\nu_2}}{\nu_2!}\cdots$ are the divided powers of the Chern character coefficients.
	\end{itemize}

	The quantity $\mathsf{D}^{\nu}(\schur_\alpha)$, which is the new ingredient in the formula, is a purely combinatorial object which is easily computed in explicit examples, see Examples~\ref{example:2} and \ref{example:3} and Proposition~\ref{prop:ch of sym}.
	\medskip

	The proof of Theorem~\ref{thm:Chern} is simple and only uses standard properties of the Chern character, such as multiplicativity and additivity. To emphasise this aspect, thus making the proof more transparent, we undress it of all the superficial structures and reduce it to a statement about polynomials in countably many variables. This is the content of our key Lemma~\ref{key lemma}, from which all the results in the paper are deduced.
	\medskip

	Notice that this abstract point of view is not only an {\em exercice de style}. The same proof in fact ensures that the result holds in any category where suitable characteristic classes can be defined. For example, it holds for proper algebraic varieties and locally free sheaves over them. Similarly, it also holds for characteristic classes valued in a Chow ring, instead of a cohomology ring. 
	As an example of characteristic classes that differs from the Chern character, we also prove the analogous statement for the \emph{twisted Chern character} 
	\[ k(F)=\exp\left(-\frac{c_1(F)}{\rk(F)}\right)\ch(F) \]
	considered in \cite{Markman} as characteristic classes of projective bundles.

	\begin{thmB}[Theorem~\ref{thm:k}]
		For any $n\geq0$, the $n^{\operatorname{th}}$ twisted Chern character coefficient of $\Schur^\alpha E$ is
		\[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\mathsf{D}^\nu(\schur_\alpha))\,k^{(\nu)}(E), \]
		where the sum may be taken over the partitions of $n$ into parts that are all strictly larger than $1$.
	\end{thmB}

	In our previous work \cite{DAFOa} we proved formulas expressing $k_2(\Schur^\alpha E)$ and $k_3(\Schur^\alpha E)$ as certain multiples of $k_2(E), k_3(E)$. Theorem B reinterprets those results as 
	\begin{align*}
		k_2(\Schur^\alpha E) = & \, \rk(\D_2(\schur_\alpha)) \, k_2(E)\, , \\
		k_3(\Schur^\alpha E) = & \, \rk(\D_3(\schur_\alpha)) \, k_3(E)\, ,
	\end{align*}
	and provides generalizations to all twisted Chern character coefficients $k_n$, see \S~\ref{section:k}.

	As already mentioned, concrete formulas for the Chern character of symmetric and exterior powers were found by Svrtan in \cite{Dragutin} and Manivel in \cite[Section~2]{Manivel}. We recover those formulas in Proposition~\ref{prop:ch of sym} and Proposition~\ref{prop:ch of wedge}, and extend them to twisted Chern characters.

	The formula for the first Chern class of a Schur bundle has long been folklore knowledge, and its first rigorous proof can be found in \cite{Rubei}. We present in Corollary~\ref{corollary:Rubei} an alternative short proof. 

	\subsection*{Plan of the paper}
	The technical core of the paper is contained in \S~\ref{section:key lemma}, where the Key Lemma is proved. In \S~\ref{section:symmetric functions} we recover some important facts about the ring of symmetric functions, that will be used in \S~\ref{section:applications}, where Theorems A and B are proved. Finally, in \S~\ref{section:Sym and Wedge} we prove formulas for Chern character and twisted Chern character of symmetric and exterior powers.

	\subsection*{Acknowledgements}
	We are glad to thank Laurent Manivel for comments on a first draft of the paper.
