\label{T:main}
    For $a\in(-1,1)$ and $N\geq 1$, let
    \begin{equation} \label{def:correlation_length}
    \xi=\xi(a,N)\defeq Ne^{-a^2g_N}(\geq 1),
    \end{equation}
    and, with $\capacity_{\mathbb R^2}^{\tau}(\cdot)$ as in \eqref{eq:cap_time_change_bm}, and viewing $[0,1]$ as $[0,1]\times\{0\} \subset \mathbb R^2$,
      \begin{equation}\label{eq:tau}
    \tau \defeq \tfrac{1}{2} \textnormal{cap}_{\mathbb R^2} \big([0,1] \big).
    \end{equation}   
    Then with $\bar{a}= \sqrt{g_N} a$ (cf.~\eqref{eq:g_N}), we have that
    \begin{equation} \label{eq:thm-asymp}
        \lim_{({N}/{\xi})\to\infty} \frac{\log\left(\theta(\bar{a},N)/\theta\big(0,\xi)\right)}{\log(N/\xi)}= - \tau,
    \end{equation}
    where the limit in is understood over any sequence of pairs $(a,N)$ (possibly dependent) such that $a^2 \log N \to \infty$.

ref_dict.prop:upper_bound:
\begin{theorem}\label{prop:upper_bound}
    For all $a\in(-1,1)$ and $N\geq 1$, we have that with $\xi$ as in \eqref{def:correlation_length},
    \begin{equation} \label{eq:prop_ub}
        \theta(\ba,N)\leq \theta(0,\xi)\exp\left\{-c\,\log\big((N/\xi)\vee 2\big)\right\}.
    \end{equation}
    Furthermore, for all $\eta\in(0,1)$, there exists $\Cl[c]{ub}(\eta)<\infty$ such that when $a^2\log(N)\geq \Cr{ub}$,
    \begin{equation} \label{eq:prop_ub_asymp}
    \theta(\ba,N)\leq  \theta(0,\xi)\exp\left\{-\frac{1-\eta}{2} \capacity_{\R^2}^{\tau}\big([0,1]\big)\log(N/\xi)\right\}.
    \end{equation}
\end{theorem}

ref_dict.prop:lower_bound:
