\begin{lemma}\label{lemma abc}
  Assume the curvature $\Theta$ of $h$ is positive on every fiber $\mathcal{X}_t$. For $1\leq k\leq m$, the following are equivalent. 
\begin{enumerate}[label=\Alph*.]
    \item\label{A} The curvature $\Theta$ has at least $n+k$ positive eigenvalues at every point in $\mathcal{X}$.
    \item\label{B} The horizontal component $\Theta_\mathcal{H}$ has at least $k$ positive eigenvalues at every point in $\mathcal{X}$.
    \item\label{C}  There exists a positive $\beta\in C^{\infty}(\mathcal{X}, p^*(\wedge^{1,1}T^*Y))$ such that the sum of any $m-k+1$ eigenvalues of $\Theta_\mathcal{H}$ with respect to $\beta$ is positive.
\end{enumerate}
Moreover, when $k=1$, statement C can be rephrased as $\Theta_\mathcal{H}\wedge \beta^{m-1}>0$ or equivalently $\Theta^{n+1}\wedge \beta^{m-1}>0$.
\end{lemma}

