Let $\bu=(u_1,u_2,\dots,u_\ell)\in R^{\ell}$. The degenerate cyclotomic Hecke algebra $H_{\ell,n}=H_{\ell,n}^R(\bu)$ of type $G(\ell,1,n)$ is the unital associative $R$-algebra with generators $s_{1} ,\dots,s_{n-1},L_1, \dots,L_n$ which satisfy certain relations, see Definition \ref{degenerate}. In \cite{AMR}, Ariki, Mathas and Rui constructed a cellular basis $\{m_{\s\t}\,|\, \s,\t\in\Std(\blam),\ \blam\in\P_{\ell,n}\}$ for $H_{\ell,n}$. This basis generalizes the well-known Murphy basis for the symmetric group algebra $R[\Sym_n]$ (i.e., the level one case). We call it {\bf the Murphy basis for the degenerate cyclotomic Hecke algebra $H_{\ell,n}$}. Brundan-Kleshchev \cite{BK08} introduced a symmetrizing form $\tau_R^{\te{BK}}$ on $H_{\ell,n}$ which makes it into a symmetric algebra over $R$. We refer the readers to Section 2.2 for their precise definitions. The following theorem is the second main result of this paper.

\begin{prop}\label{nondegvemst}
Let $\blam\in\mathscr{P}_{\ell,n}$ and $\s,\t\in\te{Std}(\blam)$. Suppose that either $n(\s)=n$ or $n(\t)=n$. Then
$$\ve_n(\fm_{\s\t})=\begin{cases} \bigg(\prod\limits_{i=l(\t,n)+1}^{\ell}(-Q_i)\bigg)\fm_{\s_{\downarrow\leq (n-1)}\t_{\downarrow\leq (n-1)}}, &\text{if\ \ $n(\s)=n(\t),$}\\
0, &\text{if\ \ $n(\s)\neq n(\t).$}\end{cases}$$
\end{prop}

\begin{prop}\label{nondegvemst2}
Let $\blam\in\mathscr{P}_{\ell,n}$ and $\s,\t\in\te{Std}(\blam)$. Suppose that $n(\s)\neq n\neq n(\t)$. Then
$$\ve_n(\fm_{\s\t})=\begin{cases} q^{n-n(\t)}\bigg(\prod\limits_{i=l(\t,n)+1}^{\ell}(-Q_i)\bigg)\fm_{\s_{\downarrow\leq (n-1)}\t_{\downarrow\leq (n-1)}}, &\text{if\ \,$n(\s)=n(\t),$}\\
0, &\text{if\ \,$n(\s)\neq n(\t).$}\end{cases}$$
\end{prop}

\smallskip\noindent
{\it Case 2.} Suppose $n(\s)\neq n=n(\t)$. Then $d(\s)\neq d(\s_{\downarrow\leq (n-1)})$ and $d(\t)=d(\t_{\downarrow\leq (n-1)}).$
Then for each $w\in\Sym_\blam$ such that $\sigma_{n-1}\not\leq w,$
using (\ref{decompositionofdt}), (\ref{deg-L-comm1}) and Lemma \ref{deg-L-comm3} (1) we deduce that
\begin{align}\label{degcompu3}
d(\s)^*w u_\blam^+ d(\t)
&=d(\s_{\downarrow\leq (n-1)})^*\gamma_{n-1,n(\s)} w
\Biggr(\prod_{s=2}^{\ell}\prod_{k=1}^{\fa_s}(L_k-u_s)\Biggr)d(\t_{\downarrow\leq (n-1)})\\
\notag &=\varpi_{\s,\t,w}^{(2,1)} s_{n-1}\varpi^{(2,2)}_{\s,\t,w} + \rp^{(2)}_{\s,\t,w},
\end{align}
where
$$\begin{aligned}
\varpi_{\s,\t,w}^{(2,1)}&=
d(\s_{\downarrow\leq (n-1)})^*
\Biggr(\prod\limits_{s=\ell_0+1}^{\ell}(L_{n-1}-u_s)\Biggr)\in H_{\ell,n-1},\\
\varpi_{\s,\t,w}^{(2,2)}&=\gamma_{n-2,n(\s)}w
\Biggr(\prod\limits_{s=2}^{\ell}\prod\limits_{\substack{1\leq k\leq \fa_s\\k\neq n}}(L_k-u_s)\Biggr) d(\t_{\downarrow\leq (n-1)})\in H_{\ell,n-1},\end{aligned}$$ and $$\begin{aligned}
\rp^{(2)}_{\s,\t,w}&=
\begin{cases}\begin{matrix}
d(\s_{\downarrow\leq (n-1)})^* \bigg(\sum\limits_{i=\ell_0+1}^{\ell}
\bigg( \prod\limits_{\ell_0+1\leq s<i}(L_{n-1}-u_s)
\prod\limits_{i< t\leq \ell}(L_{n}-u_t)\bigg)\bigg) \\
\times \gamma_{n-2,n(\s)}w\bigg(\prod\limits_{s=2}^{\ell}\prod\limits_{\substack{1\leq k\leq \fa_s\\k\neq n}}(L_k-u_s)\bigg)d(\t_{\downarrow\leq (n-1)}),\end{matrix} & \mbox{if\ \ } \ell_0<\ell,\\
 0, & \mbox{if\ \ } \ell_0=\ell.
\end{cases}
\end{aligned}$$
As in Case 1, using (\ref{easyobservationdeg}) we see that in this case,
\begin{equation}\label{Case2Vendeg1}
\e_n\bigl({d(\s)}^*w u_\blam^+ {d(\t)}\bigr)=\rp_{\ell-1}^{(n)}(\rp^{(2)}_{\s,\t,w})=0.
\end{equation}
On the other hand, for each $w\in\Sym_\blam$ such that $\sigma_{n-1} \leq w,$
using (\ref{decompositionofdt})-(\ref{decompositionofwlamr}), (\ref{degbraidrela1}), (\ref{deg-L-comm1}), Lemma \ref{keytoolsdeg} (1) and Lemma \ref{deg-L-comm3} (1)
and noticing that $b_{\ell_0,r_{\ell_0}}\geq a_{\ell_0,r_{\ell_0}-1}+1>n(\s)$, we have
\begin{align*}
d(\s)^*w u_\blam^+ d(\t)
& = d(\s_{\downarrow\leq (n-1)})^*\gamma_{n-1,n(\s)}
\Biggr(\prod_{i=1}^{\ell_0-1} w_{i}\Biggr)\Biggr(\prod_{j=1}^{r_{\ell_0}-1}w_{\ell_0,j}\Biggr)
\beta_{b_{\ell_0,r_{\ell_0},n-1}}w_{\ell_0,r_{\ell_0}}^{(1)} \\
\notag&\quad\ \times \Biggr(\prod_{s=2}^{\ell}\prod_{k=1}^{\fa_s}(L_k-Q_s)\Biggr)d(\t_{\downarrow\leq (n-1)})\\
&= d(\s_{\downarrow\leq (n-1)})^*\gamma_{n-1,n(\s)}\beta_{b_{\ell_0,r_{\ell_0},n-1}}
\Biggr(\prod_{i=1}^{\ell_0-1} w_{i}\Biggr)\Biggr(\prod_{j=1}^{r_{\ell_0}-1}w_{\ell_0,j}\Biggr)w_{\ell_0,r_{\ell_0}}^{(1)}\\
\notag&\quad\ \times
\Biggr(\prod_{s=2}^{\ell}\prod_{k=1}^{\fa_s}(L_k-u_s)\Biggr)d(\t_{\downarrow\leq (n-1)})\\
&= d(\s_{\downarrow\leq (n-1)})^*\beta_{b_{\ell_0,r_{\ell_0}}-1,n-2}s_{n-1}\gamma_{n-2,n(\s)}
\Biggr(\prod_{i=1}^{\ell_0-1} w_{i}\Biggr)\Biggr(\prod_{j=1}^{r_{\ell_0}-1}w_{\ell_0,j}\Biggr) w_{\ell_0,r_{\ell_0}}^{(1)}\\
\notag&\quad\ \times
\Biggr(\prod_{s=2}^{\ell}\prod_{k=1}^{\fa_s}(L_k-u_s)\Biggr)d(\t_{\downarrow\leq (n-1)})\\
&= \varpi_{\s,\t,w}^{(3,1)} s_{n-1}\varpi^{(3,2)}_{\s,\t,w} + \rp^{(3)}_{\s,\t,w},
\end{align*}
where
$$\begin{aligned}
\varpi_{\s,\t,w}^{(3,1)}&=
d(\s_{\downarrow\leq (n-1)})^*\beta_{b_{\ell_0,r_{\ell_0}}-1,n-2}
\Biggr(\prod\limits_{s=l(\blam,n)+1}^{\ell}(L_{n-1}-u_s)\Biggr)\in H_{\ell,n-1},\\
\varpi_{\s,\t,w}^{(3,2)}&=\gamma_{n-2,n(\s)}
\Biggr(\prod_{i=1}^{\ell_0-1} w_{i}\Biggr)\Biggr(\prod_{j=1}^{r_{\ell_0}-1}w_{\ell_0,j}\Biggr) w_{\ell_0,r_{\ell_0}}^{(1)}
\Biggr(\prod\limits_{s=2}^{\ell}\prod\limits_{\substack{1\leq k\leq \fa_s\\k\neq n}}(L_k-u_s)\Biggr) d(\t_{\downarrow\leq (n-1)})\in H_{\ell,n-1},\end{aligned}$$ and $$\begin{aligned}
\rp^{(3)}_{\s,\t,w} =
\begin{cases}\begin{matrix}
d(\s_{\downarrow\leq (n-1)})^* \beta_{b_{\ell_0,r_{\ell_0}}-1,n-2}
 \bigg(\sum\limits_{i=\ell_0+1}^{\ell}\bigg( \prod\limits_{\ell_0+1\leq s<i}(L_{n-1}-u_s)\\
\times \prod\limits_{i< t\leq \ell}(L_{n}-u_t)\bigg)\bigg)
\gamma_{n-2,n(\s)}\bigg(\prod\limits_{i=1}^{\ell_0-1} w_{i}\bigg)\bigg(\prod\limits_{j=1}^{r_{\ell_0}-1}w_{\ell_0,j}\bigg) w_{\ell_0,r_{\ell_0}}^{(1)}\\
\times \bigg(\prod\limits_{s=2}^{\ell}\prod\limits_{\substack{1\leq k\leq \fa_s\\k\neq n}}(L_k-u_s)\bigg)d(\t_{\downarrow\leq (n-1)}),\end{matrix} & \mbox{if\ \ }\ell_0<\ell,\\
 0, & \mbox{if\ \ } \ell_0=\ell.
\end{cases}
\end{aligned}$$
Then still using (\ref{easyobservationdeg}) we see that in this case, \begin{equation}\label{Case2Vendeg2}
\e_n\bigr(d(\s)^*w u_\blam^+ d(\t)\bigr)=\rp_{\ell-1}^{(n)}(\rp^{(3)}_{\s,\t,w})=0.
\end{equation}
Therefore, combining (\ref{Case2Vendeg1}) and (\ref{Case2Vendeg2}), we get
$\e_n(m_{\s\t}) =0.$

A central theme in geometric group theory is the \emph{large-scale geometry} of groups. By this we mean the metric structure that is preserved under quasi-isometries—maps which preserve distances up to a uniformly bounded multiplicative and additive error (Section \ref{sec:quasi-isometry}). In a 1983 ICM address~\cite{gromov-icm}, Gromov advocated the study of finitely generated groups as geometric objects and their classification up to quasi-isometry. Among the earliest and most classical quasi-isometric invariants is the \emph{number of ends}. The number of ends of a simplicial graph is the number of topologically distinct ways to escape to infinity, and the number of ends of a finitely generated group is defined to be the number of ends of its Cayley graph with respect to some (any) finite generating set (Section \ref{sec:ends of graphs}). Freudenthal \cite{Freudenthal} and Hopf \cite{Hopf} independently proved that the number of ends of a finitely generated infinite group is always either one, two, or infinite, and the group has exactly two ends if and only if it is virtually infinite cyclic. A celebrated theorem of Stallings~\cite{Stallings68, MR415622} provides a complete characterization of the case of infinitely many ends. It states that a finitely generated group has more than one end if and only if it splits over a finite group, or equivalently, it admits an action on a simplicial tree with finite edge-stabilizers and without edge-inversions or a global fixed vertex. More generally, countably infinite groups, even when not finitely generated, enjoy the same trichotomy on their number of ends \cite{yves}.

A surface $\Sigma$ of infinite type falls into one of two classes depending on whether or not it contains a finite-type \textit{non-displaceable subsurface}---a subsurface which intersects its image under every homeomorphism of $\Sigma$. According to recent work, the large-scale geometry of the big mapping class group $\Map(\Sigma)$ often depends on whether or not $\Sigma$ contains a non-displaceable subsurface of finite type. For example, if $\Sigma$ does contain a non-displaceable subsurface of finite type, then $\Map(\Sigma)$ is not CB \cite{MannRafi} and it admits a continuous and nonelementary action by isometries on a Gromov hyperbolic space \cite{HQR} (the authors also prove that under an extra condition, $\Map(\Sigma)$ admits such an action only if $\Sigma$ contains a non-displaceable subsurface). On the other hand, if $\Sigma$ does not contain a non-displaceable subsurface of finite type and $\Map(\Sigma)$ is not CB, then $\Map(\Sigma)$ has infinite asymptotic dimension \cite{GRV}.

In an effort to further classify the number of ends of big mapping class groups, we focus on those surfaces $\Sigma$ which do not contain a non-displaceable subsurface of finite type. Since we are attempting to analyze the large-scale geometry of $\Map(\Sigma)$, we are only interested in the surfaces for which $\Map(\Sigma)$ is CB generated, but not CB itself. A broad class of surfaces which satisfy these conditions is the class of \textit{avenue surfaces} (Section \ref{sec:avenue surfaces}). Avenue surfaces were defined in \cite{HQR}, and the only additional condition imposed on them is a weak topological condition called \textit{tameness} on the space of ends of $\Sigma$. Tameness is rather technical and lengthy to define, so we choose to work within the slightly more restrictive, but much more easily defined, class of \textit{stable} surfaces (Section \ref{sec:surface ends}). Stable surfaces form a substantial subclass of tame surfaces, and it has become somewhat standard to work with them. For example, several other works in the literature \cite{Bar-NatanVerberne,GRV,BDR} similarly restrict to stable surfaces in order to conveniently work within the framework developed in \cite{MannRafi}. That being said, we expect our results to also hold for surfaces with tame end space.

Every avenue surface has two distinct ends $e_+$ and $e_-$ which are maximal with respect to the partial pre-order $\preceq$ on $\End(\Sigma)$ defined in \cite{MannRafi}. It follows from \cite{Schaffer-Cohen} that for each end $x$ which is an immediate predecessor of $e_+$ (and $e_-$), the equivalence class of $x$ is either a discrete set or a totally disconnected perfect set, where the equivalence relation is defined by $\preceq$. In the first case, we say the end $x$ is of \textit{discrete type}. We can now state our main theorem.

\begin{introthm}
If $\Sigma$ is a stable avenue surface with a discrete-type end, then $\Map(\Sigma)$ is one-ended.
\end{introthm}

The most basic example of a surface covered by this theorem is the bi-infinite flute surface. This surface indeed has exactly two maximal ends, and all other ends, represented by punctures, form a single equivalence class homeomorphic to $\mathbb{Z}$. On the other hand, one surface which is not covered by our theorem is the Jacob's ladder surface, which has exactly two ends, each accumulated by genus. It may seem at first that the Jacob's ladder surface should be no more difficult to handle than the bi-infinite flute surface. However, one significant difference is that in the bi-infinite flute surface, curves cannot meaningfully ``interact" with the punctures, since the punctures are not points on the surface, but in the Jacob's ladder surface, curves may ``interact" with the handles in a highly non-trivial way. We do not know whether our methods may be modified to deal with this additional layer of complexity, so we ask the following.

A surface $\Sigma$ of infinite type falls into one of two classes depending on whether or not it contains a finite-type \textit{non-displaceable subsurface}---a subsurface which intersects its image under every homeomorphism of $\Sigma$. According to recent work, the large-scale geometry of the big mapping class group $\Map(\Sigma)$ often depends on whether or not $\Sigma$ contains a non-displaceable subsurface of finite type. For example, if $\Sigma$ does contain a non-displaceable subsurface of finite type, then $\Map(\Sigma)$ is not CB \cite{MannRafi} and it admits a continuous and nonelementary action by isometries on a Gromov hyperbolic space \cite{HQR} (the authors also prove that under an extra condition, $\Map(\Sigma)$ admits such an action only if $\Sigma$ contains a non-displaceable subsurface). On the other hand, if $\Sigma$ does not contain a non-displaceable subsurface of finite type and $\Map(\Sigma)$ is not CB, then $\Map(\Sigma)$ has infinite asymptotic dimension \cite{GRV}.

In an effort to further classify the number of ends of big mapping class groups, we focus on those surfaces $\Sigma$ which do not contain a non-displaceable subsurface of finite type. Since we are attempting to analyze the large-scale geometry of $\Map(\Sigma)$, we are only interested in the surfaces for which $\Map(\Sigma)$ is CB generated, but not CB itself. A broad class of surfaces which satisfy these conditions is the class of \textit{avenue surfaces} (Section \ref{sec:avenue surfaces}). Avenue surfaces were defined in \cite{HQR}, and the only additional condition imposed on them is a weak topological condition called \textit{tameness} on the space of ends of $\Sigma$. Tameness is rather technical and lengthy to define, so we choose to work within the slightly more restrictive, but much more easily defined, class of \textit{stable} surfaces (Section \ref{sec:surface ends}). Stable surfaces form a substantial subclass of tame surfaces, and it has become somewhat standard to work with them. For example, several other works in the literature \cite{Bar-NatanVerberne,GRV,BDR} similarly restrict to stable surfaces in order to conveniently work within the framework developed in \cite{MannRafi}. That being said, we expect our results to also hold for surfaces with tame end space.

\begin{introthm}
If $\Sigma$ is a stable avenue surface with a discrete-type end, then $\Map(\Sigma)$ is one-ended.
\end{introthm}

The most basic example of a surface covered by this theorem is the bi-infinite flute surface. This surface indeed has exactly two maximal ends, and all other ends, represented by punctures, form a single equivalence class homeomorphic to $\bZ$. On the other hand, one surface which is not covered by our theorem is the Jacob's ladder surface, which has exactly two ends, each accumulated by genus. It may seem at first that the Jacob's ladder surface should be no more difficult to handle than the bi-infinite flute surface. However, one significant difference is that in the bi-infinite flute surface, curves cannot meaningfully ``interact" with the punctures, since the punctures are not points on the surface, but in the Jacob's ladder surface, curves may ``interact" with the handles in a highly non-trivial way. We do not know whether our methods may be modified to deal with this additional layer of complexity, so we ask the following.

A common strategy to study mapping class groups is to construct appropriate metric spaces on which the groups act with good geometric properties. For finite-type surfaces, these spaces are often graphs whose vertices are represented by curves and arcs on the surface, and the fundamental example is the curve graph defined in~\cite{Harvey}. Avenue surfaces fall in the broader class of \textit{translatable surfaces}, for which Schaffer-Cohen~\cite{Schaffer-Cohen} introduced the \emph{translatable curve graph}, whose vertices correspond to simple closed curves which separate the two maximal ends, and whose edges connect pairs of vertices whenever the corresponding curves bound a subsurface homeomorphic to one of a pre-chosen finite collection of subsurfaces (Section \ref{sec:translatable curve graph}). The translatable curve graph is not only an analogue of the curve graph in the setting of translatable surfaces; it is even quasi-isometric to the associated mapping class group \cite{Schaffer-Cohen}. So every property which is invariant under quasi-isometry holds for the mapping class group precisely when it holds for the translatable curve graph. Therefore, we directly analyze this graph in order to determine the number of ends of the mapping class group. To this end, we devise an operation called \textit{lassoing} (Section \ref{sec:lasso and flux}) that takes a vertex in the graph to an adjacent vertex and, more generally, takes a (well-behaved) path to an adjacent path. Furthermore, we find some lower bounds on the graph distance, called \textit{flux} (Section \ref{sec:lasso and flux}) and \textit{Hamming distance} (Section \ref{sec:hamming distance}), that are crucial to proving the graph is one-ended. Section~\ref{sec3} presents a proof of the theorem in the case of the bi-infinite flute, capturing many of the key ideas, and the theorem is proved in full in Section~\ref{sec4}.

\begin{defn}
An avenue surface is a surface $\Sigma$ which does not contain any non-displaceable subsurface of finite type, whose end space is tame, and whose mapping class group $\Map(\Sigma)$ is CB-generated but not CB.
\end{defn}

\begin{thm}\cite[Theorem 4.9]{Schaffer-Cohen}\label{thm:mapping class group is quasi-isometric to its translatable curve graph}
If $\Sigma$ is a stable avenue surface, then $\Map(\Sigma)$ is quasi-isometric to $\cT\cC(\Sigma)$.
\end{thm}

\begin{thm}
 If $\Sigma$ is a stable avenue surface with a discrete-type end, then $\Map(\Sigma)$ is one-ended.
\end{thm}

post_theorem_intro_text:
A common strategy to study mapping class groups is to construct appropriate metric spaces on which the groups act with good geometric properties. For finite-type surfaces, these spaces are often graphs whose vertices are represented by curves and arcs on the surface, and the fundamental example is the curve graph defined in~\cite{Harvey}. Avenue surfaces fall in the broader class of \textit{translatable surfaces}, for which Schaffer-Cohen~\cite{Schaffer-Cohen} introduced the \emph{translatable curve graph}, whose vertices correspond to simple closed curves which separate the two maximal ends, and whose edges connect pairs of vertices whenever the corresponding curves bound a subsurface homeomorphic to one of a pre-chosen finite collection of subsurfaces (Section \ref{sec:translatable curve graph}). The translatable curve graph is not only an analogue of the curve graph in the setting of translatable surfaces; it is even quasi-isometric to the associated mapping class group \cite{Schaffer-Cohen}. So every property which is invariant under quasi-isometry holds for the mapping class group precisely when it holds for the translatable curve graph. Therefore, we directly analyze this graph in order to determine the number of ends of the mapping class group. To this end, we devise an operation called \textit{lassoing} (Section \ref{sec:lasso and flux}) that takes a vertex in the graph to an adjacent vertex and, more generally, takes a (well-behaved) path to an adjacent path. Furthermore, we find some lower bounds on the graph distance, called \textit{flux} (Section \ref{sec:lasso and flux}) and \textit{Hamming distance} (Section \ref{sec:hamming distance}), that are crucial to proving the graph is one-ended. Section~\ref{sec3} presents a proof of the theorem in the case of the bi-infinite flute, capturing many of the key ideas, and the theorem is proved in full in Section~\ref{sec4}. 

We finish with additional questions that arose during our investigation.

\subsection*{Open Questions}

This paper concerns only those surfaces which do not contain a non-displaceable subsurface of finite type. This, of course, raises the following question.

\begin{ques}
    Can one classify the number of ends of $\Map(\Sigma)$ when $\Sigma$ is an infinite-type surface which contains a non-displaceable subsurface of finite type?
\end{ques}

In particular, this question is open for the particular surface studied in \cite{Bavard16} that initiated much of the recent interest in big mapping class groups.

\begin{ques}
Let $\Sigma = \mathbb{R}^2 \setminus \mathcal{C}$ be the plane minus a Cantor set. How many ends does $\Map(\Sigma)$ have?
\end{ques}

Schaffer-Cohen proved that $\Map(\Sigma)$ is quasi-isometric to the loop graph \cite[Theorem 6.5]{Schaffer-Cohen}, which, in turn, is quasi-isometric to the ray graph~\cite[Proposition~3.11]{Bavard16}. Bavard--Walker gave a characterization of the Gromov boundary of the ray graph in~\cite{BavardWalker18}. However, their results do not immediately determine the number of ends of the ray graph.

A question that approaches the subject from another angle is:

\begin{ques}
Does there exist a big mapping class group with more than one end?
\end{ques}

Recall that a finitely generated group is two-ended if and only if it contains an infinite cyclic subgroup of finite index. This motivates the next question.

\begin{ques}
    Does there exist a big mapping class group with exactly two ends? If one exists, what can be said about its algebraic structure?
\end{ques}

\subsection*{Acknowledgments}
We thank Kasra Rafi for suggesting the notion of flux to us, and we thank Anschel Schaffer-Cohen for helpful discussions. Xiaolei Wu is currently a member of LMNS and is supported by NSFC No.\,12326601.

theorem.content:
\label{themain}
Let $f$ be a cuspidal Hecke eigenform of level $1$ with Hecke eigenvalues $\lambda(n)\ll \tau(n)n^{\theta_f}$. If $f$ is Maa\ss~form we further assume  that its root number satisfies $\ve(f)=1$. For $q\nequiv 2 \pmod4$ and $1\le a,b\le q$ satisfying $(a,b)=(ab,q)=1$, we have
\begin{align*}
M_{f,E}(q;a,b)=&c_f\prod_{p\mid qab}\left(1-\frac{\lambda(p)}{p}+\frac1{p^2}\r)\left(1-\frac1{p^2}\r)^{-2}\\
&\times\frac{c_{a,b}+c_{b,a}}{(ab)^{\frac12}}\frac{L(1,f)^2}{\zeta(2)} +O\left(q^{-\frac{1}{20}+\ve}a^{\frac{3}{10}}+q^{-\frac{1-2\theta_f}{22+16\theta_f}+\ve}b^{\frac{3+2\theta_f }{11+8\theta_f}}\r),
\end{align*}
where the coefficients $c_f$, $c_{a,b}$ are defined by
\begin{align}
c_f=
\begin{cases}
1/2,  &\text{if} \ f\ \text{is holomorphic},\\
1, &\text{if}\ f\ \text{is a Maa\ss\ form},
\end{cases}
\quad c_{a,b}=\sum_{a_1\mid a^\infty}\sum_{b_1\mid b^\infty} \frac{\lambda(aa_1b_1)\tau(ba_1b_1)}{a_1b_1}. \label{eqc1c2}
\end{align}

ref_dict.rem1:
\begin{remark}\label{rem1}
Observe that $\ve(f,\chi)$ is independent of $\chi$ when $f$ is a Maa\ss~form.
When $\ve(f,\chi)=\ve(f)=-1$, summing both sides of equation \eqref{eqfe} over all primitive characters leads to the vanishing of $M_{f,E}(q;a,b)$ by symmetry. For holomorphic $f$, the root number $\ve(f,\chi)$ depends on $\chi$ at most though its parity $\chi(-1)$. The symmetry also implies that the total contribution of such characters $\chi$ satisfying $\ve(f,\chi)=-1$ to $M_{f,E}(q;a,b)$ is zero. Therefore, we restrict our consideration to the following cases:
\begin{itemize}
  \item for a Maa\ss~form $f$, we take $\ve(f)=1$,
  \item for a holomorphic $f$, we consider only characters with $\chi(-1)=\ve(f)$.
\end{itemize}
In both cases, it holds that
\[
\ve(f,\chi)=1,
\]
which we assume henceforth.
\end{remark}

