		$$b'(K,(X,M),L)=\# I_{M,\cC},$$		where $I_{M,\cC}$ is the set of $(\mathbf{w},c)\in \Gamma_{M,\cC}/G$ satisfying $\sum_{i=1}^n \frac{w_i}{m_i}=1$, $\mathbf{w}\neq m_1\bfe_1,\dots, \mathbf{w}\neq m_n\bfe_n$ and such that the coefficient of $\tilde{D}_{(\mathbf{w},c)}$ in $\pr^*_M D$ is zero for all effective divisors $D$ whose class lies in $\mathcal{F}$.
		In particular, if $L= -K_X-D_{\bfm}$, then
		$$b(K,(X,M),L)=\rank \Pic(X)+\#\bigg\{(\mathbf{w},c)\in \Gamma_{M,\cC}/G \bigg\vert \sum_{i=1}^n \frac{w_i}{m_i}=1, \mathbf{w}\neq m_1\bfe_1,\dots, \mathbf{w}\neq m_n\bfe_n\bigg\}.$$
	\end{proposition}

ref_dict.lemma: Brauer group toric pair:
\begin{lemma} \label{lemma: Brauer group toric pair}
	Let $X$ be a smooth toric variety over a number field $K$ with dense torus $U$. Let $(X,M)$ be a smooth pair such that the divisors $D_1,\dots,D_n$ are the geometric components of the boundary $X\setminus U$. Then
	$$\Br_1(X,M)/\B(U)\cong \Br K\times \{\chi\in (U(\mathbf{A}_K)/U(K))^{\sim}\mid \chi_{\bfm}=1\, \forall \bfm\in \Gamma_M/G\}.$$
	Here $\B(U)=\ker(\Br_1(U)\rightarrow \prod_{v\in \Omega_K}\Br_1(U_{K_v}))$, which is trivial when $X$ is rational. This isomorphism identifies the Brauer-Manin pairing with the pairing between $U(\mathbf{A}_K)$ and the corresponding automorphic characters.
\end{lemma}

ref_dict.conj: generalized Manin conjecture:
\begin{conjecture} \label{conj: generalized Manin conjecture}
		Let $(X,M)$ be a smooth proper pair over a number field $K$ such that $(X,M)$ is rationally connected, and let $(\cX,\cM)$ be an integral model of $(X,M)$ over $\cO_S$. Assume furthermore that $(\cX,\cM)(\cO_S)\subset X(K)$ is Zariski dense in $X$. Then there exists a thin set $Z\subset X(K)$ such that
		$$N((\cX,\cM)(\cO_S)\setminus Z,\cL,B)\sim cB^{a((X,M),L)}(\log B)^{b(K,(X,M),L)-1} \quad \text{ as } B\rightarrow \infty,$$
		where $c>0$ is a constant, $$a((X,M),L)=\inf\{t\in \mathbb{R}\mid t\pr^*_M L+K_{(X,M)}\}$$ is the Fujita invariant of $(X,M)$ with respect to $L$, and $b(K,(X,M),L)$ is the codimension of the minimal face of $\overline{\Eff}^1(X,M)$ containing $a((X,M),L)\pr^*_M L+K_{(X,M)}$. 		
		Furthermore, assume that that $L$ is adjoint rigid with respect to $(X,M)$ as in Definition \ref{def: adjoint rigid}, and that the fundamental group $\pi_1(X^{\circ}_{\overline{K}},M^{\circ})$ is abelian (see Section \ref{section: leading constant general}). Then the constant $c=c(K,S,(\cX,\cM),\cL)$ is a Tamagawa constant explicitly given in Section \ref{section: leading constant general}.
	\end{conjecture}

ref_dict.theorem: invariants quasi-Campana:
\begin{theorem} \label{theorem: invariants quasi-Campana}
	Let $(X,D_{\bfm})$ be a Campana pair over a number field $K$ such that $X$ is smooth and its effective cone is a rational polyhedral cone. Furthermore assume that there is a field extension $E/K$ such that $$D_{\bfm,E}=\sum_{i=1}^n \left(1-\frac{1}{m_i}\right)D_i$$ is a strict normal crossings divisor, for prime divisors $D_1,\dots,D_n$. Let $(X,M)$ be the pair corresponding to one of the following special points on the Campana pair $(X,D_{\bfm})$: (geometric) Campana points, (geometric) Darmon points, weak Campana points. 	
Then the Fujita invariant appearing in Conjecture \ref{conj: generalized Manin conjecture} is given by $$a((X,M),L)=\inf\{t\in \mathbb{R}\mid tL+K_X+D_{\bfm}\in \overline{\Eff}^1(X)\}.$$
	The description of the $b$-invariant in the conjecture depends on the type of $\cM$-points considered. Let $b(K,(X,D_{\bfm}),L)$ be the codimension of the minimal face of the pseudo-effective cone $\overline{\Eff}^1(X)$ containing $a((X,M),L)L+K_X+D_{\bfm}$.
	\begin{itemize}
		\item If $(X,M)$ is the pair corresponding to geometric Campana(/Darmon) points, then $$b(K,(X,M),L)=b(K,(X,D_{\bfm}),L).$$
		\item If $(X,M)$ is the pair corresponding to weak Campana points, then 
		$$b(K,(X,M),L)=b(K,(X,D_{\bfm}),L)+\#B/G.$$
		Here $G=\gal(E/K)$ and $B$ is the set of all tuples $(\bfw,c)$ such that
		\begin{enumerate}
			\item $\bfw\in \mathbb{N}^n$ with $\sum_{i=1}^n \frac{w_i}{m_i}=1$, with $\bfw\neq w_1\bfe_1,\dots,w_n\bfe_n$,
			\item $w_i=0$ for all $i\in \{1,\dots,n\}$ such that $D_i$ appears in the support of $$a((X,M),L)L+K_X+D_{\bfm},$$
			\item $c$ is an irreducible component of
			$\bigcap_{w_i>0}D_i.$
		\end{enumerate}
		The action of $G$ on $\mathbb{N}^n$ here is induced by the action of $G$ on $\{D_1,\dots,D_n\}$.

		\item If $(X,M)$ is the pair corresponding to Campana points or Darmon points, then $$b(K,(X,M),L)=b(K,(X,D_{\bfm}),L)+\#B'/G,$$
		where $B'\subset B$ is the subset of all $(\bfw,c)$ such that $\{D_i\mid i\in\{1,\dots,n\},\, w_i>0\}$ is contained in a Galois orbit.
	\end{itemize}
	Furthermore, the divisor $a((X,M),L)L+K_X+D_{\bfm}$ is rigid if and only if $L$ is adjoint rigid with respect to $(X,M)$.\end{theorem}

ref_dict.prop: Fujita invariant quasi-Campana:
\begin{proposition} \label{prop: Fujita invariant quasi-Campana}
		Let $(X, M)$ be a smooth proper pair over a field $K$. Assume that that there exists a log-canonical class $K_{(X,M),\log}$ for $(X,M)$. Let $L$ be a big and nef $\mathbb{Q}$-divisor class on $X$. Then
		$$a((X,M),L)=\mathrm{inf}\{t\in \mathbb{R}\mid tL+K_{(X,M),\log}\in \overline{\Eff}^1(X)\}.$$
	\end{proposition}

ref_dict.conjecture: Manins conjecture:
\begin{conjecture}[Manin's conjecture] \label{conjecture: Manins conjecture}
	Let $X$ be a proper smooth rationally connected variety over a number field $K$ and assume that $X(K)$ is not a thin set. Then there exists a thin set $Z\subset X(K)$ such that 
	$$N(X(K)\setminus Z,\cL,B)\sim cB^{a(X,L)}(\log B)^{b(K,X,L)-1} \quad \text{ as } B\rightarrow \infty,$$
	where $c>0$ is an explicit Tamagawa constant, $$a(X,L)=\inf\{t\in \mathbb{R}\mid tL+K_X\in \overline{\Eff}^1(X)\}$$ is the Fujita invariant of $X$ with respect to $L$ and $b(K,X,L)$ is the codimension of the minimal face of the pseudo-effective cone $\overline{\Eff}^1(X)$ containing $a(X,L)L+K_X$.
\end{conjecture}

ref_dict.prop: rigid quasi-Campana:
\begin{proposition} \label{prop: rigid quasi-Campana}
		Let $(X,M)$ be a proper quasi-Campana pair and let $L$ be a big and nef $\mathbb{Q}$-divisor on $X$. Then $a((X,M),L)\pr_M^*L+K_{(X,M)}$ is rigid if and only if $a((X,M),L)L+K_X+D_{\bfm}$ is rigid.
	\end{proposition}

ref_dict.def: adjoint rigid:
\begin{definition} \label{def: adjoint rigid}
		Let $D\in \Div(X,M)_\mathbb{Q}$ be a $\mathbb{Q}$-divisor on a smooth pair $(X,M)$ with $X$ rationally connected. We say that $D$ is \textit{rigid} if $D$ is effective and it is the only effective $\mathbb{Q}$-divisor in its $\mathbb{Q}$-linear equivalence class. For a big and nef $\mathbb{Q}$-divisor $L$ on $X$, we say that $L$ is \textit{adjoint rigid} with respect to $(X,M)$ if $a((X,M),L)>0$ and the adjoint divisor class $a((X,M),L)\pr_M^* L+K_{(X,M)}$ is represented by a rigid $\mathbb{Q}$-divisor.
	\end{definition}

context:
These various special sets of rational points mentioned are all instances of sets of $\mathcal{M}$-points, which were first introduced in \cite{Moe24}. Many other arithmetically interesting sets of rational points can be viewed as $\mathcal{M}$-points, such as the set of squarefree solutions to a given Diophantine equation. Similarly, the set $$\{(a_1:\dots:a_n)\in \mathbb{P}^{n-1}(\mathbb{Z})\mid f(a_1,\dots,a_n) \text{ squarefree}\}$$ is also a set of $\mathcal{M}$-points, for any given homogeneous integer polynomial $f$. Such sets are related to the study of squarefree values of polynomials, which is an enduring and active research area, see for example \cite{Hoo67, Fil92, Poo03, SaWa23}.

Similar to how Campana points are points on an integral model of a Campana pair $(X,D_{\mathbf{m}})$, $\mathcal{M}$-points can be viewed a points on an integral model of a pair $(X,M)$. Here the pair $(X,M)$ consists of a proper variety $X$ together with a parameter set $M$, the latter of which is often given by a tuple of divisors $(D_1,\dots,D_n)$ of divisors on $X_{\overline{K}}$ together with a multiplicity set $\mathfrak{M}\subset (\mathbb{N}\cup \{\infty\})^n$ of allowed intersection multiplicities with these divisors.\begin{example}
 For instance, if $D_1,\dots,D_n$ are the coordinate hyperplanes of $X=\mathbb{P}^{n-1}$, then the set of $\mathcal{M}$-points over $\mathbb{Z}$ is
 $$\{(a_1:\dots:a_n)\in \mathbb{P}^n(\mathbb{Q})\mid (v_p(a_1),\dots,v_p(a_n))\in \mathfrak{M}\text{ for all prime numbers } p\}.$$
\end{example}
More generally, we also allow the set $M$ to impose conditions with respect to the different intersection strata. The notion of pair used in this article is more general than the notion considered in \cite{Moe24, Thesis}, as we explain in Section \ref{section: pairs and M-points}, where we define pairs and $\mathcal{M}$-points.

\subsection{\texorpdfstring{$\mathcal{M}$}{M}-points of bounded height}
 Now we will formulate a version of Manin's conjecture for $\mathcal{M}$-points.
 Let $(X,M)$ be a smooth, proper and rationally connected pair over a number field $K$, as defined in Section \ref{section: Manin's conjecture for M-points}. For such a pair, we introduce its Picard group $\Pic(X,M)$ along with a natural group homomorphism $\pr^*_M \colon \Pic(X)\rightarrow \Pic(X,M)$, its pseudo-effective cone $\overline{\Eff}^1(X,M)$ as well as its canonical divisor class $K_{(X,M)}\in \Pic(X,M)$. Using these notions, we formulate our conjecture exactly analogous to Manin's conjecture. Fix a finite set $S$ of places of $K$, including all infinite places and the places that ramify in the splitting field of $(X,M)$. For an integral model $(\mathcal{X},\mathcal{M})$ of $(X,M)$ over $\cO_S$, we denote the set of $\mathcal{M}$-points on $(\mathcal{X},\mathcal{M})$ over $\cO_S$ by $(\mathcal{X},\mathcal{M})(\cO_S)\subset X(K)$. As before, we let $L$ be a big and nef divisor class with adelic metrization $\mathcal{L}$.
 \begin{conjecture} \label{conj: generalized Manin conjecture}
 Let $(X,M)$ be a smooth proper pair over a number field $K$ such that $(X,M)$ is rationally connected, and let $(\mathcal{X},\mathcal{M})$ be an integral model of $(X,M)$ over $\cO_S$. Assume furthermore that $(\mathcal{X},\mathcal{M})(\cO_S)\subset X(K)$ is Zariski dense in $X$. Then there exists a thin set $Z\subset X(K)$ such that
 $$N((\mathcal{X},\mathcal{M})(\cO_S)\setminus Z,\mathcal{L},B)\sim cB^{a((X,M),L)}(\log B)^{b(K,(X,M),L)-1} \quad \text{ as } B\rightarrow \infty,$$
 where $c>0$ is a constant, $$a((X,M),L)=\inf\{t\in \mathbb{R}\mid t\pr^*_M L+K_{(X,M)}\}$$ is the Fujita invariant of $(X,M)$ with respect to $L$, and $b(K,(X,M),L)$ is the codimension of the minimal face of $\overline{\Eff}^1(X,M)$ containing $a((X,M),L)\pr^*_M L+K_{(X,M)}$. 
 Furthermore, assume that that $L$ is adjoint rigid with respect to $(X,M)$ as in Definition \ref{def: adjoint rigid}, and that the fundamental group $\pi_1(X^{\circ}_{\overline{K}},M^{\circ})$ is abelian (see Section \ref{section: leading constant general}). Then the constant $c=c(K,S,(\mathcal{X},\mathcal{M}),\mathcal{L})$ is a Tamagawa constant explicitly given in Section \ref{section: leading constant general}.
 \end{conjecture}
This conjecture is an extension of the conjecture \cite[Conjecture 1.2.2]{Thesis} presented in the author's PhD thesis, where only split pairs were considered and no prediction for the leading constant was given.
\begin{remark}
The assumption that $(X,M)$ is smooth is a much more relaxed assumption that the assumption in Conjecture \ref{conjecture: Manin Campana} that $D_{\mathbf{m}}$ has strict normal crossings support. For instance, the conjecture can be applied to any smooth toric variety, where the boundary is taken to be the complement of the torus.
\end{remark}
 \begin{remark}
 The assumption on the fundamental group is satisfied whenever the complement $U$ of the boundary divisors has an abelian fundamental group (which is satisfied in all cases for which the conjecture is known). In personal communication, Tim Santens has suggested a Campana pair for which we expect that the prediction in Conjecture \ref{conj: generalized Manin conjecture} for the constant fails due to the existance of a nonabelian cover. This assumption was also suggested to be necessary in \cite{CLTT24} for the same reason, see \cite[Remark 8.4]{CLTT24}.
 \end{remark}
 Conjecture \ref{conj: generalized Manin conjecture} can be directly seen to be a generalization of Conjecture \ref{conjecture: Manins conjecture}. It is not as apparent that it also generalizes Conjecture \ref{conjecture: Manin Campana}, but this follows from the next result, which gives a description of the Fujita invariant and $b$-invariant for (geometric) Campana points, (geometric) Darmon points, and weak Campana points.

