\begin{corollary}
 Let $X$ and $\psi$ be the same as in Theorem \ref{thm:main theorem}. Then we have
 \begin{align*}
 \| \psi \|_p \ll_\epsilon \lambda^{\delta(p,4)- (10/3p-1)/28+ \epsilon}
 \end{align*}
 if $26/9<p<10/3$. Here the implied constant depends only on $X$, $p$ and $\epsilon$.
\end{corollary}
This corollary is obtained by directly applying Theorem \ref{thm:main theorem} and the Kakeya-Nikodym bounds \eqref{eq:Blair-Sogge}.
