\begin{proposition}\label{prop: first one dimensional intgeral estimate}
 Let $B,C>0$ and $\epsilon_0,\epsilon'>0$ be constants.
 Let $\chi_0\in C_c^\infty (\BR)$ be a smooth function supported in $[-1,1]$. 
 If $(z,\tau,t)\in\BC\times\BR\times\BR$ satisfying $|z|,|\tau|,|t|<C$, $k\in K_0$, and $s^\prime>0$ satisfying
 \begin{align}\label{eq: cond for k,s first int}
 d(k,M)\geq Bs^{-1/2 + \epsilon_0}\beta^{1/2}\quad\text{ and }\quad |s^\prime-s|\leq 3\beta
 \end{align}
 for some $s,\beta\geq 1$ with $\beta\leq 3s^{1-\epsilon'}$, then
 \begin{align}\label{eq: first int where k big}
 \int_{-\infty}^\infty \chi_0(t^\prime) \exp\left( is^\prime t^\prime - is A(kn(z,\tau)a(t+t^\prime)) \right) dt^\prime\ll s^{-A}.
 \end{align}
 The implied constant depends on $A,B,C,\epsilon_0,\epsilon'$ and the size of the first $n$ derivatives of $\chi_0$, where $n$ depends on $\epsilon_0,\epsilon'$ and $A$.
\end{proposition}
\begin{proof}
 We denote by $\cD\subset\BC\times\BR\times\BR$ the set consisting of triples $(z,\tau,t)$ satisfying $|z|,|\tau|,|t|<C+2$. By applying Lemma \ref{lem: uniformazation lemma}, we see that there is a $\delta>0$ and a nonvanishing real analytic function $\xi$ on $(-\delta,\delta)\times U_{\fk/\fm} \times \cD$ such that
 \begin{align*}
 \frac{\partial}{\partial t} A(\exp(rX)n(z,\tau)a(t)) = 1-r^2\xi(r,X,z,\tau,t),
 \end{align*}
 when $r\in (-\delta,\delta)$, $X\in U_{\fk/\fm}$, $(z,\tau,t)\in \cD$. If $Z(r,X,z,\tau,t)$ is an antiderivative of $\xi$ with respect to $t$ that is smooth as a function of $(r,X,z,\tau,t)$, we may integrate this to obtain
 \begin{align*}
 A(\exp(rX)n(z,\tau)a(t)) = t - r^2 Z(r,X,z,\tau,t) + c(r,X,z,\tau)
 \end{align*}
 for some function $c(r,X,z,\tau)$.

\subsubsection{Proof of \eqref{eq:equa bd for J2}}
We apply asymptotics for the spherical function from \cite[Theorem 1.5]{marshall2016p}.
There are functions $f_{\pm} \in C^\infty ((0,3)\times \BR) $ such that
\begin{align}\label{KN bound for f pm}
 \frac{\partial^n}{\partial t^n} f_\pm(t,s) \ll_n t^{-n}(st)^{-3/2}
\end{align}
and
\begin{align}\label{KN asymtotic for spherical function}
 \varphi_s (a(t)) = f_+(t,s)e^{ist} + f_-(t,s)e^{-ist} + O_A((st)^{-A})
\end{align}
for $t\in(0,3)$. Plug the formula \eqref{KN asymtotic for spherical function} into the integral $J_2(\phi,s)$. Because of the support of $b_2$, the error term in \eqref{KN asymtotic for spherical function} contributes $O_A(s^{-A})$, which may be ignored. We shall only consider the integral involving $f_+$, as the integral involving $f_-$ is similar.
By expanding one $\phi$ via the Fourier inversion and replacing $t_2$ with $t_2+t_1$, the integral we are considering is equal to
\begin{align}
 \frac{1}{2\pi}\iint_\BC\iint_\BR&\overline{b\phi(z_1,\tau_1,t_1)}\sF_t\phi(z_2,\tau_2,s_2)16e^{is_2t_1-4t_1}\notag\\
 &\left(\int_0^\infty\chi(t_2)b_2(\cA(z,\tau,t_2)) f_+(\cA(z,\tau,t_2),s)\exp(is\cA(z,\tau,t_2)+is_2t_2)dt_2\right.\label{KN main inner integral away from spec}\\
 +&\left.\int_{-\infty}^0 \chi(t_2)b_2(\cA(z,\tau,t_2)) f_+(\cA(z,\tau,t_2),s)\exp(is\cA(z,\tau,t_2)+is_2t_2)dt_2\right)\label{KN main inner integral away from spec 2}\\
 &dz_1 dz_2 d\tau_1d\tau_2 dt_1 ds_2.\notag
\end{align}
Here $|z|,|\tau|\ll\lambda^{-1/2}$ are defined by \eqref{eq: defn for z and tau}. We denote by $\chi(t_2)=b(z_2,t_2+t_1)e^{-2 t_2}$ and omit the variables $z_2,t_1$ as the estimates for the derivatives of $\chi$ with respect to $t_2$ are uniform on $z_2,t_1$. If we replace $t_2$ with $\beta^{-1/2+\epsilon_0}t_2$, then we write the first inner integral \eqref{KN main inner integral away from spec} in the form $\int_0^\infty \alpha(t_2) e^{i(s+s_2)^{1/2+\epsilon_0} f(t_2)} dt_2$ with
\begin{align*}
 &\alpha(t_2)= \beta^{-1/2+\epsilon_0}\chi(\beta^{-1/2+\epsilon_0}t_2)b_2(\cA(z,\tau,\beta^{-1/2+\epsilon_0}t_2)) f_+(\cA(z,\tau,\beta^{-1/2+\epsilon_0}t_2),s),\\
 &f(t_2)=\frac{s}{(s+s_2)^{1/2+\epsilon_0}}\cA(z,\tau,\beta^{-1/2+\epsilon_0}t_2)+\frac{s_2}{(s+s_2)^{1/2+\epsilon_0}}\beta^{-1/2+\epsilon_0}t_2.
\end{align*}
By \eqref{KN approximate for derivative of mathcal A} and the Fourier support assumption on $\phi$: $|s_2\pm \lambda|\geq\beta$, we have the following estimate for the derivative of the phase function $f(t_2)$:
 \begin{align*}
 \left|\frac{\partial f}{\partial t_2}\right| = |s+s_2|^{-1/2-\epsilon_0}\beta^{-1/2+\epsilon_0}\left|s(1 + O(\lambda^{-1}\beta^{1- 2\epsilon_0}))+s_2\right| = \left(\frac{|s+s_2|}{\beta} \right)^{1/2-\epsilon_0}+ O(\beta^{-2\epsilon_0})\gg1.
 \end{align*}
For any $n\geq2$, \eqref{KN approximate for higher derivative of mathcal A} implies that,
 \begin{align*}
 \frac{\partial^nf}{\partial t_2^n}&\ll_n \frac{s}{|s+s_2|^{1/2+\epsilon_0}} \lambda^{-1}(\beta^{1/2-\epsilon_0})^{n+1}(\beta^{-1/2+\epsilon_0})^n\ll \beta^{-2\epsilon_0}\ll1.
 \end{align*}
By \eqref{KN bound for f pm}, if $t\gg \beta^{-1/2+\epsilon_0}$ and $n\geq0$, then
\begin{align*}
 \frac{\partial^n}{\partial t^n} b_2(t)f_+(t,s) \ll_n \lambda^{-3/2}(\beta^{1/2-\epsilon_0})^{3/2}(\beta^{1/2-\epsilon_0})^n=\lambda^{-3/2} (\beta^{1/2-\epsilon_0})^{n+3/2} .
\end{align*}
Moreover, by \eqref{KN approximate for derivative of mathcal A} and \eqref{KN approximate for higher derivative of mathcal A}, for any $n\geq1$, it may be seen that
\begin{align*}
 \frac{\partial^n}{\partial t_2^n}\cA(z,\tau,\beta^{-1/2+\epsilon_0}t_2)\ll (1+\lambda^{-1}(\beta^{1/2-\epsilon_0})^{n+1})(\beta^{-1/2+\epsilon_0})^{n}\ll \beta^{-1/2+\epsilon_0}\ll1.
\end{align*}
Therefore, by the chain rule to higher derivatives, for any $n\geq0$ we obtain that the $n$-th derivative of the amplitude function $\alpha(t_2)$ is bounded by
 \begin{align*}
 \frac{\partial^n\alpha}{\partial t_2^n}\ll_n\beta^{-1/2+\epsilon_0}\lambda^{-3/2} (\beta^{1/2-\epsilon_0})^{n+3/2}=\lambda^{-3/2}(\beta^{1/2-\epsilon_0})^{n+1/2}.
 \end{align*}
Integrating by parts $n$ times gives that the integral \eqref{KN main inner integral away from spec}, which has been written as the form of the oscillatory integral $\int_0^\infty \alpha(t_2) e^{i(s+s_2)^{1/2+\epsilon_0} f(t_2)} dt_2$, is bounded by
\begin{align*}
 \ll_n& |s+s_2|^{-n(1/2+\epsilon_0)}\int_0^\infty\left|\left(\frac{\partial}{\partial t_2}\frac{1}{\partial f/\partial t_2}\right)^n\alpha\right| dt_2\\
 \ll_n& |s+s_2|^{-n(1/2+\epsilon_0)}\lambda^{-3/2}(\beta^{1/2-\epsilon_0})^{n+1/2}\beta^{1/2-\epsilon_0}\ll |s+s_2|^{-n\epsilon_0}.
\end{align*}
In summary, \eqref{KN main inner integral away from spec} is $\ll_{A,\epsilon_0}|s+s_2|^{-A}$. The second inner integral \eqref{KN main inner integral away from spec 2} can be bounded in the same way by replacing $s+s_2$ with $s-s_2$ so \eqref{KN main inner integral away from spec 2} is $\ll_{A,\epsilon_0}|s-s_2|^{-A}$. Hence, with this estimate and the fact $|s\pm s_2|\gg\beta$, by applying the Cauchy-Schwarz inequality and the Plancherel theorem, we obtain \eqref{eq:equa bd for J2}.

